def _session_secret():
    global _session_secret_value
    if _session_secret_value is None:
        with _session_secret_lock:
            if _session_secret_value is None:
                _session_secret_value = load_or_create_session_secret(
                    os.path.join(os.getcwd(), ".maestro-session-secret")
                )
    return _session_secret_value


def _output_share_manager() -> OutputShareManager:
    global _output_share_manager_value
    if _output_share_manager_value is None:
        with _output_share_manager_lock:
            if _output_share_manager_value is None:
                _output_share_manager_value = OutputShareManager(
                    os.path.join(os.getcwd(), "storage", "output-shares.json"),
                    _session_secret(),
                )
    return _output_share_manager_value


def _env_flag_enabled(name: str) -> bool:
    return str(os.environ.get(name) or "").strip().lower() in _TRUE_ENV_VALUES


def _remote_sharing_enabled() -> bool:
    """Whether Maestro is deliberately reachable beyond loopback."""
    return _env_flag_enabled("PINOKIO_SHARE_CLOUDFLARE") or _env_flag_enabled(
        "PINOKIO_SHARE_LOCAL"
    )


_runtime_share_url_lock = threading.Lock()
_runtime_share_url = ""
_runtime_share_quick_tunnel_url = ""
_runtime_share_stable_verified = False


def _public_share_url() -> str:
    """Return only the public origin verified during this launch.

    A configured Workers address is an update destination, not proof that it
    targets this launch's Quick Tunnel.  The launcher registers it only after
    authenticated update and health checks; until then the runtime value is
    empty or the current Quick Tunnel fallback.
    """
    with _runtime_share_url_lock:
        return _runtime_share_url


def _runtime_share_registration() -> tuple[str, str, bool]:
    """Return the public and Quick origins atomically registered this launch."""
    with _runtime_share_url_lock:
        return (
            _runtime_share_url,
            _runtime_share_quick_tunnel_url,
            _runtime_share_stable_verified,
        )


def _cloudflare_origin_has_suffix(origin: str | None, suffix: str) -> bool:
    if not origin:
        return False
    try:
        hostname = urlsplit(origin).hostname or ""
    except ValueError:
        return False
    return hostname.endswith(suffix) and hostname != suffix.removeprefix(".")


def _is_quick_tunnel_origin(origin: str | None) -> bool:
    return _cloudflare_origin_has_suffix(origin, ".trycloudflare.com")


def _is_workers_dev_origin(origin: str | None) -> bool:
    return _cloudflare_origin_has_suffix(origin, ".workers.dev")


def _runtime_share_registration_is_local(request: Request) -> bool:
    """Require the helper's exact direct loopback origin, not any localhost app."""
    if not _is_loopback_request_client(request):
        return False
    direct = _canonical_http_origin(str(request.base_url), allow_path=True)
    supplied = _canonical_http_origin(
        str(request.headers.get("origin") or ""), allow_path=False,
    )
    if not direct or not supplied or direct != supplied:
        return False
    try:
        return (urlsplit(direct).hostname or "") in {"localhost", "127.0.0.1", "::1"}
    except ValueError:
        return False


def _request_is_cloudflare_remote(request: Request) -> bool:
    """Classify requests arriving through any opt-in external surface.

    The classification is deliberately restrictive, not an authentication
    credential: spoofing proxy headers can only remove local capabilities.
    Cloudflare sharing keeps the app bound to loopback, while LAN sharing may
    accept a non-loopback peer directly.  Neither path may inherit local
    machine-owner capabilities.
    """
    cloudflare = _env_flag_enabled("PINOKIO_SHARE_CLOUDFLARE")
    if not (cloudflare or _env_flag_enabled("PINOKIO_SHARE_LOCAL")):
        return False
    # Cloudflare adds CF-Ray to origin requests and CF-Connecting-IP only on
    # edge-to-origin traffic. Treat either marker as remote even if a tunnel
    # or origin rule rewrites Host/X-Forwarded-Host to loopback. A direct
    # local client can only spoof itself into the restricted role, never into
    # gaining machine-owner capabilities.
    if cloudflare and (
        request.headers.get("cf-ray") or request.headers.get("cf-connecting-ip")
    ):
        return True
    if not _is_loopback_request_client(request):
        return True
    for origin in _request_external_origins(request):
        if not _approved_local_origin(origin):
            return True
    return False


_REMOTE_LOCAL_ONLY_PREFIXES = (
    "/classic",
    "/api/v1/research",
    "/api/v1/downloads",
    "/api/v1/storage",
    "/api/v1/system-config",
    "/api/v1/system-detect",
    "/api/v1/system/preflight",
    "/api/v1/system-stats",
    "/api/v1/system/release-model",
    "/api/v1/model-folders",
    "/api/v1/huggingface",
    "/api/v1/civitai",
    "/api/v1/checkpoints",
    "/api/v1/recipes",
    "/api/v1/presets",
)
_REMOTE_LOCAL_ONLY_EXACT = frozenset({
    ("PUT", "/api/v1/services-config"),
    ("PUT", "/api/v1/model-visibility"),
    ("POST", "/api/v1/models/reload"),
    ("POST", "/api/v1/llm/load"),
    ("POST", "/api/v1/llm/unload"),
    ("GET", "/api/v1/llm/stream-status"),
    ("POST", "/api/v1/queue/pause-after-output"),
    ("POST", "/api/v1/queue/resume"),
})


def _remote_local_only_denial(request: Request) -> JSONResponse | None:
    """Fail closed on host-global/admin surfaces for Cloudflare clients."""
    if not _request_is_cloudflare_remote(request):
        return None
    method = request.method.upper()
    path = request.url.path
    if (method, path) in _REMOTE_LOCAL_ONLY_EXACT:
        return JSONResponse(
            {"detail": "This machine-wide control is available locally only"},
            status_code=403,
        )
    if any(path == prefix or path.startswith(prefix + "/") for prefix in _REMOTE_LOCAL_ONLY_PREFIXES):
        return JSONResponse(
            {"detail": "This machine-wide control is available locally only"},
            status_code=403,
        )
    if path.startswith("/api/v1/models/"):
        # Remote users may trigger only the curated model catalog's automatic
        # download route. Debug/delete/reload remain machine-owner controls.
        if not (method == "POST" and path.endswith("/download")) and path != "/api/v1/models/downloads/status":
            return JSONResponse(
                {"detail": "Custom model and model-management controls are local only"},
                status_code=403,
            )
    if path.startswith("/api/v1/loras/") and method != "GET":
        return JSONResponse(
            {"detail": "LoRA installation and management are available locally only"},
            status_code=403,
        )
    if path.startswith("/api/v1/queue/") and (
        path.endswith("/priority") or path.endswith("/start-next")
    ):
        return JSONResponse(
            {"detail": "Global queue ordering is available locally only"},
            status_code=403,
        )
    return None


def _research_local_only_denial(request: Request) -> JSONResponse | None:
    """Require a direct loopback peer and a local advertised origin."""
    remote = (
        not _is_loopback_request_client(request)
        or _request_is_cloudflare_remote(request)
        or any(
            not _approved_local_origin(origin)
            for origin in _request_external_origins(request)
        )
    )
    if not remote:
        return None
    return JSONResponse(
        {"detail": "Research controls are available locally only"},
        status_code=403,
    )


def _first_forwarded_value(value: str | None) -> str:
    """Return the original value from a comma-appended proxy header."""
    return str(value or "").split(",", 1)[0].strip()


def _canonical_http_origin(value: str | None, *, allow_path: bool = False) -> str | None:
    """Normalize an HTTP(S) URL to an origin, rejecting ambiguous inputs."""
    if not isinstance(value, str) or not value or value != value.strip():
        return None
    if value.lower() == "null" or "\\" in value or any(ord(ch) < 32 for ch in value):
        return None
    try:
        parsed = urlsplit(value)
        scheme = parsed.scheme.lower()
        if scheme not in {"http", "https"} or not parsed.hostname:
            return None
        if parsed.username is not None or parsed.password is not None:
            return None
        if not allow_path and (
            parsed.path not in {"", "/"} or parsed.query or parsed.fragment
        ):
            return None
        hostname = parsed.hostname.lower()
        if hostname.endswith("."):
            return None
        port = parsed.port
    except (TypeError, ValueError):
        return None
    rendered_host = f"[{hostname}]" if ":" in hostname else hostname
    if port is not None and not (
        (scheme == "http" and port == 80) or (scheme == "https" and port == 443)
    ):
        rendered_host = f"{rendered_host}:{port}"
    return f"{scheme}://{rendered_host}"


def _approved_local_origin(origin: str) -> bool:
    """Allow loopback and one-label Pinokio ``*.localhost`` origins."""
    try:
        hostname = urlsplit(origin).hostname or ""
    except ValueError:
        return False
    if hostname in {"localhost", "127.0.0.1", "::1"}:
        return True
    if not hostname.endswith(".localhost") or hostname.count(".") != 1:
        return False
    label = hostname[:-len(".localhost")]
    return bool(label) and label.isascii() and label[0].isalnum() and label[-1].isalnum() and all(
        character.isalnum() or character == "-" for character in label
    )


def _request_external_origins(request: Request) -> set[str]:
    """Return the direct and proxy-advertised exact origins for a request."""
    origins = set()
    direct = _canonical_http_origin(str(request.base_url), allow_path=True)
    if direct:
        origins.add(direct)

    forwarded_proto = _first_forwarded_value(
        request.headers.get("x-forwarded-proto")
    ).lower()
    forwarded_host = _first_forwarded_value(
        request.headers.get("x-forwarded-host")
    )
    if forwarded_proto in {"http", "https"} and forwarded_host:
        forwarded = _canonical_http_origin(
            f"{forwarded_proto}://{forwarded_host}", allow_path=False,
        )
        if forwarded:
            origins.add(forwarded)
    return origins


def _matches_verified_stable_redirect_origin(
    origin: str | None,
    request_origins: set[str],
) -> bool:
    """Allow only this launch's verified stable-to-Quick redirect pair."""
    if not _env_flag_enabled("PINOKIO_SHARE_CLOUDFLARE"):
        return False
    share_url, quick_tunnel, stable_verified = _runtime_share_registration()
    return bool(
        stable_verified
        and origin == share_url
        and _is_workers_dev_origin(origin)
        and _is_quick_tunnel_origin(quick_tunnel)
        and quick_tunnel in request_origins
    )


def _request_is_https(request: Request) -> bool:
    if request.url.scheme == "https":
        return True
    if _first_forwarded_value(request.headers.get("x-forwarded-proto")).lower() == "https":
        return True
    forwarded = _first_forwarded_value(request.headers.get("forwarded"))
    for field in forwarded.split(";"):
        key, separator, value = field.strip().partition("=")
        if separator and key.lower() == "proto":
            return value.strip('"').lower() == "https"
    return False


def _reject_cross_origin_mutation(request: Request) -> JSONResponse | None:
    """Reject browser CSRF while preserving local headerless API clients."""
    if request.method.upper() not in _STATE_CHANGING_METHODS:
        return None
    supplied = (
        ("origin", request.headers.get("origin"), False),
        ("referer", request.headers.get("referer"), True),
    )
    present = [item for item in supplied if item[1]]
    if not present:
        if not _remote_sharing_enabled():
            return None
        return JSONResponse(
            {"detail": "Origin or Referer is required while remote sharing is enabled"},
            status_code=403,
        )

    expected_origins = _request_external_origins(request)
    local_request = any(
        _approved_local_origin(expected) for expected in expected_origins
    )
    for header_name, raw_value, allow_path in present:
        origin = _canonical_http_origin(raw_value, allow_path=allow_path)
        if origin is None or (
            origin not in expected_origins
            and not (local_request and _approved_local_origin(origin))
            and not _matches_verified_stable_redirect_origin(
                origin, expected_origins,
            )
        ):
            return JSONResponse(
                {"detail": f"Cross-origin {request.method.upper()} rejected ({header_name})"},
                status_code=403,
            )
    return None


def _recovery_response_requires_no_store(path: str) -> bool:
    """Match only queue/job recovery reads and actions, never media routes."""
    return (
        path == "/api/v1/research"
        or path.startswith("/api/v1/research/")
        or path in {"/api/v1/jobs", "/api/v1/queue"}
        or path.startswith("/api/v1/status/")
        or path.startswith("/api/v1/cancel/")
        or path.startswith("/api/v1/jobs/")
        or path.startswith("/api/v1/queue/")
    )


def _stamp_recovery_no_store_response(request: Request, response: Response):
    if _recovery_response_requires_no_store(str(request.url.path)):
        response.headers["Cache-Control"] = "private, no-store"
        response.headers["Pragma"] = "no-cache"
    return response


async def _call_next_with_recovery_no_store(request: Request, call_next):
    """Stamp the actual success or exception-handler response."""
    return _stamp_recovery_no_store_response(
        request, await call_next(request),
    )


# Add CORS before the session middleware so Starlette wraps CORS inside the
# local-control/no-store boundary. Research OPTIONS responses cannot bypass
# remote denial or cache stamping.
_cors_origin_regex = (
    r"^https?://(?:127\.0\.0\.1|localhost|\[::1\]|"
    r"[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.localhost)(?::\d{1,5})?$"
)
api.add_middleware(
    CORSMiddleware,
    allow_origin_regex=_cors_origin_regex,
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)


@api.middleware("http")
async def _maestro_session_middleware(request: Request, call_next):
    """Enforce origin checks and attach identity for session-owned resources."""
    # Research is a machine-owner control surface. Reject remote requests
    # before CSRF handling or endpoint body parsing so a remote body is never
    # decoded, validated, or reflected by this surface.
    if request.url.path == "/api/v1/research" or request.url.path.startswith(
        "/api/v1/research/"
    ):
        remote_denial = _research_local_only_denial(request)
        if remote_denial is not None:
            return _stamp_recovery_no_store_response(request, remote_denial)
    rejected = _reject_cross_origin_mutation(request)
    if rejected is not None:
        return _stamp_recovery_no_store_response(request, rejected)
    remote_denial = _remote_local_only_denial(request)
    if remote_denial is not None:
        return _stamp_recovery_no_store_response(request, remote_denial)
    # Capability readers are deliberately separate from a Maestro browser
    # session. Visiting a shared output must not create a cookie, unlock a
    # project, or gain any other API authority.
    capability_read = request.method.upper() == "GET" and (
        request.url.path == "/health"
        or request.url.path.startswith("/share/")
        or request.url.path.startswith("/api/v1/output-shares/")
    )
    if capability_read:
        request.state.maestro_session_id = ""
        request.state.maestro_remote = _request_is_cloudflare_remote(request)
        return await call_next(request)
    secret = _session_secret()
    session_id = decode_session_cookie(
        request.cookies.get(SESSION_COOKIE_NAME), secret,
    )
    created = session_id is None
    if session_id is None:
        session_id = uuid.uuid4().hex
    request.state.maestro_session_id = session_id
    request.state.maestro_remote = _request_is_cloudflare_remote(request)
    token = _request_session_id.set(session_id)
    remote_token = _request_remote.set(bool(request.state.maestro_remote))
    try:
        response = await _call_next_with_recovery_no_store(
            request, call_next,
        )
    finally:
        _request_remote.reset(remote_token)
        _request_session_id.reset(token)
    if created:
        response.set_cookie(
            SESSION_COOKIE_NAME,
            encode_session_cookie(session_id, secret),
            httponly=True,
            samesite="strict",
            secure=_request_is_https(request),
            max_age=60 * 60 * 24 * 365,
            path="/",
        )
    return response

# Upload size caps — enforced in upload handlers. Tuned for real-world
# media the app actually ingests; anything larger is almost certainly
# abuse or a user mistake.
MAX_IMAGE_UPLOAD_BYTES = 500 * 1024 * 1024   # 500 MB (generic /api/v1/upload handles images and videos)
# Bumped from 250 MB → 500 MB when /api/v1/upload-audio was extended
# to accept video files for audio extraction. A 5-min 1080p H.264
# music video runs ~30-100 MB; longer reference clips can push
# higher. 500 MB covers ~25-50 min of typical music-video bitrates.
MAX_AUDIO_UPLOAD_BYTES = 500 * 1024 * 1024   # 500 MB (also covers video-for-audio-extract)


def _safe_join(base: str, *parts: str) -> str | None:
    """Join `parts` under `base` and return the absolute path only if it
    stays inside `base`. Returns None on traversal attempts (`..`, absolute
    paths, symlinks escaping the base, etc.). Use for any endpoint that
    accepts a user-supplied filename."""
    try:
        base_real = os.path.realpath(base)
        joined = os.path.realpath(os.path.join(base_real, *parts))
        # On Windows, realpath is case-insensitive at the FS layer but
        # commonpath is case-sensitive — normalize both sides.
        if os.name == "nt":
            if os.path.normcase(joined) != os.path.normcase(base_real) and \
               not os.path.normcase(joined).startswith(os.path.normcase(base_real) + os.sep):
                return None
        else:
            if joined != base_real and not joined.startswith(base_real + os.sep):
                return None
        return joined
    except (ValueError, OSError):
        return None

