class _JobRegistry(dict):
    """Attach browser ownership/access defaults to every HTTP-created job."""

    def prepare(self, value):
        """Apply publication policy without making the job observable."""
        if isinstance(value, dict):
            # Capture origin even for Director helpers that publish directly.
            if bool(_request_remote.get()):
                # asyncio.to_thread preserves ContextVars. Override a stale
                # explicit False from standalone helpers rather than letting
                # them downgrade a Cloudflare request to local priority.
                value["source_remote"] = True
            else:
                value.setdefault("source_remote", False)
            model_admission = globals().get("_require_remote_visible_job_models")
            if callable(model_admission):
                model_admission(value)
            value.setdefault("queue_priority", 0)
            value.setdefault("queue_held", False)
            value.setdefault("hold_after_output", False)
            try:
                requested_outputs = max(
                    1,
                    int((value.get("params") or {}).get("repeat_generation", 1) or 1),
                )
            except (TypeError, ValueError):
                requested_outputs = 1
            value.setdefault("requested_outputs", requested_outputs)
            params = value.get("params") if isinstance(value.get("params"), dict) else {}
            maturity_classifier = globals().get("_classify_generation_maturity")
            if callable(maturity_classifier):
                trusted_plan = params.get("_h3_longform")
                if not isinstance(trusted_plan, dict):
                    trusted_plan = None
                mature_output = maturity_classifier(params, trusted_plan)
            else:
                # Supports isolated startup/contract harnesses that execute
                # the registry before the launch adapter is defined. Normal
                # server publication always takes the authoritative path.
                from services.mature_policy import request_is_mature
                mature_output = bool(request_is_mature(
                    model_definition=wgp.get_model_def(
                        str(params.get("model_type") or "")
                    ) or {},
                    loras=[
                        {"filename": filename}
                        for filename in (params.get("activated_loras") or [])
                        if isinstance(filename, str)
                    ],
                    mmaudio_variant=str(params.get("_mmaudio_variant") or ""),
                ))

            session_id = value.get("session_id") or _request_session_id.get()
            if session_id:
                value["session_id"] = session_id
                try:
                    if (
                        "private_output" in params
                        or "explicit_output" in params
                        or not isinstance(value.get("access_policy"), dict)
                    ):
                        policy = output_policy_from_request(
                            params,
                            mature_output=mature_output,
                            owner_session_id=session_id,
                        )
                    else:
                        policy = harden_output_access_for_maturity(
                            value.get("access_policy"),
                            mature_output=mature_output,
                            owner_session_id=session_id,
                        )
                except ValueError as exc:
                    raise HTTPException(status_code=400, detail=str(exc)) from exc
                value["access_policy"] = policy
                value["private"] = policy["private"]
                value["explicit"] = policy["explicit"]
            elif mature_output:
                # No owner exists for a private sidecar, so this fail-closed
                # policy cannot be published or served as a public result.
                value["access_policy"] = {
                    "private": True,
                    "explicit": True,
                    "owner_session_id": None,
                }
                value["private"] = True
                value["explicit"] = True
        return value

    def publish_prepared(self, key, value):
        """Publish a policy-stamped job under the workspace deletion fence."""
        # Serialize the final publication step with workspace deletion.  HTTP
        # handlers authorize a project before assembling a job; without this
        # second, non-creating check a concurrent delete could win between
        # authorization and publication, after which the stale job would
        # recreate the deleted project on its worker thread.
        with _workspace_lifecycle_lock:
            admission = globals().get("_require_job_workspace_available")
            if callable(admission) and isinstance(value, dict):
                admission(value)
            super().__setitem__(key, value)

    def __setitem__(self, key, value):
        self.publish_prepared(key, self.prepare(value))


