def _ensure_versioned_model_current(model_type: str, *, force: bool = False) -> dict:
    model_def = wgp.get_model_def(model_type) or {}
    result = _versioned_model_updater.ensure_latest(
        model_type, model_def, force=force,
    )
    component_results = _versioned_model_updater.ensure_components_latest(
        model_type, model_def, force=force,
    )
    if component_results:
        result = dict(result)
        result["components"] = component_results
    _versioned_model_update_status[model_type] = result
    return result


_model_update_stop = threading.Event()


def _versioned_model_update_loop() -> None:
    # Let startup and queued-job restoration settle before probing metadata.
    if _model_update_stop.wait(30):
        return
    while not _model_update_stop.is_set():
        # Declarative official H3 workflow metadata follows the same daily,
        # last-known-good update policy as model manifests. It is parsed as
        # bounded data only; downloaded SKILL.md instructions are never run.
        _h3_skill_catalog_updater.refresh()
        if _gen_lock.acquire(blocking=False):
            try:
                for model_type in list(wgp.displayed_model_types):
                    model_def = wgp.get_model_def(model_type) or {}
                    if not (
                        isinstance(model_def.get("model_update"), dict)
                        or isinstance(model_def.get("component_updates"), list)
                    ):
                        continue
                    _versioned_model_updater.apply_recorded(model_type, model_def)
                    _versioned_model_updater.apply_recorded_components(model_type, model_def)
                    if not _check_model_downloaded(model_type):
                        continue  # never turn an optional model into a surprise 30+ GiB download
                    try:
                        _ensure_versioned_model_current(model_type)
                    except Exception as error:
                        _versioned_model_update_status[model_type] = {
                            "status": "failed", "error": str(error),
                        }
            finally:
                _gen_lock.release()
        # Due checks are per-policy (normally 24h); waking hourly also lets a
        # busy generation slot defer without waiting an entire day.
        _model_update_stop.wait(3600)


