@api.post("/api/v1/research/implementation/run")
async def run_research_implementation(request: Request):
    try:
        body = await request.json()
    except Exception:
        raise HTTPException(status_code=400, detail="A JSON request is required") from None
    if not isinstance(body, dict):
        raise HTTPException(status_code=400, detail="A JSON object is required")
    try:
        # Ignore every other client field. Paths, prompts, packet IDs, and
        # finding selections are derived exclusively from the server store.
        result = _research_runtime().start_implementation(
            session_id=request.state.maestro_session_id,
            nonce=str(body.get("nonce") or ""),
            force=body.get("force") is True,
        )
        return JSONResponse(result, status_code=202)
    except Exception as error:
        _raise_research_http_error(error)


