def _queue_recovery_project_identity(workspace: str, project_dir: str) -> str:
    """Return the stable HMAC identity for one existing project instance."""
    marker = ensure_project_instance_marker(project_dir)
    return project_instance_digest(_session_secret(), marker)


def _queue_recovery_existing_project_identity(project_dir: str) -> str:
    """Read an existing project marker without creating recovery evidence."""
    marker_path = os.path.join(project_dir, ".maestro-project-instance")
    descriptor = -1
    try:
        descriptor = os.open(
            marker_path,
            os.O_RDONLY
            | getattr(os, "O_NOFOLLOW", 0)
            | getattr(os, "O_NONBLOCK", 0),
        )
        info = os.fstat(descriptor)
        if (
            not stat.S_ISREG(info.st_mode)
            or info.st_nlink != 1
            or info.st_size > 64
        ):
            raise QueueRecoveryAdapterError(
                "Project instance marker is unsafe."
            )
        marker = os.read(descriptor, 65).decode("ascii").strip()
        current = os.stat(marker_path, follow_symlinks=False)
        if (
            not stat.S_ISREG(current.st_mode)
            or current.st_nlink != 1
            or (current.st_dev, current.st_ino) != (info.st_dev, info.st_ino)
            or re.fullmatch(r"[0-9a-f]{32}", marker) is None
        ):
            raise QueueRecoveryAdapterError(
                "Project instance marker is invalid."
            )
        return project_instance_digest(_session_secret(), marker)
    except (OSError, UnicodeError):
        raise QueueRecoveryAdapterError(
            "Project instance marker is missing or invalid."
        ) from None
    finally:
        if descriptor >= 0:
            os.close(descriptor)


def _queue_recovery_file_values(params: dict) -> list[tuple[str, str]]:
    """Collect only producer-declared media fields, never prompt-like strings."""
    values: list[tuple[str, str]] = []
    for key in sorted(_RECOVERABLE_INPUT_KEYS):
        raw = params.get(key)
        candidates = raw if isinstance(raw, list) else [raw]
        for index, value in enumerate(candidates):
            if isinstance(value, tuple):
                value = value[0] if value else None
            if isinstance(value, str) and value:
                values.append((f"{key}:{index}", os.path.abspath(value)))
    return values


def _queue_recovery_input_descriptors(job: dict, owner_digest: str) -> list[dict]:
    """Seal every manifest-declared file with its existing access evidence."""
    params = job.get("params") if isinstance(job.get("params"), dict) else {}
    out_dir = os.path.realpath(str(job.get("out_dir") or ""))
    uploads = os.path.realpath(os.path.join(_app_dir, "uploads"))
    audio_uploads = os.path.realpath(os.path.join(_app_dir, "uploads", "audio"))
    descriptors = []
    for field, path in _queue_recovery_file_values(params):
        resolved = os.path.realpath(path)
        size, digest = _recovery_sha256_file(resolved)
        descriptor = {
            "field": field,
            "path": resolved,
            "sha256": digest,
            "size": size,
        }
        parent = os.path.realpath(os.path.dirname(resolved))
        if parent in {uploads, audio_uploads}:
            access = read_upload_access_sidecar(resolved)
            if not isinstance(access, dict):
                raise QueueRecoveryRuntimeError(
                    "A recovery upload is missing owner evidence."
                )
            access_path = f"{resolved}.access.json"
            sidecar_size, sidecar_digest = _recovery_sha256_file(access_path)
            access_owner = owner_principal_digest(
                _session_secret(), str(access.get("owner_session_id") or ""),
            )
            if not hmac.compare_digest(access_owner, owner_digest):
                raise QueueRecoveryRuntimeError(
                    "A recovery upload no longer belongs to this job owner."
                )
            descriptor.update({
                "scope": "upload_audio" if parent == audio_uploads else "upload",
                "sidecar_path": access_path,
                "sidecar_sha256": sidecar_digest,
                "sidecar_size": sidecar_size,
            })
        elif out_dir and parent == out_dir:
            sidecar_path = os.path.join(
                out_dir, os.path.splitext(os.path.basename(resolved))[0] + ".meta.json",
            )
            sidecar_size, sidecar_digest = _recovery_sha256_file(sidecar_path)
            descriptor.update({
                "scope": "project",
                "sidecar_path": sidecar_path,
                "sidecar_sha256": sidecar_digest,
                "sidecar_size": sidecar_size,
            })
        else:
            # Derived masks/reference cards are still content-pinned, but they
            # cannot authorize themselves after restart.  The validator below
            # accepts them only while their containing project/input evidence
            # remains exact and blocks rather than falling back otherwise.
            descriptor["scope"] = "derived"
        descriptors.append(descriptor)
    return descriptors


def _queue_recovery_manifest_validator(
    descriptor: dict,
    *,
    owner_digest: str,
    workspace: str,
    project_dir: str,
) -> bool:
    """Revalidate one exact input without resolving a substitute pathname."""
    try:
        path = str(descriptor.get("path") or "")
        if not os.path.isabs(path) or os.path.normpath(path) != path:
            return False
        size, digest = _recovery_sha256_file(path)
        if size != descriptor.get("size") or digest != descriptor.get("sha256"):
            return False
        scope = descriptor.get("scope")
        if scope in {"upload", "upload_audio"}:
            root = os.path.realpath(
                os.path.join(_app_dir, "uploads", "audio")
                if scope == "upload_audio"
                else os.path.join(_app_dir, "uploads")
            )
            if os.path.realpath(os.path.dirname(path)) != root:
                return False
            access = read_upload_access_sidecar(path)
            if not isinstance(access, dict):
                return False
            candidate_owner = owner_principal_digest(
                _session_secret(), str(access.get("owner_session_id") or ""),
            )
            if not hmac.compare_digest(candidate_owner, owner_digest):
                return False
        elif scope == "project":
            if os.path.realpath(os.path.dirname(path)) != os.path.realpath(project_dir):
                return False
            from services.search_index import load_media_sidecars as _load_sidecars
            sidecar = _load_sidecars(project_dir, {os.path.basename(path)}).get(
                os.path.basename(path)
            )
            if not isinstance(sidecar, dict):
                return False
            if str(sidecar.get("workspace") or "") != workspace:
                return False
        elif scope == "derived":
            # Content hashes do not establish ownership. Derived inputs have
            # no existing upload/project sidecar contract, so they remain
            # visible as blocked after restart instead of being auto-trusted.
            return False
        else:
            return False
        sidecar_path = descriptor.get("sidecar_path")
        if sidecar_path:
            sidecar_size, sidecar_digest = _recovery_sha256_file(sidecar_path)
            if (
                sidecar_size != descriptor.get("sidecar_size")
                or sidecar_digest != descriptor.get("sidecar_sha256")
            ):
                return False
        return True
    except (QueueRecoveryRuntimeError, ValueError, TypeError):
        return False


def _queue_recovery_register_and_publish(
    job: dict,
    *,
    worker=None,
    recovery_kind: str = "studio_generation",
    thread_name: str | None = None,
) -> threading.Thread:
    """Durably register one Studio job before publication or thread start."""
    prepared = _jobs.prepare(_stamp_job_origin(job))
    prepared_params = prepared.get("params")
    if isinstance(prepared_params, dict):
        # These are worker-authored native staging controls. HTTP payloads and
        # project manifests can never select a host output directory.
        prepared_params.pop("_recovery_output_directory", None)
        prepared_params.pop("_recovery_output_prefix", None)
    prepared["kind"] = str(recovery_kind or "studio_generation")
    job_id = str(prepared.get("id") or "")
    workspace = str(prepared.get("workspace") or "default")
    project_dir = str(prepared.get("out_dir") or "")
    session_id = str(prepared.get("session_id") or "")
    if not session_id:
        raise QueueRecoveryRuntimeError(
            "Recoverable Studio jobs require a browser owner."
        )
    owner_digest = owner_principal_digest(_session_secret(), session_id)
    with _workspace_lifecycle_lock:
        _require_job_workspace_available(prepared)
        project_digest = _queue_recovery_project_identity(
            workspace, project_dir,
        )
        # This atomic 0600 project-local manifest is the only recovery record
        # allowed to retain raw parameters or absolute input paths. The
        # machine-owned journal and every public response receive only its
        # project-relative pointer, schema, size, and SHA-256.
        request_manifest = atomic_write_request_manifest(
            project_dir,
            job_id=job_id,
            params=prepared.get("params") or {},
            inputs=_queue_recovery_input_descriptors(prepared, owner_digest),
        )
        _stamp_requested_generation_residency(prepared)
        try:
            _queue_recovery_with_bounded_compaction(
                lambda: _queue_recovery_coordinator.register_job(
                    prepared,
                    owner_digest=owner_digest,
                    project_digest=project_digest,
                    request_manifest=request_manifest,
                    global_state=durable_queue_state(additions=(prepared,)),
                ),
            )
        except Exception:
            remove_request_manifest(project_dir, request_manifest)
            raise
        prepared["_recovery_owner_digest"] = owner_digest
        prepared["_recovery_project_digest"] = project_digest
        prepared["_recovery_manifest_pointer"] = dict(request_manifest)
        _jobs.publish_prepared(job_id, prepared)
    worker = worker or _run_generation
    thread = threading.Thread(
        target=worker,
        args=(job_id,),
        daemon=False,
        name=thread_name or f"studio-generation-{job_id}",
    )
    try:
        thread.start()
    except Exception as error:
        restart_worker = _queue_recovery_worker(prepared)
        blocked_state = (
            "blocked_preparation" if restart_worker is None else "blocked"
        )
        prepared["_recovery_reason_code"] = (
            "preparation_must_resubmit"
            if restart_worker is None else "worker_start_failed"
        )
        _queue_recovery_checkpoint(
            prepared,
            recovery_state=blocked_state,
            queue_held=True,
            reruns_denoise=restart_worker is not None,
            message="Recovery worker could not be started",
        )
        raise QueueRecoveryRuntimeError(
            "Recovery worker could not be started."
        ) from error
    return thread


def _queue_recovery_worker(job: dict):
    """Resolve only restart-safe top-level workers; never guess a prep path."""
    kind = str(job.get("kind") or "studio_generation")
    if kind == "studio_blend":
        return globals().get("_run_blend_generation")
    if kind == "studio_outpaint_preparation":
        return globals().get("_prepare_and_run_outpaint")
    if kind in {"studio_project_asset_preparation", "studio_repaint_preparation", "studio_recast_preparation"}:
        return None
    return _run_generation


def _queue_recovery_checkpoint(job: dict, **updates) -> None:
    """Persist an allowlisted recovery transition before mutating the job."""
    with _queue_recovery_checkpoint_lock:
        candidate = dict(job)
        candidate.update(updates)
        _queue_recovery_durable_transition(DurableTransition(
            name="recovery_checkpoint", jobs=(candidate,),
        ))
        job.update(updates)


def _director_recovery_parent_job_id(pid: str) -> str:
    return f"director-parent-{pid}"


_DIRECTOR_RECOVERY_STATE_MAX_BYTES = 64 * 1024 * 1024


def _load_director_recovery_state(
    project_dir: str,
    filename: str,
    descriptor,
) -> dict | None:
    """Read, seal, and parse one unchanged no-follow state file exactly once."""
    if (
        not isinstance(descriptor, dict)
        or descriptor.get("path") != filename
        or not isinstance(descriptor.get("sha256"), str)
        or type(descriptor.get("size")) is not int
        or descriptor["size"] < 1
        or descriptor["size"] > _DIRECTOR_RECOVERY_STATE_MAX_BYTES
        or os.path.basename(filename) != filename
    ):
        return None
    file_fd = -1
    try:
        root = os.path.abspath(project_dir)
        root_info = os.lstat(root)
        if not stat.S_ISDIR(root_info.st_mode) or stat.S_ISLNK(root_info.st_mode):
            return None
        path = os.path.join(root, filename)
        path_before = os.lstat(path)
        if (
            not stat.S_ISREG(path_before.st_mode)
            or stat.S_ISLNK(path_before.st_mode)
            or path_before.st_nlink != 1
            or path_before.st_size != descriptor["size"]
        ):
            return None
        file_fd = os.open(
            path,
            os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0),
        )
        before = os.fstat(file_fd)
        if (
            not stat.S_ISREG(before.st_mode)
            or before.st_nlink != 1
            or before.st_size != descriptor["size"]
            or (before.st_dev, before.st_ino)
                != (path_before.st_dev, path_before.st_ino)
        ):
            return None
        chunks = []
        remaining = descriptor["size"]
        digest = hashlib.sha256()
        while remaining:
            chunk = os.read(file_fd, min(1024 * 1024, remaining))
            if not chunk:
                return None
            chunks.append(chunk)
            digest.update(chunk)
            remaining -= len(chunk)
        if os.read(file_fd, 1):
            return None
        after = os.fstat(file_fd)
        current = os.lstat(path)
        identity_before = (
            before.st_dev, before.st_ino, before.st_size,
            before.st_mtime_ns, before.st_ctime_ns,
        )
        identity_after = (
            after.st_dev, after.st_ino, after.st_size,
            after.st_mtime_ns, after.st_ctime_ns,
        )
        if (
            identity_before != identity_after
            or current.st_nlink != 1
            or not stat.S_ISREG(current.st_mode)
            or stat.S_ISLNK(current.st_mode)
            or (current.st_dev, current.st_ino)
                != (before.st_dev, before.st_ino)
            or not hmac.compare_digest(
                digest.hexdigest(), descriptor["sha256"],
            )
        ):
            return None
        parsed = json.loads(b"".join(chunks).decode("utf-8"))
        return parsed if isinstance(parsed, dict) else None
    except (OSError, UnicodeDecodeError, ValueError, TypeError):
        return None
    finally:
        if file_fd >= 0:
            os.close(file_fd)


def _load_director_recovery_cursor_state(
    project_dir: str,
    filename: str,
    cursor: dict,
) -> tuple[dict | None, dict | None, bool]:
    """Load committed or crash-pending bytes from one sealed cursor."""
    for key in ("state", "pending_state"):
        descriptor = cursor.get(key)
        state = _load_director_recovery_state(
            project_dir, filename, descriptor,
        )
        if state is not None:
            return state, dict(descriptor), key == "pending_state"
    return None, None, False


def _director_runtime_parent_from_snapshot(
    snapshot: dict,
    *,
    identity_key: str,
    identity_value: str,
    state_descriptor: dict,
    unit_kind: str,
) -> dict:
    """Strip legacy artifact names/content before any new parent checkpoint."""
    return {
        "id": str(snapshot.get("id") or ""),
        "kind": str(snapshot.get("kind") or ""),
        "status": str(snapshot.get("status") or "queued"),
        "workspace": str(snapshot.get("workspace") or "default"),
        "source_remote": bool(snapshot.get("source_remote", False)),
        "private": bool(snapshot.get("private", True)),
        "explicit": bool(snapshot.get("explicit", False)),
        "created_at": snapshot.get("created_at"),
        "phase": str(snapshot.get("phase") or "restored"),
        "message": "Director recovery state restored",
        "recovery_state": str(
            snapshot.get("recovery_state") or "restored"
        ),
        "queue_held": bool(snapshot.get("queue_held", False)),
        "recovery_unit": {
            "kind": unit_kind,
            "state": "committed",
            **dict(state_descriptor),
        },
        "recovery_cursor": {
            identity_key: identity_value,
            "state": dict(state_descriptor),
        },
        "_recovery_owner_digest": str(
            snapshot.get("owner_principal") or ""
        ),
        "_recovery_project_digest": str(
            snapshot.get("project_instance") or ""
        ),
        "_recovery_manifest_pointer": dict(
            snapshot.get("request_manifest") or {}
        ),
    }


def _director_snapshot_has_legacy_artifacts(snapshot) -> bool:
    """Detect old parent snapshots that copied child/output filenames."""
    artifact_keys = {
        "output_files", "artifact_files", "clip_output_files",
        "join_output_file", "artifacts",
    }
    pending = [snapshot]
    while pending:
        value = pending.pop()
        if isinstance(value, dict):
            if artifact_keys.intersection(value):
                return True
            pending.extend(value.values())
        elif isinstance(value, list):
            pending.extend(value)
    return False


def _director_recovery_register_parent(
    pid: str,
    pipeline: dict,
    state: dict,
    state_descriptor: dict,
) -> dict:
    """Commit one Director identity without publishing it as a Studio job."""
    params = pipeline.get("params") if isinstance(pipeline.get("params"), dict) else {}
    workspace = str(pipeline.get("workspace") or "default")
    project_dir = str(pipeline.get("out_dir") or "")
    session_id = str(params.get("_maestro_session_id") or "")
    if not session_id:
        raise QueueRecoveryRuntimeError(
            "Recoverable Director pipelines require a browser owner."
        )
    owner_digest = owner_principal_digest(_session_secret(), session_id)
    project_digest = _queue_recovery_project_identity(workspace, project_dir)
    parent_id = _director_recovery_parent_job_id(pid)
    input_descriptors = _queue_recovery_input_descriptors({
        "params": params,
        "out_dir": project_dir,
    }, owner_digest)
    manifest = atomic_write_request_manifest(
        project_dir,
        job_id=parent_id,
        params={
            "pipeline_id": pid,
            "state_filename": str(state_descriptor.get("path") or ""),
        },
        inputs=input_descriptors,
    )
    policy = params.get("_maestro_access_policy")
    policy = policy if isinstance(policy, dict) else {}
    parent = {
        "id": parent_id,
        "kind": "director_pipeline",
        "status": "queued",
        "workspace": workspace,
        "source_remote": bool(pipeline.get("source_remote", False)),
        "private": bool(policy.get("private", False)),
        "explicit": bool(policy.get("explicit", False)),
        "created_at": pipeline.get("created_at"),
        "phase": "registered",
        "message": "Director pipeline registered",
        "recovery_state": "restored",
        "recovery_unit": {
            "kind": "director_parent_state",
            "state": "committed",
            **dict(state_descriptor),
        },
        "recovery_cursor": {
            "pipeline_id": pid,
            "state": dict(state_descriptor),
        },
        "_recovery_owner_digest": owner_digest,
        "_recovery_project_digest": project_digest,
        "_recovery_manifest_pointer": dict(manifest),
    }
    try:
        _queue_recovery_with_bounded_compaction(
            lambda: _queue_recovery_coordinator.register_job(
                parent,
                owner_digest=owner_digest,
                project_digest=project_digest,
                request_manifest=manifest,
            ),
        )
    except Exception:
        remove_request_manifest(project_dir, manifest)
        raise
    _director_recovery_parents[pid] = parent
    consumed_request_id = str(params.get("director_request_id") or "")
    if consumed_request_id:
        try:
            _director_recovery_retire_preparation(
                consumed_request_id,
                project_dir,
                expected_workspace=workspace,
                expected_owner_digest=owner_digest,
                expected_project_digest=project_digest,
            )
        except Exception:
            # The Director parent is already durable. Leave the completed
            # preparation for bounded startup retirement rather than failing
            # or unpublishing the newly registered pipeline.
            pass
    return {"id": parent_id, "inputs": input_descriptors}


def _director_recovery_checkpoint_parent(
    pid: str,
    state: dict,
    state_descriptor: dict,
) -> None:
    parent = _director_recovery_parents.get(pid)
    if not isinstance(parent, dict):
        raise QueueRecoveryRuntimeError("Director recovery parent is unavailable.")
    status = str(state.get("status") or "running")
    recovery_state = (
        "terminal" if status in {"completed", "failed", "cancelled"}
        else "paused" if status == "paused"
        else "restored"
    )
    cursor = dict(parent.get("recovery_cursor") or {})
    cursor.update({
        "pipeline_id": pid,
        "state": dict(state_descriptor),
        "pause_reason": str(state.get("pause_reason") or ""),
    })
    cursor.pop("pending_state", None)
    _queue_recovery_checkpoint(
        parent,
        # The generic journal drops terminal statuses during compaction.
        # Director's semantic terminal state remains repairable until its
        # explicit delete tombstone, so keep this identity non-schedulably
        # registered and carry terminality in recovery_state instead.
        status=(
            "queued"
            if status in {"completed", "failed", "cancelled"}
            else status
        ),
        phase=str(state.get("phase") or status),
        message=(
            "Director pipeline complete"
            if status == "completed"
            else "Director pipeline cancelled"
            if status == "cancelled"
            else "Director pipeline checkpoint committed"
        ),
        recovery_state=recovery_state,
        recovery_unit={
            "kind": "director_parent_state",
            "state": "committed",
            **dict(state_descriptor),
        },
        recovery_cursor=cursor,
    )


def _director_recovery_prepare_parent_state(
    pid: str,
    state: dict,
    state_descriptor: dict,
) -> bool:
    """Seal an upcoming JSON replacement before its canonical rename."""
    parent = _director_recovery_parents.get(pid)
    if not isinstance(parent, dict):
        return False
    from services.director_pipeline import pipeline_state_filename
    if (
        state.get("pipeline_id") != pid
        or state_descriptor.get("path") != pipeline_state_filename(pid)
    ):
        raise QueueRecoveryRuntimeError(
            "Director recovery mutation identity is invalid."
        )
    cursor = dict(parent.get("recovery_cursor") or {})
    cursor.update({
        "pipeline_id": pid,
        "pending_state": dict(state_descriptor),
    })
    _queue_recovery_checkpoint(
        parent,
        message="Director state replacement prepared",
        recovery_cursor=cursor,
    )
    return True


def _director_recovery_prepare_parent_delete(pid: str) -> bool:
    """Commit delete intent before any owned media or state is removed."""
    parent = _director_recovery_parents.get(pid)
    if not isinstance(parent, dict):
        return False
    cursor = dict(parent.get("recovery_cursor") or {})
    cursor["delete_pending"] = True
    _queue_recovery_checkpoint(
        parent,
        queue_held=True,
        message="Director deletion prepared",
        recovery_cursor=cursor,
    )
    return True


def _director_recovery_remove_parent(pid: str, project_dir: str) -> bool:
    """Tombstone one deleted semantic parent and retire its manifest."""
    parent = _director_recovery_parents.get(pid)
    if not isinstance(parent, dict):
        return False
    parent_id = str(parent.get("id") or "")
    _queue_recovery_durable_transition(DurableTransition(
        name="director-parent-deleted",
        tombstones=(parent_id,),
    ))
    _director_recovery_parents.pop(pid, None)
    _director_recovery_rejected_parents.pop(pid, None)
    remove_request_manifest(
        project_dir,
        parent.get("_recovery_manifest_pointer") or {},
    )
    return True


def _director_recovery_submit_child(
    job: dict,
    pid: str,
    unit: dict,
    attempt: int,
) -> dict:
    """Attach to one deterministic child, or durably register it once."""
    job_id = str(job.get("id") or "")
    existing = _jobs.get(job_id)
    if existing is not None:
        existing_parent = str(
            (existing.get("params") or {}).get("_director_pipeline_id")
            or (existing.get("params") or {}).get("_director_request_id")
            or ""
        )
        if (
            existing.get("kind") != "director_child"
            or existing_parent != pid
            or str(existing.get("workspace") or "default")
                != str(job.get("workspace") or "default")
            or os.path.normcase(os.path.realpath(str(existing.get("out_dir") or "")))
                != os.path.normcase(os.path.realpath(str(job.get("out_dir") or "")))
        ):
            raise QueueRecoveryRuntimeError(
                "Director child identity conflicts with recovered queue state."
            )
        if str(existing.get("recovery_state") or "") in {
            "blocked", "blocked_remote_reauth",
        }:
            session_id = str(job.get("session_id") or "")
            expected_owner = str(existing.get("_recovery_owner_digest") or "")
            if (
                not session_id
                or not hmac.compare_digest(
                    owner_principal_digest(_session_secret(), session_id),
                    expected_owner,
                )
                or not _queue_recovery_revalidate_job(existing)
            ):
                raise QueueRecoveryRuntimeError(
                    "Director child recovery authorization failed."
                )
            existing["session_id"] = session_id
            existing["access_policy"] = dict(job.get("access_policy") or {})
            _queue_recovery_checkpoint(
                existing,
                status="queued",
                queue_held=False,
                recovery_state="retrying",
                message="Queued for Director recovery",
            )
            if not update_queue_job(existing, held=False):
                raise QueueRecoveryRuntimeError(
                    "Director child recovery could not be queued."
                )
            try:
                threading.Thread(
                    target=_run_generation,
                    args=(job_id,),
                    daemon=False,
                    name=f"director-child-recovery-{job_id}",
                ).start()
            except Exception as error:
                _queue_recovery_checkpoint(
                    existing,
                    queue_held=True,
                    recovery_state="blocked",
                    message="Director child recovery worker could not start",
                )
                raise QueueRecoveryRuntimeError(
                    "Director child recovery worker could not start."
                ) from error
        return existing
    job["kind"] = "director_child"
    job["recovery_unit"] = {
        "kind": "director_child_intent",
        "state": "submitted",
        "variant": int(unit.get("variant", 0) or 0),
        "index": int(unit.get("index", 0) or 0),
        "director_kind": str(unit.get("kind") or ""),
        "attempt": max(0, int(attempt)),
    }
    _queue_recovery_register_and_publish(
        job,
        recovery_kind="director_child",
        thread_name=f"director-child-{job_id}",
    )
    return _jobs[job_id]


def _director_recovery_verified_child(job: dict, project_dir: str) -> dict | None:
    """Return only terminal outputs backed by completed queue safe units."""
    if str(job.get("status") or "") != "completed":
        return None
    clip_outputs = {}
    for index, filename in dict(job.get("clip_output_files") or {}).items():
        try:
            clip_outputs[str(int(index))] = str(filename)
        except (TypeError, ValueError):
            continue
    ordered = [
        filename for _index, filename in sorted(
            clip_outputs.items(), key=lambda item: int(item[0]),
        ) if filename
    ]
    join_output = str(job.get("join_output_file") or "")
    if join_output and join_output not in ordered:
        ordered.append(join_output)
    if not ordered:
        ordered = [
            str(filename) for filename in (job.get("output_files") or [])
            if isinstance(filename, str) and filename
        ]
    units = _queue_recovery_units(job)
    evidence = []
    for filename in ordered:
        matched = None
        for unit in units:
            unit_id = str(unit.get("unit_id") or "")
            for descriptor in unit.get("artifacts") or []:
                if (
                    isinstance(descriptor, dict)
                    and descriptor.get("basename") == filename
                    and validate_artifact_descriptor(
                        project_dir, descriptor, producer_unit_id=unit_id,
                    )
                ):
                    matched = dict(descriptor)
                    break
            if matched is not None:
                break
        if matched is None:
            return None
        evidence.append(matched)
    if not evidence:
        return None
    return {
        "outputs": ordered,
        "clip_output_files": clip_outputs,
        "artifacts": evidence,
    }


def _director_recovery_validate_child(
    project_dir: str,
    evidence,
) -> dict | None:
    if not isinstance(evidence, dict):
        return None
    outputs = evidence.get("outputs")
    artifacts = evidence.get("artifacts")
    if (
        not isinstance(outputs, list)
        or not outputs
        or not isinstance(artifacts, list)
        or len(outputs) != len(artifacts)
    ):
        return None
    for filename, descriptor in zip(outputs, artifacts):
        if (
            not isinstance(filename, str)
            or not isinstance(descriptor, dict)
            or descriptor.get("basename") != filename
            or not validate_artifact_descriptor(project_dir, descriptor)
        ):
            return None
    return {
        "outputs": list(outputs),
        "clip_output_files": dict(evidence.get("clip_output_files") or {}),
        "artifacts": [dict(item) for item in artifacts],
    }


_DIRECTOR_REQUEST_ID_RE = re.compile(r"^[0-9a-f]{32}$")
_DIRECTOR_PREPARATION_RETENTION_S = 7 * 24 * 60 * 60
_DIRECTOR_PREPARATION_MAX_RETAINED = 256


def _director_preparation_filename(request_id: str) -> str:
    if _DIRECTOR_REQUEST_ID_RE.fullmatch(str(request_id or "")) is None:
        raise ValueError("Invalid Director request id")
    return f"_director_request_{request_id}.json"


def _director_preparation_payload(state: dict) -> tuple[bytes, dict]:
    request_id = str(state.get("request_id") or "")
    filename = _director_preparation_filename(request_id)
    encoded = json.dumps(
        state, ensure_ascii=False, indent=2, default=str,
    ).encode("utf-8")
    return encoded, {
        "path": filename,
        "sha256": hashlib.sha256(encoded).hexdigest(),
        "size": len(encoded),
    }


def _write_director_preparation_state(
    project_dir: str,
    state: dict,
) -> dict:
    request_id = str(state.get("request_id") or "")
    filename = _director_preparation_filename(request_id)
    path = os.path.join(project_dir, filename)
    temporary = f"{path}.{uuid.uuid4().hex[:8]}.tmp"
    encoded, descriptor = _director_preparation_payload(state)
    try:
        with open(temporary, "wb") as handle:
            handle.write(encoded)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, path)
        if os.name != "nt":
            directory = os.open(
                project_dir,
                os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
            )
            try:
                os.fsync(directory)
            finally:
                os.close(directory)
        return descriptor
    finally:
        try:
            os.remove(temporary)
        except FileNotFoundError:
            pass


def _remove_director_preparation_state(
    project_dir: str,
    request_id: str,
) -> None:
    path = os.path.join(
        project_dir, _director_preparation_filename(request_id),
    )
    try:
        os.remove(path)
    except FileNotFoundError:
        return
    if os.name != "nt":
        directory = os.open(
            project_dir,
            os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
        )
        try:
            os.fsync(directory)
        finally:
            os.close(directory)


def _director_recovery_retire_preparation(
    request_id: str,
    project_dir: str,
    *,
    expected_workspace: str = "",
    expected_owner_digest: str = "",
    expected_project_digest: str = "",
) -> bool:
    """Retire one completed preparation after durable intent and state erase."""
    with _director_preparation_lock:
        parent = _director_preparation_parents.get(request_id)
        state = _director_preparation_states.get(request_id)
    if (
        not isinstance(parent, dict)
        or not isinstance(state, dict)
        or state.get("status") != "completed"
        or state.get("request_id") != request_id
    ):
        return False
    workspace = str(state.get("workspace") or "")
    owner_session_id = str(state.get("owner_session_id") or "")
    parent_owner_digest = str(parent.get("_recovery_owner_digest") or "")
    parent_project_digest = str(parent.get("_recovery_project_digest") or "")
    cursor = dict(parent.get("recovery_cursor") or {})
    if (
        not workspace
        or not owner_session_id
        or cursor.get("request_id") != request_id
        or (expected_workspace and workspace != expected_workspace)
    ):
        return False
    try:
        state_owner_digest = owner_principal_digest(
            _session_secret(), owner_session_id,
        )
        current_project_digest = _queue_recovery_project_identity(
            workspace, project_dir,
        )
    except (ValueError, QueueRecoveryAdapterError):
        return False
    if (
        not parent_owner_digest
        or not parent_project_digest
        or not hmac.compare_digest(parent_owner_digest, state_owner_digest)
        or not hmac.compare_digest(
            parent_project_digest, current_project_digest,
        )
        or (
            expected_owner_digest
            and not hmac.compare_digest(
                parent_owner_digest, expected_owner_digest,
            )
        )
        or (
            expected_project_digest
            and not hmac.compare_digest(
                parent_project_digest, expected_project_digest,
            )
        )
    ):
        return False
    cursor["retire_pending"] = True
    _queue_recovery_checkpoint(
        parent,
        queue_held=True,
        message="Director preparation retirement prepared",
        recovery_cursor=cursor,
    )
    _remove_director_preparation_state(project_dir, request_id)
    with _director_preparation_lock:
        _director_preparation_states.pop(request_id, None)
    _queue_recovery_durable_transition(DurableTransition(
        name="director-preparation-retired",
        tombstones=(str(parent.get("id") or ""),),
    ))
    with _director_preparation_lock:
        _director_preparation_parents.pop(request_id, None)
        _director_preparation_rejected_parents.pop(request_id, None)
    remove_request_manifest(
        project_dir,
        parent.get("_recovery_manifest_pointer") or {},
    )
    return True


def _director_recovery_retire_old_preparations(
    projects: dict[str, tuple[str, str]],
    *,
    now: float | None = None,
    retention_s: float = _DIRECTOR_PREPARATION_RETENTION_S,
    max_retained: int = _DIRECTOR_PREPARATION_MAX_RETAINED,
) -> int:
    """Bound completed request identities without touching active chains."""
    current_time = time.time() if now is None else float(now)
    completed = []
    with _director_preparation_lock:
        for request_id, state in _director_preparation_states.items():
            if not isinstance(state, dict) or state.get("status") != "completed":
                continue
            try:
                updated_at = float(
                    state.get("updated_at") or state.get("created_at") or 0
                )
            except (TypeError, ValueError):
                updated_at = 0.0
            completed.append((
                updated_at,
                request_id,
                str(state.get("workspace") or "default"),
            ))
    completed.sort(reverse=True)
    retired = 0
    keep_limit = max(0, int(max_retained))
    for index, (updated_at, request_id, workspace) in enumerate(completed):
        expired = updated_at <= current_time - max(0.0, float(retention_s))
        over_capacity = index >= keep_limit
        current = projects.get(workspace)
        if not (expired or over_capacity) or current is None:
            continue
        try:
            retired += int(_director_recovery_retire_preparation(
                request_id, current[0],
            ))
        except Exception:
            # Intent is durable; startup reconciliation can finish a state
            # erase whose tombstone was interrupted.
            continue
    return retired


def _register_director_preparation(
    request: Request,
    body: dict,
    workspace: str,
    project_dir: str,
) -> tuple[str, dict]:
    """Create the durable music/analyze parent before recoverable work."""
    requested_id = str(body.get("director_request_id") or "")
    if requested_id:
        state = _require_director_preparation(
            request, requested_id, workspace,
        )
        return requested_id, state
    request_id = uuid.uuid4().hex
    owner = request.state.maestro_session_id
    state = {
        "version": 1,
        "request_id": request_id,
        "workspace": workspace,
        "owner_session_id": owner,
        "source_remote": bool(getattr(request.state, "maestro_remote", False)),
        "status": "running",
        "phase": "registered",
        "created_at": time.time(),
        "updated_at": time.time(),
        "request": dict(body),
        "music": None,
        "analysis": None,
        "classification": None,
        "structure": None,
    }
    state["request"].pop("director_request_id", None)
    descriptor = _write_director_preparation_state(project_dir, state)
    parent_id = f"director-request-{request_id}"
    owner_digest = owner_principal_digest(_session_secret(), owner)
    project_digest = _queue_recovery_project_identity(workspace, project_dir)
    try:
        manifest = atomic_write_request_manifest(
            project_dir,
            job_id=parent_id,
            params={
                "request_id": request_id,
                "state_filename": descriptor["path"],
            },
            inputs=_queue_recovery_input_descriptors({
                "params": body,
                "out_dir": project_dir,
            }, owner_digest),
        )
    except Exception:
        _remove_director_preparation_state(project_dir, request_id)
        raise
    parent = {
        "id": parent_id,
        "kind": "director_preparation",
        "status": "queued",
        "workspace": workspace,
        "source_remote": state["source_remote"],
        "private": True,
        "explicit": False,
        "created_at": state["created_at"],
        "phase": "registered",
        "message": "Director preparation registered",
        "recovery_state": "restored",
        "recovery_unit": {
            "kind": "director_preparation_state",
            "state": "committed",
            **descriptor,
        },
        "recovery_cursor": {
            "request_id": request_id,
            "state": descriptor,
        },
        "_recovery_owner_digest": owner_digest,
        "_recovery_project_digest": project_digest,
        "_recovery_manifest_pointer": dict(manifest),
    }
    try:
        _queue_recovery_with_bounded_compaction(
            lambda: _queue_recovery_coordinator.register_job(
                parent,
                owner_digest=owner_digest,
                project_digest=project_digest,
                request_manifest=manifest,
            ),
        )
    except Exception:
        remove_request_manifest(project_dir, manifest)
        _remove_director_preparation_state(project_dir, request_id)
        raise
    with _director_preparation_lock:
        _director_preparation_parents[request_id] = parent
        _director_preparation_states[request_id] = state
    return request_id, dict(state)


def _checkpoint_director_preparation(
    request_id: str,
    project_dir: str,
    **updates,
) -> dict:
    with _director_preparation_lock:
        state = dict(_director_preparation_states.get(request_id) or {})
        parent = _director_preparation_parents.get(request_id)
        if not state or not isinstance(parent, dict):
            raise QueueRecoveryRuntimeError(
                "Director preparation recovery state is unavailable."
            )
        state.update(updates)
        state["updated_at"] = time.time()
        _encoded, descriptor = _director_preparation_payload(state)
        cursor = dict(parent.get("recovery_cursor") or {})
        cursor.update({
            "request_id": request_id,
            "pending_state": descriptor,
        })
        _queue_recovery_checkpoint(
            parent,
            message="Director preparation state replacement prepared",
            recovery_cursor=cursor,
        )
        descriptor = _write_director_preparation_state(project_dir, state)
        cursor["state"] = descriptor
        cursor.pop("pending_state", None)
        _queue_recovery_checkpoint(
            parent,
            status="queued",
            phase=str(state.get("phase") or "preparing"),
            message="Director preparation checkpoint committed",
            recovery_state=(
                "terminal" if state.get("status") == "completed" else "restored"
            ),
            recovery_unit={
                "kind": "director_preparation_state",
                "state": "committed",
                **descriptor,
            },
            recovery_cursor={
                **cursor,
                "request_id": request_id,
                "state": descriptor,
            },
        )
        _director_preparation_states[request_id] = state
        result = dict(state)
    if result.get("status") == "completed":
        existing_projects = globals().get("_queue_recovery_existing_projects")
        retire_old_preparations = globals().get(
            "_director_recovery_retire_old_preparations"
        )
        if (
            existing_projects is not None
            and retire_old_preparations is not None
        ):
            try:
                retire_old_preparations(existing_projects())
            except Exception:
                # Completion is already durable. A later completion or
                # startup maintenance pass can retry bounded retirement.
                pass
    return result


def _require_director_preparation(
    request: Request,
    request_id: str,
    workspace: str = "",
    *,
    allow_blocked: bool = False,
) -> dict:
    try:
        filename = _director_preparation_filename(request_id)
    except ValueError:
        raise HTTPException(status_code=404, detail="Director request not found")
    selected = workspace or _get_active_workspace()
    project_dir = _require_project_access(request, selected)
    with _director_preparation_lock:
        state = dict(_director_preparation_states.get(request_id) or {})
    if not state:
        path = os.path.join(project_dir, filename)
        try:
            with open(path, "r", encoding="utf-8") as handle:
                state = json.load(handle)
        except (OSError, ValueError, TypeError):
            raise HTTPException(
                status_code=404, detail="Director request not found",
            )
    if (
        not isinstance(state, dict)
        or state.get("request_id") != request_id
        or state.get("workspace") != selected
        or state.get("owner_session_id") != request.state.maestro_session_id
    ):
        raise HTTPException(status_code=404, detail="Director request not found")
    parent = _director_preparation_parents.get(request_id)
    rejected = _director_preparation_rejected_parents.get(request_id)
    if not isinstance(parent, dict):
        if isinstance(rejected, dict):
            expected_owner = str(rejected.get("owner_principal") or "")
            expected_project = str(rejected.get("project_instance") or "")
            try:
                request_owner = owner_principal_digest(
                    _session_secret(), request.state.maestro_session_id,
                )
                current_project = _queue_recovery_project_identity(
                    selected, project_dir,
                )
            except (ValueError, QueueRecoveryAdapterError):
                raise HTTPException(
                    status_code=404, detail="Director request not found",
                )
            if (
                not expected_owner
                or not expected_project
                or not hmac.compare_digest(expected_owner, request_owner)
                or not hmac.compare_digest(expected_project, current_project)
            ):
                raise HTTPException(
                    status_code=404, detail="Director request not found",
                )
        if allow_blocked:
            state.update({
                "status": "blocked",
                "phase": "blocked_recovery_unavailable",
                "recovery_blocked": True,
            })
            return state
        raise HTTPException(
            status_code=409,
            detail="Director preparation recovery is blocked.",
        )
    if isinstance(parent, dict):
        expected_owner = str(parent.get("_recovery_owner_digest") or "")
        try:
            request_owner = owner_principal_digest(
                _session_secret(), request.state.maestro_session_id,
            )
        except ValueError:
            raise HTTPException(
                status_code=404, detail="Director request not found",
            )
        if expected_owner and not hmac.compare_digest(
            expected_owner, request_owner,
        ):
            raise HTTPException(
                status_code=404, detail="Director request not found",
            )
        expected_project = str(parent.get("_recovery_project_digest") or "")
        try:
            current_project = _queue_recovery_project_identity(
                selected, project_dir,
            )
        except (ValueError, QueueRecoveryAdapterError):
            raise HTTPException(
                status_code=404, detail="Director request not found",
            )
        if expected_project and not hmac.compare_digest(
            expected_project, current_project,
        ):
            raise HTTPException(
                status_code=404, detail="Director request not found",
            )
        if state.get("recovery_blocked"):
            if allow_blocked:
                return state
            raise HTTPException(
                status_code=409,
                detail="Director preparation inputs changed.",
            )
        pointer = parent.get("_recovery_manifest_pointer")
        try:
            cursor = parent.get("recovery_cursor")
            cursor = cursor if isinstance(cursor, dict) else {}
            sealed_state, sealed_descriptor, used_pending = (
                _load_director_recovery_cursor_state(
                    project_dir, filename, cursor,
                )
            )
            if (
                sealed_state is None
                or sealed_state.get("request_id") != request_id
                or sealed_state.get("workspace") != selected
                or sealed_state.get("owner_session_id")
                    != request.state.maestro_session_id
            ):
                raise QueueRecoveryRuntimeError(
                    "Director preparation state identity changed."
                )
            state = sealed_state
            manifest = load_request_manifest(
                project_dir,
                pointer if isinstance(pointer, dict) else {},
                expected_job_id=str(parent.get("id") or ""),
            )
            manifest_params = manifest.get("params") or {}
            if (
                manifest_params.get("request_id") != request_id
                or manifest_params.get("state_filename") != filename
            ):
                raise QueueRecoveryRuntimeError(
                    "Director preparation pointer is invalid."
                )
            validate_manifest_inputs(
                manifest,
                lambda descriptor: _queue_recovery_manifest_validator(
                    dict(descriptor),
                    owner_digest=expected_owner,
                    workspace=selected,
                    project_dir=project_dir,
                ),
            )
            if used_pending:
                promoted_cursor = dict(cursor)
                promoted_cursor["state"] = dict(sealed_descriptor or {})
                promoted_cursor.pop("pending_state", None)
                _queue_recovery_checkpoint(
                    parent,
                    recovery_unit={
                        "kind": "director_preparation_state",
                        "state": "committed",
                        **dict(sealed_descriptor or {}),
                    },
                    recovery_cursor=promoted_cursor,
                    message="Director preparation state committed",
                )
        except QueueRecoveryRuntimeError:
            if allow_blocked:
                state.update({
                    "status": "blocked",
                    "phase": "blocked_input_changed",
                    "recovery_blocked": True,
                })
                return state
            raise HTTPException(
                status_code=409,
                detail="Director preparation inputs changed.",
            )
    return state


def _queue_recovery_existing_projects() -> dict[str, tuple[str, str]]:
    """Ensure a marker for every existing project without creating projects."""
    from services.win_safe_files import is_safe_workspace_name

    base = os.path.realpath(wgp.server_config.get("save_path", "outputs"))
    projects: dict[str, tuple[str, str]] = {}
    if os.path.isdir(base):
        try:
            projects["default"] = (
                base,
                _queue_recovery_project_identity("default", base),
            )
        except (ValueError, QueueRecoveryAdapterError):
            pass
        try:
            names = sorted(os.listdir(base))
        except OSError:
            names = []
        for name in names:
            if name == "default" or not is_safe_workspace_name(name):
                continue
            candidate = os.path.join(base, name)
            if not os.path.isdir(candidate) or os.path.islink(candidate):
                continue
            try:
                projects[name] = (
                    candidate,
                    _queue_recovery_project_identity(name, candidate),
                )
            except (ValueError, QueueRecoveryAdapterError):
                continue
    return projects


def _queue_recovery_materialize_job(
    snapshot: dict,
    projects: dict[str, tuple[str, str]],
) -> tuple[dict, bool]:
    """Rebuild one safe runtime job and report whether it may auto-resume."""
    job_id = str(snapshot.get("id") or "")
    workspace = str(snapshot.get("workspace") or "default")
    owner_digest = str(snapshot.get("owner_principal") or "")
    expected_project = str(snapshot.get("project_instance") or "")
    runtime = {
        key: value
        for key, value in snapshot.items()
        if key not in {"owner_principal", "project_instance", "request_manifest"}
    }
    runtime.update({
        "id": job_id,
        "workspace": workspace,
        "session_id": None,
        "access_policy": {
            "private": bool(snapshot.get("private", False)),
            "explicit": bool(snapshot.get("explicit", False)),
        },
        "error": None,
        "_recovery_owner_digest": owner_digest,
        "_recovery_project_digest": expected_project,
        "_recovery_manifest_pointer": dict(snapshot.get("request_manifest") or {}),
    })
    current = projects.get(workspace)
    blocked_reason = "Recovery project is missing or was recreated"
    blocked_code = "project_missing_or_recreated"
    manifest = None
    if current is not None and hmac.compare_digest(current[1], expected_project):
        runtime["out_dir"] = current[0]
        try:
            manifest = load_request_manifest(
                current[0],
                snapshot.get("request_manifest") or {},
                expected_job_id=job_id,
            )
            validate_manifest_inputs(
                manifest,
                lambda descriptor: _queue_recovery_manifest_validator(
                    dict(descriptor),
                    owner_digest=owner_digest,
                    workspace=workspace,
                    project_dir=current[0],
                ),
            )
            runtime["params"] = dict(manifest["params"])
            _queue_recovery_reconcile_cursor(runtime, current[0])
            blocked_reason = ""
            blocked_code = ""
        except QueueRecoveryRuntimeError:
            blocked_reason = "Recovery request or input validation failed"
            blocked_code = "input_missing_or_changed"

    status = str(snapshot.get("status") or "queued").casefold()
    if status in {"cancelled", "canceled"} or snapshot.get("cancel_requested"):
        runtime.update({
            "status": "cancelled",
            "cancel_requested": True,
            "recovery_state": "cancelled",
            "message": "Cancelled",
        })
        return runtime, False
    if status in {"completed", "failed"}:
        runtime["status"] = status
        runtime["recovery_state"] = "terminal"
        return runtime, False

    attempt, may_retry = next_recovery_attempt(snapshot)
    runtime["recovery_attempt"] = attempt
    runtime["status"] = "queued"
    runtime["_recovery_original_held"] = bool(snapshot.get("queue_held", False))
    remote = bool(snapshot.get("source_remote", False))
    if _queue_recovery_worker(runtime) is None:
        runtime.update({
            "_recovery_reason_code": "preparation_must_resubmit",
            "queue_held": True,
            "recovery_state": "blocked_preparation",
            "reruns_denoise": False,
            "message": "This interrupted preparation must be resubmitted",
        })
        return runtime, False
    if blocked_reason or not may_retry:
        runtime.update({
            "_recovery_reason_code": (
                blocked_code if blocked_reason else "attempt_limit_reached"
            ),
            "queue_held": True,
            "recovery_state": "blocked",
            "message": blocked_reason or "Automatic recovery attempt limit reached",
        })
        return runtime, False
    if remote:
        runtime.update({
            "_recovery_reason_code": "owner_reauthentication_required",
            "queue_held": True,
            "recovery_state": "blocked_remote_reauth",
            "message": "Owner reauthentication is required to resume",
        })
        return runtime, False
    runtime.update({
        "_recovery_reason_code": "",
        "queue_held": bool(snapshot.get("queue_held", False)),
        "recovery_state": "interrupted" if status == "running" else "restored",
        "reruns_denoise": status == "running",
        "message": (
            "Recovered after an interrupted safe unit"
            if status == "running" else str(snapshot.get("message") or "Queued")
        ),
    })
    return runtime, not runtime["queue_held"]


def _director_recovery_restore_parent(
    snapshot: dict,
    projects: dict[str, tuple[str, str]],
) -> str | None:
    """Restore one exact Director parent after all child jobs are visible."""
    cursor = snapshot.get("recovery_cursor")
    cursor = cursor if isinstance(cursor, dict) else {}
    pid = str(cursor.get("pipeline_id") or "")
    if not pid:
        return None
    # A journal-known id may never fall back to the legacy raw-JSON resume
    # route when its exact recovery authority cannot be reconstructed.
    _director_recovery_rejected_parents[pid] = dict(snapshot)
    workspace = str(snapshot.get("workspace") or "default")
    current = projects.get(workspace)
    if current is None:
        return None
    expected_project = str(snapshot.get("project_instance") or "")
    if not hmac.compare_digest(current[1], expected_project):
        return None
    owner_digest = str(snapshot.get("owner_principal") or "")
    try:
        from services.director_pipeline import pipeline_state_filename
        from services.win_safe_files import safe_direct_file_under
        state_filename = pipeline_state_filename(pid)
        state_path = safe_direct_file_under(current[0], state_filename)
        if cursor.get("delete_pending") and (
            not state_path or not os.path.isfile(state_path)
        ):
            _queue_recovery_durable_transition(DurableTransition(
                name="director-parent-delete-reconciled",
                tombstones=(str(snapshot.get("id") or ""),),
            ))
            remove_request_manifest(
                current[0], snapshot.get("request_manifest") or {},
            )
            _director_recovery_rejected_parents.pop(pid, None)
            return None
        state, sealed_state, _used_pending = (
            _load_director_recovery_cursor_state(
                current[0], state_filename, cursor,
            )
        )
        if state is None:
            raise QueueRecoveryRuntimeError(
                "Director recovery state hash changed."
            )
        if not state_path or not os.path.isfile(state_path):
            raise QueueRecoveryRuntimeError(
                "Director recovery state is unavailable."
            )
        if not isinstance(state, dict) or state.get("pipeline_id") != pid:
            raise QueueRecoveryRuntimeError(
                "Director recovery state is invalid."
            )
        state_owner = _pipeline_owner(state.get("_params_snapshot"))
        if not state_owner or not hmac.compare_digest(
            owner_principal_digest(_session_secret(), state_owner),
            owner_digest,
        ):
            raise QueueRecoveryRuntimeError(
                "Director recovery owner evidence changed."
            )
    except (OSError, ValueError, TypeError, QueueRecoveryRuntimeError):
        return None

    blocked_reason = ""
    manifest = None
    try:
        manifest = load_request_manifest(
            current[0],
            snapshot.get("request_manifest") or {},
            expected_job_id=str(snapshot.get("id") or ""),
        )
        manifest_params = manifest.get("params") or {}
        if (
            manifest_params.get("pipeline_id") != pid
            or manifest_params.get("state_filename") != state_filename
        ):
            raise QueueRecoveryRuntimeError(
                "Director recovery state pointer is invalid."
            )
        validate_manifest_inputs(
            manifest,
            lambda descriptor: _queue_recovery_manifest_validator(
                dict(descriptor),
                owner_digest=owner_digest,
                workspace=workspace,
                project_dir=current[0],
            ),
        )
    except (OSError, ValueError, TypeError, QueueRecoveryRuntimeError):
        blocked_reason = (
            "Recovery is blocked because its saved request or inputs "
            "could not be validated."
        )

    parent = _director_runtime_parent_from_snapshot(
        snapshot,
        identity_key="pipeline_id",
        identity_value=pid,
        state_descriptor=dict(sealed_state or {}),
        unit_kind="director_parent_state",
    )
    _director_recovery_parents[pid] = parent
    _director_recovery_rejected_parents.pop(pid, None)
    _init_pipeline()
    from services.director_pipeline import restore_registered_pipeline
    active = str(state.get("status") or "") not in {
        "completed", "failed", "cancelled",
    }
    blocked_remote = (
        not blocked_reason
        and bool(snapshot.get("source_remote", False))
        and active
    )
    _queue_recovery_checkpoint(
        parent,
        status=(
            "queued"
            if str(state.get("status") or "")
                in {"completed", "failed", "cancelled"}
            else str(state.get("status") or "queued")
        ),
        queue_held=bool(blocked_reason or blocked_remote),
        recovery_state=(
            "terminal" if not active
            else "blocked" if blocked_reason
            else "blocked_remote_reauth" if blocked_remote
            else "restored"
        ),
        phase=str(state.get("phase") or state.get("status") or "restored"),
        message="Director recovery state restored",
        recovery_unit=dict(parent["recovery_unit"]),
        recovery_cursor=dict(parent["recovery_cursor"]),
    )
    if blocked_reason and active:
        _queue_recovery_checkpoint(
            parent,
            status="queued",
            queue_held=True,
            recovery_state="blocked",
            message=blocked_reason,
        )
    elif blocked_remote:
        _queue_recovery_checkpoint(
            parent,
            status="queued",
            queue_held=True,
            recovery_state="blocked_remote_reauth",
            message="Owner reauthentication is required to resume",
        )
    restore_registered_pipeline(
        state,
        state_path,
        {
            "id": str(snapshot.get("id") or ""),
            "owner_digest": owner_digest,
            "project_digest": expected_project,
            "inputs": list((manifest or {}).get("inputs") or []),
        },
        blocked_remote=blocked_remote,
        blocked_reason=blocked_reason if active else "",
        defer_worker=True,
    )
    return pid if active and not blocked_remote and not blocked_reason else None


def _director_recovery_restore_preparation(
    snapshot: dict,
    projects: dict[str, tuple[str, str]],
) -> bool:
    cursor = snapshot.get("recovery_cursor")
    cursor = cursor if isinstance(cursor, dict) else {}
    request_id = str(cursor.get("request_id") or "")
    if not request_id:
        return False
    _director_preparation_rejected_parents[request_id] = dict(snapshot)
    terminal_snapshot = (
        str(snapshot.get("recovery_state") or "") == "terminal"
        or str(snapshot.get("status") or "") == "completed"
    )
    workspace = str(snapshot.get("workspace") or "default")
    current = projects.get(workspace)
    if current is None:
        if terminal_snapshot:
            _queue_recovery_durable_transition(DurableTransition(
                name="director-preparation-missing-project-retired",
                tombstones=(str(snapshot.get("id") or ""),),
            ))
            _director_preparation_rejected_parents.pop(request_id, None)
        return False
    expected_project = str(snapshot.get("project_instance") or "")
    owner_digest = str(snapshot.get("owner_principal") or "")
    if not hmac.compare_digest(current[1], expected_project):
        if terminal_snapshot:
            _queue_recovery_durable_transition(DurableTransition(
                name="director-preparation-recreated-project-retired",
                tombstones=(str(snapshot.get("id") or ""),),
            ))
            _director_preparation_rejected_parents.pop(request_id, None)
        return False
    try:
        filename = _director_preparation_filename(request_id)
        if cursor.get("retire_pending"):
            _remove_director_preparation_state(current[0], request_id)
            _queue_recovery_durable_transition(DurableTransition(
                name="director-preparation-retirement-reconciled",
                tombstones=(str(snapshot.get("id") or ""),),
            ))
            remove_request_manifest(
                current[0], snapshot.get("request_manifest") or {},
            )
            _director_preparation_rejected_parents.pop(request_id, None)
            return False
        state, sealed_state, _used_pending = (
            _load_director_recovery_cursor_state(
                current[0], filename, cursor,
            )
        )
        if state is None:
            raise QueueRecoveryRuntimeError(
                "Director preparation state hash changed."
            )
        owner = str(state.get("owner_session_id") or "")
        if (
            not isinstance(state, dict)
            or state.get("request_id") != request_id
            or state.get("workspace") != workspace
            or not owner
            or not hmac.compare_digest(
                owner_principal_digest(_session_secret(), owner),
                owner_digest,
            )
        ):
            raise QueueRecoveryRuntimeError(
                "Director preparation owner evidence changed."
            )
    except (OSError, ValueError, TypeError, QueueRecoveryRuntimeError):
        return False
    blocked_inputs = False
    try:
        manifest = load_request_manifest(
            current[0],
            snapshot.get("request_manifest") or {},
            expected_job_id=str(snapshot.get("id") or ""),
        )
        manifest_params = manifest.get("params") or {}
        if (
            manifest_params.get("request_id") != request_id
            or manifest_params.get("state_filename") != filename
        ):
            raise QueueRecoveryRuntimeError(
                "Director preparation pointer is invalid."
            )
        validate_manifest_inputs(
            manifest,
            lambda descriptor: _queue_recovery_manifest_validator(
                dict(descriptor),
                owner_digest=owner_digest,
                workspace=workspace,
                project_dir=current[0],
            ),
        )
    except (OSError, ValueError, TypeError, QueueRecoveryRuntimeError):
        blocked_inputs = state.get("status") != "completed"
    parent = _director_runtime_parent_from_snapshot(
        snapshot,
        identity_key="request_id",
        identity_value=request_id,
        state_descriptor=dict(sealed_state or {}),
        unit_kind="director_preparation_state",
    )
    with _director_preparation_lock:
        _director_preparation_parents[request_id] = parent
        runtime_state = dict(state)
        if blocked_inputs:
            runtime_state.update({
                "status": "blocked",
                "phase": "blocked_input_changed",
                "recovery_blocked": True,
            })
        _director_preparation_states[request_id] = runtime_state
    _director_preparation_rejected_parents.pop(request_id, None)
    _queue_recovery_checkpoint(
        parent,
        status="queued",
        queue_held=bool(
            blocked_inputs
            or (
                snapshot.get("source_remote", False)
                and state.get("status") != "completed"
            )
        ),
        recovery_state=(
            "terminal" if state.get("status") == "completed"
            else "blocked" if blocked_inputs
            else "blocked_remote_reauth"
            if snapshot.get("source_remote", False)
            else "restored"
        ),
        phase=str(state.get("phase") or "restored"),
        message="Director preparation state restored",
        recovery_unit=dict(parent["recovery_unit"]),
        recovery_cursor=dict(parent["recovery_cursor"]),
    )
    if blocked_inputs:
        _queue_recovery_checkpoint(
            parent,
            status="queued",
            queue_held=True,
            recovery_state="blocked",
            message=(
                "Director preparation inputs changed; manual restart is "
                "required"
            ),
        )
    elif (
        bool(snapshot.get("source_remote", False))
        and state.get("status") != "completed"
    ):
        _queue_recovery_checkpoint(
            parent,
            status="queued",
            queue_held=True,
            recovery_state="blocked_remote_reauth",
            message="Owner reauthentication is required to resume",
        )
    return True


def _restore_queue_recovery_on_startup() -> None:
    """Restore scheduler membership before starting any recovered workers."""
    global _queue_recovery_workers_started
    if _queue_recovery_workers_started:
        return
    projects = _queue_recovery_existing_projects()
    restored_jobs: list[dict] = []
    resumable: list[dict] = []
    director_parents: list[dict] = []
    director_preparations: list[dict] = []
    director_resumable: list[str] = []
    director_legacy_payloads = False
    for snapshot in _queue_recovery_restored.jobs.values():
        if snapshot.get("kind") == "director_pipeline":
            director_parents.append(snapshot)
            director_legacy_payloads = (
                director_legacy_payloads
                or _director_snapshot_has_legacy_artifacts(snapshot)
            )
            continue
        if snapshot.get("kind") == "director_preparation":
            director_preparations.append(snapshot)
            director_legacy_payloads = (
                director_legacy_payloads
                or _director_snapshot_has_legacy_artifacts(snapshot)
            )
            continue
        job, auto_resume = _queue_recovery_materialize_job(snapshot, projects)
        # Persist running->interrupted/blocked conversion before publication.
        if job.get("status") not in {"completed", "failed", "cancelled"}:
            _queue_recovery_checkpoint(
                job,
                status=job.get("status"),
                queue_held=bool(job.get("queue_held", False)),
                recovery_attempt=int(job.get("recovery_attempt", 0) or 0),
                recovery_state=str(job.get("recovery_state") or "blocked"),
                reruns_denoise=bool(job.get("reruns_denoise", False)),
                message=str(job.get("message") or "Recovery blocked"),
            )
        if job.get("out_dir"):
            try:
                _stamp_requested_generation_residency(job, replace=True)
            except Exception:
                job["queue_held"] = True
                job["recovery_state"] = "blocked"
                job["message"] = "Recovery scheduling validation failed"
                auto_resume = False
            _jobs.publish_prepared(job["id"], _jobs.prepare(job))
        else:
            # A missing/recreated project must remain visible as blocked but
            # can never trigger the registry's project-creating fallback.
            dict.__setitem__(_jobs, job["id"], _jobs.prepare(job))
        restored_jobs.append(job)
        if auto_resume:
            resumable.append(job)
    restore_scheduler_state(restored_jobs, _queue_recovery_restored.global_state)
    for snapshot in director_parents:
        resumable_pid = _director_recovery_restore_parent(snapshot, projects)
        if resumable_pid:
            director_resumable.append(resumable_pid)
    for snapshot in director_preparations:
        _director_recovery_restore_preparation(snapshot, projects)
    retire_old_preparations = globals().get(
        "_director_recovery_retire_old_preparations"
    )
    if retire_old_preparations is not None:
        retire_old_preparations(projects)
    terminal_statuses = {"cancelled", "canceled", "completed", "failed"}
    if director_legacy_payloads or any(
        str(snapshot.get("status") or "").casefold() in terminal_statuses
        and snapshot.get("kind") != "director_child"
        for snapshot in _queue_recovery_restored.jobs.values()
    ):
        # One bounded atomic replacement retires terminal queue snapshots and
        # their old revision fences before any recovered worker starts.
        _queue_recovery_coordinator.compact()
    live_manifests: dict[str, list[str]] = {}
    live_staging_jobs: dict[str, list[str]] = {}
    for snapshot in _queue_recovery_restored.jobs.values():
        if str(snapshot.get("status") or "").casefold() in terminal_statuses:
            continue
        snapshot_workspace = str(snapshot.get("workspace") or "default")
        snapshot_job_id = snapshot.get("id")
        if isinstance(snapshot_job_id, str):
            live_staging_jobs.setdefault(snapshot_workspace, []).append(
                snapshot_job_id
            )
        pointer = snapshot.get("request_manifest")
        path = pointer.get("path") if isinstance(pointer, dict) else None
        if isinstance(path, str):
            live_manifests.setdefault(
                snapshot_workspace, [],
            ).append(path)
    for workspace, (project_dir, _project_digest) in projects.items():
        cleanup_orphan_request_manifests(
            project_dir, live_manifests.get(workspace, ()),
        )
        cleanup_orphan_staged_outputs(
            project_dir, live_staging_jobs.get(workspace, ()),
        )
    _queue_recovery_workers_started = True
    from services.director_pipeline import start_restored_pipeline
    for pid in director_resumable:
        start_restored_pipeline(pid)
    for job in resumable:
        worker = _queue_recovery_worker(job)
        if worker is None:
            job["_recovery_reason_code"] = "preparation_must_resubmit"
            _queue_recovery_checkpoint(
                job,
                queue_held=True,
                recovery_state="blocked_preparation",
                reruns_denoise=False,
                message="This interrupted preparation must be resubmitted",
            )
            continue
        thread = threading.Thread(
            target=worker,
            args=(job["id"],),
            daemon=False,
            name=f"studio-recovery-{job['id']}",
        )
        try:
            thread.start()
        except Exception:
            job["_recovery_reason_code"] = "worker_start_failed"
            _queue_recovery_checkpoint(
                job,
                queue_held=True,
                recovery_state="blocked",
                reruns_denoise=bool(job.get("reruns_denoise", True)),
                message="Recovery worker could not be started",
            )


def _queue_recovery_revalidate_job(job: dict) -> bool:
    """Recheck project marker, manifest, and all inputs for manual resume."""
    workspace = str(job.get("workspace") or "default")
    try:
        project_dir = _existing_workspace_dir(workspace)
        project_digest = _queue_recovery_existing_project_identity(project_dir)
        if not hmac.compare_digest(
            project_digest, str(job.get("_recovery_project_digest") or ""),
        ):
            job["_recovery_reason_code"] = "project_missing_or_recreated"
            return False
    except (HTTPException, QueueRecoveryAdapterError, ValueError):
        job["_recovery_reason_code"] = "project_missing_or_recreated"
        return False
    try:
        manifest = load_request_manifest(
            project_dir,
            job.get("_recovery_manifest_pointer") or {},
            expected_job_id=str(job.get("id") or ""),
        )
        validate_manifest_inputs(
            manifest,
            lambda descriptor: _queue_recovery_manifest_validator(
                dict(descriptor),
                owner_digest=str(job.get("_recovery_owner_digest") or ""),
                workspace=workspace,
                project_dir=project_dir,
            ),
        )
        job["params"] = dict(manifest["params"])
        job["out_dir"] = project_dir
        job["_recovery_reason_code"] = ""
        return True
    except (QueueRecoveryRuntimeError, ValueError):
        job["_recovery_reason_code"] = "input_missing_or_changed"
        return False


def _queue_recovery_units(job: dict) -> list[dict]:
    cursor = job.get("recovery_cursor")
    if not isinstance(cursor, dict):
        return []
    units = cursor.get("completed_units")
    return [dict(unit) for unit in units if isinstance(unit, dict)] \
        if isinstance(units, list) else []


def _queue_recovery_unit_matches(
    job: dict,
    *,
    kind: str,
    variant: int,
    index: int,
    project_dir: str,
) -> dict | None:
    """Return one fully verified completed unit; invalid evidence is ignored."""
    for unit in _queue_recovery_units(job):
        if (
            unit.get("kind") != kind
            or unit.get("variant") != variant
            or unit.get("index") != index
            or unit.get("state") != "completed"
        ):
            continue
        unit_id = str(unit.get("unit_id") or "")
        artifacts = unit.get("artifacts")
        if not isinstance(artifacts, list) or not artifacts:
            continue
        if not all(
            validate_artifact_descriptor(
                project_dir, descriptor, producer_unit_id=unit_id,
            )
            for descriptor in artifacts
            if isinstance(descriptor, dict)
        ) or len([item for item in artifacts if isinstance(item, dict)]) != len(artifacts):
            for descriptor in artifacts:
                if isinstance(descriptor, dict):
                    _quarantine_recovery_artifact(project_dir, descriptor)
            return None
        continuation = unit.get("continuation")
        if isinstance(continuation, dict) and continuation.get("basename"):
            try:
                path = _queue_recovery_continuation_path(
                    project_dir, continuation,
                )
                size, digest = _recovery_sha256_file(path)
            except QueueRecoveryRuntimeError:
                return None
            if size != continuation.get("size") or digest != continuation.get("sha256"):
                return None
        return unit
    return None


def _queue_recovery_checkpoint_unit(
    job: dict,
    *,
    kind: str,
    variant: int,
    index: int,
    project_dir: str,
    artifact_names: list[str],
    dependencies: list[str] | None = None,
    continuation: dict | None = None,
    settings: dict | None = None,
    ordinary_repeat_offset: int | None = None,
) -> dict:
    """Seal media+sidecars, then persist one completed safe-unit descriptor."""
    unit_id = recovery_unit_id(
        str(job.get("id") or ""), kind,
        variant=variant,
        index=index,
        dependencies=dependencies or (),
        settings=settings or {},
    )
    artifacts = []
    for name in artifact_names:
        sidecar_name = os.path.splitext(name)[0] + ".meta.json"
        artifacts.append(_recovery_artifact_descriptor(
            project_dir,
            basename=name,
            sidecar_basename=sidecar_name,
            producer_unit_id=unit_id,
        ))
    unit = {
        "artifacts": artifacts,
        "dependencies": list(dependencies or ()),
        "index": index,
        "kind": kind,
        "state": "completed",
        "unit_id": unit_id,
        "variant": variant,
    }
    if continuation:
        unit["continuation"] = dict(continuation)
    if settings:
        unit["settings"] = dict(settings)
    units = [
        item for item in _queue_recovery_units(job)
        if not (
            item.get("kind") == kind
            and item.get("variant") == variant
            and item.get("index") == index
        )
    ]
    units.append(unit)
    cursor = dict(job.get("recovery_cursor") or {})
    cursor["completed_units"] = units[-2048:]
    if ordinary_repeat_offset is not None:
        cursor["ordinary_repeat_offset"] = max(0, int(ordinary_repeat_offset))
    _queue_recovery_checkpoint(
        job,
        recovery_unit=unit,
        recovery_cursor=cursor,
        recovery_state="restored",
        reruns_denoise=False,
    )
    return unit


def _queue_recovery_continuation_descriptor(
    project_dir: str,
    path: str | None,
    *,
    mode: str,
    dependency: str,
    metadata: dict | None = None,
) -> dict:
    """Seal an H3 continuation file or an explicit prompt-only handoff."""
    if not path:
        return {"dependency": dependency, "mode": "prompt_only"}
    candidate = os.path.abspath(path)
    staging_root = os.path.realpath(
        ensure_recovery_staging_directory(project_dir)
    )
    if (
        os.path.dirname(candidate) != staging_root
        or os.path.realpath(candidate) != candidate
        or os.path.basename(candidate) != os.path.basename(path)
        or not os.path.basename(candidate).startswith("unit-")
    ):
        raise QueueRecoveryRuntimeError(
            "H3 continuation is not in private recovery staging."
        )
    size, digest = _recovery_sha256_file(candidate)
    descriptor = {
        "basename": os.path.basename(candidate),
        "dependency": dependency,
        "mode": mode,
        "sha256": digest,
        "size": size,
        "storage": "recovery_staging",
    }
    if metadata:
        allowed = {
            "fps", "audio_sample_rate", "audio_channels", "overlap_frames",
            "discard_frames", "boundary_type",
        }
        descriptor.update({
            key: metadata[key] for key in allowed if key in metadata
        })
    return descriptor


def _queue_recovery_continuation_path(
    project_dir: str,
    continuation: dict,
) -> str | None:
    """Resolve one journal-safe continuation pointer to an exact local root."""
    name = continuation.get("basename")
    if not name:
        return None
    if (
        not isinstance(name, str)
        or os.path.basename(name) != name
        or name in {".", ".."}
    ):
        raise QueueRecoveryRuntimeError("H3 continuation identity is invalid.")
    storage = continuation.get("storage")
    if storage == "recovery_staging" and name.startswith("unit-"):
        root = os.path.realpath(ensure_recovery_staging_directory(project_dir))
    else:
        raise QueueRecoveryRuntimeError("H3 continuation storage is invalid.")
    path = os.path.abspath(os.path.join(root, name))
    if os.path.dirname(path) != root or os.path.realpath(path) != path:
        raise QueueRecoveryRuntimeError("H3 continuation escaped its storage root.")
    return path


def _queue_recovery_staged_media_paths(
    values,
    staging_dir: str | None,
) -> dict[str, str]:
    """Return existing direct-child staged media keyed by stable basename."""
    if not staging_dir:
        return {}
    root = os.path.normcase(os.path.realpath(staging_dir))
    result: dict[str, str] = {}
    for value in values or ():
        if isinstance(value, tuple):
            value = value[0] if value else None
        if not isinstance(value, str) or not value:
            continue
        resolved = os.path.realpath(os.path.abspath(value))
        name = os.path.basename(resolved)
        if (
            os.path.normcase(os.path.dirname(resolved)) == root
            and os.path.splitext(name)[1].lower() in GENERATED_MEDIA_EXTENSIONS
            and os.path.isfile(resolved)
            and not os.path.islink(resolved)
        ):
            result[name] = resolved
    return result


def _queue_recovery_resolve_task_video_path(
    output_path: str,
    project_dir: str,
    staged_media: dict[str, str],
) -> str | None:
    """Accept only a current public child or its attested private staging path."""
    if not isinstance(output_path, str) or not output_path:
        return None
    candidate = output_path if os.path.isabs(output_path) else os.path.join(
        project_dir, output_path,
    )
    resolved = os.path.realpath(candidate)
    public_child = (
        os.path.normcase(os.path.dirname(resolved))
        == os.path.normcase(os.path.realpath(project_dir))
    )
    staged = staged_media.get(os.path.basename(resolved))
    staged_child = (
        isinstance(staged, str)
        and os.path.normcase(os.path.realpath(staged))
        == os.path.normcase(resolved)
    )
    if (
        not (public_child or staged_child)
        or not os.path.isfile(resolved)
        or os.path.islink(resolved)
    ):
        return None
    return resolved


def _queue_recovery_promote_staged_outputs(
    gen: dict,
    project_dir: str,
    media_paths: dict[str, str],
) -> None:
    """Promote sidecar-sealed media and rebind WGP's in-memory path state."""
    replacements = {}
    for basename, staged_path in media_paths.items():
        promote_recovery_staged_artifact(
            project_dir,
            staged_path=staged_path,
            output_basename=basename,
        )
        replacements[os.path.realpath(staged_path)] = os.path.join(
            project_dir, basename,
        )
    for list_name in ("artifact_list", "file_list", "audio_file_list"):
        values = gen.get(list_name)
        if not isinstance(values, list):
            continue
        for index, value in enumerate(values):
            raw = value[0] if isinstance(value, tuple) and value else value
            if not isinstance(raw, str):
                continue
            replacement = replacements.get(os.path.realpath(raw))
            if replacement is None:
                continue
            values[index] = (
                (replacement, *value[1:])
                if isinstance(value, tuple) else replacement
            )
    roles = gen.get("artifact_roles")
    if isinstance(roles, dict):
        for staged_real, replacement in replacements.items():
            role = None
            for path in list(roles):
                if isinstance(path, str) and os.path.realpath(path) == staged_real:
                    role = roles.pop(path)
                    break
            if role is not None:
                roles[replacement] = role
    groups = gen.get("multi_clip_paths")
    if isinstance(groups, dict):
        for group in groups.values():
            if not isinstance(group, dict):
                continue
            for item in group.values():
                if not isinstance(item, dict):
                    continue
                raw = item.get("path")
                if isinstance(raw, str):
                    replacement = replacements.get(os.path.realpath(raw))
                    if replacement is not None:
                            item["path"] = replacement


def _queue_recovery_expected_artifact_role(kind: str, meta: dict) -> str | None:
    """Resolve only producer-declared modern roles; never infer a final name."""
    fixed = _RECOVERY_UNIT_FIXED_ARTIFACT_ROLES.get(str(kind or ""))
    if fixed is not None:
        return fixed
    if kind == "ordinary_repeat":
        declared = meta.get("producer_artifact_class")
        return declared if declared in _RECOVERY_ARTIFACT_ROLES else None
    return None


def _queue_recovery_repair_unit_roles(
    job: dict,
    unit: dict,
    project_dir: str,
) -> dict | None:
    """Repair semantic roles and reseal descriptors after byte changes."""
    kind = str(unit.get("kind") or "")
    unit_id = str(unit.get("unit_id") or "")
    try:
        variant = max(0, int(unit.get("variant", 0) or 0))
    except (TypeError, ValueError):
        return None
    repaired = dict(unit)
    repaired_artifacts = []
    for descriptor in unit.get("artifacts") or []:
        if not isinstance(descriptor, dict):
            return None
        name = descriptor.get("basename")
        sidecar_name = descriptor.get("sidecar_basename")
        if (
            not isinstance(name, str)
            or os.path.basename(name) != name
            or not isinstance(sidecar_name, str)
            or os.path.basename(sidecar_name) != sidecar_name
        ):
            return None
        sidecar_path = os.path.join(project_dir, sidecar_name)
        try:
            with open(sidecar_path, "r", encoding="utf-8") as handle:
                meta = json.load(handle)
        except (OSError, ValueError, TypeError):
            return None
        if (
            not isinstance(meta, dict)
            or meta.get("producer_unit_id") != unit_id
            or meta.get("producer_unit_kind") != kind
        ):
            return None
        expected_role = _queue_recovery_expected_artifact_role(kind, meta)
        if expected_role is None:
            return None
        changed = (
            meta.get("producer_artifact_class") != expected_role
            or meta.get("artifact_class") != expected_role
        )
        meta["producer_artifact_class"] = expected_role
        meta["artifact_class"] = expected_role
        if kind in {"h3_segment", "h3_concat"}:
            lineage = f"h3:{job.get('id', '')}:variant:{variant}"
            changed = changed or (
                meta.get("artifact_lineage") != lineage
                or meta.get("producer_variant_lineage") != lineage
            )
            meta["artifact_lineage"] = lineage
            meta["producer_variant_lineage"] = lineage
        if changed:
            try:
                _atomic_write_json(sidecar_path, meta)
            except (OSError, TypeError, ValueError):
                return None
        try:
            repaired_artifacts.append(_recovery_artifact_descriptor(
                project_dir,
                basename=name,
                sidecar_basename=sidecar_name,
                producer_unit_id=unit_id,
            ))
        except QueueRecoveryRuntimeError:
            return None
    if not repaired_artifacts:
        return None
    repaired["artifacts"] = repaired_artifacts
    return repaired


def _h3_dependency_closed_recovery_units(verified: list[dict]) -> list[dict]:
    """Remove H3 units whose exact predecessor evidence is unavailable."""
    dependency_closed = [
        unit for unit in verified
        if not str(unit.get("kind") or "").startswith("h3_")
    ]
    accepted_by_id = {
        str(unit.get("unit_id") or ""): unit
        for unit in dependency_closed
    }
    pending_h3 = [
        unit for unit in verified
        if str(unit.get("kind") or "").startswith("h3_")
    ]
    while pending_h3:
        admitted = []
        for unit in pending_h3:
            dependencies = unit.get("dependencies")
            if not isinstance(dependencies, list):
                continue
            if not all(
                isinstance(dependency, str) and dependency in accepted_by_id
                for dependency in dependencies
            ):
                continue
            kind = str(unit.get("kind") or "")
            settings = unit.get("settings")
            if not isinstance(settings, dict):
                settings = {}
            if kind == "h3_segment" and dependencies:
                predecessor = accepted_by_id[dependencies[-1]]
                actual_hashes = sorted(
                    str(artifact.get("sha256") or "")
                    for artifact in predecessor.get("artifacts") or []
                    if isinstance(artifact, dict) and artifact.get("sha256")
                )
                if settings.get("predecessor_artifact_hashes") != actual_hashes:
                    continue
                predecessor_continuation = predecessor.get("continuation")
                expected_continuation_hash = (
                    str(predecessor_continuation.get("sha256") or "")
                    if isinstance(predecessor_continuation, dict) else ""
                )
                if str(settings.get("predecessor_continuation_sha256") or "") != expected_continuation_hash:
                    continue
            elif kind == "h3_concat":
                actual_hashes = []
                actual_start_trims = []
                actual_tail_trims = []
                tail_metadata_complete = True
                for dependency in dependencies:
                    predecessor = accepted_by_id[dependency]
                    actual_hashes.extend(
                        str(artifact.get("sha256") or "")
                        for artifact in predecessor.get("artifacts") or []
                        if isinstance(artifact, dict) and artifact.get("sha256")
                    )
                    predecessor_settings = predecessor.get("settings")
                    tail_metadata_complete = (
                        tail_metadata_complete
                        and isinstance(predecessor_settings, dict)
                        and "trim_tail_frames" in predecessor_settings
                    )
                    actual_start_trims.append(int(
                        predecessor_settings.get("discard_prefix_frames", 0)
                        if isinstance(predecessor_settings, dict) else 0
                    ))
                    actual_tail_trims.append(int(
                        predecessor_settings.get("trim_tail_frames", 0)
                        if isinstance(predecessor_settings, dict) else 0
                    ))
                if (
                    settings.get("component_hashes") != actual_hashes
                    or settings.get("clip_start_frames") != actual_start_trims
                    or (
                        (tail_metadata_complete or "clip_tail_frames" in settings)
                        and settings.get("clip_tail_frames") != actual_tail_trims
                    )
                ):
                    continue
            dependency_closed.append(unit)
            accepted_by_id[str(unit.get("unit_id") or "")] = unit
            admitted.append(unit)
        if not admitted:
            break
        admitted_ids = {id(unit) for unit in admitted}
        pending_h3 = [
            unit for unit in pending_h3 if id(unit) not in admitted_ids
        ]
    return dependency_closed


def _queue_recovery_reconcile_cursor(job: dict, project_dir: str) -> None:
    """Keep verified units and recover the sidecar-before-journal crash gap."""
    verified: list[dict] = []
    seen: set[str] = set()
    original_units = _queue_recovery_units(job)
    had_h3_units = any(
        str(unit.get("kind") or "").startswith("h3_")
        for unit in original_units
    )
    for unit in original_units:
        unit_id = str(unit.get("unit_id") or "")
        matched = _queue_recovery_unit_matches(
            job,
            kind=str(unit.get("kind") or ""),
            variant=max(0, int(unit.get("variant", 0) or 0)),
            index=max(0, int(unit.get("index", 0) or 0)),
            project_dir=project_dir,
        )
        repair_roles = globals().get("_queue_recovery_repair_unit_roles")
        if matched is not None and callable(repair_roles):
            matched = repair_roles(job, matched, project_dir)
        if matched is not None and unit_id not in seen:
            verified.append(matched)
            seen.add(unit_id)

    # Sidecars are written and fsynced before the journal checkpoint. If the
    # process dies in that narrow gap, reconstruct the exact unit only from a
    # direct-child sidecar whose producer ID and media hash still match.
    try:
        from services.search_index import load_media_sidecars as _load_sidecars
        sidecars = _load_sidecars(project_dir)
    except Exception:
        sidecars = {}
    recovered_by_unit: dict[str, dict] = {}
    invalid_recovered_units: set[str] = set()
    for name, meta in sidecars.items():
        if not isinstance(meta, dict) or meta.get("job_id") != job.get("id"):
            continue
        unit_id = str(meta.get("producer_unit_id") or "")
        kind = str(meta.get("producer_unit_kind") or "")
        if not kind:
            continue
        try:
            variant = max(0, int(meta.get("producer_unit_variant", 0) or 0))
            index = max(0, int(meta.get("producer_unit_index", 0) or 0))
            dependencies = meta.get("producer_unit_dependencies")
            settings = meta.get("producer_unit_settings")
            continuation = meta.get("producer_unit_continuation")
            expected_artifacts = meta.get("producer_unit_artifact_names")
            if not isinstance(dependencies, list):
                dependencies = []
            if not isinstance(settings, dict):
                settings = {}
            if continuation is not None and not isinstance(continuation, dict):
                continue
            if (
                not isinstance(expected_artifacts, list)
                or not expected_artifacts
                or len(expected_artifacts) > 4096
                or len(set(expected_artifacts)) != len(expected_artifacts)
                or any(
                    not isinstance(value, str)
                    or os.path.basename(value) != value
                    or value.startswith(".")
                    for value in expected_artifacts
                )
            ):
                continue
            size, digest = _recovery_sha256_file(os.path.join(project_dir, name))
        except (TypeError, ValueError, QueueRecoveryRuntimeError):
            continue
        try:
            expected_id = recovery_unit_id(
                str(job.get("id") or ""), kind,
                variant=variant, index=index,
                dependencies=dependencies,
                settings=settings,
            )
        except QueueRecoveryRuntimeError:
            continue
        if (
            not hmac.compare_digest(unit_id, expected_id)
            or size != meta.get("producer_media_size")
            or digest != meta.get("producer_media_sha256")
        ):
            continue
        if continuation:
            if continuation.get("dependency") != unit_id:
                continue
            if continuation.get("basename"):
                try:
                    continuation_path = _queue_recovery_continuation_path(
                        project_dir, continuation,
                    )
                    continuation_size, continuation_sha = _recovery_sha256_file(
                        continuation_path,
                    )
                except QueueRecoveryRuntimeError:
                    continue
                if (
                    continuation_size != continuation.get("size")
                    or continuation_sha != continuation.get("sha256")
                ):
                    continue
        try:
            artifact = _recovery_artifact_descriptor(
                project_dir,
                basename=name,
                sidecar_basename=os.path.splitext(name)[0] + ".meta.json",
                producer_unit_id=unit_id,
            )
        except QueueRecoveryRuntimeError:
            continue
        recovered = recovered_by_unit.setdefault(unit_id, {
            "artifacts": [],
            "dependencies": list(dependencies),
            "index": index,
            "kind": kind,
            "state": "completed",
            "unit_id": unit_id,
            "variant": variant,
            "_expected_artifacts": tuple(sorted(expected_artifacts)),
        })
        if recovered.get("_expected_artifacts") != tuple(sorted(expected_artifacts)):
            invalid_recovered_units.add(unit_id)
            continue
        if settings:
            recovered["settings"] = dict(settings)
        if continuation:
            recovered["continuation"] = dict(continuation)
        recovered["artifacts"].append(artifact)
    for unit_id, unit in recovered_by_unit.items():
        expected_artifacts = set(unit.pop("_expected_artifacts", ()))
        actual_artifacts = {
            str(artifact.get("basename") or "")
            for artifact in unit.get("artifacts") or []
            if isinstance(artifact, dict)
        }
        if (
            unit_id not in invalid_recovered_units
            and actual_artifacts == expected_artifacts
            and unit_id not in seen
        ):
            repair_roles = globals().get("_queue_recovery_repair_unit_roles")
            repaired = (
                repair_roles(job, unit, project_dir)
                if callable(repair_roles) else unit
            )
            if repaired is not None:
                verified.append(repaired)
                seen.add(unit_id)

    # An independently valid downstream file must not survive after a
    # predecessor artifact or continuation is quarantined.
    verified = _h3_dependency_closed_recovery_units(verified)

    cursor = dict(job.get("recovery_cursor") or {})
    cursor["completed_units"] = verified[-2048:]
    verified_h3_units = [
        unit for unit in verified
        if str(unit.get("kind") or "").startswith("h3_")
    ]
    if had_h3_units or verified_h3_units:
        # Snapshot output_files came from the pre-repair schema and may name
        # segments as Finals. Rebuild public finality only from verified modern
        # producer units; retain every prior name in artifact lineage.
        prior_outputs = [
            name for name in job.get("output_files") or []
            if isinstance(name, str) and name
        ]
        artifacts = [
            name for name in job.get("artifact_files") or []
            if isinstance(name, str) and name
        ]
        for name in prior_outputs:
            if name not in artifacts:
                artifacts.append(name)
        for unit in verified_h3_units:
            for descriptor in unit.get("artifacts") or []:
                name = (
                    descriptor.get("basename")
                    if isinstance(descriptor, dict) else None
                )
                if isinstance(name, str) and name and name not in artifacts:
                    artifacts.append(name)
        job["artifact_files"] = artifacts
        delivery_units = [
            unit for unit in verified_h3_units
            if unit.get("kind") == "h3_delivery"
        ]
        final_units = delivery_units or [
            unit for unit in verified_h3_units
            if unit.get("kind") == "h3_concat"
        ]
        verified_finals = []
        for unit in final_units:
            for artifact in unit.get("artifacts") or []:
                name = (
                    artifact.get("basename")
                    if isinstance(artifact, dict) else None
                )
                if isinstance(name, str) and name and name not in verified_finals:
                    verified_finals.append(name)
        job["output_files"] = verified_finals
        if delivery_units or not verified_finals:
            job.pop("join_output_file", None)
        else:
            job["join_output_file"] = verified_finals[0]
    repeat_indices = {
        int(unit.get("index", -1))
        for unit in verified
        if unit.get("kind") == "ordinary_repeat"
        and int(unit.get("variant", 0) or 0) == 0
    }
    repeat_offset = 0
    while repeat_offset in repeat_indices:
        repeat_offset += 1
    cursor["ordinary_repeat_offset"] = repeat_offset
    if not isinstance(cursor.get("delivery_pending"), dict):
        recovered_delivery = _queue_recovery_reconcile_orphan_delivery(
            job, project_dir,
        )
        if recovered_delivery is not None:
            cursor["delivery_pending"] = recovered_delivery
            job["reruns_denoise"] = False
    job["recovery_cursor"] = cursor


def _h3_segment_recovery_settings(clip_info: dict) -> dict:
    """Bind published/trim semantics into one durable H3 segment identity."""
    if not isinstance(clip_info, dict):
        raise QueueRecoveryRuntimeError("H3 segment recovery metadata is invalid.")
    try:
        discard = max(
            0, int(clip_info.get("boundary_overlap_discard_frames", 0) or 0),
        )
        tail = max(0, int(clip_info.get("trim_tail_frames", 0) or 0))
        published = max(1, int(clip_info.get("published_frames", 0) or 0))
        generated_value = clip_info.get("generated_frames")
        generated = (
            max(1, int(generated_value))
            if generated_value not in (None, "")
            else published + tail
        )
    except (TypeError, ValueError):
        raise QueueRecoveryRuntimeError(
            "H3 segment trim metadata is invalid."
        ) from None
    native = clip_info.get("native_boundary_conditioning") is True
    if discard not in ({0, 17} if native else {0}):
        raise QueueRecoveryRuntimeError(
            "H3 segment trim does not match its boundary policy."
        )
    if tail >= generated or published != generated - tail:
        raise QueueRecoveryRuntimeError(
            "H3 segment tail trim does not match its publication geometry."
        )
    return {
        "discard_prefix_frames": discard,
        "generated_frames": generated,
        "native_boundary_conditioning": native,
        "published_frames": published,
        "trim_tail_frames": tail,
    }


def _snapshot_h3_recovery_task_params(
    task_params: dict, clip_info: dict | None,
) -> dict:
    """Freeze JSON-safe producer metadata before WGP materializes media inputs."""
    if not (
        isinstance(task_params, dict)
        and isinstance(clip_info, dict)
        and clip_info.get("automatic_h3_longform")
    ):
        return task_params
    try:
        snapshot = json.loads(json.dumps(task_params))
    except (TypeError, ValueError, OverflowError):
        raise QueueRecoveryRuntimeError(
            "H3 task metadata is not serializable before generation."
        ) from None
    if not isinstance(snapshot, dict):
        raise QueueRecoveryRuntimeError(
            "H3 task metadata snapshot is invalid."
        )
    return snapshot


def _merge_h3_ref2va_keyframes(
    semantic_refs: list | tuple | None,
    keyframes: list | tuple,
) -> list:
    """Preserve semantic refs while adding local Ref2VA keyframes."""
    combined = list(semantic_refs or ()) + list(keyframes or ())
    if len(combined) > 9:
        raise ValueError(
            "MiniMax H3 Ref2VA accepts at most 9 combined semantic references and per-clip keyframes"
        )
    return combined


def _apply_h3_recovered_continuation(
    unit: dict,
    next_task: dict,
    project_dir: str,
) -> None:
    """Restore only a hash-verified H3 continuation descriptor."""
    continuation = unit.get("continuation")
    if not isinstance(continuation, dict):
        return
    if continuation.get("dependency") != unit.get("unit_id"):
        raise QueueRecoveryRuntimeError("H3 continuation dependency is invalid.")
    mode = str(continuation.get("mode") or "prompt_only")
    path = _queue_recovery_continuation_path(project_dir, continuation)
    params = next_task.get("params")
    if not isinstance(params, dict):
        raise QueueRecoveryRuntimeError("H3 continuation target is invalid.")
    if mode == "last_frame" and path:
        from PIL import Image as PILImage
        frame = PILImage.open(path).convert("RGB")
        params["image_start"] = path
        params["image_prompt_type"] = "S" + str(params.get("image_prompt_type") or "")
        next_task["start_image_data"] = frame
        params.pop("_continuation", None)
    elif mode == "semantic_still" and path:
        refs = list(params.get("image_refs") or [])
        refs.append(path)
        params["image_refs"] = refs
        custom = dict(params.get("custom_settings") or {})
        custom["h3_ref2va_handoff"] = "semantic_still"
        params["custom_settings"] = custom
        params.pop("_ref2va_continuation", None)
    elif mode == "temporal_tail" and path:
        for slot, key in enumerate(
            ("video_guide", "video_guide2", "video_guide3"), start=1,
        ):
            if not params.get(key):
                params[key] = path
                params["video_prompt_type"] = {1: "V-", 2: "V+-", 3: "V++-"}[slot]
                custom = dict(params.get("custom_settings") or {})
                custom.update({
                    "h3_ref2va_handoff": "temporal_tail",
                    "h3_ref2va_handoff_video_slot": slot,
                    "h3_ref2va_handoff_frames": _H3_REF2VA_HANDOFF_FRAMES,
                })
                params["custom_settings"] = custom
                break
        params.pop("_ref2va_continuation", None)
    elif mode == "native_av_overlap" and path:
        from services.h3_boundary_policy import (
            H3_NATIVE_AUDIO_SAMPLE_RATE,
            H3_NATIVE_FPS,
            H3_NATIVE_HISTORY_FRAMES,
            H3_NATIVE_OVERLAP_FRAMES,
        )
        expected = {
            "fps": H3_NATIVE_FPS,
            "audio_sample_rate": H3_NATIVE_AUDIO_SAMPLE_RATE,
            "audio_channels": 2,
            "overlap_frames": H3_NATIVE_OVERLAP_FRAMES,
            "discard_frames": H3_NATIVE_HISTORY_FRAMES,
        }
        if any(int(continuation.get(key) or 0) != value for key, value in expected.items()):
            raise QueueRecoveryRuntimeError("H3 recovered native boundary metadata is invalid.")
        params["_h3_native_boundary"] = {
            **expected,
            "boundary_type": str(
                continuation.get("boundary_type") or "continuous"
            ),
            "mode": mode,
            "path": path,
            "sha256": continuation.get("sha256"),
            "size": continuation.get("size"),
        }
        params.pop("_h3_native_boundary_request", None)
    elif mode == "prompt_only":
        params.pop("_ref2va_continuation", None)
    else:
        raise QueueRecoveryRuntimeError("H3 continuation mode is invalid.")


def _queue_recovery_delivery_pending(job: dict) -> dict | None:
    cursor = job.get("recovery_cursor")
    pending = cursor.get("delivery_pending") if isinstance(cursor, dict) else None
    if not isinstance(pending, dict) or pending.get("state") not in {
        "staging_native", "protected_native",
    }:
        return None
    if pending.get("state") == "staging_native":
        return pending if isinstance(pending.get("staging"), list) else None
    if not isinstance(pending.get("artifacts"), list) or not pending["artifacts"]:
        return None
    if not isinstance(pending.get("settings"), dict):
        return None
    return pending


def _queue_recovery_reconcile_orphan_delivery(
    job: dict,
    project_dir: str,
) -> dict | None:
    """Recover the native-staged-before-journal crash window from sidecars."""
    records: dict[str, list[tuple[dict, dict]]] = {}
    try:
        entries = list(os.scandir(project_dir))
    except OSError:
        return None
    for entry in entries:
        if (
            not entry.is_file(follow_symlinks=False)
            or not entry.name.startswith(".maestro-delivery-")
            or not entry.name.endswith(".native.meta.json")
        ):
            continue
        try:
            with open(entry.path, "r", encoding="utf-8") as handle:
                meta = json.load(handle)
            durable = meta.get("delivery_recovery")
            unit_id = str((durable or {}).get("queue_recovery_unit_id") or "")
            settings = (durable or {}).get("queue_recovery_settings")
            dependencies = (durable or {}).get("queue_recovery_dependencies")
            original = str((durable or {}).get("original_filename") or "")
            if (
                not isinstance(meta, dict)
                or not isinstance(durable, dict)
                or str(durable.get("source_job_id") or "") != str(job.get("id") or "")
                or not isinstance(settings, dict)
                or not isinstance(dependencies, list)
                or os.path.basename(original) != original
                or original.startswith(".")
            ):
                continue
            expected = recovery_unit_id(
                str(job.get("id") or ""),
                "h3_delivery",
                dependencies=dependencies,
                settings=settings,
            )
            if not hmac.compare_digest(expected, unit_id):
                continue
            owner = str(durable.get("owner_session_id") or "")
            if not owner:
                continue
            candidate_owner = owner_principal_digest(_session_secret(), owner)
            if not hmac.compare_digest(
                candidate_owner, str(job.get("_recovery_owner_digest") or ""),
            ):
                continue
            extension = os.path.splitext(original)[1]
            native_path = entry.path[:-len(".meta.json")] + extension
            if not os.path.isfile(native_path) or os.path.islink(native_path):
                continue
            descriptor = _protected_recovery_artifact_descriptor(
                project_dir,
                basename=os.path.basename(native_path),
                sidecar_basename=entry.name,
                original_basename=original,
                producer_unit_id=unit_id,
            )
            if descriptor.get("sha256") not in settings.get("native_hashes", []):
                continue
            records.setdefault(unit_id, []).append((descriptor, durable))
        except (OSError, ValueError, TypeError, QueueRecoveryRuntimeError):
            continue
    for unit_id, candidates in records.items():
        first = candidates[0][1]
        settings = dict(first.get("queue_recovery_settings") or {})
        native_hashes = list(settings.get("native_hashes") or [])
        by_hash = {descriptor["sha256"]: descriptor for descriptor, _ in candidates}
        if len(by_hash) != len(native_hashes) or any(value not in by_hash for value in native_hashes):
            continue
        artifacts = [by_hash[value] for value in native_hashes]
        work_basenames = []
        for descriptor in artifacts:
            native = descriptor["basename"]
            marker = ".native"
            position = native.rfind(marker)
            if position < 0:
                break
            work_basenames.append(native[:position] + ".work" + native[position + len(marker):])
        if len(work_basenames) != len(artifacts):
            continue
        return {
            "artifacts": artifacts,
            "dependencies": list(first.get("queue_recovery_dependencies") or []),
            "settings": settings,
            "state": "protected_native",
            "unit_id": unit_id,
            "work_basenames": work_basenames,
        }
    return None


def _queue_recovery_delivery_plan(
    job: dict,
    project_dir: str,
    file_names: list[str],
    *,
    spatial_upsampling: str,
    delivery_resolution: str,
    delivery_fit: str,
) -> dict:
    """Bind delivery to ordered verified native hashes and producer units."""
    native_hashes = []
    dependencies = []
    sources = []
    for file_name in file_names:
        matching = None
        for unit in _queue_recovery_units(job):
            if unit.get("state") != "completed":
                continue
            for artifact in unit.get("artifacts") or []:
                if (
                    isinstance(artifact, dict)
                    and artifact.get("basename") == file_name
                    and validate_artifact_descriptor(
                        project_dir,
                        artifact,
                        producer_unit_id=str(unit.get("unit_id") or ""),
                    )
                ):
                    matching = (unit, artifact)
                    break
            if matching is not None:
                break
        if matching is None:
            raise QueueRecoveryRuntimeError(
                "H3 delivery requires a verified native producer unit."
            )
        unit, artifact = matching
        native_hashes.append(str(artifact.get("sha256") or ""))
        dependencies.append(str(unit.get("unit_id") or ""))
        sources.append(dict(artifact))
    settings = {
        "delivery_fit": delivery_fit,
        "delivery_resolution": delivery_resolution,
        "native_hashes": native_hashes,
        "spatial_upsampling": spatial_upsampling,
    }
    unit_id = recovery_unit_id(
        str(job.get("id") or ""),
        "h3_delivery",
        dependencies=dependencies,
        settings=settings,
    )
    staging = []
    for item_index, file_name in enumerate(file_names):
        stem, extension = os.path.splitext(file_name)
        prefix = (
            f".maestro-delivery-{job.get('id', 'job')}-"
            f"{unit_id[-12:]}-{item_index}-{stem}"
        )
        staging.append({
            "native_basename": prefix + ".native" + extension,
            "native_sidecar_basename": prefix + ".native.meta.json",
            "original_basename": file_name,
            "source": sources[item_index],
            "work_basename": prefix + ".work" + extension,
        })
    return {
        "dependencies": dependencies,
        "staging": staging,
        "settings": settings,
        "unit_id": unit_id,
    }


def _queue_recovery_checkpoint_delivery_intent(job: dict, plan: dict) -> dict:
    """Persist planned native names and source hashes before the first rename."""
    pending = {
        "dependencies": list(plan.get("dependencies") or []),
        "settings": dict(plan.get("settings") or {}),
        "staging": [dict(item) for item in plan.get("staging") or []],
        "state": "staging_native",
        "unit_id": str(plan.get("unit_id") or ""),
    }
    cursor = dict(job.get("recovery_cursor") or {})
    cursor["delivery_pending"] = pending
    _queue_recovery_checkpoint(
        job,
        recovery_cursor=cursor,
        recovery_state="interrupted",
        reruns_denoise=False,
        message="Protecting native output for delivery",
    )
    return pending


def _queue_recovery_checkpoint_delivery_pending(
    job: dict,
    project_dir: str,
    staged: list[dict],
    plan: dict,
) -> dict:
    artifacts = []
    for item in staged:
        descriptor = _protected_recovery_artifact_descriptor(
            project_dir,
            basename=os.path.basename(item["native_path"]),
            sidecar_basename=os.path.basename(item["native_meta"]),
            original_basename=item["file_name"],
            producer_unit_id=plan["unit_id"],
        )
        item["recovery_descriptor"] = descriptor
        item["work_basename"] = os.path.basename(item["work_path"])
        artifacts.append(descriptor)
    pending = {
        "artifacts": artifacts,
        "dependencies": list(plan["dependencies"]),
        "settings": dict(plan["settings"]),
        "state": "protected_native",
        "unit_id": str(plan["unit_id"]),
        "work_basenames": [item["work_basename"] for item in staged],
    }
    cursor = dict(job.get("recovery_cursor") or {})
    cursor["delivery_pending"] = pending
    _queue_recovery_checkpoint(
        job,
        recovery_cursor=cursor,
        recovery_state="interrupted",
        reruns_denoise=False,
        message="Protected native output is ready for delivery",
    )
    return pending


def _queue_recovery_restore_delivery_staged(
    job: dict,
    project_dir: str,
    pending: dict,
) -> list[dict]:
    artifacts = pending.get("artifacts") or []
    work_names = pending.get("work_basenames") or []
    if len(artifacts) != len(work_names):
        raise QueueRecoveryRuntimeError("Protected delivery evidence is incomplete.")
    staged = []
    for descriptor, work_name in zip(artifacts, work_names):
        if not validate_protected_artifact_descriptor(
            project_dir,
            descriptor,
            producer_unit_id=str(pending.get("unit_id") or ""),
        ):
            raise QueueRecoveryRuntimeError("Protected delivery native no longer matches.")
        original = str(descriptor.get("original_basename") or "")
        if (
            os.path.basename(original) != original
            or original.startswith(".")
            or os.path.basename(str(work_name)) != work_name
            or not str(work_name).startswith(".maestro-delivery-")
        ):
            raise QueueRecoveryRuntimeError("Protected delivery identity is invalid.")
        stem = os.path.splitext(original)[0]
        staged.append({
            "file_name": original,
            "source_path": os.path.join(project_dir, original),
            "source_meta": os.path.join(project_dir, stem + ".meta.json"),
            "native_path": os.path.join(project_dir, descriptor["basename"]),
            "native_meta": os.path.join(project_dir, descriptor["sidecar_basename"]),
            "work_path": os.path.join(project_dir, work_name),
            "work_basename": work_name,
            "rollback_meta": os.path.join(project_dir, work_name + ".rollback.meta.json"),
            "recovery_descriptor": dict(descriptor),
        })
    job["_h3_delivery_native"] = staged
    return staged


def _queue_recovery_checkpoint_delivery_completed(
    job: dict,
    project_dir: str,
    file_names: list[str],
    pending: dict,
) -> dict:
    """Seal final delivery sidecars, then journal the completed delivery unit."""
    unit_id = str(pending.get("unit_id") or "")
    for file_name in file_names:
        media_path = os.path.join(project_dir, file_name)
        meta_path = os.path.join(
            project_dir, os.path.splitext(file_name)[0] + ".meta.json",
        )
        media_size, media_sha256 = _recovery_sha256_file(media_path)
        try:
            with open(meta_path, "r", encoding="utf-8") as handle:
                sidecar = json.load(handle)
        except (OSError, ValueError, TypeError) as error:
            raise QueueRecoveryRuntimeError(
                "Completed delivery sidecar is unavailable."
            ) from error
        if not isinstance(sidecar, dict):
            raise QueueRecoveryRuntimeError("Completed delivery sidecar is invalid.")
        sidecar.update({
            "producer_artifact_class": "final",
            "artifact_class": "final",
            "producer_unit_artifact_names": sorted(file_names),
            "producer_unit_id": unit_id,
            "producer_unit_kind": "h3_delivery",
            "producer_unit_variant": 0,
            "producer_unit_index": 0,
            "producer_unit_dependencies": list(
                pending.get("dependencies") or []
            ),
            "producer_unit_settings": dict(pending.get("settings") or {}),
            "producer_media_sha256": media_sha256,
            "producer_media_size": media_size,
        })
        _atomic_write_json(meta_path, sidecar)
    unit = _queue_recovery_checkpoint_unit(
        job,
        kind="h3_delivery",
        variant=0,
        index=0,
        project_dir=project_dir,
        artifact_names=file_names,
        dependencies=list(pending.get("dependencies") or []),
        settings=dict(pending.get("settings") or {}),
    )
    if unit.get("unit_id") != unit_id:
        raise QueueRecoveryRuntimeError("Completed delivery identity changed.")
    return unit


def _require_project_access(request: Request, workspace: str) -> str:
    """Return the contained workspace dir or reject a locked project."""
    remote = bool(getattr(request.state, "maestro_remote", False))
    workspace_dir = (
        _existing_workspace_dir(workspace) if remote else _workspace_dir(workspace)
    )
    status = _project_access.status(
        workspace, workspace_dir, request.state.maestro_session_id,
    )
    if remote and not status.protected:
        raise HTTPException(
            status_code=423,
            detail="Remote access requires a password-protected project",
        )
    if not status.unlocked:
        raise HTTPException(status_code=423, detail="Project is password locked")
    return workspace_dir


def _request_project_workspace(request: Request, workspace: str | None) -> str:
    """Resolve a project scope without remote fallback to host-global state."""
    selected = str(workspace or "")
    if bool(getattr(request.state, "maestro_remote", False)) and not selected:
        raise HTTPException(
            status_code=400,
            detail="workspace is required for remote project access",
        )
    return selected or _get_active_workspace()


def _require_authorized_output(
    request: Request,
    workspace: str,
    name: str,
) -> tuple[str, str, dict | None]:
    """Resolve one direct-child output after project + session checks."""
    from services.win_safe_files import (
        is_safe_direct_basename,
        safe_direct_file_under,
    )
    if not is_safe_direct_basename(name) or name.startswith("."):
        raise HTTPException(status_code=400, detail="Invalid output name")
    out_dir = _require_project_access(request, workspace)
    filepath = safe_direct_file_under(out_dir, name)
    if not filepath or not os.path.isfile(filepath):
        raise HTTPException(status_code=404, detail="Output file not found")
    sidecar = load_media_sidecars(out_dir, {name}).get(name)
    expected_sidecar = safe_direct_file_under(
        out_dir, os.path.splitext(name)[0] + ".meta.json",
    )
    if expected_sidecar and os.path.isfile(expected_sidecar) and sidecar is None:
        # A present-but-malformed or ambiguous sidecar is evidence that this
        # is managed output, not a legacy sidecarless file. Fail closed.
        raise HTTPException(status_code=404, detail="Output file not found")
    if not can_access_output(sidecar, request.state.maestro_session_id):
        raise HTTPException(status_code=404, detail="Output file not found")
    return out_dir, filepath, sidecar


def _redact_local_paths(value):
    """Remove host directory disclosure from output-facing JSON shapes."""
    if isinstance(value, dict):
        return {
            key: _redact_local_paths(nested)
            for key, nested in value.items()
            if key not in {"owner_session_id", "_maestro_session_id", "_maestro_access_policy"}
        }
    if isinstance(value, list):
        return [_redact_local_paths(item) for item in value]
    if isinstance(value, tuple):
        return [_redact_local_paths(item) for item in value]
    if isinstance(value, str) and (
        os.path.isabs(value) or PureWindowsPath(value).is_absolute()
    ):
        return os.path.basename(value.replace("\\", "/"))
    return value


def _stamp_upload_derivatives(value, owner_session_id: str) -> None:
    """Stamp direct upload files returned by an internal media operation."""
    from services.win_safe_files import safe_direct_file_under

    if isinstance(value, dict):
        for nested in value.values():
            _stamp_upload_derivatives(nested, owner_session_id)
        return
    if isinstance(value, (list, tuple, set)):
        for nested in value:
            _stamp_upload_derivatives(nested, owner_session_id)
        return
    if not isinstance(value, str) or not value or "\x00" in value:
        return
    absolute = os.path.abspath(value)
    name = os.path.basename(absolute)
    if name.startswith("."):
        return
    for root in (
        os.path.join(os.getcwd(), "uploads"),
        os.path.join(os.getcwd(), "uploads", "audio"),
    ):
        candidate = safe_direct_file_under(root, name)
        if candidate == absolute and os.path.isfile(candidate):
            # Recursive operation results can also echo an original source.
            # Never change an existing upload's deliberate owner/visibility.
            try:
                if read_upload_access_sidecar(candidate) is not None:
                    return
            except ValueError:
                return
            write_upload_access_sidecar(
                candidate,
                owner_session_id,
                private=True,
            )
            return


def _stamp_job_output_access(job: dict) -> None:
    """Apply one job's access policy to every published sidecar."""
    policy = job.get("access_policy")
    if not isinstance(policy, dict):
        return
    out_dir = job.get("out_dir")
    if not isinstance(out_dir, str) or not os.path.isdir(out_dir):
        return
    job_id = str(job.get("id") or "")
    output_names = set(job.get("output_files") or [])
    try:
        candidates = [name for name in os.listdir(out_dir) if name.endswith(".meta.json")]
    except OSError:
        return
    for sidecar_name in candidates:
        path = _safe_join(out_dir, sidecar_name)
        if path is None or not os.path.isfile(path):
            continue
        media_stem = sidecar_name[:-len(".meta.json")]
        try:
            with open(path, "r", encoding="utf-8") as handle:
                meta = json.load(handle)
            output_filename = str(meta.get("output_filename") or "")
            if meta.get("job_id") != job_id and not (
                output_filename in output_names
                or any(os.path.splitext(name)[0] == media_stem for name in output_names)
            ):
                continue
            stamp_sidecar_policy(
                meta, policy,
                workspace=str(job.get("workspace") or "default"),
            )
            temp = f"{path}.{uuid.uuid4().hex[:8]}.tmp"
            with open(temp, "w", encoding="utf-8") as handle:
                json.dump(meta, handle, indent=2)
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(temp, path)
        except (OSError, ValueError, TypeError):
            continue


_lifecycle_finish_job = finish_job


def finish_job(job, *args, **kwargs):
    """Lifecycle finish plus producer-parity access metadata stamping."""
    result = _lifecycle_finish_job(job, *args, **kwargs)
    _stamp_job_output_access(job)
    return result


def _workspace_file_count(path: str) -> int:
    """Non-hidden files directly inside a workspace folder (for delete
    confirms). scandir answers is_file() from the enumeration data on
    Windows — no per-entry stat syscall."""
    try:
        with os.scandir(path) as entries:
            return sum(1 for e in entries if not e.name.startswith(".") and e.is_file())
    except OSError:
        return 0


def _list_workspaces() -> list[dict]:
    """List all workspaces (subdirectories of the base output path + default)."""
    base = wgp.server_config.get("save_path", "outputs")
    workspaces = [{"name": "default", "path": base, "file_count": _workspace_file_count(base)}]
    if os.path.isdir(base):
        for name in sorted(os.listdir(base)):
            full = os.path.join(base, name)
            if os.path.isdir(full) and not name.startswith(("_", ".")):
                workspaces.append({"name": name, "path": full, "file_count": _workspace_file_count(full)})
    return workspaces


def _persist_active_workspace(name: str, apply_save_paths: bool = True) -> str:
    """Write services.active_workspace to config and (optionally) point
    wgp's save paths at it. Pass apply_save_paths=False while a generation
    is running — the in-flight job has locked wgp.save_path to its target
    and the new value takes effect on the next job / restart."""
    services = wgp.server_config.setdefault("services", {})
    services["active_workspace"] = name
    wgp.server_config["services"] = services
    with open(wgp.server_config_filename, "w", encoding="utf-8") as f:
        f.write(json.dumps(wgp.server_config, indent=4))
    ws_dir = _workspace_dir(name)
    if apply_save_paths:
        wgp.save_path = ws_dir
        wgp.image_save_path = ws_dir
    return ws_dir

# --- Director pipeline (lazy init after _run_generation is defined) ---
_pipeline_initialized = False


def _init_pipeline():
    global _pipeline_initialized
    if not _pipeline_initialized:
        from services.director_pipeline import init as pipeline_init
        pipeline_init(
            _jobs, _run_generation, wgp, _gen_lock, _active_gen_states,
            recovery_register_parent=_director_recovery_register_parent,
            recovery_prepare_parent_state=(
                _director_recovery_prepare_parent_state
            ),
            recovery_checkpoint_parent=_director_recovery_checkpoint_parent,
            recovery_prepare_parent_delete=(
                _director_recovery_prepare_parent_delete
            ),
            recovery_remove_parent=_director_recovery_remove_parent,
            recovery_submit_child=_director_recovery_submit_child,
            recovery_verify_child=_director_recovery_verified_child,
            recovery_validate_child=_director_recovery_validate_child,
        )
        _pipeline_initialized = True


# ============================================================================
# API Routes: /api/v1/*
# ============================================================================

def _variant_group_filenames(urls) -> list:
    """Flatten one weight group (list of variant URLs / dict entries) to file names."""
    names = []
    for url_entry in urls:
        url_str = url_entry
        if isinstance(url_entry, dict):
            inner = url_entry.get("URLs", url_entry.get("url", []))
            url_str = inner[0] if isinstance(inner, list) and inner else (inner if isinstance(inner, str) else "")
        if not isinstance(url_str, str) or not url_str:
            continue
        names.append(url_str.rstrip("/").split("/")[-1])
    return names


def _variant_group_downloaded(urls, *, extra_paths=None) -> bool:
    """True when ANY variant (full bf16 vs quantized int8...) of one weight
    group exists locally. Resolves through the files locator so checkpoints
    in linked model folders (Settings -> System -> Linked Model Folders)
    light up too — a hardcoded ckpts_dir check misses every secondary root."""
    for filename in _variant_group_filenames(urls):
        if wgp.get_local_model_filename(
            filename, extra_paths=extra_paths,
        ) is not None:
            return True
    return False


def _model_weight_groups(model_type: str, owned_only: bool = False) -> list:
    """All weight groups a model needs on disk: main URLs + weight modules.

    "URLs" may be a string pointer to another model type (finetunes such as
    z_image_control or scail2_14B_fast use "URLs": "<base_model>"). Resolve
    recursively like the engine does — iterating the raw value would walk
    the characters of the string and permanently report not-downloaded.

    owned_only=True returns only groups this entry itself declares (skips a
    string-pointer base). Used by delete: removing a finetune must not pull
    the shared base transformer out from under its sibling entries — the
    base is deleted from the base model's own row instead.

    String-named modules resolve through the engine's module registry and
    are intentionally left out (they were never counted here).
    """
    md = wgp.get_model_def(model_type) or {}
    groups = []
    raw_urls = md.get("URLs", None)
    if isinstance(raw_urls, str):
        if not owned_only:
            urls = wgp.get_model_recursive_prop(model_type, "URLs", return_list=True)
            if urls:
                groups.append(urls)
    elif raw_urls:
        groups.append(raw_urls)
    for module in md.get("modules", []):
        if isinstance(module, list):
            groups.append(module)
        elif isinstance(module, dict):
            group = module.get("URLs", [])
            if group:
                groups.append(group)
    return groups


def _check_model_downloaded(model_type: str) -> bool:
    """Check if a model's checkpoint files are downloaded.

    Models often list multiple URLs (e.g. full bf16 + quantized int8) per
    weight group; ONE variant per group is enough. Every group (main
    transformer + each weight module) must be present.
    """
    try:
        model_def = wgp.get_model_def(model_type)
        if model_def is None:
            return False
        groups = _model_weight_groups(model_type)
        if not groups:
            return False
        if not all(_variant_group_downloaded(g) for g in groups):
            return False
        text_encoder_urls = wgp.get_model_recursive_prop(
            model_type, "text_encoder_URLs", return_list=True,
        )
        if text_encoder_urls and not _variant_group_downloaded(
            text_encoder_urls,
            extra_paths=model_def.get("text_encoder_folder"),
        ):
            return False
        # Some edit pipelines split required conditioning weights out of the
        # main transformer/text-encoder groups. Krea 2 Edit cannot run without
        # its Qwen3-VL vision tower, so do not report it as ready until that
        # preloaded companion file is actually discoverable (including through
        # linked checkpoint roots).
        vision_encoder_filename = model_def.get("vision_encoder_filename")
        if (
            vision_encoder_filename
            and wgp.fl.locate_file(vision_encoder_filename, error_if_none=False) is None
        ):
            return False
        # Def-bundled accelerator loras (e.g. SCAIL-2 Fast's lightx2v
        # distill) are loaded unconditionally at generation time, so they
        # count toward readiness too. resolve_lora_path searches linked
        # read-only roots like the generation path does.
        for url in wgp.get_model_recursive_prop(model_type, "loras", return_list=True):
            if not os.path.isfile(wgp.resolve_lora_path(model_type, url.split("/")[-1])):
                return False
        return True
    except Exception:
        return False


def _remote_visible_model_ids(request: Request) -> frozenset[str] | None:
    """Return the persisted remote catalog, or ``None`` for local callers.

    The browser selector is not an authorization boundary.  Cloudflare
    callers may use only the owner-persisted model whitelist; missing or
    malformed persisted state is deliberately an empty remote catalog.
    """
    if not bool(getattr(request.state, "maestro_remote", False)):
        return None
    visibility = _model_visibility_response()
    if not visibility.get("configured"):
        return frozenset()
    return frozenset(visibility.get("enabled_models") or ())


def _require_remote_visible_models(request: Request, model_types) -> None:
    allowed = _remote_visible_model_ids(request)
    if allowed is None:
        return
    requested = {
        str(model_type).strip()
        for model_type in (model_types or ())
        if str(model_type).strip()
    }
    if any(model_type not in allowed for model_type in requested):
        # Hidden and unknown identifiers are intentionally indistinguishable.
        raise HTTPException(status_code=404, detail="Model not found")


def _require_remote_visible_job_models(job: dict) -> None:
    """Fail closed if a remote-origin job could load a hidden checkpoint."""
    if not bool(job.get("source_remote")):
        return
    visibility = _model_visibility_response()
    allowed = (
        set(visibility.get("enabled_models") or ())
        if visibility.get("configured") else set()
    )
    params = job.get("params") if isinstance(job.get("params"), dict) else {}
    requested = {
        str(value).strip()
        for value in (
            job.get("model_type"), params.get("model_type"),
            params.get("video_model"), params.get("image_model"),
        )
        if str(value or "").strip()
    }
    longform = params.get("_h3_longform")
    if isinstance(longform, dict):
        for segment in longform.get("segment_models") or ():
            value = segment.get("model_type") if isinstance(segment, dict) else segment
            if str(value or "").strip():
                requested.add(str(value).strip())
    if any(model_type not in allowed for model_type in requested):
        raise HTTPException(status_code=404, detail="Model not found")


@api.get("/api/v1/models")
def list_models(request: Request):
    """List available model families and model types."""
    from services.director_model_compat import assess_director_model

    remote_visible = _remote_visible_model_ids(request)

    # Models
    models = []
    for mt in wgp.displayed_model_types:
        if remote_visible is not None and mt not in remote_visible:
            continue
        md = wgp.get_model_def(mt)
        if md is None:
            continue
        _versioned_model_updater.apply_recorded(mt, md)
        _versioned_model_updater.apply_recorded_components(mt, md)
        family = wgp.get_model_family(mt, for_ui=True)
        architecture = wgp.get_base_model_type(mt)
        try:
            director = assess_director_model(
                mt,
                md,
                family=family,
                architecture=architecture,
            )
        except Exception:
            # A malformed optional model definition must not take down the
            # catalog or expose its internal value through the response.
            director = assess_director_model(
                mt,
                None,
                family=family,
                architecture=architecture,
            )
        models.append({
            "model_type": mt,
            "name": md.get("name", mt),
            "description": md.get("description"),
            "selector_help": md.get("selector_help"),
            "lora_compatibility_note": md.get("lora_compatibility_note"),
            "family": family,
            "architecture": architecture,
            "is_i2v": wgp.test_class_i2v(mt),
            "is_t2v": wgp.test_class_t2v(mt),
            "guidance_max_phases": md.get("guidance_max_phases", 1),
            "fps": md.get("fps", 16),
            "supports_end_frame": "E" in md.get("image_prompt_types_allowed", ""),
            "supports_audio": bool(md.get("any_audio_prompt", False) or md.get("returns_audio", False)),
            "supports_audio_input": bool(md.get("any_audio_prompt", False)),
            "generates_audio": bool(md.get("returns_audio", False)),
            "supports_ref_images": bool(md.get("image_ref_choices")),
            "director": director,
            "is_downloaded": _check_model_downloaded(mt),
            # When True, the UI hides this model unless Mature Mode is
            # enabled. Set in the model JSON's "model" block (e.g.
            # defaults/ltx2_22B_10eros.json). The backend ALWAYS returns
            # the entry — visibility gating happens client-side so a single
            # nsfw_mode toggle can show/hide without reloading models.
            "nsfw_only": bool(md.get("nsfw_only", False)),
            "preferred_explicit_fl2va": bool(md.get("preferred_explicit_fl2va", False)),
            "update_status": str(_versioned_model_update_status.get(mt, {}).get("status") or (
                "versioned" if isinstance(md.get("model_update"), dict) else "pinned"
            )),
        })

    visible_families = {model["family"] for model in models}
    families = []
    for fid, (order, label) in wgp.families_infos.items():
        if fid == "unknown" or (
            remote_visible is not None and fid not in visible_families
        ):
            continue
        families.append({"id": fid, "label": label, "order": order})
    families.sort(key=lambda family: family["order"])
    return {"families": families, "models": models}


_MODEL_VISIBILITY_CONFIG_KEY = "maestro_model_visibility"
_MODEL_VISIBILITY_WRITE_LOCK = threading.RLock()


def _normalize_model_visibility_ids(values):
    """Return a stable, de-duplicated list of persisted model identifiers."""
    if not isinstance(values, list):
        raise ValueError("Model visibility must be a list.")
    normalized = []
    seen = set()
    for value in values:
        if not isinstance(value, str):
            raise ValueError("Model visibility entries must be strings.")
        model_type = value.strip()
        if not model_type or model_type in seen:
            continue
        if len(model_type) > 200:
            raise ValueError("A model identifier is too long.")
        seen.add(model_type)
        normalized.append(model_type)
    if len(normalized) > 5000:
        raise ValueError("Too many model visibility entries.")
    return normalized


def _model_visibility_response():
    raw = wgp.server_config.get(_MODEL_VISIBILITY_CONFIG_KEY)
    configured = isinstance(raw, dict) and isinstance(
        raw.get("enabled_models"), list,
    )
    if not configured:
        return {
            "configured": False,
            "enabled_models": [],
            "initialized_mature_models": [],
            "defaults_version": 0,
        }
    try:
        enabled_models = _normalize_model_visibility_ids(
            raw.get("enabled_models", []),
        )
        initialized_mature_models = _normalize_model_visibility_ids(
            raw.get("initialized_mature_models", []),
        )
    except ValueError:
        return {
            "configured": False,
            "enabled_models": [],
            "initialized_mature_models": [],
            "defaults_version": 0,
        }
    try:
        defaults_version = max(0, int(raw.get("defaults_version", 0)))
    except (TypeError, ValueError):
        defaults_version = 0
    return {
        "configured": True,
        "enabled_models": enabled_models,
        "initialized_mature_models": initialized_mature_models,
        "defaults_version": defaults_version,
    }


def _persist_model_visibility_config():
    """Atomically persist visibility across Pinokio's changing UI ports."""
    config_path = os.path.abspath(wgp.server_config_filename)
    temp_path = (
        f"{config_path}.{os.getpid()}.{threading.get_ident()}.tmp"
    )
    with _MODEL_VISIBILITY_WRITE_LOCK:
        try:
            with open(temp_path, "w", encoding="utf-8") as handle:
                json.dump(wgp.server_config, handle, indent=4)
            os.replace(temp_path, config_path)
        finally:
            if os.path.isfile(temp_path):
                try:
                    os.remove(temp_path)
                except OSError:
                    pass


@api.get("/api/v1/model-visibility")
def get_model_visibility(request: Request):
    """Return the server-persisted model selector whitelist."""
    response = _model_visibility_response()
    if not bool(getattr(request.state, "maestro_remote", False)):
        return response
    return {**response, "initialized_mature_models": []}


@api.put("/api/v1/model-visibility")
async def update_model_visibility(request: Request):
    """Persist model visibility independently of the browser's origin."""
    body = await request.json()
    if not isinstance(body, dict):
        raise HTTPException(
            status_code=400,
            detail="Model visibility payload must be an object.",
        )
    try:
        enabled_models = _normalize_model_visibility_ids(
            body.get("enabled_models"),
        )
        initialized_mature_models = _normalize_model_visibility_ids(
            body.get("initialized_mature_models", []),
        )
    except ValueError as error:
        raise HTTPException(status_code=400, detail=str(error)) from error
    try:
        defaults_version = max(0, int(body.get("defaults_version", 0)))
    except (TypeError, ValueError) as error:
        raise HTTPException(
            status_code=400,
            detail="defaults_version must be an integer.",
        ) from error

    with _MODEL_VISIBILITY_WRITE_LOCK:
        wgp.server_config[_MODEL_VISIBILITY_CONFIG_KEY] = {
            "enabled_models": enabled_models,
            "initialized_mature_models": initialized_mature_models,
            "defaults_version": defaults_version,
        }
        _persist_model_visibility_config()
        return _model_visibility_response()


@api.get("/api/v1/models/{model_type}/debug")
def debug_model(model_type: str):
    """Debug: show raw model definition and download check."""
    md = wgp.get_model_def(model_type)
    if not md:
        return {"error": "Model not found"}
    # Collect keys and sample values (avoid huge nested objects)
    keys_info = {}
    for k, v in md.items():
        if isinstance(v, (str, int, float, bool)):
            keys_info[k] = v
        elif isinstance(v, list):
            keys_info[k] = f"[list len={len(v)}] {str(v[:2])[:200]}"
        elif isinstance(v, dict):
            keys_info[k] = f"[dict keys={list(v.keys())[:10]}]"
        else:
            keys_info[k] = f"[{type(v).__name__}]"
    return {
        "model_type": model_type,
        "keys": keys_info,
        "is_downloaded": _check_model_downloaded(model_type),
        "ckpts_dir": wgp.fl.get_download_location() if hasattr(wgp.fl, 'get_download_location') else "unknown",
    }


@api.delete("/api/v1/models/{model_type}")
def delete_model(model_type: str):
    """Delete a model's checkpoint files from disk."""
    md = wgp.get_model_def(model_type)
    if not md:
        return JSONResponse({"error": "Model not found"}, status_code=404)

    # Same group resolution as _check_model_downloaded, restricted to files
    # this entry owns — a finetune's delete removes its modules but leaves a
    # shared base transformer for the base model's own delete button.
    filenames = []
    for group in _model_weight_groups(model_type, owned_only=True):
        filenames.extend(_variant_group_filenames(group))
    deleted = []
    skipped_linked = []
    errors = []
    for filename in filenames:
        filepath = wgp.fl.locate_file(filename, error_if_none=False)
        if filepath and os.path.isfile(filepath):
            # locate_file also finds checkpoints in linked (read-only) model
            # folders — deleting those would break the OTHER install. Skip
            # them and tell the UI why the model still shows as available.
            if wgp.fl.is_protected_path(filepath):
                skipped_linked.append(filename)
                print(f"[Models] Skipped delete of linked checkpoint: {filepath}")
                continue
            try:
                os.remove(filepath)
                deleted.append(filename)
                print(f"[Models] Deleted checkpoint: {filepath}")
            except Exception as e:
                errors.append(f"{filename}: {e}")
    if errors:
        return JSONResponse({"deleted": deleted, "skipped_linked": skipped_linked, "errors": errors}, status_code=207)
    return {"deleted": deleted, "skipped_linked": skipped_linked, "model_type": model_type}


# ── Model pre-download ──────────────────────────────────────────────────
# Backs the click-to-download icon in Settings → System → Enabled Models.
# Fetches everything a generation would need (transformer + second-stage +
# modules + shared assets + text encoder) without occupying the GPU, so
# the first generation starts instantly. Progress reaches the UI through
# the existing /api/v1/downloads/active feed (safe_download's tqdm hook).
_model_downloads: dict = {}
_model_downloads_lock = threading.Lock()


def _download_model_files(model_type: str):
    """Resolve and fetch every file load_models() would download.

    Mirrors the file-resolution block at the top of wgp.load_models()
    (wgp.py:4041-4143) — keep the two in sync.
    """
    model_def = wgp.get_model_def(model_type)
    update_result = _ensure_versioned_model_current(model_type, force=True)
    quantization = wgp.transformer_quantization
    dtype_policy = wgp.transformer_dtype_policy
    transformer_dtype = wgp.get_transformer_dtype(model_type, dtype_policy)

    model_file_list = [wgp.get_model_filename(model_type=model_type, quantization=quantization, dtype_policy=dtype_policy)]
    source_type_list = [0]
    submodel_no_list = [1]
    if "URLs2" in model_def:
        model_file_list.append(wgp.get_model_filename(model_type=model_type, quantization=quantization, dtype_policy=dtype_policy, submodel_no=2))
        source_type_list.append(0)
        submodel_no_list.append(2)
    modules = wgp.get_model_recursive_prop(model_type, "modules", return_list=True)
    modules = [wgp.get_model_recursive_prop(module, "modules", sub_prop_name="_list", return_list=True) if isinstance(module, str) else module for module in modules]
    for module_type in modules:
        if isinstance(module_type, dict):
            for urls_key, submodel_no in (("URLs", 1), ("URLs2", 2)):
                urls = module_type.get(urls_key, None)
                if urls is None:
                    raise Exception(f"No {urls_key} defined for Module {module_type}")
                model_file_list.append(wgp.get_model_filename(model_type, quantization, transformer_dtype, URLs=urls))
                source_type_list.append(1)
                submodel_no_list.append(submodel_no)
        else:
            model_file_list.append(wgp.get_model_filename(model_type, quantization, transformer_dtype, module_type=module_type))
            source_type_list.append(1)
            submodel_no_list.append(0)

    for filename, source_type, submodel_no in zip(model_file_list, source_type_list, submodel_no_list):
        if len(filename) == 0:
            continue
        wgp.download_models(filename, model_type, source_type, submodel_no)

    text_encoder_URLs = wgp.get_model_recursive_prop(model_type, "text_encoder_URLs", return_list=True)
    if text_encoder_URLs is not None:
        te_quant = (model_def.get("text_encoder_quantization", None) if model_def else None) or wgp.text_encoder_quantization
        text_encoder_filename = wgp.get_model_filename(model_type=model_type, quantization=te_quant, dtype_policy=dtype_policy, URLs=text_encoder_URLs)
        if text_encoder_filename is not None and len(text_encoder_filename):
            text_encoder_folder = model_def.get("text_encoder_folder", None)
            wgp.download_models(text_encoder_filename, model_type, 2, -1, force_path=text_encoder_folder)
            if wgp.get_local_model_filename(text_encoder_filename, extra_paths=text_encoder_folder) is None:
                raise Exception(f"Text encoder '{os.path.basename(text_encoder_filename)}' could not be located after download.")

    if not _check_model_downloaded(model_type):
        raise Exception("Download finished but the checkpoint could not be located — check disk space and earlier terminal output.")
    _versioned_model_updater.finalize_download(
        model_type,
        model_def,
        update_result.get("candidate") if isinstance(update_result, dict) else None,
    )
    component_candidates = {
        component_id: value.get("candidate")
        for component_id, value in (update_result.get("components") or {}).items()
        if isinstance(value, dict) and isinstance(value.get("candidate"), dict)
    }
    _versioned_model_updater.finalize_component_downloads(
        model_type, model_def, component_candidates,
    )


@api.post("/api/v1/models/{model_type}/download")
def download_model(model_type: str, request: Request):
    """Start downloading a model's files in the background."""
    _require_remote_visible_models(request, [model_type])
    md = wgp.get_model_def(model_type)
    if not md:
        return JSONResponse({"error": "Model not found"}, status_code=404)
    with _model_downloads_lock:
        entry = _model_downloads.get(model_type)
        if entry and entry["status"] == "downloading":
            return {"status": "downloading", "model_type": model_type}
        _model_downloads[model_type] = {"status": "downloading", "error": None, "started": time.time()}

    def _worker():
        try:
            _download_model_files(model_type)
            _model_downloads[model_type] = {"status": "completed", "error": None, "started": _model_downloads[model_type]["started"]}
            print(f"[Models] Pre-download complete: {model_type}")
        except Exception as e:
            traceback.print_exc()
            _model_downloads[model_type] = {"status": "failed", "error": str(e), "started": _model_downloads[model_type]["started"]}
            print(f"[Models] Pre-download FAILED for {model_type}: {e}")

    threading.Thread(target=_worker, daemon=True, name=f"model-dl-{model_type}").start()
    return {"status": "downloading", "model_type": model_type}


@api.get("/api/v1/models/downloads/status")
def model_downloads_status(request: Request):
    """Status of model pre-downloads started via POST .../download."""
    remote_visible = _remote_visible_model_ids(request)
    with _model_downloads_lock:
        snapshot = {
            model_type: {
                "status": entry["status"],
                "error": (
                    "Model download failed"
                    if remote_visible is not None and entry.get("error")
                    else entry.get("error")
                ),
            }
            for model_type, entry in _model_downloads.items()
            if remote_visible is None or model_type in remote_visible
        }
    return {"downloads": snapshot}


