@api.get("/api/v1/loras/directories")
def list_lora_directories():
    """Return all available LoRA directories for target selection during download."""
    lora_root = wgp.server_config.get("loras_root", "loras") if hasattr(wgp, 'server_config') else "loras"
    candidates = [lora_root]
    if not os.path.isabs(lora_root):
        candidates.append(os.path.join(os.path.dirname(__file__), lora_root))
        candidates.append(os.path.join(os.getcwd(), lora_root))
    resolved = None
    for c in candidates:
        if os.path.isdir(c):
            resolved = c
            break
    if not resolved:
        return {"directories": []}
    dirs = sorted([
        d for d in os.listdir(resolved)
        if os.path.isdir(os.path.join(resolved, d)) and not d.startswith(".")
    ])
    return {"directories": dirs}


@api.get("/api/v1/loras/preview/{filename}")
def serve_lora_preview(filename: str):
    """Serve a locally downloaded LoRA preview file (video or image)."""
    # Reject any traversal markers up front; only basenames are valid here.
    if filename != os.path.basename(filename) or filename.startswith("."):
        raise HTTPException(status_code=400, detail="Invalid filename")
    lora_root = wgp.server_config.get("loras_root", "loras") if hasattr(wgp, 'server_config') else "loras"
    app_dir = os.path.dirname(os.path.abspath(__file__))
    base = os.path.join(app_dir, lora_root)
    # Search all subdirectories for the preview file
    for dirpath, _, files in os.walk(base):
        if filename in files:
            filepath = _safe_join(base, os.path.relpath(dirpath, base), filename)
            if filepath is None:
                continue
            media_type = "video/mp4" if filename.endswith(".mp4") else "image/png"
            from services.win_safe_files import share_delete_file_response
            return share_delete_file_response(filepath, media_type=media_type)
    return JSONResponse({"error": "Preview not found"}, status_code=404)


# ── Stable LoRA identifier ───────────────────────────────────────────
# A `lora_id` is a stable identifier that survives version updates.
# Anything keyed off a LoRA in persisted state (activations, weights,
# NSFW stash, etc.) should use this instead of the filename so that
# updating from v1.2 → v1.5 carries those settings forward automatically.
#
#   civitai:{modelId}   - LoRA from CivitAI (any version of the same model)
#   local:{filename}    - locally-trained / hand-installed (no sidecar)
#
# The version is tracked separately in the update manifest, NOT here.
def _compute_lora_id(filename: str, sidecar_meta: dict | None) -> str:
    """Return the stable lora_id for a LoRA file.

    Always prefer `civitai:{modelId}` when the sidecar exposes one so
    that swapping a v1.2 file for v1.5 (different filename, same model)
    keeps the same identifier. Falls back to `local:{filename}` otherwise,
    which is the right behavior for hand-trained or hand-installed LoRAs.
    """
    if isinstance(sidecar_meta, dict):
        model_id = sidecar_meta.get("modelId")
        if model_id is not None:
            try:
                return f"civitai:{int(model_id)}"
            except (TypeError, ValueError):
                # Some sidecars store modelId as a string; pass through.
                return f"civitai:{model_id}"
    return f"local:{filename}"


# ── NSFW LoRA classification ─────────────────────────────────────────
# Used by /api/v1/loras/installed and /api/v1/loras/{model_type}/details.
# Always called as a fallback after checking the CivitAI sidecar's `nsfw`
# boolean — sidecar-true wins; this only fires when the sidecar didn't
# flag it (or the LoRA has no sidecar at all, which is the case for
# anything downloaded outside our CivitAI integration).
#
# Two design choices to limit false positives:
#
#   1. Word-boundary matching, not substring. So "anal" matches "anal"
#      but not "ANALysis"; "oral" matches "oral" but not "mORAL"; "sex"
#      matches "sex" but not "susSEX". Substring matching previously
#      caused real-world FPs (e.g. an LTX-2.3 enhancement LoRA whose
#      guide mentioned "explicit text overlays" was flagged because
#      "explicit" appeared anywhere in the text).
#
#   2. Curated keyword list. Words too ambiguous for context-free
#      matching (e.g. "explicit", "adult", "mature") are deliberately
#      EXCLUDED — they show up too often in SFW contexts. Words that
#      are unambiguous in any reasonable context stay.
#
# Filenames and tags often use `_` or `-` as separators; Python's `\b`
# treats `_` as a word char, so we normalize those to spaces before
# matching. This lets `\bboob\b` correctly match "Big_Boobs_LoRA" when
# the filename is normalized to "Big Boobs LoRA".
import re as _re_nsfw
from functools import lru_cache as _lru_cache_nsfw

# NSFW LoRA-classification keyword fallback — flags a LoRA as mature when a
# keyword appears as a whole word in its name / tags / description, used only
# when the CivitAI sidecar doesn't already flag it. Category-level terms only
# (the two most explicit terms from the original list are dropped to
# keep tracked source clean). `\b` word boundaries prevent false hits like
# "oral"->"moral", "breast"->"breastfeeding", "sex"->"Sussex" (filenames are
# normalized `_`/`-` -> space before matching; see _NSFW_NORMALIZE_RE).
_NSFW_LORA_KEYWORDS = [
    "nsfw", "nude", "naked", "sex", "breast", "oral",
    "doggy", "xxx", "porn", "hentai", "uncensored", "unchained",
]


@_lru_cache_nsfw(maxsize=1)
def _get_nsfw_regex() -> "_re_nsfw.Pattern[str]":
    """Compiled word-boundary regex over the NSFW LoRA keyword fallback."""
    return _re_nsfw.compile(
        r"\b(?:" + "|".join(_re_nsfw.escape(k) for k in _NSFW_LORA_KEYWORDS) + r")\b",
        _re_nsfw.IGNORECASE,
    )


# Normalize filename separators to spaces so word boundaries work
# inside underscore/dash-joined identifiers.
_NSFW_NORMALIZE_RE = _re_nsfw.compile(r"[_\-]")

def _classify_lora_nsfw(
    filename: str,
    display_name: str | None = None,
    sidecar_meta: dict | None = None,
    guide_text: str | None = None,
) -> bool:
    """Return True if any NSFW keyword appears as a whole word anywhere
    across the LoRA's text metadata. Checks:
      - filename (with `_`/`-` normalized to spaces so word boundaries
        catch tokens inside identifiers like `Big_Boobs_LoRA`)
      - display name (CivitAI sidecar's `name`)
      - sidecar tags
      - sidecar description + versionDescription
      - generated `.guide.md` content
    """
    blobs: list[str] = []
    blobs.append(filename or "")
    if display_name:
        blobs.append(str(display_name))
    if isinstance(sidecar_meta, dict):
        tags = sidecar_meta.get("tags") or []
        if isinstance(tags, list):
            blobs.append(" ".join(str(t) for t in tags))
        for key in ("description", "versionDescription"):
            val = sidecar_meta.get(key)
            if isinstance(val, str):
                blobs.append(val)
    if guide_text:
        blobs.append(str(guide_text))
    haystack = _NSFW_NORMALIZE_RE.sub(" ", " ".join(blobs))
    return _get_nsfw_regex().search(haystack) is not None


# ── System-managed LoRA detection ────────────────────────────────────
# Some LoRAs in the user's loras folder are auto-downloaded by the
# launcher itself (model-loading code, blend mode, edit anything, etc.)
# rather than manually installed. They:
#   - are tied to specific model versions (the model loader expects them)
#   - shouldn't be "updated" through the LoRA browser — that's the model
#     update flow's job, and a mismatch can break inference outright
#   - happen to be uploaded to CivitAI by various people, so a naive
#     versionId comparison flags them as "available" even though there's
#     nothing the user should do about it
#
# Filename patterns are the most reliable discriminator since the
# launcher always uses deterministic filenames sourced from HuggingFace.
import re as _re_sys_lora
_SYSTEM_MANAGED_LORA_PATTERNS = (
    # LTX-2 / LTX-2.3 distilled LoRAs (e.g. ltx-2-19b-distilled-lora-384,
    # ltx-2.3-22b-distilled-lora-384, ltx-2.3-22b-distilled-lora-384-1.1).
    # See app/defaults/ltx2_*.json for the canonical download URLs.
    _re_sys_lora.compile(r"distilled[-_]lora", _re_sys_lora.IGNORECASE),
    # Edit Anything LoRA (Alissonerdx, auto-downloaded by /api/v1/edit-anything).
    _re_sys_lora.compile(r"edit[-_]anything", _re_sys_lora.IGNORECASE),
    # Official SCAIL-2 Relighting LoRA, downloaded and converted on first
    # Recast use. It is pinned to the upstream checkpoint hash below.
    _re_sys_lora.compile(r"scail2[-_]relighting[-_]lora", _re_sys_lora.IGNORECASE),
    # LTX-2.3 Transition LoRA (auto-downloaded by ensureTransitionLoraForBlend).
    _re_sys_lora.compile(r"transition", _re_sys_lora.IGNORECASE),
)


def _is_system_managed_lora(filename: str) -> bool:
    """Return True if `filename` matches a known system-managed LoRA pattern."""
    if not filename:
        return False
    base = os.path.splitext(filename)[0]
    return any(p.search(base) for p in _SYSTEM_MANAGED_LORA_PATTERNS)


# ── video_prompt_type normalization ─────────────────────────────────
# Maestro's video_prompt_type is a string of single-letter mode flags
# the wgp.py pipeline uses to decide what optional inputs are needed
# (e.g. "I" → image_refs required, "V" → video/image guide required).
# wgp.py rejects the job with a friendly UI error if a flag is set but
# the corresponding input is missing.
#
# Without this normalization, stale UI state can leave a flag set after
# its input got cleared — most commonly "I" persisting in localStorage
# after the user removed their reference image, causing every subsequent
# text-to-image gen to fail with "You must provide at least one
# Reference Image". The frontend should already be keeping the flag in
# sync with the inputs, but this defense-in-depth strip lets us recover
# from any UI bug that lets the inconsistent state through.
#
# The set is conservative — only flags where (a) we know the required
# input field name with confidence and (b) the wgp.py validation rejects
# the job rather than silently degrading. Adding too many strips here
# could mask other bugs, so we extend on demand.
_VPT_REQUIRED_INPUTS = {
    # flag → (param key in body, friendly label for log line)
    "I": ("image_refs", "image references"),
}


def _normalize_video_prompt_type(body: dict) -> None:
    """Strip video_prompt_type flags whose required input is missing.

    Mutates `body` in place. No-op when video_prompt_type isn't set or
    when all flags have their inputs.
    """
    vpt = body.get("video_prompt_type")
    if not isinstance(vpt, str) or not vpt:
        return

    new_vpt = vpt
    for flag, (input_key, label) in _VPT_REQUIRED_INPUTS.items():
        if flag not in new_vpt:
            continue
        input_val = body.get(input_key)
        # Treat missing, None, empty string, and empty list as absent.
        is_absent = (
            input_val is None
            or (isinstance(input_val, (list, tuple, str)) and len(input_val) == 0)
        )
        if is_absent:
            new_vpt = new_vpt.replace(flag, "")
            print(
                f"[Generate] Stripped '{flag}' from video_prompt_type "
                f"(no {label} attached) — was {vpt!r}, now {new_vpt!r}"
            )

    if new_vpt != vpt:
        body["video_prompt_type"] = new_vpt


# ── image_prompt_type normalization ──────────────────────────────────
# Sibling to video_prompt_type. wgp's image_prompt_type controls whether
# I2V (image-to-video) start/end frames are expected. When "S" is set
# but no image_start is attached, wgp rejects the job with "You must
# provide a Start Image" instead of falling back to T2V — even though
# Maestro's UX promises "no start image → T2V automatically."
#
# Stale UI state is the usual cause: model defaults, sidecar metadata
# from a previous re-roll, or the user clearing the start-image
# preview after the prompt_type was set. Strip the flag when its
# input is absent so the user gets the T2V fallback they expected.
_IPT_REQUIRED_INPUTS = {
    # flag → (param key in body, friendly label for log line)
    "S": ("image_start", "start image"),
    "E": ("image_end", "end image"),
}

_GENERATION_MEDIA_INPUTS = (
    "image_start", "image_end", "image_refs", "image_guide", "image_mask",
    "video_guide", "video_guide2", "video_guide3", "video_mask",
    "video_source", "video_end", "audio_guide", "audio_guide2",
    "audio_guide3", "audio_guide4", "audio_guide5", "audio_guide6",
    "audio_source", "custom_guide", "voice_reference",
)


def _authorize_generation_media_inputs(
    request: Request,
    body: dict,
    workspace: str,
) -> None:
    """Resolve every HTTP-supplied attachment before generation can probe it."""
    def _resolve(value, field: str):
        if value is None or value == "":
            return value
        if isinstance(value, list):
            return [_resolve(item, field) for item in value]
        if not isinstance(value, str):
            raise HTTPException(
                status_code=400,
                detail=f"{field} must be a media path or list of media paths",
            )
        resolved = _resolve_authorized_request_media(request, value, workspace)
        if not resolved:
            raise HTTPException(status_code=404, detail=f"Unauthorized media: {field}")
        return resolved

    for field in _GENERATION_MEDIA_INPUTS:
        if field in body:
            body[field] = _resolve(body[field], field)


def _authorize_director_media_inputs(request: Request, body: dict) -> str:
    """Authorize every Director reference before an LLM/provider sees it."""
    workspace = body.get("workspace") or _get_active_workspace()
    _require_project_access(request, workspace)
    _require_remote_visible_models(
        request,
        [body.get("video_model"), body.get("image_model")],
    )
    fields = (
        "reference_image_path", "character_ref_paths", "location_ref_paths",
        "audio_path", "voice_reference", "voice_ref_paths",
    )
    def resolve(value, field):
        if value is None or value == "":
            return value
        if isinstance(value, list):
            return [resolve(item, field) for item in value]
        if not isinstance(value, str):
            raise HTTPException(status_code=400, detail=f"{field} must be a media path or list")
        authorized = _resolve_authorized_request_media(request, value, workspace)
        if not authorized:
            raise HTTPException(status_code=404, detail=f"Unauthorized media: {field}")
        return authorized
    for field in fields:
        if field in body:
            body[field] = resolve(body[field], field)
    body["workspace"] = workspace
    return workspace


def _normalize_image_prompt_type(body: dict) -> None:
    """Strip image_prompt_type flags whose required input is missing.

    Mutates `body` in place. No-op when image_prompt_type isn't set or
    when all flags have their inputs.

    Effect: a body with image_prompt_type='S' but no image_start gets
    its prompt_type rewritten to '' (or stripped of just 'S' if other
    flags survive), turning the job into T2V — matching Maestro's
    documented behavior of auto-falling-back to T2V when no start
    image is provided.
    """
    ipt = body.get("image_prompt_type")
    if not isinstance(ipt, str) or not ipt:
        return

    new_ipt = ipt
    for flag, (input_key, label) in _IPT_REQUIRED_INPUTS.items():
        if flag not in new_ipt:
            continue
        input_val = body.get(input_key)
        is_absent = (
            input_val is None
            or (isinstance(input_val, (list, tuple, str)) and len(input_val) == 0)
        )
        if is_absent:
            new_ipt = new_ipt.replace(flag, "")
            print(
                f"[Generate] Stripped '{flag}' from image_prompt_type "
                f"(no {label} attached) — was {ipt!r}, now {new_ipt!r}. "
                f"Falling back to {'T2V' if not new_ipt else 'I2V with remaining flags'}."
            )

    if new_ipt != ipt:
        body["image_prompt_type"] = new_ipt


_H3_BASE_FL2VA_MODEL = "minimax_h3"
_H3_EXPLICIT_FL2VA_MODEL = "minimax_h3_pinkcherry_fl2va"
_H3_W4A8_FL2VA_MODEL = "minimax_h3_w4a8_fl2va"
_H3_REF2VA_MODEL = "minimax_h3_ref2va"
_H3_CHECKPOINT_CATALOG_ORDER = (
    _H3_BASE_FL2VA_MODEL,
    _H3_EXPLICIT_FL2VA_MODEL,
    _H3_W4A8_FL2VA_MODEL,
    _H3_REF2VA_MODEL,
)
_H3_FL2VA_MODELS = {
    _H3_BASE_FL2VA_MODEL, _H3_EXPLICIT_FL2VA_MODEL, _H3_W4A8_FL2VA_MODEL,
}
_H3_LONG_STUDIO_MODELS = _H3_FL2VA_MODELS | {_H3_REF2VA_MODEL}
_MULTI_CLIP_SEPARATOR = "\n---CLIP_BOUNDARY---\n"
_H3_REF2VA_HANDOFF_FRAMES = 56  # first legal 17*n+5 clip at/above two seconds


def _validate_h3_sampling_steps(body: dict) -> int | None:
    """Reject invalid H3 schedules before any download or model load."""
    if str(body.get("model_type") or "") not in _H3_LONG_STUDIO_MODELS:
        return None
    raw_steps = body.get("num_inference_steps", 20)
    if isinstance(raw_steps, bool):
        raise ValueError("MiniMax H3 inference steps must be an integer from 2 to 50.")
    try:
        steps = int(raw_steps)
    except (TypeError, ValueError) as exc:
        raise ValueError(
            "MiniMax H3 inference steps must be an integer from 2 to 50."
        ) from exc
    if isinstance(raw_steps, float) and not raw_steps.is_integer():
        raise ValueError("MiniMax H3 inference steps must be an integer from 2 to 50.")
    if not 2 <= steps <= 50:
        raise ValueError(
            "MiniMax H3 inference steps must be between 2 and 50 "
            "scheduler grid points (20 is the default)."
        )
    body["num_inference_steps"] = steps
    return steps


def _reject_client_h3_internal_state(body: dict) -> None:
    """Reject executable H3 worker state supplied by an HTTP client.

    Public H3 controls intentionally use ``h3_*`` names.  Leading-underscore
    ``_h3_*`` fields are server-owned: in particular, ``_h3_longform`` may
    contain media paths that the ordinary top-level media authorization pass
    cannot see.  Server and Director jobs retain those fields because they
    enter the worker directly rather than crossing this HTTP boundary.
    """
    internal = sorted(
        str(key) for key in body
        if isinstance(key, str) and key.startswith("_h3_")
    )
    if internal:
        raise HTTPException(
            status_code=400,
            detail=f"Internal H3 request fields are not accepted: {internal}",
        )


def _reject_client_h3_turbo_validation_controls(body: dict) -> None:
    """Keep synthetic Turbo compatibility controls off every HTTP lane.

    A server-owned benchmark capability can authorize its worker directly;
    neither loopback nor remote clients may self-authorize through payload
    fields.
    """
    custom_settings = body.get("custom_settings")
    if (
        isinstance(custom_settings, dict)
        and any(
            key in custom_settings
            for key in (
                "h3_turbo_validation_mode",
                "_h3_turbo_validation_authorized",
            )
        )
    ):
        raise HTTPException(
            status_code=400,
            detail="Internal H3 validation controls are not accepted from clients.",
        )


_H3_TURBO_BENCHMARK_HEADER = "X-Maestro-H3-Benchmark"
_H3_TURBO_BENCHMARK_VERSION = "synthetic-v1"
_H3_TURBO_BENCHMARK_PROMPT_SHA256 = (
    "2e7771bec9eb68269bb79a01f3b605b368071b54e51a6b2f1b8ccd5f4b5b0937"
)
_H3_TURBO_BENCHMARK_REFERENCE_SHA256 = (
    "820ebc22b7fb2896dd9c0b2485e8e9d42ac567a5b838f3a665fafb1380547cab"
)
_H3_TURBO_BENCHMARK_REFERENCE_BYTES = 1858
_H3_TURBO_BENCHMARK_BODY_KEYS = frozenset({
    "model_type", "prompt", "generation_mode", "image_mode",
    "video_length", "sliding_window_size", "sliding_window_overlap",
    "resolution", "num_inference_steps", "guidance_scale", "seed",
    "repeat_generation", "image_prompt_type", "video_prompt_type",
    "audio_prompt_type", "activated_loras", "loras_multipliers",
    "tea_cache", "private_output", "explicit_output", "custom_settings",
    "image_refs", "image_refs_relative_size", "remove_background_images_ref",
    "h3_ref2va_terms_accepted", "h3_adaptive_conditioning",
})


def _is_loopback_request_client(request: Request) -> bool:
    client = getattr(request, "client", None)
    host = str(getattr(client, "host", "") or "").strip()
    if host.casefold() == "localhost":
        return True
    try:
        return bool(ipaddress.ip_address(host).is_loopback)
    except ValueError:
        return False


def _authorize_h3_turbo_benchmark_request(
    request: Request,
    body: dict,
) -> bytes | None:
    """Derive the one-use Ref2VA Turbo probe capability server-side.

    The versioned header is only a request to enter this lane. The server
    grants it after project/media authorization and only for the exact,
    content-pinned synthetic 4/8-evaluation probe emitted by Maestro's local
    benchmark runner. No payload field can self-authorize.
    """
    header = str(request.headers.get(_H3_TURBO_BENCHMARK_HEADER, "") or "")
    if not header:
        return None
    if header != _H3_TURBO_BENCHMARK_VERSION:
        raise HTTPException(status_code=400, detail="Unsupported H3 benchmark request.")
    if bool(getattr(request.state, "maestro_remote", False)) or not (
        _is_loopback_request_client(request)
    ):
        raise HTTPException(status_code=403, detail="H3 benchmark access is local-only.")

    custom = body.get("custom_settings")
    image_refs = body.get("image_refs")
    fixed_integers = {
        "video_length": 124,
        "sliding_window_size": 124,
        "sliding_window_overlap": 0,
        "repeat_generation": 1,
        "image_mode": 0,
    }
    valid = (
        set(body) == _H3_TURBO_BENCHMARK_BODY_KEYS
        and body.get("model_type") == "minimax_h3_ref2va"
        and body.get("generation_mode") == "video"
        and body.get("resolution") == "608x352"
        and body.get("video_prompt_type") == "I"
        and body.get("image_prompt_type") in (None, "")
        and body.get("audio_prompt_type") in (None, "")
        and body.get("private_output") is True
        and body.get("explicit_output") in (None, False)
        and body.get("h3_ref2va_terms_accepted") is True
        and body.get("h3_adaptive_conditioning") is False
        and not isinstance(body.get("guidance_scale"), bool)
        and body.get("guidance_scale") == 1.0
        and not isinstance(body.get("seed"), bool)
        and isinstance(body.get("seed"), int)
        and not isinstance(body.get("image_refs_relative_size"), bool)
        and body.get("image_refs_relative_size") == 100
        and not isinstance(body.get("remove_background_images_ref"), bool)
        and body.get("remove_background_images_ref") == 0
        and isinstance(image_refs, list)
        and len(image_refs) == 1
        and isinstance(image_refs[0], str)
        and isinstance(custom, dict)
        and set(custom) == {
            "h3_attention_engine",
            "h3_benchmark_capture",
            "h3_turbo_profile",
        }
        and custom.get("h3_attention_engine") == "sdpa"
        and custom.get("h3_benchmark_capture") is True
        and custom.get("h3_turbo_profile") == "h3_turbo_v4"
        and body.get("activated_loras") in (None, [])
        and body.get("loras_multipliers") in (None, "")
        and body.get("tea_cache") in (None, False, 0, "")
        and body.get("skip_steps_cache_type") in (None, False, 0, "")
        and all(
            not isinstance(body.get(key), bool)
            and isinstance(body.get(key), int)
            and body.get(key) == expected
            for key, expected in fixed_integers.items()
        )
        and not isinstance(body.get("num_inference_steps"), bool)
        and body.get("num_inference_steps") in (4, 8)
        and hashlib.sha256(
            str(body.get("prompt") or "").encode("utf-8")
        ).hexdigest() == _H3_TURBO_BENCHMARK_PROMPT_SHA256
    )
    forbidden_media = (
        "image_start", "image_end", "image_guide", "image_mask",
        "video_guide", "video_guide2", "video_guide3", "video_mask",
        "video_source", "video_end", "audio_guide", "audio_guide2",
        "audio_guide3", "audio_guide4", "audio_guide5", "audio_guide6",
        "audio_source", "custom_guide", "voice_reference",
    )
    if valid:
        valid = all(body.get(key) in (None, "", []) for key in forbidden_media)
    reference_bytes = None
    if valid:
        reference_path = image_refs[0]
        try:
            valid = (
                os.path.isfile(reference_path)
                and os.path.getsize(reference_path)
                == _H3_TURBO_BENCHMARK_REFERENCE_BYTES
            )
            if valid:
                with open(reference_path, "rb") as handle:
                    reference_bytes = handle.read()
                    valid = hashlib.sha256(reference_bytes).hexdigest() == (
                        _H3_TURBO_BENCHMARK_REFERENCE_SHA256
                    )
        except OSError:
            valid = False
    if not valid:
        raise HTTPException(
            status_code=400,
            detail="Synthetic H3 benchmark request does not match the server-owned validation case.",
        )
    return reference_bytes


def _materialize_h3_turbo_validation_reference(
    reference_bytes: bytes,
    task_params: dict,
) -> tuple[bool, object]:
    """Replace an admitted pathname with its captured immutable image bytes."""
    if (
        not isinstance(reference_bytes, bytes)
        or len(reference_bytes) != _H3_TURBO_BENCHMARK_REFERENCE_BYTES
        or hashlib.sha256(reference_bytes).hexdigest()
        != _H3_TURBO_BENCHMARK_REFERENCE_SHA256
    ):
        raise ValueError("Synthetic H3 validation input is unavailable.")
    import io as _io
    from PIL import Image as _PILImage

    had_image_refs = "image_refs" in task_params
    original_image_refs = task_params.get("image_refs")
    with _PILImage.open(_io.BytesIO(reference_bytes)) as reference_image:
        pinned_reference = reference_image.convert("RGB")
    task_params["image_refs"] = [pinned_reference]
    return had_image_refs, original_image_refs


def _restore_h3_turbo_validation_reference(
    task_params: dict,
    restoration: tuple[bool, object],
) -> None:
    had_image_refs, original_image_refs = restoration
    if had_image_refs:
        task_params["image_refs"] = original_image_refs
    else:
        task_params.pop("image_refs", None)


def _trusted_h3_prepared_plan(
    body: dict,
    plan: dict | None = None,
    *,
    allow_server_prepared: bool = False,
) -> dict | None:
    """Select a prepared plan only on an explicitly trusted server path."""
    if isinstance(plan, dict):
        return plan
    if allow_server_prepared:
        prepared = body.get("_h3_longform")
        if isinstance(prepared, dict):
            return prepared
    return None


def _require_h3_acceleration_available(
    body: dict,
    plan: dict | None = None,
    *,
    allow_server_prepared: bool = False,
) -> None:
    """Reject optional H3 checkpoints whose validated runtime is unavailable."""
    trusted_plan = _trusted_h3_prepared_plan(
        body, plan, allow_server_prepared=allow_server_prepared,
    )
    requested = set(_h3_effective_model_types(body, trusted_plan))
    if _H3_W4A8_FL2VA_MODEL not in requested:
        return
    from services.h3_acceleration import get_h3_acceleration_status
    capability = get_h3_acceleration_status(probe_kernel=False).get("w4a8") or {}
    if capability.get("available") is not True:
        reason = str(capability.get("reason") or "W4A8 runtime validation is unavailable")
        raise ValueError(f"Kijai W4A8 FL2VA is unavailable: {reason}")


def _apply_h3_adaptive_checkpoint(body: dict) -> str:
    """Resolve the effective H3 checkpoint from the supplied conditioning.

    This also covers native single-window jobs.  Turning adaptive conditioning
    off is the explicit override and leaves the selected checkpoint untouched.
    """
    selected = str(body.get("model_type") or "")
    if selected not in _H3_LONG_STUDIO_MODELS:
        return selected
    has_semantic = bool(body.get("image_refs")) or any(
        body.get(key) for key in (
            "video_guide", "video_guide2", "video_guide3",
            "audio_guide", "audio_guide2", "audio_guide3",
        )
    ) or any(letter in str(body.get("audio_prompt_type") or "") for letter in "ABCK")
    has_frame_anchor = bool(body.get("image_start") or body.get("image_end"))
    if body.get("h3_adaptive_conditioning", True) is False:
        if (
            selected == _H3_REF2VA_MODEL
            and has_frame_anchor
            and body.get("h3_native_boundary_conditioning") is not True
        ):
            raise ValueError(
                "Pinned Ref2VA cannot use first/last-frame anchors; enable "
                "adaptive conditioning or remove the edge anchors"
            )
        if selected in _H3_FL2VA_MODELS and has_semantic:
            raise ValueError(
                "Pinned FL2VA cannot use semantic references; enable adaptive "
                "conditioning or remove the semantic references"
            )
        return selected
    # Preserve the user's FL2VA flavor before adaptive routing temporarily
    # moves the request to Ref2VA. The long-form planner must still return to
    # that exact checkpoint for continuous segments and supplied edge frames.
    body.setdefault("_h3_requested_checkpoint", selected)
    requested_frames = int(body.get("video_length") or 0)
    selected_def = wgp.get_model_def(selected) or {}
    is_long = requested_frames > int(selected_def.get("frames_maximum") or 0)

    # A multi-segment plan can use FL2VA at supplied edge anchors and Ref2VA
    # through semantic/cut segments. Preserve all inputs for that planner.
    if has_semantic and has_frame_anchor and is_long:
        effective = _H3_REF2VA_MODEL
    elif has_semantic:
        effective = _H3_REF2VA_MODEL
    else:
        effective = _h3_preferred_fl2va_model(body)
    body["model_type"] = effective
    body["h3_effective_checkpoint_reason"] = (
        "semantic references" if has_semantic else
        "supplied frame anchor" if has_frame_anchor else
        "text/audio-video generation profile"
    )
    return effective


def _h3_preferred_fl2va_model(body: dict) -> str:
    """Return the FL2VA checkpoint matching caller model-selection intent.

    Adaptive routing may temporarily use Ref2VA, but it must return to the
    caller's exact Base, W4A8, or PinkCherry FL2VA flavor. ``explicit_output``
    is output metadata and never participates in checkpoint selection.
    """
    selected = str(
        body.get("_h3_requested_checkpoint")
        or body.get("model_type")
        or _H3_BASE_FL2VA_MODEL
    )
    if selected in _H3_FL2VA_MODELS:
        return selected
    return _H3_BASE_FL2VA_MODEL


def _h3_ref2va_reference_capacity(params: dict, *, handoff_seconds: float) -> dict:
    """Describe whether one rolling video or still reference can be appended."""
    video_paths = [
        params.get(key)
        for key in ("video_guide", "video_guide2", "video_guide3")
        if params.get(key)
    ]
    video_seconds = 0.0
    for path in video_paths:
        try:
            source_fps, _, _, source_frames = wgp.get_video_info(path)
            if source_fps:
                video_seconds += float(source_frames) / float(source_fps)
        except Exception:
            # Validation will report an unreadable user reference later. Do
            # not count unknown duration as spare continuation capacity.
            video_seconds = 15.0
            break
    image_refs = list(params.get("image_refs") or [])
    audio_type = str(params.get("audio_prompt_type") or "")
    standalone_audio_count = sum(letter in audio_type for letter in "ABC")
    audio_count = len(video_paths) if "K" in audio_type else standalone_audio_count
    mixed_count = len(image_refs) + len(video_paths) + standalone_audio_count
    return {
        "video": (
            len(video_paths) < 3
            and video_seconds + float(handoff_seconds) <= 15.0 + 1e-6
            and mixed_count < 12
        ),
        "image": len(image_refs) < 9 and mixed_count < 12,
        "video_count": len(video_paths),
        "video_seconds": video_seconds,
        "mixed_count": mixed_count,
        "audio": audio_count < 3,
    }


def _create_h3_ref2va_tail_video(
    source_path: str,
    output_path: str,
    *,
    frames: int = _H3_REF2VA_HANDOFF_FRAMES,
    fps: float = 24.0,
) -> str:
    """Encode an exact, silent H3-grid tail for the next Ref2VA segment."""
    source_fps, _, _, source_frames = wgp.get_video_info(source_path)
    if not source_fps or not source_frames:
        raise ValueError("preceding segment has no readable video timeline")
    source_duration = float(source_frames) / float(source_fps)
    duration = float(frames) / float(fps)
    if source_duration + 1e-6 < duration:
        raise ValueError("preceding segment is too short for a Ref2VA handoff")
    start_seconds = max(0.0, source_duration - duration)
    ffmpeg_bin = os.environ.get("FFMPEG_BINARY", "ffmpeg")
    command = [
        ffmpeg_bin, "-hide_banner", "-loglevel", "error", "-nostdin", "-y",
        "-ss", f"{start_seconds:.6f}", "-i", source_path,
        "-an", "-vf", f"fps={fps:g}", "-frames:v", str(int(frames)),
        "-c:v", "libx264", "-preset", "fast", "-crf", "15",
        "-pix_fmt", "yuv420p", output_path,
    ]
    completed = subprocess.run(command, capture_output=True, text=True, timeout=180)
    if completed.returncode != 0 or not os.path.isfile(output_path):
        raise RuntimeError(
            "ffmpeg could not encode the Ref2VA continuation tail: "
            + (completed.stderr or "unknown ffmpeg error")[-500:]
        )
    prepared_fps, _, _, prepared_frames = wgp.get_video_info(output_path)
    if not prepared_fps or int(prepared_frames or 0) < int(frames):
        raise RuntimeError("Ref2VA continuation tail did not contain the required frames")
    return output_path


def _create_h3_native_boundary_media(
    source_path: str,
    output_path: str,
) -> dict:
    """Create an exact private 18-frame, 32 kHz stereo AV overlap."""

    from services.h3_boundary_policy import (
        H3_NATIVE_AUDIO_SAMPLE_RATE,
        H3_NATIVE_FPS,
        H3_NATIVE_OVERLAP_FRAMES,
        attest_boundary_file,
    )

    source_fps, _, _, source_frames = wgp.get_video_info(source_path)
    if not source_fps or int(source_frames or 0) < H3_NATIVE_OVERLAP_FRAMES:
        raise ValueError("preceding H3 segment is too short for native AV history")
    duration = H3_NATIVE_OVERLAP_FRAMES / float(H3_NATIVE_FPS)
    source_duration = float(source_frames) / float(source_fps)
    start_seconds = max(0.0, source_duration - duration)
    output_path = os.path.abspath(output_path)
    output_parent = os.path.dirname(output_path)
    if (
        os.path.realpath(output_parent) != output_parent
        or os.path.basename(output_path) in {"", ".", ".."}
        or os.path.lexists(output_path)
    ):
        raise QueueRecoveryRuntimeError(
            "native H3 boundary output identity is unsafe"
        )

    def remove_invalid_output() -> None:
        try:
            if (
                os.path.dirname(output_path) == output_parent
                and os.path.isfile(output_path)
                and not os.path.islink(output_path)
            ):
                os.remove(output_path)
        except OSError:
            pass

    ffmpeg_bin = os.environ.get("FFMPEG_BINARY", "ffmpeg")
    command = [
        ffmpeg_bin, "-hide_banner", "-loglevel", "error", "-nostdin", "-y",
        "-ss", f"{start_seconds:.9f}", "-i", source_path,
        "-map", "0:v:0", "-map", "0:a:0",
        "-vf", f"fps={H3_NATIVE_FPS}",
        "-frames:v", str(H3_NATIVE_OVERLAP_FRAMES),
        "-af", (
            f"aresample={H3_NATIVE_AUDIO_SAMPLE_RATE},"
            f"apad=pad_dur={duration:.9f},atrim=duration={duration:.9f},"
            "asetpts=PTS-STARTPTS"
        ),
        "-c:v", "libx264", "-preset", "fast", "-crf", "15",
        "-pix_fmt", "yuv420p", "-c:a", "aac", "-ar",
        str(H3_NATIVE_AUDIO_SAMPLE_RATE), "-ac", "2", "-shortest", output_path,
    ]
    completed = subprocess.run(command, capture_output=True, text=True, timeout=180)
    if completed.returncode != 0 or not os.path.isfile(output_path):
        remove_invalid_output()
        raise RuntimeError(
            "ffmpeg could not create native H3 AV boundary media: "
            + (completed.stderr or "unknown ffmpeg error")[-500:]
        )
    if os.path.islink(output_path) or os.path.realpath(output_path) != output_path:
        raise QueueRecoveryRuntimeError(
            "native H3 boundary output escaped private staging"
        )
    prepared_fps, _, _, prepared_frames = wgp.get_video_info(output_path)
    if (
        abs(float(prepared_fps or 0) - H3_NATIVE_FPS) > 1e-6
        or int(prepared_frames or 0) != H3_NATIVE_OVERLAP_FRAMES
    ):
        remove_invalid_output()
        raise RuntimeError("native H3 boundary video geometry is invalid")
    ffprobe_bin = ffmpeg_bin.replace("ffmpeg", "ffprobe")
    probe = subprocess.run(
        [
            ffprobe_bin, "-v", "error", "-select_streams", "a:0",
            "-show_entries", "stream=sample_rate,channels",
            "-of", "json", output_path,
        ],
        capture_output=True, text=True, timeout=30,
    )
    try:
        streams = json.loads(probe.stdout).get("streams") or []
        audio = streams[0]
        audio_valid = (
            int(audio.get("sample_rate") or 0) == H3_NATIVE_AUDIO_SAMPLE_RATE
            and int(audio.get("channels") or 0) == 2
        )
    except (IndexError, TypeError, ValueError, json.JSONDecodeError):
        audio_valid = False
    if probe.returncode != 0 or not audio_valid:
        remove_invalid_output()
        raise RuntimeError("native H3 boundary audio is not 32 kHz stereo")
    try:
        descriptor = attest_boundary_file(output_path)
    except Exception:
        remove_invalid_output()
        raise
    descriptor.update({
        "mode": "native_av_overlap",
        "fps": H3_NATIVE_FPS,
        "audio_sample_rate": H3_NATIVE_AUDIO_SAMPLE_RATE,
        "audio_channels": 2,
        "overlap_frames": H3_NATIVE_OVERLAP_FRAMES,
        "discard_frames": H3_NATIVE_OVERLAP_FRAMES - 1,
    })
    return descriptor


def _attach_h3_native_boundary_handoff(
    next_params: dict,
    *,
    latest_video: str,
    project_dir: str,
    output_prefix: str,
) -> dict:
    """Materialize a server-owned native AV boundary in private staging."""

    request = next_params.get("_h3_native_boundary_request")
    if not isinstance(request, dict):
        raise QueueRecoveryRuntimeError("H3 native boundary request is missing")
    from services.h3_boundary_policy import (
        H3_NATIVE_HISTORY_FRAMES,
        H3_NATIVE_OVERLAP_FRAMES,
    )

    if (
        int(request.get("overlap_frames") or 0) != H3_NATIVE_OVERLAP_FRAMES
        or int(request.get("discard_frames") or 0) != H3_NATIVE_HISTORY_FRAMES
    ):
        raise QueueRecoveryRuntimeError("H3 native boundary math is invalid")
    staging = ensure_recovery_staging_directory(project_dir)
    if not output_prefix or os.path.basename(output_prefix) != output_prefix:
        raise QueueRecoveryRuntimeError("H3 native boundary identity is invalid")
    path = os.path.join(
        staging,
        f"{output_prefix}-native-boundary-{uuid.uuid4().hex}.mp4",
    )
    descriptor = _create_h3_native_boundary_media(latest_video, path)
    descriptor["boundary_type"] = str(
        request.get("boundary_type") or "continuous"
    )
    next_params["_h3_native_boundary"] = descriptor
    next_params.pop("_h3_native_boundary_request", None)
    return descriptor


def _attach_h3_ref2va_handoff(
    next_params: dict,
    *,
    latest_video: str,
    last_frame_path: str,
    out_dir: str,
    task_no: int,
    boundary_type: str,
    recovery_staging_dir: str | None = None,
    recovery_output_prefix: str | None = None,
) -> dict:
    """Attach prior-segment context with cut-aware Ref2VA semantics."""
    handoff_seconds = _H3_REF2VA_HANDOFF_FRAMES / 24.0
    capacity = _h3_ref2va_reference_capacity(
        next_params, handoff_seconds=handoff_seconds,
    )
    result = {"mode": "prompt_only", "boundary": boundary_type}
    # A continuous join benefits from a time-ordered video tail. Cuts and soft
    # transitions deliberately receive a still semantic memory so the old
    # camera pose is not mistaken for a required first frame.
    if boundary_type in {"continuous", "precut"} and capacity["video"]:
        if recovery_staging_dir:
            if not recovery_output_prefix:
                raise QueueRecoveryRuntimeError(
                    "H3 recovery continuation identity is missing."
                )
            tail_path = os.path.join(
                recovery_staging_dir,
                f"{recovery_output_prefix}-continuation-ref.mp4",
            )
        else:
            tail_path = os.path.join(
                out_dir, f"_continuation_ref_{task_no}.mp4",
            )
        try:
            _create_h3_ref2va_tail_video(latest_video, tail_path)
            for slot, key in enumerate(
                ("video_guide", "video_guide2", "video_guide3"), start=1,
            ):
                if not next_params.get(key):
                    next_params[key] = tail_path
                    video_count = capacity["video_count"] + 1
                    next_params["video_prompt_type"] = {
                        1: "V-", 2: "V+-", 3: "V++-",
                    }[video_count]
                    custom = dict(next_params.get("custom_settings") or {})
                    custom.update({
                        "h3_ref2va_handoff": "temporal_tail",
                        "h3_ref2va_handoff_video_slot": slot,
                        "h3_ref2va_handoff_frames": _H3_REF2VA_HANDOFF_FRAMES,
                        "h3_ref2va_handoff_audio": bool(capacity["audio"]),
                    })
                    next_params["custom_settings"] = custom
                    result = {"mode": "temporal_tail", "path": tail_path, "boundary": boundary_type}
                    break
        except Exception as error:
            result["warning"] = str(error)
            try:
                os.remove(tail_path)
            except OSError:
                pass
    if result["mode"] == "prompt_only" and capacity["image"]:
        refs = list(next_params.get("image_refs") or [])
        refs.append(last_frame_path)
        next_params["image_refs"] = refs
        custom = dict(next_params.get("custom_settings") or {})
        custom["h3_ref2va_handoff"] = "semantic_still"
        next_params["custom_settings"] = custom
        warning = result.get("warning")
        result = {"mode": "semantic_still", "path": last_frame_path, "boundary": boundary_type}
        if warning:
            result["warning"] = warning
    next_params["_h3_ref2va_handoff_result"] = result["mode"]
    return result


def _plan_h3_adaptive_models(
    body: dict,
    *,
    clip_count: int,
    clip_boundaries: list[dict],
    first_anchor,
    last_anchor,
) -> list[dict]:
    """Choose conditioning checkpoints without checkpoint thrashing.

    Once the plan enters Ref2VA at a cut it stays there for the remaining
    semantic run; it does not bounce back to FL2VA at every ordinary join.
    A supplied final-frame contract is the one exception and always reserves
    FL2VA for the final segment.
    """
    selected = str(body.get("model_type") or "minimax_h3")
    fl2va_model = _h3_preferred_fl2va_model(body)
    adaptive = body.get("h3_adaptive_conditioning", True) is not False
    native_boundaries = body.get("h3_native_boundary_conditioning") is True
    legacy_semantic_refs = bool(body.get("image_refs")) or any(
        body.get(key) for key in ("video_guide", "video_guide2", "video_guide3")
    ) or any(letter in str(body.get("audio_prompt_type") or "") for letter in "ABCK")
    if native_boundaries:
        from services.h3_boundary_policy import has_semantic_references

        has_semantic_refs = has_semantic_references(body)
    else:
        has_semantic_refs = legacy_semantic_refs
    if not adaptive:
        return [{
            "model_type": selected,
            "reason": "manual checkpoint override",
        } for _ in range(clip_count)]

    models = []
    if native_boundaries:
        from services.h3_boundary_policy import decide_h3_boundary

        for index in range(clip_count):
            boundary = (
                clip_boundaries[index - 1]
                if index > 0 and index - 1 < len(clip_boundaries)
                else {}
            )
            decision = decide_h3_boundary(
                segment_index=index,
                boundary_type=boundary.get("type"),
                semantic_references=has_semantic_refs,
                preferred_fl2va_model=fl2va_model,
            )
            models.append(decision.as_dict())
    else:
        semantic_run = has_semantic_refs
        for index in range(clip_count):
            boundary = clip_boundaries[index - 1] if index > 0 and index - 1 < len(clip_boundaries) else {}
            boundary_type = str(boundary.get("type") or "continuous")
            if index == 0 and first_anchor:
                model_type = fl2va_model
                reason = "supplied first-frame anchor"
            elif semantic_run:
                model_type = "minimax_h3_ref2va"
                reason = "supplied semantic references" if has_semantic_refs else "semantic continuity after cut"
            elif index > 0 and boundary_type in {"cut", "transition", "precut"}:
                semantic_run = True
                model_type = "minimax_h3_ref2va"
                reason = (
                    "rolling context before authored cut"
                    if boundary_type == "precut"
                    else "semantic context across authored cut"
                )
            else:
                model_type = fl2va_model
                reason = "hard frame continuity for continuous action"
            models.append({"model_type": model_type, "reason": reason})

        if last_anchor:
            models[-1] = {
                "model_type": fl2va_model,
                "reason": "supplied final-frame anchor",
            }
    overrides = body.get("h3_segment_overrides")
    if overrides is not None and not isinstance(overrides, list):
        raise ValueError("h3_segment_overrides must be a list")
    if isinstance(overrides, list):
        for index, override in enumerate(overrides[:clip_count]):
            if not isinstance(override, dict) or not override.get("model_type"):
                continue
            requested = str(override.get("model_type"))
            if requested not in _H3_LONG_STUDIO_MODELS:
                raise ValueError(f"Unknown H3 segment model override: {requested}")
            if not native_boundaries and requested == "minimax_h3_ref2va" and (
                (index == 0 and first_anchor)
                or (index == clip_count - 1 and last_anchor)
            ):
                raise ValueError(
                    f"Segment {index + 1} must use FL2VA to honor its supplied frame anchor"
                )
            if requested in _H3_FL2VA_MODELS and has_semantic_refs and not bool(
                override.get("drop_semantic_refs")
            ):
                raise ValueError(
                    f"Segment {index + 1} needs drop_semantic_refs=true before FL2VA can replace supplied semantic references"
                )
            drop_semantic_refs = bool(override.get("drop_semantic_refs"))
            if native_boundaries:
                # An override may select the preferred FL2VA flavor, but it
                # must not replace the native handoff decision. Re-evaluate
                # after an explicit semantic-ref drop, then retain every
                # overlap/still field from the shared policy.
                boundary = (
                    clip_boundaries[index - 1]
                    if index > 0 and index - 1 < len(clip_boundaries)
                    else {}
                )
                preferred = requested if requested in _H3_FL2VA_MODELS else fl2va_model
                decision = decide_h3_boundary(
                    segment_index=index,
                    boundary_type=boundary.get("type"),
                    semantic_references=has_semantic_refs and not drop_semantic_refs,
                    preferred_fl2va_model=preferred,
                )
                if requested != decision.model_type:
                    raise ValueError(
                        f"Segment {index + 1} override conflicts with the native H3 boundary policy ({decision.model_type} required)"
                    )
                models[index] = decision.as_dict()
                models[index].update({
                    "reason": str(override.get("reason") or "user plan override"),
                    "drop_semantic_refs": drop_semantic_refs,
                    "user_override": True,
                })
            else:
                models[index] = {
                    "model_type": requested,
                    "reason": str(override.get("reason") or "user plan override"),
                    "drop_semantic_refs": drop_semantic_refs,
                    "user_override": True,
                }
    for index, item in enumerate(models):
        item["index"] = index
        item["switch_from_previous"] = bool(
            index and models[index - 1]["model_type"] != item["model_type"]
        )
    return models


def _validate_h3_segment_plan(
    body: dict,
    *,
    clip_frames: list[int],
    segment_models: list[dict],
    first_anchor,
    last_anchor,
) -> None:
    """Validate each planned segment against its actual checkpoint contract."""
    if len(clip_frames) != len(segment_models):
        raise ValueError("H3 segment frame and model plans must have equal length")
    has_semantic_refs = bool(body.get("image_refs")) or any(
        body.get(key) for key in (
            "video_guide", "video_guide2", "video_guide3",
            "audio_guide", "audio_guide2", "audio_guide3",
        )
    ) or any(
        letter in str(body.get("audio_prompt_type") or "")
        for letter in "ABCK"
    )
    for index, (frame_count, item) in enumerate(zip(clip_frames, segment_models)):
        model_type = str(item.get("model_type") or "")
        if model_type not in _H3_LONG_STUDIO_MODELS:
            raise ValueError(f"Unknown H3 segment model: {model_type}")
        model_def = wgp.get_model_def(model_type) or {}
        minimum = int(model_def.get("frames_minimum") or 1)
        maximum = int(model_def.get("frames_maximum") or 0)
        frame_count = int(frame_count)
        if maximum <= 0 or not minimum <= frame_count <= maximum:
            raise ValueError(
                f"Segment {index + 1} uses {model_type}, which requires "
                f"{minimum}-{maximum} frames"
            )
        aligned = int(wgp.align_model_frame_count(frame_count, model_def))
        if aligned != frame_count:
            raise ValueError(
                f"Segment {index + 1} frame count {frame_count} is not on "
                f"the {model_type} temporal grid"
            )
        edge_anchor = bool(
            (index == 0 and first_anchor)
            or (index == len(segment_models) - 1 and last_anchor)
        )
        if (
            model_type == _H3_REF2VA_MODEL
            and edge_anchor
            and body.get("h3_native_boundary_conditioning") is not True
        ):
            raise ValueError(
                f"Segment {index + 1} must use FL2VA for its supplied frame anchor"
            )
        if (
            item.get("user_override")
            and model_type in _H3_FL2VA_MODELS
            and has_semantic_refs
            and not item.get("drop_semantic_refs")
        ):
            raise ValueError(
                f"Segment {index + 1} must explicitly drop semantic references "
                "before using FL2VA"
            )


def _require_h3_native_boundary_experimental(body: dict) -> None:
    """Reject the unproven native H3 boundary path before admission.

    The model handler retains the same check as a final inference backstop,
    but HTTP and internal Director callers must fail before a job can become
    visible or enter the scheduler.
    """
    if (
        str(body.get("model_type") or "") in _H3_LONG_STUDIO_MODELS
        and body.get("h3_native_boundary_conditioning") is True
        and os.environ.get("MAESTRO_H3_NATIVE_BOUNDARY_EXPERIMENTAL") != "1"
    ):
        raise ValueError(
            "Native MiniMax H3 boundary conditioning is unavailable; "
            "use the supported automatic segmented path"
        )


def _prepare_h3_long_studio_request(body: dict) -> dict | None:
    """Convert a >native-window H3 Studio request into native clip tasks.

    This is deliberately an API normalization rather than a UI-only feature:
    saved payloads and direct callers get the same model-grid planning.  The
    worker consumes ``_h3_longform`` while constructing its ordinary existing
    multi-clip manifest.
    """
    model_type = str(body.get("model_type") or "")
    if (
        model_type not in _H3_LONG_STUDIO_MODELS
        or body.get("sfx_mode")
        or str(body.get("generation_mode") or "video") == "image"
        or int(body.get("multi_prompts_gen_type") or 0) == 3
    ):
        return None

    model_def = wgp.get_model_def(model_type) or {}
    try:
        requested_frames = int(body.get("video_length") or 0)
        maximum_frames = int(model_def.get("frames_maximum") or 0)
        minimum_frames = int(model_def.get("frames_minimum") or 1)
        fps = float(model_def.get("fps") or 24)
    except (TypeError, ValueError):
        return None
    if maximum_frames <= 0:
        return None

    if body.get("h3_adaptive_conditioning", True) is not False:
        fl2va_def = wgp.get_model_def("minimax_h3") or {}
        minimum_frames = max(
            minimum_frames,
            int(fl2va_def.get("frames_minimum") or minimum_frames),
        )

    from services.h3_shot_planner import (
        floor_h3_frame_count,
        infer_h3_profile_id,
        plan_h3_clip_frames,
        plan_h3_native_shots,
    )

    # A locked Studio ceiling is the native-shot boundary even when the total
    # request still fits beneath the checkpoint's absolute maximum.  Decide
    # admission against that effective aligned ceiling so bounded H3 never
    # falls through to WGP's legacy rolling-window path.
    try:
        requested_segment_maximum = int(
            body.get("sliding_window_size") or maximum_frames
        )
    except (TypeError, ValueError):
        requested_segment_maximum = maximum_frames
    manual_segment_ceiling = body.get("sliding_window_size") not in (None, "")
    if manual_segment_ceiling:
        segment_maximum = floor_h3_frame_count(
            requested_segment_maximum,
            minimum_frames=minimum_frames,
            maximum_frames=maximum_frames,
            align_frame_count=lambda value: wgp.align_model_frame_count(
                value, model_def,
            ),
        )
    else:
        segment_maximum = int(wgp.align_model_frame_count(
            maximum_frames, model_def,
        ))
    segment_maximum = max(
        minimum_frames,
        min(maximum_frames, segment_maximum),
    )
    if requested_frames <= segment_maximum:
        return None

    reference_mode = bool(model_def.get("minimax_h3_reference_mode"))

    def edge_anchor(value, *, last=False):
        if isinstance(value, (list, tuple)):
            present = [item for item in value if item]
            if not present:
                return None
            return present[-1] if last else present[0]
        return value or None

    first_anchor = edge_anchor(body.get("image_start"))
    last_anchor = edge_anchor(body.get("image_end"), last=True)
    # FL2VA's end anchor requires its native tail to be discarded. Generate
    # that tail inside the last legal H3 clip, then trim the aggregate exactly
    # to the requested published duration instead of adding a minimum-5s
    # generic compensation clip.
    end_anchor_trim = int(model_def.get("frames_steps") or 0) if last_anchor else 0
    generation_target_frames = requested_frames + end_anchor_trim

    from shared.utils.prompt_parser import (
        classify_timeline_clip_boundaries,
    )
    # Studio exposes a user-controlled native segment ceiling.  Honor its
    # model-aligned value here so the card's segment count and the worker's
    # actual plan cannot diverge.  Missing/legacy payloads retain the model's
    # largest legal segment.
    global_prompt = str(body.get("prompt") or "")
    clip_frames, segment_policy = plan_h3_clip_frames(
        generation_target_frames,
        prompt=global_prompt,
        fps=fps,
        minimum_frames=minimum_frames,
        maximum_frames=segment_maximum,
        align_frame_count=lambda value: wgp.align_model_frame_count(
            value, model_def,
        ),
        profile_id=infer_h3_profile_id(body),
        manual_segment_ceiling=manual_segment_ceiling,
        published_total_frames=requested_frames,
    )
    clip_requested_frames = list(
        segment_policy.get("clip_requested_frames") or clip_frames
    )
    if "clip_requested_frames" not in segment_policy:
        clip_requested_frames[-1] -= sum(clip_frames) - requested_frames
    clip_boundaries = classify_timeline_clip_boundaries(
        global_prompt,
        clip_frame_counts=clip_requested_frames,
        fps=fps,
    )
    boundary_overrides = body.get("h3_boundary_overrides")
    if boundary_overrides is not None and not isinstance(boundary_overrides, list):
        raise ValueError("h3_boundary_overrides must be a list")
    if isinstance(boundary_overrides, list):
        for index, override in enumerate(boundary_overrides[:len(clip_boundaries)]):
            if not isinstance(override, dict) or not override.get("type"):
                continue
            requested_type = str(override.get("type"))
            if requested_type not in {"continuous", "precut", "cut", "transition"}:
                raise ValueError(
                    f"Unknown H3 boundary override: {requested_type}"
                )
            clip_boundaries[index] = {
                **clip_boundaries[index],
                "type": requested_type,
                "source": "user_override",
            }
    shot_plan = plan_h3_native_shots(
        global_prompt=global_prompt,
        clip_frame_counts=clip_frames,
        fps=fps,
        clip_boundaries=clip_boundaries,
        clip_requested_frames=clip_requested_frames,
        segment_frames_maximum=segment_maximum,
        segment_policy=segment_policy,
    )
    clip_prompts = list(shot_plan["clip_prompts"])
    clip_boundaries = list(shot_plan["clip_boundaries"])
    segment_models = _plan_h3_adaptive_models(
        body,
        clip_count=len(clip_frames),
        clip_boundaries=clip_boundaries,
        first_anchor=first_anchor,
        last_anchor=last_anchor,
    )
    _validate_h3_segment_plan(
        body,
        clip_frames=clip_frames,
        segment_models=segment_models,
        first_anchor=first_anchor,
        last_anchor=last_anchor,
    )

    clip_count = len(clip_frames)
    native_boundaries = body.get("h3_native_boundary_conditioning") is True
    if reference_mode and not native_boundaries:
        # Ref2VA's image/audio/video guides are semantic references copied to
        # every task. They must never be rewritten as FL2VA frame anchors.
        body.pop("image_start", None)
        body.pop("image_end", None)
        body["image_prompt_type"] = ""
        continuation = "semantic_references"
    else:
        body["image_start"] = [first_anchor] + [None] * (clip_count - 1)
        body["image_end"] = [None] * (clip_count - 1) + [last_anchor]
        continuation = "last_frame"

    planned_frames = sum(clip_frames)
    clip_published_frames = list(shot_plan["clip_published_frames"])
    clip_trim_tail_frames = list(shot_plan["clip_trim_tail_frames"])
    body["prompt"] = _MULTI_CLIP_SEPARATOR.join(clip_prompts)
    body["per_clip_prompts"] = clip_prompts
    body["per_clip_frames"] = clip_frames
    body["video_length"] = requested_frames
    body["multi_prompts_gen_type"] = 3
    body["_h3_longform"] = {
        "model_type": model_type,
        "requested_frames": requested_frames,
        "planned_frames": planned_frames,
        "published_frames": requested_frames,
        "final_trim_frames": sum(clip_trim_tail_frames),
        "clip_count": clip_count,
        "clip_frames": clip_frames,
        "clip_published_frames": clip_published_frames,
        "clip_trim_tail_frames": clip_trim_tail_frames,
        "clip_prompt_previews": [prompt[:240] for prompt in clip_prompts],
        "segment_frames_maximum": segment_maximum,
        "manual_segment_ceiling": manual_segment_ceiling,
        "continuation": continuation,
        "clip_boundaries": clip_boundaries,
        "shot_plan": shot_plan,
        "segment_policy": segment_policy,
        "ref2va_continuity": (
            "rolling_reference" if reference_mode else None
        ),
        "adaptive_conditioning": body.get(
            "h3_adaptive_conditioning", True,
        ) is not False,
        "segment_models": segment_models,
        "preserve_generated_audio": reference_mode or native_boundaries,
        "native_boundary_conditioning": native_boundaries,
        "global_prompt": global_prompt,
        "original_image_start": first_anchor,
        "original_image_end": last_anchor,
    }
    return body["_h3_longform"]


def _public_h3_long_plan(
    plan: dict | None,
    requirements: dict | None = None,
) -> dict | None:
    if not isinstance(plan, dict) or int(plan.get("clip_count") or 0) <= 1:
        return None
    frames = list(plan.get("clip_frames") or [])
    models = list(plan.get("segment_models") or [])
    boundaries = list(plan.get("clip_boundaries") or [])
    prompts = list(plan.get("clip_prompt_previews") or [])
    segments = []
    for index in range(int(plan.get("clip_count") or 0)):
        model = models[index] if index < len(models) and isinstance(models[index], dict) else {}
        boundary = boundaries[index - 1] if index > 0 and index - 1 < len(boundaries) else None
        frame_count = int(frames[index]) if index < len(frames) else 0
        segments.append({
            "index": index + 1,
            "frames": frame_count,
            "duration_seconds": frame_count / 24.0,
            "model_type": model.get("model_type"),
            "model_reason": model.get("reason"),
            "edge_anchor_locked": bool(
                (index == 0 and plan.get("original_image_start"))
                or (
                    index == int(plan.get("clip_count") or 0) - 1
                    and plan.get("original_image_end")
                )
            ),
            "switch_from_previous": bool(model.get("switch_from_previous")),
            "boundary_from_previous": boundary,
            "prompt_preview": prompts[index] if index < len(prompts) else "",
        })
    effective_models = []
    for segment in segments:
        model_type = str(segment.get("model_type") or "")
        if model_type and model_type not in effective_models:
            effective_models.append(model_type)
    public = {
        "kind": "h3_segments",
        "clip_count": len(segments),
        "requested_frames": int(plan.get("requested_frames") or 0),
        "planned_frames": int(plan.get("planned_frames") or 0),
        "adaptive_conditioning": bool(plan.get("adaptive_conditioning")),
        "checkpoint_switches": sum(
            1 for segment in segments if segment["switch_from_previous"]
        ),
        "effective_model_count": len(effective_models),
        "effective_models": effective_models,
        "segments": segments,
    }
    if isinstance(requirements, dict):
        options = requirements.get("checkpoint_options")
        if isinstance(options, list):
            # The server owns this catalog. It contains no paths or arbitrary
            # download URLs, only registered model IDs and actionable state.
            public["checkpoint_options"] = options
    return public


def _h3_effective_model_types(body: dict, plan: dict | None = None) -> list[str]:
    """Return the unique checkpoints the effective request can load."""
    ordered: list[str] = []
    if isinstance(plan, dict):
        for segment in plan.get("segment_models") or []:
            if isinstance(segment, dict):
                model_type = str(segment.get("model_type") or "")
                if model_type in _H3_LONG_STUDIO_MODELS and model_type not in ordered:
                    ordered.append(model_type)
    if not ordered:
        model_type = str(body.get("model_type") or "")
        if model_type in _H3_LONG_STUDIO_MODELS:
            ordered.append(model_type)
    return ordered


def _ensure_h3_effective_models_current(
    body: dict,
    plan: dict | None,
    *,
    already_checked: set[str] | None = None,
) -> dict[str, dict]:
    """Run each effective H3 checkpoint's update policy at most once."""
    checked = set(already_checked or ())
    results: dict[str, dict] = {}
    for model_type in _h3_effective_model_types(body, plan):
        if model_type in checked:
            continue
        checked.add(model_type)
        model_def = wgp.get_model_def(model_type) or {}
        if not (
            isinstance(model_def.get("model_update"), dict)
            or isinstance(model_def.get("component_updates"), list)
        ):
            continue
        results[model_type] = _ensure_versioned_model_current(model_type)
    return results


def _h3_checkpoint_downloaded(model_type: str) -> bool:
    """Include H3's separately declared conditioning encoder in readiness."""
    if not _check_model_downloaded(model_type):
        return False
    model_def = wgp.get_model_def(model_type) or {}
    text_encoder_urls = model_def.get("text_encoder_URLs")
    if isinstance(text_encoder_urls, list) and text_encoder_urls:
        return _variant_group_downloaded(
            text_encoder_urls,
            extra_paths=model_def.get("text_encoder_folder"),
        )
    return True


def _h3_checkpoint_options() -> list[dict]:
    """Describe every managed H3 checkpoint registered by this server.

    Installed state is deliberately independent from catalog presence: a clean
    install must still let the user select a registered checkpoint which the
    ordinary model loader can auto-download. Optional runtimes and mature-only
    checkpoints remain visible but disabled with the server-authored reason.
    """
    mature_allowed = _nsfw_allowed()
    w4a8_capability = None
    options = []
    for model_type in _H3_CHECKPOINT_CATALOG_ORDER:
        model_def = wgp.get_model_def(model_type)
        if not isinstance(model_def, dict):
            continue
        downloaded = _h3_checkpoint_downloaded(model_type)
        urls = model_def.get("URLs")
        managed_download = bool(
            (isinstance(urls, str) and urls.strip())
            or (isinstance(urls, list) and any(
                isinstance(url, str) and url.strip() for url in urls
            ))
        )
        available = True
        unavailable_reason = ""
        if model_def.get("nsfw_only") is True and not mature_allowed:
            available = False
            unavailable_reason = (
                "Requires Explicit mode with recorded consent and a "
                "local/private LLM provider."
            )
        elif model_type == _H3_W4A8_FL2VA_MODEL:
            if w4a8_capability is None:
                from services.h3_acceleration import get_h3_acceleration_status
                w4a8_capability = (
                    get_h3_acceleration_status(probe_kernel=False).get("w4a8")
                    or {}
                )
            if w4a8_capability.get("available") is not True:
                available = False
                unavailable_reason = str(
                    w4a8_capability.get("reason")
                    or "The validated W4A8 runtime is unavailable."
                )
        if available and not downloaded and not managed_download:
            available = False
            unavailable_reason = (
                "Checkpoint is not installed and has no managed download."
            )
        options.append({
            "model_type": model_type,
            "name": str(model_def.get("name") or model_type),
            "conditioning_mode": str(
                model_def.get("minimax_h3_conditioning_mode")
                or (
                    "semantic_references"
                    if model_type == _H3_REF2VA_MODEL
                    else "first_last_frames"
                )
            ),
            "is_downloaded": downloaded,
            "managed_download": managed_download,
            "auto_download": managed_download,
            "terms_required": model_type == _H3_REF2VA_MODEL,
            "mature_only": model_def.get("nsfw_only") is True,
            "available": available,
            "unavailable_reason": unavailable_reason,
        })
    return options


def _h3_generation_requirements(body: dict, plan: dict | None = None) -> dict:
    models = _h3_effective_model_types(body, plan)
    checkpoint_options = _h3_checkpoint_options()
    by_model = {
        str(option.get("model_type") or ""): option
        for option in checkpoint_options
    }
    entries = []
    for model_type in models:
        option = by_model.get(model_type)
        if option is None:
            entries.append({
                "model_type": model_type,
                "is_downloaded": _h3_checkpoint_downloaded(model_type),
                "terms_required": model_type == _H3_REF2VA_MODEL,
                "auto_download": False,
            })
        else:
            entries.append({
                key: option[key]
                for key in (
                    "model_type", "is_downloaded", "terms_required",
                    "auto_download", "available", "unavailable_reason",
                )
            })
    return {
        "models": entries,
        "checkpoint_options": checkpoint_options,
        "ref2va_terms_required": _H3_REF2VA_MODEL in models,
        "all_downloaded": all(entry["is_downloaded"] for entry in entries),
    }


def _require_h3_generation_terms(body: dict, plan: dict | None = None) -> None:
    requirements = _h3_generation_requirements(body, plan)
    if (
        requirements["ref2va_terms_required"]
        and body.get("h3_ref2va_terms_accepted") is not True
    ):
        raise HTTPException(
            status_code=400,
            detail=(
                "This effective H3 plan uses the separately licensed Ref2VA "
                "checkpoint. Review and accept its model terms before submitting."
            ),
        )


def _expand_h3_longform_outputs(
    manifest: list[dict],
    *,
    group_id: str,
    output_count: int,
    base_seed: int,
    allocate_task_id,
) -> list[dict]:
    """Expand segment tasks into independent, variant-major H3 chains."""
    import copy

    output_count = max(1, int(output_count or 1))
    expanded_manifest = []
    for output_index in range(output_count):
        output_group_id = (
            group_id
            if output_count == 1
            else f"{group_id}_output_{output_index + 1}"
        )
        for segment_index, base_task in enumerate(manifest):
            expanded_task = copy.deepcopy(base_task)
            expanded_task["id"] = allocate_task_id()
            expanded_params = expanded_task["params"]
            expanded_params["repeat_generation"] = 1
            if base_seed >= 0:
                expanded_params["seed"] = base_seed + output_index
            expanded_info = expanded_params["multi_clip_info"]
            expanded_info["group_id"] = output_group_id
            expanded_info["output_index"] = output_index
            expanded_info["output_total"] = output_count
            if segment_index == 0:
                expanded_params.pop("_continuation", None)
            expanded_manifest.append(expanded_task)
    return expanded_manifest


def _validate_h3_explicit_multiclip_request(body: dict) -> None:
    """Reject oversized explicit H3 scenes instead of silently clamping."""
    model_type = str(body.get("model_type") or "")
    if (
        model_type not in _H3_LONG_STUDIO_MODELS
        or int(body.get("multi_prompts_gen_type") or 0) != 3
        or body.get("_h3_longform")
    ):
        return
    model_def = wgp.get_model_def(model_type) or {}
    maximum = int(model_def.get("frames_maximum") or 0)
    if maximum <= 0:
        return
    per_clip = body.get("per_clip_frames")
    if isinstance(per_clip, (list, tuple)) and per_clip:
        candidates = per_clip
    else:
        candidates = [
            body.get("sliding_window_size") or body.get("video_length") or 0
        ]
    try:
        oversized = [int(value) for value in candidates if int(value) > maximum]
    except (TypeError, ValueError) as exc:
        raise ValueError("H3 per-clip frame counts must be integers") from exc
    if oversized:
        raise ValueError(
            f"MiniMax H3 clips are limited to {maximum} frames each. "
            "Split oversized Director scenes into consecutive clips; a "
            "single long Studio prompt is segmented automatically."
        )


def _resolve_per_file_update_status(
    lora_id: str,
    file_version_id: int | None,
    lora_max_version: dict[str, int],
    manifest_entry: dict | None,
    filename: str | None = None,
) -> dict:
    """Compute a per-file update status from the manifest + sidecar version.

    The manifest's collective `status` is informative but not authoritative
    for a single file: when a CivitAI LoRA has been updated and the user
    keeps the old file alongside the new one (common when authors change
    naming conventions between releases), both files share a `lora_id` but
    have different `versionId`s. We need to:

      - flag the file that's actually old as `available` so the user sees
        a download prompt for the latest;
      - leave the file that already matches CivitAI's latest as `current`;
      - mark previous-version files as `current` (superseded by another
        file on disk — there's nothing more to download), so we don't keep
        nagging about the same update after the user installs it.

    The result dict mirrors the manifest entry shape so callers can spread
    it directly into their info row.
    """
    out: dict = {
        "update_status": "unknown",
        "latest_version_id": None,
        "current_version_id": file_version_id,
        "latest_published_at": None,
        "latest_changelog": None,
    }
    # System-managed LoRAs (auto-downloaded by the launcher's model code)
    # always report 'current' — there's no user-facing update flow for them
    # and they're tied to specific model versions that the launcher manages.
    if filename and _is_system_managed_lora(filename):
        out["update_status"] = "current"
        return out
    if not isinstance(manifest_entry, dict):
        # No manifest entry yet — local-only LoRAs report 'local',
        # CivitAI-sourced LoRAs that haven't been checked report 'unknown'.
        out["update_status"] = "local" if lora_id.startswith("local:") else "unknown"
        return out
    out["latest_version_id"] = manifest_entry.get("latest_version_id")
    out["latest_published_at"] = manifest_entry.get("latest_published_at")
    out["latest_changelog"] = manifest_entry.get("latest_changelog")
    if manifest_entry.get("status") == "removed":
        out["update_status"] = "removed"
        return out
    # Suppress the badge when CivitAI says the modelId is for a Checkpoint
    # (or any non-LoRA type). Files that land in the LoRA folder but reference
    # a checkpoint-typed model on CivitAI are typically distilled LoRAs that
    # ship bundled with the main model download — there's no per-LoRA update
    # to apply, the user would update the whole checkpoint via a different
    # flow. The file still shows up in listings, just without the "available"
    # status.
    civitai_type = manifest_entry.get("civitai_model_type")
    if isinstance(civitai_type, str) and civitai_type and civitai_type.upper() != "LORA":
        out["update_status"] = "current"
        return out
    latest = out["latest_version_id"]
    if file_version_id is None or latest is None:
        out["update_status"] = "unknown"
        return out
    # File matches or exceeds CivitAI's latest: nothing newer to fetch.
    if file_version_id >= latest:
        out["update_status"] = "current"
        return out
    # File is older than latest, but another file on disk for this same
    # lora_id is the actual newest local copy → this one is superseded
    # (a newer version is already installed). Don't badge.
    if lora_max_version.get(lora_id, 0) > file_version_id:
        out["update_status"] = "current"
        return out
    # Genuinely the only / newest local copy and CivitAI has a newer one.
    out["update_status"] = "available"
    return out


def _build_lora_max_version_map(root: str) -> dict[str, int]:
    """Walk a LoRA directory tree and return `{lora_id: max(versionId)}`
    so the listing endpoints can identify superseded files.

    Only includes LoRAs with a `civitai:`-style lora_id since `local:`
    files don't have versions to compare anyway.
    """
    result: dict[str, int] = {}
    if not root or not os.path.isdir(root):
        return result
    for dirpath, _dirnames, filenames in os.walk(root):
        for f in filenames:
            if not f.endswith((".safetensors", ".sft")):
                continue
            sidecar = os.path.splitext(os.path.join(dirpath, f))[0] + ".civitai.json"
            if not os.path.isfile(sidecar):
                continue
            try:
                with open(sidecar, "r", encoding="utf-8") as sf:
                    meta = json.load(sf)
            except Exception:
                continue
            mid = meta.get("modelId")
            vid = meta.get("versionId")
            if mid is None or vid is None:
                continue
            try:
                lora_id = f"civitai:{int(mid)}"
                vid_i = int(vid)
            except (TypeError, ValueError):
                continue
            if vid_i > result.get(lora_id, 0):
                result[lora_id] = vid_i
    return result


@api.get("/api/v1/loras/installed")
def list_all_installed_loras():
    """List ALL installed LoRAs across all directories with CivitAI metadata.

    Walks the primary loras root PLUS each linked install's loras root
    (issue #16: linked LoRAs never appeared in "My LoRAs" even though the
    guide scan processed them). Same enumeration and mirror convention as
    the scan: linked files are deduped against primary by relative key,
    and their sidecars/guides are read from the PRIMARY MIRROR path first
    (where the scan writes them, since linked installs stay read-only),
    then from beside the file itself.
    """
    lora_root = wgp.server_config.get("loras_root", "loras") if hasattr(wgp, 'server_config') else "loras"
    candidates = [lora_root]
    if not os.path.isabs(lora_root):
        candidates.append(os.path.join(os.path.dirname(__file__), lora_root))
        candidates.append(os.path.join(os.getcwd(), lora_root))
    resolved = None
    for c in candidates:
        if os.path.isdir(c):
            resolved = c
            break
    lora_root = resolved
    if not lora_root:
        return {"loras": []}

    walk_roots = [(lora_root, False)] + [(root, True) for root in _linked_lora_roots()]

    # Read the cached update manifest once per request so each row can
    # surface its update_status without an extra round trip.
    _manifest = _load_lora_manifest()
    _manifest_entries = _manifest.get("entries", {}) if isinstance(_manifest, dict) else {}
    # Pre-compute the highest local versionId per lora_id so per-file
    # status can correctly suppress 'available' on superseded files
    # (older files left over after a newer version was downloaded).
    _lora_max_version = _build_lora_max_version_map(lora_root)

    loras = []
    _seen_keys = set()
    for walk_root, is_linked in walk_roots:
      for dirpath, _dirnames, filenames in os.walk(walk_root):
        for f in filenames:
            if not f.endswith((".safetensors", ".sft")):
                continue
            rel_dir = os.path.relpath(dirpath, walk_root)
            # Dedupe primary vs linked by relative key — primary walks
            # first, so its copy wins (same rule as the scan and the
            # per-model listing endpoints).
            _key = os.path.normcase(os.path.normpath(os.path.join(rel_dir, f)))
            if _key in _seen_keys:
                continue
            _seen_keys.add(_key)
            full_path = os.path.join(dirpath, f)
            own_base = os.path.splitext(full_path)[0]
            # Sidecars/guides for linked files live at the primary-mirror
            # base (scan write target); check it first, then beside the file.
            if is_linked:
                _mirror_base = os.path.normpath(os.path.join(lora_root, rel_dir, os.path.splitext(f)[0]))
                _bases = [_mirror_base, own_base]
            else:
                _bases = [own_base]
            try:
                _size_bytes = os.path.getsize(full_path)
            except OSError:
                _size_bytes = None
            info = {
                "filename": f,
                "directory": rel_dir,
                "linked": is_linked,
                "size_bytes": _size_bytes,
                "trained_words": [],
                "preview_url": None,
                "civitai_model_id": None,
                "has_guide": any(os.path.isfile(b + ".guide.md") for b in _bases),
                "name": None,
                "base_model": None,
                "nsfw": False,
                "downloaded_at": None,
                "released_at": None,
                "lora_id": f"local:{f}",  # overwritten below if sidecar has modelId
            }
            sidecar = next((b + ".civitai.json" for b in _bases if os.path.isfile(b + ".civitai.json")), _bases[0] + ".civitai.json")
            meta = None
            if os.path.isfile(sidecar):
                try:
                    with open(sidecar, "r", encoding="utf-8") as sf:
                        meta = json.load(sf)
                    info["trained_words"] = meta.get("trainedWords", [])
                    info["civitai_model_id"] = meta.get("modelId")
                    info["hf_repo_id"] = meta.get("repoId")
                    info["name"] = meta.get("name")
                    info["base_model"] = meta.get("baseModel")
                    # CivitAI sidecars have carried downloadedAt since the
                    # download path first shipped; publishedAt (the version
                    # release date) is newer — captured at download time and
                    # backfilled for existing files by check-updates.
                    info["downloaded_at"] = meta.get("downloadedAt")
                    info["released_at"] = meta.get("publishedAt")
                    # Manual override (set via /api/v1/loras/nsfw-override)
                    # takes precedence over CivitAI's `nsfw` boolean, which
                    # is sometimes overly conservative (it's "worst content
                    # across the entire model" — set true if any version or
                    # example image is NSFW, even when the LoRA itself is
                    # SFW). Override = bool → use it; Override absent → fall
                    # back to CivitAI's flag.
                    if isinstance(meta.get("nsfw_override"), bool):
                        info["nsfw"] = meta["nsfw_override"]
                        info["nsfw_overridden"] = True
                    else:
                        info["nsfw"] = meta.get("nsfw", False)
                        info["nsfw_overridden"] = False
                    # CivitAI images
                    images = meta.get("images", [])
                    if images and isinstance(images, list) and images[0].get("url"):
                        info["preview_url"] = images[0]["url"]
                    # HuggingFace example media
                    if not info["preview_url"]:
                        example_media = meta.get("exampleMedia", [])
                        if example_media and isinstance(example_media, list):
                            info["preview_url"] = example_media[0]
                except Exception:
                    pass
            # Downloaded-date fallback for HF/hand-installed files without a
            # CivitAI sidecar: the weight file's mtime.
            if not info.get("downloaded_at"):
                try:
                    info["downloaded_at"] = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(os.path.getmtime(full_path)))
                except OSError:
                    info["downloaded_at"] = None
            # Check for local preview files (downloaded from HF)
            if not info.get("preview_url"):
                for _b in _bases:
                    for ext in (".mp4", ".png", ".jpg", ".webp"):
                        preview_file = _b + f"_preview1{ext}"
                        if os.path.isfile(preview_file):
                            info["preview_url"] = f"/api/v1/loras/preview/{os.path.basename(preview_file)}"
                            info["preview_type"] = "video" if ext == ".mp4" else "image"
                            break
                    if info.get("preview_url"):
                        break
            # Infer NSFW from filename + sidecar tags/description + guide
            # text — but only when no authoritative signal exists. Manual
            # override always wins; CivitAI's flag wins over the heuristic;
            # the keyword fallback is only for hand-installed LoRAs without
            # sidecars at all.
            has_override = isinstance(meta, dict) and isinstance(meta.get("nsfw_override"), bool)
            sidecar_has_nsfw_field = isinstance(meta, dict) and "nsfw" in meta
            if not info["nsfw"] and not has_override and not sidecar_has_nsfw_field:
                _meta = meta if os.path.isfile(sidecar) else None
                guide_path = next((b + ".guide.md" for b in _bases if os.path.isfile(b + ".guide.md")), None)
                guide_text = None
                if guide_path:
                    try:
                        with open(guide_path, "r", encoding="utf-8") as gf:
                            guide_text = gf.read()
                    except Exception:
                        guide_text = None
                if _classify_lora_nsfw(filename=f, display_name=info.get("name"),
                                       sidecar_meta=_meta, guide_text=guide_text):
                    info["nsfw"] = True
            # Stable identifier: civitai:{modelId} when available, else local:{filename}.
            # Survives version updates so persisted state (weights, activations,
            # NSFW stash) carries forward automatically.
            info["lora_id"] = _compute_lora_id(f, meta)
            # Per-file update status — uses the cached manifest entry plus
            # this file's own sidecar versionId, so superseded files (older
            # version sitting next to a newer one) don't get falsely flagged
            # as "update available."
            file_vid = None
            if isinstance(meta, dict):
                _v = meta.get("versionId")
                if _v is not None:
                    try:
                        file_vid = int(_v)
                    except (TypeError, ValueError):
                        file_vid = None
            _entry = _manifest_entries.get(info["lora_id"]) if isinstance(_manifest_entries, dict) else None
            info.update(_resolve_per_file_update_status(
                lora_id=info["lora_id"],
                file_version_id=file_vid,
                lora_max_version=_lora_max_version,
                manifest_entry=_entry,
                filename=f,
            ))
            loras.append(info)
    return {"loras": loras, "manifest_last_check_at": _manifest.get("last_full_check_at") if isinstance(_manifest, dict) else None}


def _linked_lora_roots() -> list[str]:
    """Loras folders of every linked install, derived from their ckpts
    roots (the convention get_lora_search_dirs and the guide scan use)."""
    roots = []
    for _linked_ckpts in _get_linked_model_folders():
        _linked_loras = os.path.normpath(os.path.join(os.path.dirname(os.path.abspath(_linked_ckpts)), "loras"))
        if os.path.isdir(_linked_loras):
            roots.append(_linked_loras)
    return roots


def _is_def_bundled_lora(filename: str) -> bool:
    """True when any model definition bundles this LoRA (accelerator
    distills like SCAIL-2 Fast's lightx2v). Deleting one of these only
    triggers a re-download on that model's next generation — the model
    loads it unconditionally. The try is PER model type: one malformed
    def (e.g. a finetune whose "loras" points at a removed base) must
    not abort the scan and fail the guard open for everything after it."""
    base = os.path.normcase(filename)
    for mt in wgp.displayed_model_types:
        try:
            for url in wgp.get_model_recursive_prop(mt, "loras", return_list=True) or []:
                if isinstance(url, str) and os.path.normcase(url.split("/")[-1]) == base:
                    return True
        except Exception:
            continue
    return False


@api.delete("/api/v1/loras/file")
def delete_lora_file(directory: str, filename: str):
    """Delete an installed LoRA plus its sidecar, guide, and preview files.

    Takes the {directory, filename} pair exactly as /loras/installed
    reports it (directory is relative, "." for the root). Only files in
    the primary loras root are deletable — linked installs are read-only,
    same rule as checkpoint deletes.
    """
    if not filename.endswith((".safetensors", ".sft")) or os.path.basename(filename) != filename:
        raise HTTPException(status_code=400, detail="Not a LoRA file.")
    lora_root = _resolve_lora_root()
    if not lora_root:
        raise HTTPException(status_code=500, detail="LoRA folder not found.")
    rel_dir = "" if directory in ("", ".") else directory
    # _safe_join resolves symlinks before the containment check.
    target = _safe_join(os.path.abspath(lora_root), rel_dir, filename) if rel_dir else _safe_join(os.path.abspath(lora_root), filename)
    if target is None:
        raise HTTPException(status_code=400, detail="Invalid path.")
    if not os.path.isfile(target):
        # The same relative key existing only under a linked root means the
        # user clicked delete on a read-only linked copy.
        for _linked_loras in _linked_lora_roots():
            if os.path.isfile(os.path.join(_linked_loras, rel_dir, filename)):
                raise HTTPException(status_code=403, detail="This LoRA lives in a linked model folder, which is read-only. Delete it from that install instead.")
        raise HTTPException(status_code=404, detail=f"LoRA not found: {filename}")
    # Def-bundled only — the fuzzy _is_system_managed_lora patterns
    # over-match user LoRAs whose names merely contain words like
    # "transition" and would make them permanently undeletable.
    if _is_def_bundled_lora(filename):
        raise HTTPException(status_code=409, detail="This LoRA is bundled with a model (a distill/accelerator) and would just re-download on next use. Delete the model instead.")

    from services.win_safe_files import safe_delete
    result = safe_delete(target)
    if not result.get("deleted"):
        raise HTTPException(status_code=423, detail="The file is locked by another process. Try again in a moment.")
    base = os.path.splitext(target)[0]
    extras_removed = []
    extras = [base + ".civitai.json", base + ".guide.md"]
    extras += [base + f"_preview1{ext}" for ext in (".mp4", ".png", ".jpg", ".webp")]
    for extra in extras:
        try:
            if os.path.isfile(extra):
                os.remove(extra)
                extras_removed.append(os.path.basename(extra))
        except OSError:
            pass
    print(f"[LoRA] Deleted {os.path.join(rel_dir, filename) if rel_dir else filename} (+{len(extras_removed)} sidecar files)")
    return {"status": "ok", "deleted": filename, "deferred": bool(result.get("deferred")), "extras_removed": extras_removed}


@api.get("/api/v1/loras/{model_type}")
def list_loras(model_type: str):
    """List available LoRA files for a model type."""
    md = wgp.get_model_def(model_type)
    if md is None:
        raise HTTPException(status_code=404, detail=f"Unknown model: {model_type}")

    try:
        lora_dir = wgp.get_lora_dir(model_type)
    except Exception:
        return {"loras": [], "guidance_max_phases": md.get("guidance_max_phases", 1)}

    if lora_dir is None or not os.path.isdir(lora_dir):
        return {"loras": [], "guidance_max_phases": md.get("guidance_max_phases", 1)}

    # Merge the primary dir with linked read-only dirs (Linked Model
    # Folders' sibling loras/), deduped by filename — so LoRAs from an
    # existing Wan2GP install show up in the Studio selector without
    # copying them.
    names = set()
    for search_dir in wgp.get_lora_search_dirs(model_type):
        for f in glob.glob(os.path.join(search_dir, "*.safetensors")) + glob.glob(os.path.join(search_dir, "*.sft")):
            names.add(os.path.basename(f))
    loras = sorted(names)

    return {
        "loras": loras,
        "guidance_max_phases": md.get("guidance_max_phases", 1),
    }


@api.get("/api/v1/loras/{model_type}/details")
def list_loras_details(model_type: str):
    """List LoRAs with metadata from .civitai.json sidecars."""
    md = wgp.get_model_def(model_type)
    if md is None:
        raise HTTPException(status_code=404, detail=f"Unknown model: {model_type}")
    try:
        lora_dir = wgp.get_lora_dir(model_type)
    except Exception:
        return {"loras": [], "guidance_max_phases": md.get("guidance_max_phases", 1)}
    if lora_dir is None or not os.path.isdir(lora_dir):
        return {"loras": [], "guidance_max_phases": md.get("guidance_max_phases", 1)}

    # Merge across the primary dir and linked read-only dirs (same set as
    # the plain listing endpoint), primary copy wins per filename.
    _seen_names = set()
    files = []
    for _search_dir in wgp.get_lora_search_dirs(model_type):
        for f in sorted(
            glob.glob(os.path.join(_search_dir, "*.safetensors"))
            + glob.glob(os.path.join(_search_dir, "*.sft"))
        ):
            _b = os.path.basename(f)
            if _b in _seen_names:
                continue
            _seen_names.add(_b)
            files.append(f)
    files.sort(key=lambda p: os.path.basename(p))

    # Read the cached update manifest once per request so each row can
    # surface its update_status without an extra round trip.
    _manifest = _load_lora_manifest()
    _manifest_entries = _manifest.get("entries", {}) if isinstance(_manifest, dict) else {}
    # Per-file status needs to know the highest local versionId for each
    # lora_id so we can suppress 'available' on superseded files. Walking
    # just this model-type's lora_dir is enough since multiple versions
    # of the same model live in the same dir.
    _lora_max_version = _build_lora_max_version_map(lora_dir)

    loras = []
    for f in files:
        basename = os.path.basename(f)
        info = {
            "filename": basename,
            "trained_words": [],
            "preview_url": None,
            "civitai_model_id": None,
            "recommended_weights": None,
            "has_guide": False,
            "nsfw": False,
            "downloaded_at": None,
            "released_at": None,
            "lora_id": f"local:{basename}",  # overwritten below if sidecar has modelId
        }
        # Guides and sidecars for LINKED loras are stored in Maestro's own
        # lora dir keyed by the same basename — check there first, then
        # fall back to a sidecar sitting next to the file itself (read-only,
        # e.g. when the linked install is another Maestro/Wan2GP).
        _primary_base = os.path.join(lora_dir, os.path.splitext(basename)[0])
        _own_base = os.path.splitext(f)[0]
        guide_file = next(
            (p for p in (_primary_base + ".guide.md", _own_base + ".guide.md") if os.path.isfile(p)),
            None,
        )
        if guide_file:
            info["has_guide"] = True
            try:
                with open(guide_file, "r", encoding="utf-8") as gf:
                    info["guide"] = gf.read().strip()
            except Exception:
                info["guide"] = None
        # Check for .civitai.json sidecar
        sidecar = next(
            (p for p in (_primary_base + ".civitai.json", _own_base + ".civitai.json") if os.path.isfile(p)),
            _primary_base + ".civitai.json",
        )
        meta = None
        if os.path.isfile(sidecar):
            try:
                with open(sidecar, "r", encoding="utf-8") as sf:
                    meta = json.load(sf)
                info["trained_words"] = meta.get("trainedWords", [])
                info["civitai_model_id"] = meta.get("modelId")
                info["recommended_weights"] = meta.get("recommendedWeights")
                # Same date semantics as /api/v1/loras/installed: downloadedAt
                # is stamped by the download path, publishedAt (version release
                # date) is captured at download and backfilled by check-updates.
                info["downloaded_at"] = meta.get("downloadedAt")
                info["released_at"] = meta.get("publishedAt")
                # Manual override > CivitAI flag > keyword fallback. See
                # /api/v1/loras/installed for full rationale.
                if isinstance(meta.get("nsfw_override"), bool):
                    info["nsfw"] = meta["nsfw_override"]
                    info["nsfw_overridden"] = True
                else:
                    info["nsfw"] = bool(meta.get("nsfw", False))
                    info["nsfw_overridden"] = False
                images = meta.get("images", [])
                if images and isinstance(images, list) and images[0].get("url"):
                    info["preview_url"] = images[0]["url"]
            except Exception:
                meta = None
        # Downloaded-date fallback for HF/hand-installed files without a
        # CivitAI sidecar: the weight file's mtime.
        if not info.get("downloaded_at"):
            try:
                info["downloaded_at"] = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(os.path.getmtime(f)))
            except OSError:
                info["downloaded_at"] = None
        # Fallback: infer NSFW from filename + tags + description + guide
        # only when no authoritative signal exists.
        has_override = isinstance(meta, dict) and isinstance(meta.get("nsfw_override"), bool)
        sidecar_has_nsfw_field = isinstance(meta, dict) and "nsfw" in meta
        if not info["nsfw"] and not has_override and not sidecar_has_nsfw_field:
            if _classify_lora_nsfw(
                filename=basename,
                display_name=(meta.get("name") if isinstance(meta, dict) else None),
                sidecar_meta=meta,
                guide_text=info.get("guide"),
            ):
                info["nsfw"] = True
        # Stable identifier: civitai:{modelId} when available, else local:{filename}.
        info["lora_id"] = _compute_lora_id(basename, meta)
        # Per-file update status (see /api/v1/loras/installed for the
        # equivalent logic). Computes against this file's own sidecar
        # versionId rather than blindly inheriting the manifest's
        # collective status, so superseded files don't keep nagging
        # after the user has already downloaded the new version.
        file_vid = None
        if isinstance(meta, dict):
            _v = meta.get("versionId")
            if _v is not None:
                try:
                    file_vid = int(_v)
                except (TypeError, ValueError):
                    file_vid = None
        _entry = _manifest_entries.get(info["lora_id"]) if isinstance(_manifest_entries, dict) else None
        info.update(_resolve_per_file_update_status(
            lora_id=info["lora_id"],
            file_version_id=file_vid,
            lora_max_version=_lora_max_version,
            manifest_entry=_entry,
            filename=basename,
        ))
        loras.append(info)
    return {
        "loras": loras,
        "guidance_max_phases": md.get("guidance_max_phases", 1),
        "manifest_last_check_at": _manifest.get("last_full_check_at") if isinstance(_manifest, dict) else None,
    }


@api.post("/api/v1/loras/nsfw-override")
async def set_lora_nsfw_override(request: Request):
    """Manually flag a LoRA as SFW or NSFW, overriding CivitAI's nsfw value.

    CivitAI's model-level `nsfw` boolean is "worst content across the model"
    and gets set true if any version or example image is NSFW — even when
    the LoRA itself is SFW. Their browser uses a granular `nsfwLevel` int
    that we don't currently capture, so users with misclassified LoRAs need
    a way to correct the local sidecar.

    Body: `{"filename": "<basename>", "nsfw": true|false|null}`
      - `true` / `false`: write `nsfw_override` to sidecar
      - `null`: clear the override, fall back to CivitAI's flag

    Returns: `{filename, nsfw, nsfw_overridden}` — the new effective state.
    """
    body = await request.json()
    filename = body.get("filename")
    nsfw_value = body.get("nsfw")
    if not isinstance(filename, str) or not filename:
        raise HTTPException(status_code=400, detail="filename is required")
    if nsfw_value is not None and not isinstance(nsfw_value, bool):
        raise HTTPException(status_code=400, detail="nsfw must be true, false, or null")
    # Reject path-traversal — only accept a basename.
    if "/" in filename or "\\" in filename or ".." in filename:
        raise HTTPException(status_code=400, detail="filename must be a basename, not a path")

    lora_root = _resolve_lora_root()
    if not lora_root:
        raise HTTPException(status_code=500, detail="LoRA root not found")

    # Locate the sidecar by walking the tree — LoRAs live in subdirectories
    # by architecture, and the caller doesn't necessarily know which.
    target_safetensors: str | None = None
    for dirpath, _dirnames, filenames in os.walk(lora_root):
        if filename in filenames:
            target_safetensors = os.path.join(dirpath, filename)
            break
    if not target_safetensors:
        raise HTTPException(status_code=404, detail=f"LoRA not found: {filename}")

    sidecar_path = os.path.splitext(target_safetensors)[0] + ".civitai.json"
    if os.path.isfile(sidecar_path):
        try:
            with open(sidecar_path, "r", encoding="utf-8") as sf:
                sidecar = json.load(sf)
            if not isinstance(sidecar, dict):
                sidecar = {}
        except Exception:
            sidecar = {}
    else:
        # Create a minimal sidecar so the override has somewhere to live.
        sidecar = {}

    if nsfw_value is None:
        sidecar.pop("nsfw_override", None)
    else:
        sidecar["nsfw_override"] = bool(nsfw_value)

    try:
        with open(sidecar_path, "w", encoding="utf-8") as sf:
            json.dump(sidecar, sf, indent=2)
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Failed to write sidecar: {e}")

    # Compute the new effective nsfw value (override wins over flag).
    if isinstance(sidecar.get("nsfw_override"), bool):
        effective_nsfw = sidecar["nsfw_override"]
        overridden = True
    else:
        effective_nsfw = bool(sidecar.get("nsfw", False))
        overridden = False
    return {
        "filename": filename,
        "nsfw": effective_nsfw,
        "nsfw_overridden": overridden,
    }


@api.post("/api/v1/loras/check-updates")
def check_lora_updates(force: bool = False):
    """Walk all installed LoRAs, query CivitAI for the latest version of
    each one that has a sidecar `modelId`, and update the manifest with
    the results. Returns a summary the UI can display in a toast.

    Honors a 24h staleness window unless `force=true` is passed: a manifest
    less than 24h old is returned as-is so we don't hammer CivitAI on every
    app start. Uses a small thread pool for parallelism — typical libraries
    of <100 LoRAs finish in a few seconds.
    """
    from datetime import datetime, timezone, timedelta
    from concurrent.futures import ThreadPoolExecutor, as_completed

    lora_root = _resolve_lora_root()
    if not lora_root:
        return {"checked": 0, "updates_available": 0, "errors": ["LoRA root not found"], "skipped": True}

    manifest = _load_lora_manifest()
    now = datetime.now(timezone.utc)
    now_iso = now.strftime("%Y-%m-%dT%H:%M:%SZ")

    if not force and manifest.get("last_full_check_at"):
        try:
            last = datetime.strptime(manifest["last_full_check_at"], "%Y-%m-%dT%H:%M:%SZ").replace(tzinfo=timezone.utc)
            if now - last < timedelta(hours=LORA_MANIFEST_STALE_HOURS):
                avail = sum(1 for e in manifest.get("entries", {}).values() if e.get("status") == "available")
                return {
                    "checked": len(manifest.get("entries", {})),
                    "updates_available": avail,
                    "errors": [],
                    "skipped": True,
                    "reason": "fresh",
                    "last_full_check_at": manifest["last_full_check_at"],
                }
        except HTTPException:
            raise
        except Exception:
            pass

    # Walk all LoRA files and collect (lora_id, model_id, current_version_id).
    targets: list[tuple[str, int, int | None]] = []
    # Every sidecar per model, including superseded-version duplicates the
    # targets list dedupes away — used to backfill publishedAt below.
    sidecars_by_model: dict[int, list[str]] = {}
    for dirpath, _dirnames, filenames in os.walk(lora_root):
        for f in filenames:
            if not f.endswith((".safetensors", ".sft")):
                continue
            # Skip system-managed LoRAs — there's no useful update flow for
            # them and we don't want to waste CivitAI requests on entries
            # that will always render as 'current' anyway.
            if _is_system_managed_lora(f):
                continue
            sidecar = os.path.splitext(os.path.join(dirpath, f))[0] + ".civitai.json"
            if not os.path.isfile(sidecar):
                continue
            try:
                with open(sidecar, "r", encoding="utf-8") as sf:
                    meta = json.load(sf)
            except Exception:
                continue
            model_id = meta.get("modelId")
            if model_id is None:
                continue
            try:
                model_id_int = int(model_id)
            except (TypeError, ValueError):
                continue
            current_v = meta.get("versionId")
            try:
                current_v_int = int(current_v) if current_v is not None else None
            except (TypeError, ValueError):
                current_v_int = None
            sidecars_by_model.setdefault(model_id_int, []).append(sidecar)
            lora_id = f"civitai:{model_id_int}"
            # If multiple files share a modelId (user kept v1 + v2 side by
            # side), we keep the highest current_version_id since that's
            # the one whose update status is most informative.
            existing = next((t for t in targets if t[0] == lora_id), None)
            if existing:
                if (current_v_int or 0) > (existing[2] or 0):
                    targets = [t for t in targets if t[0] != lora_id]
                    targets.append((lora_id, model_id_int, current_v_int))
                continue
            targets.append((lora_id, model_id_int, current_v_int))

    errors: list[str] = []
    new_entries: dict[str, dict] = dict(manifest.get("entries", {}))

    def _backfill_published_at(sidecar_paths: list[str], model_data: dict):
        """Write each version's publishedAt into local sidecars that predate
        publishedAt capture, matched by the sidecar's versionId."""
        versions = {}
        for v in model_data.get("modelVersions", []) or []:
            if isinstance(v, dict) and v.get("id") is not None:
                try:
                    versions[int(v["id"])] = v.get("publishedAt")
                except (TypeError, ValueError):
                    continue
        for path in sidecar_paths:
            try:
                with open(path, "r", encoding="utf-8") as f:
                    meta = json.load(f)
                if meta.get("publishedAt"):
                    continue
                vid = meta.get("versionId")
                published = versions.get(int(vid)) if vid is not None else None
                if not published:
                    continue
                meta["publishedAt"] = published
                with open(path, "w", encoding="utf-8") as f:
                    json.dump(meta, f, indent=2)
            except Exception:
                continue

    def _fetch_one(target):
        lora_id, model_id, current_v = target
        data, status = _civitai_fetch_model(model_id)
        return lora_id, model_id, current_v, data, status

    if targets:
        # Politeness: keep concurrency low so the CivitAI search/detail
        # endpoints stay responsive for the user's other browsing while
        # this runs in the background. Earlier versions used 8 workers
        # which triggered IP-level rate limits and made parallel /search
        # requests time out at 504. With max_workers=2 a 100-LoRA library
        # finishes in ~50 seconds and the public API stays responsive.
        #
        # Early abort: if the first handful of requests all fail (network
        # outage, CivitAI down, our IP rate-limited), stop hammering and
        # let the user retry later via the manual "Check" button.
        consecutive_failures = 0
        FAILURE_THRESHOLD = 5
        with ThreadPoolExecutor(max_workers=2) as pool:
            futures = [pool.submit(_fetch_one, t) for t in targets]
            for fut in as_completed(futures):
                try:
                    lora_id, model_id, current_v, data, status = fut.result()
                except Exception as e:
                    errors.append(str(e))
                    consecutive_failures += 1
                    if consecutive_failures >= FAILURE_THRESHOLD:
                        # Cancel pending futures so the endpoint returns
                        # quickly instead of waiting on doomed retries.
                        for f in futures:
                            f.cancel()
                        errors.append(f"Aborted after {consecutive_failures} consecutive failures")
                        break
                    continue
                if data is None and status not in (404,):
                    # Network error / rate limit. Preserve the previous entry
                    # rather than overwriting it with an `unknown` stub —
                    # the user's existing badge state stays accurate.
                    consecutive_failures += 1
                    if consecutive_failures >= FAILURE_THRESHOLD:
                        for f in futures:
                            f.cancel()
                        errors.append(f"Aborted after {consecutive_failures} consecutive CivitAI failures")
                        break
                    if lora_id in new_entries:
                        continue
                else:
                    consecutive_failures = 0  # reset on any success or 404
                entry = _build_manifest_entry(model_id, current_v, data, status, now_iso)
                new_entries[lora_id] = entry
                # Backfill release dates into sidecars that predate
                # publishedAt capture — the fetched model JSON carries
                # every version's publishedAt, so this is free here.
                if data is not None:
                    _backfill_published_at(sidecars_by_model.get(model_id, []), data)

    # Drop entries for LoRAs that no longer exist on disk (deleted by user).
    live_ids = {t[0] for t in targets}
    new_entries = {k: v for k, v in new_entries.items() if k in live_ids}

    manifest["entries"] = new_entries
    manifest["last_full_check_at"] = now_iso
    manifest["_version"] = LORA_MANIFEST_VERSION
    _save_lora_manifest(manifest)

    updates_available = sum(1 for e in new_entries.values() if e.get("status") == "available")
    return {
        "checked": len(targets),
        "updates_available": updates_available,
        "errors": errors,
        "skipped": False,
        "last_full_check_at": now_iso,
    }


@api.get("/api/v1/loras/update-manifest")
def get_lora_update_manifest():
    """Return the cached manifest without hitting CivitAI. The frontend
    reads this on app start to populate badges immediately, and triggers
    /check-updates separately if the cache is stale."""
    return _load_lora_manifest()


