@api.put("/api/v1/access-context/share-url")
async def register_runtime_share_url(request: Request):
    """Accept the verified public origin reported by this Pinokio launch.

    Pinokio creates the tunnel only after Maestro has printed its loopback
    URL, so the public origin cannot be injected into the server process at
    startup. The launcher always supplies the current Quick Tunnel. A
    ``workers.dev`` redirect is accepted only after the local helper reports
    that its authenticated update and health target both matched that tunnel.
    """

    if _request_is_cloudflare_remote(request):
        raise HTTPException(status_code=403, detail="Runtime share URL registration is local only")
    if not _runtime_share_registration_is_local(request):
        raise HTTPException(status_code=403, detail="Runtime share URL registration requires loopback")
    body = await request.json()
    origin = _canonical_http_origin(str(body.get("share_url") or ""), allow_path=False)
    quick_tunnel = _canonical_http_origin(
        str(body.get("quick_tunnel_url") or ""), allow_path=False,
    )
    if not _is_quick_tunnel_origin(quick_tunnel):
        raise HTTPException(status_code=400, detail="Invalid Cloudflare quick-tunnel URL")
    stable = _is_workers_dev_origin(origin)
    if not (
        (origin == quick_tunnel and _is_quick_tunnel_origin(origin))
        or (stable and body.get("stable_verified") is True)
    ):
        raise HTTPException(status_code=400, detail="Invalid verified Cloudflare share URL")
    global _runtime_share_url
    global _runtime_share_quick_tunnel_url
    global _runtime_share_stable_verified
    with _runtime_share_url_lock:
        _runtime_share_url = origin
        _runtime_share_quick_tunnel_url = quick_tunnel
        _runtime_share_stable_verified = stable
    return {"status": "ok", "share_url": origin}


@api.put("/api/v1/services-config")
async def update_services_config(request: Request):
    """Update services configuration. API keys are stored in full, returned masked."""
    body = await request.json()

    ALLOWED_KEYS = {
        "llm_model_id", "llm_device", "llm_provider", "llm_remote_url",
        "enhance_llm_model_id", "enhance_llm_device",
        "google_api_key", "openai_api_key", "anthropic_api_key",
        "use_director_v2", "nsfw_mode", "nsfw_accepted_at", "director_prompt_polish",
        "civitai_api_key", "voice_reference_enabled", "ltx_progressive_pipeline",
        "show_experimental", "auto_performance", "storage_allow_linked_removal",
        "director_multishot_lora_mode",
        "flashvsr_mode", "flashvsr_topk_ratio", "flashvsr_backend",
    }

    services = wgp.server_config.setdefault("services", {})
    updated = {}

    for key, value in body.items():
        if key not in ALLOWED_KEYS:
            continue
        # Don't overwrite a real key with its masked version
        if key.endswith("_api_key") and value and "..." in value:
            continue
        services[key] = value
        updated[key] = _mask_key(value) if key.endswith("_api_key") else value

    # Enforce: cannot enable NSFW with a public LLM provider
    provider = services.get("llm_provider", "local")
    if services.get("nsfw_mode") and provider in _PUBLIC_LLM_PROVIDERS:
        services["nsfw_mode"] = False
        updated["nsfw_mode"] = False

    if services.get("nsfw_mode"):
        accepted_at = services.get("nsfw_accepted_at")
        if not isinstance(accepted_at, str) or not accepted_at.strip():
            services["nsfw_mode"] = False
            updated["nsfw_mode"] = False
            raise HTTPException(
                status_code=400,
                detail="Explicit mode requires recorded consent before it can be enabled",
            )

    # When switching TO a public provider, auto-disable NSFW
    if "llm_provider" in body and body["llm_provider"] in _PUBLIC_LLM_PROVIDERS:
        if services.get("nsfw_mode"):
            services["nsfw_mode"] = False
            updated["nsfw_mode"] = False

    if not updated:
        raise HTTPException(status_code=400, detail="No valid fields to update")

    wgp.server_config["services"] = services

    with open(wgp.server_config_filename, "w", encoding="utf-8") as f:
        f.write(json.dumps(wgp.server_config, indent=4))

    return {"status": "ok", "updated": updated}


