@api.delete("/api/v1/projects/{project}/assets/{asset_id}/variants/{variant_id}")
def delete_project_asset_variant(
    project: str, asset_id: str, variant_id: str, request: Request,
):
    """Delete one rejected/candidate/kept variant and its copied media."""
    project_id, workspace_id = _asset_scope(request, project)
    _begin_workspace_operation(project_id)
    try:
        _require_project_asset_media_access(
            project_id, workspace_id, asset_id,
            request.state.maestro_session_id, variant_id=variant_id,
        )
        deleted = _project_asset_store().delete_variant(
            project_id, workspace_id, asset_id, variant_id,
        )
    except Exception as error:
        raise _project_asset_error(error) from error
    finally:
        _end_workspace_operation(project_id)
    if not deleted:
        raise HTTPException(status_code=404, detail="Reference variant not found")
    return {"deleted": True, "variant_id": variant_id}


@api.get("/api/v1/projects/{project}/assets/media/{relative_path:path}")
def serve_project_asset_media(project: str, relative_path: str, request: Request):
    project_id, workspace_id = _asset_scope(request, project)
    try:
        path = _project_asset_store().resolve_output_path(
            project_id, workspace_id, relative_path,
        )
    except Exception as error:
        raise _project_asset_error(error) from error
    if not os.path.isfile(path):
        raise HTTPException(status_code=404, detail="Reference media not found")
    authorized = False
    for asset in _project_asset_store().list_assets(project_id, workspace_id):
        for variant in asset.get("variants") or []:
            if not _can_access_project_asset_variant(
                variant, request.state.maestro_session_id,
            ):
                continue
            for output in variant.get("outputs") or []:
                if output.get("relative_path") != relative_path:
                    continue
                policy = output.get("metadata") if isinstance(output.get("metadata"), dict) else {}
                authorized = can_access_output(
                    policy, request.state.maestro_session_id,
                )
                break
    if not authorized:
        raise HTTPException(status_code=404, detail="Reference media not found")
    from services.win_safe_files import share_delete_file_response
    return share_delete_file_response(path)


@api.post("/api/v1/projects/{project}/assets/generate")
async def generate_project_asset_references(project: str, request: Request):
    """Generate one or more candidate reference variants from a card brief."""
    project_id, workspace_id = _asset_scope(request, project)
    body = await request.json()
    model_type = body.get("model_type") or "flux2_klein_9b"
    _require_remote_visible_models(request, [model_type])
    asset_id = body.get("asset_id")
    _begin_workspace_operation(project_id)
    try:
        if asset_id:
            asset = _require_project_asset_media_access(
                project_id, workspace_id, asset_id,
                request.state.maestro_session_id,
            )
        else:
            asset = _project_asset_store().create_asset(
                project_id,
                workspace_id,
                name=body.get("name", "Untitled reference"),
                asset_type=body.get("asset_type", "character"),
                description=body.get("description", ""),
                tags=body.get("tags"),
                provenance="generated",
                metadata={"genre": body.get("genre"), "style": body.get("style")},
            )
            asset_id = asset["id"]
    except Exception as error:
        raise _project_asset_error(error) from error
    finally:
        _end_workspace_operation(project_id)

    candidate_count = max(1, min(8, int(body.get("candidate_count") or 1)))
    variant_parts = [
        str(body.get("poses") or "").strip(),
        str(body.get("outfits") or "").strip(),
        str(body.get("style") or "").strip(),
        str(body.get("genre") or "").strip(),
    ]
    variant_direction = ", ".join(part for part in variant_parts if part)
    asset_type = str(asset.get("asset_type") or "reference")
    prompt = (
        f"Create a production reference sheet for this {asset_type}: "
        f"{asset.get('name')}. {asset.get('description')}. "
        f"{variant_direction}. Clear identity-consistent design, useful for "
        "future image and video conditioning, uncluttered background."
    ).strip()
    generation_params = {
        "model_type": model_type,
        "prompt": prompt,
        "image_mode": 1,
        "image_prompt_type": "",
        "video_prompt_type": "",
        "resolution": body.get("resolution") or "1280x720",
        "num_inference_steps": int(body.get("num_inference_steps") or 8),
        "guidance_scale": float(body.get("guidance_scale") or 1),
        "seed": int(body.get("seed") or -1),
        "settings_version": 2.52,
        "generation_mode": "image",
        "repeat_generation": candidate_count,
        "negative_prompt": str(body.get("negative_prompt") or ""),
        "activated_loras": body.get("activated_loras") or [],
        "loras_multipliers": str(body.get("loras_multipliers") or ""),
        "video_length": 1,
        "private_output": body.get("private_output"),
        "explicit_output": body.get("explicit_output"),
    }
    workspace = project
    job_out_dir = _require_project_access(request, workspace)
    job_id = uuid.uuid4().hex[:8]
    job = {
        "id": job_id,
        "status": "queued",
        "progress": 0,
        "step": 0,
        "total_steps": 0,
        "phase": "",
        "message": "Queued reference generation",
        "created_at": time.time(),
        "params": generation_params,
        "output_files": [],
        "error": None,
        "workspace": workspace,
        "out_dir": job_out_dir,
        "prompt_preview": prompt[:500],
        "model_type": generation_params["model_type"],
        "generation_mode": "image",
    }
    # Reserve before publication so delete cannot interleave between a queued
    # registry entry and the worker taking responsibility for the project.
    _begin_workspace_operation(project_id)

    def _run_and_attach_candidates(_job_id):
        try:
            _run_generation(job_id)
            snapshot = snapshot_job(job)
            if snapshot.get("status") != "completed":
                return
            for index, filename in enumerate(snapshot.get("output_files") or []):
                path = os.path.join(job["out_dir"], filename)
                if not os.path.isfile(path):
                    continue
                try:
                    _project_asset_store().add_variant(
                        project_id,
                        workspace_id,
                        asset_id,
                        variant_type="reference",
                        label=f"Candidate {index + 1}",
                        outputs=[{
                            "source_path": path,
                            "label": variant_direction or "Reference",
                            "metadata": dict(job.get("access_policy") or {}),
                        }],
                        provenance="generated",
                        status="candidate",
                        metadata={"prompt": prompt, "job_id": job_id},
                    )
                except Exception as error:
                    print(f"[ProjectAssets] Could not attach {filename}: {error}")
        finally:
            _end_workspace_operation(project_id)

    try:
        _queue_recovery_register_and_publish(
            job,
            worker=_run_and_attach_candidates,
            recovery_kind="studio_project_asset_preparation",
            thread_name=f"studio-project-asset-{job_id}",
        )
    except Exception:
        _end_workspace_operation(project_id)
        raise
    return {"job_id": job_id, "asset": asset}


# ============================================================================
# API Routes: Blender MCP (pinned, structured, project-scoped)
# ============================================================================

_blender_services: dict[str, object] = {}
_blender_services_lock = threading.RLock()
_blender_scene_lock = threading.RLock()


def _blender_checkout_root() -> str:
    return os.path.join(os.getcwd(), "services", "blender_mcp")


def _blender_runtime_info() -> dict:
    marker = os.path.join(os.getcwd(), "tools", "blender", "runtime.json")
    try:
        from services.blender_mcp_service import read_blender_runtime_info

        return read_blender_runtime_info(marker)
    except (ImportError, OSError, ValueError, TypeError):
        return {}


def _blender_bridge_ready() -> bool:
    try:
        with socket.create_connection(("127.0.0.1", 9876), timeout=0.2):
            return True
    except OSError:
        return False


def _blender_mcp_sdk_ready() -> bool:
    """Return whether this app interpreter can run the standard MCP client."""
    try:
        metadata_module = __import__("importlib.metadata", fromlist=("version",))
        if (
            metadata_module.version("mcp") != "1.12.4"
            or metadata_module.version("blender-mcp") != "1.0.0"
        ):
            return False
        mcp_module = __import__(
            "mcp",
            fromlist=("ClientSession", "StdioServerParameters"),
        )
        stdio_module = __import__(
            "mcp.client.stdio",
            fromlist=("get_default_environment", "stdio_client"),
        )
        required = (
            mcp_module.ClientSession,
            mcp_module.StdioServerParameters,
            stdio_module.get_default_environment,
            stdio_module.stdio_client,
        )
        __import__("blmcp")
        __import__("docutils")
        __import__("yaml")
    except Exception:
        # A present-but-incompatible SDK can fail while importing one of its
        # transitive modules. Status must fail closed and direct repair rather
        # than turning the Blender status endpoint into a 500 response.
        return False
    return all(callable(value) for value in required)


def _blender_readiness(runtime: dict | None = None) -> dict:
    """Return the user-safe installed/ready matrix for hosted Blender."""
    from services.blender_mcp_service import PINNED_INSTALL

    checkout = _blender_checkout_root()
    marker_path = os.path.join(checkout, ".maestro-attested")
    mcp_attested = False
    try:
        with open(marker_path, "r", encoding="utf-8") as handle:
            marker = json.load(handle)
        mcp_attested = bool(
            isinstance(marker, dict)
            and marker.get("repository") == PINNED_INSTALL.repository
            and marker.get("tag") == PINNED_INSTALL.tag
            and marker.get("revision") == PINNED_INSTALL.revision
            and marker.get("package_version") == PINNED_INSTALL.package_version
            and marker.get("transport") == PINNED_INSTALL.transport
            and os.path.isfile(os.path.join(checkout, "mcp", "blmcp", "__init__.py"))
        )
    except (OSError, TypeError, ValueError):
        mcp_attested = False

    runtime = dict(runtime) if isinstance(runtime, dict) else _blender_runtime_info()
    runtime_attested = bool(runtime)
    mcp_sdk_ready = _blender_mcp_sdk_ready()
    bridge_ready = _blender_bridge_ready()
    installed = mcp_attested and runtime_attested
    ready = installed and mcp_sdk_ready and bridge_ready
    if not mcp_attested:
        recovery = (
            "On the Maestro host, open Pinokio → Maestro and run "
            "Verify / Repair Blender MCP Support, then restart Maestro."
        )
    elif not runtime_attested:
        recovery = (
            "On the Maestro host, open Pinokio → Maestro and run "
            "Verify / Repair Blender Runtime, then restart Maestro."
        )
    elif not mcp_sdk_ready:
        recovery = (
            "On the Maestro host, open Pinokio → Maestro and run "
            "Verify / Repair Blender MCP Support, then try again."
        )
    elif not bridge_ready:
        recovery = (
            "On the Maestro host, stop and start Maestro in Pinokio so its "
            "localhost Blender bridge starts."
        )
    else:
        recovery = "Blender is ready."
    return {
        "installed": installed,
        "ready": ready,
        "mcp_attested": mcp_attested,
        "runtime_attested": runtime_attested,
        "mcp_sdk_ready": mcp_sdk_ready,
        "bridge_ready": bridge_ready,
        "recovery_action": recovery,
    }


def _require_blender_ready() -> dict:
    readiness = _blender_readiness()
    if not readiness["ready"]:
        raise HTTPException(status_code=503, detail=readiness["recovery_action"])
    return readiness


def _close_blender_services() -> None:
    with _blender_services_lock:
        services = list(_blender_services.values())
        _blender_services.clear()
    for service in services:
        try:
            service.close()
        except Exception:
            pass


atexit.register(_close_blender_services)


def _blender_service_for(workspace: str, project_root: str):
    """Return one serialized lazy MCP client per validated project."""
    _require_blender_ready()
    checkout = _blender_checkout_root()
    if not os.path.isdir(checkout):
        raise HTTPException(
            status_code=503,
            detail="Blender is not installed. Run Blender setup and try again.",
        )
    with _blender_services_lock:
        service = _blender_services.get(workspace)
        if service is not None:
            return service
        try:
            from services.blender_mcp_service import BlenderMCPService
            from services.blender_mcp_transport import StdioBlenderMCPClient
            client = StdioBlenderMCPClient(
                checkout_root=checkout,
                blender_version=str(
                    os.environ.get("BLENDER_MCP_BLENDER_VERSION")
                    or _blender_runtime_info().get("version")
                    or "5.1.0"
                ),
            )
            service = BlenderMCPService(client, project_root)
        except Exception as error:
            raise HTTPException(
                status_code=503, detail="Blender is unavailable. Restart Maestro and try again.",
            ) from error
        _blender_services[workspace] = service
        return service


def _blender_error(error: Exception) -> HTTPException:
    from services.blender_mcp_service import (
        BlenderMCPCancelled,
        BlenderMCPSecurityError,
        BlenderMCPToolError,
        BlenderMCPValidationError,
    )
    if isinstance(error, BlenderMCPValidationError):
        return HTTPException(status_code=400, detail=str(error))
    if isinstance(error, BlenderMCPCancelled):
        return HTTPException(status_code=409, detail=str(error))
    if isinstance(error, BlenderMCPSecurityError):
        return HTTPException(status_code=503, detail="Blender could not pass its safety check. Run Blender setup or restart Maestro.")
    if isinstance(error, BlenderMCPToolError):
        if "camera" in str(error).lower():
            return HTTPException(
                status_code=503,
                detail=(
                    "Blender could not prepare a camera for this scene. "
                    "Recreate the structured scene, then try rendering again."
                ),
            )
        return HTTPException(status_code=503, detail="Blender could not complete that operation. Restart Blender and try again.")
    return HTTPException(status_code=500, detail="The Blender operation failed")


def _write_blender_preview_sidecar(
    out_dir: str,
    filename: str,
    *,
    workspace: str,
    policy: dict,
    frames: list[int],
    lineage: str,
) -> None:
    sidecar = {
        "params": {
            "edit_sub_mode": "blender_review_sample",
            "sampled_frames": frames,
            "review_only": True,
        },
        "generation_mode": "image",
        "tool": "blender_mcp",
        "artifact_class": "temporary",
        "artifact_lineage": lineage,
        "review_only": True,
        "created_at": time.time(),
        "output_filename": filename,
    }
    stamp_sidecar_policy(sidecar, policy, workspace=workspace)
    meta_path = os.path.join(out_dir, os.path.splitext(filename)[0] + ".meta.json")
    temp_path = f"{meta_path}.{uuid.uuid4().hex[:8]}.tmp"
    try:
        with open(temp_path, "w", encoding="utf-8") as handle:
            json.dump(sidecar, handle, indent=2)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temp_path, meta_path)
    except Exception as error:
        for path in (temp_path, os.path.join(out_dir, filename)):
            try:
                os.remove(path)
            except OSError:
                pass
        raise HTTPException(
            status_code=500,
            detail="Could not publish protected Blender preview metadata",
        ) from error


def _write_blender_video_sidecar(
    out_dir: str,
    filename: str,
    *,
    workspace: str,
    policy: dict,
    lineage: str,
    frame_start: int,
    frame_end: int,
    fps: int,
    review_attempts: int,
    director_model: str,
    control_mode: str,
    semantic_mapping: dict | None = None,
) -> None:
    frame_count = frame_end - frame_start + 1
    sidecar = {
        "params": {
            "edit_sub_mode": "blender_director_reference",
            "frame_start": frame_start,
            "frame_end": frame_end,
            "fps": fps,
            "frame_count": frame_count,
            "duration_seconds": frame_count / fps,
            "review_attempts": review_attempts,
            "video_prompt_type": control_mode,
            "control_reference_fps": "match_generation",
            "ic_lora_attention_strength": 1.0,
            "ic_lora_reference_downscale": 2,
            "semantic_mapping": dict(semantic_mapping or {}),
            "conditioned_prompt": str(
                (semantic_mapping or {}).get("conditioned_prompt") or ""
            ),
            # Official LTX IC-LoRA applies video conditioning in stage 1;
            # stage 2 is an unconditioned refinement pass.
            "ic_lora_stage2_controlled": False,
        },
        "generation_mode": "video",
        "tool": "blender_mcp",
        # Director has approved the render for human review, but only the
        # user's explicit Keep action promotes it into the default gallery.
        "artifact_class": "temporary",
        "artifact_lineage": lineage,
        "director_reviewed": True,
        "director_approved": False,
        "user_review_status": "candidate",
        "director_model": director_model,
        "semantic_mapping": dict(semantic_mapping or {}),
        "created_at": time.time(),
        "output_filename": filename,
    }
    stamp_sidecar_policy(sidecar, policy, workspace=workspace)
    meta_path = os.path.join(out_dir, os.path.splitext(filename)[0] + ".meta.json")
    temp_path = f"{meta_path}.{uuid.uuid4().hex[:8]}.tmp"
    try:
        with open(temp_path, "w", encoding="utf-8") as handle:
            json.dump(sidecar, handle, indent=2)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temp_path, meta_path)
    except Exception as error:
        for path in (temp_path, os.path.join(out_dir, filename)):
            try:
                os.remove(path)
            except OSError:
                pass
        raise HTTPException(
            status_code=500,
            detail="Could not publish protected Blender reference metadata",
        ) from error


def _set_blender_candidate_status(
    project_id: str,
    workspace_id: str,
    asset_id: str,
    variant_id: str,
    status: str,
    *,
    out_dir: str,
    session_id: str,
) -> dict | None:
    """Promote or reject a Blender candidate with sidecar rollback.

    Generic reference variants retain the project-asset store's ordinary
    status behavior.  Blender full-video candidates additionally own a gallery
    sidecar, so the two durable representations must transition together.
    """
    if status not in {"candidate", "kept", "rejected"}:
        raise ValueError("status must be candidate, kept, or rejected")

    from services.win_safe_files import safe_direct_file_under

    store = _project_asset_store()
    with _blender_candidate_status_lock:
        asset = store.get_asset(project_id, workspace_id, asset_id)
        variant = next(
            (
                item for item in asset.get("variants") or []
                if isinstance(item, dict) and item.get("id") == variant_id
            ),
            None,
        )
        if variant is None:
            raise HTTPException(status_code=404, detail="Reference variant not found")
        variant_meta = (
            variant.get("metadata")
            if isinstance(variant.get("metadata"), dict)
            else {}
        )
        if (
            variant.get("variant_type") != "blender_video"
            or variant_meta.get("tool") != "blender_mcp"
        ):
            return None

        current_status = str(variant.get("status") or "candidate")
        if status == current_status:
            return variant
        if current_status != "candidate" or status == "candidate":
            raise HTTPException(
                status_code=409,
                detail="This Blender reference has already been reviewed",
            )

        variant_outputs = variant.get("outputs") or []
        legacy_filename = (
            str(variant_outputs[0].get("filename") or "")
            if len(variant_outputs) == 1 and isinstance(variant_outputs[0], dict)
            else ""
        )
        filename = str(
            variant_meta.get("gallery_output_filename") or legacy_filename
        )
        sidecar_name = os.path.splitext(filename)[0] + ".meta.json"
        sidecar_path = safe_direct_file_under(out_dir, sidecar_name)
        media_path = safe_direct_file_under(out_dir, filename)
        if (
            not filename
            or sidecar_path is None
            or media_path is None
            or not os.path.isfile(sidecar_path)
            or not os.path.isfile(media_path)
        ):
            raise HTTPException(
                status_code=409,
                detail="The Blender review candidate is no longer available",
            )

        try:
            with open(sidecar_path, "rb") as handle:
                original_bytes = handle.read()
            sidecar = json.loads(original_bytes)
        except (OSError, ValueError, TypeError) as error:
            raise HTTPException(
                status_code=409,
                detail="The Blender review candidate metadata is unavailable",
            ) from error
        if (
            not isinstance(sidecar, dict)
            or sidecar.get("tool") != "blender_mcp"
            or sidecar.get("artifact_lineage") != variant_meta.get("artifact_lineage")
        ):
            raise HTTPException(
                status_code=409,
                detail="The Blender review candidate metadata does not match",
            )

        updated_sidecar = dict(sidecar)
        updated_sidecar["artifact_class"] = "final" if status == "kept" else "temporary"
        updated_sidecar["director_reviewed"] = True
        updated_sidecar["director_approved"] = status == "kept"
        updated_sidecar["user_review_status"] = status
        updated_sidecar.pop("approved_at", None)
        updated_sidecar.pop("rejected_at", None)
        updated_sidecar[f"{'approved' if status == 'kept' else 'rejected'}_at"] = time.time()

        requested_explicit = bool(
            variant_meta.get("requested_explicit", sidecar.get("explicit", False))
        )
        requested_private = bool(
            variant_meta.get("requested_private", sidecar.get("private", False))
        )
        final_private = requested_private if status == "kept" else True
        stamp_sidecar_policy(
            updated_sidecar,
            {
                "private": final_private,
                "explicit": requested_explicit,
            },
            workspace=project_id,
        )

        staged = None
        sidecar_published = False
        try:
            staged = _stage_json_replacement(sidecar_path, updated_sidecar)
            # The staged sidecar is not visible yet. Abort with both durable
            # representations unchanged if capability revocation cannot be
            # persisted.
            _revoke_output_shares(project_id, [filename])
            os.replace(staged, sidecar_path)
            staged = None
            sidecar_published = True
            updated_variant = store.set_variant_status(
                project_id, workspace_id, asset_id, variant_id, status,
            )
        except Exception as error:
            rollback_error = None
            if sidecar_published:
                try:
                    _restore_file_bytes(sidecar_path, original_bytes)
                except Exception as restore_error:
                    rollback_error = restore_error
            try:
                persisted = store.get_variant(project_id, workspace_id, asset_id, variant_id)
                if str(persisted.get("status") or "candidate") != current_status:
                    store.set_variant_status(
                        project_id, workspace_id, asset_id, variant_id,
                        current_status,
                    )
            except Exception as restore_error:
                rollback_error = rollback_error or restore_error
            if rollback_error is not None:
                raise HTTPException(
                    status_code=500,
                    detail="Could not safely restore the Blender review candidate",
                ) from rollback_error
            raise HTTPException(
                status_code=500,
                detail="Could not update the Blender review candidate",
            ) from error
        finally:
            if staged:
                try:
                    os.remove(staged)
                except OSError:
                    pass

    return updated_variant


