# API Routes: LLM service
# ============================================================================

@api.get("/api/v1/llm/status")
def llm_status():
    """Get LLM service status."""
    from services import llm_service
    return _truthful_llm_status(llm_service)


def _truthful_llm_status(llm_service) -> dict:
    """Publish a local model as loaded only after health-ready commit.

    ``llama-server`` exists while it is still loading weights, but the runtime
    intentionally commits ``model_id`` and effective ``device`` only after its
    health endpoint reports ready.  Treat that identity-less subprocess state
    as loading so API/UI consumers cannot mistake it for usable inference.
    """
    status = dict(llm_service.get_status())
    runtime = status.get("runtime")
    if isinstance(runtime, dict):
        runtime = dict(runtime)
        if "speed" in runtime:
            runtime["speed"] = _safe_llm_speed(runtime.get("speed"))
        status["runtime"] = runtime
    transient_local_load = bool(
        status.get("provider", "local") == "local"
        and status.get("loaded")
        and (not status.get("model_id") or not status.get("device"))
    )
    if transient_local_load:
        status["loaded"] = False
        status["device"] = None
        status["vision_available"] = False
        status["loading"] = True
        status["loading_phase"] = status.get("loading_phase") or "loading model"
        if isinstance(runtime, dict) and "speed" in runtime:
            runtime["speed"] = _safe_llm_speed(None)
            runtime["speed"]["reason"] = "The selected model is still loading."
    return status


def _safe_llm_speed(speed) -> dict:
    """Normalize content-free runtime speed metadata for browser exposure."""
    unavailable = {
        "prompt_tokens_per_second": None,
        "generation_tokens_per_second": None,
        "source": "unavailable",
        "confidence": "unavailable",
        "reason": "No calibrated measurement is available yet.",
        "sample_count": 0,
        "backend": "unavailable",
    }
    if not isinstance(speed, dict):
        return unavailable
    result = dict(unavailable)
    for key in (
        "prompt_tokens_per_second", "generation_tokens_per_second",
    ):
        value = speed.get(key)
        if (
            isinstance(value, (int, float))
            and not isinstance(value, bool)
            and math.isfinite(value)
            and value > 0
        ):
            result[key] = float(value)
    if speed.get("source") in {
        "measured", "calibrated", "heuristic", "unavailable",
    }:
        result["source"] = speed["source"]
    if speed.get("confidence") in {
        "measured", "high", "medium", "low", "unavailable",
    }:
        result["confidence"] = speed["confidence"]
    reason = speed.get("reason")
    if isinstance(reason, str) and reason.strip():
        # Reasons describe only numeric/model-profile calibration. Bounded text
        # prevents a provider response from becoming a path or prompt oracle.
        result["reason"] = reason.strip()[:240]
    count = speed.get("sample_count")
    if isinstance(count, int) and not isinstance(count, bool) and count >= 0:
        result["sample_count"] = min(count, 1_000_000)
    backend = speed.get("backend")
    if backend in {"cuda", "cpu", "remote", "openai", "anthropic", "unavailable"}:
        result["backend"] = backend
    return result


@api.post("/api/v1/llm/load")
async def llm_load(request: Request):
    """Load the LLM model."""
    from services import llm_service
    body = {}
    if request.headers.get("content-type", "").startswith("application/json"):
        body = await request.json()

    services = wgp.server_config.get("services", {})
    model_id = body.get("model_id", services.get("llm_model_id", _DEFAULT_LLM_REPO))
    device = body.get("device", services.get("llm_device", _llm_default_device()))
    provider = body.get("provider", services.get("llm_provider", "local"))
    remote_url = body.get("remote_url", services.get("llm_remote_url", ""))
    api_key = ""
    if provider == "openai":
        api_key = services.get("openai_api_key", "")
    elif provider == "anthropic":
        api_key = services.get("anthropic_api_key", "")

    try:
        llm_service.load_model(model_id=model_id, device=device, provider=provider, remote_url=remote_url, api_key=api_key)
        return {"status": "ok", **llm_service.get_status()}
    except Exception as e:
        traceback.print_exc()
        raise HTTPException(status_code=500, detail=str(e))


@api.post("/api/v1/llm/unload")
def llm_unload():
    """Unload the LLM model to free memory."""
    from services import llm_service
    llm_service.unload_model()
    return {"status": "ok"}


def _llm_provider_api_key(provider: str, services: dict) -> str:
    if provider == "openai":
        return services.get("openai_api_key", "")
    if provider == "anthropic":
        return services.get("anthropic_api_key", "")
    return ""


def _llm_linked_model_roots() -> list[str]:
    """Return only owner-configured, read-only roots for GGUF discovery."""
    return list(_get_linked_model_folders())


_llm_chat_admission = threading.BoundedSemaphore(1)
_LLM_CHAT_MAX_IMAGES = 4
_LLM_CHAT_MAX_IMAGE_BYTES = 32 * 1024 * 1024
_LLM_CHAT_IMAGE_EXTENSIONS = {
    ".avif", ".bmp", ".gif", ".jpeg", ".jpg", ".png", ".webp",
}
_LLM_CHAT_UPLOAD_MARKER_SUFFIX = ".llm-chat-upload.json"
_LLM_CHAT_UPLOAD_TTL_SECONDS = 24 * 60 * 60
_llm_chat_upload_lock = threading.RLock()
_llm_project_instance_lock = threading.Lock()


def _llm_chat_upload_marker_path(upload_path: str) -> str:
    return f"{upload_path}{_LLM_CHAT_UPLOAD_MARKER_SUFFIX}"


def _read_llm_chat_upload_marker(upload_path: str) -> dict | None:
    try:
        with open(
            _llm_chat_upload_marker_path(upload_path),
            "r",
            encoding="utf-8",
        ) as handle:
            marker = json.load(handle)
    except (OSError, TypeError, ValueError):
        return None
    if not isinstance(marker, dict) or marker.get("version") != 1:
        return None
    if marker.get("kind") != "llm_chat_upload":
        return None
    owner = marker.get("owner_session_id")
    workspace = marker.get("workspace")
    created_at = marker.get("created_at")
    if (
        not isinstance(owner, str)
        or len(owner) != 32
        or any(character not in "0123456789abcdef" for character in owner)
        or not isinstance(workspace, str)
        or not workspace
        or not isinstance(created_at, (int, float))
    ):
        return None
    return marker


def _register_llm_chat_upload(
    request: Request,
    workspace: str,
    filename: str,
) -> None:
    """Mark one direct, private upload as single-use Chat input."""
    from services.win_safe_files import safe_direct_file_under

    root = os.path.join(os.getcwd(), "uploads")
    upload_path = safe_direct_file_under(root, filename)
    owner = str(getattr(request.state, "maestro_session_id", "") or "")
    if (
        upload_path is None
        or not os.path.isfile(upload_path)
        or not can_access_upload(upload_path, owner)
    ):
        raise HTTPException(status_code=404, detail="Chat image not found")
    marker = {
        "version": 1,
        "kind": "llm_chat_upload",
        "owner_session_id": owner,
        "workspace": workspace,
        "created_at": time.time(),
    }
    marker_path = _llm_chat_upload_marker_path(upload_path)
    temp_path = f"{marker_path}.{uuid.uuid4().hex[:8]}.tmp"
    with _llm_chat_upload_lock:
        descriptor = None
        try:
            descriptor = os.open(
                temp_path,
                os.O_WRONLY | os.O_CREAT | os.O_EXCL,
                0o600,
            )
            with os.fdopen(descriptor, "w", encoding="utf-8") as handle:
                descriptor = None
                json.dump(marker, handle)
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(temp_path, marker_path)
        finally:
            if descriptor is not None:
                os.close(descriptor)
            try:
                os.remove(temp_path)
            except OSError:
                pass


def _cleanup_llm_chat_uploads(
    request: Request,
    workspace: str,
    image_paths: list[str],
) -> list[str]:
    """Delete only single-use Chat uploads owned by this project/session."""
    from services.output_access import upload_access_sidecar_path
    from services.win_safe_files import safe_direct_file_under

    root = os.path.join(os.getcwd(), "uploads")
    owner = str(getattr(request.state, "maestro_session_id", "") or "")
    deleted = []
    with _llm_chat_upload_lock:
        for raw_path in image_paths:
            filename = os.path.basename(str(raw_path or ""))
            upload_path = safe_direct_file_under(root, filename)
            if (
                upload_path is None
                or not os.path.isabs(str(raw_path or ""))
                or os.path.normcase(os.path.abspath(str(raw_path)))
                != os.path.normcase(upload_path)
                or not os.path.isfile(upload_path)
            ):
                continue
            marker = _read_llm_chat_upload_marker(upload_path)
            if marker is None:
                continue
            if (
                not hmac.compare_digest(marker["owner_session_id"], owner)
                or marker["workspace"] != workspace
                or not can_access_upload(upload_path, owner)
            ):
                continue
            for path in (
                upload_path,
                upload_access_sidecar_path(upload_path),
                _llm_chat_upload_marker_path(upload_path),
            ):
                try:
                    os.remove(path)
                except OSError:
                    pass
            if not os.path.exists(upload_path):
                deleted.append(filename)
    return deleted


def _prune_stale_llm_chat_uploads() -> None:
    """Bound crash/disconnect leftovers without touching ordinary uploads."""
    from services.output_access import upload_access_sidecar_path
    from services.win_safe_files import safe_direct_file_under

    root = os.path.join(os.getcwd(), "uploads")
    try:
        names = os.listdir(root)
    except OSError:
        return
    cutoff = time.time() - _LLM_CHAT_UPLOAD_TTL_SECONDS
    with _llm_chat_upload_lock:
        for marker_name in names[:4096]:
            if not marker_name.endswith(_LLM_CHAT_UPLOAD_MARKER_SUFFIX):
                continue
            filename = marker_name[:-len(_LLM_CHAT_UPLOAD_MARKER_SUFFIX)]
            upload_path = safe_direct_file_under(root, filename)
            if upload_path is None:
                continue
            marker = _read_llm_chat_upload_marker(upload_path)
            if marker is None or marker["created_at"] >= cutoff:
                continue
            for path in (
                upload_path,
                upload_access_sidecar_path(upload_path),
                _llm_chat_upload_marker_path(upload_path),
            ):
                try:
                    os.remove(path)
                except OSError:
                    pass


def _llm_chat_image_signature(header: bytes) -> bool:
    """Recognize the bounded image formats accepted by Chat."""
    return bool(
        header.startswith(b"\x89PNG\r\n\x1a\n")
        or header.startswith(b"\xff\xd8\xff")
        or header.startswith((b"GIF87a", b"GIF89a", b"BM"))
        or (
            len(header) >= 12
            and header[:4] == b"RIFF"
            and header[8:12] == b"WEBP"
        )
        or (
            len(header) >= 12
            and header[4:8] == b"ftyp"
            and header[8:12] in {b"avif", b"avis"}
        )
    )


@api.post("/api/v1/llm/chat-upload")
async def llm_chat_upload(
    request: Request,
    workspace: str,
    file: UploadFile = File(...),
):
    """Upload one private Chat image without exposing its server path."""
    if _llm_chat_request_is_external(request):
        request.state.maestro_remote = True
    _require_project_access(request, workspace)
    _prune_stale_llm_chat_uploads()
    content_type = str(file.content_type or "").casefold()
    if not content_type.startswith("image/"):
        raise HTTPException(status_code=400, detail="Chat attachments must be images")
    extension = os.path.splitext(str(file.filename or ""))[1].casefold()
    if extension not in _LLM_CHAT_IMAGE_EXTENSIONS:
        raise HTTPException(status_code=400, detail="Unsupported Chat image format")
    declared_size = getattr(file, "size", None)
    if (
        isinstance(declared_size, int)
        and declared_size > _LLM_CHAT_MAX_IMAGE_BYTES
    ):
        raise HTTPException(
            status_code=413,
            detail="Chat image is too large (max 32 MB)",
        )
    if declared_size is None:
        probe = await file.read(_LLM_CHAT_MAX_IMAGE_BYTES + 1)
        await file.seek(0)
        if len(probe) > _LLM_CHAT_MAX_IMAGE_BYTES:
            raise HTTPException(
                status_code=413,
                detail="Chat image is too large (max 32 MB)",
            )
        header = probe[:16]
    else:
        header = await file.read(16)
        await file.seek(0)
    if not _llm_chat_image_signature(header):
        raise HTTPException(
            status_code=400,
            detail="Chat attachment is not a valid image",
        )
    result = await upload_image(request, file, private=True)
    try:
        _register_llm_chat_upload(request, workspace, result["filename"])
    except Exception:
        from services.output_access import upload_access_sidecar_path
        from services.win_safe_files import safe_direct_file_under
        candidate = safe_direct_file_under(
            os.path.join(os.getcwd(), "uploads"),
            result["filename"],
        )
        if candidate and can_access_upload(
            candidate,
            request.state.maestro_session_id,
        ):
            for path in (candidate, upload_access_sidecar_path(candidate)):
                try:
                    os.remove(path)
                except OSError:
                    pass
        raise
    return {
        "filename": result["filename"],
        "url": result["url"],
    }


@api.delete("/api/v1/llm/chat-upload/{filename}")
def delete_llm_chat_upload(
    request: Request,
    filename: str,
    workspace: str,
):
    """Cancel one not-yet-consumed Chat upload owned by this session."""
    if _llm_chat_request_is_external(request):
        request.state.maestro_remote = True
    _require_project_access(request, workspace)
    resolved = _resolve_authorized_request_media(request, filename, workspace)
    deleted = (
        _cleanup_llm_chat_uploads(request, workspace, [resolved])
        if resolved else []
    )
    if not deleted:
        raise HTTPException(status_code=404, detail="Chat image not found")
    return {"deleted": deleted[0]}


def _llm_chat_request_is_external(request: Request) -> bool:
    """Treat Cloudflare and non-loopback LAN clients as remote for Chat."""
    if bool(getattr(request.state, "maestro_remote", False)):
        return True
    peer_host = str(getattr(getattr(request, "client", None), "host", "") or "")
    if peer_host:
        try:
            if not ipaddress.ip_address(peer_host.split("%", 1)[0]).is_loopback:
                return True
        except ValueError:
            if peer_host.casefold() != "localhost":
                return True
    return any(
        not _approved_local_origin(origin)
        for origin in _request_external_origins(request)
    )


def _llm_project_instance_id(request: Request, workspace: str) -> str:
    """Return an opaque identity that changes if a project is recreated."""
    _require_project_access(request, workspace)
    workspace_dir = _existing_workspace_dir(workspace)
    marker_path = os.path.join(workspace_dir, ".llm-chat-instance")

    def read_marker() -> str:
        flags = os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0)
        try:
            descriptor = os.open(marker_path, flags)
            with os.fdopen(descriptor, "r", encoding="ascii") as handle:
                value = handle.read(64).strip()
        except (OSError, UnicodeError):
            return ""
        return value if (
            len(value) == 32
            and all(character in "0123456789abcdef" for character in value)
        ) else ""

    with _llm_project_instance_lock:
        instance = read_marker()
        if not instance:
            instance = uuid.uuid4().hex
            flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
            flags |= getattr(os, "O_NOFOLLOW", 0)
            try:
                descriptor = os.open(marker_path, flags, 0o600)
                with os.fdopen(descriptor, "w", encoding="ascii") as handle:
                    handle.write(instance)
                    handle.flush()
                    os.fsync(handle.fileno())
            except FileExistsError:
                instance = read_marker()
            except OSError as error:
                raise HTTPException(
                    status_code=500,
                    detail="Could not open the project conversation",
                ) from error
        if not instance:
            raise HTTPException(
                status_code=500,
                detail="Could not open the project conversation",
            )

    material = f"llm-chat-project-v1\0{workspace}\0{instance}".encode("utf-8")
    return hmac.new(_session_secret(), material, hashlib.sha256).hexdigest()


def _llm_model_catalog(request: Request, provider: str = "") -> list[dict]:
    """Build a path-free catalog appropriate to this request's authority."""
    from services import llm_service

    services = wgp.server_config.get("services", {})
    remote = _llm_chat_request_is_external(request)
    # A Cloudflare client may inspect only the fixed local catalog. It cannot
    # make Maestro query a configured external provider with machine secrets.
    selected_provider = (
        "local" if remote
        else provider or services.get("llm_provider", "local")
    )
    remote_url = "" if remote else services.get("llm_remote_url", "")
    api_key = (
        "" if remote
        else _llm_provider_api_key(selected_provider, services)
    )
    models = llm_service.get_available_models(
        provider=selected_provider,
        remote_url=remote_url,
        api_key=api_key,
    )
    linked_roots = _llm_linked_model_roots()
    models.extend(llm_service.discover_gguf_models(linked_roots))

    truthful_status = globals().get("_truthful_llm_status")
    status = (
        truthful_status(llm_service)
        if callable(truthful_status)
        else llm_service.get_status()
    )
    desired_device = services.get("llm_device", _llm_default_device())
    safe_fields = {
        "id", "label", "size_hint", "provider", "source", "installed",
        "downloaded", "description", "vision_capable",
        "projector_available", "native_vision", "backend",
        "effective_device",
    }
    safe_profile_fields = {
        "backend", "device", "gpu_layers", "threads", "context_size",
        "threads_batch", "batch_size", "ubatch_size", "flash_attention",
        "cache_type_k", "cache_type_v", "slots", "prompt_cache",
        "projector_offload",
    }
    seen = set()
    catalog = []
    for raw in models:
        model_id = raw.get("id")
        if not isinstance(model_id, str) or not model_id or model_id in seen:
            continue
        seen.add(model_id)
        # Provider catalogs and linked-folder discovery are never allowed to
        # turn the browser catalog into a filesystem oracle.
        item = {key: raw.get(key) for key in safe_fields if key in raw}
        raw_profile = raw.get("runtime_profile")
        if isinstance(raw_profile, dict):
            item["runtime_profile"] = {
                key: raw_profile.get(key)
                for key in safe_profile_fields
                if key in raw_profile
            }
        item["current"] = bool(
            status.get("loaded")
            and status.get("model_id") == model_id
            and status.get("provider") == item.get("provider", "local")
        )
        item["configured"] = bool(
            model_id == services.get(
                "llm_model_id", globals().get("_DEFAULT_LLM_REPO", ""),
            )
            and item.get("provider", "local")
            == services.get("llm_provider", "local")
        )
        item["loaded"] = item["current"]
        item["vision_available"] = (
            bool(status.get("vision_available")) if item["current"] else None
        )
        item.setdefault("downloaded", item.get("provider") != "local")
        item.setdefault(
            "backend",
            "llama.cpp" if item.get("provider", "local") == "local"
            else item.get("provider"),
        )
        item["effective_device"] = (
            status.get("device") if item["current"]
            else item.get("effective_device")
            or (
                desired_device
                if item.get("provider", "local") == "local"
                else item.get("provider")
            )
        )
        download = status.get("download")
        loading_id = (
            status.get("loading_model_id")
            or (download.get("model_id") if isinstance(download, dict) else None)
        )
        item["loading"] = bool(
            status.get("loading")
            and (loading_id == model_id or status.get("model_id") == model_id)
        )
        item["loading_phase"] = (
            status.get("loading_phase") if item["loading"] else None
        )
        if item["current"]:
            runtime = status.get("runtime")
            if isinstance(runtime, dict):
                item["backend"] = runtime.get("backend") or item["backend"]
                effective_profile = runtime.get("effective_profile")
                if isinstance(effective_profile, dict):
                    item["runtime_profile"] = {
                        key: effective_profile.get(key)
                        for key in safe_profile_fields
                        if key in effective_profile
                    }
                    item["effective_device"] = (
                        effective_profile.get("backend")
                        or runtime.get("backend")
                        or item["effective_device"]
                    )
        if item["loading"] and isinstance(download, dict):
            item["download"] = {
                "phase": status.get("loading_phase"),
                "downloaded_bytes": int(download.get("downloaded_bytes") or 0),
                "total_bytes": download.get("total_bytes"),
                "seconds_since_progress": download.get("seconds_since_progress"),
            }
        else:
            item["download"] = None
        speed = None
        if item["current"]:
            runtime = status.get("runtime")
            if isinstance(runtime, dict):
                speed = runtime.get("speed")
        if (
            speed is None
            and item.get("provider", "local") == "local"
            and hasattr(llm_service, "get_model_speed_estimate")
        ):
            local_gguf_path = ""
            if item.get("source") == "Linked model folder":
                try:
                    local_gguf_path = (
                        llm_service.resolve_discovered_gguf(
                            model_id, linked_roots,
                        ) or ""
                    )
                except Exception:
                    local_gguf_path = ""
            try:
                speed = llm_service.get_model_speed_estimate(
                    model_id,
                    local_gguf_path=local_gguf_path,
                    device=(
                        status.get("device") if item["current"]
                        else desired_device
                        if item.get("provider", "local") == "local"
                        else item.get("provider")
                    ) or "auto",
                    multimodal=bool(item.get("vision_capable")),
                )
            except Exception:
                speed = None
        if speed is None and item.get("provider", "local") != "local":
            speed = {
                "source": "unavailable",
                "confidence": "unavailable",
                "reason": "Throughput depends on the external provider.",
                "sample_count": 0,
                "backend": item.get("provider"),
            }
        safe_speed = globals().get("_safe_llm_speed")
        item["speed"] = safe_speed(speed) if callable(safe_speed) else None
        catalog.append(item)
    return catalog


@api.get("/api/v1/llm/models")
def list_llm_models(
    request: Request,
    provider: str = "",
    workspace: str = "",
):
    """Return the safe model catalog and server-owned prompting guides."""
    from services import llm_service
    project_instance = (
        _llm_project_instance_id(request, workspace) if workspace else None
    )
    result = {
        "models": _llm_model_catalog(request, provider),
        "guides": llm_service.get_chat_guides(),
    }
    if project_instance:
        result["project_instance"] = project_instance
    return result


def _resolve_llm_chat_model(request: Request, model_id: str) -> dict:
    """Resolve one authorized catalog/custom selection to runtime arguments."""
    from services import llm_service

    if not isinstance(model_id, str) or not model_id or model_id != model_id.strip():
        raise ValueError("model_id is required")
    services = wgp.server_config.get("services", {})
    remote = _llm_chat_request_is_external(request)
    roots = _llm_linked_model_roots()

    # Remote users get a strict server-owned allowlist: curated models plus
    # opaque IDs for files in linked roots. Hidden registry entries and raw
    # Hugging Face sources remain machine-owner capabilities.
    safe_models = llm_service.get_available_models(provider="local")
    safe_models.extend(llm_service.discover_gguf_models(roots))
    safe_by_id = {item["id"]: item for item in safe_models}
    if remote:
        selected = safe_by_id.get(model_id)
        if selected is None:
            raise ValueError("That LLM is not available for remote chat")
    else:
        configured_provider = services.get("llm_provider", "local")
        available = llm_service.get_available_models(
            provider=configured_provider,
            remote_url=services.get("llm_remote_url", ""),
            api_key=_llm_provider_api_key(configured_provider, services),
        )
        available.extend(llm_service.discover_gguf_models(roots))
        selected = next(
            (item for item in available if item.get("id") == model_id),
            None,
        )

    provider = selected.get("provider", "local") if selected else "local"
    runtime_model_id = model_id
    local_gguf_path = ""
    gguf_file_override = ""
    if model_id.startswith("gguf:"):
        local_gguf_path = llm_service.resolve_discovered_gguf(model_id, roots) or ""
        if not local_gguf_path:
            raise ValueError("That linked GGUF is no longer available")
    elif selected is None:
        runtime_model_id, gguf_file_override = (
            llm_service.normalize_hf_model_source(model_id)
        )

    return {
        "model_id": runtime_model_id,
        "response_model_id": model_id,
        "device": services.get("llm_device", _llm_default_device()),
        "provider": provider,
        "remote_url": (
            services.get("llm_remote_url", "")
            if provider in {"remote", "openai"} else ""
        ),
        "api_key": _llm_provider_api_key(provider, services),
        "local_gguf_path": local_gguf_path,
        "gguf_file_override": gguf_file_override or "",
        "vision_capable": (
            selected.get("vision_capable") if selected is not None else None
        ),
        # This is only a catalog capability hint. Runtime availability is
        # established after the exact model/projector identity is loaded.
        "vision_available": None,
    }


def _resolve_llm_chat_images(
    request: Request,
    body: dict,
    workspace: str,
) -> list[str]:
    """Resolve a bounded set of session/project-authorized Chat images.

    Browser clients submit only upload references.  Local API compatibility
    also permits the existing authorized media forms, but every value passes
    through the same project/session resolver before a model can see it.
    """
    raw_images = body.get("image_paths", [])
    if raw_images in (None, []):
        return []
    if (
        not isinstance(raw_images, list)
        or not 1 <= len(raw_images) <= _LLM_CHAT_MAX_IMAGES
    ):
        raise HTTPException(
            status_code=400,
            detail=f"image_paths must contain at most {_LLM_CHAT_MAX_IMAGES} images",
        )
    resolved: list[str] = []
    for raw in raw_images:
        if not isinstance(raw, str) or not raw.strip():
            raise HTTPException(status_code=400, detail="Invalid Chat image reference")
        image_path = _resolve_authorized_request_media(request, raw, workspace)
        if image_path is None:
            # Keep ownership and existence failures indistinguishable.
            raise HTTPException(status_code=404, detail="Chat image not found")
        resolved.append(image_path)
    return resolved


async def _execute_llm_chat(
    request: Request,
    body: dict,
    image_paths: list[str],
) -> dict:
    """Validate, resolve, and execute one already-authorized Chat turn."""
    from services import llm_service

    try:
        messages = llm_service.validate_chat_messages(body.get("messages"))
        guide_ids, system_prompt = llm_service.load_chat_guides(
            body.get("guide_ids", []),
        )
        selection = _resolve_llm_chat_model(request, body.get("model_id"))
        if image_paths and selection.get("vision_capable") is False:
            raise ValueError("The selected LLM is text only and cannot accept images")
        max_new_tokens = body.get("max_new_tokens", 2048)
        if (
            isinstance(max_new_tokens, bool)
            or not isinstance(max_new_tokens, int)
            or not 1 <= max_new_tokens <= llm_service.CHAT_MAX_NEW_TOKENS
        ):
            raise ValueError(
                "max_new_tokens must be between 1 and "
                f"{llm_service.CHAT_MAX_NEW_TOKENS}"
            )
    except ValueError as error:
        raise HTTPException(status_code=400, detail=str(error)) from error

    try:
        text = await asyncio.to_thread(
            llm_service.generate_chat,
            messages,
            model_id=selection["model_id"],
            device=selection["device"],
            provider=selection["provider"],
            remote_url=selection["remote_url"],
            api_key=selection["api_key"],
            local_gguf_path=selection["local_gguf_path"],
            gguf_file_override=selection["gguf_file_override"],
            system_prompt=system_prompt,
            max_new_tokens=max_new_tokens,
            image_paths=image_paths,
        )
    except ValueError as error:
        raise HTTPException(status_code=400, detail=str(error)) from error
    except Exception as error:
        traceback.print_exc()
        detail = (
            "LLM chat failed; check the local Maestro logs"
            if bool(getattr(request.state, "maestro_remote", False))
            else str(error)
        )
        raise HTTPException(status_code=500, detail=detail) from error
    return {
        "text": text,
        "model_id": selection["response_model_id"],
        "guide_ids": guide_ids,
    }


@api.post("/api/v1/llm/chat")
async def llm_chat(request: Request):
    """Run one bounded, project-authorized LLM Chat turn."""
    body = await request.json()
    if not isinstance(body, dict):
        raise HTTPException(status_code=400, detail="JSON object body is required")
    workspace = body.get("workspace")
    if not isinstance(workspace, str) or not workspace.strip():
        raise HTTPException(status_code=400, detail="workspace is required")

    # PINOKIO_SHARE_LOCAL clients are external even though the broader legacy
    # middleware reserves `maestro_remote` for Cloudflare. Promote only this
    # request before the shared project guard/model resolver run.
    if _llm_chat_request_is_external(request):
        request.state.maestro_remote = True
    # Authorization happens before guide/model resolution or any download.
    _require_project_access(request, workspace)
    image_paths = (
        _resolve_llm_chat_images(request, body, workspace)
        if "image_paths" in body else []
    )
    cleanup_chat_uploads = globals().get("_cleanup_llm_chat_uploads")

    if not _llm_chat_admission.acquire(blocking=False):
        if callable(cleanup_chat_uploads):
            cleanup_chat_uploads(request, workspace, image_paths)
        raise HTTPException(
            status_code=429,
            detail="Another LLM chat turn is already running; retry shortly",
        )
    execution = asyncio.create_task(
        _execute_llm_chat(request, body, image_paths),
    )
    def finish_chat_turn(_finished) -> None:
        try:
            if callable(cleanup_chat_uploads):
                cleanup_chat_uploads(request, workspace, image_paths)
        finally:
            _llm_chat_admission.release()
    try:
        # Keep the worker and its admission slot alive if a client disconnects;
        # cancelling to_thread does not stop its underlying model inference.
        return await asyncio.shield(execution)
    finally:
        if execution.done():
            finish_chat_turn(execution)
        else:
            execution.add_done_callback(finish_chat_turn)


@api.get("/api/v1/llm/stream-status")
def llm_stream_status():
    """Return current LLM streaming state for real-time display."""
    from services import llm_service
    return llm_service.get_stream_status()


def _ensure_llm_loaded():
    """Auto-load LLM if not already loaded. Reloads if configured model changed."""
    from services import llm_service
    services = wgp.server_config.get("services", {})
    desired = services.get("llm_model_id", _DEFAULT_LLM_REPO)
    desired_device = services.get("llm_device", _llm_default_device())
    desired_provider = services.get("llm_provider", "local")
    desired_remote_url = services.get("llm_remote_url", "")
    desired_api_key = ""
    if desired_provider == "openai":
        desired_api_key = services.get("openai_api_key", "")
    elif desired_provider == "anthropic":
        desired_api_key = services.get("anthropic_api_key", "")

    # load_model owns the complete idempotence key: model bytes, projector,
    # device, endpoint, runtime binary, flags, and performance profile.
    llm_service.load_model(
        model_id=desired,
        device=desired_device,
        provider=desired_provider,
        remote_url=desired_remote_url,
        api_key=desired_api_key,
    )


@api.post("/api/v1/llm/generate")
async def llm_generate(request: Request):
    """Generate text with the local LLM."""
    from services import llm_service
    body = await request.json()

    prompt = body.get("prompt", "")
    if not prompt:
        raise HTTPException(status_code=400, detail="prompt is required")

    _ensure_llm_loaded()

    try:
        result = llm_service.generate(
            prompt=prompt,
            system_prompt=body.get("system_prompt", ""),
            max_new_tokens=body.get("max_new_tokens", 256),
            temperature=body.get("temperature", 0.7),
            top_p=body.get("top_p", 0.9),
            seed=body.get("seed"),
        )
        return {"text": result}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


# --- Music: LLM song-writer (Music mode Simple) ---

# The song-writer system prompts live in editable guide files (loaded via
# services.guide_loader.load_guide at request time, cached after first read):
#   app/services/llm_guides/music/song_writer.md            (vocals)
#   app/services/llm_guides/music/song_writer_instrumental.md
# Edit those to tune the prompt without touching code. These short fallbacks are
# only used if a guide file is missing/unreadable.
_SONG_WRITER_FALLBACK = (
    "You are a songwriter for ACE-Step 1.5. From the user's brief, output EXACTLY "
    "two sections and nothing else:\n[STYLE]\nA dense prose paragraph describing "
    "genre, instruments, mood, production, and vocal type (no numeric BPM/key).\n"
    "[LYRICS]\nOriginal lyrics with [Verse]/[Chorus]/[Bridge] section tags on their "
    "own lines, ~6-10 syllables per line. Keep STYLE and LYRICS consistent."
)
_SONG_WRITER_FALLBACK_INSTRUMENTAL = (
    "You are a music producer for ACE-Step 1.5. Output EXACTLY two sections:\n"
    "[STYLE]\nA dense prose paragraph describing genre, instruments, mood, "
    "production, and energy — instrumental, no vocals, no numeric BPM/key.\n"
    "[LYRICS]\n[Instrumental]"
)


def _parse_song_output(raw, instrumental):
    """Split the song-writer LLM output into (style, lyrics)."""
    import re as _re
    text = str(raw or "").strip()
    style, lyrics = "", ""
    sm = _re.search(r"\[STYLE\](.*?)(?=\[LYRICS\]|\Z)", text, _re.IGNORECASE | _re.DOTALL)
    lm = _re.search(r"\[LYRICS\](.*)\Z", text, _re.IGNORECASE | _re.DOTALL)
    if sm:
        style = sm.group(1).strip()
    if lm:
        lyrics = lm.group(1).strip()
    if not style and not lyrics:
        # LLM ignored the format — keep the whole thing as lyrics.
        lyrics = text
    if instrumental:
        lyrics = "[Instrumental]"
    return style, lyrics


@api.post("/api/v1/llm/write-song")
async def llm_write_song(request: Request):
    """Music-mode Simple writer: from a free-text description, produce a Music
    Caption (style tags) + structured lyrics for ACE-Step. Returns
    {style, lyrics, raw}."""
    from services import llm_service
    body = await request.json()
    description = (body.get("description") or "").strip()
    if not description:
        raise HTTPException(status_code=400, detail="description is required")
    instrumental = bool(body.get("instrumental"))

    # Optional reference image → the vision LLM lets the visuals inform the
    # STYLE (e.g. neon cityscape → synthwave). Degrades gracefully: if the
    # loaded LLM has no vision (mmproj), llm_service.generate ignores images.
    image_paths = body.get("image_paths") or []
    if not image_paths and body.get("reference_image_path"):
        image_paths = [body["reference_image_path"]]
    workspace = body.get("workspace") or _get_active_workspace()
    image_paths = [
        resolved for path in image_paths
        if (resolved := _resolve_authorized_request_media(
            request, path, workspace,
        ))
    ]

    _ensure_llm_loaded()
    from services.guide_loader import load_guide
    if instrumental:
        system_prompt = load_guide("music", "song_writer_instrumental") or _SONG_WRITER_FALLBACK_INSTRUMENTAL
    else:
        system_prompt = load_guide("music", "song_writer") or _SONG_WRITER_FALLBACK
    try:
        raw = llm_service.generate(
            prompt=description,
            system_prompt=system_prompt,
            max_new_tokens=body.get("max_new_tokens", 1024),
            temperature=body.get("temperature", 0.85),
            top_p=body.get("top_p", 0.9),
            seed=body.get("seed"),
            image_paths=image_paths or None,
        )
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))
    style, lyrics = _parse_song_output(raw, instrumental)
    return {"style": style, "lyrics": lyrics, "raw": raw}


def _build_music_gen_params(model_type: str, lyrics: str, style: str, duration_seconds, seed) -> dict:
    """Build an ACE-Step generation params dict by seeding from the model's
    OWN default settings — the exact same source the Studio Music UI starts
    from (served via /api/v1/models/{model_type} → wgp.get_default_settings).
    This guarantees parity: every model-specific field the ACE-Step pipeline
    needs (LM sampling temperature/top_k/top_p, audio_scale, scheduler_type,
    shift, num_inference_steps, etc.) is present. A hand-built subset omitted
    the LM sampling fields, which made the XL "Strong Think" LM path fail with
    'NoneType object does not support item assignment'. We override only the
    song content, duration, and seed, then force audio-only generation."""
    try:
        params = dict(wgp.get_default_settings(model_type) or {})
    except Exception as e:
        print(f"[generate-music] get_default_settings failed for {model_type}: {e}")
        params = {}
    params["model_type"] = model_type
    params["prompt"] = lyrics or "[Instrumental]"
    params["alt_prompt"] = style or ""
    params.setdefault("negative_prompt", "")
    if duration_seconds:
        try:
            params["duration_seconds"] = float(duration_seconds)
        except (TypeError, ValueError):
            pass
    try:
        params["seed"] = int(seed)
    except (TypeError, ValueError):
        params["seed"] = -1
    # Force audio-only, single-prompt generation (no video output).
    params["video_length"] = 0
    params["image_mode"] = 0
    params["multi_prompts_gen_type"] = 2
    params["generation_mode"] = "audio"
    return params


@api.post("/api/v1/director/preparation")
async def director_preparation_start(request: Request):
    """Issue the durable request id before a long music/analysis chain."""
    body = await request.json()
    workspace = body.get("workspace") or _get_active_workspace()
    image_paths = body.get("image_paths") or []
    if not image_paths and body.get("reference_image_path"):
        image_paths = [body["reference_image_path"]]
    image_paths = [
        resolved for path in image_paths
        if (resolved := _resolve_authorized_request_media(
            request, path, workspace,
        ))
    ]
    project_dir = _require_project_access(request, workspace)
    durable_request = dict(body)
    durable_request["workspace"] = workspace
    durable_request["image_paths"] = list(image_paths)
    durable_request.pop("reference_image_path", None)
    request_id, state = _register_director_preparation(
        request, durable_request, workspace, project_dir,
    )
    return {
        "director_request_id": request_id,
        "status": str(state.get("status") or "running"),
        "phase": str(state.get("phase") or "registered"),
        "next_action": "generate_music",
        "actions": ["generate_music"],
    }


@api.post("/api/v1/director/generate-music")
async def director_generate_music(request: Request):
    """Generate a music track for Director Music Video mode. Dual-mode:
      - If `style`/`lyrics` are supplied, render them directly.
      - Else if `description` is supplied, write the song first (optionally
        informed by a reference image via the vision LLM), then render.
    Blocks until the track is rendered (consistent with the awaited
    upload→analyze→plan-structure chain) and returns the ABSOLUTE
    {audio_path} so the frontend can feed it straight into /audio/analyze.
    Returns {audio_path, filename, style, lyrics}."""
    import asyncio
    body = await request.json()
    description = (body.get("description") or "").strip()
    style = (body.get("style") or "").strip()
    lyrics = (body.get("lyrics") or "").strip()
    instrumental = bool(body.get("instrumental"))
    model_type = body.get("model_type") or "ace_step_v1_5_xl_sft_lm_4b"
    duration_seconds = body.get("duration_seconds")
    seed = body.get("seed")
    workspace = body.get("workspace") or _get_active_workspace()
    if not body.get("director_request_id") and wgp.get_model_def(model_type) is None:
        raise HTTPException(status_code=400, detail=f"Unknown model: {model_type}")

    image_paths = body.get("image_paths") or []
    if not image_paths and body.get("reference_image_path"):
        image_paths = [body["reference_image_path"]]
    image_paths = [
        resolved for path in image_paths
        if (resolved := _resolve_authorized_request_media(
            request, path, workspace,
        ))
    ]

    out_dir = _require_project_access(request, workspace)
    durable_request = dict(body)
    durable_request["workspace"] = workspace
    durable_request["image_paths"] = list(image_paths)
    durable_request.pop("reference_image_path", None)
    request_id, preparation = _register_director_preparation(
        request, durable_request, workspace, out_dir,
    )
    saved_request = preparation.get("request")
    if isinstance(saved_request, dict):
        description = str(
            saved_request.get("description") or description
        ).strip()
        style = str(saved_request.get("style") or style).strip()
        lyrics = str(saved_request.get("lyrics") or lyrics).strip()
        instrumental = bool(
            saved_request.get("instrumental", instrumental)
        )
        model_type = str(saved_request.get("model_type") or model_type)
        duration_seconds = saved_request.get(
            "duration_seconds", duration_seconds,
        )
        seed = saved_request.get("seed", seed)
        saved_images = saved_request.get("image_paths")
        if isinstance(saved_images, list):
            image_paths = list(saved_images)
    _require_remote_visible_models(request, [model_type])
    if wgp.get_model_def(model_type) is None:
        raise HTTPException(status_code=400, detail=f"Unknown model: {model_type}")
    _checkpoint_director_preparation(
        request_id,
        out_dir,
        phase=(
            "song_writing"
            if description and (not style or not lyrics)
            else "music_queued"
        ),
    )

    if instrumental:
        lyrics = "[Instrumental]"

    # Write the song from the description when we don't already have content.
    if (not style or not lyrics) and description:
        from services import llm_service
        from services.guide_loader import load_guide
        _ensure_llm_loaded()
        if instrumental:
            system_prompt = load_guide("music", "song_writer_instrumental") or _SONG_WRITER_FALLBACK_INSTRUMENTAL
        else:
            system_prompt = load_guide("music", "song_writer") or _SONG_WRITER_FALLBACK
        try:
            raw = await asyncio.to_thread(
                llm_service.generate,
                prompt=description,
                system_prompt=system_prompt,
                max_new_tokens=body.get("max_new_tokens", 1024),
                temperature=body.get("temperature", 0.85),
                top_p=body.get("top_p", 0.9),
                seed=body.get("seed"),
                image_paths=image_paths or None,
            )
        except Exception as e:
            raise HTTPException(status_code=500, detail=f"Song writing failed: {e}")
        w_style, w_lyrics = _parse_song_output(raw, instrumental)
        style = style or w_style
        lyrics = lyrics or w_lyrics

    with _director_preparation_lock:
        current_preparation = dict(
            _director_preparation_states.get(request_id) or {}
        )
    current_request = dict(current_preparation.get("request") or durable_request)
    current_request.update({"style": style, "lyrics": lyrics})
    _checkpoint_director_preparation(
        request_id, out_dir,
        phase="music_queued",
        request=current_request,
    )

    if not lyrics:
        raise HTTPException(status_code=400, detail="Provide a description, or style + lyrics")

    gen_params = _build_music_gen_params(model_type, lyrics, style, duration_seconds, seed)
    mature_output = _classify_generation_maturity(gen_params)

    music_policy = _http_output_policy_from_request(
        body,
        mature_output=mature_output,
        owner_session_id=request.state.maestro_session_id,
    )
    gen_params["_maestro_access_policy"] = music_policy
    gen_params["_maestro_session_id"] = request.state.maestro_session_id
    gen_params["_director_request_id"] = request_id
    gen_params["_director_recovery_parent_id"] = request_id
    gen_params["_director_recovery_unit"] = {
        "kind": "prepipeline_music",
        "variant": 0,
        "index": 0,
    }

    # Wire director_pipeline's shared refs (_jobs / _run_generation / _gen_lock)
    # before using _submit_and_wait — without this they're None and the first
    # line `_jobs[job_id] = job` raises "'NoneType' object does not support
    # item assignment". Every other _submit_and_wait caller calls this first.
    _init_pipeline()
    from services.director_pipeline import _submit_and_wait
    try:
        output_files = await asyncio.to_thread(
            _submit_and_wait,
            gen_params,
            timeout_s=1800,
            workspace=workspace,
            out_dir=out_dir,
        )
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Music generation failed: {e}")
    if not output_files:
        raise HTTPException(status_code=500, detail="Music generation produced no output")

    filename = output_files[0]
    audio_path = os.path.join(out_dir, filename)
    music_evidence = None
    for candidate in list(_jobs.values()):
        candidate_params = candidate.get("params") or {}
        if (
            candidate.get("kind") != "director_child"
            or candidate_params.get("_director_request_id") != request_id
        ):
            continue
        verified = _director_recovery_verified_child(candidate, out_dir)
        if (
            isinstance(verified, dict)
            and filename in (verified.get("outputs") or [])
        ):
            music_evidence = verified
            break
    if music_evidence is None:
        raise HTTPException(
            status_code=500,
            detail="Music generation recovery evidence is incomplete",
        )
    _checkpoint_director_preparation(
        request_id, out_dir,
        phase="music_completed",
        music={"filename": filename, "evidence": music_evidence},
    )
    return {
        "director_request_id": request_id,
        "audio_path": filename if bool(getattr(request.state, "maestro_remote", False)) else audio_path,
        "filename": filename,
        "style": style,
        "lyrics": lyrics,
    }


@api.post("/api/v1/llm/enhance-prompt")
async def llm_enhance_prompt(request: Request):
    """Enhance a generation prompt. Routes to Wan2GP enhancer or local LLM based on config."""
    body = await request.json()

    prompt = body.get("prompt", "")
    if not prompt:
        raise HTTPException(status_code=400, detail="prompt is required")

    workspace = body.get("workspace") or _get_active_workspace()
    requested_image_paths = body.get("image_paths") or []
    if not requested_image_paths and body.get("image_path"):
        requested_image_paths = [body["image_path"]]
    authorized_image_paths = [
        resolved for path in requested_image_paths
        if (resolved := _resolve_authorized_request_media(
            request, path, workspace,
        ))
    ]

    model_type = str(body.get("model_type", "") or "")
    generation_mode = str(body.get("mode", "video") or "video")
    needs_h3_context_ir = (
        model_type.lower().startswith("minimax_h3")
        and generation_mode in ("video", "avatar")
    )
    enhancer_enabled = int(wgp.server_config.get("enhancer_enabled", 0) or 0)

    # The generic Wan2GP cinematic enhancer cannot produce MiniMax H3's
    # required Context-IR fields, speaker IDs, or <d> dialogue tags. Route H3
    # through Maestro's model-specific guide even when the legacy enhancer is
    # enabled; all other model families retain the configured behavior.
    if enhancer_enabled > 0 and not needs_h3_context_ir:
        try:
            # Support both single image_path and array image_paths
            return await _enhance_with_wangp(
                prompt,
                generation_mode,
                enhancer_enabled,
                image_paths=authorized_image_paths,
            )
        except Exception as e:
            print(f"[Enhance] Wan2GP enhancer failed, falling back to LLM: {e}")
            # Fall through to LLM
    elif enhancer_enabled > 0 and needs_h3_context_ir:
        print("[Enhance] MiniMax H3 requires structured Context-IR; using Maestro's model-specific LLM guide")

    # Use our local LLM service
    from services import llm_service

    services = wgp.server_config.get("services", {})
    provider = services.get("llm_provider", "local")
    nsfw = services.get("nsfw_mode", False) and provider not in _PUBLIC_LLM_PROVIDERS

    # Check if a separate enhance LLM is configured
    enhance_model = services.get("enhance_llm_model_id", "")
    enhance_device = services.get("enhance_llm_device", "cuda")

    # Per-model dedicated prompt enhancer: when the active gen model declares
    # `prompt_enhancer_model` (e.g. Sulphur ships its own uncensored enhancer
    # LLM), it takes precedence and runs in raw-passthrough mode — the user's
    # prompt (+ optional image) is sent with NO guide/system prompt because the
    # model is trained to enhance directly. nsfw_only gen models are already
    # gated to Mature Mode, so no extra gate is needed here.
    raw_enhancer_mode = False
    _enh_mt = body.get("model_type", "")
    if _enh_mt:
        try:
            _md = wgp.get_model_def(_enh_mt)
            _pe = (_md or {}).get("prompt_enhancer_model")
            if _pe:
                enhance_model = _pe
                raw_enhancer_mode = True
                print(f"[Enhance] Per-model enhancer for {_enh_mt}: {_pe} (raw passthrough)")
        except Exception as e:
            print(f"[Enhance] Per-model enhancer lookup failed: {e}")

    if enhance_model:
        # Load the enhance-specific LLM (may differ from Director LLM)
        def _prepare_enhance_model():
            llm_service.load_model(
                model_id=enhance_model,
                device=enhance_device,
            )
        await asyncio.to_thread(_prepare_enhance_model)
    else:
        # Use the Director LLM (default)
        await asyncio.to_thread(_ensure_llm_loaded)

    # Collect image paths for vision-enabled LLM
    llm_image_paths = authorized_image_paths

    # Load LoRA info for activated LoRAs — extract ONLY trigger words and key tips
    lora_hint_text = ""
    activated_loras = body.get("activated_loras") or []
    print(f"[Enhance] LoRA check: activated_loras={activated_loras}, model_type={model_type}")
    if activated_loras and model_type:
        try:
            lora_dir = wgp.get_lora_dir(model_type)
            print(f"[Enhance] LoRA dir: {lora_dir}")
            # Only inject trigger words from the CivitAI sidecar's
            # trainedWords field. Do NOT extract triggers from guide prose —
            # guide descriptions like "include the trigger phrase 'Unchained'"
            # are instructions for the user, not actual trained tokens, and
            # injecting them causes the LLM to insert them as broken tags.
            trigger_lines = []
            for lora_name in activated_loras:
                sidecar_path = os.path.join(lora_dir, os.path.splitext(lora_name)[0] + ".civitai.json")
                trigger_words = []
                if os.path.isfile(sidecar_path):
                    try:
                        with open(sidecar_path, "r", encoding="utf-8") as sf:
                            sidecar = json.loads(sf.read())
                        trigger_words = sidecar.get("trainedWords", []) or []
                    except Exception:
                        pass

                if trigger_words:
                    trigger_lines.append(f"- {', '.join(trigger_words[:5])}")
                print(f"[Enhance] LoRA '{lora_name}': triggers={trigger_words[:3]}, sidecar={os.path.isfile(sidecar_path)}")

            if trigger_lines:
                any_leet = any(any(c.isdigit() for c in ln) for ln in trigger_lines)
                leet_block = (
                    " Some trigger words are coded tokens with letters replaced by "
                    "numbers (e.g. 'o'→'0', 'i'→'1', 's'→'5', 'e'→'3', 'a'→'4'). "
                    "If you see one with digits, copy it EXACTLY as written — do "
                    "not decode it into plain English."
                ) if any_leet else ""
                lora_hint_text = (
                    "\n\n[LORA TRIGGER WORDS — these are exact tokens the model was "
                    "trained on. Pick the ONE most relevant trigger and include it "
                    "somewhere in the prompt IF AND ONLY IF it forms a natural, "
                    "grammatical part of a sentence. If you cannot weave it in "
                    "naturally, OMIT IT ENTIRELY.\n\n"
                    "FORBIDDEN INSERTION PATTERNS (any of these ruins the prompt):\n"
                    "- At the start as a standalone tag:  'Unchained, the doctor...'\n"
                    "- As a comma-offset appositive:      'the doctor, Unchained, in white...'\n"
                    "- As a parenthetical:                'the doctor (Unchained) in white...'\n"
                    "- As a standalone label anywhere:    '...in the exam room. Unchained. She...'\n"
                    "- Attached to an unrelated character: 'the doctor, Mystic XXX, leans...'\n\n"
                    "ACCEPTABLE INSERTIONS only if grammatically natural:\n"
                    "- Body/appearance descriptor trigger ('detailed muscle definition'): "
                    "scoped to the right character inside a sentence — "
                    "'the man with detailed muscle definition lifts the crate...'\n"
                    "- Style tag trigger ('Mystic XXX', 'Unchained'): use only when the "
                    "trigger names a genre or action the scene actually depicts. If it "
                    "does not fit grammatically, OMIT IT. Do not force it in.\n\n"
                    "Do NOT invent variants. Do NOT include a trigger that does not "
                    "match the scene." + leet_block + "]\n"
                ) + "\n".join(trigger_lines)
                print(f"[Enhance] Loaded {len(trigger_lines)} trigger block(s): {lora_hint_text[:200]}")
            else:
                print(f"[Enhance] No LoRA triggers extractable from {len(activated_loras)} LoRA(s)")
        except Exception as e:
            print(f"[Enhance] LoRA hint loading failed: {e}")

    try:
        # Pass LoRA hints as system-level context so the LLM treats them as instructions,
        # not content to parrot. The hints go via lora_system_hint into the system prompt.
        result = await asyncio.to_thread(
            llm_service.enhance_prompt,
            prompt=prompt,
            lora_system_hint=lora_hint_text,
            mode=body.get("mode", "video"),
            max_new_tokens=body.get("max_new_tokens", 512),
            temperature=body.get("temperature", 0.6),
            nsfw=nsfw,
            model_type=model_type,
            image_paths=llm_image_paths if llm_image_paths else None,
            duration_seconds=body.get("duration_seconds"),
            window_count=body.get("window_count"),
            window_size_seconds=body.get("window_size_seconds"),
            preserve_global_timeline=bool(body.get("preserve_global_timeline")),
            tts_enhance_mode=body.get("tts_enhance_mode"),
            tts_voice_count=body.get("tts_voice_count", 2),
            raw_enhancer_mode=raw_enhancer_mode,
        )
        return {"original": prompt, "enhanced": result}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


async def _enhance_with_wangp(prompt: str, mode: str, enhancer_enabled: int, image_paths: list = None):
    """Run the Wan2GP prompt enhancer using wgp's built-in offload system."""
    return await asyncio.to_thread(
        _enhance_with_wangp_sync,
        prompt,
        mode,
        enhancer_enabled,
        image_paths,
    )


def _enhance_with_wangp_sync(prompt: str, mode: str, enhancer_enabled: int, image_paths: list = None):
    """Blocking Wan2GP enhancer implementation, isolated from the API loop."""
    import secrets
    from PIL import Image
    from shared.prompt_enhancer.prompt_enhance_utils import generate_cinematic_prompt
    from mmgp import offload

    # Setup enhancer with proper GPU offload (same as Wan2GP does internally)
    if wgp.enhancer_offloadobj is None:
        print(f"[Enhance] Loading Wan2GP enhancer (mode {enhancer_enabled}) with GPU offload...")
        pipe = {}
        kwargs = {}
        wgp.download_models()
        wgp.setup_prompt_enhancer(pipe, kwargs)
        profile = wgp.compute_profile(-1, "video")
        mmgp_profile = wgp.init_pipe(pipe, kwargs, profile)
        wgp.enhancer_offloadobj = offload.profile(pipe, profile_no=mmgp_profile, **kwargs)

    if wgp.prompt_enhancer_llm_model is None:
        raise RuntimeError("Prompt enhancer model failed to load")

    is_video = mode in ("video", "avatar")
    temperature = wgp.server_config.get("prompt_enhancer_temperature", 0.6)
    top_p = wgp.server_config.get("prompt_enhancer_top_p", 0.9)
    seed = secrets.randbits(32) if wgp.server_config.get("prompt_enhancer_randomize_seed", True) else 0

    # Load images if provided
    prompt_images = None
    if image_paths:
        loaded = []
        for img_path in image_paths:
            if img_path and os.path.isfile(img_path):
                try:
                    loaded.append(Image.open(img_path))
                    print(f"[Enhance] Including image: {os.path.basename(img_path)}")
                except Exception as e:
                    print(f"[Enhance] Failed to load image {img_path}: {e}")
        if loaded:
            prompt_images = loaded

    post_image_caption_hook = None
    if prompt_images and wgp.enhancer_offloadobj is not None:
        if hasattr(wgp.prompt_enhancer_image_caption_model, "vision_tower_model") and hasattr(wgp.prompt_enhancer_llm_model, "generate_messages"):
            post_image_caption_hook = wgp.enhancer_offloadobj.unload_all

    def _run():
        return generate_cinematic_prompt(
            wgp.prompt_enhancer_image_caption_model,
            wgp.prompt_enhancer_image_caption_processor,
            wgp.prompt_enhancer_llm_model,
            wgp.prompt_enhancer_llm_tokenizer,
            [prompt],
            prompt_images,
            video_prompt=is_video,
            text_prompt=False,
            max_new_tokens=512,
            do_sample=True,
            temperature=temperature,
            top_p=top_p,
            seed=seed,
            post_image_caption_hook=post_image_caption_hook,
        )

    result = _run()

    # Unload from GPU to free VRAM
    if wgp.enhancer_offloadobj is not None:
        wgp.enhancer_offloadobj.unload_all()

    enhanced = result[0] if isinstance(result, list) and result else (result or prompt)
    print(f"[Enhance] Wan2GP enhanced: {len(enhanced)} chars")
    return {"original": prompt, "enhanced": enhanced}


@api.post("/api/v1/llm/describe-image")
async def llm_describe_image(request: Request):
    """Describe an uploaded image using the LLM."""
    from services import llm_service
    body = await request.json()

    image_path = body.get("image_path", "")
    if not image_path:
        raise HTTPException(status_code=400, detail="image_path is required")
    image_path = _resolve_authorized_request_media(
        request,
        image_path,
        body.get("workspace") or _get_active_workspace(),
    )
    if not image_path:
        raise HTTPException(status_code=404, detail="Image not found")

    _ensure_llm_loaded()

    try:
        result = llm_service.describe_image(
            image_path=image_path,
            prompt=body.get("prompt", "Describe this image in detail."),
            max_new_tokens=body.get("max_new_tokens", 256),
        )
        return {"description": result}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


# ============================================================================
# API Routes: Audio Analysis
# ============================================================================

def _probe_audio_duration(filepath: str) -> float | None:
    """Return only the duration scalar; never expose container metadata."""
    try:
        import soundfile as sf

        info = sf.info(filepath)
        if info.samplerate and info.frames:
            return round(float(info.frames) / float(info.samplerate), 3)
    except Exception:
        pass
    return None


@api.post("/api/v1/upload-audio")
async def upload_audio(
    request: Request,
    file: UploadFile = File(...),
    private: bool = True,
):
    """Upload an audio file (wav, mp3, flac, ogg, m4a) OR a video file
    (mp4, mov, mkv, webm, avi, m4v) for audio extraction. Video files
    are transparently demuxed to a 16-bit PCM WAV containing only the
    audio track; the source video is deleted afterwards. The response
    shape is identical regardless of input format — callers always
    receive a WAV path."""
    AUDIO_EXTENSIONS = {".wav", ".mp3", ".flac", ".ogg", ".m4a", ".aac"}
    VIDEO_EXTENSIONS = {".mp4", ".mov", ".mkv", ".webm", ".avi", ".m4v"}
    ALLOWED_EXTENSIONS = AUDIO_EXTENSIONS | VIDEO_EXTENSIONS

    ext = os.path.splitext(file.filename or "audio.wav")[1].lower()
    if ext not in ALLOWED_EXTENSIONS:
        raise HTTPException(
            status_code=400,
            detail=(
                f"Unsupported format: {ext}. Allowed audio: "
                f"{', '.join(sorted(AUDIO_EXTENSIONS))}. "
                f"Allowed video (audio will be extracted): "
                f"{', '.join(sorted(VIDEO_EXTENSIONS))}."
            ),
        )

    # Pre-check via Content-Length to reject obviously-too-large uploads
    # before we read them into memory. The post-read length check below
    # is the authoritative one since Content-Length can be spoofed.
    cl = request.headers.get("content-length")
    if cl and cl.isdigit() and int(cl) > MAX_AUDIO_UPLOAD_BYTES:
        raise HTTPException(status_code=413, detail="File too large (max 500 MB)")

    upload_dir = os.path.join(os.getcwd(), "uploads", "audio")
    os.makedirs(upload_dir, exist_ok=True)

    unique_name = f"{uuid.uuid4().hex[:8]}{ext}"
    filepath = os.path.join(upload_dir, unique_name)

    content = await file.read()
    if len(content) > MAX_AUDIO_UPLOAD_BYTES:
        raise HTTPException(status_code=413, detail="File too large (max 500 MB)")
    with open(filepath, "wb") as f:
        f.write(content)

    # libsndfile (soundfile) supports wav/flac/ogg natively but NOT the
    # compressed formats users commonly have (mp3, m4a, aac). Downstream code
    # like wgp.slice_audio_window calls sf.SoundFile() directly which raises
    # LibsndfileError: Format not recognised. Transcode those to 16-bit PCM
    # wav here so the rest of the pipeline stays format-agnostic. Video
    # files take the same path with audio-only extraction (no -vn flag
    # needed because the .wav output container can't hold video — ffmpeg
    # naturally drops the video stream — but we pass `vn=None` to be
    # explicit and avoid bitstream-copy attempts on rare containers).
    is_video = ext in VIDEO_EXTENSIONS
    needs_transcode = ext in (".mp3", ".m4a", ".aac") or is_video
    if needs_transcode:
        wav_name = f"{os.path.splitext(unique_name)[0]}.wav"
        wav_path = os.path.join(upload_dir, wav_name)
        source_original = filepath
        transcode_ok = False
        try:
            import ffmpeg as _ffmpeg
            output_kwargs = {"acodec": "pcm_s16le"}
            if is_video:
                # `-vn`: explicitly drop video stream. The .wav container
                # doesn't support video so ffmpeg would drop it anyway,
                # but being explicit avoids edge cases where the encoder
                # tries to copy an unsupported video bitstream.
                output_kwargs["vn"] = None
            (
                _ffmpeg
                .input(filepath)
                .output(wav_path, **output_kwargs)
                .overwrite_output()
                .run(quiet=True)
            )
            transcode_ok = True
            os.remove(source_original)
            filepath = wav_path
            unique_name = wav_name
            if is_video:
                print(
                    f"[upload-audio] Extracted audio track from "
                    f"{file.filename!r} ({ext}) → {wav_name}. Source "
                    f"video deleted."
                )
        except _ffmpeg.Error as err:
            stderr = getattr(err, "stderr", b"") or b""
            if isinstance(stderr, (bytes, bytearray)):
                stderr = stderr.decode("utf-8", errors="ignore")
            detail_prefix = (
                "Failed to extract audio from video"
                if is_video else f"Failed to decode {ext} audio"
            )
            raise HTTPException(
                status_code=400,
                detail=f"{detail_prefix}: {(stderr or str(err)).strip()[:300]}",
            ) from err
        except Exception as err:
            raise HTTPException(
                status_code=500,
                detail=(
                    "Audio extraction failed" if is_video
                    else "Audio transcode failed"
                ) + f": {err}",
            ) from err
        finally:
            # If transcode/extract bombed (either branch above raised),
            # clean up the partial wav AND the original upload so orphans
            # don't pile up in uploads/audio/ on repeated failures.
            if not transcode_ok:
                for stale in (wav_path, source_original):
                    if stale and os.path.isfile(stale):
                        try:
                            os.remove(stale)
                        except OSError:
                            pass

    if bool(getattr(request.state, "maestro_remote", False)):
        private = True
    access = write_upload_access_sidecar(
        filepath,
        request.state.maestro_session_id,
        private=private,
    )
    return {
        "filename": unique_name,
        "path": (
            unique_name
            if bool(getattr(request.state, "maestro_remote", False))
            else filepath
        ),
        "url": f"/api/v1/uploads/audio/{unique_name}",
        "duration_seconds": _probe_audio_duration(filepath),
        **public_output_policy(access),
    }


@api.get("/api/v1/uploads/audio/{filename}")
def serve_audio_upload(request: Request, filename: str):
    """Serve an uploaded audio file."""
    from services.win_safe_files import (
        safe_direct_file_under,
        share_delete_file_response,
    )
    base = os.path.join(os.getcwd(), "uploads", "audio")
    filepath = safe_direct_file_under(base, filename)
    if filepath is None or not os.path.isfile(filepath):
        raise HTTPException(status_code=404, detail="File not found")
    resolved = _resolve_authorized_request_media(request, filepath)
    if resolved != filepath:
        raise HTTPException(status_code=404, detail="File not found")
    return share_delete_file_response(resolved)


@api.post("/api/v1/audio/mix")
async def mix_audio(request: Request):
    """Mix multiple audio tracks into one file using ffmpeg.

    Body: {
        tracks: [{ path: str, start_time: float, volume: float }, ...],
        workspace: str | null
    }
    First track is the base (full duration). Subsequent tracks are overlaid at their start_time.
    Volume is 0.0-1.0.
    """
    import subprocess

    body = await request.json()
    tracks = body.get("tracks", [])
    if len(tracks) < 2:
        raise HTTPException(status_code=400, detail="At least 2 tracks required (base + overlay)")

    workspace = body.get("workspace") or _get_active_workspace()
    out_dir = _require_project_access(request, workspace)
    source_policies = []
    for i, t in enumerate(tracks):
        path = t.get("path", "")
        resolved = _resolve_authorized_request_media(request, path, workspace)
        if not resolved:
            raise HTTPException(
                status_code=404,
                detail=f"Track {i+1}: file not found",
            )
        t["path"] = resolved
        if os.path.normcase(os.path.realpath(os.path.dirname(resolved))) == os.path.normcase(
            os.path.realpath(out_dir)
        ):
            source_policies.append(
                load_media_sidecars(out_dir, {os.path.basename(resolved)}).get(
                    os.path.basename(resolved),
                ) or {}
            )
        else:
            source_policies.append(read_upload_access_sidecar(resolved) or {})

    # Build ffmpeg filter_complex for mixing
    # Input 0 = base track, inputs 1..N = overlay tracks
    inputs = []
    filter_parts = []

    for i, t in enumerate(tracks):
        inputs.extend(["-i", t["path"]])

    # Process each track: apply volume and delay (except base track which starts at 0)
    mix_labels = []
    for i, t in enumerate(tracks):
        vol = max(0.0, min(1.0, float(t.get("volume", 1.0))))
        start_ms = int(float(t.get("start_time", 0)) * 1000)

        filters = []
        if start_ms > 0:
            filters.append(f"adelay={start_ms}|{start_ms}")
        if vol != 1.0:
            filters.append(f"volume={vol:.3f}")

        if filters:
            label = f"t{i}"
            filter_parts.append(f"[{i}]{','.join(filters)}[{label}]")
            mix_labels.append(f"[{label}]")
        else:
            mix_labels.append(f"[{i}]")

    # Combine all tracks with amix
    n = len(tracks)
    mix_input = "".join(mix_labels)
    filter_parts.append(f"{mix_input}amix=inputs={n}:duration=longest:normalize=0")

    filter_complex = ";".join(filter_parts)

    # Output to workspace
    os.makedirs(out_dir, exist_ok=True)
    out_filename = f"mix_{uuid.uuid4().hex[:6]}.wav"
    out_path = os.path.join(out_dir, out_filename)

    cmd = [
        "ffmpeg", "-y",
        *inputs,
        "-filter_complex", filter_complex,
        "-ac", "1",  # mono output (LTX audio guide works best with mono)
        out_path,
    ]

    print(f"[Audio Mix] Mixing {n} tracks → {out_path}")
    print(f"[Audio Mix] Filter: {filter_complex}")

    try:
        result = subprocess.run(cmd, capture_output=True, text=True, timeout=120)
        if result.returncode != 0:
            print(f"[Audio Mix] ffmpeg error: {result.stderr[-500:]}")
            raise HTTPException(status_code=500, detail=f"ffmpeg failed: {result.stderr[-200:]}")
    except subprocess.TimeoutExpired:
        raise HTTPException(status_code=500, detail="Audio mix timed out")

    if not os.path.isfile(out_path):
        raise HTTPException(status_code=500, detail="Mix output file not created")

    policy = {
        "private": any(bool(item.get("private", False)) for item in source_policies),
        "explicit": any(bool(item.get("explicit", False)) for item in source_policies),
        "owner_session_id": request.state.maestro_session_id,
    }
    sidecar = {
        "params": {
            "source_files": [os.path.basename(t["path"]) for t in tracks],
            "track_count": len(tracks),
        },
        "artifact_class": "final",
        "generation_mode": "audio",
        "created_at": time.time(),
    }
    stamp_sidecar_policy(sidecar, policy, workspace=workspace)
    sidecar_path = os.path.splitext(out_path)[0] + ".meta.json"
    sidecar_temp = f"{sidecar_path}.{uuid.uuid4().hex[:8]}.tmp"
    try:
        with open(sidecar_temp, "w", encoding="utf-8") as handle:
            json.dump(sidecar, handle, indent=2)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(sidecar_temp, sidecar_path)
    except Exception as error:
        for stale in (sidecar_temp, out_path):
            try:
                os.remove(stale)
            except OSError:
                pass
        raise HTTPException(
            status_code=500, detail="Could not protect mixed audio output",
        ) from error

    print(f"[Audio Mix] Done: {out_filename}")

    return {
        "filename": out_filename,
        "path": out_path,
    }


_audio_analysis_gate = threading.Lock()
_audio_analysis_state_lock = threading.RLock()
_audio_analysis_active: dict | None = None


def _audio_analysis_workspace(request: Request, explicit: str = "") -> str:
    """Resolve the project scope without exposing machine-global selection."""
    requested = str(explicit or "").strip()
    if bool(getattr(request.state, "maestro_remote", False)):
        with _remote_active_projects_lock:
            active = _remote_active_projects.get(
                request.state.maestro_session_id, "",
            )
        if not active:
            raise HTTPException(
                status_code=423,
                detail="Select and unlock a project before analyzing audio",
            )
        if requested and requested != active:
            raise HTTPException(status_code=404, detail="Analysis not found")
        return active
    return requested or _get_active_workspace()


def _audio_analysis_owner_key(request: Request, workspace: str) -> str:
    material = (
        f"audio-analysis\0{workspace}\0"
        f"{request.state.maestro_session_id}"
    ).encode("utf-8")
    return hmac.new(_session_secret(), material, hashlib.sha256).hexdigest()


@api.post("/api/v1/audio/analyze")
async def analyze_audio(request: Request):
    """Analyze an audio file: beat detection, sections, optional transcription."""
    from services import audio_analysis
    body = await request.json()

    audio_path = body.get("audio_path", "")
    if not audio_path:
        raise HTTPException(status_code=400, detail="audio_path is required")
    workspace = _audio_analysis_workspace(
        request, str(body.get("workspace") or ""),
    )
    audio_path = _resolve_authorized_request_media(
        request,
        audio_path,
        workspace,
    )
    if not audio_path:
        raise HTTPException(status_code=404, detail="Audio file not found")
    director_request_id = str(body.get("director_request_id") or "")
    director_project_dir = ""
    if director_request_id:
        preparation = _require_director_preparation(
            request, director_request_id, workspace,
        )
        expected_music = preparation.get("music")
        expected_filename = (
            str(expected_music.get("filename") or "")
            if isinstance(expected_music, dict) else ""
        )
        if not expected_filename or expected_filename != os.path.basename(audio_path):
            raise HTTPException(status_code=404, detail="Director request not found")
        director_project_dir = _require_project_access(request, workspace)
        if _director_recovery_validate_child(
            director_project_dir,
            expected_music.get("evidence"),
        ) is None:
            raise HTTPException(status_code=404, detail="Director request not found")
        _checkpoint_director_preparation(
            director_request_id,
            director_project_dir,
            phase="analyzing_audio",
        )

    if not _audio_analysis_gate.acquire(blocking=False):
        raise HTTPException(
            status_code=409,
            detail="Another audio analysis is already in progress",
        )
    # Do not let the next owner briefly inherit a prior operation's global
    # progress text before the worker publishes its first phase.
    reset_progress = getattr(audio_analysis, "_set_progress", None)
    if callable(reset_progress):
        try:
            reset_progress("", "")
        except Exception:
            pass
    analysis_id = uuid.uuid4().hex
    owner_key = _audio_analysis_owner_key(request, workspace)
    global _audio_analysis_active
    with _audio_analysis_state_lock:
        _audio_analysis_active = {
            "analysis_id": analysis_id,
            "owner_key": owner_key,
            "workspace": workspace,
        }
    worker_started = threading.Event()
    lease_lock = threading.Lock()
    lease_released = False

    def release_analysis_lease():
        """Clear this operation exactly once, including pre-start failure."""
        nonlocal lease_released
        global _audio_analysis_active
        with lease_lock:
            if lease_released:
                return
            lease_released = True
        with _audio_analysis_state_lock:
            if (
                isinstance(_audio_analysis_active, dict)
                and hmac.compare_digest(
                    str(_audio_analysis_active.get("analysis_id") or ""),
                    analysis_id,
                )
            ):
                _audio_analysis_active = None
        _audio_analysis_gate.release()

    # Free the generation model's VRAM before analysis. The Director flow
    # runs analysis right after rendering the song, and as of v1.2.0 the
    # default music model is much larger (XL SFT, 10GB bf16). On smaller
    # cards the resident model + vocal separator + Whisper oversubscribe
    # VRAM, and Windows' CUDA sysmem fallback turns that into a silent,
    # near-endless crawl instead of a clean OOM ("analyzing never
    # finishes"). The song is already saved; wgp reloads the model
    # transparently on the next job. Guarded by _gen_lock so an active
    # generation is never touched.
    if _gen_lock.acquire(blocking=False):
        try:
            if getattr(wgp, "wan_model", None) is not None:
                print("[AudioAnalysis] Releasing generation model VRAM before analysis")
                wgp.release_model()
            else:
                import gc
                gc.collect()
                if torch.cuda.is_available():
                    torch.cuda.empty_cache()
        except Exception as e:
            print(f"[AudioAnalysis] Pre-analysis VRAM release skipped: {e}")
        finally:
            _gen_lock.release()
    else:
        print("[AudioAnalysis] Generation in progress - skipping pre-analysis VRAM release")

    def run_analysis():
        """The worker owns cleanup so client cancellation cannot release the
        single-analysis gate while native/model work is still running."""
        worker_started.set()
        try:
            return audio_analysis.analyze(
                audio_path=audio_path,
                transcribe=body.get("transcribe", False),
                extract_vocals_for_transcription=body.get("extract_vocals", True),
                # Known written lyrics (generated tracks) → Whisper initial_prompt
                lyrics_hint=body.get("lyrics_hint") or None,
            )
        finally:
            release_analysis_lease()

    try:
        # Keep FastAPI's event loop available for the scoped progress poller.
        # The synchronous audio stack may run for minutes and download models.
        worker_task = asyncio.create_task(asyncio.to_thread(run_analysis))

        def finalize_worker_task(done_task):
            # Executor shutdown/submission failure can complete the future
            # without ever entering run_analysis. Request cancellation is
            # shielded, so a queued worker otherwise retains the lease until
            # it really finishes.
            if not worker_started.is_set():
                release_analysis_lease()
            try:
                done_task.exception()
            except BaseException:
                pass

        worker_task.add_done_callback(finalize_worker_task)
        result = await asyncio.shield(worker_task)
        if director_request_id:
            _checkpoint_director_preparation(
                director_request_id,
                director_project_dir,
                phase="analysis_completed",
                analysis=result,
            )
        public_result = dict(result)
        public_result["analysis_id"] = analysis_id
        if director_request_id:
            public_result["director_request_id"] = director_request_id
        return public_result
    except ImportError as e:
        raise HTTPException(status_code=501, detail=str(e))
    except Exception as e:
        if director_request_id and director_project_dir:
            try:
                _checkpoint_director_preparation(
                    director_request_id,
                    director_project_dir,
                    phase="analysis_interrupted",
                )
            except Exception:
                pass
        traceback.print_exc()
        raise HTTPException(status_code=500, detail=str(e))


@api.get("/api/v1/audio/analyze/status")
def audio_analyze_status(
    request: Request,
    analysis_id: str = "",
    workspace: str = "",
):
    """Read the current audio-analyze phase for live UI progress.

    Polled by the frontend during the synchronous /audio/analyze call
    so the user sees meaningful sub-status ("Preparing transcription
    model on this host (downloads ~300MB if needed before loading)..."
    vs "Transcribing audio...")
    instead of a single "Analyzing audio..." message for the entire
    1-5 minute wait.

    The server issues an opaque ``analysis_id`` and binds it to the browser
    session plus selected project. Legacy no-id polling remains safe because
    it can see only that same owner/project's active operation. Unknown and
    foreign IDs are indistinguishable 404s; no global progress is returned.
    """
    selected_workspace = _audio_analysis_workspace(request, workspace)
    owner_key = _audio_analysis_owner_key(request, selected_workspace)
    with _audio_analysis_state_lock:
        active = dict(_audio_analysis_active or {})
    if not active:
        if analysis_id:
            raise HTTPException(status_code=404, detail="Analysis not found")
        return {"step": "", "detail": ""}
    if (
        active.get("workspace") != selected_workspace
        or not hmac.compare_digest(
            str(active.get("owner_key") or ""), owner_key,
        )
        or (
            analysis_id
            and not hmac.compare_digest(
                str(active.get("analysis_id") or ""), analysis_id,
            )
        )
    ):
        raise HTTPException(status_code=404, detail="Analysis not found")
    from services.audio_analysis import get_progress
    progress = get_progress()
    return {
        "analysis_id": active["analysis_id"],
        "step": str(progress.get("step") or ""),
        "detail": str(progress.get("detail") or ""),
    }


