@api.get("/api/v1/director/pipelines")
def list_saved_pipelines(request: Request, workspace: str = ""):
    """List authorized saved pipeline states in one explicit project."""
    from services.director_pipeline import list_pipeline_states
    selected_workspace = _request_project_workspace(request, workspace)
    base = _require_project_access(request, selected_workspace)
    pipelines = []
    for summary in list_pipeline_states(base):
        pid = summary.get("id")
        if not isinstance(pid, str) or not pid:
            continue
        try:
            _require_saved_pipeline(request, pid, selected_workspace)
        except HTTPException:
            continue
        clean = dict(summary)
        clean.pop("_filepath", None)
        clean["workspace"] = selected_workspace
        clean.update(_saved_pipeline_live_recovery_overlay(pid))
        pipelines.append(clean)
    return {"pipelines": pipelines}


@api.get("/api/v1/director/pipelines/{pid}")
def get_saved_pipeline(request: Request, pid: str, workspace: str = ""):
    """Get a full saved pipeline state."""
    selected_workspace = _request_project_workspace(request, workspace)
    state, _base = _require_saved_pipeline(
        request, pid, selected_workspace,
    )
    public = _public_pipeline_state(state)
    public.update(_saved_pipeline_live_recovery_overlay(pid))
    return public


@api.put("/api/v1/director/pipelines/{pid}/clips/{clip_index}/tag")
async def tag_pipeline_clip(pid: str, clip_index: int, request: Request):
    """Tag a clip as 'good', 'needs_work', or null."""
    from services.director_pipeline import PipelineBusyError, update_clip_tag
    body = await request.json()
    tag = body.get("tag")
    selected_workspace = _request_project_workspace(
        request, body.get("workspace"),
    )
    _state, base = _require_saved_pipeline(request, pid, selected_workspace)
    _begin_workspace_operation(selected_workspace)
    try:
        success = update_clip_tag(base, pid, clip_index, tag)
    except PipelineBusyError as exc:
        return JSONResponse({"error": str(exc)}, status_code=409)
    finally:
        _end_workspace_operation(selected_workspace)
    if not success:
        return JSONResponse({"error": "Pipeline or clip not found"}, status_code=404)
    return {"status": "ok"}


