_h3_benchmark_cache = None


def _get_h3_benchmark_cache():
    global _h3_benchmark_cache
    if _h3_benchmark_cache is None:
        from services.h3_benchmark import H3BenchmarkCache
        _h3_benchmark_cache = H3BenchmarkCache(
            os.path.join(_app_dir, "storage", "h3_benchmarks.json")
        )
    return _h3_benchmark_cache


def _h3_benchmark_input_signature(params: dict, case_id: str) -> dict:
    """Return counts only; never hash, retain, or inspect reference content."""
    if case_id == "text_only":
        return {}
    images = params.get("image_refs")
    image_count = len(images) if isinstance(images, (list, tuple)) else int(bool(images))
    return {
        "has_start": bool(params.get("image_start")),
        "has_end": bool(params.get("image_end")),
        "image_count": image_count,
        "video_count": sum(bool(params.get(key)) for key in (
            "video_guide", "video_guide2", "video_guide3",
        )),
        "audio_count": sum(bool(params.get(key)) for key in (
            "audio_guide", "audio_guide2", "audio_guide3",
        )),
    }


def _record_h3_benchmark_observation(
    params: dict,
    *,
    wall_time_seconds: float,
    output_files: list[str],
    out_dir: str,
    model_load_state: str = "unknown",
) -> None:
    custom = params.get("custom_settings")
    if not isinstance(custom, dict):
        custom = {}
    model_type = str(params.get("model_type") or "")
    if model_type not in _H3_LONG_STUDIO_MODELS:
        return
    from services.h3_benchmark import build_benchmark_spec, record_observation
    model_def = wgp.get_model_def(model_type) or {}
    has_semantic = bool(params.get("image_refs")) or any(
        params.get(key) for key in (
            "video_guide", "video_guide2", "video_guide3",
            "audio_guide", "audio_guide2", "audio_guide3",
        )
    )
    has_start = bool(params.get("image_start"))
    has_end = bool(params.get("image_end"))
    case_id = (
        "ref2va" if has_semantic or model_type == _H3_REF2VA_MODEL
        else "first_last" if has_start and has_end
        else "first_frame" if has_start or has_end
        else "text_only"
    )
    resolution = str(params.get("resolution") or "608x352").lower()
    try:
        width, height = [int(value) for value in resolution.split("x", 1)]
    except (TypeError, ValueError):
        width, height = 608, 352
    frames = int(params.get("video_length") or 124)
    steps = int(params.get("num_inference_steps") or 20)
    profile = "quick" if (width, height, frames, steps) == (608, 352, 124, 4) else "observed_job"
    engine_id = str(custom.get("h3_attention_engine") or "sol_attn")
    # Explicit engines are fail-closed before an output can complete, so a
    # successful observation may truthfully record the requested engine as
    # effective. This prevents SDPA fallback timings from being labeled Sage.
    engine_spec = {"id": engine_id}
    if engine_id in {"sdpa", "sage2"}:
        engine_spec["effective_id"] = engine_id
    if engine_id == "sol_attn":
        engine_spec.update({
            "tau": custom.get("h3_sol_tau", 1.0),
            "dense_steps": custom.get("h3_sol_dense_steps", 10),
            "dense_blocks": custom.get("h3_sol_dense_blocks", 2),
            "min_tokens": custom.get("h3_sol_min_tokens", 4096),
        })
    spec = build_benchmark_spec(
        case_id=case_id,
        hardware={
            "gpu": torch.cuda.get_device_name(0) if torch.cuda.is_available() else "cpu",
            "compute_capability": (
                "sm" + "".join(str(value) for value in torch.cuda.get_device_capability(0))
                if torch.cuda.is_available() else ""
            ),
            "driver": str(getattr(torch.version, "cuda", "") or ""),
        },
        runtime={
            "torch": str(torch.__version__),
            "cuda": str(getattr(torch.version, "cuda", "") or ""),
            "triton": str(getattr(sys.modules.get("triton"), "__version__", "unknown")),
            "model_load_state": model_load_state,
        },
        model={
            "id": model_type,
            "family": "minimax_h3",
            "quantization": "w4a8" if model_type == _H3_W4A8_FL2VA_MODEL else "native",
            "accelerator": (
                "turbo"
                if custom.get("h3_turbo_profile") == "h3_turbo_v4"
                else "native"
            ),
        },
        engine=engine_spec,
        encoder={
            "id": "heretic_int8_convrot" if model_def.get("preferred_explicit_conditioner") else "official_nvfp4_awq",
            "quantization": "int8" if model_def.get("preferred_explicit_conditioner") else "nvfp4_awq",
        },
        input_signature=_h3_benchmark_input_signature(params, case_id),
        task={
            "profile": profile,
            "width": width,
            "height": height,
            "frame_count": frames,
            "fps": 24,
            "sampling_steps": steps,
            "window_count": 1,
            "processed_frame_count": frames,
            "lora_count": len(params.get("activated_loras") or []),
            "cache_enabled": bool(params.get("tea_cache")),
        },
    )
    peak = None
    if torch.cuda.is_available():
        try:
            peak = int(torch.cuda.max_memory_allocated())
        except Exception:
            peak = None
    from services.h3_benchmark import validate_output_artifacts
    media_exists = validate_output_artifacts(out_dir, output_files)
    record = record_observation(
        spec,
        wall_time_seconds=wall_time_seconds,
        output_frames=frames,
        output_valid=media_exists,
        peak_gpu_memory_bytes=peak,
        phase_times_seconds={"generation": wall_time_seconds},
    )
    _get_h3_benchmark_cache().put(record)


def _h3_estimate_context(body: dict, plan: dict | None = None) -> dict:
    """Project a generation request to content-free timing factors."""
    model_type = str(body.get("model_type") or "minimax_h3")
    model_def = wgp.get_model_def(model_type) or {}
    fps = float(model_def.get("fps") or 24)
    try:
        duration = float(body.get("_duration_seconds") or 0)
    except (TypeError, ValueError):
        duration = 0
    if duration <= 0:
        try:
            duration = float(body.get("video_length") or 124) / fps
        except (TypeError, ValueError, ZeroDivisionError):
            duration = 124 / 24
    long_plan = plan if isinstance(plan, dict) else body.get("_h3_longform")
    clip_frames = list(long_plan.get("clip_frames") or []) if isinstance(long_plan, dict) else []
    try:
        window_seconds = max(clip_frames) / fps if clip_frames else float(
            body.get("sliding_window_size") or model_def.get("frames_maximum") or 345
        ) / fps
    except (TypeError, ValueError, ZeroDivisionError):
        window_seconds = 345 / 24
    images = body.get("image_refs")
    context = {
        "model_type": model_type,
        "duration_seconds": duration,
        "window_seconds": window_seconds,
        "window_overlap": (
            0 if isinstance(long_plan, dict)
            else body.get("sliding_window_overlap", 0)
        ),
        "num_inference_steps": body.get("num_inference_steps", 20),
        "resolution": body.get("resolution") or "1344x768",
        "custom_settings": dict(body.get("custom_settings") or {}),
        "activated_loras": list(body.get("activated_loras") or []),
        "tea_cache": body.get("tea_cache", 0),
        "spatial_upsampling": str(body.get("spatial_upsampling") or ""),
        "delivery_resolution": str(body.get("delivery_resolution") or ""),
        "delivery_fit": str(body.get("delivery_fit") or ""),
        "reference_shape": {
            "has_start": bool(body.get("image_start")),
            "has_end": bool(body.get("image_end")),
            "image_count": len(images) if isinstance(images, (list, tuple)) else int(bool(images)),
            "video_count": sum(bool(body.get(key)) for key in (
                "video_guide", "video_guide2", "video_guide3",
            )),
            "audio_count": sum(bool(body.get(key)) for key in (
                "audio_guide", "audio_guide2", "audio_guide3",
            )),
        },
        "explicit_output": bool(body.get("explicit_output")),
    }
    segment_models = list(long_plan.get("segment_models") or []) if isinstance(long_plan, dict) else []
    if len(clip_frames) > 1 and len(segment_models) == len(clip_frames):
        segment_contexts = []
        base_shape = dict(context["reference_shape"])
        for index, (frame_count, segment_model) in enumerate(zip(clip_frames, segment_models)):
            if not isinstance(segment_model, dict):
                continue
            effective_model = str(segment_model.get("model_type") or model_type)
            segment = dict(context)
            segment.update({
                "model_type": effective_model,
                "duration_seconds": max(1, int(frame_count)) / fps,
                "window_seconds": min(15.0, max(1.0, int(frame_count) / fps)),
                "window_overlap": 0,
                # Whole-file delivery runs once after confirmed segments are
                # assembled, never independently per segment.
                "spatial_upsampling": "",
                "delivery_resolution": "",
                "delivery_fit": "",
            })
            if effective_model == _H3_REF2VA_MODEL:
                semantic_count = sum(int(base_shape.get(key) or 0) for key in (
                    "image_count", "video_count", "audio_count",
                ))
                segment["reference_shape"] = {
                    "has_start": False,
                    "has_end": False,
                    "image_count": int(base_shape.get("image_count") or 0) + int(index > 0 and semantic_count == 0),
                    "video_count": int(base_shape.get("video_count") or 0),
                    "audio_count": int(base_shape.get("audio_count") or 0),
                }
            else:
                segment["reference_shape"] = {
                    "has_start": bool(index > 0 or (index == 0 and base_shape.get("has_start"))),
                    "has_end": bool(index == len(clip_frames) - 1 and base_shape.get("has_end")),
                    "image_count": 0,
                    "video_count": 0,
                    "audio_count": 0,
                }
            segment_contexts.append(segment)
        if len(segment_contexts) == len(clip_frames):
            context["_segment_contexts"] = segment_contexts
    return context


def _h3_model_is_resident(model_type: str) -> bool:
    """Require live weights/offloader, not only WanGP's last model label."""
    return bool(
        model_type
        and str(getattr(wgp, "transformer_type", "") or "") == model_type
        and getattr(wgp, "wan_model", None) is not None
        and getattr(wgp, "offloadobj", None) is not None
        and not bool(getattr(wgp, "reload_needed", False))
    )


def _h3_estimate_for_context(
    context: dict,
    *,
    include_residency: bool = True,
) -> dict:
    from services.h3_benchmark import (
        add_h3_postprocess_estimate, aggregate_h3_estimates, estimate_h3_output,
    )
    selected = str(context.get("model_type") or "")
    resident = None
    if selected and include_residency:
        resident = _h3_model_is_resident(selected)
    records = _get_h3_benchmark_cache().load() if include_residency else []
    if records:
        current_gpu = (
            torch.cuda.get_device_name(0) if torch.cuda.is_available() else "cpu"
        )
        current_torch = str(torch.__version__)
        current_cuda = str(getattr(torch.version, "cuda", "") or "")
        current_triton = str(
            getattr(sys.modules.get("triton"), "__version__", "unknown")
        )
        records = [
            record for record in records
            if str(record.get("spec", {}).get("hardware", {}).get("gpu") or "") == current_gpu
            and str(record.get("spec", {}).get("runtime", {}).get("torch") or "") == current_torch
            and str(record.get("spec", {}).get("runtime", {}).get("cuda") or "") == current_cuda
            and str(record.get("spec", {}).get("runtime", {}).get("triton") or "") == current_triton
        ]
    segment_contexts = context.get("_segment_contexts")
    if isinstance(segment_contexts, list) and segment_contexts:
        estimates = []
        previous_model = ""
        for index, segment in enumerate(segment_contexts):
            if not isinstance(segment, dict):
                continue
            segment_model = str(segment.get("model_type") or "")
            segment_resident = None
            if include_residency and segment_model:
                # WanGP holds one active transformer. Consecutive segments on
                # the same checkpoint stay resident; every A->B (including a
                # later B->A return) incurs another load.
                segment_resident = (
                    _h3_model_is_resident(segment_model)
                    if index == 0 else segment_model == previous_model
                )
            previous_model = segment_model
            estimates.append(estimate_h3_output(
                segment, records, model_resident=segment_resident,
            ))
        if estimates:
            return add_h3_postprocess_estimate(
                aggregate_h3_estimates(estimates), context,
            )
    return estimate_h3_output(context, records, model_resident=resident)


def _h3_profile_estimate_payload(
    context: dict,
    *,
    include_residency: bool = True,
) -> dict:
    from services.h3_profiles import build_profile_options
    turbo_status = {"registered": False, "downloaded": False}
    sage2_status = {"available": False, "validated": False}
    upscale_status = {"enabled": False, "downloaded": False}
    try:
        from services.h3_turbo import turbo_assets_status
        runtime_status = dict(turbo_assets_status() or {})
        turbo_status = {
            "registered": True,
            "downloaded": bool(runtime_status.get("available")),
        }
    except (ImportError, OSError, TypeError, ValueError):
        pass
    try:
        from services.h3_acceleration import get_h3_acceleration_status
        sage2_status = dict(
            get_h3_acceleration_status(probe_kernel=False).get("sage2") or {}
        )
    except (ImportError, OSError, RuntimeError, TypeError, ValueError):
        pass
    try:
        flash_enabled, flash_variant, _ = wgp.flashvsr.settings()
        flash_paths = wgp.flashvsr.paths(flash_variant) if flash_enabled else None
        required_paths = [
            value
            for value in vars(flash_paths).values()
            if value is not None
        ] if flash_paths is not None else []
        upscale_status = {
            "enabled": bool(flash_enabled),
            "downloaded": bool(required_paths) and all(
                os.path.isfile(str(path)) for path in required_paths
            ),
            "reason": (
                None if flash_enabled
                else "FlashVSR spatial upscaling is disabled in Services settings."
            ),
        }
    except (AttributeError, ImportError, OSError, RuntimeError, TypeError, ValueError):
        upscale_status = {
            "enabled": bool(getattr(wgp, "flashvsr", None)),
            "downloaded": False,
            "reason": "FlashVSR assets are not available yet.",
        }
    def candidate_for_settings(settings: dict) -> dict:
        candidate = dict(context)
        candidate.update({
            "model_type": settings["model_type"],
            "num_inference_steps": settings["num_inference_steps"],
            "resolution": settings["resolution"],
            "activated_loras": settings["activated_loras"],
            "loras_multipliers": settings["loras_multipliers"],
            "tea_cache": settings.get("tea_cache", 0),
            "spatial_upsampling": str(settings.get("spatial_upsampling") or ""),
            "delivery_resolution": str(settings.get("delivery_resolution") or ""),
            "delivery_fit": str(settings.get("delivery_fit") or ""),
            # Match applyH3PerformanceProfile: profile custom settings replace,
            # rather than merge with, the previously selected profile.
            "custom_settings": dict(settings["custom_settings"]),
        })
        source_segments = context.get("_segment_contexts")
        if isinstance(source_segments, list):
            candidate["_segment_contexts"] = [
                {
                    **dict(segment),
                    "num_inference_steps": settings["num_inference_steps"],
                    "resolution": settings["resolution"],
                    "activated_loras": list(settings["activated_loras"]),
                    "loras_multipliers": settings["loras_multipliers"],
                    "tea_cache": settings.get("tea_cache", 0),
                    "spatial_upsampling": "",
                    "delivery_resolution": "",
                    "delivery_fit": "",
                    "custom_settings": dict(settings["custom_settings"]),
                }
                for segment in source_segments
                if isinstance(segment, dict)
            ]
        return candidate

    def turbo_compatibility(settings: dict) -> tuple[bool, str | None]:
        candidate = candidate_for_settings(settings)
        try:
            _validate_h3_turbo_estimate_context(candidate)
        except (TypeError, ValueError, RuntimeError) as exc:
            return False, str(exc)
        return True, None

    profiles = build_profile_options(
        context,
        model_exists=lambda model: wgp.get_model_def(model) is not None,
        model_downloaded=_check_model_downloaded,
        turbo_status=turbo_status,
        turbo_compatibility=turbo_compatibility,
        sage2_status=sage2_status,
        upscale_status=upscale_status,
    )
    for profile in profiles:
        settings = profile["settings"]
        candidate = candidate_for_settings(settings)
        profile["estimate"] = _h3_estimate_for_context(
            candidate, include_residency=include_residency,
        )
        profile.pop("matched_reference_count", None)
    return {
        "current": {"estimate": _h3_estimate_for_context(
            context, include_residency=include_residency,
        )},
        "profiles": profiles,
    }


def _validate_h3_turbo_estimate_context(
    context: dict,
    *,
    _h3_turbo_validation_authorized: bool = False,
) -> None:
    """Use the runtime's single compatibility matrix for estimate parity."""
    from services.h3_turbo import turbo_requested, validate_turbo_request

    custom = context.get("custom_settings")
    if not turbo_requested(custom):
        return
    segment_contexts = context.get("_segment_contexts")
    if isinstance(segment_contexts, list) and segment_contexts:
        for segment in segment_contexts:
            if not isinstance(segment, dict):
                continue
            candidate = {
                **segment,
                "custom_settings": dict(custom or {}),
                "num_inference_steps": context.get("num_inference_steps"),
                "activated_loras": context.get("activated_loras"),
                "loras_multipliers": context.get("loras_multipliers"),
                "tea_cache": context.get("tea_cache"),
            }
            candidate.pop("_segment_contexts", None)
            _validate_h3_turbo_estimate_context(
                candidate,
                _h3_turbo_validation_authorized=(
                    _h3_turbo_validation_authorized
                ),
            )
        return
    selected = str(context.get("model_type") or _H3_BASE_FL2VA_MODEL)
    reference = context.get("reference_shape")
    if not isinstance(reference, dict):
        reference = {}
    if any(int(reference.get(key) or 0) > 0 for key in (
        "image_count", "video_count", "audio_count",
    )):
        selected = _H3_REF2VA_MODEL
    model_def = wgp.get_model_def(selected) or {}
    validate_turbo_request(
        base_model_type=wgp.get_base_model_type(selected),
        model_def=model_def,
        custom_settings=custom,
        authored_steps=context.get("num_inference_steps"),
        activated_loras=context.get("activated_loras"),
        loras_multipliers=context.get("loras_multipliers"),
        skip_steps_cache_type=context.get("tea_cache"),
        _h3_turbo_validation_authorized=bool(
            _h3_turbo_validation_authorized
        ),
    )


@api.post("/api/v1/h3/estimate")
async def h3_estimate(request: Request):
    """Return stateless H3 profile estimates from content-free configuration."""
    body = await request.json()
    if not isinstance(body, dict):
        raise HTTPException(status_code=400, detail="H3 estimate body must be an object")
    allowed = {
        "model_type", "duration_seconds", "window_seconds", "window_overlap",
        "num_inference_steps", "resolution", "custom_settings",
        "activated_loras", "loras_multipliers", "reference_shape",
        "explicit_output", "tea_cache",
        "spatial_upsampling",
        "delivery_resolution", "delivery_fit",
    }
    unknown = sorted(set(body) - allowed)
    if unknown:
        raise HTTPException(status_code=400, detail=f"Unsupported H3 estimate fields: {unknown}")
    selected_model = str(body.get("model_type") or "minimax_h3")
    _require_remote_visible_models(request, [selected_model])
    if selected_model not in _H3_LONG_STUDIO_MODELS:
        raise HTTPException(status_code=400, detail="H3 estimates require a managed MiniMax H3 model")
    from services.h3_profiles import H3_NATIVE_RESOLUTIONS
    if str(body.get("resolution") or "1344x768") not in H3_NATIVE_RESOLUTIONS:
        raise HTTPException(status_code=400, detail="H3 estimates require a model-native resolution")
    custom = body.get("custom_settings")
    if custom is not None and (
        not isinstance(custom, dict)
        or set(custom) - {
            "h3_attention_engine", "h3_sol_tau", "h3_sol_dense_steps",
            "h3_sol_dense_blocks", "h3_sol_min_tokens", "h3_turbo_profile",
            "h3_benchmark_capture",
        }
    ):
        raise HTTPException(status_code=400, detail="Unsupported H3 estimator settings")
    if isinstance(custom, dict) and custom.get("h3_turbo_profile") not in (None, "", "h3_turbo_v4"):
        raise HTTPException(status_code=400, detail="Unknown H3 performance profile")
    reference = body.get("reference_shape")
    if reference is not None and (
        not isinstance(reference, dict)
        or set(reference) - {
            "has_start", "has_end", "image_count", "video_count", "audio_count",
        }
    ):
        raise HTTPException(status_code=400, detail="Unsupported H3 reference shape")
    try:
        _validate_h3_turbo_estimate_context(body)
        return _h3_profile_estimate_payload(
            body,
            include_residency=not bool(
                getattr(request.state, "maestro_remote", False)
            ),
        )
    except (TypeError, ValueError, RuntimeError) as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc


@api.get("/api/v1/h3/benchmark")
def h3_benchmark_report(request: Request):
    """Return local measurements separately from non-comparable published claims."""
    if bool(getattr(request.state, "maestro_remote", False)):
        raise HTTPException(status_code=403, detail="H3 hardware benchmarks are local-only")
    from services.h3_benchmark import build_benchmark_report
    return build_benchmark_report(_get_h3_benchmark_cache().load())


@api.post("/api/v1/h3/evaluation/preflight")
async def h3_evaluation_preflight(request: Request):
    """Build a deterministic offline manifest/report without spending GPU time."""
    from services.h3_evaluation import (
        H3EvaluationError,
        build_h3_evaluation_manifest,
        build_h3_evaluation_report,
    )
    body = await request.json()
    workspace = str(body.pop("workspace", None) or _get_active_workspace())
    _require_project_access(request, workspace)
    allowed = {
        "job_id", "model_type", "resolved_seed", "prompt", "frame_count",
        "resolution", "fps", "sampling_steps", "conditioning",
        "output_artifacts", "explicit", "private", "profile_id",
        "encoder_profile_id", "allow_experimental",
    }
    unknown = set(body) - allowed
    if unknown:
        raise HTTPException(
            status_code=400,
            detail=f"Unsupported H3 evaluation fields: {sorted(unknown)}",
        )
    body["project_id"] = workspace
    body.setdefault("job_id", f"manual-{uuid.uuid4().hex[:16]}")
    try:
        manifest = build_h3_evaluation_manifest(**body)
        report = build_h3_evaluation_report(manifest)
    except (H3EvaluationError, TypeError) as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    return {"manifest": manifest, "report": report}


@api.post("/api/v1/generate")
async def generate(request: Request):
    """Submit a generation job. Returns immediately with a job_id."""
    body = await request.json()
    workspace = body.pop("workspace", None) or _get_active_workspace()
    job_out_dir = _require_project_access(request, workspace)
    _reject_client_h3_internal_state(body)
    _reject_client_h3_turbo_validation_controls(body)
    _authorize_generation_media_inputs(request, body, workspace)
    _require_remote_visible_models(request, [body.get("model_type")])
    _h3_turbo_validation_reference_bytes = (
        _authorize_h3_turbo_benchmark_request(request, body)
    )
    _h3_turbo_validation_authorized = (
        _h3_turbo_validation_reference_bytes is not None
    )
    try:
        _apply_h3_adaptive_checkpoint(body)
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    is_sfx = body.get("sfx_mode")
    if not body.get("model_type"):
        raise HTTPException(status_code=400, detail="model_type is required")
    if not is_sfx and not body.get("prompt"):
        raise HTTPException(status_code=400, detail="prompt is required")
    # SFX virtual models (mmaudio_*) are frontend-only; skip backend model validation
    if not is_sfx and wgp.get_model_def(body["model_type"]) is None:
        raise HTTPException(status_code=400, detail=f"Unknown model: {body['model_type']}")

    # A complete Studio prompt with global timestamps must remain one
    # structured prompt until wgp knows the backend's effective FPS and exact
    # quantized sliding-window geometry. This server-side normalization also
    # covers older clients and direct API callers; Frames/multi-clip mode keeps
    # its separate per-clip semantics.
    if (
        not is_sfx
        and int(body.get("image_mode") or 0) != 2
        and int(body.get("multi_prompts_gen_type") or 0) != 3
    ):
        from shared.utils import prompt_parser as _studio_prompt_parser
        if _studio_prompt_parser.has_global_timeline(body.get("prompt", "")):
            body["multi_prompts_gen_type"] = 2

    # Defense: normalize video_prompt_type so flags whose required input
    # is missing get stripped before wgp.py's validation rejects the job.
    # This catches stale UI state (e.g. "I" persisting in a saved snapshot
    # after the user cleared their reference image) so users don't have to
    # manually wipe localStorage to recover.
    _normalize_video_prompt_type(body)
    # Same defense for image_prompt_type. Catches the user-reported bug
    # where image_prompt_type='S' persisted after the user cleared the
    # start-image preview (or never set one), causing wgp to reject T2V
    # generations with "You must provide a Start Image" instead of
    # falling back to T2V as Maestro's UX promises.
    _normalize_image_prompt_type(body)

    # MiniMax H3 checkpoints have a hard native 15-second ceiling and do not
    # implement latent sliding windows. A longer Studio duration is therefore
    # planned as consecutive legal H3 clips, using the existing multi-clip
    # renderer/concatenator. This runs after input normalization so stale
    # anchor flags cannot leak into the generated clip manifest.
    try:
        _require_h3_native_boundary_experimental(body)
        _validate_h3_sampling_steps(body)
        _validate_h3_explicit_multiclip_request(body)
        _h3_long_plan = _prepare_h3_long_studio_request(body)
        _require_h3_acceleration_available(body, _h3_long_plan)
        _validate_h3_turbo_estimate_context(
            _h3_estimate_context(body, _h3_long_plan),
            _h3_turbo_validation_authorized=(
                _h3_turbo_validation_authorized
            ),
        )
    except (TypeError, ValueError, RuntimeError) as exc:
        raise HTTPException(
            status_code=400,
            detail=f"Unable to plan long MiniMax H3 generation: {exc}",
        ) from exc
    mature_output = _classify_generation_maturity(body, _h3_long_plan)
    _require_remote_visible_models(
        request,
        _h3_effective_model_types(body, _h3_long_plan),
    )
    _require_h3_generation_terms(body, _h3_long_plan)
    if _h3_long_plan:
        print(
            "[Generate] MiniMax H3 long Studio plan: "
            f"{_h3_long_plan['requested_frames']} requested frames -> "
            f"{_h3_long_plan['clip_count']} native clips / "
            f"{_h3_long_plan['planned_frames']} aligned frames"
        )

    # ── SCAIL-2 operating guards ────────────────────────────────────
    # The React UI exposes no fps or audio controls for the SCAIL-2
    # class, so these keys can only reach the request via defaults
    # hydration — which Load Settings happily overwrites with values
    # recorded in pre-v1.3 sidecars (user-reported: restored jobs came
    # out 16fps/silent/6.4s even after the hydration fix). The server
    # is the durable place to hold the model's operating contract:
    #   1. Output follows the control video's fps (force_fps=control).
    #   2. The control video's audio is remuxed in (audio_prompt_type
    #      R) unless the request carries a real audio source (ABXK).
    #   3. video_length is recomputed from the UI's _duration_seconds
    #      at the guide's REAL fps, so "10s" means 10 seconds of the
    #      source no matter which fps the client assumed.
    #   4. sliding_window_size is clamped to the model's 81-frame
    #      training window — larger windows add VRAM risk (the whole
    #      driving window rides along as in-context tokens) without
    #      adding quality, and stale restores carried inflated values.
    try:
        _scail2_bmt = wgp.get_base_model_type(body.get("model_type"))
    except Exception:
        _scail2_bmt = None
    if _scail2_bmt in ("scail2_14B", "scail2_1.3B"):
        if not body.get("force_fps"):
            body["force_fps"] = "control"
        _apt = body.get("audio_prompt_type") or ""
        if not any(l in _apt for l in "ABXKR"):
            body["audio_prompt_type"] = "R"
        _guide = body.get("video_guide")
        _dur = body.get("_duration_seconds")
        if _guide and _dur and body.get("force_fps") == "control":
            try:
                if os.path.isfile(_guide):
                    from shared.utils.utils import get_video_info
                    _gfps, _, _, _gframes = get_video_info(_guide)
                    if _gfps and float(_gfps) > 0:
                        _gfps = float(_gfps)
                        # Cap the follow rate at 30fps: a 60fps source would
                        # double frames (and windows) for no visible gain —
                        # user report: a 10s test ran as 8 windows because
                        # the source was 60fps. wgp resamples the guide to
                        # the forced integer rate.
                        _fps_used = _gfps
                        if _gfps > 30.5:
                            _fps_used = 30.0
                            body["force_fps"] = "30"
                            print(f"[generate] SCAIL-2 fps cap: {_gfps:.6g}fps guide → generating at 30fps")
                        _want = int(round(float(_dur) * _fps_used))
                        if _gframes:
                            _want = min(_want, int(int(_gframes) * _fps_used / _gfps))
                        if _want >= 5 and _want != int(body.get("video_length") or 0):
                            print(
                                f"[generate] SCAIL-2 duration: video_length "
                                f"{body.get('video_length')} → {_want} "
                                f"({_dur}s × {_fps_used:.6g}fps)"
                            )
                            body["video_length"] = _want
            except Exception as _sferr:
                print(f"[generate] SCAIL-2 guide fps probe skipped: {_sferr}")
        try:
            _sw = int(body.get("sliding_window_size") or 0)
        except (TypeError, ValueError):
            _sw = 0
        if _sw > 81:
            print(f"[generate] SCAIL-2 window clamp: sliding_window_size {_sw} → 81")
            body["sliding_window_size"] = 81

    # ── Sliding-window safety bump ──────────────────────────────────
    # User-reported bug: a 19.6s audio upload in Studio Mode caused
    # video_length and sliding_window_size to both be auto-set to
    # 470 frames (19.6 * 24fps), but the clip generated as TWO sliding
    # windows with a stutter at the end. Root cause: wgp.py internally
    # quantizes both values to (k * latent_size + 1) form (line ~6725).
    # Floating-point rounding in the UI's Math.round(s * fps) compute
    # can land video_length and sliding_window_size on opposite sides
    # of a latent step boundary, triggering `video_length >
    # sliding_window_size` and forcing a multi-window split that wasn't
    # intended.
    #
    # Fix: if sliding_window_size is set and ≤ video_length + latent_size,
    # bump it to (video_length + latent_size + 1) so the post-quantize
    # comparison `video_length > sliding_window_size` always evaluates
    # false for single-window clips. Direct API callers benefit too —
    # not just the UI — because the safety net is at the endpoint.
    try:
        _video_length = int(body.get("video_length") or 0)
        _sliding_window = int(body.get("sliding_window_size") or 0)
        if _video_length > 0 and _sliding_window > 0:
            try:
                _, _, _latent = wgp.get_model_min_frames_and_step(body["model_type"])
            except Exception:
                _latent = 8
            # Safety bump ONLY applies to single-window-intent cases —
            # i.e. sliding_window_size is close to video_length. The
            # original bug fired when the user picked duration ≈ window
            # (e.g. both 470 frames) and float rounding pushed one above
            # the other after quantization, splitting a single-window
            # clip into two.
            #
            # CRITICAL: the OLD condition `_sliding_window <= _video_length
            # + _latent` was wrong — it fired for EVERY legitimate
            # sliding-window case where the window is much smaller than
            # the video (e.g. 120s clip with 20s windows: 500 ≤ 3000+8
            # → True → bump to 3009 → forces ENTIRE 120s into one window).
            # User-reported regression 2026-05-18.
            #
            # Correct condition: only bump when sliding_window_size is
            # within one latent step of video_length on EITHER side —
            # that's the actual quantize-boundary danger zone. For
            # legitimate sliding-window gens (sliding much smaller than
            # video) leave the values alone.
            if (_video_length - _latent) <= _sliding_window <= (_video_length + _latent):
                _new_sw = _video_length + _latent + 1
                print(
                    f"[generate] Sliding-window safety bump: "
                    f"sliding_window_size {_sliding_window} → {_new_sw} "
                    f"(video_length={_video_length}, latent_size={_latent}). "
                    f"Prevents off-by-quantization window split that "
                    f"causes a stutter at the end of single-window clips."
                )
                body["sliding_window_size"] = _new_sw
    except Exception as _swerr:
        # Defensive: never let the bump break job submission. Log and
        # carry on with the user's original values.
        print(f"[generate] Sliding-window safety bump skipped: {_swerr}")

    # Capture workspace at submission time — NOT at execution time
    session_id = request.state.maestro_session_id
    access_policy = _http_output_policy_from_request(
        body,
        mature_output=mature_output,
        owner_session_id=session_id,
    )

    job_id = uuid.uuid4().hex[:8]
    _long_plan = body.get("_h3_longform")
    if not isinstance(_long_plan, dict):
        _long_plan = {}
    try:
        _planned_clip_count = max(0, int(_long_plan.get("clip_count") or 0))
    except (TypeError, ValueError):
        _planned_clip_count = 0
    _submitted_h3_estimate = None
    if str(body.get("model_type") or "") in _H3_LONG_STUDIO_MODELS:
        _submitted_h3_estimate = _h3_profile_estimate_payload(
            _h3_estimate_context(body, _long_plan),
            include_residency=not bool(
                getattr(request.state, "maestro_remote", False)
            ),
        )["current"]["estimate"]
    job = {
        "id": job_id,
        "status": "queued",
        "progress": 0,
        "step": 0,
        "total_steps": 0,
        "phase": "",
        "message": "Queued",
        "created_at": time.time(),
        "params": body,
        "output_files": [],
        "error": None,
        "workspace": workspace,
        "out_dir": job_out_dir,
        "session_id": session_id,
        "access_policy": access_policy,
        "private": access_policy["private"],
        "explicit": access_policy["explicit"],
        "prompt_preview": str(
            _long_plan.get("global_prompt") or body.get("prompt") or ""
        )[:500],
        "model_type": str(body.get("model_type") or ""),
        "generation_mode": str(body.get("generation_mode") or "video"),
        "window_current": 0,
        "window_total": _planned_clip_count,
        "window_step": 0,
        "window_total_steps": 0,
        "window_progress": 0,
        "overall_progress": 0,
        "active_window_prompt": "",
        "clip_current": 0,
        "clip_total": _planned_clip_count,
        "clip_progress": 0,
        "h3_segment_plan": _public_h3_long_plan(_long_plan),
        "current_segment_model": "",
        "current_segment_reason": "",
        "current_segment_boundary": None,
        "h3_estimate": _submitted_h3_estimate,
        "_h3_turbo_validation_authorized": bool(
            _h3_turbo_validation_authorized
        ),
        "_h3_turbo_validation_reference_bytes": (
            _h3_turbo_validation_reference_bytes
        ),
    }
    # Registration, owner/project identity, and the request manifest are
    # durable before the job becomes observable or its worker can run.
    _queue_recovery_register_and_publish(job)

    return {
        "job_id": job_id,
        "status": "queued",
        "h3_estimate": _submitted_h3_estimate,
    }


@api.post("/api/v1/retake")
async def retake_video_endpoint(request: Request):
    """Submit a retake job: regenerate a time region of an existing video.

    Body: {
        video_path: str, start_time: float, end_time: float,
        prompt: str, model_type: str,
        negative_prompt?: str, seed?: int, guidance_scale?: float,
        num_inference_steps?: int, retake_strength?: float (0-1),
        workspace?: str
    }
    """
    body = await request.json()

    video_path = body.get("video_path")
    if not video_path:
        raise HTTPException(status_code=400, detail="video_path is required")
    workspace = body.get("workspace") or _get_active_workspace()
    job_out_dir = _require_project_access(request, workspace)
    video_path = _resolve_authorized_request_media(request, video_path, workspace)
    if not video_path:
        raise HTTPException(status_code=404, detail="Video not found")

    start_time = float(body.get("start_time", 0))
    end_time = float(body.get("end_time", -1))
    model_type = body.get("model_type")
    if not model_type:
        raise HTTPException(status_code=400, detail="model_type is required")

    try:
        import decord
        vr = decord.VideoReader(video_path)
        fps = vr.get_avg_fps()
        total_frames = len(vr)
        src_h, src_w = vr[0].shape[:2]
        del vr
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"Cannot read video: {e}")

    start_frame = max(0, int(start_time * fps))
    end_frame = int(end_time * fps) if end_time > 0 else total_frames
    end_frame = min(end_frame, total_frames)
    if start_frame >= end_frame:
        raise HTTPException(status_code=400, detail="Invalid time range")

    gen_params = {
        "prompt": body.get("prompt", "retake"),
        "model_type": model_type,
        "negative_prompt": body.get("negative_prompt", ""),
        "seed": body.get("seed", -1),
        "guidance_scale": body.get("guidance_scale", 3.0),
        "num_inference_steps": body.get("num_inference_steps", 30),
        "video_length": total_frames,
        "resolution": body.get("resolution") or f"{src_w}x{src_h}",
        "generation_mode": "video",
        # Tag the output so the gallery's Edits filter and the UI's
        # loadSettingsFromOutput restore path can recognize this as a
        # retake-mode generation. Mirrors the same field added to the
        # other edit endpoints.
        "edit_sub_mode": "retake",
        "retake_video": video_path,
        "retake_start_frame": start_frame,
        "retake_end_frame": end_frame,
        "retake_strength": float(body.get("retake_strength", 1.0)),
        "retake_engine": body.get("retake_engine", "native"),
        "regenerate_audio": body.get("regenerate_audio", True),
        "activated_loras": body.get("activated_loras", []),
        # Strip multi-phase LoRA multipliers to single phase (retake is single-stage)
        "loras_multipliers": " ".join(m.split(";")[0] for m in (body.get("loras_multipliers", "") or "").split()),
        "sliding_window_size": total_frames + 10,
        "settings_version": 2.52,
        # Mirror these in plain UI-friendly keys for the Load Settings
        # restore path (frontend reads sidecar params and re-populates
        # the Retake controls).
        "edit_video_path": video_path,
        "edit_start_time": start_time,
        "edit_end_time": end_time,
    }

    job_id = uuid.uuid4().hex[:8]
    job = {
        "id": job_id, "status": "queued", "progress": 0, "step": 0, "total_steps": 0,
        "phase": "", "message": "Queued (retake)", "created_at": time.time(),
        "params": gen_params, "output_files": [], "error": None,
        "workspace": workspace, "out_dir": job_out_dir,
    }
    _queue_recovery_register_and_publish(job)

    return {"job_id": job_id, "status": "queued", "retake_frames": f"{start_frame}-{end_frame}/{total_frames}"}


@api.post("/api/v1/extract-frames")
async def extract_frames_endpoint(request: Request):
    """Extract one or two frames from a video at specific timestamps.

    Used by the Edit Anything → "Send to Image Mode" round-trip: we extract
    the start and/or end frames of the user's chosen edit range so they
    can be loaded into Studio Image mode for prompt-driven editing, then
    fed back as boundary anchors to Edit Anything.

    Body: {
        video_path: str,
        start_time?: float,    # if provided, extract this frame
        end_time?: float,      # if provided, extract this frame
    }

    Returns: {
        start_path, start_url,    # only if start_time provided
        end_path, end_url,        # only if end_time provided
    }
    """
    body = await request.json()
    video_path = body.get("video_path")
    if not video_path:
        raise HTTPException(status_code=400, detail="video_path is required")
    workspace = body.get("workspace") or _get_active_workspace()
    video_path = _resolve_authorized_request_media(request, video_path, workspace)
    if not video_path:
        raise HTTPException(status_code=404, detail="Video not found")

    start_time = body.get("start_time")
    end_time = body.get("end_time")
    if start_time is None and end_time is None:
        raise HTTPException(status_code=400, detail="At least one of start_time or end_time is required")

    import subprocess as _sp
    uploads = os.path.join(os.getcwd(), "uploads")
    os.makedirs(uploads, exist_ok=True)
    base_id = uuid.uuid4().hex[:8]

    def _extract(t: float, suffix: str) -> str:
        # PNG keeps the frame lossless — important since the user is going
        # to edit pixels in Image mode and we don't want compression to
        # creep into the boundary anchor.
        out = os.path.join(uploads, f"frame_{base_id}_{suffix}.png")
        cmd = [
            "ffmpeg", "-y", "-ss", f"{float(t):.3f}", "-i", video_path,
            "-frames:v", "1", "-q:v", "2", out,
        ]
        proc = _sp.run(cmd, capture_output=True, text=True, timeout=30)
        if proc.returncode != 0 or not os.path.isfile(out):
            raise HTTPException(status_code=500, detail=f"ffmpeg extract failed: {proc.stderr[:200]}")
        write_upload_access_sidecar(
            out,
            request.state.maestro_session_id,
            private=True,
        )
        return out

    response: dict = {}
    if start_time is not None:
        sp = _extract(float(start_time), "start")
        response["start_path"] = sp
        response["start_url"] = f"/api/v1/uploads/{os.path.basename(sp)}"
    if end_time is not None:
        ep = _extract(float(end_time), "end")
        response["end_path"] = ep
        response["end_url"] = f"/api/v1/uploads/{os.path.basename(ep)}"
    return response


# ── Edit Anything LoRA identifier ──────────────────────────────────────
# Hosted at https://huggingface.co/Alissonerdx/LTX-LoRAs
# Trained on 8k video pairs for Add / Remove / Replace / Style edits.
# Uses the prompt itself as the edit instruction — no spatial mask required.
# We pick the 9000-step Adam variant as the default because the card
# describes it as the more-trained checkpoint.
EDIT_ANYTHING_LORA_HF_URL = "https://huggingface.co/Alissonerdx/LTX-LoRAs"
EDIT_ANYTHING_LORA_FILENAME = "ltx23_edit_anything_global_rank128_v1_9000steps_adamw.safetensors"

# Official replacement-specific SCAIL-2 Relighting LoRA. Upstream publishes a
# SAT/PyTorch checkpoint, so Maestro downloads the immutable revision, verifies
# its official hash, and converts it to Wan safetensors when needed.
_RECAST_RELIGHTING_LORA_FILENAME = "scail2_relighting_lora.safetensors"
_RECAST_RELIGHTING_LORA_REVISION = "150cc0ca4e98e50e60b9295dacde39442fdccab2"
_RECAST_RELIGHTING_LORA_REMOTE_PATH = "model/relighting-lora.pt"
_RECAST_RELIGHTING_LORA_SHA256 = "80d338a7969c1b286c8f5c4996b37eb198d0864837fecb6c87c106ca74571a2b"
_RECAST_RELIGHTING_LORA_SIZE = 1_227_381_060


def _normalize_recast_lora_settings(
    activated_loras, loras_multipliers, use_relighting,
):
    """Return aligned, single-phase LoRA settings for a Recast run.

    Wan exposes as many as three LoRA phases in the shared Studio UI, while
    SCAIL-2 Recast deliberately runs one guidance phase. Old/stale UI state
    can therefore contain ``1;1;1`` even when Recast has only one selected
    LoRA. Pair multipliers with their LoRA *before* appending the managed
    relighting LoRA, discard orphan multipliers, and retain only the first
    phase for every selected LoRA.

    Selecting the official relighting LoRA directly in Advanced is also an
    explicit opt-in. The main Recast toggle adds it at 1.0 only when Advanced
    has not already supplied it, preserving a user-adjusted Advanced weight.
    """

    if isinstance(activated_loras, (list, tuple)):
        source_loras = [
            str(item).strip()
            for item in activated_loras
            if isinstance(item, str) and item.strip()
        ]
    else:
        source_loras = []

    if isinstance(loras_multipliers, (list, tuple)):
        source_multipliers = [
            str(item).strip() for item in loras_multipliers
        ]
    else:
        source_multipliers = []
        for line in str(loras_multipliers or "").replace("\r", "").split("\n"):
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            source_multipliers.extend(line.replace("|", " ").split())

    def _single_phase_multiplier(index):
        if index >= len(source_multipliers):
            return "1.0"
        first_phase = source_multipliers[index].split(";", 1)[0].strip()
        return first_phase or "1.0"

    def _lora_key(value):
        return str(value).replace("\\", "/").rsplit("/", 1)[-1].casefold()

    normalized_loras = []
    normalized_multipliers = []
    seen = set()
    for index, name in enumerate(source_loras):
        key = _lora_key(name)
        if key in seen:
            continue
        seen.add(key)
        normalized_loras.append(name)
        normalized_multipliers.append(_single_phase_multiplier(index))

    relighting_key = _lora_key(_RECAST_RELIGHTING_LORA_FILENAME)
    if use_relighting and relighting_key not in seen:
        normalized_loras.append(_RECAST_RELIGHTING_LORA_FILENAME)
        normalized_multipliers.append("1.0")
        seen.add(relighting_key)

    return (
        normalized_loras,
        " ".join(normalized_multipliers),
        relighting_key in seen,
    )


# ── Managed auto-download LoRAs ──────────────────────────────────────────
# LoRAs that Maestro fetches when absent from the host cache so generation
# does not error out with "file not found" when a feature requires one
# (these are multi-hundred-MB files we don't ship in the repo). The
# frontend pre-downloads them when the relevant panel mounts; this registry
# powers the server-side safety net in _run_generation so the job waits for
# the download instead of failing if the user hits Generate first.
#
# Maps the final on-disk .safetensors filename to its HuggingFace source.
# Most entries download that same filename; converted sources can declare an
# immutable revision, remote path, expected hash/size, and converter. `label`
# is what the job status shows while host preparation runs.
_MANAGED_LORAS = {
    EDIT_ANYTHING_LORA_FILENAME: {
        "repo_id": "Alissonerdx/LTX-LoRAs",
        "label": "Edit Anything",
        "support_url": EDIT_ANYTHING_LORA_HF_URL,
    },
    _RECAST_RELIGHTING_LORA_FILENAME: {
        "repo_id": "zai-org/SCAIL-2",
        "revision": _RECAST_RELIGHTING_LORA_REVISION,
        "remote_path": _RECAST_RELIGHTING_LORA_REMOTE_PATH,
        "sha256": _RECAST_RELIGHTING_LORA_SHA256,
        "size": _RECAST_RELIGHTING_LORA_SIZE,
        "converter": "scail2_sat_lora",
        "label": "SCAIL-2 Relighting",
        "support_url": "https://huggingface.co/zai-org/SCAIL-2/blob/main/model/relighting-lora.pt",
    },
}


def _ensure_managed_loras_present(activated_loras, model_type, progress=None):
    """Download any managed auto-download LoRA in `activated_loras` that is
    missing from disk, blocking until each finishes.

    The file is written into the exact directory wgp loads LoRAs from for
    this model (`wgp.get_lora_dir`), so the pipeline finds it immediately
    after we return. Downloads to a .part file and atomically renames on
    success so a crashed/partial download can't masquerade as a valid LoRA.

    `progress(msg)` — optional callback used to surface a status string
    while a download is in flight (we point it at the job's `message` so the
    polling UI shows "Downloading … model").

    Returns the list of filenames downloaded this call (empty if everything
    was already present). Raises RuntimeError on download failure.
    """
    if not activated_loras:
        return []

    try:
        target_dir = wgp.get_lora_dir(model_type)
    except Exception:
        # Fall back to the configured loras_root if the model dir can't be
        # resolved (shouldn't happen for the ltx2 models these LoRAs target).
        lora_root = wgp.server_config.get("loras_root", "loras") if hasattr(wgp, "server_config") else "loras"
        if not os.path.isabs(lora_root):
            lora_root = os.path.join(os.path.dirname(os.path.abspath(__file__)), lora_root)
        target_dir = os.path.join(lora_root, "ltx2")

    def _find_download_record(name):
        """Snapshot of the active-downloads entry for `name`, preferring an
        in-flight ("downloading") record over a finished one. Used to detect
        the frontend's proactive fetch so we wait on it instead of racing."""
        with _civitai_download_lock:
            match = None
            for rec in _civitai_downloads.values():
                if os.path.basename(str(rec.get("filename", ""))) == name:
                    if rec.get("status") == "downloading":
                        return dict(rec)
                    match = dict(rec)
            return match

    downloaded = []
    for fname in activated_loras:
        base = os.path.basename(str(fname))
        spec = _MANAGED_LORAS.get(base)
        if not spec:
            continue
        save_path = os.path.join(target_dir, base)
        label = spec.get("label", base)

        # A linked installation's verified converted file is a valid runtime
        # source too; don't reclaim another 1.2 GB in the primary install.
        try:
            resolved_path = wgp.resolve_lora_path(model_type, base)
        except Exception:
            resolved_path = save_path
        if os.path.isfile(resolved_path):
            continue

        # If another part of the app is already fetching this exact file (the
        # frontend pre-downloads it when the panel mounts), wait for that to
        # finish rather than starting a second concurrent download — on
        # Windows a parallel write / atomic rename onto the open file would
        # fail or corrupt it.
        rec = _find_download_record(base)
        if rec is not None and rec.get("status") == "downloading":
            print(f"[ManagedLoRA] {label} already downloading elsewhere — waiting for it")
            waited = 0.0
            while waited < 600:
                rec = _find_download_record(base)
                if rec is None or rec.get("status") != "downloading":
                    break
                if progress:
                    pct = int(rec.get("progress") or 0)
                    progress(f"Downloading {label} model on this host… {pct}%")
                time.sleep(2)
                waited += 2
            # A legacy or externally-created failed record may still point at
            # an in-place partial. Drop it so the presence check below can
            # re-fetch a clean copy.
            if rec is not None and rec.get("status") == "failed":
                try:
                    if os.path.isfile(save_path):
                        os.remove(save_path)
                except Exception:
                    pass

        if os.path.isfile(save_path):
            continue

        os.makedirs(target_dir, exist_ok=True)
        remote_path = spec.get("remote_path", base)
        revision = spec.get("revision", "main")
        url = f"https://huggingface.co/{spec['repo_id']}/resolve/{revision}/{remote_path}"
        # Unique temp + atomic rename: a partial/failed download can never be
        # mistaken for a valid LoRA, and we don't clobber another writer.
        tmp_path = save_path + f".{uuid.uuid4().hex[:8]}.part"
        source_tmp_path = (
            save_path + f".{uuid.uuid4().hex[:8]}.source.part"
            if spec.get("converter") else tmp_path
        )
        print(f"[ManagedLoRA] {label} not found — downloading {url} -> {save_path}")
        if progress:
            progress(f"Downloading {label} model on this host…")
        try:
            import hashlib

            resp = requests.get(url, stream=True, timeout=30)
            resp.raise_for_status()
            total = int(resp.headers.get("content-length", 0))
            done = 0
            last_pct = -1
            digest = hashlib.sha256()
            with open(source_tmp_path, "wb") as out:
                for chunk in resp.iter_content(chunk_size=1024 * 1024):
                    if not chunk:
                        continue
                    out.write(chunk)
                    digest.update(chunk)
                    done += len(chunk)
                    if progress and total > 0:
                        pct = int(done * 100 / total)
                        if pct >= last_pct + 5:
                            last_pct = pct
                            progress(f"Downloading {label} model on this host… {pct}%")

            expected_size = spec.get("size")
            if expected_size is not None and done != int(expected_size):
                raise RuntimeError(
                    f"download size mismatch (expected {int(expected_size)} bytes, got {done})"
                )
            expected_sha256 = spec.get("sha256")
            actual_sha256 = digest.hexdigest()
            if expected_sha256 and actual_sha256.lower() != str(expected_sha256).lower():
                raise RuntimeError("download SHA-256 mismatch; the checkpoint was not published")

            if spec.get("converter") == "scail2_sat_lora":
                if progress:
                    progress(f"Converting {label} model on this host…")
                print(f"[ManagedLoRA] Converting official SAT LoRA -> {tmp_path}")
                from services.scail2_lora import convert_scail2_sat_lora
                tensor_count = convert_scail2_sat_lora(
                    source_tmp_path,
                    tmp_path,
                    expected_sha256=str(expected_sha256),
                )
                print(f"[ManagedLoRA] Converted {tensor_count} SCAIL-2 Relighting tensors")
                os.remove(source_tmp_path)
            elif source_tmp_path != tmp_path:
                os.replace(source_tmp_path, tmp_path)
            os.replace(tmp_path, save_path)
            downloaded.append(base)
            print(f"[ManagedLoRA] {label} downloaded -> {save_path}")
        except Exception as e:
            for partial_path in {tmp_path, source_tmp_path}:
                try:
                    if os.path.isfile(partial_path):
                        os.remove(partial_path)
                except Exception:
                    pass
            support_url = spec.get("support_url", f"https://huggingface.co/{spec['repo_id']}")
            if spec.get("converter"):
                recovery_hint = (
                    f"Retry the automatic setup, or download the official source from "
                    f"{support_url} and convert it with SCAIL-2's convert_lora.py."
                )
            else:
                recovery_hint = f"Try again, or import it manually from {support_url}."
            raise RuntimeError(
                f"Could not download the {label} model automatically: {e}. "
                f"Check your internet connection. {recovery_hint}"
            ) from e

    return downloaded


@api.post("/api/v1/edit-anything")
async def edit_anything_endpoint(request: Request):
    """Submit an Edit Anything job: prompt-driven video edit using the
    Alissonerdx Edit Anything LoRA for LTX-2.3.

    Unlike Inpaint, this does NOT require a SAM mask. The LoRA is trained
    to interpret prompts in the patterns:
      Add:     "Add a/an [thing] with [attributes], [location]."
      Remove:  "Remove the [thing] [location]."
      Replace: "Replace the [original] [location] with a/an [new] [attributes]."
      Style:   "Convert the video into a [style name] style."

    Body: {
        video_path: str, prompt: str, model_type: str,
        start_time?: float, end_time?: float  (optional time range; default = full video),
        lora_strength?: float (default 1.0, try 1.2 if edit too weak),
        negative_prompt?: str, seed?: int,
        guidance_scale?: float (default 1.0 — distilled LoRA is designed to work at CFG=1),
        num_inference_steps?: int (default 8 — distilled),
        retake_strength?: float (default 1.0 — full regen of range; lower = preserve more source),
        activated_loras?: list, loras_multipliers?: str (user's OTHER LoRAs; ours gets appended),
        workspace?: str,
    }
    """
    body = await request.json()

    video_path = body.get("video_path")
    if not video_path:
        raise HTTPException(status_code=400, detail="video_path is required")
    workspace = body.get("workspace") or _get_active_workspace()
    job_out_dir = _require_project_access(request, workspace)
    video_path = _resolve_authorized_request_media(request, video_path, workspace)
    if not video_path:
        raise HTTPException(status_code=404, detail="Video not found")

    # Resolve optional boundary-anchor image paths the same way we resolve
    # the source video: absolute first, else workspace, else uploads/, else
    # the active output dir (gallery filename). Image-mode outputs come
    # back from the round-trip as bare filenames (e.g. "2026-04-27-...png")
    # which live in the active workspace's outputs/ folder.
    def _resolve_anchor_path(raw):
        if not raw:
            return None
        return _resolve_authorized_request_media(request, raw, workspace)

    start_anchor_path = _resolve_anchor_path(body.get("start_anchor_path"))
    end_anchor_path = _resolve_anchor_path(body.get("end_anchor_path"))

    prompt = (body.get("prompt") or "").strip()
    if not prompt:
        raise HTTPException(status_code=400, detail="prompt is required")
    model_type = body.get("model_type")
    if not model_type:
        raise HTTPException(status_code=400, detail="model_type is required")

    # Probe video dimensions and length
    try:
        import decord
        vr = decord.VideoReader(video_path)
        fps = vr.get_avg_fps()
        total_frames = len(vr)
        src_h, src_w = vr[0].shape[:2]
        del vr
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"Cannot read video: {e}")

    # Optional time range (default = full video)
    start_time = float(body.get("start_time", 0))
    end_time = float(body.get("end_time", -1))
    start_frame = max(0, int(start_time * fps))
    end_frame = int(end_time * fps) if end_time > 0 else total_frames
    end_frame = min(end_frame, total_frames)
    if start_frame >= end_frame:
        raise HTTPException(status_code=400, detail="Invalid time range")

    # Merge user's activated LoRAs with the Edit Anything LoRA.
    # If the user already has it toggled on, we don't duplicate — just ensure
    # its multiplier reflects the lora_strength from the request.
    lora_strength = float(body.get("lora_strength", 1.0))
    lora_strength = max(0.1, min(2.0, lora_strength))
    user_activated = list(body.get("activated_loras") or [])
    user_mults_raw = (body.get("loras_multipliers", "") or "").split()
    # Strip multi-phase suffix — retake is single-stage
    user_mults = [m.split(";")[0] for m in user_mults_raw]

    activated_loras = list(user_activated)
    multipliers_list = list(user_mults)
    # Pad multipliers to match activated count if user under-specified
    while len(multipliers_list) < len(activated_loras):
        multipliers_list.append("1.0")

    if EDIT_ANYTHING_LORA_FILENAME in activated_loras:
        idx = activated_loras.index(EDIT_ANYTHING_LORA_FILENAME)
        multipliers_list[idx] = f"{lora_strength:.2f}"
    else:
        activated_loras.append(EDIT_ANYTHING_LORA_FILENAME)
        multipliers_list.append(f"{lora_strength:.2f}")

    print(f"[EditAnything] prompt='{prompt[:80]}', lora={EDIT_ANYTHING_LORA_FILENAME}, "
          f"strength={lora_strength:.2f}, range=[{start_frame}-{end_frame}]/{total_frames}, "
          f"cfg={body.get('guidance_scale', 1.0)}, steps={body.get('num_inference_steps', 8)}")

    gen_params = {
        "prompt": prompt,
        "model_type": model_type,
        "negative_prompt": body.get("negative_prompt", ""),
        "seed": body.get("seed", -1),
        # Distilled LTX + Edit Anything LoRA is designed for CFG=1.
        # Per the card: "Starting point: Distilled model with CFG = 1.
        # If edit is too weak: Increase CFG."
        "guidance_scale": float(body.get("guidance_scale", 1.0)),
        "num_inference_steps": int(body.get("num_inference_steps", 8)),
        "video_length": total_frames,
        "resolution": body.get("resolution") or f"{src_w}x{src_h}",
        "generation_mode": "video",
        # Tag the output for the gallery's Edits filter + Load Settings
        # restore path. Stored alongside generation_mode in the .meta.json
        # sidecar via _run_generation's params copy.
        "edit_sub_mode": "edit_anything",
        # Route through the native retake pipeline so we get the standard
        # temporal regen behavior. No spatial mask — the LoRA itself does
        # the region-aware editing per the prompt.
        "retake_video": video_path,
        "retake_start_frame": start_frame,
        "retake_end_frame": end_frame,
        "retake_strength": float(body.get("retake_strength", 1.0)),
        "retake_engine": "native",
        "regenerate_audio": body.get("regenerate_audio", True),
        "activated_loras": activated_loras,
        "loras_multipliers": " ".join(multipliers_list),
        "sliding_window_size": total_frames + 10,
        "settings_version": 2.52,
        # Track the source video + LoRA strength so the UI can rebuild
        # state when the user clicks "Load Settings" in the gallery.
        "edit_video_path": video_path,
        "edit_anything_lora_strength": lora_strength,
        "edit_start_time": start_time,
        "edit_end_time": end_time if end_time > 0 else (total_frames / fps if fps else 0),
        # Optional user-provided boundary anchors. When present, ltx2.py's
        # retake setup uses these instead of auto-extracting the source's
        # first/last frames as I2V anchors. Empty slots fall through to
        # source-extracted frames (matches today's behavior). See ltx2.py
        # _is_spatial_inpaint branch around line 1215. Paths are resolved
        # absolute above so ltx2.py's os.path.isfile check works regardless
        # of where the image came from (uploads/ or outputs/).
        "retake_user_start_anchor": start_anchor_path,
        "retake_user_end_anchor": end_anchor_path,
    }

    job_id = uuid.uuid4().hex[:8]
    job = {
        "id": job_id, "status": "queued", "progress": 0, "step": 0, "total_steps": 0,
        "phase": "", "message": "Queued (edit anything)", "created_at": time.time(),
        "params": gen_params, "output_files": [], "error": None,
        "workspace": workspace, "out_dir": job_out_dir,
    }
    _queue_recovery_register_and_publish(job)

    return {
        "job_id": job_id, "status": "queued",
        "edit_range": f"{start_frame}-{end_frame}/{total_frames}",
        "lora_filename": EDIT_ANYTHING_LORA_FILENAME,
    }


def _resolve_recast_media(request: Request, raw, workspace):
    """Resolve Recast/Repaint media through the shared request authorizer."""
    return _resolve_authorized_request_media(request, raw, workspace)


_RECAST_MASK_COLORS = [
    (0, 0, 255),
    (255, 0, 0),
    (0, 255, 0),
    (255, 0, 255),
    (0, 255, 255),
]

# Extra SAM3 tracking colors used by native bystander mapping and the adaptive
# protection fallback. SCAIL-2 can condition at most five people, but the
# source or generated scene may contain additional people that must remain
# distinguishable while Maestro selects the relevant tracks.
_RECAST_PROTECTION_COLORS = _RECAST_MASK_COLORS + [
    (255, 255, 0),
    (255, 128, 0),
    (128, 0, 255),
    (0, 192, 128),
    (255, 64, 128),
]

_RECAST_FAST_MODEL_TYPE = "scail2_14B_recast_fast"
_RECAST_LEGACY_FAST_MODEL_TYPE = "scail2_14B_fast"
_RECAST_RESOLUTION_PROFILES = {
    # Width/height describe the landscape budget. The source video's
    # orientation and aspect ratio are applied below on a 32px boundary.
    "480p": (832, 480),
    "512p": (896, 512),
    "704p": (1280, 704),
}
_RECAST_WARMUP_FRAMES = 8
_RECAST_U2NET_CACHE_LIMIT = 8
_recast_u2net_session = None
_recast_u2net_session_lock = threading.Lock()
_recast_u2net_run_lock = threading.Lock()
_recast_u2net_cache_lock = threading.Lock()
_recast_u2net_cache = {}


def _normalize_recast_person_count(value):
    """Clamp the SCAIL-2 person slot count to its supported 1-5 range."""
    try:
        return min(5, max(1, int(value)))
    except (TypeError, ValueError):
        return 1


def _normalize_recast_resolution_profile(value):
    """Return a supported SCAIL-2 edit resolution without changing models."""
    normalized = str(value or "").strip().lower().replace(" ", "")
    aliases = {
        "480": "480p",
        "832x480": "480p",
        "fast": "480p",
        "512": "512p",
        "896x512": "512p",
        "quality": "512p",
        "704": "704p",
        "1280x704": "704p",
        "high": "704p",
    }
    normalized = aliases.get(normalized, normalized)
    if normalized not in _RECAST_RESOLUTION_PROFILES:
        return "480p"
    return normalized


def _normalize_scail2_inference_steps(value, default):
    """Clamp dedicated SCAIL-2 edit jobs to the UI's supported step range."""
    try:
        steps = int(float(value))
    except (TypeError, ValueError, OverflowError):
        steps = int(default)
    return min(50, max(1, steps))


def _normalize_scail2_guidance_scale(value, default=5.0):
    """Return a finite SCAIL-2 HQ guidance value accepted by the UI."""
    import math

    try:
        guidance = float(value)
    except (TypeError, ValueError, OverflowError):
        guidance = float(default)
    if not math.isfinite(guidance):
        guidance = float(default)
    return min(20.0, max(0.0, guidance))


def _recast_window_size_for_profile(resolution_profile, total_vram_gb):
    """Choose a VAE-aligned SCAIL-2 edit window without changing model steps.

    SCAIL-2 activation pressure scales approximately with spatial pixels times
    frames in the active window. A 1280x704 frame has almost twice the pixels
    of 896x512, so retaining the ordinary 81-frame window would nearly double
    the non-streamable attention workspace. Shorter 4n+1 windows keep 704p
    practical while MMGP independently streams model weights.

    A zero return means the detected GPU is below the currently supported
    704p floor. Unknown hardware uses the conservative middle window rather
    than rejecting a valid NVIDIA setup because a probe was unavailable.
    """
    profile = _normalize_recast_resolution_profile(resolution_profile)
    if profile != "704p":
        return 81
    try:
        vram_gb = float(total_vram_gb)
    except (TypeError, ValueError):
        vram_gb = 0.0
    if vram_gb <= 0:
        return 41
    if vram_gb >= 24.0:
        return 49
    if vram_gb >= 20.0:
        return 41
    if vram_gb >= 16.0:
        return 33
    return 0


def _build_recast_prompt(raw_prompt, person_count, enhance=True):
    """Return an idempotent finished-video description for SCAIL-2.

    Upstream explicitly asks for a description of the completed video, not an
    editing command. Convert the most common ``replace X with Y`` phrasing and
    append descriptive continuity language without imperative "keep" clauses.
    When enhancement is disabled, preserve the user's prompt verbatim apart
    from surrounding whitespace so A/B tests can isolate the model behavior.
    """
    import re

    prompt = str(raw_prompt or "").strip()
    if not enhance:
        if not prompt:
            raise ValueError(
                "Enter a Recast prompt when automatic prompt enhancement is disabled."
            )
        return prompt

    detail_marker = "The surrounding people, environment, camera framing"
    count = _normalize_recast_person_count(person_count)
    plural = count != 1
    if prompt:
        instruction_patterns = (
            r"^(?:please\s+)?(?:replace|swap)\s+.+?\s+(?:with|for)\s+(.+)$",
            r"^(?:please\s+)?change\s+.+?\s+(?:into|to)\s+(.+)$",
        )
        for pattern in instruction_patterns:
            match = re.match(pattern, prompt, flags=re.IGNORECASE | re.DOTALL)
            if match:
                prompt = match.group(1).strip()
                break
    if not prompt:
        prompt = (
            "Several clearly defined characters perform naturally within the scene"
            if plural else
            "A clearly defined character performs naturally within the scene"
        )
    prompt = prompt[0].upper() + prompt[1:] if prompt else prompt
    if detail_marker in prompt:
        return prompt
    prompt = prompt.rstrip()
    if prompt[-1:] not in ".!?":
        prompt += "."
    identity = (
        "The characters' faces, hair, body shapes, and complete outfits remain "
        "visually consistent as they follow the visible action and interactions."
        if plural else
        "The character's face, hair, body shape, and complete outfit remain "
        "visually consistent as the character follows the visible action and interactions."
    )
    return (
        f"{prompt} {identity} {detail_marker}, lighting, shadows, and nearby "
        "objects form one coherent, naturally lit scene throughout the video."
    )


def _extract_output_seed(filename):
    """Return the resolved seed embedded in a generated media filename."""
    import os
    import re

    match = re.search(r"(?:^|_)seed(\d+)(?:_|$)", os.path.splitext(filename)[0])
    return int(match.group(1)) if match else None


def _recast_video_has_audio(video_path):
    """Return whether ffprobe finds an audio stream in a video."""
    import subprocess

    probe = subprocess.run(
        [
            "ffprobe", "-v", "quiet", "-select_streams", "a:0",
            "-show_entries", "stream=codec_type", "-of", "csv=p=0",
            video_path,
        ],
        capture_output=True,
        text=True,
        timeout=15,
    )
    return probe.returncode == 0 and bool(probe.stdout.strip())


def _build_recast_mask_lock_command(source_video, mask_video, generated_video, output_path):
    """Build the ffmpeg pass that restores every pixel outside the target.

    The SCAIL target is selected by a colored tracking mask. ``colorkey``
    converts the native Replace mask's white background to transparency;
    two tiny dilations plus a soft edge keep the replacement seam clean
    without giving the model room to alter neighboring people.
    """
    import json
    import subprocess

    probe = subprocess.run(
        [
            "ffprobe", "-v", "error", "-select_streams", "v:0",
            "-show_entries", "stream=width,height", "-of", "json",
            generated_video,
        ],
        capture_output=True,
        text=True,
        timeout=15,
    )
    try:
        stream = (json.loads(probe.stdout).get("streams") or [])[0]
        width, height = int(stream["width"]), int(stream["height"])
    except (IndexError, KeyError, TypeError, ValueError, json.JSONDecodeError):
        width, height = 0, 0
    if width <= 0 or height <= 0:
        raise ValueError(f"Could not read generated Recast dimensions: {generated_video}")
    filter_graph = (
        f"[0:v]scale={width}:{height}:flags=lanczos,setsar=1,setpts=PTS-STARTPTS[base];"
        f"[1:v]scale={width}:{height}:flags=neighbor,format=rgba,"
        "colorkey=0xFFFFFF:0.18:0.04,alphaextract,dilation,dilation,"
        "gblur=sigma=1.2[alpha];"
        "[2:v]format=rgba,setpts=PTS-STARTPTS[generated];"
        "[generated][alpha]alphamerge[foreground];"
        "[base][foreground]overlay=shortest=1:format=auto[outv]"
    )
    command = [
        "ffmpeg", "-y",
        "-i", source_video,
        "-i", mask_video,
        "-i", generated_video,
        "-filter_complex", filter_graph,
        "-map", "[outv]",
        # Preserve the generated file's embedded prompt and resolved seed.
        "-map_metadata", "2",
        "-c:v", "libx264", "-crf", "18", "-preset", "fast",
        "-pix_fmt", "yuv420p",
    ]
    if _recast_video_has_audio(generated_video):
        command += ["-map", "2:a:0", "-c:a", "copy"]
    elif _recast_video_has_audio(source_video):
        command += ["-map", "0:a:0", "-c:a", "aac", "-b:a", "192k"]
    else:
        command += ["-an"]
    return command + ["-shortest", "-movflags", "+faststart", output_path]


def _render_recast_mask_locked_video(source_video, mask_video, generated_video):
    """Render a protected sibling file and return its path."""
    import subprocess

    stem, extension = os.path.splitext(generated_video)
    protected_path = f"{stem}.recast-protected{extension}"
    command = _build_recast_mask_lock_command(
        source_video, mask_video, generated_video, protected_path,
    )
    result = subprocess.run(
        command,
        capture_output=True,
        text=True,
        timeout=900,
    )
    if result.returncode != 0 or not os.path.isfile(protected_path):
        if os.path.isfile(protected_path):
            try:
                os.remove(protected_path)
            except OSError:
                pass
        raise RuntimeError(
            "Recast target-mask protection failed: "
            + (result.stderr[-500:] if result.stderr else "ffmpeg produced no output")
        )
    return protected_path


def _recast_color_region(mask_frames, color, tolerance=90):
    """Return pixels close to an RGB tracking color after lossy video decode."""
    import numpy as np

    frames = np.asarray(mask_frames, dtype=np.int16)
    target = np.asarray(color, dtype=np.int16).reshape(1, 1, 1, 3)
    return np.max(np.abs(frames - target), axis=-1) <= int(tolerance)


def _matte_recast_reference_frame(reference_frame, semantic_mask, neutral_value=127):
    """Remove pixels that an additional SCAIL reference must not describe.

    SCAIL-2 encodes reference RGB and its semantic mask separately. A black
    semantic region therefore does not stop identity detail in the original
    RGB image from reaching the reference latent. Replace hidden pixels with
    model-neutral gray so a bystander reference cannot reintroduce the old
    target or condition the surrounding scene.
    """
    import numpy as np

    frame = np.asarray(reference_frame, dtype=np.uint8)
    mask = np.asarray(semantic_mask, dtype=np.uint8)
    if frame.ndim != 3 or frame.shape[-1] != 3:
        raise ValueError(
            f"Recast reference frame must have H/W/RGB dimensions; got {frame.shape}."
        )
    if mask.shape != frame.shape:
        raise ValueError(
            "Recast reference frame and semantic mask must have matching "
            f"H/W/RGB dimensions; got frame={frame.shape}, mask={mask.shape}."
        )
    try:
        neutral = int(neutral_value)
    except (TypeError, ValueError) as exc:
        raise ValueError("Recast reference neutral value must be an integer.") from exc
    if not 0 <= neutral <= 255:
        raise ValueError("Recast reference neutral value must be between 0 and 255.")

    visible = np.any(mask > 30, axis=-1)
    matted = np.full_like(frame, neutral, dtype=np.uint8)
    matted[visible] = frame[visible]
    return matted


def _recast_reference_canvas_size(
    source_frame, base_width=832, base_height=480, block_size=32,
):
    """Choose a SCAIL output/reference canvas for the control orientation.

    Recast profiles advertise a landscape resolution budget, but SCAIL-2
    reallocates that budget to follow the control video's aspect ratio.
    Preparing hidden references at a literal landscape size makes portrait
    controls consume references that are cropped again later. Preserve the
    source orientation on SCAIL-2's documented 32px boundary.
    """
    import math
    import numpy as np

    frame = np.asarray(source_frame)
    if frame.ndim != 3 or frame.shape[-1] != 3:
        raise ValueError(
            "Recast reference canvas needs an H/W/RGB source frame; "
            f"got {frame.shape}."
        )
    try:
        base_width = int(base_width)
        base_height = int(base_height)
        block_size = int(block_size)
    except (TypeError, ValueError) as exc:
        raise ValueError("Recast reference canvas dimensions must be integers.") from exc
    if min(base_width, base_height, block_size) <= 0:
        raise ValueError("Recast reference canvas dimensions must be positive.")

    source_height, source_width = frame.shape[:2]
    aspect = float(source_width) / float(max(1, source_height))
    short_edge = min(base_width, base_height)
    long_edge = max(base_width, base_height)

    def _floor_block(value):
        return max(
            block_size,
            int(math.floor(float(value) / block_size)) * block_size,
        )

    if aspect >= 1.0:
        height = short_edge
        width = min(long_edge, _floor_block(height * aspect))
    else:
        width = short_edge
        height = min(long_edge, _floor_block(width / max(aspect, 1e-6)))
    return int(width), int(height)


def _recast_resolution_for_source(source_frame, resolution_profile=None):
    """Resolve a SCAIL-2 edit profile to the source-oriented output size."""
    profile = _normalize_recast_resolution_profile(resolution_profile)
    base_width, base_height = _RECAST_RESOLUTION_PROFILES[profile]
    return _recast_reference_canvas_size(
        source_frame,
        base_width=base_width,
        base_height=base_height,
        block_size=32,
    )


def _build_recast_source_scene_layers(
    source_frame, target_mask, selected_count, output_size=None,
):
    """Return a target-free scene image and its official visibility mask."""
    import cv2
    import numpy as np
    from PIL import Image as _PILImage
    from PIL import ImageFilter as _PILImageFilter

    frame = np.asarray(source_frame, dtype=np.uint8)
    mask = np.asarray(target_mask, dtype=np.uint8)
    if frame.ndim != 3 or frame.shape[-1] != 3:
        raise ValueError(
            "Recast source-scene reference needs an H/W/RGB source frame; "
            f"got {frame.shape}."
        )
    if mask.shape != frame.shape:
        raise ValueError(
            "Recast source frame and target-anchor mask must have "
            f"matching dimensions; got frame={frame.shape}, mask={mask.shape}."
        )
    if output_size is not None:
        try:
            output_width, output_height = (
                int(output_size[0]),
                int(output_size[1]),
            )
        except (TypeError, ValueError, IndexError) as exc:
            raise ValueError(
                "Recast source-scene output size must contain width and height."
            ) from exc
        if output_width <= 0 or output_height <= 0:
            raise ValueError(
                "Recast source-scene output dimensions must be positive."
            )
        frame = np.asarray(
            _PILImage.fromarray(frame).resize(
                (output_width, output_height),
                resample=_PILImage.Resampling.LANCZOS,
            ),
            dtype=np.uint8,
        )
        mask = np.asarray(
            _PILImage.fromarray(mask).resize(
                (output_width, output_height),
                resample=_PILImage.Resampling.NEAREST,
            ),
            dtype=np.uint8,
        )

    requested_count = _normalize_recast_person_count(selected_count)
    target_region = np.zeros(frame.shape[:2], dtype=bool)
    mask_frames = mask[None]
    for color in _RECAST_MASK_COLORS[:requested_count]:
        target_region |= _recast_color_region(mask_frames, color)[0]
    if not bool(target_region.any()):
        raise ValueError(
            "Could not build the Recast source-scene reference because the "
            "selected target is missing from the anchor mask."
        )

    # Hide a small margin around the old target. The semantic mask is exact,
    # but VAE receptive fields can otherwise retain hair, clothing, or edge
    # pixels just outside the segmentation boundary.
    expansion = max(
        2,
        min(16, int(round(min(frame.shape[:2]) * 0.01))),
    )
    expanded = _PILImage.fromarray(
        target_region.astype(np.uint8) * 255,
    ).filter(_PILImageFilter.MaxFilter(expansion * 2 + 1))
    hidden_region = np.asarray(expanded, dtype=np.uint8) > 127

    # A neutral gray hole is not truly invisible to the VAE; the reference
    # mask is learned conditioning rather than a hard RGB gate. Inpaint the
    # hidden pixels from their surrounding scene so any latent leakage carries
    # compatible scene color/texture instead of replacing the whole background
    # with the matte color. The black semantic mask still tells SCAIL-2 not to
    # treat the synthesized hole as authoritative visible content.
    inpaint_mask = hidden_region.astype(np.uint8) * 255
    reference_frame = cv2.inpaint(
        frame,
        inpaint_mask,
        max(3, expansion * 2),
        cv2.INPAINT_TELEA,
    )
    reference_mask = np.full_like(frame, 255, dtype=np.uint8)
    reference_mask[hidden_region] = 0
    return {
        "image": reference_frame,
        "mask": reference_mask,
        "hidden_fraction": float(hidden_region.mean()),
        "expansion_pixels": expansion,
    }


def _build_recast_source_scene_reference(
    source_frame, target_mask, selected_count, output_dir, job_id,
    neutral_value=127, output_size=None,
):
    """Build an official-style clean-background reference for Recast.

    SCAIL-2's multi-reference mask semantics use white for source content that
    should remain visible and black for content that must be ignored. Preserve
    the selected source frame everywhere except the old target, then inpaint
    and black-mask that target so neither its identity nor a gray matte can
    leak through the VAE. This reuses one target anchor from Recast's tracked
    timeline; it does not add another SAM3 tracking pass.
    """
    import os
    from PIL import Image as _PILImage
    layers = _build_recast_source_scene_layers(
        source_frame,
        target_mask,
        selected_count,
        output_size=output_size,
    )
    try:
        int(neutral_value)
    except (TypeError, ValueError) as exc:
        raise ValueError(
            "Recast source-scene neutral value must be an integer."
        ) from exc
    if not 0 <= int(neutral_value) <= 255:
        raise ValueError(
            "Recast source-scene neutral value must be between 0 and 255."
        )

    os.makedirs(output_dir, exist_ok=True)
    reference_path = os.path.join(
        output_dir, f"recast_source_scene_ref_{job_id}.png",
    )
    reference_mask_path = os.path.join(
        output_dir, f"recast_source_scene_mask_{job_id}.png",
    )
    _PILImage.fromarray(layers["image"]).save(reference_path)
    _PILImage.fromarray(layers["mask"]).save(reference_mask_path)
    return {
        "image": reference_path,
        "mask": reference_mask_path,
        "hidden_fraction": layers["hidden_fraction"],
        "expansion_pixels": layers["expansion_pixels"],
    }


def _enable_recast_dynamic_source_scene_reference(
    params, source_frame, target_mask, selected_count, output_dir, job_id,
):
    """Enable target-free source-scene conditioning for Recast.

    The historical helper/flag names say ``dynamic`` for saved-project
    compatibility. Dedicated single-shot Recast reuses this persisted pair.
    Timeline-aware jobs retain it as a fallback and ask SCAIL-2 to rebuild the
    pair from each current control window.
    """
    if not isinstance(params, dict):
        raise ValueError("Recast generation parameters must be a dictionary.")
    image_refs = params.get("image_refs")
    custom_settings = params.get("custom_settings")
    if not isinstance(image_refs, list) or not image_refs:
        raise ValueError(
            "Recast needs a primary identity reference before adding the "
            "source-scene reference."
        )
    if not isinstance(custom_settings, dict):
        raise ValueError("Recast custom settings are missing.")
    additional_masks = custom_settings.get(
        "scail2_additional_reference_mask_paths",
    )
    expected_colors = custom_settings.get(
        "scail2_reference_expected_colors",
    )
    if not isinstance(additional_masks, list):
        raise ValueError("Recast additional reference masks are missing.")
    if not isinstance(expected_colors, list):
        raise ValueError("Recast expected reference colors are missing.")
    if len(additional_masks) != len(image_refs) - 1:
        raise ValueError(
            "Recast image references and additional masks are out of sync."
        )
    if len(expected_colors) != len(image_refs):
        raise ValueError(
            "Recast image references and expected colors are out of sync."
        )

    output_size = params.get("edit_recast_reference_canvas")
    if (
        not isinstance(output_size, (list, tuple))
        or len(output_size) != 2
    ):
        output_size = _recast_reference_canvas_size(source_frame)
    else:
        try:
            output_size = tuple(int(value) for value in output_size)
        except (TypeError, ValueError):
            output_size = _recast_reference_canvas_size(source_frame)
        if min(output_size) <= 0:
            output_size = _recast_reference_canvas_size(source_frame)
    scene_reference = _build_recast_source_scene_reference(
        source_frame,
        target_mask,
        selected_count,
        output_dir,
        job_id,
        output_size=output_size,
    )
    # Keep this pair out of ``image_refs`` so it does not become a user-facing
    # character slot.  The dedicated conditioner loads it as a separate,
    # stable additional reference for every segment.
    custom_settings["scail2_dynamic_source_scene_reference"] = True
    custom_settings["scail2_source_scene_reference_path"] = (
        scene_reference["image"]
    )
    custom_settings["scail2_source_scene_mask_path"] = (
        scene_reference["mask"]
    )
    params["edit_recast_source_scene_reference"] = scene_reference["image"]
    params["edit_recast_source_scene_mask"] = scene_reference["mask"]
    params["edit_recast_source_scene_hidden_fraction"] = scene_reference[
        "hidden_fraction"
    ]
    params["edit_recast_reference_canvas"] = list(output_size)
    params["edit_recast_source_scene_conditioning"] = (
        "stable_official_reference"
    )
    return scene_reference


def _compose_recast_group_reference_frame(
    source_frame, semantic_mask, target_reference_layers, selected_count,
    neutral_value=127,
):
    """Build one native multi-person SCAIL reference on a neutral canvas.

    The selected shared frame supplies only the tracked bystanders. Each selected
    source target is replaced by the corresponding prepared replacement
    cutout, positioned inside that target's shared-frame slot. The returned
    semantic mask therefore describes every visible conditioned person in one
    ordinary multi-color reference instead of making bystanders compete as a
    separate, target-free multi-reference image.
    """
    import numpy as np
    from PIL import Image as _PILImage

    source = np.asarray(source_frame, dtype=np.uint8)
    group_mask = np.asarray(semantic_mask, dtype=np.uint8)
    if (
        source.ndim != 3
        or source.shape[-1] != 3
        or group_mask.shape != source.shape
    ):
        raise ValueError(
            "Recast group reference needs matching H/W/RGB source and mask "
            f"arrays; got source={source.shape}, mask={group_mask.shape}."
        )
    layers = list(target_reference_layers or [])
    if not layers:
        raise ValueError("Recast group reference needs a prepared target layer.")
    try:
        neutral = int(neutral_value)
    except (TypeError, ValueError) as exc:
        raise ValueError("Recast group neutral value must be an integer.") from exc
    if not 0 <= neutral <= 255:
        raise ValueError("Recast group neutral value must be between 0 and 255.")

    normalized_layers = []
    canvas_width = canvas_height = None
    for layer_index, layer in enumerate(layers):
        if not isinstance(layer, (list, tuple)) or len(layer) != 2:
            raise ValueError(
                "Each Recast group target layer must contain an RGB image and "
                "its semantic mask."
            )
        layer_rgb = np.asarray(layer[0], dtype=np.uint8)
        layer_mask = np.asarray(layer[1], dtype=np.uint8)
        if (
            layer_rgb.ndim != 3
            or layer_rgb.shape[-1] != 3
            or layer_mask.shape != layer_rgb.shape
        ):
            raise ValueError(
                f"Recast group target layer {layer_index + 1} has mismatched "
                f"RGB/mask dimensions: image={layer_rgb.shape}, "
                f"mask={layer_mask.shape}."
            )
        if canvas_width is None:
            canvas_height, canvas_width = layer_rgb.shape[:2]
        elif layer_rgb.shape[:2] != (canvas_height, canvas_width):
            layer_rgb = np.asarray(
                _PILImage.fromarray(layer_rgb).resize(
                    (canvas_width, canvas_height),
                    resample=_PILImage.Resampling.LANCZOS,
                ),
                dtype=np.uint8,
            )
            layer_mask = np.asarray(
                _PILImage.fromarray(layer_mask).resize(
                    (canvas_width, canvas_height),
                    resample=_PILImage.Resampling.NEAREST,
                ),
                dtype=np.uint8,
            )
        normalized_layers.append((layer_rgb, layer_mask))

    if source.shape[:2] != (canvas_height, canvas_width):
        source = np.asarray(
            _PILImage.fromarray(source).resize(
                (canvas_width, canvas_height),
                resample=_PILImage.Resampling.LANCZOS,
            ),
            dtype=np.uint8,
        )
        group_mask = np.asarray(
            _PILImage.fromarray(group_mask).resize(
                (canvas_width, canvas_height),
                resample=_PILImage.Resampling.NEAREST,
            ),
            dtype=np.uint8,
        )

    requested_count = _normalize_recast_person_count(selected_count)
    composite = np.full_like(source, neutral, dtype=np.uint8)
    composite_mask = np.zeros_like(group_mask, dtype=np.uint8)

    # Retain source pixels only for the explicitly color-mapped bystanders.
    # The old selected subject and the surrounding scene never enter this RGB
    # reference, so neither can compete with the requested replacement.
    for color in _RECAST_MASK_COLORS[requested_count:]:
        color_array = np.asarray(color, dtype=np.uint8)
        region = np.all(group_mask == color_array, axis=-1)
        if bool(region.any()):
            composite[region] = source[region]
            composite_mask[region] = color_array

    for target_index, color in enumerate(
        _RECAST_MASK_COLORS[:requested_count],
    ):
        color_array = np.asarray(color, dtype=np.uint8)
        target_region = np.all(group_mask == color_array, axis=-1)
        target_ys, target_xs = np.nonzero(target_region)
        if len(target_xs) == 0:
            raise ValueError(
                "Could not place replacement target "
                f"{target_index + 1}: its first-frame color is missing."
            )

        # Legacy "replace N people" reuses one identity for every selected
        # slot; explicit character mappings provide one primary layer each.
        layer_rgb, layer_mask = normalized_layers[
            min(target_index, len(normalized_layers) - 1)
        ]
        subject = np.any(layer_mask > 30, axis=-1)
        subject_ys, subject_xs = np.nonzero(subject)
        if len(subject_xs) == 0:
            raise ValueError(
                f"Prepared replacement target {target_index + 1} is empty."
            )
        sx0, sx1 = int(subject_xs.min()), int(subject_xs.max()) + 1
        sy0, sy1 = int(subject_ys.min()), int(subject_ys.max()) + 1
        subject_rgb = layer_rgb[sy0:sy1, sx0:sx1]
        subject_alpha = (
            subject[sy0:sy1, sx0:sx1].astype(np.uint8) * 255
        )

        tx0, tx1 = int(target_xs.min()), int(target_xs.max()) + 1
        ty0, ty1 = int(target_ys.min()), int(target_ys.max()) + 1
        target_width, target_height = max(1, tx1 - tx0), max(1, ty1 - ty0)
        scale = min(
            target_width / max(1, subject_rgb.shape[1]),
            target_height / max(1, subject_rgb.shape[0]),
        )
        placed_width = max(
            1,
            min(canvas_width, int(round(subject_rgb.shape[1] * scale))),
        )
        placed_height = max(
            1,
            min(canvas_height, int(round(subject_rgb.shape[0] * scale))),
        )
        placed_rgb = np.asarray(
            _PILImage.fromarray(subject_rgb).resize(
                (placed_width, placed_height),
                resample=_PILImage.Resampling.LANCZOS,
            ),
            dtype=np.uint8,
        )
        placed_alpha = np.asarray(
            _PILImage.fromarray(subject_alpha).resize(
                (placed_width, placed_height),
                resample=_PILImage.Resampling.BILINEAR,
            ),
            dtype=np.float32,
        ) / 255.0

        left = int(round((tx0 + tx1 - placed_width) / 2.0))
        top = ty1 - placed_height
        left = max(0, min(left, canvas_width - placed_width))
        top = max(0, min(top, canvas_height - placed_height))
        right, bottom = left + placed_width, top + placed_height

        alpha = placed_alpha[..., None]
        destination = composite[top:bottom, left:right].astype(np.float32)
        composite[top:bottom, left:right] = np.rint(
            placed_rgb.astype(np.float32) * alpha
            + destination * (1.0 - alpha)
        ).clip(0, 255).astype(np.uint8)
        visible = placed_alpha > 0.05
        mask_destination = composite_mask[top:bottom, left:right]
        mask_destination[visible] = color_array

    return composite, composite_mask


def _compose_recast_cast_reference_frame(
    target_reference_layers, selected_count, canvas_size, neutral_value=127,
):
    """Arrange independently prepared characters in one native SCAIL cast.

    SCAIL-2's trained multi-person path expects all mapped identities and their
    semantic colors in one primary reference.  A timeline may never show every
    requested character at once, so this neutral cast sheet is the fallback
    when no shared source frame can provide natural target positions.
    """
    import numpy as np
    from PIL import Image as _PILImage

    layers = list(target_reference_layers or [])
    requested_count = _normalize_recast_person_count(selected_count)
    if len(layers) < requested_count:
        raise ValueError(
            "Recast cast reference needs one prepared target layer per "
            f"character ({len(layers)}/{requested_count})."
        )
    try:
        canvas_width, canvas_height = (
            int(canvas_size[0]),
            int(canvas_size[1]),
        )
        neutral = int(neutral_value)
    except (IndexError, TypeError, ValueError) as exc:
        raise ValueError(
            "Recast cast reference needs a valid canvas and neutral value."
        ) from exc
    if min(canvas_width, canvas_height) <= 0:
        raise ValueError("Recast cast reference canvas must be positive.")
    if not 0 <= neutral <= 255:
        raise ValueError(
            "Recast cast reference neutral value must be between 0 and 255."
        )

    composite = np.full(
        (canvas_height, canvas_width, 3),
        neutral,
        dtype=np.uint8,
    )
    composite_mask = np.zeros_like(composite)
    outer_margin = max(4, int(round(min(canvas_width, canvas_height) * 0.025)))
    gap = max(4, int(round(canvas_width * 0.012)))
    available_width = max(
        requested_count,
        canvas_width - 2 * outer_margin - gap * (requested_count - 1),
    )
    cell_width = float(available_width) / float(requested_count)
    maximum_height = max(1, canvas_height - 2 * outer_margin)

    for target_index in range(requested_count):
        layer = layers[target_index]
        if not isinstance(layer, (list, tuple)) or len(layer) != 2:
            raise ValueError(
                "Each Recast cast target layer must contain an RGB image and "
                "its semantic mask."
            )
        layer_rgb = np.asarray(layer[0], dtype=np.uint8)
        layer_mask = np.asarray(layer[1], dtype=np.uint8)
        if (
            layer_rgb.ndim != 3
            or layer_rgb.shape[-1] != 3
            or layer_mask.shape != layer_rgb.shape
        ):
            raise ValueError(
                f"Recast cast target layer {target_index + 1} has mismatched "
                f"RGB/mask dimensions: image={layer_rgb.shape}, "
                f"mask={layer_mask.shape}."
            )
        color_array = np.asarray(
            _RECAST_MASK_COLORS[target_index],
            dtype=np.uint8,
        )
        subject = np.all(layer_mask == color_array, axis=-1)
        if not bool(subject.any()):
            # Prepared PNG masks are normally exact, but tolerate masks from
            # older saved jobs whose semantic color was not persisted.
            subject = np.any(layer_mask > 30, axis=-1)
        subject_ys, subject_xs = np.nonzero(subject)
        if len(subject_xs) == 0:
            raise ValueError(
                f"Prepared replacement target {target_index + 1} is empty."
            )
        sx0, sx1 = int(subject_xs.min()), int(subject_xs.max()) + 1
        sy0, sy1 = int(subject_ys.min()), int(subject_ys.max()) + 1
        subject_rgb = layer_rgb[sy0:sy1, sx0:sx1]
        subject_alpha = (
            subject[sy0:sy1, sx0:sx1].astype(np.uint8) * 255
        )

        maximum_width = max(1, int(round(cell_width * 0.90)))
        scale = min(
            maximum_width / max(1, subject_rgb.shape[1]),
            maximum_height / max(1, subject_rgb.shape[0]),
        )
        placed_width = max(1, int(round(subject_rgb.shape[1] * scale)))
        placed_height = max(1, int(round(subject_rgb.shape[0] * scale)))
        placed_rgb = np.asarray(
            _PILImage.fromarray(subject_rgb).resize(
                (placed_width, placed_height),
                resample=_PILImage.Resampling.LANCZOS,
            ),
            dtype=np.uint8,
        )
        placed_alpha = np.asarray(
            _PILImage.fromarray(subject_alpha).resize(
                (placed_width, placed_height),
                resample=_PILImage.Resampling.BILINEAR,
            ),
            dtype=np.float32,
        ) / 255.0

        cell_left = outer_margin + target_index * (cell_width + gap)
        left = int(round(cell_left + (cell_width - placed_width) / 2.0))
        top = int(round((canvas_height - placed_height) / 2.0))
        left = max(0, min(left, canvas_width - placed_width))
        top = max(0, min(top, canvas_height - placed_height))
        right, bottom = left + placed_width, top + placed_height

        alpha = placed_alpha[..., None]
        destination = composite[top:bottom, left:right].astype(np.float32)
        composite[top:bottom, left:right] = np.rint(
            placed_rgb.astype(np.float32) * alpha
            + destination * (1.0 - alpha)
        ).clip(0, 255).astype(np.uint8)
        visible = placed_alpha > 0.05
        mask_destination = composite_mask[top:bottom, left:right]
        mask_destination[visible] = color_array

    return composite, composite_mask


def _build_recast_target_group_reference(
    prepared_refs, output_dir, job_id, selected_count, *,
    shared_source_frame=None, shared_semantic_mask=None,
):
    """Persist one primary multi-character reference for SCAIL-2 Recast."""
    import numpy as np
    from PIL import Image as _PILImage

    target_layers = []
    for item in prepared_refs.get("primary_target_refs", []):
        if (
            not isinstance(item, dict)
            or not item.get("image")
            or not item.get("mask")
        ):
            raise ValueError(
                "Multi-character Recast needs prepared target image/mask "
                "pairs."
            )
        with _PILImage.open(item["image"]) as target_image:
            target_rgb = np.asarray(
                target_image.convert("RGB"),
                dtype=np.uint8,
            )
        with _PILImage.open(item["mask"]) as target_mask:
            target_semantic = np.asarray(
                target_mask.convert("RGB"),
                dtype=np.uint8,
            )
        target_layers.append((target_rgb, target_semantic))

    mode = "cast_sheet"
    if shared_source_frame is not None and shared_semantic_mask is not None:
        try:
            reference_frame, reference_mask = (
                _compose_recast_group_reference_frame(
                    shared_source_frame,
                    shared_semantic_mask,
                    target_layers,
                    selected_count,
                )
            )
        except ValueError as shared_error:
            print(
                "[Recast] Shared-frame cast layout was unavailable; "
                f"using a neutral cast sheet: {shared_error}"
            )
            reference_frame, reference_mask = (
                _compose_recast_cast_reference_frame(
                    target_layers,
                    selected_count,
                    prepared_refs["reference_canvas"],
                )
            )
        else:
            mode = "shared_timeline_frame"
    else:
        reference_frame, reference_mask = (
            _compose_recast_cast_reference_frame(
                target_layers,
                selected_count,
                prepared_refs["reference_canvas"],
            )
        )

    os.makedirs(output_dir, exist_ok=True)
    reference_path = os.path.join(
        output_dir,
        f"recast_cast_ref_{job_id}.png",
    )
    reference_mask_path = os.path.join(
        output_dir,
        f"recast_cast_mask_{job_id}.png",
    )
    _PILImage.fromarray(reference_frame).save(reference_path)
    _PILImage.fromarray(reference_mask).save(reference_mask_path)
    return {
        "image": reference_path,
        "mask": reference_mask_path,
        "mode": mode,
        "character_count": _normalize_recast_person_count(selected_count),
    }


def _compose_recast_native_people_masks(
    target_mask_frames, all_people_masks, selected_count,
    reference_frame_index=0,
):
    """Build native SCAIL-2 masks for targets plus visible bystanders.

    The user's selected targets retain the first SCAIL colors. Other people
    visible in the selected shared frame are assigned the remaining colors (up
    to SCAIL-2's five-person limit). The driving mask carries all of those
    correspondences, while the shared-frame reference mask identifies every
    target and bystander for one ordinary multi-person reference.
    """
    import numpy as np

    targets = np.asarray(target_mask_frames, dtype=np.uint8)
    people = np.asarray(all_people_masks, dtype=np.uint8)
    if targets.shape != people.shape or targets.ndim != 4 or targets.shape[-1] != 3:
        raise ValueError(
            "Native Recast people masks must have matching T/H/W/RGB dimensions; "
            f"got targets={targets.shape}, people={people.shape}."
        )
    try:
        reference_index = int(reference_frame_index)
    except (TypeError, ValueError) as exc:
        raise ValueError(
            "Native Recast reference frame index must be an integer."
        ) from exc
    if not 0 <= reference_index < len(targets):
        raise ValueError(
            "Native Recast reference frame index is outside the mask timeline."
        )

    requested_count = _normalize_recast_person_count(selected_count)
    target_regions = []
    for color in _RECAST_MASK_COLORS[:requested_count]:
        region = _recast_color_region(targets, color)
        if bool(region.any()):
            target_regions.append(region)
    if len(target_regions) != requested_count:
        raise ValueError(
            "Could not recover every selected target from the tracked Recast mask "
            f"({len(target_regions)}/{requested_count})."
        )

    candidates = []
    for color_index, color in enumerate(_RECAST_PROTECTION_COLORS):
        region = np.all(people == np.asarray(color, dtype=np.uint8), axis=-1)
        area = int(region.sum())
        reference_frame_area = int(region[reference_index].sum())
        if area and reference_frame_area:
            candidates.append({
                "source_color_index": color_index,
                "region": region,
                "area": area,
                "reference_frame_area": reference_frame_area,
            })
    if not candidates:
        raise ValueError("SAM3 found no people to map for native Recast preservation.")

    # Match the broad "person" tracks back to the user's more specific target
    # tracks. Anything matched here must never be reused as a bystander ref.
    pairings = []
    for target_index, target_region in enumerate(target_regions):
        target_area = max(1, int(target_region.sum()))
        for candidate_index, candidate in enumerate(candidates):
            overlap = int(np.logical_and(target_region, candidate["region"]).sum())
            score = overlap / np.sqrt(float(target_area * candidate["area"]))
            pairings.append((score, overlap, target_index, candidate_index))
    pairings.sort(key=lambda item: (item[0], item[1]), reverse=True)

    used_targets = set()
    target_candidate_indices = set()
    for score, overlap, target_index, candidate_index in pairings:
        if target_index in used_targets or candidate_index in target_candidate_indices:
            continue
        if overlap <= 0 or score < 0.02:
            continue
        used_targets.add(target_index)
        target_candidate_indices.add(candidate_index)
        if len(used_targets) == len(target_regions):
            break
    if len(used_targets) != len(target_regions):
        raise ValueError(
            "Could not match every selected target to the source person tracks "
            f"({len(used_targets)}/{len(target_regions)})."
        )

    target_union = np.logical_or.reduce(target_regions)
    bystanders = []
    for candidate_index, candidate in enumerate(candidates):
        if candidate_index in target_candidate_indices:
            continue
        overlap = int(np.logical_and(target_union, candidate["region"]).sum())
        overlap_fraction = overlap / max(
            1, min(candidate["area"], int(target_union.sum())),
        )
        # Avoid treating a fragmented duplicate of a target track as another
        # person when SAM's broad prompt splits loose clothing or an occlusion.
        # A high threshold deliberately retains real dancers who pass behind
        # or partly overlap the selected subject.
        if overlap_fraction > 0.65:
            continue
        bystanders.append(candidate)
    bystanders.sort(
        key=lambda candidate: (
            candidate["area"],
            candidate["reference_frame_area"],
        ),
        reverse=True,
    )
    capacity = max(0, len(_RECAST_MASK_COLORS) - len(target_regions))
    bystanders = bystanders[:capacity]

    driving_mask = np.full_like(targets, 255, dtype=np.uint8)
    group_ref_mask = np.zeros(targets.shape[1:], dtype=np.uint8)
    assignments = []
    for offset, candidate in enumerate(bystanders):
        assigned_index = len(target_regions) + offset
        assigned_color = _RECAST_MASK_COLORS[assigned_index]
        driving_mask[candidate["region"]] = np.asarray(assigned_color, dtype=np.uint8)
        group_ref_mask[candidate["region"][reference_index]] = np.asarray(
            assigned_color, dtype=np.uint8,
        )
        assignments.append((
            candidate["source_color_index"],
            assigned_index,
            candidate["area"],
        ))

    # The explicit target mask wins wherever people overlap or cross.
    for target_index, target_region in enumerate(target_regions):
        driving_mask[target_region] = np.asarray(
            _RECAST_MASK_COLORS[target_index], dtype=np.uint8,
        )
    # A broad bystander track can overlap the selected subject in the shared
    # frame. The selected target wins there, keeping one unambiguous color per
    # pixel in the native group reference.
    group_ref_mask[target_union[reference_index]] = 0
    for target_index, target_region in enumerate(target_regions):
        group_ref_mask[target_region[reference_index]] = np.asarray(
            _RECAST_MASK_COLORS[target_index], dtype=np.uint8,
        )
    return (
        driving_mask,
        group_ref_mask,
        len(target_regions) + len(bystanders),
        assignments,
    )


def _recast_probe_needs_bystander_tracking(
    probe_frame, target_probe_mask, selected_count,
):
    """Cheaply decide whether Recast needs a second full SAM3 tracking pass.

    Native group preservation can only use people visible in the first frame,
    so a one-frame broad ``person`` segmentation is sufficient to determine
    whether any usable bystander exists. If the probe is ambiguous, return
    True and retain the conservative full-pass behavior.
    """
    import numpy as np
    from shared import magic_mask

    frame = np.asarray(probe_frame, dtype=np.uint8)
    target = np.asarray(target_probe_mask, dtype=np.uint8)
    if frame.ndim != 3 or frame.shape[-1] != 3 or target.shape != frame.shape:
        return True
    try:
        people = magic_mask.generate_keyword_masks(
            frame[None],
            "person",
            no_hole=True,
            colorize_objects=True,
            color_palette=_RECAST_PROTECTION_COLORS,
            max_colored_objects=len(_RECAST_PROTECTION_COLORS),
        )
        _, _, conditioning_count, _ = _compose_recast_native_people_masks(
            target[None],
            people,
            selected_count,
        )
    except Exception:
        return True
    return conditioning_count > _normalize_recast_person_count(selected_count)


def _build_recast_native_people_conditioning(
    source_video, target_mask_video, selected_count, output_dir, job_id,
    target_references=None, progress_callback=None, reference_frame_index=0,
):
    """Track source bystanders and write one SCAIL-native group reference."""
    import cv2
    import numpy as np
    from PIL import Image as _PILImage
    from shared import magic_mask

    source_path, source_frames, fps = magic_mask.prepare_video_mask_input(source_video)
    _, target_masks, _ = magic_mask.prepare_video_mask_input(target_mask_video)
    frame_count, height, width = source_frames.shape[:3]
    if len(target_masks) != frame_count:
        indices = np.rint(
            np.linspace(0, len(target_masks) - 1, frame_count),
        ).astype(np.int64)
        target_masks = target_masks[indices]
    if target_masks.shape[1:3] != (height, width):
        target_masks = np.stack([
            cv2.resize(frame, (width, height), interpolation=cv2.INTER_NEAREST)
            for frame in target_masks
        ])

    all_people_masks = magic_mask.generate_keyword_masks(
        source_frames,
        "person",
        no_hole=True,
        colorize_objects=True,
        color_palette=_RECAST_PROTECTION_COLORS,
        max_colored_objects=len(_RECAST_PROTECTION_COLORS),
        progress_callback=progress_callback,
    )
    driving_mask, group_ref_mask, conditioning_count, assignments = (
        _compose_recast_native_people_masks(
            target_masks,
            all_people_masks,
            selected_count,
            reference_frame_index=reference_frame_index,
        )
    )
    if conditioning_count <= _normalize_recast_person_count(selected_count):
        return {
            "video_mask": target_mask_video,
            "reference_image": None,
            "reference_mask": None,
            "conditioning_count": conditioning_count,
            "assignments": assignments,
        }

    os.makedirs(output_dir, exist_ok=True)
    driving_mask_path = magic_mask.save_mask_video(
        source_path,
        driving_mask,
        fps,
        ["recast people"],
        output_dir=output_dir,
    )
    reference_path = os.path.join(
        output_dir, f"recast_group_ref_{job_id}.png",
    )
    reference_mask_path = os.path.join(
        output_dir, f"recast_group_mask_{job_id}.png",
    )
    target_layers = []
    for item in target_references or []:
        if not isinstance(item, dict) or not item.get("image") or not item.get("mask"):
            raise ValueError(
                "Native Recast preservation needs prepared target image/mask pairs."
            )
        with _PILImage.open(item["image"]) as target_image:
            target_rgb = np.asarray(target_image.convert("RGB"), dtype=np.uint8)
        with _PILImage.open(item["mask"]) as target_mask:
            target_semantic = np.asarray(
                target_mask.convert("RGB"), dtype=np.uint8,
            )
        target_layers.append((target_rgb, target_semantic))
    reference_frame, reference_mask = _compose_recast_group_reference_frame(
        source_frames[int(reference_frame_index)],
        group_ref_mask,
        target_layers,
        selected_count,
    )
    _PILImage.fromarray(reference_frame).save(reference_path)
    _PILImage.fromarray(reference_mask).save(reference_mask_path)
    return {
        "video_mask": driving_mask_path,
        "reference_image": reference_path,
        "reference_mask": reference_mask_path,
        "conditioning_count": conditioning_count,
        "assignments": assignments,
    }


def _select_recast_generated_regions(
    source_mask_frames, generated_people_masks, person_count,
):
    """Select generated person tracks that correspond to source targets.

    The source mask identifies who the user approved. SAM3 assigns stable
    colors to every person in the generated video. Spatiotemporal overlap
    matches those generated tracks back to the approved targets even when
    replacement changes body size or silhouette substantially.
    """
    import numpy as np

    source = np.asarray(source_mask_frames, dtype=np.uint8)
    generated = np.asarray(generated_people_masks, dtype=np.uint8)
    if source.shape != generated.shape or source.ndim != 4 or source.shape[-1] != 3:
        raise ValueError(
            "Adaptive Recast masks must have matching T/H/W/RGB dimensions; "
            f"got source={source.shape}, generated={generated.shape}."
        )

    source_white = np.all(source > 225, axis=-1)
    source_black = np.all(source < 30, axis=-1)
    source_union = ~source_white & ~source_black
    if not bool(source_union.any()):
        raise ValueError("The approved Recast target mask is empty.")

    requested_count = min(5, max(1, int(person_count or 1)))
    target_regions = []
    for color in _RECAST_MASK_COLORS[:requested_count]:
        region = _recast_color_region(source, color)
        if bool(region.any()):
            target_regions.append(region)
    if not target_regions:
        target_regions = [source_union]

    candidates = []
    for color_index, color in enumerate(_RECAST_PROTECTION_COLORS):
        region = np.all(generated == np.asarray(color, dtype=np.uint8), axis=-1)
        area = int(region.sum())
        if area:
            candidates.append((color_index, region, area))
    if not candidates:
        raise ValueError("SAM3 found no people in the generated Recast video.")

    pairings = []
    for target_index, target_region in enumerate(target_regions):
        target_area = max(1, int(target_region.sum()))
        for color_index, generated_region, generated_area in candidates:
            overlap = int(np.logical_and(target_region, generated_region).sum())
            score = overlap / np.sqrt(float(target_area * generated_area))
            pairings.append(
                (score, overlap, target_index, color_index, generated_region)
            )
    pairings.sort(key=lambda item: (item[0], item[1]), reverse=True)

    used_targets = set()
    used_colors = set()
    selected_regions = []
    selected_scores = []
    for score, overlap, target_index, color_index, generated_region in pairings:
        if target_index in used_targets or color_index in used_colors:
            continue
        # A tiny incidental crossing should not attach an unrelated bystander.
        if overlap <= 0 or score < 0.02:
            continue
        used_targets.add(target_index)
        used_colors.add(color_index)
        selected_regions.append(generated_region)
        selected_scores.append((color_index, float(score), overlap))
        if len(used_targets) == len(target_regions):
            break

    if len(used_targets) != len(target_regions):
        raise ValueError(
            "Could not match every generated replacement to its approved "
            f"source target ({len(used_targets)}/{len(target_regions)} matched)."
        )

    adaptive = source_union.copy()
    for region in selected_regions:
        adaptive |= region
    return adaptive, selected_scores


def _build_recast_adaptive_mask(
    generated_video, source_mask_video, person_count, output_dir,
    progress_callback=None,
):
    """Trace generated replacement silhouettes and return a mask-video path."""
    import cv2
    import numpy as np
    from shared import magic_mask

    generated_path, generated_frames, fps = magic_mask.prepare_video_mask_input(
        generated_video,
    )
    _, source_masks, _ = magic_mask.prepare_video_mask_input(source_mask_video)
    frame_count, height, width = generated_frames.shape[:3]
    if len(source_masks) != frame_count:
        indices = np.rint(
            np.linspace(0, len(source_masks) - 1, frame_count)
        ).astype(np.int64)
        source_masks = source_masks[indices]
    if source_masks.shape[1:3] != (height, width):
        source_masks = np.stack([
            cv2.resize(frame, (width, height), interpolation=cv2.INTER_NEAREST)
            for frame in source_masks
        ])

    generated_people = magic_mask.generate_keyword_masks(
        generated_frames,
        "person",
        no_hole=True,
        colorize_objects=True,
        color_palette=_RECAST_PROTECTION_COLORS,
        max_colored_objects=len(_RECAST_PROTECTION_COLORS),
        progress_callback=progress_callback,
    )
    adaptive, selected_scores = _select_recast_generated_regions(
        source_masks, generated_people, person_count,
    )

    # Close tiny segmentation gaps and leave a narrow safety rim for hair,
    # fingers, motion blur, and compression. The ffmpeg compositor feathers it.
    kernel = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (7, 7))
    adaptive = np.stack([
        cv2.dilate(
            cv2.morphologyEx(frame.astype(np.uint8), cv2.MORPH_CLOSE, kernel),
            kernel,
        ) != 0
        for frame in adaptive
    ])
    output_masks = np.zeros((frame_count, height, width, 3), dtype=np.uint8)
    output_masks[adaptive] = np.asarray(_RECAST_MASK_COLORS[0], dtype=np.uint8)
    mask_path = magic_mask.save_mask_video(
        generated_path,
        output_masks,
        fps,
        ["adaptive recast target"],
        output_dir=output_dir,
        background_color=(255, 255, 255),
    )
    score_text = ", ".join(
        f"track {color_index}: {score:.3f} ({overlap} px)"
        for color_index, score, overlap in selected_scores
    )
    print(f"  [Recast] Adaptive protection selected {score_text}")
    return mask_path


def _count_recast_mask_people(mask, colors):
    """Count SCAIL-2 palette colors present in a colorized SAM3 mask."""
    import numpy as np

    array = np.asarray(mask)
    if array.ndim < 3 or array.shape[-1] != 3:
        return 0
    return sum(
        bool(np.all(array == np.asarray(color, dtype=array.dtype), axis=-1).any())
        for color in colors
    )


def _align_recast_reference_mask(source_mask, reference_mask, target_colors, candidate_colors):
    """Match people in an edited first frame to source targets by overlap.

    SAM3 segments every person in the edited reference.  Spatial overlap
    with the already-previewed source mask then tells us which new person
    belongs to each SCAIL slot, even when the edit changed "woman" to "man".
    """
    import itertools
    import numpy as np
    from PIL import Image as _PILImage

    source = np.asarray(source_mask, dtype=np.uint8)
    reference = np.asarray(reference_mask, dtype=np.uint8)
    if source.shape[:2] != reference.shape[:2]:
        source = np.asarray(
            _PILImage.fromarray(source, mode="RGB").resize(
                (reference.shape[1], reference.shape[0]),
                resample=_PILImage.Resampling.NEAREST,
            ),
            dtype=np.uint8,
        )

    target_regions = [
        np.all(source == np.asarray(color, dtype=np.uint8), axis=-1)
        for color in target_colors
    ]
    present_candidates = []
    for color in candidate_colors:
        region = np.all(reference == np.asarray(color, dtype=np.uint8), axis=-1)
        if bool(region.any()):
            present_candidates.append(region)

    scores = np.zeros((len(target_regions), len(present_candidates)), dtype=np.float64)
    for target_idx, target_region in enumerate(target_regions):
        for candidate_idx, candidate_region in enumerate(present_candidates):
            union = np.logical_or(target_region, candidate_region).sum()
            if union:
                scores[target_idx, candidate_idx] = np.logical_and(target_region, candidate_region).sum() / union

    assignment = ()
    if present_candidates:
        assignment_size = min(len(target_regions), len(present_candidates))
        assignment = max(
            itertools.permutations(range(len(present_candidates)), assignment_size),
            key=lambda candidate_ids: sum(
                scores[target_idx, candidate_id]
                for target_idx, candidate_id in enumerate(candidate_ids)
            ),
        )

    output = np.zeros_like(reference, dtype=np.uint8)
    matched = 0
    for target_idx, (target_color, target_region) in enumerate(zip(target_colors, target_regions)):
        selected_region = target_region
        if target_idx < len(assignment):
            candidate_idx = assignment[target_idx]
            if scores[target_idx, candidate_idx] > 0.01:
                selected_region = present_candidates[candidate_idx]
                matched += 1
        output[selected_region] = np.asarray(target_color, dtype=np.uint8)
    return output, matched


def _normalize_recast_character_mappings(request, body, workspace):
    """Resolve explicit Recast character mappings while retaining legacy API input.

    New clients send one mapping per source person.  Older clients send a
    single target/reference plus ``person_count``; that form is intentionally
    left grouped so existing saved settings remain loadable.
    """
    raw_mappings = body.get("character_mappings")
    explicit = isinstance(raw_mappings, list) and len(raw_mappings) > 0
    if explicit:
        if len(raw_mappings) > len(_RECAST_MASK_COLORS):
            raise ValueError("SCAIL-2 supports at most five character mappings.")
        mappings = []
        for index, raw_mapping in enumerate(raw_mappings):
            if not isinstance(raw_mapping, dict):
                raise ValueError(f"Character mapping {index + 1} is invalid.")
            target = str(raw_mapping.get("target") or "").strip()
            if not target:
                raise ValueError(
                    f"Character mapping {index + 1} needs a source-person description."
                )
            raw_reference = (
                raw_mapping.get("ref_image_path")
                or raw_mapping.get("reference_image_path")
            )
            reference_path = _resolve_recast_media(
                request, raw_reference, workspace,
            )
            if not reference_path:
                raise ValueError(
                    f"Character mapping {index + 1} reference was not found: "
                    f"{raw_reference}"
                )
            additional_paths = []
            raw_additional = (
                raw_mapping.get("additional_ref_image_paths")
                or raw_mapping.get("additional_reference_paths")
                or []
            )
            if not isinstance(raw_additional, list):
                raise ValueError(
                    f"Character mapping {index + 1} additional views must be a list."
                )
            for raw_path in raw_additional[:4]:
                resolved = _resolve_recast_media(request, raw_path, workspace)
                if not resolved:
                    raise ValueError(
                        f"Character mapping {index + 1} additional view was not found: "
                        f"{raw_path}"
                    )
                additional_paths.append(resolved)
            mappings.append({
                "id": str(raw_mapping.get("id") or f"recast-{index + 1}"),
                "target": target,
                "ref_image_path": reference_path,
                "additional_ref_image_paths": additional_paths,
                "reference_aligned_to_source": (
                    raw_mapping.get("reference_aligned_to_source") is True
                ),
            })
        if len(mappings) > 1 and any(
            mapping["reference_aligned_to_source"] for mapping in mappings
        ):
            raise ValueError(
                "An edited full-frame reference can currently map one replacement. "
                "Use standalone primary references for multi-character mapping."
            )
        return mappings, True

    raw_reference = body.get("ref_image_path")
    reference_path = _resolve_recast_media(request, raw_reference, workspace)
    if not reference_path:
        raise ValueError(f"Reference image not found: {raw_reference}")
    additional_paths = []
    raw_additional = body.get("additional_ref_image_paths") or []
    if not isinstance(raw_additional, list):
        raise ValueError("Additional reference views must be a list.")
    for raw_path in raw_additional[:4]:
        resolved = _resolve_recast_media(request, raw_path, workspace)
        if not resolved:
            raise ValueError(f"Additional reference view was not found: {raw_path}")
        additional_paths.append(resolved)
    return [{
        "id": "recast-1",
        "target": str(body.get("target") or "person").strip() or "person",
        "ref_image_path": reference_path,
        "additional_ref_image_paths": additional_paths,
        "reference_aligned_to_source": (
            body.get("reference_aligned_to_source") is True
        ),
    }], False


def _compose_recast_character_masks(
    mapping_masks, colors, overlap_limit=0.35,
    background_color=(255, 255, 255),
):
    """Merge separately tracked people into deterministic SCAIL color slots."""
    import numpy as np

    if not mapping_masks or len(mapping_masks) != len(colors):
        raise ValueError("Recast needs one tracked mask per character color.")
    shape = np.asarray(mapping_masks[0]).shape
    if len(shape) not in (3, 4):
        raise ValueError(f"Unsupported Recast character-mask shape: {shape}.")
    region_shape = shape[:-1] if shape[-1] == 3 else shape
    background = np.asarray(background_color, dtype=np.uint8)
    if background.shape != (3,):
        raise ValueError("Character-mask background must be one RGB color.")
    output = np.empty((*region_shape, 3), dtype=np.uint8)
    output[...] = background
    occupied = np.zeros(region_shape, dtype=bool)
    overlaps = []
    for index, (raw_mask, color) in enumerate(zip(mapping_masks, colors)):
        mask = np.asarray(raw_mask)
        if mask.shape != shape:
            raise ValueError("Every Recast character mask must have matching dimensions.")
        region = np.any(mask > 30, axis=-1) if mask.shape[-1] == 3 else mask.astype(bool)
        area = int(region.sum())
        if area <= 0:
            raise ValueError(f"Character mapping {index + 1} matched no pixels.")
        overlap = np.logical_and(region, occupied)
        overlap_fraction = float(overlap.sum()) / float(max(1, area))
        overlaps.append(overlap_fraction)
        if overlap_fraction > float(overlap_limit):
            raise ValueError(
                f"Character mapping {index + 1} overlaps an earlier mapping by "
                f"{overlap_fraction:.0%}. Use more specific source descriptions."
            )
        # Earlier cards win the occasional occlusion pixel, making color
        # assignment stable regardless of SAM's internal object ordering.
        writable = region & ~occupied
        output[writable] = np.asarray(color, dtype=np.uint8)
        occupied |= region
    return output, overlaps


def _detect_recast_shot_ranges(
    source_frames, min_shot_frames=4, absolute_cut_threshold=0.12,
):
    """Return half-open camera-shot ranges for timeline-aware SAM3 tracking.

    A hard cut needs a fresh text anchor: carrying a segmentation track
    through the cut can attach one character card to whichever person happens
    to occupy the same screen position in the next shot. The detector combines
    low-resolution pixel change with color-histogram change and uses the
    video's own motion baseline, so ordinary camera motion is not treated as a
    cut. The absolute floor remains deliberately below typical same-location
    shot/reverse-shot edits: their shared lighting and background can keep the
    combined score below 0.30 even though the subject changes completely.
    """
    import cv2
    import numpy as np

    frames = np.asarray(source_frames, dtype=np.uint8)
    if frames.ndim != 4 or frames.shape[-1] != 3:
        raise ValueError(
            "Recast shot detection needs T/H/W/RGB source frames."
        )
    frame_count = int(len(frames))
    if frame_count <= 1:
        return [(0, frame_count)] if frame_count else []

    thumbnails = []
    histograms = []
    for frame in frames:
        thumbnail = cv2.resize(
            frame,
            (64, 36),
            interpolation=cv2.INTER_AREA,
        )
        thumbnails.append(thumbnail.astype(np.float32) / 255.0)
        histogram = cv2.calcHist(
            [thumbnail],
            [0, 1],
            None,
            [16, 16],
            [0, 256, 0, 256],
        )
        cv2.normalize(histogram, histogram)
        histograms.append(histogram)

    scores = []
    for index in range(1, frame_count):
        pixel_change = float(
            np.mean(np.abs(thumbnails[index] - thumbnails[index - 1]))
        )
        histogram_change = float(
            cv2.compareHist(
                histograms[index - 1],
                histograms[index],
                cv2.HISTCMP_BHATTACHARYYA,
            )
        )
        scores.append(0.60 * pixel_change + 0.40 * histogram_change)
    score_array = np.asarray(scores, dtype=np.float32)
    median = float(np.median(score_array))
    mad = float(np.median(np.abs(score_array - median)))
    adaptive_threshold = median + max(0.10, 6.0 * mad)
    threshold = max(float(absolute_cut_threshold), adaptive_threshold)

    minimum = max(2, int(min_shot_frames))
    boundaries = [0]
    for frame_index, score in enumerate(scores, start=1):
        if score < threshold:
            continue
        previous = scores[frame_index - 2] if frame_index > 1 else -1.0
        following = (
            scores[frame_index]
            if frame_index < len(scores)
            else -1.0
        )
        if score < previous or score < following:
            continue
        if frame_index - boundaries[-1] < minimum:
            continue
        if frame_count - frame_index < minimum:
            continue
        boundaries.append(frame_index)
    boundaries.append(frame_count)
    return [
        (start, end)
        for start, end in zip(boundaries, boundaries[1:])
        if end > start
    ]


def _summarize_recast_mapping_mask(mask, fps=25.0):
    """Describe where one independently tracked mapping appears."""
    import numpy as np

    array = np.asarray(mask)
    if array.ndim == 4 and array.shape[-1] == 3:
        region = np.any(array > 30, axis=-1)
    elif array.ndim == 3:
        region = array.astype(bool)
    else:
        raise ValueError(
            f"Unsupported Recast mapping-mask shape: {array.shape}."
        )
    areas = region.reshape(len(region), -1).sum(axis=1)
    present_indices = np.flatnonzero(areas > 0)
    if not len(present_indices):
        return None

    appearance_ranges = []
    range_start = int(present_indices[0])
    previous = range_start
    for raw_index in present_indices[1:]:
        frame_index = int(raw_index)
        if frame_index > previous + 1:
            appearance_ranges.append([range_start, previous + 1])
            range_start = frame_index
        previous = frame_index
    appearance_ranges.append([range_start, previous + 1])

    anchor_index = int(np.argmax(areas))
    safe_fps = float(fps or 25.0)
    return {
        "first_frame_index": int(present_indices[0]),
        "last_frame_index": int(present_indices[-1]),
        "anchor_frame_index": anchor_index,
        "first_time_seconds": float(present_indices[0]) / safe_fps,
        "anchor_time_seconds": float(anchor_index) / safe_fps,
        "appearance_ranges": appearance_ranges,
        "anchor_area": int(areas[anchor_index]),
        "present_frame_count": int(len(present_indices)),
    }


def _select_recast_timeline_anchor(mapping_masks):
    """Choose a useful shared scene frame and report true co-occurrence."""
    import numpy as np

    if not mapping_masks:
        return None, None
    regions = []
    areas = []
    for raw_mask in mapping_masks:
        mask = np.asarray(raw_mask)
        region = (
            np.any(mask > 30, axis=-1)
            if mask.ndim == 4 and mask.shape[-1] == 3
            else mask.astype(bool)
        )
        regions.append(region)
        areas.append(region.reshape(len(region), -1).sum(axis=1))
    frame_count = len(regions[0])
    if any(len(region) != frame_count for region in regions):
        raise ValueError("Recast mapping timelines have different lengths.")

    present = np.stack([area > 0 for area in areas], axis=0)
    common_indices = np.flatnonzero(np.all(present, axis=0))
    if len(common_indices):
        common_scores = np.stack(areas, axis=0)[:, common_indices].sum(axis=0)
        common_index = int(common_indices[int(np.argmax(common_scores))])
    else:
        common_index = None

    visible_counts = present.sum(axis=0)
    total_areas = np.stack(areas, axis=0).sum(axis=0)
    scene_index = int(np.lexsort((total_areas, visible_counts))[-1])
    return common_index, scene_index


def _normalize_recast_tracking_target(target):
    """Use wording SAM3 grounds reliably without changing user metadata."""
    import re

    text = " ".join(str(target or "").split())
    # SAM3 consistently grounds "person in red/black/..." more reliably than
    # the equivalent "person wearing ..." phrasing in camera-shot close-ups.
    return re.sub(r"\bwearing\b", "in", text, flags=re.IGNORECASE)


def _recast_mask_region(mask):
    """Return a boolean T/H/W or H/W region from a Recast mask."""
    import numpy as np

    array = np.asarray(mask)
    if array.ndim in (3, 4) and array.shape[-1] == 3:
        return np.any(array > 30, axis=-1)
    if array.ndim in (2, 3):
        return array.astype(bool)
    raise ValueError(f"Unsupported Recast mask shape: {array.shape}.")


def _find_recast_unmapped_shots(
    mapping_masks, shot_ranges, min_area_ratio=0.0001,
):
    """Return camera shots where no mapped character was grounded."""
    import numpy as np

    regions = [_recast_mask_region(mask) for mask in mapping_masks or []]
    if not regions:
        return []
    frame_count = int(len(regions[0]))
    frame_area = int(regions[0].shape[-2] * regions[0].shape[-1])
    minimum_pixels = max(
        16,
        int(round(frame_area * max(0.0, float(min_area_ratio)))),
    )
    unresolved = []
    for shot_index, (raw_start, raw_end) in enumerate(shot_ranges or []):
        start = max(0, min(frame_count, int(raw_start)))
        end = max(start, min(frame_count, int(raw_end)))
        if end <= start:
            continue
        largest = max(
            (
                int(
                    region[start:end]
                    .reshape(end - start, -1)
                    .sum(axis=1)
                    .max()
                )
                for region in regions
            ),
            default=0,
        )
        if largest < minimum_pixels:
            unresolved.append({
                "shot_index": shot_index,
                "start_frame": start,
                "end_frame": end,
            })
    return unresolved


def _recast_appearance_descriptor(source_frame, subject_region):
    """Build a compact clothing/appearance descriptor for shot reacquisition."""
    import cv2
    import numpy as np

    frame = np.asarray(source_frame, dtype=np.uint8)
    region = np.asarray(subject_region).astype(bool)
    if (
        frame.ndim != 3
        or frame.shape[-1] != 3
        or region.shape != frame.shape[:2]
        or not bool(region.any())
    ):
        return None

    # Erode away SAM's boundary pixels so the descriptor represents the
    # person rather than the changing background around their silhouette.
    edge = max(3, int(round(min(region.shape) * 0.012)))
    if edge % 2 == 0:
        edge += 1
    core = cv2.erode(
        region.astype(np.uint8),
        np.ones((edge, edge), dtype=np.uint8),
        iterations=1,
    ).astype(bool)
    if int(core.sum()) < 100:
        core = region
    mask = core.astype(np.uint8)

    hsv = cv2.cvtColor(frame, cv2.COLOR_RGB2HSV)
    lab = cv2.cvtColor(frame, cv2.COLOR_RGB2LAB)
    hue_saturation = cv2.calcHist(
        [hsv],
        [0, 1],
        mask,
        [24, 8],
        [0, 180, 0, 256],
    ).reshape(-1)
    perceptual_color = cv2.calcHist(
        [lab],
        [0, 1, 2],
        mask,
        [8, 8, 8],
        [0, 256, 0, 256, 0, 256],
    ).reshape(-1)
    hue_saturation /= max(1.0, float(hue_saturation.sum()))
    perceptual_color /= max(1.0, float(perceptual_color.sum()))
    descriptor = np.concatenate(
        [hue_saturation, perceptual_color],
    ).astype(np.float32, copy=False)
    norm = float(np.linalg.norm(descriptor))
    return descriptor / norm if norm > 1e-8 else None


def _build_recast_mapping_appearance_prototypes(
    source_frames, mapping_masks, shot_ranges, max_per_mapping=6,
):
    """Collect high-confidence per-shot source appearances for each card."""
    import numpy as np

    frames = np.asarray(source_frames, dtype=np.uint8)
    prototypes = []
    for raw_mask in mapping_masks or []:
        region = _recast_mask_region(raw_mask)
        candidates = []
        for raw_start, raw_end in shot_ranges or [(0, len(frames))]:
            start = max(0, min(len(frames), int(raw_start)))
            end = max(start, min(len(frames), int(raw_end)))
            if end <= start:
                continue
            areas = (
                region[start:end]
                .reshape(end - start, -1)
                .sum(axis=1)
            )
            if not int(areas.max(initial=0)):
                continue
            frame_index = start + int(np.argmax(areas))
            descriptor = _recast_appearance_descriptor(
                frames[frame_index],
                region[frame_index],
            )
            if descriptor is not None:
                candidates.append((
                    int(areas[frame_index - start]),
                    descriptor,
                ))
        candidates.sort(key=lambda item: item[0], reverse=True)
        prototypes.append([
            descriptor
            for _area, descriptor in candidates[:max_per_mapping]
        ])
    return prototypes


def _recover_recast_unmapped_shots(
    source_frames, mapping_masks, shot_ranges, unresolved_shots,
    compact_people_mask, compact_ranges, *,
    minimum_similarity=0.72, minimum_margin=0.06,
):
    """Assign generic SAM people in blank shots by source appearance.

    Text grounding remains authoritative. This fallback is used only when an
    entire camera shot has no mapped target, and only accepts a generic person
    when their clothing/color descriptor clearly favors one established
    mapping prototype.
    """
    import numpy as np

    frames = np.asarray(source_frames, dtype=np.uint8)
    people = np.asarray(compact_people_mask, dtype=np.uint8)
    # These masks are private products of the current tracking job. Mutate
    # them in place instead of duplicating several full-resolution video
    # tensors (which can consume multiple gigabytes on a 20-second clip).
    output_masks = [
        np.asarray(mask, dtype=np.uint8)
        for mask in mapping_masks
    ]
    prototypes = _build_recast_mapping_appearance_prototypes(
        frames,
        output_masks,
        shot_ranges,
    )
    recovered = []

    for shot, compact_bounds in zip(
        unresolved_shots,
        compact_ranges,
    ):
        compact_start, compact_end = (
            int(compact_bounds[0]),
            int(compact_bounds[1]),
        )
        source_start, source_end = (
            int(shot["start_frame"]),
            int(shot["end_frame"]),
        )
        if (
            compact_end <= compact_start
            or source_end - source_start != compact_end - compact_start
        ):
            continue

        candidates = []
        shot_people = people[compact_start:compact_end]
        for candidate_index, color in enumerate(_RECAST_MASK_COLORS):
            color_array = np.asarray(color, dtype=np.uint8)
            region = np.all(shot_people == color_array, axis=-1)
            areas = region.reshape(len(region), -1).sum(axis=1)
            if not int(areas.max(initial=0)):
                continue
            local_anchor = int(np.argmax(areas))
            descriptor = _recast_appearance_descriptor(
                frames[source_start + local_anchor],
                region[local_anchor],
            )
            if descriptor is None:
                continue
            scores = []
            for mapping_prototypes in prototypes:
                scores.append(max(
                    (
                        float(np.dot(descriptor, prototype))
                        for prototype in mapping_prototypes
                    ),
                    default=0.0,
                ))
            candidates.append({
                "candidate_index": candidate_index,
                "region": region,
                "scores": scores,
                "area": int(areas[local_anchor]),
            })

        pairings = []
        for candidate in candidates:
            scores = list(candidate["scores"])
            for mapping_index, score in enumerate(scores):
                alternatives = [
                    other_score
                    for other_index, other_score in enumerate(scores)
                    if other_index != mapping_index
                ]
                margin = score - max(alternatives, default=0.0)
                if (
                    score >= float(minimum_similarity)
                    and margin >= float(minimum_margin)
                    and prototypes[mapping_index]
                ):
                    pairings.append((
                        score,
                        margin,
                        candidate["area"],
                        candidate["candidate_index"],
                        mapping_index,
                        candidate["region"],
                    ))
        pairings.sort(reverse=True, key=lambda item: item[:3])

        used_candidates = set()
        used_mappings = set()
        for (
            score, margin, _area, candidate_index, mapping_index, region,
        ) in pairings:
            if (
                candidate_index in used_candidates
                or mapping_index in used_mappings
            ):
                continue
            color_array = np.asarray(
                _RECAST_MASK_COLORS[mapping_index],
                dtype=np.uint8,
            )
            target = output_masks[mapping_index][source_start:source_end]
            target[region] = color_array
            used_candidates.add(candidate_index)
            used_mappings.add(mapping_index)
            recovered.append({
                "shot_index": int(shot["shot_index"]),
                "mapping_index": mapping_index,
                "similarity": round(float(score), 4),
                "margin": round(float(margin), 4),
            })
    return output_masks, recovered


def _build_recast_character_mask(
    source_video, mappings, output_dir, progress_callback=None,
    abort_callback=None,
):
    """Track mapped characters across shots, then save one color mask."""
    import numpy as np
    from shared import magic_mask

    source_path, source_frames, fps = magic_mask.prepare_video_mask_input(
        source_video,
    )
    shot_ranges = _detect_recast_shot_ranges(source_frames)
    if len(shot_ranges) > 1:
        safe_fps = float(fps or 25.0)
        cut_times = ", ".join(
            f"{start / safe_fps:.2f}s"
            for start, _end in shot_ranges[1:]
        )
        print(
            f"[Recast] Detected {len(shot_ranges)} camera shots; "
            f"reacquiring mapped characters after cuts at {cut_times}."
        )
    else:
        print(
            "[Recast] Detected one continuous camera shot; "
            "tracking mapped characters across the full timeline."
        )
    mapping_masks = []
    mapping_summaries = []
    tracking_targets = []
    total_mappings = len(mappings)
    for index, mapping in enumerate(mappings):
        if abort_callback is not None:
            abort_callback()

        def _mapping_progress(done, total, mapping_index=index):
            if abort_callback is not None:
                abort_callback()
            if progress_callback is not None:
                progress_callback(
                    mapping_index,
                    total_mappings,
                    done,
                    total,
                )

        color = _RECAST_MASK_COLORS[index]
        tracking_target = _normalize_recast_tracking_target(
            mapping["target"],
        )
        tracking_targets.append(tracking_target)
        if tracking_target != mapping["target"]:
            print(
                "[Recast] SAM3 tracking wording normalized: "
                f"'{mapping['target']}' -> '{tracking_target}'."
            )
        tracked = magic_mask.generate_keyword_masks(
            source_frames,
            tracking_target,
            no_hole=True,
            colorize_objects=True,
            color_palette=[color],
            max_colored_objects=1,
            progress_callback=_mapping_progress,
            tracking_segments=shot_ranges,
        )
        summary = _summarize_recast_mapping_mask(tracked, fps)
        if summary is None:
            raise ValueError(
                f"Character mapping {index + 1} found no "
                f"'{mapping['target']}' anywhere in the selected video. "
                "Try a more specific description or adjust the trim range."
            )
        summary.update({
            "mapping_index": index,
            "target": mapping["target"],
            "tracking_target": tracking_target,
            "color": list(color),
        })
        mapping_masks.append(tracked)
        mapping_summaries.append(summary)

    unresolved_shots = _find_recast_unmapped_shots(
        mapping_masks,
        shot_ranges,
    )
    recovered_shots = []
    if unresolved_shots:
        compact_parts = []
        compact_ranges = []
        compact_offset = 0
        for shot in unresolved_shots:
            start = int(shot["start_frame"])
            end = int(shot["end_frame"])
            compact_parts.append(source_frames[start:end])
            length = end - start
            compact_ranges.append(
                (compact_offset, compact_offset + length),
            )
            compact_offset += length
        recovery_frames = (
            compact_parts[0]
            if len(compact_parts) == 1
            else np.concatenate(compact_parts, axis=0)
        )
        shot_numbers = ", ".join(
            str(int(shot["shot_index"]) + 1)
            for shot in unresolved_shots
        )
        print(
            "[Recast] No mapped target was grounded in camera shot"
            f"{'s' if len(unresolved_shots) != 1 else ''} "
            f"{shot_numbers}; running generic-person appearance recovery."
        )

        def _recovery_progress(_done, _total):
            if abort_callback is not None:
                abort_callback()

        compact_people_mask = magic_mask.generate_keyword_masks(
            recovery_frames,
            "person",
            no_hole=True,
            colorize_objects=True,
            color_palette=_RECAST_MASK_COLORS,
            max_colored_objects=len(_RECAST_MASK_COLORS),
            progress_callback=_recovery_progress,
            tracking_segments=compact_ranges,
        )
        mapping_masks, recovered_shots = (
            _recover_recast_unmapped_shots(
                source_frames,
                mapping_masks,
                shot_ranges,
                unresolved_shots,
                compact_people_mask,
                compact_ranges,
            )
        )
        del compact_people_mask
        del recovery_frames
        if recovered_shots:
            recovery_summary = ", ".join(
                "shot "
                f"{item['shot_index'] + 1} -> character "
                f"{chr(65 + item['mapping_index'])} "
                f"({item['similarity']:.2f})"
                for item in recovered_shots
            )
            print(
                "[Recast] Appearance recovery accepted "
                f"{recovery_summary}."
            )
            refreshed_summaries = []
            for index, mapping_mask in enumerate(mapping_masks):
                refreshed = _summarize_recast_mapping_mask(
                    mapping_mask,
                    fps,
                )
                if refreshed is None:
                    refreshed = mapping_summaries[index]
                refreshed.update({
                    "mapping_index": index,
                    "target": mappings[index]["target"],
                    "tracking_target": tracking_targets[index],
                    "color": list(_RECAST_MASK_COLORS[index]),
                    "recovered_shot_indices": [
                        item["shot_index"]
                        for item in recovered_shots
                        if item["mapping_index"] == index
                    ],
                })
                refreshed_summaries.append(refreshed)
            mapping_summaries = refreshed_summaries
        else:
            print(
                "[Recast] Generic-person recovery found no sufficiently "
                "distinct identity match; unresolved shots remain unchanged."
            )
    merged, overlaps = _compose_recast_character_masks(
        mapping_masks,
        _RECAST_MASK_COLORS[:total_mappings],
    )
    common_frame_index, scene_anchor_index = (
        _select_recast_timeline_anchor(mapping_masks)
    )
    for summary, overlap in zip(mapping_summaries, overlaps):
        summary["overlap_fraction"] = float(overlap)
    mask_path = magic_mask.save_mask_video(
        source_path,
        merged,
        fps,
        [mapping["target"] for mapping in mappings],
        output_dir=output_dir,
        abort_callback=abort_callback,
        background_color=(255, 255, 255),
    )
    return {
        "video_mask": mask_path,
        "mask_frames": merged,
        "source_frames": source_frames,
        "fps": fps,
        "overlaps": overlaps,
        "mapping_masks": mapping_masks,
        "mapping_summaries": mapping_summaries,
        "recovered_shots": recovered_shots,
        "shot_ranges": [list(bounds) for bounds in shot_ranges],
        "shot_count": len(shot_ranges),
        "common_frame_index": common_frame_index,
        "scene_anchor_index": scene_anchor_index,
        "timeline_aware": (
            len(shot_ranges) > 1
            or (
                total_mappings > 1
                and common_frame_index is None
            )
            or any(
                summary["first_frame_index"] > 0
                for summary in mapping_summaries
            )
        ),
    }


def _plan_recast_shot_segments(
    mapping_masks, shot_ranges, min_area_ratio=0.0001, *,
    split_cast_transitions=False, min_cast_run_frames=4,
):
    """Resolve active mappings and the best composition anchor per segment.

    Presence is evaluated inside each detected camera shot rather than across
    a diffusion window. This prevents two characters in adjacent
    shot/reverse-shot frames from being mistaken for a simultaneous cast.

    Recast can additionally divide one camera shot when its stable set of
    mapped characters changes. SCAIL-2 then starts every generated segment
    with the same semantic colors represented by its primary reference,
    instead of asking it to introduce a second identity partway through a
    window. Short presence/dropout runs are absorbed into their neighbors so
    detector flicker and momentary occlusion do not create tiny jobs.
    """
    import numpy as np

    masks = [np.asarray(mask) for mask in mapping_masks or []]
    if not masks:
        raise ValueError("Shot-aware Recast needs tracked mapping masks.")
    frame_count = int(len(masks[0]))
    if frame_count <= 0:
        raise ValueError("Shot-aware Recast received an empty timeline.")
    if any(len(mask) != frame_count for mask in masks):
        raise ValueError("Shot-aware Recast mapping timelines differ in length.")

    regions = []
    areas = []
    for mask in masks:
        if mask.ndim == 4 and mask.shape[-1] == 3:
            region = np.any(mask > 30, axis=-1)
        elif mask.ndim == 3:
            region = mask.astype(bool)
        else:
            raise ValueError(
                f"Unsupported Recast mapping-mask shape: {mask.shape}."
            )
        regions.append(region)
        areas.append(region.reshape(frame_count, -1).sum(axis=1))

    frame_area = int(regions[0].shape[-2] * regions[0].shape[-1])
    minimum_pixels = max(
        16,
        int(round(frame_area * max(0.0, float(min_area_ratio)))),
    )
    try:
        minimum_cast_run = max(1, int(min_cast_run_frames))
    except (TypeError, ValueError):
        minimum_cast_run = 4

    def _runs(values):
        values = np.asarray(values, dtype=bool)
        if not len(values):
            return []
        result = []
        run_start = 0
        run_value = bool(values[0])
        for index in range(1, len(values)):
            value = bool(values[index])
            if value == run_value:
                continue
            result.append((run_start, index, run_value))
            run_start, run_value = index, value
        result.append((run_start, len(values), run_value))
        return result

    def _stabilize_presence(values):
        stable = np.asarray(values, dtype=bool).copy()
        if minimum_cast_run <= 1 or len(stable) <= 1:
            return stable
        while True:
            presence_runs = _runs(stable)
            if len(presence_runs) <= 1:
                return stable
            short = [
                (end - start, run_index, start, end)
                for run_index, (start, end, _value) in enumerate(
                    presence_runs
                )
                if end - start < minimum_cast_run
            ]
            if not short:
                return stable
            _length, run_index, start, end = min(short)
            if run_index == 0:
                replacement = presence_runs[1][2]
            elif run_index == len(presence_runs) - 1:
                replacement = presence_runs[-2][2]
            else:
                # Boolean runs alternate, so both neighbors normally agree.
                # The duration tie-break keeps this safe if the representation
                # ever expands beyond a single presence bit.
                left = presence_runs[run_index - 1]
                right = presence_runs[run_index + 1]
                replacement = (
                    left[2]
                    if (
                        left[2] == right[2]
                        or left[1] - left[0] >= right[1] - right[0]
                    )
                    else right[2]
                )
            stable[start:end] = replacement

    def _signature_runs(stable_presence):
        if stable_presence.shape[1] <= 0:
            return []
        signatures = [
            tuple(np.flatnonzero(stable_presence[:, frame_index]).tolist())
            for frame_index in range(stable_presence.shape[1])
        ]
        result = []
        run_start = 0
        run_signature = signatures[0]
        for frame_index in range(1, len(signatures)):
            signature = signatures[frame_index]
            if signature == run_signature:
                continue
            result.append([run_start, frame_index, run_signature])
            run_start, run_signature = frame_index, signature
        result.append([run_start, len(signatures), run_signature])

        # Two long tracks can overlap or hand off for only a frame or two even
        # after each individual presence timeline is stable. Fold that brief
        # combined signature into the most compatible neighboring segment.
        while len(result) > 1:
            short = [
                (end - start, run_index)
                for run_index, (start, end, _signature) in enumerate(result)
                if end - start < minimum_cast_run
            ]
            if not short:
                break
            _length, run_index = min(short)
            current = set(result[run_index][2])
            neighbor_indices = [
                index
                for index in (run_index - 1, run_index + 1)
                if 0 <= index < len(result)
            ]
            replacement_index = max(
                neighbor_indices,
                key=lambda index: (
                    len(current.intersection(result[index][2])),
                    -len(current.symmetric_difference(result[index][2])),
                    result[index][1] - result[index][0],
                    -abs(index - run_index),
                ),
            )
            result[run_index][2] = result[replacement_index][2]
            merged = []
            for start, end, signature in result:
                if merged and merged[-1][2] == signature:
                    merged[-1][1] = end
                else:
                    merged.append([start, end, signature])
            result = merged
        return result

    normalized_ranges = []
    for raw_start, raw_end in shot_ranges or [(0, frame_count)]:
        start = max(0, min(frame_count, int(raw_start)))
        end = max(start, min(frame_count, int(raw_end)))
        if end > start:
            normalized_ranges.append((start, end))
    if not normalized_ranges:
        normalized_ranges = [(0, frame_count)]

    plans = []
    for camera_shot_index, (shot_start, shot_end) in enumerate(
        normalized_ranges
    ):
        shot_areas = np.stack(
            [area[shot_start:shot_end] for area in areas],
            axis=0,
        )
        if split_cast_transitions:
            stable_presence = np.stack([
                _stabilize_presence(mapping_area >= minimum_pixels)
                for mapping_area in shot_areas
            ])
            local_segments = _signature_runs(stable_presence)
        else:
            active = tuple(
                index
                for index in range(len(masks))
                if int(shot_areas[index].max(initial=0)) >= minimum_pixels
            )
            local_segments = [[0, shot_end - shot_start, active]]

        for cast_segment_index, (
            local_start, local_end, active_signature,
        ) in enumerate(local_segments):
            start = shot_start + int(local_start)
            end = shot_start + int(local_end)
            active_indices = [int(index) for index in active_signature]
            segment_areas = np.stack(
                [area[start:end] for area in areas],
                axis=0,
            )
            if active_indices:
                active_areas = segment_areas[active_indices]
                visible = active_areas >= minimum_pixels
                common = np.all(visible, axis=0)
                if bool(common.any()):
                    candidates = np.flatnonzero(common)
                    first_all_active = start + int(candidates[0])
                    # Favor a frame where the least-visible active character
                    # is still large, then total area as the tie-breaker.
                    minimum_area = active_areas[:, candidates].min(axis=0)
                    total_area = active_areas[:, candidates].sum(axis=0)
                    local_anchor = int(
                        candidates[
                            np.lexsort((total_area, minimum_area))[-1]
                        ]
                    )
                    cooccurring = True
                else:
                    first_all_active = None
                    visible_count = visible.sum(axis=0)
                    total_area = active_areas.sum(axis=0)
                    local_anchor = int(
                        np.lexsort((total_area, visible_count))[-1]
                    )
                    cooccurring = False
                anchor = start + local_anchor
            else:
                anchor = start
                first_all_active = None
                cooccurring = False

            initial_active = [
                index
                for index in active_indices
                if int(areas[index][start]) >= minimum_pixels
            ]
            active_count = len(active_indices)
            plans.append({
                "shot_index": len(plans),
                "camera_shot_index": camera_shot_index,
                "cast_segment_index": cast_segment_index,
                "segment_reason": (
                    "camera_shot"
                    if cast_segment_index == 0
                    else "cast_change"
                ),
                "start_frame": start,
                "end_frame": end,
                "frame_count": end - start,
                "anchor_frame_index": anchor,
                "first_all_active_frame_index": first_all_active,
                "active_mapping_indices": active_indices,
                "initial_active_mapping_indices": initial_active,
                "starts_with_all_active_mappings": (
                    initial_active == active_indices
                ),
                "cooccurring": cooccurring,
                "mode": (
                    "passthrough"
                    if active_count == 0
                    else "solo"
                    if active_count == 1
                    else "group"
                ),
            })
    return plans


def _resample_recast_tracking_timeline(
    source_frames, mapping_masks, shot_ranges, target_frame_count,
):
    """Resample tracked frames and cuts onto Recast's generation timeline."""
    import numpy as np

    source = np.asarray(source_frames)
    source_count = int(len(source))
    target_count = int(target_frame_count)
    if source_count <= 0 or target_count <= 0:
        raise ValueError("Recast timeline frame counts must be positive.")
    masks = [np.asarray(mask) for mask in mapping_masks or []]
    if any(len(mask) != source_count for mask in masks):
        raise ValueError("Recast masks do not match the source timeline.")

    indices = np.floor(
        np.arange(target_count, dtype=np.float64)
        * float(source_count)
        / float(target_count)
    ).astype(np.int64)
    indices = np.clip(indices, 0, source_count - 1)
    resampled_source = source[indices]
    resampled_masks = [mask[indices] for mask in masks]

    ranges = list(shot_ranges or [(0, source_count)])
    if not ranges:
        ranges = [(0, source_count)]
    shot_count = min(len(ranges), target_count)
    ranges = ranges[:shot_count]
    boundaries = [0]
    for boundary_index, (_start, raw_end) in enumerate(ranges[:-1], 1):
        remaining = shot_count - boundary_index
        scaled = int(round(
            max(0, min(source_count, int(raw_end)))
            * float(target_count)
            / float(source_count)
        ))
        lower = boundaries[-1] + 1
        upper = target_count - remaining
        boundaries.append(max(lower, min(upper, scaled)))
    boundaries.append(target_count)
    resampled_ranges = [
        (start, end)
        for start, end in zip(boundaries, boundaries[1:])
        if end > start
    ]
    return resampled_source, resampled_masks, resampled_ranges


def _remap_recast_shot_mask(
    semantic_mask, active_mapping_indices,
    background_color=(255, 255, 255),
):
    """Convert global card colors to contiguous per-shot SCAIL colors."""
    import numpy as np

    mask = np.asarray(semantic_mask, dtype=np.uint8)
    if mask.ndim not in (3, 4) or mask.shape[-1] != 3:
        raise ValueError(
            f"Recast semantic mask must be H/W/RGB or T/H/W/RGB; got {mask.shape}."
        )
    output = np.empty_like(mask, dtype=np.uint8)
    output[...] = np.asarray(background_color, dtype=np.uint8)
    for local_index, mapping_index in enumerate(active_mapping_indices or []):
        global_color = np.asarray(
            _RECAST_MASK_COLORS[int(mapping_index)],
            dtype=np.uint8,
        )
        local_color = np.asarray(
            _RECAST_MASK_COLORS[local_index],
            dtype=np.uint8,
        )
        output[np.all(mask == global_color, axis=-1)] = local_color
    return output


def _quantize_recast_shot_frame_count(
    frame_count, minimum_frames, latent_size,
):
    """Return a valid model length and tail trim for one exact-length shot."""
    count = int(frame_count)
    minimum = max(1, int(minimum_frames))
    latent = max(1, int(latent_size))
    if count <= 0:
        raise ValueError("A Recast shot must contain at least one frame.")
    generated = ((count - 1 + latent - 1) // latent) * latent + 1
    generated = max(generated, minimum)
    if (generated - 1) % latent:
        generated = (
            (generated - 1 + latent - 1) // latent
        ) * latent + 1
    return generated, generated - count


def _build_recast_shot_prompt(
    active_count, *, finished_video_prompt=None, total_mapping_count=None,
):
    """Build text that cannot introduce identities absent from this shot."""
    count = max(1, min(5, int(active_count)))
    try:
        total_count = max(1, min(5, int(total_mapping_count)))
    except (TypeError, ValueError):
        total_count = None
    requested_prompt = str(finished_video_prompt or "").strip()
    if (
        count > 1
        and total_count == count
        and any(character.isalnum() for character in requested_prompt)
    ):
        # When the whole requested cast shares a shot, the user's
        # finished-video description is safe and materially helps SCAIL-2
        # retain clothing details that may be outside a portrait reference.
        # Solo/subset shots stay neutral so an absent identity cannot leak in.
        return requested_prompt
    if count == 1:
        return (
            "A clearly defined character performs naturally within the "
            "original scene. The character's face, hair, body shape, and "
            "complete outfit remain visually consistent while following the "
            "visible action and camera movement. The environment, lighting, "
            "shadows, and nearby objects form one coherent natural shot."
        )
    return (
        f"{count} clearly defined characters perform naturally within the "
        "original scene. Each character's face, hair, body shape, and complete "
        "outfit remain visually distinct and consistent while following the "
        "visible action and interactions. The environment, lighting, shadows, "
        "and nearby objects form one coherent natural shot."
    )


def _clean_recast_reference_region(region):
    """Keep the dominant connected subject and discard detached people."""
    import cv2
    import numpy as np

    binary = np.ascontiguousarray(
        np.asarray(region).astype(np.uint8, copy=False),
    )
    if binary.ndim != 2 or not bool(binary.any()):
        return binary.astype(bool), 0
    component_count, labels, stats, _ = cv2.connectedComponentsWithStats(
        binary,
        connectivity=8,
    )
    foreground_count = max(0, int(component_count) - 1)
    if foreground_count <= 1:
        return binary.astype(bool), foreground_count
    areas = stats[1:, cv2.CC_STAT_AREA]
    selected_label = 1 + int(np.argmax(areas))
    return labels == selected_label, foreground_count


def _select_recast_reference_instance(colored_mask, palette):
    """Select one prominent central SAM3 instance from a reference image."""
    import numpy as np

    mask = np.asarray(colored_mask)
    if mask.ndim == 2:
        cleaned, component_count = _clean_recast_reference_region(mask)
        return cleaned, {
            "instance_count": component_count,
            "selected_index": 0,
        }
    if mask.ndim != 3 or mask.shape[-1] != 3:
        raise ValueError(
            "SAM3 returned an unsupported reference mask shape: "
            f"{mask.shape}."
        )

    height, width = mask.shape[:2]
    center_x = (width - 1) / 2.0
    center_y = (height - 1) / 2.0
    max_distance = max(1.0, (center_x ** 2 + center_y ** 2) ** 0.5)
    candidates = []
    for palette_index, color in enumerate(palette):
        color_array = np.asarray(color, dtype=np.uint8)
        region = np.all(mask == color_array, axis=-1)
        if not bool(region.any()):
            continue
        cleaned, component_count = _clean_recast_reference_region(region)
        ys, xs = np.nonzero(cleaned)
        if len(xs) == 0:
            continue
        area = int(len(xs))
        distance = (
            (float(xs.mean()) - center_x) ** 2
            + (float(ys.mean()) - center_y) ** 2
        ) ** 0.5
        centrality = max(0.0, 1.0 - distance / max_distance)
        # Area remains the dominant signal. Centrality breaks close calls in
        # favor of the foreground subject users normally place near the middle.
        score = float(area) * (1.0 + 0.25 * centrality)
        candidates.append({
            "region": cleaned,
            "score": score,
            "area": area,
            "palette_index": palette_index,
            "component_count": component_count,
        })

    if not candidates:
        fallback, component_count = _clean_recast_reference_region(
            np.any(mask > 30, axis=-1),
        )
        return fallback, {
            "instance_count": component_count,
            "selected_index": 0,
        }
    selected = max(candidates, key=lambda item: item["score"])
    return selected["region"], {
        "instance_count": len(candidates),
        "selected_index": selected["palette_index"],
        "discarded_components": max(0, selected["component_count"] - 1),
    }


def _recast_reference_subject_mask(reference_frame, alpha_channel=None):
    """Find the single person represented by a standalone reference view."""
    import numpy as np
    from shared import magic_mask

    if alpha_channel is not None:
        alpha = np.asarray(alpha_channel, dtype=np.uint8)
        transparent_fraction = (
            float(np.count_nonzero(alpha < 250)) / float(alpha.size)
            if alpha.size else 0.0
        )
        if transparent_fraction >= 0.02 and int(alpha.max()) > 5:
            selected, component_count = _clean_recast_reference_region(
                alpha > 5,
            )
            opacity = alpha.astype(np.float32) / 255.0
            opacity[~selected] = 0.0
            return (
                selected,
                opacity,
                "png alpha"
                + (
                    f" (dominant of {component_count} regions)"
                    if component_count > 1 else ""
                ),
            )

    frame = np.asarray(reference_frame, dtype=np.uint8)
    instance_palette = [
        (0, 0, 255),
        (255, 0, 0),
        (0, 255, 0),
        (255, 0, 255),
        (0, 255, 255),
    ]
    for keyword in ("person", "human character", "woman", "man"):
        mask = magic_mask.generate_keyword_masks(
            frame[None],
            keyword,
            no_hole=True,
            colorize_objects=True,
            color_palette=instance_palette,
            max_colored_objects=len(instance_palette),
        )[0]
        region, selection = _select_recast_reference_instance(
            mask,
            instance_palette,
        )
        if bool(region.any()):
            instance_count = int(selection.get("instance_count") or 1)
            selected_number = int(selection.get("selected_index") or 0) + 1
            source = (
                f"{keyword} instance {selected_number}/{instance_count}"
                if instance_count > 1
                else f"{keyword} instance"
            )
            discarded = int(selection.get("discarded_components") or 0)
            if discarded:
                source += f" (removed {discarded} detached region(s))"
            return region, region.astype(np.float32), source
    raise ValueError(
        "SAM3 could not find one person in the replacement reference. "
        "Try a clearer full- or half-body image."
    )


def _decontaminate_recast_reference_edges(reference_frame, subject, width=3):
    """Replace bright boundary contamination with nearby foreground color."""
    import cv2
    import numpy as np

    frame = np.asarray(reference_frame, dtype=np.uint8)
    region = np.asarray(subject).astype(bool)
    if frame.ndim != 3 or frame.shape[-1] != 3:
        raise ValueError(
            "Recast edge cleanup needs an H/W/RGB reference image."
        )
    if region.shape != frame.shape[:2]:
        raise ValueError(
            "Recast edge cleanup mask does not match its reference image."
        )
    cleaned = frame.copy()
    current = region.copy()
    kernel = np.ones((3, 3), dtype=np.uint8)
    for _ in range(max(1, int(width))):
        inner = cv2.erode(
            current.astype(np.uint8),
            kernel,
            iterations=1,
        ).astype(bool)
        boundary = current & ~inner
        if not bool(boundary.any()) or not bool(inner.any()):
            break
        neighbor_count = cv2.filter2D(
            inner.astype(np.float32),
            cv2.CV_32F,
            kernel.astype(np.float32),
            borderType=cv2.BORDER_REPLICATE,
        )
        replace = boundary & (neighbor_count > 0.0)
        for channel in range(3):
            neighbor_sum = cv2.filter2D(
                cleaned[..., channel].astype(np.float32)
                * inner.astype(np.float32),
                cv2.CV_32F,
                kernel.astype(np.float32),
                borderType=cv2.BORDER_REPLICATE,
            )
            values = neighbor_sum / np.maximum(neighbor_count, 1.0)
            cleaned[..., channel][replace] = np.rint(
                values[replace],
            ).clip(0, 255).astype(np.uint8)
        current = inner
    return cleaned


def _constrain_recast_u2net_matte(subject, opacity, u2net_alpha):
    """Keep a soft U2Net edge inside the person instance selected by SAM3."""
    import cv2
    import numpy as np

    region = np.asarray(subject).astype(bool)
    original_opacity = np.clip(
        np.asarray(opacity, dtype=np.float32),
        0.0,
        1.0,
    )
    matte = np.asarray(u2net_alpha, dtype=np.float32)
    if matte.size and float(matte.max()) > 1.0:
        matte = matte / 255.0
    matte = np.clip(matte, 0.0, 1.0)
    if (
        region.shape != original_opacity.shape
        or region.shape != matte.shape
    ):
        raise ValueError(
            "U2Net matte dimensions do not match the selected SAM3 person."
        )
    if not bool(region.any()):
        raise ValueError("The selected SAM3 person mask is empty.")

    # SAM3 owns identity selection. U2Net is allowed only a small perimeter
    # around that instance so another person in the reference cannot leak
    # back into the conditioning image.
    edge_width = max(
        1,
        min(4, int(round(min(region.shape[:2]) * 0.004))),
    )
    kernel_size = edge_width * 2 + 1
    kernel = np.ones((kernel_size, kernel_size), dtype=np.uint8)
    guard = cv2.dilate(
        region.astype(np.uint8),
        kernel,
        iterations=1,
    ).astype(bool)
    guard_soft = cv2.GaussianBlur(
        guard.astype(np.float32),
        (0, 0),
        sigmaX=max(0.75, edge_width * 0.55),
        sigmaY=max(0.75, edge_width * 0.55),
    )
    guard_soft[~guard] = 0.0

    # Retain a feathered SAM3 silhouette even if U2Net misses a hand, hair
    # curl, or dark clothing. U2Net still supplies the cleaner outer alpha.
    inside_distance = cv2.distanceTransform(
        region.astype(np.uint8),
        cv2.DIST_L2,
        3,
    )
    sam_feather = np.clip(
        inside_distance / float(edge_width + 0.5),
        0.0,
        1.0,
    )
    sam_feather *= original_opacity
    refined = np.maximum(matte * guard_soft, sam_feather)
    refined[~guard] = 0.0
    return np.clip(refined, 0.0, 1.0).astype(np.float32)


def _get_recast_u2net_session():
    """Load the existing local background-removal model once on CPU."""
    global _recast_u2net_session

    if _recast_u2net_session is not None:
        return _recast_u2net_session
    with _recast_u2net_session_lock:
        if _recast_u2net_session is None:
            model_home = os.path.join(_app_dir, "ckpts", "rembg")
            os.makedirs(model_home, exist_ok=True)
            os.environ.setdefault("U2NET_HOME", model_home)
            import onnxruntime as _ort
            from rembg import new_session

            print(
                "[Recast] Loading U2Net edge refinement on CPU "
                "(SAM3 remains the person selector)"
            )
            # This rembg release ignores a caller-supplied providers list and
            # chooses CUDA whenever the GPU build of ONNX Runtime is present.
            # That both spends generation VRAM and emits a scary DLL error on
            # systems whose ORT CUDA version differs from PyTorch. Report CPU
            # only for the brief session-construction call; the resulting ORT
            # session then remains explicitly CPU-backed for its lifetime.
            original_get_device = _ort.get_device
            try:
                _ort.get_device = lambda: "CPU"
                _recast_u2net_session = new_session("u2net")
            finally:
                _ort.get_device = original_get_device
    return _recast_u2net_session


def _run_recast_u2net_matte(reference_frame, reference_path=None):
    """Return decontaminated foreground RGB and alpha, with a small cache."""
    import numpy as np
    from PIL import Image as _PILImage
    from rembg import remove

    frame = np.asarray(reference_frame, dtype=np.uint8)
    cache_key = None
    if reference_path:
        try:
            stat = os.stat(reference_path)
            cache_key = (
                os.path.normcase(os.path.realpath(reference_path)),
                int(stat.st_mtime_ns),
                int(stat.st_size),
            )
        except OSError:
            cache_key = None
    if cache_key is not None:
        with _recast_u2net_cache_lock:
            cached = _recast_u2net_cache.get(cache_key)
            if cached is not None:
                return cached[0].copy(), cached[1].copy()

    session = _get_recast_u2net_session()
    with _recast_u2net_run_lock:
        cutout = remove(
            _PILImage.fromarray(frame),
            session=session,
            alpha_matting=True,
            alpha_matting_erode_size=1,
            bgcolor=(0, 0, 0, 0),
        )
    if not isinstance(cutout, _PILImage.Image):
        raise ValueError("U2Net returned an unsupported Recast matte.")
    cutout_array = np.asarray(cutout.convert("RGBA"), dtype=np.uint8)
    foreground = cutout_array[..., :3].copy()
    alpha = cutout_array[..., 3].astype(np.float32) / 255.0
    if foreground.shape != frame.shape or alpha.shape != frame.shape[:2]:
        raise ValueError("U2Net returned a mismatched Recast matte size.")

    if cache_key is not None:
        with _recast_u2net_cache_lock:
            _recast_u2net_cache[cache_key] = (
                foreground.copy(),
                alpha.copy(),
            )
            while len(_recast_u2net_cache) > _RECAST_U2NET_CACHE_LIMIT:
                oldest_key = next(iter(_recast_u2net_cache))
                _recast_u2net_cache.pop(oldest_key, None)
    return foreground, alpha


def _refine_recast_reference_cutout(
    reference_frame,
    subject,
    opacity,
    mask_source,
    *,
    reference_path=None,
    matte_runner=None,
):
    """Clean one selected reference subject without changing its identity."""
    import cv2
    import numpy as np

    frame = np.asarray(reference_frame, dtype=np.uint8)
    selected = np.asarray(subject).astype(bool)
    selected_opacity = np.clip(
        np.asarray(opacity, dtype=np.float32),
        0.0,
        1.0,
    )
    # Respect a user's authored transparent cutout. It already has the most
    # precise alpha available and should not be reinterpreted by U2Net.
    if str(mask_source).lower().startswith("png alpha"):
        return selected, selected_opacity, mask_source, frame.copy()

    runner = matte_runner or _run_recast_u2net_matte
    edge_width = max(
        1,
        min(4, int(round(min(selected.shape[:2]) * 0.004))),
    )
    fallback_rgb = _decontaminate_recast_reference_edges(
        frame,
        selected,
        width=edge_width,
    )
    try:
        u2net_rgb, u2net_alpha = runner(
            frame,
            reference_path=reference_path,
        )
        u2net_rgb = np.asarray(u2net_rgb, dtype=np.uint8)
        u2net_alpha = np.asarray(u2net_alpha, dtype=np.float32)
        if u2net_rgb.shape != frame.shape:
            raise ValueError("U2Net foreground RGB size is invalid.")
        if u2net_alpha.shape != selected.shape:
            raise ValueError("U2Net alpha size is invalid.")
        normalized_alpha = (
            u2net_alpha / 255.0
            if u2net_alpha.size and float(u2net_alpha.max()) > 1.0
            else u2net_alpha
        )
        coverage = float(np.count_nonzero(
            (normalized_alpha > 0.05) & selected,
        )) / float(max(1, np.count_nonzero(selected)))
        if coverage < 0.45:
            raise ValueError(
                f"U2Net covered only {coverage:.0%} of the selected person."
            )
        refined_opacity = _constrain_recast_u2net_matte(
            selected,
            selected_opacity,
            normalized_alpha,
        )
        refined_subject = refined_opacity > 0.02
        cleaned_rgb = fallback_rgb
        valid_foreground = normalized_alpha > 0.01
        cleaned_rgb[valid_foreground] = u2net_rgb[valid_foreground]
        return (
            refined_subject,
            refined_opacity,
            f"{mask_source} + U2Net soft edge",
            cleaned_rgb,
        )
    except Exception as exc:
        # Recast must still work offline or when the optional matte runtime is
        # unavailable. The local fallback removes the most obvious fringe and
        # feathers only the boundary of the SAM-selected person.
        distance = cv2.distanceTransform(
            selected.astype(np.uint8),
            cv2.DIST_L2,
            3,
        )
        fallback_opacity = np.minimum(
            selected_opacity,
            np.clip(
                distance / float(edge_width + 0.5),
                0.0,
                1.0,
            ),
        ).astype(np.float32)
        print(
            "[Recast] U2Net edge refinement unavailable; using local "
            f"boundary cleanup ({exc})"
        )
        return (
            selected,
            fallback_opacity,
            f"{mask_source} + local edge cleanup",
            fallback_rgb,
        )


def _recast_subject_crop_box(subject, margin_fraction=0.08):
    """Return a padded subject box without discarding any identity pixels."""
    import numpy as np

    region = np.asarray(subject).astype(bool)
    ys, xs = np.nonzero(region)
    if len(xs) == 0:
        return 0, 0, region.shape[1], region.shape[0]
    x0, x1 = int(xs.min()), int(xs.max()) + 1
    y0, y1 = int(ys.min()), int(ys.max()) + 1
    margin = max(4, int(round(max(x1 - x0, y1 - y0) * margin_fraction)))
    return (
        max(0, x0 - margin),
        max(0, y0 - margin),
        min(region.shape[1], x1 + margin),
        min(region.shape[0], y1 + margin),
    )


def _recast_face_detail_crop_box(subject):
    """Frame the upper identity region while retaining hair and shoulders.

    Recast references are expected to contain one clear replacement subject.
    A second, tighter view of that same subject gives SCAIL-2 substantially
    more facial detail without sacrificing the primary image's outfit/body
    information.  The semantic subject silhouette keeps this deterministic
    and avoids introducing a separate face-model download.
    """
    import numpy as np

    region = np.asarray(subject).astype(bool)
    height, width = region.shape[:2]
    ys, xs = np.nonzero(region)
    if len(xs) == 0 or width < 2 or height < 2:
        return 0, 0, width, height

    x0, x1 = int(xs.min()), int(xs.max()) + 1
    y0, y1 = int(ys.min()), int(ys.max()) + 1
    subject_width = max(1, x1 - x0)
    subject_height = max(1, y1 - y0)

    # The upper 56% of an upright subject is a reliable head-and-shoulders
    # detail view.  A roughly 4:5 crop matches the successful manual Recast
    # close-up workflow while leaving room for hair, neck, and clothing cues.
    crop_height = max(2, int(round(subject_height * 0.56)))
    crop_width = max(
        2,
        int(round(crop_height * 0.80)),
        int(round(subject_width * 0.66)),
    )
    crop_height = max(crop_height, int(round(crop_width / 0.82)))
    crop_width = min(width, crop_width)
    crop_height = min(height, crop_height)

    upper_limit = y0 + max(1, int(round(subject_height * 0.40)))
    upper_xs = np.nonzero(region & (
        np.arange(height, dtype=np.int32)[:, None] < upper_limit
    ))[1]
    center_x = (
        float(np.median(upper_xs))
        if len(upper_xs)
        else (x0 + x1) / 2.0
    )

    left = int(round(center_x - crop_width / 2.0))
    top = int(round(y0 - subject_height * 0.02))
    left = max(0, min(left, width - crop_width))
    top = max(0, min(top, height - crop_height))
    return left, top, left + crop_width, top + crop_height


def _derive_recast_face_detail_reference(
    reference_path,
    output_path,
    *,
    refine_cutout=True,
):
    """Persist an automatic head-and-shoulders view of one reference."""
    import numpy as np
    from PIL import Image as _PILImage, ImageOps as _PILImageOps

    with _PILImage.open(reference_path) as source:
        rgba = _PILImageOps.exif_transpose(source).convert("RGBA")
        rgb = np.asarray(rgba.convert("RGB"), dtype=np.uint8)
        alpha = np.asarray(rgba.getchannel("A"), dtype=np.uint8)

    subject, opacity, mask_source = _recast_reference_subject_mask(rgb, alpha)
    foreground_rgb = rgb
    if refine_cutout:
        subject, opacity, mask_source, foreground_rgb = (
            _refine_recast_reference_cutout(
                rgb,
                subject,
                opacity,
                mask_source,
                reference_path=reference_path,
            )
        )
    crop_box = _recast_face_detail_crop_box(subject)
    if crop_box == (0, 0, rgba.width, rgba.height):
        return None
    clean_rgba = np.concatenate(
        (
            np.asarray(foreground_rgb, dtype=np.uint8),
            np.rint(np.clip(opacity, 0.0, 1.0) * 255.0)
            .astype(np.uint8)[..., None],
        ),
        axis=-1,
    )
    detail = _PILImage.fromarray(clean_rgba).crop(crop_box)
    if detail.width < 2 or detail.height < 2:
        return None
    detail.save(output_path, format="PNG")
    left, top, right, bottom = crop_box
    metadata = {
        "path": output_path,
        "crop_box": list(crop_box),
        "source_size": [rgba.width, rgba.height],
        "detail_size": [detail.width, detail.height],
        "detail_source": f"upper-subject crop from {mask_source}",
    }
    return {
        "metadata": metadata,
        # Reuse this one segmentation pass for both generated SCAIL views.
        # Without these cached layers, the primary plus derived crop would
        # make SAM3 analyze the same identity three times.
        "source_conditioning": (
            subject,
            opacity,
            mask_source,
            foreground_rgb,
        ),
        "detail_conditioning": (
            subject[top:bottom, left:right],
            opacity[top:bottom, left:right],
            mask_source,
            foreground_rgb[top:bottom, left:right],
        ),
    }


def _recast_region_bbox_aspect(region):
    """Return width/height for the visible bounding box of a mask."""
    import numpy as np

    ys, xs = np.nonzero(np.asarray(region).astype(bool))
    if len(xs) == 0:
        return None
    width = max(1, int(xs.max()) - int(xs.min()) + 1)
    height = max(1, int(ys.max()) - int(ys.min()) + 1)
    return float(width) / float(height)


def _recast_face_detail_upscale_factor(detail_size, canvas_size):
    """Return the enlargement needed to contain a detail view on its canvas."""
    try:
        detail_width, detail_height = (
            float(detail_size[0]),
            float(detail_size[1]),
        )
        canvas_width, canvas_height = (
            float(canvas_size[0]),
            float(canvas_size[1]),
        )
    except (IndexError, TypeError, ValueError):
        return None
    if min(
        detail_width,
        detail_height,
        canvas_width,
        canvas_height,
    ) <= 0:
        return None
    return min(
        canvas_width / detail_width,
        canvas_height / detail_height,
    )


def _recast_should_add_auto_face_detail(
    mapping,
    enabled=True,
    *,
    source_probe_mask=None,
    semantic_color=None,
    reference_subject=None,
    detail_size=None,
    canvas_size=None,
    max_upscale=1.75,
):
    """Use auto detail only when it will not compete with an explicit view."""
    eligible = bool(
        enabled
        and not mapping.get("reference_aligned_to_source")
        and not mapping.get("additional_ref_image_paths")
    )
    if not eligible:
        return False

    upscale_factor = _recast_face_detail_upscale_factor(
        detail_size,
        canvas_size,
    )
    if (
        upscale_factor is not None
        and upscale_factor > float(max_upscale)
    ):
        return False

    if (
        source_probe_mask is None
        or semantic_color is None
        or reference_subject is None
    ):
        return eligible

    import numpy as np

    source_mask = np.asarray(source_probe_mask)
    if source_mask.ndim == 3 and source_mask.shape[-1] == 3:
        target_region = np.all(
            source_mask == np.asarray(semantic_color, dtype=np.uint8),
            axis=-1,
        )
    else:
        target_region = source_mask.astype(bool)
    target_aspect = _recast_region_bbox_aspect(target_region)
    reference_aspect = _recast_region_bbox_aspect(reference_subject)
    if target_aspect is None or reference_aspect is None:
        return eligible

    # A tall/narrow driving silhouette normally means a full-body shot. If
    # the supplied identity is a substantially wider upper-body portrait,
    # another enlarged face crop becomes a second competing spatial subject.
    # Keep the primary identity view but omit that redundant extra region.
    if (
        target_aspect < 0.65
        and reference_aspect > target_aspect * 1.45
    ):
        return False
    return eligible


def _fit_recast_reference_layers(
    rgb, semantic_rgb, width, height, *, aligned=False,
    crop_to_subject=True, canvas_color=(127, 127, 127),
):
    """Apply the exact shared image/mask transform used by Recast."""
    import numpy as np
    from PIL import Image as _PILImage

    rgb_image = _PILImage.fromarray(np.asarray(rgb, dtype=np.uint8))
    mask_image = _PILImage.fromarray(np.asarray(semantic_rgb, dtype=np.uint8))
    if aligned:
        scale = max(width / rgb_image.width, height / rgb_image.height)
        resized_size = (
            max(width, int(round(rgb_image.width * scale))),
            max(height, int(round(rgb_image.height * scale))),
        )
        rgb_image = rgb_image.resize(
            resized_size, resample=_PILImage.Resampling.LANCZOS,
        )
        mask_image = mask_image.resize(
            resized_size, resample=_PILImage.Resampling.NEAREST,
        )
        left = (resized_size[0] - width) // 2
        top = (resized_size[1] - height) // 2
        box = (left, top, left + width, top + height)
        return rgb_image.crop(box), mask_image.crop(box)

    subject = np.any(np.asarray(semantic_rgb, dtype=np.uint8) > 30, axis=-1)
    crop_box = (
        _recast_subject_crop_box(subject)
        if crop_to_subject
        else (0, 0, rgb_image.width, rgb_image.height)
    )
    rgb_image = rgb_image.crop(crop_box)
    mask_image = mask_image.crop(crop_box)
    scale = min(width / rgb_image.width, height / rgb_image.height)
    resized_size = (
        max(1, min(width, int(round(rgb_image.width * scale)))),
        max(1, min(height, int(round(rgb_image.height * scale)))),
    )
    rgb_image = rgb_image.resize(
        resized_size, resample=_PILImage.Resampling.LANCZOS,
    )
    mask_image = mask_image.resize(
        resized_size, resample=_PILImage.Resampling.NEAREST,
    )
    rgb_canvas = _PILImage.new(
        "RGB",
        (width, height),
        tuple(int(value) for value in canvas_color),
    )
    mask_canvas = _PILImage.new("RGB", (width, height), (0, 0, 0))
    offset = ((width - resized_size[0]) // 2, (height - resized_size[1]) // 2)
    rgb_canvas.paste(rgb_image, offset)
    mask_canvas.paste(mask_image, offset)
    return rgb_canvas, mask_canvas


def _prepare_recast_reference_frame(
    reference_path, color, *, isolate_reference=True,
    aligned_semantic_mask=None, subject_conditioning=None,
    spatial_background=None, width=832, height=480,
):
    """Build separate CLIP-identity and spatial RGB inputs for SCAIL-2."""
    import numpy as np
    from PIL import Image as _PILImage, ImageOps as _PILImageOps

    with _PILImage.open(reference_path) as source:
        rgba = _PILImageOps.exif_transpose(source).convert("RGBA")
        rgb = np.asarray(rgba.convert("RGB"), dtype=np.uint8)
        alpha = np.asarray(rgba.getchannel("A"), dtype=np.uint8)

    aligned = aligned_semantic_mask is not None
    foreground_rgb = rgb
    if aligned:
        semantic_rgb = np.asarray(aligned_semantic_mask, dtype=np.uint8)
        if semantic_rgb.shape[:2] != rgb.shape[:2]:
            semantic_rgb = np.asarray(
                _PILImage.fromarray(semantic_rgb, mode="RGB").resize(
                    (rgb.shape[1], rgb.shape[0]),
                    resample=_PILImage.Resampling.NEAREST,
                ),
                dtype=np.uint8,
            )
        subject = np.any(semantic_rgb > 30, axis=-1)
        opacity = subject.astype(np.float32)
        mask_source = "aligned source overlap"
    else:
        if subject_conditioning is None:
            subject, opacity, mask_source = _recast_reference_subject_mask(
                rgb, alpha,
            )
            if isolate_reference:
                subject, opacity, mask_source, foreground_rgb = (
                    _refine_recast_reference_cutout(
                        rgb,
                        subject,
                        opacity,
                        mask_source,
                        reference_path=reference_path,
                    )
                )
        else:
            if len(subject_conditioning) == 4:
                (
                    subject,
                    opacity,
                    mask_source,
                    foreground_rgb,
                ) = subject_conditioning
            elif len(subject_conditioning) == 3:
                subject, opacity, mask_source = subject_conditioning
            else:
                raise ValueError(
                    "Cached Recast reference conditioning is invalid."
                )
            subject = np.asarray(subject).astype(bool)
            opacity = np.asarray(opacity, dtype=np.float32)
            foreground_rgb = np.asarray(foreground_rgb, dtype=np.uint8)
            if (
                subject.shape != rgb.shape[:2]
                or opacity.shape != rgb.shape[:2]
                or foreground_rgb.shape != rgb.shape
            ):
                raise ValueError(
                    "Cached Recast reference mask does not match its image."
                )
        semantic_rgb = np.zeros_like(rgb, dtype=np.uint8)
        semantic_rgb[subject] = np.asarray(color, dtype=np.uint8)

    if isolate_reference:
        foreground_image, prepared_mask = _fit_recast_reference_layers(
            foreground_rgb,
            semantic_rgb,
            int(width),
            int(height),
            aligned=aligned,
            crop_to_subject=True,
        )
        opacity_rgb = np.repeat(
            np.rint(np.clip(opacity, 0.0, 1.0) * 255.0)
            .astype(np.uint8)[..., None],
            3,
            axis=-1,
        )
        opacity_image, _ = _fit_recast_reference_layers(
            opacity_rgb,
            semantic_rgb,
            int(width),
            int(height),
            aligned=aligned,
            crop_to_subject=True,
            canvas_color=(0, 0, 0),
        )
        if spatial_background is None:
            background = np.full(
                (int(height), int(width), 3),
                127,
                dtype=np.uint8,
            )
        else:
            background = np.asarray(spatial_background, dtype=np.uint8)
            if background.ndim != 3 or background.shape[-1] != 3:
                raise ValueError(
                    "Recast spatial background must be an H/W/RGB image; "
                    f"got {background.shape}."
                )
            if background.shape[:2] != (int(height), int(width)):
                background = np.asarray(
                    _PILImage.fromarray(background).resize(
                        (int(width), int(height)),
                        resample=_PILImage.Resampling.LANCZOS,
                    ),
                    dtype=np.uint8,
                )
        foreground_array = np.asarray(
            foreground_image.convert("RGB"),
            dtype=np.uint8,
        )
        prepared_opacity = (
            np.asarray(
                opacity_image.convert("RGB"),
                dtype=np.float32,
            )[..., :1]
            / 255.0
        )
        semantic_region = np.any(
            np.asarray(
                prepared_mask.convert("RGB"),
                dtype=np.uint8,
            ) > 30,
            axis=-1,
        )
        prepared_opacity[~semantic_region] = 0.0
        prepared_array = np.rint(
            foreground_array.astype(np.float32) * prepared_opacity
            + background.astype(np.float32) * (1.0 - prepared_opacity)
        ).clip(0, 255).astype(np.uint8)
        prepared_image = _PILImage.fromarray(prepared_array)
    else:
        prepared_image, prepared_mask = _fit_recast_reference_layers(
            rgb,
            semantic_rgb,
            int(width),
            int(height),
            aligned=aligned,
            crop_to_subject=False,
        )
    if isolate_reference:
        # Keep the original, uncropped reference composition for CLIP identity.
        # Only the VAE/spatial reference gets the source-scene background and
        # tighter subject framing. This preserves the strong face signal
        # observed with isolation disabled without allowing the reference
        # room/background to leak through SCAIL-2's spatial latent.
        identity_image, _ = _fit_recast_reference_layers(
            rgb,
            semantic_rgb,
            int(width),
            int(height),
            aligned=aligned,
            crop_to_subject=False,
        )
    else:
        identity_image = prepared_image.copy()
    return {
        "image": prepared_image,
        "identity_image": identity_image,
        "mask": prepared_mask,
        "mask_source": mask_source,
        "source_size": (int(rgb.shape[1]), int(rgb.shape[0])),
        "prepared_size": (int(width), int(height)),
    }


def _recast_image_data_uri(image, image_format="PNG"):
    import base64
    import io

    buffer = io.BytesIO()
    image.save(buffer, format=image_format)
    mime = "image/png" if image_format.upper() == "PNG" else "image/jpeg"
    return f"data:{mime};base64," + base64.b64encode(buffer.getvalue()).decode()


def _compose_recast_timeline_preview(
    source_frames, mapping_masks, mapping_results, max_tile_width=420,
):
    """Build one compact card per mapping at its best sampled anchor."""
    import numpy as np
    from PIL import Image as _PILImage, ImageDraw as _PILImageDraw

    frames = np.asarray(source_frames, dtype=np.uint8)
    if frames.ndim != 4 or frames.shape[-1] != 3:
        raise ValueError("Recast timeline preview needs T/H/W/RGB frames.")
    tiles = []
    for result, raw_mask in zip(mapping_results, mapping_masks):
        if not result.get("found"):
            continue
        sample_index = int(result["anchor_sample_index"])
        frame = frames[sample_index].copy()
        mask = np.asarray(raw_mask, dtype=np.uint8)[sample_index]
        selected = np.any(mask > 30, axis=-1)
        if bool(selected.any()):
            frame[selected] = (
                frame[selected].astype(np.float32) * 0.45
                + mask[selected].astype(np.float32) * 0.55
            ).astype(np.uint8)
        image = _PILImage.fromarray(frame)
        if image.width > int(max_tile_width):
            tile_height = max(
                1,
                int(round(image.height * int(max_tile_width) / image.width)),
            )
            image = image.resize(
                (int(max_tile_width), tile_height),
                resample=_PILImage.Resampling.LANCZOS,
            )
        header_height = 24
        tile = _PILImage.new(
            "RGB",
            (image.width, image.height + header_height),
            (22, 24, 29),
        )
        tile.paste(image, (0, header_height))
        draw = _PILImageDraw.Draw(tile)
        color = tuple(int(value) for value in result["color"])
        draw.rectangle((6, 6, 16, 16), fill=color, outline=(235, 235, 235))
        label = (
            f"Character {chr(65 + int(result['mapping_index']))} - "
            f"{float(result['anchor_time_seconds']):.1f}s"
        )
        draw.text((22, 5), label, fill=(235, 238, 244))
        tiles.append(tile)
    if not tiles:
        return _PILImage.fromarray(frames[0])
    columns = min(2, len(tiles))
    rows = (len(tiles) + columns - 1) // columns
    cell_width = max(tile.width for tile in tiles)
    cell_height = max(tile.height for tile in tiles)
    sheet = _PILImage.new(
        "RGB",
        (columns * cell_width, rows * cell_height),
        (14, 16, 20),
    )
    for index, tile in enumerate(tiles):
        x = (index % columns) * cell_width
        y = (index // columns) * cell_height
        sheet.paste(tile, (x, y))
    return sheet


def _recast_reference_preview_payload(
    prepared, mapping_index, view_index, kind, view_metadata=None,
):
    image = prepared["image"].convert("RGB")
    identity_image = prepared["identity_image"].convert("RGB")
    mask = prepared["mask"].convert("RGB")
    payload = {
        "mapping_index": mapping_index,
        "view_index": view_index,
        "kind": kind,
        "mask_source": prepared["mask_source"],
        "source_size": list(prepared["source_size"]),
        "prepared_size": list(prepared["prepared_size"]),
        "prepared_image": _recast_image_data_uri(image),
        "semantic_mask": _recast_image_data_uri(mask),
    }
    if view_metadata:
        payload.update({
            key: value
            for key, value in view_metadata.items()
            if key in {
                "crop_box", "detail_size", "detail_source",
                "detail_upscale_factor",
            }
        })
    if mapping_index == 0 and view_index == 0:
        payload["clip_identity_image"] = _recast_image_data_uri(identity_image)
    return payload


def _prepare_recast_reference_conditioning(
    mappings, source_probe_mask, output_dir, job_id, *,
    isolate_reference, selected_count, auto_face_detail=True,
    source_frame=None, reference_canvas=None, mapping_anchors=None,
):
    """Prepare reference pairs using each character's own timeline anchor."""
    import numpy as np
    from PIL import Image as _PILImage, ImageOps as _PILImageOps
    from shared import magic_mask

    os.makedirs(output_dir, exist_ok=True)
    image_paths = []
    mask_paths = []
    clip_identity_path = None
    expected_colors = []
    previews = []
    auto_face_detail_refs = []
    primary_target_refs = []
    canvas_width, canvas_height = 832, 480
    anchor_list = (
        mapping_anchors
        if isinstance(mapping_anchors, list)
        else []
    )
    first_anchor_frame = None
    if anchor_list and isinstance(anchor_list[0], dict):
        first_anchor_frame = anchor_list[0].get("source_frame")
    if reference_canvas is not None:
        try:
            canvas_width, canvas_height = (
                int(reference_canvas[0]),
                int(reference_canvas[1]),
            )
        except (IndexError, TypeError, ValueError) as exc:
            raise ValueError(
                "Recast reference canvas must contain width and height."
            ) from exc
        if (
            min(canvas_width, canvas_height) <= 0
            or canvas_width % 32
            or canvas_height % 32
        ):
            raise ValueError(
                "Recast reference canvas dimensions must be positive and "
                "divisible by 32."
            )
    elif source_frame is not None:
        canvas_width, canvas_height = _recast_reference_canvas_size(
            source_frame,
        )
    elif first_anchor_frame is not None:
        canvas_width, canvas_height = _recast_reference_canvas_size(
            first_anchor_frame,
        )
    for mapping_index, mapping in enumerate(mappings):
        color = _RECAST_MASK_COLORS[mapping_index]
        mapping_source_frame = source_frame
        mapping_source_mask = source_probe_mask
        if (
            mapping_index < len(anchor_list)
            and isinstance(anchor_list[mapping_index], dict)
        ):
            mapping_source_frame = anchor_list[mapping_index].get(
                "source_frame",
                mapping_source_frame,
            )
            mapping_source_mask = anchor_list[mapping_index].get(
                "source_mask",
                mapping_source_mask,
            )
        spatial_background = None
        if mapping_source_frame is not None:
            scene_layers = _build_recast_source_scene_layers(
                mapping_source_frame,
                mapping_source_mask,
                selected_count,
                output_size=(canvas_width, canvas_height),
            )
            spatial_background = scene_layers["image"]
        views = [{
            "kind": "primary",
            "path": mapping["ref_image_path"],
        }]
        if _recast_should_add_auto_face_detail(mapping, auto_face_detail):
            detail_path = os.path.join(
                output_dir,
                f"recast_auto_face_detail_{job_id}_{mapping_index + 1}.png",
            )
            detail_result = _derive_recast_face_detail_reference(
                mapping["ref_image_path"],
                detail_path,
                refine_cutout=isolate_reference,
            )
            if detail_result:
                views[0]["subject_conditioning"] = detail_result[
                    "source_conditioning"
                ]
                detail_upscale_factor = _recast_face_detail_upscale_factor(
                    detail_result["metadata"]["detail_size"],
                    (canvas_width, canvas_height),
                )
                detail_result["metadata"]["detail_upscale_factor"] = (
                    round(detail_upscale_factor, 3)
                    if detail_upscale_factor is not None
                    else None
                )
                if _recast_should_add_auto_face_detail(
                    mapping,
                    auto_face_detail,
                    source_probe_mask=mapping_source_mask,
                    semantic_color=color,
                    reference_subject=detail_result[
                        "source_conditioning"
                    ][0],
                    detail_size=detail_result["metadata"]["detail_size"],
                    canvas_size=(canvas_width, canvas_height),
                ):
                    views.append({
                        "kind": "auto_face_detail",
                        "path": detail_path,
                        "metadata": detail_result["metadata"],
                        "subject_conditioning": detail_result[
                            "detail_conditioning"
                        ],
                    })
                    auto_face_detail_refs.append({
                        "mapping_index": mapping_index,
                        **detail_result["metadata"],
                    })
                else:
                    try:
                        os.remove(detail_path)
                    except OSError:
                        pass
                    if (
                        detail_upscale_factor is not None
                        and detail_upscale_factor > 1.75
                    ):
                        reason = (
                            "the crop would require "
                            f"{detail_upscale_factor:.2f}x enlargement"
                        )
                    else:
                        reason = (
                            "the source target is full-body while the identity "
                            "reference is already a tighter upper-body view"
                        )
                    print(
                        "[Recast] Skipped automatic face-detail spatial view "
                        f"for mapping {mapping_index + 1}: {reason}."
                    )
        views.extend({
            "kind": "additional",
            "path": path,
        } for path in mapping.get("additional_ref_image_paths", []))
        for view_index, view in enumerate(views):
            kind = view["kind"]
            reference_path = view["path"]
            aligned_mask = None
            if view_index == 0 and mapping.get("reference_aligned_to_source"):
                with _PILImage.open(reference_path) as reference_image:
                    reference_frame = np.asarray(
                        _PILImageOps.exif_transpose(reference_image).convert("RGB"),
                        dtype=np.uint8,
                    )
                reference_people = magic_mask.generate_keyword_masks(
                    reference_frame[None],
                    "person",
                    no_hole=True,
                    colorize_objects=True,
                    color_palette=_RECAST_MASK_COLORS,
                    max_colored_objects=len(_RECAST_MASK_COLORS),
                )[0]
                aligned_colors = (
                    _RECAST_MASK_COLORS[:selected_count]
                    if len(mappings) == 1 and selected_count > 1
                    else [color]
                )
                aligned_mask, matched = _align_recast_reference_mask(
                    mapping_source_mask,
                    reference_people,
                    aligned_colors,
                    _RECAST_MASK_COLORS,
                )
                if matched < len(aligned_colors):
                    raise ValueError(
                        "The edited first-frame reference could not be aligned "
                        f"to every selected source person ({matched}/"
                        f"{len(aligned_colors)})."
                    )
            prepared = _prepare_recast_reference_frame(
                reference_path,
                color,
                isolate_reference=isolate_reference,
                aligned_semantic_mask=aligned_mask,
                subject_conditioning=view.get("subject_conditioning"),
                spatial_background=spatial_background,
                width=canvas_width,
                height=canvas_height,
            )
            suffix = f"{mapping_index + 1}_{view_index + 1}"
            prepared_path = os.path.join(
                output_dir, f"recast_prepared_ref_{job_id}_{suffix}.png",
            )
            mask_path = os.path.join(
                output_dir, f"recast_prepared_mask_{job_id}_{suffix}.png",
            )
            prepared["image"].save(prepared_path)
            prepared["mask"].save(mask_path)
            if clip_identity_path is None:
                if isolate_reference:
                    clip_identity_path = os.path.join(
                        output_dir,
                        f"recast_clip_identity_ref_{job_id}_{suffix}.png",
                    )
                    prepared["identity_image"].save(clip_identity_path)
                else:
                    clip_identity_path = prepared_path
            image_paths.append(prepared_path)
            mask_paths.append(mask_path)
            expected_colors.append(list(color))
            if view_index == 0:
                primary_target_refs.append({
                    "mapping_index": mapping_index,
                    "image": prepared_path,
                    "mask": mask_path,
                    "color": list(color),
                })
            previews.append(
                _recast_reference_preview_payload(
                    prepared,
                    mapping_index,
                    view_index,
                    kind,
                    view.get("metadata"),
                )
            )
    if not image_paths:
        raise ValueError("Recast needs at least one prepared reference.")
    return {
        "image_refs": image_paths,
        "clip_identity_ref": clip_identity_path,
        "primary_mask": mask_paths[0],
        "additional_masks": mask_paths[1:],
        "expected_colors": expected_colors,
        "previews": previews,
        "auto_face_detail_refs": auto_face_detail_refs,
        "primary_target_refs": primary_target_refs,
        "reference_canvas": [canvas_width, canvas_height],
    }


def _resize_recast_shot_frames(frames, canvas_size, *, semantic=False):
    """Resize T/H/W/RGB frames to the exact generation canvas."""
    import numpy as np
    from PIL import Image as _PILImage

    array = np.asarray(frames, dtype=np.uint8)
    if array.ndim != 4 or array.shape[-1] != 3:
        raise ValueError(
            f"Recast shot frames must be T/H/W/RGB; got {array.shape}."
        )
    width, height = int(canvas_size[0]), int(canvas_size[1])
    if min(width, height) <= 0:
        raise ValueError("Recast shot canvas dimensions must be positive.")
    if array.shape[1:3] == (height, width):
        return array.copy()
    resample = (
        _PILImage.Resampling.NEAREST
        if semantic
        else _PILImage.Resampling.LANCZOS
    )
    return np.stack([
        np.asarray(
            _PILImage.fromarray(frame).resize(
                (width, height),
                resample=resample,
            ),
            dtype=np.uint8,
        )
        for frame in array
    ])


def _write_recast_shot_video(path, frames, fps, *, semantic=False):
    """Persist one silent internal guide or semantic-mask clip."""
    import imageio.v2 as imageio
    import numpy as np

    array = np.asarray(frames, dtype=np.uint8)
    if array.ndim != 4 or array.shape[-1] != 3 or len(array) == 0:
        raise ValueError("Cannot write an empty or malformed Recast shot.")
    os.makedirs(os.path.dirname(os.path.abspath(path)), exist_ok=True)
    if semantic:
        from shared import magic_mask

        codec_params = magic_mask._magic_mask_video_codec_params()
    else:
        codec_params = {
            "codec": "libx264",
            "quality": 9,
            "pixelformat": "yuv420p",
            "macro_block_size": 1,
        }
    writer = imageio.get_writer(
        path,
        fps=float(fps),
        ffmpeg_log_level="error",
        **codec_params,
    )
    try:
        for frame in array:
            writer.append_data(frame)
    finally:
        writer.close()
    return path


def _recolor_recast_reference_mask(
    semantic_mask, global_mapping_index, local_mapping_index,
):
    """Recolor one prepared identity mask for a shot-local character slot."""
    import numpy as np

    mask = np.asarray(semantic_mask, dtype=np.uint8)
    global_color = np.asarray(
        _RECAST_MASK_COLORS[int(global_mapping_index)],
        dtype=np.uint8,
    )
    local_color = np.asarray(
        _RECAST_MASK_COLORS[int(local_mapping_index)],
        dtype=np.uint8,
    )
    region = np.all(mask == global_color, axis=-1)
    if not bool(region.any()):
        region = np.any(mask > 30, axis=-1)
    output = np.zeros_like(mask, dtype=np.uint8)
    output[region] = local_color
    return output


def _load_recast_reference_pair(
    image_path, mask_path, global_mapping_index, local_mapping_index,
):
    """Load a prepared image/mask pair and assign its shot-local color."""
    import numpy as np
    from PIL import Image as _PILImage

    with _PILImage.open(image_path) as image:
        rgb = np.asarray(image.convert("RGB"), dtype=np.uint8)
    with _PILImage.open(mask_path) as mask:
        semantic = np.asarray(mask.convert("RGB"), dtype=np.uint8)
    if semantic.shape != rgb.shape:
        raise ValueError(
            "Prepared Recast reference image and mask dimensions differ."
        )
    return (
        rgb,
        _recolor_recast_reference_mask(
            semantic,
            global_mapping_index,
            local_mapping_index,
        ),
    )


def _save_recast_reference_pair(
    output_dir, stem, image, semantic_mask,
):
    """Save an internal SCAIL reference pair and return both paths."""
    from PIL import Image as _PILImage

    os.makedirs(output_dir, exist_ok=True)
    image_path = os.path.join(output_dir, f"{stem}.png")
    mask_path = os.path.join(output_dir, f"{stem}_mask.png")
    _PILImage.fromarray(image).save(image_path)
    _PILImage.fromarray(semantic_mask).save(mask_path)
    return image_path, mask_path


def _build_recast_shot_reference_conditioning(
    prepared_refs, active_mapping_indices, source_frame,
    local_semantic_mask, output_dir, job_id, shot_index, *,
    cooccurring, reference_canvas,
):
    """Build balanced, composition-aware references for one camera shot."""
    import numpy as np

    active = [int(index) for index in active_mapping_indices]
    if not active:
        raise ValueError("A generated Recast shot needs an active character.")
    active_count = len(active)
    all_images = list(prepared_refs.get("image_refs") or [])
    all_masks = [
        prepared_refs.get("primary_mask"),
        *list(prepared_refs.get("additional_masks") or []),
    ]
    all_colors = list(prepared_refs.get("expected_colors") or [])
    if (
        len(all_images) != len(all_masks)
        or len(all_images) != len(all_colors)
    ):
        raise ValueError("Prepared Recast reference pairs are out of sync.")

    views_by_mapping = {mapping_index: [] for mapping_index in active}
    for image_path, mask_path, raw_color in zip(
        all_images, all_masks, all_colors,
    ):
        if not image_path or not mask_path or raw_color is None:
            continue
        try:
            color = tuple(int(channel) for channel in raw_color)
        except (TypeError, ValueError):
            continue
        for mapping_index in active:
            if color == tuple(_RECAST_MASK_COLORS[mapping_index]):
                views_by_mapping[mapping_index].append(
                    (image_path, mask_path),
                )
                break

    primary_items = {
        int(item["mapping_index"]): item
        for item in prepared_refs.get("primary_target_refs") or []
        if isinstance(item, dict) and "mapping_index" in item
    }
    primary_layers = []
    for local_index, mapping_index in enumerate(active):
        item = primary_items.get(mapping_index)
        if not item:
            raise ValueError(
                f"Missing primary reference for Recast mapping "
                f"{mapping_index + 1}."
            )
        primary_layers.append(
            _load_recast_reference_pair(
                item["image"],
                item["mask"],
                mapping_index,
                local_index,
            )
        )

    primary_mode = "shot_layout"
    try:
        if active_count > 1 and not cooccurring:
            raise ValueError(
                "active characters never share one frame in this shot"
            )
        primary_image, primary_mask = (
            _compose_recast_group_reference_frame(
                source_frame,
                local_semantic_mask,
                primary_layers,
                active_count,
            )
        )
    except ValueError as composition_error:
        print(
            f"[Recast] Shot {shot_index + 1} has no usable shared layout; "
            f"using a balanced cast sheet: {composition_error}"
        )
        primary_image, primary_mask = (
            _compose_recast_cast_reference_frame(
                primary_layers,
                active_count,
                reference_canvas,
            )
        )
        primary_mode = "cast_sheet"

    stem = f"recast_shot_ref_{job_id}_{shot_index + 1}"
    primary_path, primary_mask_path = _save_recast_reference_pair(
        output_dir,
        stem,
        primary_image,
        primary_mask,
    )
    image_refs = [primary_path]
    mask_paths = [primary_mask_path]
    expected_colors = [
        list(_RECAST_MASK_COLORS[0])
        if active_count == 1
        else None
    ]

    if active_count == 1:
        mapping_index = active[0]
        for view_index, (image_path, mask_path) in enumerate(
            views_by_mapping.get(mapping_index) or [],
            1,
        ):
            _rgb, recolored_mask = _load_recast_reference_pair(
                image_path,
                mask_path,
                mapping_index,
                0,
            )
            recolored_mask_path = os.path.join(
                output_dir,
                f"{stem}_identity_{view_index}_mask.png",
            )
            from PIL import Image as _PILImage

            _PILImage.fromarray(recolored_mask).save(recolored_mask_path)
            image_refs.append(image_path)
            mask_paths.append(recolored_mask_path)
            expected_colors.append(list(_RECAST_MASK_COLORS[0]))
    else:
        # A spatial group primary already contains every active identity in
        # the tracked left/right slots. Extra side-by-side cast/detail sheets
        # can disagree with those positions when the source actors cross or
        # appear in reverse card order. SCAIL-2 then follows the sheet layout
        # instead of its semantic colors, swapping and enlarging characters.
        # Keep the native group pair singular; the dedicated source-scene
        # reference below remains the only supporting reference.
        omitted_views = sum(
            len(views_by_mapping.get(mapping_index) or [])
            for mapping_index in active
        )
        reference_kind = (
            "spatial"
            if primary_mode == "shot_layout"
            else "balanced"
        )
        print(
            f"[Recast] Shot {shot_index + 1} uses one {reference_kind} "
            f"{active_count}-character reference; omitted "
            f"{omitted_views} separate identity view(s) that could override "
            "tracked color correspondence."
        )

    scene_reference = _build_recast_source_scene_reference(
        source_frame,
        local_semantic_mask,
        active_count,
        output_dir,
        f"{job_id}_shot_{shot_index + 1}",
        output_size=tuple(reference_canvas),
    )
    return {
        "image_refs": image_refs,
        "primary_mask": mask_paths[0],
        "additional_masks": mask_paths[1:],
        "expected_colors": expected_colors,
        "clip_identity_ref": (
            (views_by_mapping.get(active[0]) or [(primary_path, None)])[0][0]
            if active_count == 1
            else primary_path
        ),
        "source_scene_reference": scene_reference,
        "primary_mode": primary_mode,
    }


def _build_recast_shot_manifest(
    base_params, mapped_tracking, prepared_refs, output_dir, job_id, *,
    reference_canvas, target_frame_count, generation_fps,
    minimum_frames, latent_size,
):
    """Create internal, exact-length generation tasks per detected shot."""
    import copy
    import numpy as np

    source_frames, mapping_masks, shot_ranges = (
        _resample_recast_tracking_timeline(
            mapped_tracking["source_frames"],
            mapped_tracking["mapping_masks"],
            mapped_tracking["shot_ranges"],
            target_frame_count,
        )
    )
    cast_transition_hold_frames = max(
        4,
        min(12, int(round(max(1.0, float(generation_fps)) * 0.2))),
    )
    transition_plans = _plan_recast_shot_segments(
        mapping_masks,
        shot_ranges,
        split_cast_transitions=True,
        min_cast_run_frames=cast_transition_hold_frames,
    )
    plans = _plan_recast_shot_segments(
        mapping_masks,
        shot_ranges,
        # Keep every camera shot continuous. Splitting at a cast entrance
        # created tiny independent clips that could leave the source actor
        # untouched and made SCAIL-2 relearn color/identity correspondence at
        # the join. A hidden identity-aware pre-roll below gives late entrants
        # an initialization frame without publishing a new boundary.
        split_cast_transitions=False,
        min_cast_run_frames=cast_transition_hold_frames,
    )
    cast_transition_count = max(
        0,
        len(transition_plans) - len(shot_ranges),
    )

    global_semantic = np.empty(
        (*source_frames.shape[:-1], 3),
        dtype=np.uint8,
    )
    global_semantic[...] = (255, 255, 255)
    occupied = np.zeros(source_frames.shape[:-1], dtype=bool)
    for mapping_index, mapping_mask in enumerate(mapping_masks):
        region = (
            np.any(mapping_mask > 30, axis=-1)
            if mapping_mask.ndim == 4
            else mapping_mask.astype(bool)
        )
        writable = region & ~occupied
        global_semantic[writable] = np.asarray(
            _RECAST_MASK_COLORS[mapping_index],
            dtype=np.uint8,
        )
        occupied |= region

    os.makedirs(output_dir, exist_ok=True)
    tasks = []
    published_plans = []
    for plan in plans:
        shot_index = int(plan["shot_index"])
        start, end = int(plan["start_frame"]), int(plan["end_frame"])
        active = list(plan["active_mapping_indices"])
        shot_frames = source_frames[start:end]
        resized_source = _resize_recast_shot_frames(
            shot_frames,
            reference_canvas,
        )
        published = dict(plan)
        published["active_mapping_indices"] = list(active)

        if not active:
            passthrough_path = os.path.join(
                output_dir,
                f"recast_{job_id}_shot_{shot_index + 1}_source.mp4",
            )
            _write_recast_shot_video(
                passthrough_path,
                resized_source,
                generation_fps,
            )
            plan["passthrough_path"] = passthrough_path
            published["generation_mode"] = "source_passthrough"
            published_plans.append(published)
            continue

        local_mask = _remap_recast_shot_mask(
            global_semantic[start:end],
            active,
        )
        resized_mask = _resize_recast_shot_frames(
            local_mask,
            reference_canvas,
            semantic=True,
        )
        anchor_index = int(plan["anchor_frame_index"])
        anchor_mask = _remap_recast_shot_mask(
            global_semantic[anchor_index],
            active,
            background_color=(0, 0, 0),
        )
        shot_refs = _build_recast_shot_reference_conditioning(
            prepared_refs,
            active,
            source_frames[anchor_index],
            anchor_mask,
            output_dir,
            job_id,
            shot_index,
            cooccurring=bool(plan["cooccurring"]),
            reference_canvas=reference_canvas,
        )

        generated_frames, trim_tail = (
            _quantize_recast_shot_frame_count(
                end - start,
                minimum_frames,
                latent_size,
            )
        )
        pad_count = generated_frames - (end - start)
        if pad_count > 0:
            resized_source = np.concatenate([
                resized_source,
                np.repeat(resized_source[-1:], pad_count, axis=0),
            ])
            resized_mask = np.concatenate([
                resized_mask,
                np.repeat(resized_mask[-1:], pad_count, axis=0),
            ])

        guide_path = os.path.join(
            output_dir,
            f"recast_{job_id}_shot_{shot_index + 1}_guide.mp4",
        )
        mask_path = os.path.join(
            output_dir,
            f"recast_{job_id}_shot_{shot_index + 1}_mask.mp4",
        )
        _write_recast_shot_video(
            guide_path,
            resized_source,
            generation_fps,
        )
        _write_recast_shot_video(
            mask_path,
            resized_mask,
            generation_fps,
            semantic=True,
        )

        custom_settings = copy.deepcopy(
            base_params.get("custom_settings") or {},
        )
        try:
            requested_warmup = max(
                0,
                int(custom_settings.get(
                    "scail2_recast_warmup_frames",
                    8,
                ) or 0),
            )
        except (TypeError, ValueError):
            requested_warmup = 8
        identity_warmup_anchor = None
        if (
            len(active) > 1
            and bool(plan.get("cooccurring"))
            and not bool(plan.get("starts_with_all_active_mappings"))
        ):
            first_all_active = plan.get("first_all_active_frame_index")
            if first_all_active is not None:
                latent = max(1, int(latent_size))
                # Keep the normal hidden-frame budget whenever possible. The
                # remote anchor supplies the missing identity; increasing the
                # budget from 8 to 16 can needlessly create another diffusion
                # window on common 5-second shots.
                desired_warmup = min(
                    16,
                    max(latent, requested_warmup or 8),
                )
                desired_warmup = min(
                    16,
                    max(
                        latent,
                        (
                            (desired_warmup + latent - 1)
                            // latent
                        ) * latent,
                    ),
                )
                identity_warmup_anchor = max(
                    1,
                    int(plan["anchor_frame_index"]) - start,
                )
                custom_settings["scail2_recast_warmup_frames"] = (
                    desired_warmup
                )
                custom_settings[
                    "scail2_recast_warmup_anchor_offset"
                ] = identity_warmup_anchor
                published["identity_warmup_frames"] = desired_warmup
                published["identity_warmup_anchor_frame_index"] = int(
                    plan["anchor_frame_index"]
                )
                print(
                    f"[Recast] Shot {shot_index + 1} stays continuous; "
                    f"a hidden {desired_warmup}-frame identity pre-roll "
                    f"starts from mapped frame "
                    f"{int(plan['anchor_frame_index'])} before returning "
                    "to the shot boundary."
                )
        custom_settings.update({
            "scail2_reference_mask_path": shot_refs["primary_mask"],
            "scail2_additional_reference_mask_paths": list(
                shot_refs["additional_masks"],
            ),
            "scail2_reference_expected_colors": list(
                shot_refs["expected_colors"],
            ),
            "scail2_clip_reference_path": shot_refs["clip_identity_ref"],
            "scail2_primary_reference_people": len(active),
            "scail2_dynamic_source_scene_reference": True,
            "scail2_timeline_source_scene_reference": False,
            "scail2_source_scene_reference_path": shot_refs[
                "source_scene_reference"
            ]["image"],
            "scail2_source_scene_mask_path": shot_refs[
                "source_scene_reference"
            ]["mask"],
            "scail2_identity_latent_reference_index": 0,
        })
        shot_prompt = _build_recast_shot_prompt(
            len(active),
            finished_video_prompt=base_params.get("prompt"),
            total_mapping_count=len(mapping_masks),
        )
        tasks.append({
            "shot_index": shot_index,
            "params": {
                "prompt": shot_prompt,
                "video_guide": guide_path,
                "video_mask": mask_path,
                "image_refs": list(shot_refs["image_refs"]),
                "video_length": generated_frames,
                "trim_tail_frames": trim_tail,
                "video_prompt_type": f"V0{len(active)}AI",
                "image_prompt_type": "",
                # Each internal clip is silent. One pristine source track is
                # attached only after exact-frame assembly.
                "audio_prompt_type": "",
                "audio_guide": None,
                "audio_source": None,
                "force_fps": "control",
                "custom_settings": custom_settings,
                "_recast_protect_bystanders": False,
                "output_filename": (
                    f"recast_{job_id}_shot_{shot_index + 1}.mp4"
                ),
            },
        })
        plan["generated_task_index"] = len(tasks) - 1
        published.update({
            "generation_mode": "scail2",
            "generated_frame_count": generated_frames,
            "trim_tail_frames": trim_tail,
            "reference_mode": shot_refs["primary_mode"],
        })
        published_plans.append(published)

    return {
        "tasks": tasks,
        "shots": plans,
        "published_shots": published_plans,
        "frame_count": int(target_frame_count),
        "fps": float(generation_fps),
        "camera_shot_count": len(shot_ranges),
        "cast_transition_count": cast_transition_count,
    }


def _normalize_repaint_region_mappings(raw_mappings):
    """Validate optional source-video → edited-frame semantic mappings."""
    if raw_mappings in (None, []):
        return []
    if not isinstance(raw_mappings, list):
        raise ValueError("Repaint region_mappings must be a list.")
    if len(raw_mappings) > len(_RECAST_MASK_COLORS):
        raise ValueError("SCAIL-2 supports at most five Repaint regions.")
    mappings = []
    for index, raw in enumerate(raw_mappings):
        if not isinstance(raw, dict):
            raise ValueError(f"Repaint region {index + 1} is invalid.")
        source = str(
            raw.get("source")
            or raw.get("source_target")
            or raw.get("source_description")
            or ""
        ).strip()
        target = str(
            raw.get("target")
            or raw.get("target_description")
            or raw.get("edited_target")
            or ""
        ).strip()
        if not source or not target:
            raise ValueError(
                f"Repaint region {index + 1} needs both a source-video "
                "description and an edited-frame description."
            )
        mappings.append({
            "id": str(raw.get("id") or f"repaint-{index + 1}"),
            "source": source,
            "target": target,
        })
    return mappings


def _repaint_resolution_for_aspect(
    width, height, pixel_budget=848 * 480, block_size=16,
):
    """Return a SCAIL-sized canvas while preserving the source aspect."""
    import math

    source_width = int(width)
    source_height = int(height)
    block = max(1, int(block_size))
    budget = max(block * block, int(pixel_budget))
    if source_width <= 0 or source_height <= 0:
        raise ValueError("Repaint source dimensions must be positive.")
    ratio = float(source_width) / float(source_height)
    ideal_width = math.sqrt(float(budget) * ratio)
    ideal_height = math.sqrt(float(budget) / ratio)
    output_width = max(block, int(round(ideal_width / block)) * block)
    output_height = max(block, int(round(ideal_height / block)) * block)
    return output_width, output_height


def _validate_repaint_target_aspect(
    source_width, source_height, target_width, target_height,
    tolerance=0.025,
):
    """Reject edited frames that would require a destructive crop."""
    values = [
        int(source_width), int(source_height),
        int(target_width), int(target_height),
    ]
    if any(value <= 0 for value in values):
        raise ValueError("Repaint source and edited-frame dimensions must be positive.")
    source_ratio = float(values[0]) / float(values[1])
    target_ratio = float(values[2]) / float(values[3])
    difference = abs(target_ratio - source_ratio) / source_ratio
    if difference > float(tolerance):
        raise ValueError(
            "The edited first frame must keep the source video's aspect ratio "
            f"({values[0]}×{values[1]} source vs "
            f"{values[2]}×{values[3]} edited frame). "
            "Edit the extracted frame in Image Mode or resize without cropping."
        )
    return difference


def _prepare_repaint_target_frame(
    target_path, source_width, source_height, output_width, output_height,
    output_dir, job_id,
):
    """Orient, validate, and resize the edited frame without cropping."""
    from PIL import Image as _PILImage
    from PIL import ImageOps as _PILImageOps

    with _PILImage.open(target_path) as image:
        target = _PILImageOps.exif_transpose(image).convert("RGB")
        target_width, target_height = target.size
        _validate_repaint_target_aspect(
            source_width,
            source_height,
            target_width,
            target_height,
        )
        target = target.resize(
            (int(output_width), int(output_height)),
            resample=_PILImage.Resampling.LANCZOS,
        )
        os.makedirs(output_dir, exist_ok=True)
        prepared_path = os.path.join(
            output_dir,
            f"repaint_target_{job_id}.png",
        )
        target.save(prepared_path)
    return prepared_path, (target_width, target_height)


def _repaint_preview_data_uri(frame, semantic_mask, background="black"):
    """Blend a semantic mask over one RGB frame and return a JPEG data URI."""
    import base64
    import io as _io
    import numpy as np
    from PIL import Image as _PILImage

    rgb = np.asarray(frame, dtype=np.uint8)
    mask = np.asarray(semantic_mask, dtype=np.uint8)
    if rgb.shape != mask.shape:
        raise ValueError(
            f"Repaint preview frame/mask mismatch: {rgb.shape} vs {mask.shape}."
        )
    selected = (
        ~np.all(mask > 225, axis=-1)
        if background == "white"
        else np.any(mask > 30, axis=-1)
    )
    overlay = rgb.copy()
    if bool(selected.any()):
        overlay[selected] = (
            overlay[selected].astype(np.float32) * 0.45
            + mask[selected].astype(np.float32) * 0.55
        ).astype(np.uint8)
    buffer = _io.BytesIO()
    _PILImage.fromarray(overlay).save(buffer, format="JPEG", quality=85)
    return (
        "data:image/jpeg;base64,"
        + base64.b64encode(buffer.getvalue()).decode()
    )


def _build_repaint_semantic_conditioning(
    source_video, target_frame_path, mappings, output_dir,
    progress_callback=None, abort_callback=None,
):
    """Track mapped regions independently inside every detected camera shot."""
    import numpy as np
    from PIL import Image as _PILImage
    from shared import magic_mask

    source_path, source_frames, fps = magic_mask.prepare_video_mask_input(
        source_video,
    )
    shot_ranges = _detect_recast_shot_ranges(source_frames)
    if len(shot_ranges) > 1:
        print(
            "[Repaint] Detected "
            f"{len(shot_ranges)} camera shots; SAM3 will reacquire each "
            "mapped region after every cut."
        )
    with _PILImage.open(target_frame_path) as target_image:
        target_frame = np.asarray(target_image.convert("RGB"), dtype=np.uint8)

    source_masks = []
    target_masks = []
    mapping_summaries = []
    total = len(mappings)
    for index, mapping in enumerate(mappings):
        if abort_callback is not None:
            abort_callback()

        def _source_progress(done, frame_total, mapping_index=index):
            if abort_callback is not None:
                abort_callback()
            if progress_callback is not None:
                progress_callback(
                    mapping_index,
                    total,
                    done,
                    frame_total,
                )

        color = _RECAST_MASK_COLORS[index]
        source_mask = magic_mask.generate_keyword_masks(
            source_frames,
            mapping["source"],
            no_hole=True,
            colorize_objects=True,
            color_palette=[color],
            max_colored_objects=1,
            progress_callback=_source_progress,
            tracking_segments=shot_ranges,
        )
        summary = _summarize_recast_mapping_mask(source_mask, fps)
        if summary is None:
            raise ValueError(
                f"Repaint region {index + 1} found no "
                f"'{mapping['source']}' anywhere in the selected video."
            )
        target_mask = magic_mask.generate_keyword_masks(
            target_frame[None],
            mapping["target"],
            no_hole=True,
            colorize_objects=True,
            color_palette=[color],
            max_colored_objects=1,
        )[0]
        if not bool(target_mask.any()):
            raise ValueError(
                f"Repaint region {index + 1} found no "
                f"'{mapping['target']}' in the edited first frame."
            )
        source_masks.append(source_mask)
        target_masks.append(target_mask)
        mapping_summaries.append(summary)

    driving_mask, _ = _compose_recast_character_masks(
        source_masks,
        _RECAST_MASK_COLORS[:total],
        background_color=(0, 0, 0),
    )
    reference_mask, _ = _compose_recast_character_masks(
        target_masks,
        _RECAST_MASK_COLORS[:total],
        background_color=(255, 255, 255),
    )
    video_mask_path = magic_mask.save_mask_video(
        source_path,
        driving_mask,
        fps,
        [mapping["source"] for mapping in mappings],
        output_dir=output_dir,
        abort_callback=abort_callback,
        background_color=(0, 0, 0),
    )
    os.makedirs(output_dir, exist_ok=True)
    reference_mask_path = os.path.join(
        output_dir,
        "repaint_reference_mask_"
        + uuid.uuid4().hex[:8]
        + ".png",
    )
    _PILImage.fromarray(reference_mask).save(reference_mask_path)
    return {
        "source_video": source_path,
        "source_frames": source_frames,
        "fps": float(fps),
        "mapping_masks": source_masks,
        "mapping_summaries": mapping_summaries,
        "target_frame": target_frame,
        "target_masks": target_masks,
        "shot_ranges": [list(bounds) for bounds in shot_ranges],
        "shot_count": len(shot_ranges),
        "video_mask": video_mask_path,
        "reference_mask": reference_mask_path,
        "region_count": total,
    }


def _build_repaint_shot_prompt(
    active_count, *, finished_video_prompt=None, total_mapping_count=None,
):
    """Avoid mentioning mapped subjects that are absent from a camera shot."""
    count = max(1, min(5, int(active_count)))
    try:
        total_count = max(1, min(5, int(total_mapping_count)))
    except (TypeError, ValueError):
        total_count = None
    requested_prompt = str(finished_video_prompt or "").strip()
    if (
        total_count == count
        and any(character.isalnum() for character in requested_prompt)
    ):
        return requested_prompt
    noun = "region" if count == 1 else "regions"
    return (
        f"The {count} mapped edited {noun} move naturally with the exact "
        "source action and camera motion. Their edited appearance remains "
        "consistent, while the surrounding original scene, people, objects, "
        "lighting, and composition remain coherent and unchanged."
    )


def _build_repaint_shot_reference_conditioning(
    target_frame, target_masks, active_mapping_indices, source_frame,
    local_semantic_mask, output_dir, job_id, shot_index, *,
    cooccurring, reference_canvas, use_exact_target_frame=False,
):
    """Build one shot-local edited-region reference plus a clean scene anchor."""
    active = [int(index) for index in active_mapping_indices]
    if not active:
        raise ValueError("A generated Repaint shot needs an active region.")
    if any(
        index < 0 or index >= len(target_masks)
        for index in active
    ):
        raise ValueError("Repaint shot references contain an invalid mapping.")

    target_layers = []
    for local_index, mapping_index in enumerate(active):
        target_layers.append((
            target_frame,
            _recolor_recast_reference_mask(
                target_masks[mapping_index],
                mapping_index,
                local_index,
            ),
        ))

    if use_exact_target_frame:
        primary_image = target_frame
        primary_mask, _ = _compose_recast_character_masks(
            [layer[1] for layer in target_layers],
            _RECAST_MASK_COLORS[:len(active)],
            background_color=(255, 255, 255),
        )
        primary_mode = "edited_first_frame"
    else:
        primary_mode = "shot_layout"
        try:
            if len(active) > 1 and not cooccurring:
                raise ValueError(
                    "active edited regions never share one frame in this shot"
                )
            primary_image, primary_mask = (
                _compose_recast_group_reference_frame(
                    source_frame,
                    local_semantic_mask,
                    target_layers,
                    len(active),
                )
            )
        except ValueError as composition_error:
            print(
                f"[Repaint] Shot {shot_index + 1} has no usable shared "
                f"layout; using a balanced region sheet: "
                f"{composition_error}"
            )
            primary_image, primary_mask = (
                _compose_recast_cast_reference_frame(
                    target_layers,
                    len(active),
                    reference_canvas,
                )
            )
            primary_mode = "region_sheet"

    stem = f"repaint_shot_ref_{job_id}_{shot_index + 1}"
    primary_path, primary_mask_path = _save_recast_reference_pair(
        output_dir,
        stem,
        primary_image,
        primary_mask,
    )
    scene_reference = _build_recast_source_scene_reference(
        source_frame,
        local_semantic_mask,
        len(active),
        output_dir,
        f"repaint_{job_id}_shot_{shot_index + 1}",
        output_size=tuple(reference_canvas),
    )
    return {
        "image_start": primary_path,
        "primary_mask": primary_mask_path,
        "expected_colors": [
            list(_RECAST_MASK_COLORS[0])
            if len(active) == 1
            else None
        ],
        "source_scene_reference": scene_reference,
        "primary_mode": primary_mode,
    }


def _build_repaint_shot_manifest(
    base_params, conditioning, output_dir, job_id, *,
    reference_canvas, target_frame_count, generation_fps,
    minimum_frames, latent_size,
):
    """Create silent, exact-length mapped Repaint tasks per camera shot."""
    import copy
    import numpy as np

    source_frames, mapping_masks, shot_ranges = (
        _resample_recast_tracking_timeline(
            conditioning["source_frames"],
            conditioning["mapping_masks"],
            conditioning["shot_ranges"],
            target_frame_count,
        )
    )
    plans = _plan_recast_shot_segments(mapping_masks, shot_ranges)

    global_semantic = np.zeros(
        (*source_frames.shape[:-1], 3),
        dtype=np.uint8,
    )
    occupied = np.zeros(source_frames.shape[:-1], dtype=bool)
    for mapping_index, mapping_mask in enumerate(mapping_masks):
        region = (
            np.any(mapping_mask > 30, axis=-1)
            if mapping_mask.ndim == 4
            else mapping_mask.astype(bool)
        )
        writable = region & ~occupied
        global_semantic[writable] = np.asarray(
            _RECAST_MASK_COLORS[mapping_index],
            dtype=np.uint8,
        )
        occupied |= region

    os.makedirs(output_dir, exist_ok=True)
    tasks = []
    published_plans = []
    for plan in plans:
        shot_index = int(plan["shot_index"])
        start, end = int(plan["start_frame"]), int(plan["end_frame"])
        active = list(plan["active_mapping_indices"])
        resized_source = _resize_recast_shot_frames(
            source_frames[start:end],
            reference_canvas,
        )
        published = dict(plan)
        published["active_mapping_indices"] = list(active)

        if not active:
            passthrough_path = os.path.join(
                output_dir,
                f"repaint_{job_id}_shot_{shot_index + 1}_source.mp4",
            )
            _write_recast_shot_video(
                passthrough_path,
                resized_source,
                generation_fps,
            )
            plan["passthrough_path"] = passthrough_path
            published["generation_mode"] = "source_passthrough"
            published_plans.append(published)
            continue

        local_mask = _remap_recast_shot_mask(
            global_semantic[start:end],
            active,
            background_color=(0, 0, 0),
        )
        resized_mask = _resize_recast_shot_frames(
            local_mask,
            reference_canvas,
            semantic=True,
        )
        use_exact_target_frame = (
            shot_index == 0
            and len(active) == len(mapping_masks)
            and all(
                bool(np.any(mapping_masks[index][start] > 30))
                for index in active
            )
        )
        # The user's edited image is the selected first source frame. Keep
        # its clean scene anchor on that same frame; pairing it with a later
        # camera position would create contradictory background references.
        anchor_index = (
            start
            if use_exact_target_frame
            else int(plan["anchor_frame_index"])
        )
        anchor_mask = _remap_recast_shot_mask(
            global_semantic[anchor_index],
            active,
            background_color=(0, 0, 0),
        )
        shot_refs = _build_repaint_shot_reference_conditioning(
            conditioning["target_frame"],
            conditioning["target_masks"],
            active,
            source_frames[anchor_index],
            anchor_mask,
            output_dir,
            job_id,
            shot_index,
            cooccurring=bool(plan["cooccurring"]),
            reference_canvas=reference_canvas,
            use_exact_target_frame=use_exact_target_frame,
        )

        generated_frames, trim_tail = (
            _quantize_recast_shot_frame_count(
                end - start,
                minimum_frames,
                latent_size,
            )
        )
        pad_count = generated_frames - (end - start)
        if pad_count > 0:
            resized_source = np.concatenate([
                resized_source,
                np.repeat(resized_source[-1:], pad_count, axis=0),
            ])
            resized_mask = np.concatenate([
                resized_mask,
                np.repeat(resized_mask[-1:], pad_count, axis=0),
            ])

        guide_path = os.path.join(
            output_dir,
            f"repaint_{job_id}_shot_{shot_index + 1}_guide.mp4",
        )
        mask_path = os.path.join(
            output_dir,
            f"repaint_{job_id}_shot_{shot_index + 1}_mask.mp4",
        )
        _write_recast_shot_video(
            guide_path,
            resized_source,
            generation_fps,
        )
        _write_recast_shot_video(
            mask_path,
            resized_mask,
            generation_fps,
            semantic=True,
        )

        custom_settings = copy.deepcopy(
            base_params.get("custom_settings") or {},
        )
        custom_settings.update({
            "scail2_reference_mask_path": shot_refs["primary_mask"],
            "scail2_additional_reference_mask_paths": [],
            "scail2_reference_expected_colors": list(
                shot_refs["expected_colors"],
            ),
            "scail2_clip_reference_path": shot_refs["image_start"],
            "scail2_primary_reference_people": len(active),
            "scail2_dynamic_source_scene_reference": True,
            "scail2_timeline_source_scene_reference": False,
            "scail2_source_scene_reference_path": shot_refs[
                "source_scene_reference"
            ]["image"],
            "scail2_source_scene_mask_path": shot_refs[
                "source_scene_reference"
            ]["mask"],
        })
        shot_prompt = _build_repaint_shot_prompt(
            len(active),
            finished_video_prompt=base_params.get("prompt"),
            total_mapping_count=len(mapping_masks),
        )
        tasks.append({
            "shot_index": shot_index,
            "params": {
                "prompt": shot_prompt,
                "video_guide": guide_path,
                "video_mask": mask_path,
                "image_start": shot_refs["image_start"],
                "image_refs": [],
                "video_length": generated_frames,
                "trim_tail_frames": trim_tail,
                "video_prompt_type": f"V{len(active)}A",
                "image_prompt_type": "S",
                # Internal shots remain silent. The finishing worker restores
                # one pristine source track after exact-frame assembly.
                "audio_prompt_type": "",
                "audio_guide": None,
                "audio_source": None,
                "force_fps": "control",
                "custom_settings": custom_settings,
                "output_filename": (
                    f"repaint_{job_id}_shot_{shot_index + 1}.mp4"
                ),
            },
        })
        plan["generated_task_index"] = len(tasks) - 1
        published.update({
            "generation_mode": "scail2",
            "generated_frame_count": generated_frames,
            "trim_tail_frames": trim_tail,
            "reference_mode": shot_refs["primary_mode"],
            "reference_anchor_frame_index": anchor_index,
            "native_scene_preservation": True,
        })
        published_plans.append(published)

    return {
        "tasks": tasks,
        "shots": plans,
        "published_shots": published_plans,
        "frame_count": int(target_frame_count),
        "fps": float(generation_fps),
    }


@api.post("/api/v1/repaint/preview")
async def repaint_preview_endpoint(request: Request):
    """Preview optional source/edited-frame semantic correspondences."""
    body = await request.json()
    workspace = body.get("workspace")
    video_path = _resolve_recast_media(request, body.get("video_path"), workspace)
    target_path = _resolve_recast_media(
        request,
        body.get("target_frame_path"),
        workspace,
    )
    if not video_path:
        raise HTTPException(
            status_code=400,
            detail=f"Video not found: {body.get('video_path')}",
        )
    if not target_path:
        raise HTTPException(
            status_code=400,
            detail=(
                "Edited first frame not found: "
                f"{body.get('target_frame_path')}"
            ),
        )
    try:
        mappings = _normalize_repaint_region_mappings(
            body.get("region_mappings"),
        )
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc))
    if not mappings:
        raise HTTPException(
            status_code=400,
            detail="Add at least one region before previewing mappings.",
        )

    at_time = float(body.get("time", 0) or 0)
    try:
        import decord
        import numpy as np
        from PIL import Image as _PILImage
        from PIL import ImageOps as _PILImageOps
        from shared import magic_mask

        reader = decord.VideoReader(video_path)
        fps = reader.get_avg_fps() or 25
        frame_index = min(
            len(reader) - 1,
            max(0, int(at_time * fps)),
        )
        source_frame = reader[frame_index].asnumpy()
        del reader
        source_height, source_width = source_frame.shape[:2]
        with _PILImage.open(target_path) as image:
            target_image = _PILImageOps.exif_transpose(image).convert("RGB")
            _validate_repaint_target_aspect(
                source_width,
                source_height,
                *target_image.size,
            )
            target_frame = np.asarray(
                target_image.resize(
                    (source_width, source_height),
                    resample=_PILImage.Resampling.LANCZOS,
                ),
                dtype=np.uint8,
            )

        source_preview_mask = np.zeros_like(source_frame, dtype=np.uint8)
        target_preview_mask = np.full_like(
            target_frame,
            255,
            dtype=np.uint8,
        )
        source_occupied = np.zeros(
            source_frame.shape[:2],
            dtype=bool,
        )
        target_occupied = np.zeros(
            target_frame.shape[:2],
            dtype=bool,
        )
        results = []
        for index, mapping in enumerate(mappings):
            color = _RECAST_MASK_COLORS[index]
            source_mask = magic_mask.generate_keyword_masks(
                source_frame[None],
                mapping["source"],
                no_hole=True,
                colorize_objects=True,
                color_palette=[color],
                max_colored_objects=1,
            )[0]
            target_mask = magic_mask.generate_keyword_masks(
                target_frame[None],
                mapping["target"],
                no_hole=True,
                colorize_objects=True,
                color_palette=[color],
                max_colored_objects=1,
            )[0]
            source_region = np.any(source_mask > 30, axis=-1)
            target_region = np.any(target_mask > 30, axis=-1)
            source_preview_mask[source_region & ~source_occupied] = color
            target_preview_mask[target_region & ~target_occupied] = color
            source_occupied |= source_region
            target_occupied |= target_region
            results.append({
                "mapping_index": index,
                "source": mapping["source"],
                "target": mapping["target"],
                "source_found": bool(source_region.any()),
                "target_found": bool(target_region.any()),
                "color": list(color),
            })
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc))
    except Exception as exc:
        raise HTTPException(
            status_code=500,
            detail=f"Repaint preview failed: {exc}",
        )

    found = all(
        result["source_found"] and result["target_found"]
        for result in results
    )
    return {
        "found": found,
        "frame_index": frame_index,
        "source_preview": _repaint_preview_data_uri(
            source_frame,
            source_preview_mask,
            background="black",
        ),
        "target_preview": _repaint_preview_data_uri(
            target_frame,
            target_preview_mask,
            background="white",
        ),
        "mapping_results": results,
    }


@api.post("/api/v1/repaint")
async def repaint_endpoint(request: Request):
    """Animate an edited first frame with SCAIL-2 and a source video.

    With no region mappings this deliberately mirrors the proven Studio
    Video/Frames SCAIL Animate path. Optional mappings add paired SAM3
    semantic masks for specific people or objects without changing that
    underlying motion-conditioning recipe.
    """
    body = await request.json()
    workspace = body.get("workspace") or _get_active_workspace()
    job_out_dir = _require_project_access(request, workspace)
    original_video_path = _resolve_recast_media(
        request,
        body.get("video_path"),
        workspace,
    )
    original_target_path = _resolve_recast_media(
        request,
        body.get("target_frame_path"),
        workspace,
    )
    if not original_video_path:
        raise HTTPException(
            status_code=400,
            detail=f"Video not found: {body.get('video_path')}",
        )
    if not original_target_path:
        raise HTTPException(
            status_code=400,
            detail=(
                "Edited first frame not found: "
                f"{body.get('target_frame_path')}"
            ),
        )
    try:
        mappings = _normalize_repaint_region_mappings(
            body.get("region_mappings"),
        )
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc))

    job_id = uuid.uuid4().hex[:8]
    video_path = original_video_path
    trim_start = body.get("start_time")
    trim_end = body.get("end_time")
    selected_start = 0.0
    selected_end = None
    if trim_start is not None and trim_end is not None:
        try:
            selected_start = float(trim_start)
            selected_end = float(trim_end)
        except (TypeError, ValueError):
            raise HTTPException(
                status_code=400,
                detail="Repaint trim times must be numeric.",
            )
        if selected_start < 0 or selected_end <= selected_start + 0.05:
            raise HTTPException(
                status_code=400,
                detail="Repaint needs a valid source-video time range.",
            )
        try:
            import subprocess

            trim_dir = os.path.join(os.getcwd(), "uploads")
            os.makedirs(trim_dir, exist_ok=True)
            trimmed_path = os.path.join(
                trim_dir,
                f"repaint_trim_{job_id}.mp4",
            )
            command = [
                "ffmpeg", "-y", "-i", video_path,
                "-ss", f"{selected_start:.3f}",
                "-to", f"{selected_end:.3f}",
                "-c:v", "libx264", "-crf", "18", "-preset", "fast",
                "-c:a", "aac", "-b:a", "192k",
                trimmed_path,
            ]
            process = subprocess.run(
                command,
                capture_output=True,
                text=True,
                timeout=180,
            )
            if process.returncode != 0 or not os.path.isfile(trimmed_path):
                raise RuntimeError(process.stderr[-500:])
            write_upload_access_sidecar(
                trimmed_path,
                request.state.maestro_session_id,
                private=True,
            )
            video_path = trimmed_path
            print(
                "[Repaint] Trimmed source to "
                f"[{selected_start:.2f}s, {selected_end:.2f}s] -> "
                f"{os.path.basename(trimmed_path)}"
            )
        except Exception as exc:
            raise HTTPException(
                status_code=500,
                detail=f"Could not prepare the selected Repaint range: {exc}",
            )

    try:
        import decord

        reader = decord.VideoReader(video_path)
        fps = float(reader.get_avg_fps() or 25)
        total_frames = len(reader)
        if total_frames <= 0:
            raise ValueError("the selected video range contains no frames")
        probe_frame = reader[0].asnumpy()
        del reader
    except Exception as exc:
        raise HTTPException(
            status_code=400,
            detail=f"Cannot read Repaint source video: {exc}",
        )

    source_height, source_width = probe_frame.shape[:2]
    resolution_profile = _normalize_recast_resolution_profile(
        body.get("resolution_profile"),
    )
    output_width, output_height = _recast_resolution_for_source(
        probe_frame,
        resolution_profile,
    )
    output_resolution = f"{output_width}x{output_height}"
    repaint_vram_gb = 0.0
    try:
        repaint_vram_gb = float(
            _get_cached_hardware().get("gpu_vram_gb", 0.0),
        )
    except (TypeError, ValueError, AttributeError):
        repaint_vram_gb = 0.0
    repaint_window_size = _recast_window_size_for_profile(
        resolution_profile,
        repaint_vram_gb,
    )
    if repaint_window_size <= 0:
        raise HTTPException(
            status_code=400,
            detail=(
                "704p Repaint currently requires at least 16 GB of VRAM. "
                f"Detected {repaint_vram_gb:.1f} GB; select 512p or 480p."
            ),
        )
    print(
        f"[Repaint] Resolution profile {resolution_profile} -> "
        f"{output_resolution}."
    )
    if resolution_profile == "704p":
        hardware_label = (
            f"{repaint_vram_gb:.1f} GB VRAM"
            if repaint_vram_gb > 0
            else "unknown VRAM"
        )
        print(
            f"[Repaint] Adaptive 704p window: {hardware_label} -> "
            f"{repaint_window_size} frames with 5-frame overlap."
        )
    try:
        prepared_target_path, target_size = _prepare_repaint_target_frame(
            original_target_path,
            source_width,
            source_height,
            output_width,
            output_height,
            os.path.join(os.getcwd(), "uploads"),
            job_id,
        )
        write_upload_access_sidecar(
            prepared_target_path,
            request.state.maestro_session_id,
            private=True,
        )
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc))
    except Exception as exc:
        raise HTTPException(
            status_code=500,
            detail=f"Could not prepare the edited first frame: {exc}",
        )

    model_type = str(body.get("model_type") or "scail2_14B_fast")
    if model_type not in {"scail2_14B_fast", "scail2_14B"}:
        raise HTTPException(
            status_code=400,
            detail=(
                "Repaint requires SCAIL-2 Fast or SCAIL-2 HQ. "
                f"Received: {model_type}"
            ),
        )
    if wgp.get_model_def(model_type) is None:
        raise HTTPException(
            status_code=400,
            detail=f"Unknown model: {model_type}",
        )
    fast_profile = model_type == "scail2_14B_fast"
    duration_s = total_frames / fps if fps else 0.0
    force_fps = "control"
    generation_frames = total_frames
    if fps > 30.5:
        force_fps = "30"
        generation_frames = int(round(duration_s * 30.0))
        print(
            f"[Repaint] fps cap: {fps:.6g}fps source → "
            f"30fps ({generation_frames} frames)"
        )

    raw_prompt = str(body.get("prompt") or "").strip()
    prompt = raw_prompt or (
        "The edited first-frame scene moves naturally with the source "
        "video's exact action, interaction, and camera motion."
    )
    activated_loras = body.get("activated_loras")
    if not isinstance(activated_loras, list):
        activated_loras = []
    loras_multipliers = str(body.get("loras_multipliers") or "")
    region_count = len(mappings)
    process_type = f"V{region_count}A" if region_count else "V1"
    inference_steps = _normalize_scail2_inference_steps(
        body.get("num_inference_steps"),
        6 if fast_profile else 40,
    )
    # SCAIL-2 Fast uses a CFG-step-distilled LightX LoRA, so CFG remains at
    # one. The full model supports ordinary classifier-free guidance.
    guidance_scale = (
        1.0
        if fast_profile
        else _normalize_scail2_guidance_scale(
            body.get("guidance_scale"),
            5.0,
        )
    )
    print(
        f"[Repaint] Sampling: {inference_steps} steps, "
        f"guidance {guidance_scale:g} "
        f"({'Fast distilled' if fast_profile else 'HQ'})."
    )
    gen_params = {
        "prompt": prompt,
        "model_type": model_type,
        "negative_prompt": str(body.get("negative_prompt") or ""),
        "seed": body.get("seed", -1),
        "activated_loras": activated_loras,
        "loras_multipliers": loras_multipliers,
        "num_inference_steps": inference_steps,
        "flow_shift": 5 if fast_profile else 3,
        "guidance_scale": guidance_scale,
        "sample_solver": "euler" if fast_profile else "unipc",
        "generation_mode": "video",
        # Keep ``restyle`` as the internal saved-output id so existing gallery
        # filters and sidecars remain compatible; the UI calls this Repaint.
        "edit_sub_mode": "restyle",
        "video_prompt_type": process_type,
        "image_prompt_type": "S",
        "video_guide": video_path,
        "image_start": prepared_target_path,
        "video_length": generation_frames,
        "_duration_seconds": duration_s,
        "resolution": output_resolution,
        "force_fps": force_fps,
        "audio_prompt_type": "R",
        "input_video_strength": 1,
        "sliding_window_size": repaint_window_size,
        "sliding_window_overlap": 5,
        "settings_version": 2.57,
        "custom_settings": {
            "image_ref_keyword_content": (
                mappings[0]["target"] if mappings else "human character"
            ),
            "scail2_animate_preprocessing": "raw",
        },
        # Gallery Load Settings / API diagnostics.
        "edit_video_path": original_video_path,
        "edit_start_time": selected_start,
        "edit_end_time": selected_end if selected_end is not None else duration_s,
        "edit_repaint_target_frame": original_target_path,
        "edit_repaint_prepared_target_frame": prepared_target_path,
        "edit_repaint_target_size": list(target_size),
        "edit_repaint_region_mappings": mappings,
        "edit_repaint_region_count": region_count,
        "edit_repaint_resolution_profile": resolution_profile,
        "edit_repaint_output_resolution": [output_width, output_height],
        "edit_repaint_sliding_window_size": repaint_window_size,
        "edit_repaint_conditioning": (
            "semantic_regions" if mappings else "whole_frame_animate"
        ),
    }

    workspace_name = workspace or _get_active_workspace()
    job = {
        "id": job_id,
        "status": "queued",
        "progress": 0,
        "step": 0,
        "total_steps": 0,
        "phase": "",
        "message": "Queued (repaint)",
        "created_at": time.time(),
        "params": gen_params,
        "output_files": [],
        "error": None,
        "workspace": workspace_name,
        "out_dir": job_out_dir,
    }
    if not mappings:
        _queue_recovery_register_and_publish(job)
        return {
            "job_id": job_id,
            "status": "queued",
            "frames": generation_frames,
            "region_count": 0,
            "resolution_profile": resolution_profile,
            "resolution": output_resolution,
            "sliding_window_size": repaint_window_size,
            "num_inference_steps": inference_steps,
            "guidance_scale": guidance_scale,
        }

    def _run_repaint(_job_id):
        abort_state = {"abort": False}
        shot_temp_dir = None
        shot_final_out_dir = None
        try:
            with generation_slot(_gen_lock, job) as acquired:
                if not acquired:
                    return
                if not try_start(
                    job,
                    generation_lock=_gen_lock,
                    phase="Mapping repaint regions",
                    message=(
                        f"Mapping {region_count} Repaint "
                        f"region{'s' if region_count != 1 else ''}..."
                    ),
                ):
                    return
                if not register_abort_state(
                    job,
                    job_id,
                    _active_gen_states,
                    abort_state,
                ):
                    return

                progress_state = {"bucket": -1}

                def _abort_repaint_mapping():
                    if is_cancel_requested(job):
                        raise InterruptedError(
                            "Repaint region mapping was cancelled",
                        )

                def _mapping_progress(index, count, done, total):
                    percent = min(
                        100,
                        max(
                            0,
                            int(round(
                                100
                                * (
                                    index
                                    + float(done) / max(1, total)
                                )
                                / max(1, count)
                            )),
                        ),
                    )
                    bucket = percent // 5
                    if bucket == progress_state["bucket"]:
                        return
                    progress_state["bucket"] = bucket
                    if not update_job(
                        job,
                        phase="Mapping repaint regions",
                        message=f"Mapping Repaint regions... {percent}%",
                    ):
                        raise InterruptedError(
                            "Repaint region mapping was cancelled",
                        )

                conditioning = _build_repaint_semantic_conditioning(
                    video_path,
                    prepared_target_path,
                    mappings,
                    os.path.join(os.getcwd(), "uploads"),
                    progress_callback=_mapping_progress,
                    abort_callback=_abort_repaint_mapping,
                )
                _stamp_upload_derivatives(
                    conditioning,
                    job.get("session_id") or request.state.maestro_session_id,
                )
                if is_cancel_requested(job):
                    return
                job["params"]["video_mask"] = conditioning["video_mask"]
                job["params"]["custom_settings"][
                    "scail2_reference_mask_path"
                ] = conditioning["reference_mask"]
                job["params"]["custom_settings"][
                    "scail2_primary_reference_people"
                ] = region_count
                job["params"]["custom_settings"][
                    "scail2_reference_expected_colors"
                ] = [
                    list(color)
                    for color in _RECAST_MASK_COLORS[:region_count]
                ]
                job["params"]["edit_repaint_video_mask"] = conditioning[
                    "video_mask"
                ]
                job["params"]["edit_repaint_reference_mask"] = conditioning[
                    "reference_mask"
                ]
                job["params"]["edit_repaint_shot_ranges"] = conditioning[
                    "shot_ranges"
                ]
                job["params"]["edit_repaint_mapping_summaries"] = (
                    conditioning["mapping_summaries"]
                )
                print(
                    "[Repaint] Built native semantic correspondence for "
                    f"{region_count} region{'s' if region_count != 1 else ''}."
                )

                if not update_job(
                    job,
                    phase="Preparing camera shots",
                    message="Preparing shot-specific Repaint references...",
                ):
                    return
                import secrets
                import shutil
                import tempfile

                try:
                    resolved_seed = int(job["params"].get("seed", -1))
                except (TypeError, ValueError):
                    resolved_seed = -1
                if resolved_seed < 0:
                    resolved_seed = secrets.randbelow(1_000_000_000)
                job["params"]["seed"] = resolved_seed

                generation_fps = (
                    30.0
                    if force_fps == "30"
                    else float(conditioning.get("fps") or fps or 25.0)
                )
                try:
                    minimum_frames, _frame_step, latent_size = (
                        wgp.get_model_min_frames_and_step(model_type)
                    )
                except Exception:
                    minimum_frames, latent_size = 5, 4

                shot_temp_dir = tempfile.mkdtemp(
                    prefix="maestro-repaint-shots-",
                )
                try:
                    shot_manifest = _build_repaint_shot_manifest(
                        job["params"],
                        conditioning,
                        shot_temp_dir,
                        job_id,
                        reference_canvas=(output_width, output_height),
                        target_frame_count=generation_frames,
                        generation_fps=generation_fps,
                        minimum_frames=minimum_frames,
                        latent_size=latent_size,
                    )
                    if not shot_manifest["tasks"]:
                        raise ValueError(
                            "The mapped Repaint regions were too small to "
                            "schedule in any camera shot."
                        )
                except Exception:
                    shutil.rmtree(
                        shot_temp_dir,
                        ignore_errors=True,
                    )
                    shot_temp_dir = None
                    raise

                final_out_dir = job.get("out_dir") or _workspace_dir(
                    workspace_name,
                )
                shot_final_out_dir = final_out_dir
                job["params"].update({
                    "_defer_output_publication": True,
                    "_repaint_shot_manifest": shot_manifest["tasks"],
                    "_repaint_shot_temp_dir": shot_temp_dir,
                    "_repaint_final_out_dir": final_out_dir,
                    "_repaint_source_video": video_path,
                    "_repaint_shot_bundle": {
                        "shots": shot_manifest["shots"],
                        "published_shots": shot_manifest[
                            "published_shots"
                        ],
                        "frame_count": shot_manifest["frame_count"],
                        "fps": shot_manifest["fps"],
                        "resolved_seed": resolved_seed,
                    },
                    "edit_repaint_shot_aware": True,
                    "edit_repaint_shot_plan": shot_manifest[
                        "published_shots"
                    ],
                    "edit_repaint_native_scene_preservation": True,
                })
                # Generated shots and their references are disposable. The
                # finishing worker publishes only the exact joined timeline.
                job["out_dir"] = shot_temp_dir
                generated_count = len(shot_manifest["tasks"])
                passthrough_count = sum(
                    1
                    for shot in shot_manifest["shots"]
                    if shot["mode"] == "passthrough"
                )
                print(
                    "[Repaint] Shot-aware plan prepared "
                    f"{len(shot_manifest['shots'])} camera shots "
                    f"({generated_count} generated, "
                    f"{passthrough_count} source passthrough), "
                    f"{shot_manifest['frame_count']} exact output frames "
                    f"at {shot_manifest['fps']:.6g}fps."
                )
        except InterruptedError:
            return
        except Exception as exc:
            traceback.print_exc()
            if shot_temp_dir and os.path.isdir(shot_temp_dir):
                import shutil

                shutil.rmtree(shot_temp_dir, ignore_errors=True)
                if shot_final_out_dir:
                    job["out_dir"] = shot_final_out_dir
            finish_job(
                job,
                "failed",
                error=f"Repaint region mapping failed: {exc}",
                message="Region mapping failed",
            )
            return
        finally:
            unregister_abort_state(
                job_id,
                _active_gen_states,
                abort_state,
            )

        if not try_requeue(job, message="Queued (repaint)", phase=""):
            if shot_temp_dir and os.path.isdir(shot_temp_dir):
                import shutil

                shutil.rmtree(shot_temp_dir, ignore_errors=True)
                if shot_final_out_dir:
                    job["out_dir"] = shot_final_out_dir
            return
        _run_repaint_shot_generation(job_id)

    _queue_recovery_register_and_publish(
        job,
        worker=_run_repaint,
        recovery_kind="studio_repaint_preparation",
        thread_name=f"studio-repaint-{job_id}",
    )
    return {
        "job_id": job_id,
        "status": "queued",
        "frames": generation_frames,
        "region_count": region_count,
        "resolution_profile": resolution_profile,
        "resolution": output_resolution,
        "sliding_window_size": repaint_window_size,
        "num_inference_steps": inference_steps,
        "guidance_scale": guidance_scale,
    }


@api.post("/api/v1/recast/preview")
async def recast_preview_endpoint(request: Request):
    """Preview mapped people across the selected Recast timeline.

    Body: { video_path: str, target?: str, person_count?: int,
            character_mappings?: list, ref_image_path?: str,
            time?: float, end_time?: float, workspace?: str }
    """
    body = await request.json()
    workspace = body.get("workspace")
    video_path = _resolve_recast_media(request, body.get("video_path"), workspace)
    if not video_path:
        raise HTTPException(status_code=400, detail=f"Video not found: {body.get('video_path')}")
    raw_mappings = body.get("character_mappings")
    explicit_mappings = isinstance(raw_mappings, list) and len(raw_mappings) > 0
    if explicit_mappings:
        if len(raw_mappings) > len(_RECAST_MASK_COLORS):
            raise HTTPException(
                status_code=400,
                detail="SCAIL-2 supports at most five character mappings.",
            )
        preview_mappings = []
        for index, mapping in enumerate(raw_mappings):
            if not isinstance(mapping, dict):
                raise HTTPException(
                    status_code=400,
                    detail=f"Character mapping {index + 1} is invalid.",
                )
            target = str(mapping.get("target") or "").strip()
            if not target:
                raise HTTPException(
                    status_code=400,
                    detail=f"Character mapping {index + 1} needs a source-person description.",
                )
            preview_mappings.append({"target": target})
        person_count = len(preview_mappings)
    else:
        target = (body.get("target") or "person").strip() or "person"
        person_count = _normalize_recast_person_count(body.get("person_count"))
        preview_mappings = [{"target": target}]
    mask_colors = _RECAST_MASK_COLORS[:person_count]
    at_time = max(0.0, float(body.get("time", 0) or 0))
    try:
        import decord
        import numpy as np

        vr = decord.VideoReader(video_path)
        fps = vr.get_avg_fps() or 25
        total_video_frames = len(vr)
        if total_video_frames <= 0:
            raise ValueError("The selected video contains no frames.")
        start_index = min(
            total_video_frames - 1,
            max(0, int(round(at_time * fps))),
        )
        raw_end_time = body.get("end_time")
        end_time = (
            float(raw_end_time)
            if raw_end_time is not None
            else float(total_video_frames) / float(fps)
        )
        if end_time <= at_time:
            end_index = total_video_frames - 1
        else:
            end_index = min(
                total_video_frames - 1,
                max(start_index, int(round(end_time * fps)) - 1),
            )
        if explicit_mappings:
            span = end_index - start_index + 1
            sample_count = min(24, max(1, span))
            sample_indices = np.unique(
                np.rint(
                    np.linspace(start_index, end_index, sample_count),
                ).astype(np.int64)
            )
            sampled_frames = vr.get_batch(sample_indices).asnumpy()
        else:
            sample_indices = np.asarray([start_index], dtype=np.int64)
            sampled_frames = vr.get_batch(sample_indices).asnumpy()
        del vr
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"Cannot read video: {e}")
    try:
        from shared import magic_mask

        mapping_results = []
        mapping_anchors = None
        if explicit_mappings:
            mapping_masks = []
            found_mapping_indices = []
            for index, mapping in enumerate(preview_mappings):
                tracking_target = _normalize_recast_tracking_target(
                    mapping["target"],
                )
                mapping_mask = magic_mask.generate_keyword_masks(
                    sampled_frames,
                    tracking_target,
                    no_hole=True,
                    colorize_objects=True,
                    color_palette=[mask_colors[index]],
                    max_colored_objects=1,
                    tracking_segments=[
                        (sample_index, sample_index + 1)
                        for sample_index in range(len(sampled_frames))
                    ],
                )
                region = np.any(mapping_mask > 30, axis=-1)
                areas = region.reshape(len(region), -1).sum(axis=1)
                present_samples = np.flatnonzero(areas > 0)
                found_mapping = bool(len(present_samples))
                result = {
                    "mapping_index": index,
                    "target": mapping["target"],
                    "found": found_mapping,
                    "color": list(mask_colors[index]),
                    "overlap_fraction": 0.0,
                    "first_frame_index": None,
                    "first_time_seconds": None,
                    "anchor_frame_index": None,
                    "anchor_time_seconds": None,
                    "anchor_sample_index": None,
                }
                if found_mapping:
                    anchor_sample_index = int(np.argmax(areas))
                    first_sample_index = int(present_samples[0])
                    anchor_frame_index = int(
                        sample_indices[anchor_sample_index]
                    )
                    first_frame_index = int(
                        sample_indices[first_sample_index]
                    )
                    result.update({
                        "first_frame_index": first_frame_index,
                        "first_time_seconds": (
                            float(first_frame_index) / float(fps)
                        ),
                        "anchor_frame_index": anchor_frame_index,
                        "anchor_time_seconds": (
                            float(anchor_frame_index) / float(fps)
                        ),
                        "anchor_sample_index": anchor_sample_index,
                    })
                    mapping_masks.append(mapping_mask)
                    found_mapping_indices.append(index)
                mapping_results.append(result)
            if mapping_masks:
                sampled_mask, overlaps = _compose_recast_character_masks(
                    mapping_masks,
                    [mask_colors[index] for index in found_mapping_indices],
                )
                for mapping_index, overlap in zip(
                    found_mapping_indices, overlaps,
                ):
                    mapping_results[mapping_index][
                        "overlap_fraction"
                    ] = overlap
                common_sample_index, scene_sample_index = (
                    _select_recast_timeline_anchor(mapping_masks)
                )
            else:
                sampled_mask = np.full(
                    sampled_frames.shape,
                    255,
                    dtype=np.uint8,
                )
                common_sample_index, scene_sample_index = None, 0
            matched_people = sum(result["found"] for result in mapping_results)
            selected_sample_index = (
                common_sample_index
                if common_sample_index is not None
                else scene_sample_index
            )
            idx = int(sample_indices[selected_sample_index])
            frame = sampled_frames[selected_sample_index]
            mask = sampled_mask[selected_sample_index]
            preview_image = _compose_recast_timeline_preview(
                sampled_frames,
                [
                    mapping_mask
                    for mapping_mask in mapping_masks
                ],
                [
                    mapping_results[mapping_index]
                    for mapping_index in found_mapping_indices
                ],
            )
            if matched_people == person_count:
                mapping_anchors = []
                tracked_by_mapping = {
                    mapping_index: mapping_mask
                    for mapping_index, mapping_mask in zip(
                        found_mapping_indices,
                        mapping_masks,
                    )
                }
                for mapping_index in range(person_count):
                    result = mapping_results[mapping_index]
                    anchor_sample_index = int(
                        result["anchor_sample_index"]
                    )
                    mapping_anchors.append({
                        "frame_index": result["anchor_frame_index"],
                        "source_frame": sampled_frames[
                            anchor_sample_index
                        ],
                        "source_mask": sampled_mask[
                            anchor_sample_index
                        ],
                        "mapping_mask": tracked_by_mapping[mapping_index][
                            anchor_sample_index
                        ],
                    })
        else:
            mask = magic_mask.generate_keyword_masks(
                sampled_frames, target, no_hole=True,
                colorize_objects=True,
                color_palette=mask_colors,
                max_colored_objects=person_count,
            )[0]
            idx = int(sample_indices[0])
            frame = sampled_frames[0]
            matched_people = _count_recast_mask_people(mask, mask_colors)
            mapping_results = [{
                "mapping_index": 0,
                "target": target,
                "found": matched_people >= person_count,
                "color": list(mask_colors[0]),
                "overlap_fraction": 0.0,
                "first_frame_index": idx if matched_people else None,
                "first_time_seconds": (
                    float(idx) / float(fps)
                    if matched_people
                    else None
                ),
                "anchor_frame_index": idx if matched_people else None,
                "anchor_time_seconds": (
                    float(idx) / float(fps)
                    if matched_people
                    else None
                ),
            }]
            selected = mask.any(axis=-1)
            overlay = frame.copy()
            if bool(selected.any()):
                overlay[selected] = (
                    overlay[selected].astype(np.float32) * 0.45
                    + mask[selected].astype(np.float32) * 0.55
                ).astype(np.uint8)
            from PIL import Image as _PILImage
            preview_image = _PILImage.fromarray(overlay)
    except ValueError as e:
        raise HTTPException(status_code=400, detail=f"Segmentation failed: {e}")
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Segmentation failed: {e}")
    found = matched_people >= person_count
    import base64
    import io as _io

    buf = _io.BytesIO()
    preview_image.save(buf, format="JPEG", quality=85)
    resolution_profile = _normalize_recast_resolution_profile(
        body.get("resolution_profile"),
    )
    reference_canvas = _recast_resolution_for_source(
        frame,
        resolution_profile,
    )
    reference_previews = []
    has_reference = bool(body.get("ref_image_path"))
    if explicit_mappings:
        has_reference = all(
            isinstance(mapping, dict)
            and bool(
                mapping.get("ref_image_path")
                or mapping.get("reference_image_path")
            )
            for mapping in raw_mappings
        )
    if has_reference and found:
        try:
            import tempfile

            resolved_mappings, _ = _normalize_recast_character_mappings(
                request, body, workspace,
            )
            with tempfile.TemporaryDirectory(
                prefix="maestro-recast-preview-",
            ) as preview_dir:
                prepared = _prepare_recast_reference_conditioning(
                    resolved_mappings,
                    mask,
                    preview_dir,
                    "preview",
                    isolate_reference=body.get("isolate_reference") is not False,
                    selected_count=person_count,
                    auto_face_detail=body.get("auto_face_detail") is not False,
                    source_frame=frame,
                    reference_canvas=reference_canvas,
                    mapping_anchors=mapping_anchors,
                )
                reference_previews = prepared["previews"]
        except ValueError as exc:
            raise HTTPException(
                status_code=400,
                detail=f"Reference preview failed: {exc}",
            )
        except Exception as exc:
            raise HTTPException(
                status_code=500,
                detail=f"Reference preview failed: {exc}",
            )
    return {
        "found": found,
        "matched_people": matched_people,
        "requested_people": person_count,
        "frame_index": idx,
        "time_seconds": float(idx) / float(fps),
        "timeline_start_seconds": float(start_index) / float(fps),
        "timeline_end_seconds": float(end_index + 1) / float(fps),
        "sampled_frame_count": int(len(sample_indices)),
        "preview": "data:image/jpeg;base64," + base64.b64encode(buf.getvalue()).decode(),
        "mapping_results": mapping_results,
        "reference_previews": reference_previews,
        "resolution_profile": resolution_profile,
        "output_resolution": list(reference_canvas),
    }


@api.post("/api/v1/recast")
async def recast_endpoint(request: Request):
    """Submit a Recast job: replace a person in an existing video with the
    character from a reference image (SCAIL-2 Replace mode). The colored
    person mask is built automatically with SAM3 keyword tracking as a
    pre-step INSIDE the job thread — tracking a 10s clip takes about a
    minute, so the endpoint returns a job_id immediately and the job's
    message reflects detection progress.

    Body: {
        video_path: str, ref_image_path?: str,
        character_mappings?: [{
            target: str, ref_image_path: str,
            additional_ref_image_paths?: list[str],
        }],
        target?: str ("who to replace" keyword, default "person"),
        person_count?: int (legacy grouped replacement count, 1-5),
        additional_ref_image_paths?: list[str] (legacy same-character views),
        reference_aligned_to_source?: bool (reference is an edited first frame),
        auto_face_detail?: bool (derive a tighter identity view when no
            additional view is supplied; default true),
        protect_bystanders?: bool (strict post-composite; default false),
        preserve_bystanders?: bool (single-reference native multi-person
            identity conditioning; default true),
        isolate_reference?: bool (neutralize unrelated reference background;
            default true),
        enhance_prompt?: bool (rewrite and append identity/scene continuity
            guidance; default false),
        use_relighting?: bool (optional official SCAIL-2 Relighting LoRA;
            default false),
        resolution_profile?: str ("480p", "512p", or "704p"; changes spatial
            resolution and, at 704p, the adaptive window size; never model or
            step schedule),
        prompt?: str (describe the completed video, not an edit command),
        start_time?: float, end_time?: float  (optional trim),
        model_type?: str (default scail2_14B_recast_fast),
        negative_prompt?: str, seed?: int,
        num_inference_steps?: int, guidance_scale?: float,
        activated_loras?: list, loras_multipliers?: str,
        workspace?: str,
    }
    """
    body = await request.json()
    workspace = body.get("workspace") or _get_active_workspace()
    job_out_dir = _require_project_access(request, workspace)

    video_path = _resolve_recast_media(request, body.get("video_path"), workspace)
    if not video_path:
        raise HTTPException(status_code=400, detail=f"Video not found: {body.get('video_path')}")
    try:
        character_mappings, explicit_character_mappings = (
            _normalize_recast_character_mappings(request, body, workspace)
        )
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc))
    ref_image_path = character_mappings[0]["ref_image_path"]
    target = character_mappings[0]["target"]
    person_count = (
        len(character_mappings)
        if explicit_character_mappings
        else _normalize_recast_person_count(body.get("person_count"))
    )
    reference_aligned_to_source = character_mappings[0][
        "reference_aligned_to_source"
    ]
    # Native SCAIL output is the default. Strict pixel lock remains available
    # as an expert fallback, but compositing source pixels over a freshly
    # rendered frame can create visible lighting/color seams.
    protect_bystanders = body.get("protect_bystanders") is True
    # Older saved jobs used ``preserve_scene_reference`` for an experimental
    # full-frame reference. Keep that input as a compatibility alias, but the
    # implementation now builds one neutral group reference containing only
    # the requested replacement and color-mapped people.
    if "preserve_bystanders" in body:
        preserve_bystanders = body.get("preserve_bystanders") is True
    elif "preserve_scene_reference" in body:
        preserve_bystanders = body.get("preserve_scene_reference") is True
    else:
        preserve_bystanders = True
    isolate_reference = body.get("isolate_reference") is not False
    auto_face_detail = body.get("auto_face_detail") is not False
    enhance_prompt = body.get("enhance_prompt") is True
    use_relighting = body.get("use_relighting") is True
    mask_colors = _RECAST_MASK_COLORS[:person_count]
    original_video_path = video_path

    # Optional trim — outpaint's frame-accurate re-encode pattern. The
    # trimmed clip becomes the canonical guide so the SAM3 mask and the
    # generation windows stay 1:1 with the frames actually used.
    trim_start = body.get("start_time")
    trim_end = body.get("end_time")
    if trim_start is not None and trim_end is not None:
        try:
            trim_start_f = float(trim_start)
            trim_end_f = float(trim_end)
            if trim_end_f - trim_start_f > 0.05 and trim_start_f >= 0:
                import subprocess
                trim_dir = os.path.join(os.getcwd(), "uploads")
                os.makedirs(trim_dir, exist_ok=True)
                trimmed_path = os.path.join(trim_dir, f"recast_trim_{uuid.uuid4().hex[:8]}.mp4")
                cmd = [
                    "ffmpeg", "-y", "-i", video_path,
                    "-ss", f"{trim_start_f:.3f}",
                    "-to", f"{trim_end_f:.3f}",
                    "-c:v", "libx264", "-crf", "18", "-preset", "fast",
                    "-c:a", "aac", "-b:a", "192k",
                    trimmed_path,
                ]
                proc = subprocess.run(cmd, capture_output=True, text=True, timeout=180)
                if proc.returncode == 0 and os.path.isfile(trimmed_path):
                    write_upload_access_sidecar(
                        trimmed_path,
                        request.state.maestro_session_id,
                        private=True,
                    )
                    print(f"[Recast] Trimmed source to [{trim_start_f:.2f}s, {trim_end_f:.2f}s] -> {os.path.basename(trimmed_path)}")
                    video_path = trimmed_path
                else:
                    print(f"[Recast] Trim failed (continuing with full clip): {proc.stderr[:200]}")
        except (TypeError, ValueError) as e:
            print(f"[Recast] Invalid trim params: {e}")

    try:
        import decord
        vr = decord.VideoReader(video_path)
        fps = vr.get_avg_fps() or 25
        total_frames = len(vr)
        probe_frame = vr[0].asnumpy()
        del vr
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"Cannot read video: {e}")

    resolution_profile = _normalize_recast_resolution_profile(
        body.get("resolution_profile"),
    )
    recast_width, recast_height = _recast_resolution_for_source(
        probe_frame,
        resolution_profile,
    )
    recast_resolution = f"{recast_width}x{recast_height}"
    print(
        f"[Recast] Resolution profile {resolution_profile} -> "
        f"{recast_resolution}; model and step schedule remain independent."
    )
    recast_vram_gb = 0.0
    try:
        recast_vram_gb = float(
            _get_cached_hardware().get("gpu_vram_gb", 0.0),
        )
    except (TypeError, ValueError, AttributeError):
        recast_vram_gb = 0.0
    recast_window_size = _recast_window_size_for_profile(
        resolution_profile,
        recast_vram_gb,
    )
    if recast_window_size <= 0:
        raise HTTPException(
            status_code=400,
            detail=(
                "704p Recast currently requires at least 16 GB of VRAM. "
                f"Detected {recast_vram_gb:.1f} GB; select 512p or 480p."
            ),
        )
    if resolution_profile == "704p":
        hardware_label = (
            f"{recast_vram_gb:.1f} GB VRAM"
            if recast_vram_gb > 0
            else "unknown VRAM"
        )
        print(
            f"[Recast] Adaptive 704p window: {hardware_label} -> "
            f"{recast_window_size} frames with 5-frame overlap."
        )

    requested_model_type = body.get("model_type") or _RECAST_FAST_MODEL_TYPE
    # Settings saved before the dedicated Recast model existed selected the
    # general I2V-accelerated SCAIL Fast model. Transparently migrate those
    # jobs to the dedicated, corrected native-replacement recipe instead of
    # recreating the incompatible hybrid that caused weak replacements.
    model_type = (
        _RECAST_FAST_MODEL_TYPE
        if requested_model_type == _RECAST_LEGACY_FAST_MODEL_TYPE
        else requested_model_type
    )
    if wgp.get_model_def(model_type) is None:
        raise HTTPException(status_code=400, detail=f"Unknown model: {model_type}")
    recast_fast = model_type == _RECAST_FAST_MODEL_TYPE
    # Both Recast profiles use SCAIL-2's native replacement conditioning.
    # Fast differs only in the official I2V LightX operating point; the base
    # model remains available as the full 40-step comparison.
    recast_conditioning = "native_replace_fast" if recast_fast else "native_replace"
    duration_s = total_frames / fps if fps else 0

    # Cap the follow rate at 30fps (same rationale as the generate guard):
    # a 60fps source doubles frames and windows for no visible gain. wgp
    # resamples the guide (and the SAM3 mask video, which carries the
    # source fps) to the forced integer rate.
    recast_force_fps = "control"
    gen_frames = total_frames
    if fps and float(fps) > 30.5:
        recast_force_fps = "30"
        gen_frames = int(round(duration_s * 30.0))
        print(f"[Recast] fps cap: {float(fps):.6g}fps source → generating at 30fps ({gen_frames} frames)")

    raw_recast_prompt = str(body.get("prompt") or "").strip()
    try:
        prompt = _build_recast_prompt(
            raw_recast_prompt, person_count, enhance=enhance_prompt,
        )
    except ValueError as exc:
        raise HTTPException(status_code=400, detail=str(exc))

    activated_loras, loras_multipliers, use_relighting = (
        _normalize_recast_lora_settings(
            body.get("activated_loras"),
            body.get("loras_multipliers"),
            use_relighting,
        )
    )
    if use_relighting:
        relighting_index = next(
            index
            for index, name in enumerate(activated_loras)
            if str(name).replace("\\", "/").rsplit("/", 1)[-1].casefold()
            == _RECAST_RELIGHTING_LORA_FILENAME.casefold()
        )
        relighting_weight = loras_multipliers.split()[relighting_index]
        print(
            "[Recast] SCAIL-2 Relighting LoRA enabled with single-phase "
            f"weight {relighting_weight}."
        )

    serialized_mappings = [
        {
            "id": mapping["id"],
            "target": mapping["target"],
            "ref_image_path": mapping["ref_image_path"],
            "additional_ref_image_paths": list(
                mapping.get("additional_ref_image_paths", []),
            ),
            "reference_aligned_to_source": mapping[
                "reference_aligned_to_source"
            ],
        }
        for mapping in character_mappings
    ]
    initial_reference_paths = [
        path
        for mapping in character_mappings
        for path in [
            mapping["ref_image_path"],
            *mapping.get("additional_ref_image_paths", []),
        ]
    ]
    inference_steps = _normalize_scail2_inference_steps(
        body.get("num_inference_steps"),
        8 if recast_fast else 40,
    )
    # The Fast LightX recipe is CFG-distilled, but its denoising step count is
    # intentionally user-adjustable for quality/speed experiments.
    guidance_scale = (
        1.0
        if recast_fast
        else _normalize_scail2_guidance_scale(
            body.get("guidance_scale"),
            5.0,
        )
    )
    print(
        f"[Recast] Sampling: {inference_steps} steps, "
        f"guidance {guidance_scale:g} "
        f"({'Fast distilled' if recast_fast else 'HQ'})."
    )

    gen_params = {
        "prompt": prompt,
        "model_type": model_type,
        "negative_prompt": body.get("negative_prompt", ""),
        "seed": body.get("seed", -1),
        "activated_loras": activated_loras,
        "loras_multipliers": loras_multipliers,
        "guidance_scale": guidance_scale,
        "num_inference_steps": inference_steps,
        "flow_shift": 1 if recast_fast else 3,
        "sample_solver": "unipc",
        "generation_mode": "video",
        "edit_sub_mode": "recast",
        # The 0 is SCAIL-2's native Replace 1-5 People flag. The reference is
        # identity conditioning only; it must never become the output canvas.
        "video_prompt_type": f"V0{person_count}AI",
        "image_prompt_type": "",
        "video_guide": video_path,
        # video_mask is filled by the detection pre-step below.
        "image_refs": initial_reference_paths,
        "video_length": gen_frames,
        "_duration_seconds": duration_s,
        "resolution": recast_resolution,
        "force_fps": recast_force_fps,
        "audio_prompt_type": "R",
        "sliding_window_size": recast_window_size,
        "sliding_window_overlap": 5,
        "settings_version": 2.57,
        "custom_settings": {
            "image_ref_keyword_content": "human character",
            "scail2_animate_preprocessing": "raw",
            "scail2_recast_conditioning": "native_replace",
            # The detection pre-step prepares exact RGB/mask pairs.  Runtime
            # isolation stays off so it cannot harden the already-preserved
            # soft alpha edges a second time.
            "scail2_primary_reference_people": 1,
            "scail2_isolate_reference_background": False,
            "scail2_reference_alpha_path": "",
            # Recast gives CLIP the untouched primary image. When isolation is
            # requested, SCAIL-2 also encodes that original through the VAE and
            # retains its latent features inside the semantic subject mask;
            # the neutral reference remains outside the subject.
            "scail2_clip_reference_path": "",
            "scail2_identity_latent_isolation": isolate_reference,
            # Zero keeps the identity-preserving VAE blend on the ordinary
            # primary target reference. Native group preservation moves that
            # target reference to slot one and updates this index accordingly.
            "scail2_identity_latent_reference_index": 0,
            # Generate a disposable reverse-motion pre-roll from the first
            # control/mask frames, then remove it before output assembly.
            "scail2_recast_warmup_frames": _RECAST_WARMUP_FRAMES,
            # Establish identity and scene with all prepared references in
            # window one. Continuations use the primary SCAIL reference plus
            # clean generated overlap to avoid cumulative multi-ref artifacts.
            "scail2_primary_only_continuations": True,
        },
        # UI restore keys for the gallery Edits filter + Load Settings.
        "edit_video_path": original_video_path,
        "edit_start_time": float(trim_start) if trim_start is not None else 0.0,
        "edit_end_time": float(trim_end) if trim_end is not None else duration_s,
        "edit_recast_target": target,
        "edit_recast_person_count": person_count,
        "edit_recast_character_mappings": serialized_mappings,
        "edit_recast_conditioning_people": person_count,
        "edit_recast_ref_path": ref_image_path,
        "edit_recast_ref_aligned": reference_aligned_to_source,
        "edit_recast_isolate_reference": isolate_reference,
        "edit_recast_auto_face_detail": auto_face_detail,
        "edit_recast_enhance_prompt": enhance_prompt,
        "edit_recast_raw_prompt": raw_recast_prompt,
        "edit_recast_protect_bystanders": protect_bystanders,
        "edit_recast_preserve_bystanders": preserve_bystanders,
        "edit_recast_use_relighting": use_relighting,
        "edit_recast_resolution_profile": resolution_profile,
        "edit_recast_output_resolution": [recast_width, recast_height],
        "edit_recast_sliding_window_size": recast_window_size,
        "edit_recast_conditioning": recast_conditioning,
        "edit_recast_warmup_frames": _RECAST_WARMUP_FRAMES,
        # Consumed by _run_generation's deterministic Recast finishing pass.
        "_recast_protect_bystanders": protect_bystanders,
        "_recast_source_video": video_path,
    }

    workspace_name = workspace or _get_active_workspace()
    job_id = uuid.uuid4().hex[:8]
    job = {
        "id": job_id, "status": "queued", "progress": 0, "step": 0, "total_steps": 0,
        "phase": "", "message": "Queued (recast)", "created_at": time.time(),
        "params": gen_params, "output_files": [], "error": None,
        "workspace": workspace_name, "out_dir": job_out_dir,
    }
    initial_probe_frame = probe_frame

    def _run_recast(_job_id):
        abort_state = {"abort": False}
        shot_temp_dir = None
        shot_final_out_dir = None
        # The timeline-aware branch selects a later frame and therefore
        # reassigns ``probe_frame`` below. Initialize the resulting local from
        # the endpoint's decoded first frame before either branch reads it.
        probe_frame = initial_probe_frame
        try:
            # The SAM3 tracking pass is GPU work. Take the generation lock
            # for the detection phase so queued recasts don't run their
            # propagate_in_video passes concurrently with (and on top of)
            # the active job's denoising — user report: several queued
            # recasts all tracked at once and everything crawled. The lock
            # is released before _run_generation, which re-acquires it for
            # the generation phase; a waiting job may slip its detection in
            # between, but everything stays strictly one-GPU-task-at-a-time.
            with generation_slot(_gen_lock, job) as acquired:
                if not acquired:
                    return
                if not try_start(
                    job,
                    generation_lock=_gen_lock,
                    phase="Detecting target",
                    message=f"Finding {person_count} '{target}' subject{'s' if person_count != 1 else ''} in the video...",
                ):
                    return
                if not register_abort_state(
                    job, job_id, _active_gen_states, abort_state,
                ):
                    return
                from shared import magic_mask
                mapped_tracking = None
                mapping_anchors = None
                native_reference_frame_index = 0
                scene_anchor_frame = probe_frame
                scene_anchor_mask = None
                shot_aware_recast_required = False
                cast_transition_count = 0
                if explicit_character_mappings:
                    tracking_progress = {"bucket": -1}

                    def _abort_mapped_tracking():
                        if is_cancel_requested(job):
                            raise InterruptedError(
                                "Recast character tracking was cancelled",
                            )

                    def _mapped_tracking_progress(
                        mapping_index, mapping_total, done, total,
                    ):
                        percent = min(
                            100,
                            max(
                                0,
                                int(round(
                                    100
                                    * (
                                        mapping_index
                                        + float(done) / max(1, total)
                                    )
                                    / max(1, mapping_total)
                                )),
                            ),
                        )
                        bucket = percent // 5
                        if bucket == tracking_progress["bucket"]:
                            return
                        tracking_progress["bucket"] = bucket
                        if not update_job(
                            job,
                            phase="Tracking timeline",
                            message=(
                                "Finding mapped characters across shots... "
                                f"{percent}%"
                            ),
                        ):
                            raise InterruptedError(
                                "Recast character tracking was cancelled",
                            )

                    try:
                        mapped_tracking = _build_recast_character_mask(
                            video_path,
                            character_mappings,
                            os.path.join(os.getcwd(), "uploads"),
                            progress_callback=_mapped_tracking_progress,
                            abort_callback=_abort_mapped_tracking,
                        )
                        _stamp_upload_derivatives(
                            mapped_tracking,
                            job.get("session_id") or request.state.maestro_session_id,
                        )
                    except InterruptedError:
                        return

                    tracking_fps = float(
                        mapped_tracking.get("fps") or fps or 25.0
                    )
                    cast_transition_hold_frames = max(
                        4,
                        min(
                            12,
                            int(round(max(1.0, tracking_fps) * 0.2)),
                        ),
                    )
                    cast_preview = _plan_recast_shot_segments(
                        mapped_tracking["mapping_masks"],
                        mapped_tracking["shot_ranges"],
                        split_cast_transitions=True,
                        min_cast_run_frames=cast_transition_hold_frames,
                    )
                    cast_transition_count = max(
                        0,
                        len(cast_preview) - int(mapped_tracking["shot_count"]),
                    )
                    shot_aware_recast_required = (
                        int(mapped_tracking["shot_count"]) > 1
                        or cast_transition_count > 0
                    )
                    common_index = mapped_tracking["common_frame_index"]
                    scene_index = mapped_tracking["scene_anchor_index"]
                    native_reference_frame_index = (
                        common_index
                        if common_index is not None
                        else scene_index
                    )
                    probe_frame = mapped_tracking["source_frames"][
                        native_reference_frame_index
                    ]
                    probe_mask = mapped_tracking["mask_frames"][
                        native_reference_frame_index
                    ]
                    scene_anchor_frame = mapped_tracking["source_frames"][
                        scene_index
                    ]
                    scene_anchor_mask = mapped_tracking["mask_frames"][
                        scene_index
                    ]
                    mapping_anchors = []
                    for summary in mapped_tracking["mapping_summaries"]:
                        anchor_index = summary["anchor_frame_index"]
                        mapping_anchors.append({
                            "frame_index": anchor_index,
                            "source_frame": mapped_tracking["source_frames"][
                                anchor_index
                            ],
                            "source_mask": mapped_tracking["mask_frames"][
                                anchor_index
                            ],
                        })
                    job["params"]["edit_recast_timeline_anchors"] = [
                        dict(summary)
                        for summary in mapped_tracking["mapping_summaries"]
                    ]
                    job["params"]["edit_recast_recovered_shots"] = [
                        dict(item)
                        for item in mapped_tracking.get(
                            "recovered_shots",
                            [],
                        )
                    ]
                    job["params"]["edit_recast_shot_ranges"] = [
                        list(bounds)
                        for bounds in mapped_tracking["shot_ranges"]
                    ]
                    job["params"]["edit_recast_shot_count"] = (
                        mapped_tracking["shot_count"]
                    )
                    job["params"]["edit_recast_common_frame_index"] = (
                        common_index
                    )
                    job["params"]["edit_recast_timeline_aware"] = (
                        mapped_tracking["timeline_aware"]
                    )
                    job["params"]["edit_recast_cast_transition_count"] = (
                        cast_transition_count
                    )
                    print(
                        "[Recast] Timeline discovery mapped "
                        f"{person_count} character"
                        f"{'s' if person_count != 1 else ''} across "
                        f"{mapped_tracking['shot_count']} shot"
                        f"{'s' if mapped_tracking['shot_count'] != 1 else ''}; "
                        + (
                            f"shared anchor frame={common_index}."
                            if common_index is not None
                            else "no shared frame; using per-character anchors."
                        )
                    )
                    if cast_transition_count:
                        print(
                            "[Recast] Found "
                            f"{cast_transition_count} stable cast change"
                            f"{'s' if cast_transition_count != 1 else ''} "
                            "inside a camera shot; hidden identity pre-rolls "
                            "will initialize late entrants without splitting "
                            "the visible shot."
                        )
                    matched_people = person_count
                else:
                    probe_mask = magic_mask.generate_keyword_masks(
                        probe_frame[None], target, no_hole=True,
                        colorize_objects=True,
                        color_palette=mask_colors,
                        max_colored_objects=person_count,
                    )[0]
                    matched_people = _count_recast_mask_people(
                        probe_mask, mask_colors,
                    )
                    scene_anchor_mask = probe_mask
                if matched_people < person_count:
                    finish_job(
                        job,
                        "failed",
                        error=(
                            f"Found {matched_people} of {person_count} requested "
                            f"'{target}' subjects in the first frame. Try "
                            "another description, lower the person count, or "
                            "adjust the trim start."
                        ),
                        message="Not enough targets found",
                    )
                    return
                native_group_supported = (
                    not explicit_character_mappings
                    or (
                        not shot_aware_recast_required
                        and mapped_tracking["shot_count"] == 1
                        and mapped_tracking["common_frame_index"] is not None
                    )
                )
                map_native_bystanders = (
                    preserve_bystanders
                    and native_group_supported
                    and _recast_probe_needs_bystander_tracking(
                        probe_frame,
                        probe_mask,
                        person_count,
                    )
                )
                job["params"]["edit_recast_bystander_tracking"] = (
                    "full"
                    if map_native_bystanders
                    else (
                        "timeline_scene"
                        if preserve_bystanders and not native_group_supported
                        else "not_needed"
                    )
                )
                if preserve_bystanders and not map_native_bystanders:
                    if not native_group_supported:
                        print(
                            "[Recast] Multi-shot/separate-appearance mapping "
                            "will preserve surrounding people with per-window "
                            "source-scene anchors instead of one contradictory "
                            "group reference."
                        )
                    else:
                        print(
                            "[Recast] Anchor-frame probe found no additional "
                            "bystanders; skipping the second full SAM3 pass."
                        )
                if is_cancel_requested(job):
                    return
                if not update_job(
                    job,
                    phase="Preparing references",
                    message="Preparing exact SCAIL-2 reference crops and masks...",
                ):
                    return
                prepared_refs = _prepare_recast_reference_conditioning(
                    character_mappings,
                    probe_mask,
                    os.path.join(os.getcwd(), "uploads"),
                    job_id,
                    isolate_reference=isolate_reference,
                    selected_count=person_count,
                    auto_face_detail=auto_face_detail,
                    source_frame=probe_frame,
                    reference_canvas=(recast_width, recast_height),
                    mapping_anchors=mapping_anchors,
                )
                _stamp_upload_derivatives(
                    prepared_refs,
                    job.get("session_id") or request.state.maestro_session_id,
                )
                job["params"]["image_refs"] = prepared_refs["image_refs"]
                job["params"]["custom_settings"][
                    "scail2_reference_mask_path"
                ] = prepared_refs["primary_mask"]
                job["params"]["custom_settings"][
                    "scail2_additional_reference_mask_paths"
                ] = prepared_refs["additional_masks"]
                job["params"]["custom_settings"][
                    "scail2_reference_expected_colors"
                ] = prepared_refs["expected_colors"]
                job["params"]["custom_settings"][
                    "scail2_clip_reference_path"
                ] = prepared_refs["clip_identity_ref"]
                target_group_reference = None
                if explicit_character_mappings and person_count > 1:
                    target_group_reference = (
                        _build_recast_target_group_reference(
                            prepared_refs,
                            os.path.join(os.getcwd(), "uploads"),
                            job_id,
                            person_count,
                            shared_source_frame=(
                                probe_frame
                                if common_index is not None
                                else None
                            ),
                            shared_semantic_mask=(
                                probe_mask
                                if common_index is not None
                                else None
                            ),
                        )
                    )
                    _stamp_upload_derivatives(
                        target_group_reference,
                        job.get("session_id") or request.state.maestro_session_id,
                    )
                    # SCAIL-2 was trained to map several semantic colors from
                    # one primary multi-person reference. Keep the individual
                    # full/detail views as supporting evidence rather than
                    # asking the experimental multi-reference path to decide
                    # which unrelated identity owns each color.
                    job["params"]["image_refs"] = [
                        target_group_reference["image"],
                        *prepared_refs["image_refs"],
                    ]
                    job["params"]["custom_settings"][
                        "scail2_reference_mask_path"
                    ] = target_group_reference["mask"]
                    job["params"]["custom_settings"][
                        "scail2_additional_reference_mask_paths"
                    ] = [
                        prepared_refs["primary_mask"],
                        *prepared_refs["additional_masks"],
                    ]
                    job["params"]["custom_settings"][
                        "scail2_reference_expected_colors"
                    ] = [
                        None,
                        *prepared_refs["expected_colors"],
                    ]
                    job["params"]["custom_settings"][
                        "scail2_primary_reference_people"
                    ] = person_count
                    job["params"]["custom_settings"][
                        "scail2_identity_latent_reference_index"
                    ] = 1
                    job["params"]["edit_recast_cast_reference"] = (
                        target_group_reference["image"]
                    )
                    job["params"]["edit_recast_cast_mask"] = (
                        target_group_reference["mask"]
                    )
                    job["params"]["edit_recast_cast_mode"] = (
                        target_group_reference["mode"]
                    )
                    job["params"]["edit_recast_conditioning_people"] = (
                        person_count
                    )
                    print(
                        "[Recast] Built one native color-mapped cast "
                        f"reference for {person_count} characters "
                        f"({target_group_reference['mode']})."
                    )
                job["params"]["edit_recast_prepared_refs"] = list(
                    prepared_refs["image_refs"],
                )
                job["params"]["edit_recast_clip_identity_ref"] = (
                    prepared_refs["clip_identity_ref"]
                )
                job["params"]["edit_recast_auto_face_detail_refs"] = list(
                    prepared_refs["auto_face_detail_refs"],
                )
                job["params"]["edit_recast_reference_canvas"] = list(
                    prepared_refs["reference_canvas"],
                )
                source_scene_reference = None

                def _ensure_source_scene_reference(reason):
                    nonlocal source_scene_reference
                    if source_scene_reference is not None:
                        return source_scene_reference
                    source_scene_reference = (
                        _enable_recast_dynamic_source_scene_reference(
                            job["params"],
                            scene_anchor_frame,
                            scene_anchor_mask,
                            person_count,
                            os.path.join(os.getcwd(), "uploads"),
                            job_id,
                        )
                    )
                    _stamp_upload_derivatives(
                        source_scene_reference,
                        job.get("session_id") or request.state.maestro_session_id,
                    )
                    job["params"][
                        "edit_recast_source_scene_reference_reason"
                    ] = reason
                    if (
                        explicit_character_mappings
                        and mapped_tracking["timeline_aware"]
                    ):
                        job["params"]["custom_settings"][
                            "scail2_timeline_source_scene_reference"
                        ] = True
                        job["params"][
                            "edit_recast_source_scene_conditioning"
                        ] = "per_window_timeline_reference"
                    print(
                        "[Recast] Enabled source-scene anchoring "
                        f"({reason}; hidden="
                        f"{source_scene_reference['hidden_fraction']:.1%}, "
                        f"margin={source_scene_reference['expansion_pixels']}px)."
                    )
                    return source_scene_reference

                print(
                    "[Recast] Prepared "
                    f"{len(prepared_refs['image_refs'])} exact reference "
                    "view(s) with paired semantic masks and an identity-first "
                    "primary VAE/CLIP image"
                    + (
                        f", including {len(prepared_refs['auto_face_detail_refs'])} "
                        "automatic face-detail view(s)."
                        if prepared_refs["auto_face_detail_refs"]
                        else "."
                    )
                )
                if explicit_character_mappings:
                    mask_path = mapped_tracking["video_mask"]
                else:
                    if not update_job(
                        job,
                        phase="Tracking targets",
                        message=(
                            f"Tracking '{target}' across "
                            f"{total_frames} frames..."
                        ),
                    ):
                        return
                    mask_path, _ = magic_mask.generate_video_mask(
                        video_path, target,
                        colorize_objects=True,
                        color_palette=mask_colors,
                        max_colored_objects=person_count,
                        background_color=(255, 255, 255),
                        output_dir=os.path.join(os.getcwd(), "uploads"),
                    )
                    _stamp_upload_derivatives(
                        mask_path,
                        job.get("session_id") or request.state.maestro_session_id,
                    )
                if is_cancel_requested(job):
                    return
                job["params"]["video_mask"] = mask_path
                if not map_native_bystanders:
                    _ensure_source_scene_reference(
                        "no separate bystander pass needed",
                    )
                if map_native_bystanders:
                    if not update_job(
                        job,
                        message="Mapping the other people for native preservation...",
                        phase="Mapping surrounding people",
                    ):
                        return

                    mapping_progress = {"bucket": -1}

                    def _native_people_progress(done, total):
                        percent = min(
                            100,
                            max(0, int(round(100 * float(done) / max(1, total)))),
                        )
                        bucket = percent // 5
                        if bucket == mapping_progress["bucket"]:
                            return
                        mapping_progress["bucket"] = bucket
                        if not update_job(
                            job,
                            message=f"Mapping the other people... {percent}%",
                            phase="Mapping surrounding people",
                        ):
                            raise InterruptedError("Recast bystander mapping was cancelled")

                    try:
                        native_people = _build_recast_native_people_conditioning(
                            video_path,
                            mask_path,
                            person_count,
                            os.path.join(os.getcwd(), "uploads"),
                            job_id,
                            target_references=prepared_refs[
                                "primary_target_refs"
                            ],
                            progress_callback=_native_people_progress,
                            reference_frame_index=(
                                native_reference_frame_index
                            ),
                        )
                        _stamp_upload_derivatives(
                            native_people,
                            job.get("session_id") or request.state.maestro_session_id,
                        )
                    except InterruptedError:
                        return
                    except Exception as native_error:
                        # Native preservation is an enhancement. If broad
                        # person mapping is ambiguous, retain the known-good
                        # target-only Recast instead of failing the whole job.
                        print(
                            "[Recast] Native bystander conditioning unavailable; "
                            f"continuing target-only: {native_error}"
                        )
                        traceback.print_exc()
                        _ensure_source_scene_reference(
                            "native bystander mapping unavailable",
                        )
                    else:
                        if is_cancel_requested(job):
                            return
                        if native_people["reference_image"]:
                            job["params"]["video_mask"] = native_people["video_mask"]
                            target_image_refs = list(
                                prepared_refs["image_refs"],
                            )
                            target_mask_paths = [
                                prepared_refs["primary_mask"],
                                *prepared_refs["additional_masks"],
                            ]
                            target_expected_colors = list(
                                prepared_refs["expected_colors"],
                            )
                            # The color-mapped group is now the primary
                            # reference adjacent to the video timeline. Large
                            # target and face-detail views remain as supporting
                            # references, so bystander identity no longer
                            # arrives through a contradictory target-free frame.
                            job["params"]["image_refs"] = [
                                native_people["reference_image"],
                                *target_image_refs,
                            ]
                            job["params"]["custom_settings"][
                                "scail2_reference_mask_path"
                            ] = native_people["reference_mask"]
                            job["params"]["custom_settings"][
                                "scail2_additional_reference_mask_paths"
                            ] = target_mask_paths
                            job["params"]["custom_settings"][
                                "scail2_reference_expected_colors"
                            ] = [None, *target_expected_colors]
                            job["params"]["custom_settings"][
                                "scail2_primary_reference_people"
                            ] = native_people["conditioning_count"]
                            job["params"]["custom_settings"][
                                "scail2_identity_latent_reference_index"
                            ] = 1
                            job["params"]["video_prompt_type"] = (
                                f"V0{native_people['conditioning_count']}AI"
                            )
                            job["params"]["edit_recast_conditioning_people"] = (
                                native_people["conditioning_count"]
                            )
                            job["params"]["edit_recast_group_reference"] = (
                                native_people["reference_image"]
                            )
                            job["params"]["edit_recast_group_mask"] = (
                                native_people["reference_mask"]
                            )
                            print(
                                "[Recast] Native group conditioning mapped "
                                f"{native_people['conditioning_count']} people "
                                f"(targets={person_count}, "
                                f"bystanders={len(native_people['assignments'])})"
                            )
                        else:
                            _ensure_source_scene_reference(
                                "no additional bystanders survived full tracking",
                            )
                            print(
                                "[Recast] No additional visible bystanders fit "
                                "the native five-person conditioning limit."
                            )

                if (
                    explicit_character_mappings
                    and shot_aware_recast_required
                ):
                    if not update_job(
                        job,
                        phase="Preparing cast-aware segments",
                        message=(
                            "Preparing shot and cast-specific character "
                            "references..."
                        ),
                    ):
                        return
                    import secrets
                    import shutil
                    import tempfile

                    try:
                        resolved_seed = int(job["params"].get("seed", -1))
                    except (TypeError, ValueError):
                        resolved_seed = -1
                    if resolved_seed < 0:
                        resolved_seed = secrets.randbelow(1_000_000_000)
                    job["params"]["seed"] = resolved_seed

                    generation_fps = (
                        30.0
                        if recast_force_fps == "30"
                        else float(mapped_tracking.get("fps") or fps or 25.0)
                    )
                    try:
                        minimum_frames, _frame_step, latent_size = (
                            wgp.get_model_min_frames_and_step(model_type)
                        )
                    except Exception:
                        minimum_frames, latent_size = 5, 4

                    shot_temp_dir = tempfile.mkdtemp(
                        prefix="maestro-recast-shots-",
                    )
                    try:
                        shot_manifest = _build_recast_shot_manifest(
                            job["params"],
                            mapped_tracking,
                            prepared_refs,
                            shot_temp_dir,
                            job_id,
                            reference_canvas=(
                                recast_width,
                                recast_height,
                            ),
                            target_frame_count=gen_frames,
                            generation_fps=generation_fps,
                            minimum_frames=minimum_frames,
                            latent_size=latent_size,
                        )
                    except Exception:
                        shutil.rmtree(
                            shot_temp_dir,
                            ignore_errors=True,
                        )
                        raise

                    final_out_dir = job.get("out_dir") or _workspace_dir(
                        workspace_name,
                    )
                    shot_final_out_dir = final_out_dir
                    job["params"].update({
                        "_defer_output_publication": True,
                        "_recast_shot_manifest": shot_manifest["tasks"],
                        "_recast_shot_temp_dir": shot_temp_dir,
                        "_recast_final_out_dir": final_out_dir,
                        "_recast_shot_bundle": {
                            "shots": shot_manifest["shots"],
                            "published_shots": shot_manifest[
                                "published_shots"
                            ],
                            "frame_count": shot_manifest["frame_count"],
                            "fps": shot_manifest["fps"],
                            "camera_shot_count": shot_manifest[
                                "camera_shot_count"
                            ],
                            "cast_transition_count": shot_manifest[
                                "cast_transition_count"
                            ],
                            "resolved_seed": resolved_seed,
                        },
                        "edit_recast_shot_aware": True,
                        "edit_recast_shot_plan": shot_manifest[
                            "published_shots"
                        ],
                    })
                    if job["params"].get("_recast_protect_bystanders"):
                        print(
                            "[Recast] Strict pixel-lock fallback is disabled "
                            "for shot-aware generation; native shot references "
                            "preserve the surrounding scene."
                        )
                        job["params"]["_recast_protect_bystanders"] = False
                    # Generated shots and their references are disposable.
                    # Point the normal task engine at the private directory;
                    # the finishing worker publishes only the final join.
                    job["out_dir"] = shot_temp_dir
                    generated_count = len(shot_manifest["tasks"])
                    passthrough_count = sum(
                        1
                        for shot in shot_manifest["shots"]
                        if shot["mode"] == "passthrough"
                    )
                    print(
                        "[Recast] Shot-aware plan prepared "
                        f"{len(shot_manifest['shots'])} generation segments "
                        f"from {shot_manifest['camera_shot_count']} camera "
                        "shot"
                        f"{'s' if shot_manifest['camera_shot_count'] != 1 else ''} "
                        f"with {shot_manifest['cast_transition_count']} stable "
                        "cast transition"
                        f"{'s' if shot_manifest['cast_transition_count'] != 1 else ''} "
                        f"({generated_count} generated, "
                        f"{passthrough_count} source passthrough), "
                        f"{shot_manifest['frame_count']} exact output frames "
                        f"at {shot_manifest['fps']:.6g}fps."
                    )
        except Exception as e:
            traceback.print_exc()
            if shot_temp_dir and os.path.isdir(shot_temp_dir):
                import shutil

                shutil.rmtree(shot_temp_dir, ignore_errors=True)
                if shot_final_out_dir:
                    job["out_dir"] = shot_final_out_dir
            finish_job(
                job,
                "failed",
                error=f"Target detection failed: {e}",
                message="Detection failed",
            )
            return
        finally:
            if abort_state is not None:
                unregister_abort_state(job_id, _active_gen_states, abort_state)

        if not try_requeue(job, message="Queued (recast)", phase=""):
            if shot_temp_dir and os.path.isdir(shot_temp_dir):
                import shutil

                shutil.rmtree(shot_temp_dir, ignore_errors=True)
                if shot_final_out_dir:
                    job["out_dir"] = shot_final_out_dir
            return
        if job["params"].get("_recast_shot_manifest"):
            _run_recast_shot_generation(job_id)
        else:
            _run_generation(job_id)

    _queue_recovery_register_and_publish(
        job,
        worker=_run_recast,
        recovery_kind="studio_recast_preparation",
        thread_name=f"studio-recast-{job_id}",
    )

    return {
        "job_id": job_id,
        "status": "queued",
        "frames": total_frames,
        "target": target,
        "person_count": person_count,
        "resolution_profile": resolution_profile,
        "resolution": recast_resolution,
        "sliding_window_size": recast_window_size,
        "num_inference_steps": inference_steps,
        "guidance_scale": guidance_scale,
    }


def _resolve_outpaint_sampling(
    body, base_model_type, model_def, model_defaults,
):
    """Resolve model-aware Outpaint steps and guidance.

    Outpaint used to omit the Studio Advanced values and independently fall
    back to 8 steps. That is valid for distilled LTX-2, but LTXV 13B Dev
    rejects fewer than 20 steps. Use each model's own defaults, honor locked
    schedules, and reject invalid API input before it reaches the queue.
    """
    model_def = model_def if isinstance(model_def, dict) else {}
    model_defaults = (
        model_defaults if isinstance(model_defaults, dict) else {}
    )
    default_steps = (
        model_def.get("num_inference_steps")
        or model_defaults.get("num_inference_steps")
        or 8
    )
    default_guidance = (
        model_def.get("guidance_scale")
        or model_defaults.get("guidance_scale")
        or 1.0
    )

    try:
        default_steps = int(default_steps)
        default_guidance = float(default_guidance)
        if model_def.get("lock_inference_steps", False):
            inference_steps = default_steps
        else:
            inference_steps = int(
                body.get("num_inference_steps", default_steps)
            )
        if model_def.get("lock_guidance_scale", False):
            guidance_scale = default_guidance
        else:
            guidance_scale = float(
                body.get("guidance_scale", default_guidance)
            )
    except (TypeError, ValueError) as error:
        raise ValueError(
            "Inference Steps and Guidance Scale must be numeric."
        ) from error

    if inference_steps <= 0:
        raise ValueError("Inference Steps must be greater than zero.")
    if (
        base_model_type == "ltxv_13B"
        and not model_def.get("lock_inference_steps", False)
        and inference_steps < 20
    ):
        raise ValueError(
            "LTX Video 13B requires at least 20 inference steps."
        )
    return inference_steps, guidance_scale


def _resolve_outpaint_video_timing(
    source_frames,
    source_fps,
    model_def,
    reference_fps=None,
):
    """Resolve Outpaint duration, FPS, and the model's 8n+1 frame grid.

    The short-form Diffusers LTX-2.3 Outpaint demo resamples every source to
    24 fps.  ``reference_fps`` remains available for reproducing that narrow
    demo contract and rounds *up* to the next complete latent group so the
    source tail is not discarded. Maestro's production video path omits it:
    preserving source timing produced materially better long-form continuity
    and lets the normal sliding-window path carry clips beyond one window.
    """
    model_def = model_def if isinstance(model_def, dict) else {}
    try:
        fallback_fps = float(model_def.get("fps") or 25)
    except (TypeError, ValueError):
        fallback_fps = 25.0
    if not math.isfinite(fallback_fps) or fallback_fps <= 0:
        fallback_fps = 25.0

    try:
        source_frame_count = max(1, int(source_frames))
    except (TypeError, ValueError):
        source_frame_count = 1
    try:
        source_rate = float(source_fps)
    except (TypeError, ValueError):
        source_rate = fallback_fps
    if not math.isfinite(source_rate) or source_rate <= 0:
        source_rate = fallback_fps
    uses_reference_rate = reference_fps is not None
    if uses_reference_rate:
        try:
            target_fps = float(reference_fps)
        except (TypeError, ValueError):
            target_fps = 24.0
        if not math.isfinite(target_fps) or target_fps <= 0:
            target_fps = 24.0
    else:
        target_fps = source_rate

    duration = source_frame_count / source_rate
    try:
        minimum_frames = max(
            1,
            int(model_def.get("frames_minimum") or 1),
        )
    except (TypeError, ValueError):
        minimum_frames = 1
    try:
        frame_step = max(
            1,
            int(
                model_def.get("latent_size")
                or model_def.get("frames_steps")
                or 1
            ),
        )
    except (TypeError, ValueError):
        frame_step = 1

    nominal_frames = max(
        float(minimum_frames),
        (
            duration * target_fps
            if uses_reference_rate
            else float(source_frame_count)
        ),
    )
    if uses_reference_rate:
        # The reference loader clamps samples past EOF to the final source
        # frame.  Preserve that behavior instead of dropping up to seven
        # source frames when converting to LTX's causal temporal grid.
        latent_steps = max(
            0,
            int(math.ceil((nominal_frames - 1) / frame_step)),
        )
    else:
        latent_steps = max(
            0,
            int((nominal_frames - 1) // frame_step),
        )
    target_frames = max(
        minimum_frames,
        latent_steps * frame_step + 1,
    )
    return duration, target_fps, target_frames


def _resolve_ltx2_outpaint_reference_model(requested_model_type):
    """Select the best locally available model for official Outpaint.

    Lightricks' published two-stage graph uses the LTX-2.3 Dev transformer
    with the Distilled 1.1 LoRA at 0.5.  Keep an explicitly selected Dev
    model.  When the UI supplied a baked-Distilled model, prefer a compatible
    Dev checkpoint only when it is already installed; otherwise retain the
    requested model as a no-download compatibility fallback.
    """

    from urllib.parse import unquote, urlparse
    from shared.utils import files_locator as fl

    requested_def = wgp.get_model_def(requested_model_type) or {}
    requested_is_dev = bool(
        requested_def.get("architecture") == "ltx2_22B"
        and requested_def.get("ltx2_pipeline", "two_stage")
        != "distilled"
    )
    if requested_is_dev:
        return requested_model_type

    requested_lower = str(requested_model_type or "").lower()
    dev_candidates = (
        ("ltx2_22B_fp8", "ltx2_22B_1_1", "ltx2_22B")
        if "fp8" in requested_lower
        else ("ltx2_22B_1_1", "ltx2_22B_fp8", "ltx2_22B")
    )
    seen = set()
    for candidate in dev_candidates:
        if not candidate or candidate in seen:
            continue
        seen.add(candidate)
        candidate_def = wgp.get_model_def(candidate) or {}
        if (
            candidate_def.get("architecture") != "ltx2_22B"
            or candidate_def.get("ltx2_pipeline", "two_stage")
            == "distilled"
        ):
            continue
        urls = wgp.get_model_recursive_prop(
            candidate,
            "URLs",
            return_list=True,
        )
        for url in urls or []:
            filename = os.path.basename(
                unquote(urlparse(str(url)).path)
            )
            if (
                filename
                and fl.locate_file(filename, error_if_none=False)
                is not None
            ):
                return candidate
    return requested_model_type


_OUTPAINT_PIXEL_BUDGETS = {
    "480p": 480 * 848,
    "540p": 540 * 960,
    "720p": 720 * 1280,
    "1080p": 1088 * 1920,
}

# A 257-frame 704x1280 two-stage Outpaint is the largest composition verified
# to fit a 24 GB card with Maestro's normal streaming profile.
# Keep larger canvases within the same approximate pixel-frame activation
# budget by shortening each diffusion window. This affects peak VRAM, not the
# total clip length; the existing sliding-window path covers the remainder.
_OUTPAINT_SINGLE_STAGE_REFERENCE_PIXELS = 704 * 1280
_OUTPAINT_SINGLE_STAGE_REFERENCE_FRAMES = 257


def _cap_outpaint_single_stage_window(
    requested_frames,
    target_width,
    target_height,
    window_min=17,
    window_max=501,
):
    requested_frames = max(1, int(requested_frames))
    target_pixels = max(1, int(target_width) * int(target_height))
    window_min = max(1, int(window_min))
    window_max = max(window_min, int(window_max))
    capped = max(window_min, min(window_max, requested_frames))
    if target_pixels <= _OUTPAINT_SINGLE_STAGE_REFERENCE_PIXELS:
        return capped

    pixel_frame_budget = (
        _OUTPAINT_SINGLE_STAGE_REFERENCE_PIXELS
        * _OUTPAINT_SINGLE_STAGE_REFERENCE_FRAMES
    )
    safe_frames = max(window_min, int(pixel_frame_budget / target_pixels))
    # LTX-2's causal temporal grid is 1 + 8k frames. Keeping the window on
    # that grid prevents downstream rounding from increasing it again.
    safe_frames = 1 + max(0, (safe_frames - 1) // 8) * 8
    safe_frames = max(window_min, min(window_max, safe_frames))
    return min(capped, safe_frames)


def _resolve_outpaint_canvas_geometry(
    src_w,
    src_h,
    pad_top,
    pad_bottom,
    pad_left,
    pad_right,
    resolution_preset="auto",
    alignment=64,
):
    """Resolve one grid-aligned Outpaint canvas and protected source rect.

    LTX-2's VAE works on a 64-pixel spatial grid. Previously the endpoint
    computed padding against an arbitrary target (for example 896x1593)
    and wgp silently floored that target later (to 896x1536). The model and
    source-overlay coordinates consequently described different canvases.

    Scale the complete composition uniformly, snap the final canvas once,
    then derive fractional padding percentages from that exact canvas.
    """
    src_w = max(1, int(src_w))
    src_h = max(1, int(src_h))
    pad_top = max(0, int(pad_top))
    pad_bottom = max(0, int(pad_bottom))
    pad_left = max(0, int(pad_left))
    pad_right = max(0, int(pad_right))
    alignment = max(1, int(alignment))

    composed_w = src_w + pad_left + pad_right
    composed_h = src_h + pad_top + pad_bottom
    target_w = float(composed_w)
    target_h = float(composed_h)
    preset = str(resolution_preset or "auto").lower()
    if preset in _OUTPAINT_PIXEL_BUDGETS:
        scale = (
            _OUTPAINT_PIXEL_BUDGETS[preset]
            / max(1.0, target_w * target_h)
        ) ** 0.5
        target_w *= scale
        target_h *= scale

    def _align(value):
        return max(
            alignment,
            int(math.floor((float(value) / alignment) + 0.5))
            * alignment,
        )

    final_w = _align(target_w)
    final_h = _align(target_h)

    # Uniformly fit the requested composition into the aligned canvas. Any
    # few grid-rounding pixels left over are centered around the composition,
    # preserving both the source aspect and the user's source placement.
    scale = min(
        final_w / max(1.0, float(composed_w)),
        final_h / max(1.0, float(composed_h)),
    )
    fitted_w = composed_w * scale
    fitted_h = composed_h * scale
    composition_x = (final_w - fitted_w) / 2.0
    composition_y = (final_h - fitted_h) / 2.0
    overlay_x = int(round(composition_x + pad_left * scale))
    overlay_y = int(round(composition_y + pad_top * scale))
    overlay_w = max(1, int(round(src_w * scale)))
    overlay_h = max(1, int(round(src_h * scale)))
    overlay_x = max(0, min(overlay_x, final_w - overlay_w))
    overlay_y = max(0, min(overlay_y, final_h - overlay_h))

    resolved_left = overlay_x
    resolved_top = overlay_y
    resolved_right = max(0, final_w - overlay_x - overlay_w)
    resolved_bottom = max(0, final_h - overlay_y - overlay_h)
    dims = (
        100.0 * resolved_top / overlay_h,
        100.0 * resolved_bottom / overlay_h,
        100.0 * resolved_left / overlay_w,
        100.0 * resolved_right / overlay_w,
    )

    # Re-resolve through the same helper inference uses. These coordinates
    # are retained for legacy overlay metadata and make any float rounding
    # difference observable instead of allowing two geometries to diverge.
    from shared.utils.utils import get_outpainting_frame_location

    (
        model_overlay_h,
        model_overlay_w,
        model_overlay_y,
        model_overlay_x,
    ) = get_outpainting_frame_location(
        final_h,
        final_w,
        list(dims),
        1,
    )
    return {
        "final_w": final_w,
        "final_h": final_h,
        "dims": dims,
        "overlay_w": int(model_overlay_w),
        "overlay_h": int(model_overlay_h),
        "overlay_x": int(model_overlay_x),
        "overlay_y": int(model_overlay_y),
        "requested_w": composed_w,
        "requested_h": composed_h,
    }


def _format_outpaint_percentage(value):
    text = f"{float(value):.8f}".rstrip("0").rstrip(".")
    return text or "0"


def _detect_outpaint_video_shot_ranges(
    source_video, target_frame_count, *, abort_callback=None,
    min_shot_frames=4, absolute_cut_threshold=0.12,
):
    """Stream a video into tiny thumbnails and return hard-cut ranges.

    Outpaint only needs camera-cut boundaries, not the full-resolution frame
    tensor that Recast keeps for SAM tracking. Retaining 64x36 RGB thumbnails
    bounds memory while deliberately reusing Recast's proven adaptive cut
    scoring. ``target_frame_count`` matches the exact timeline LTX will
    generate; any source tail outside its causal 8n+1 grid is ignored just as
    it is by the ordinary continuous Outpaint path.
    """
    import cv2
    import numpy as np

    frame_limit = max(1, int(target_frame_count))
    capture = cv2.VideoCapture(str(source_video))
    if not capture.isOpened():
        capture.release()
        raise ValueError(
            f"Outpaint could not open the source video: {source_video}"
        )

    thumbnails = []
    try:
        while len(thumbnails) < frame_limit:
            if abort_callback is not None:
                abort_callback()
            ok, frame = capture.read()
            if not ok or frame is None:
                break
            thumbnail = cv2.resize(
                frame,
                (64, 36),
                interpolation=cv2.INTER_AREA,
            )
            thumbnails.append(cv2.cvtColor(thumbnail, cv2.COLOR_BGR2RGB))
    finally:
        capture.release()

    decoded_count = len(thumbnails)
    if decoded_count <= 0:
        raise ValueError("Outpaint source video contains no decodable frames.")
    if decoded_count < frame_limit:
        raise ValueError(
            "Outpaint source ended before its planned timeline "
            f"({decoded_count}/{frame_limit} frames)."
        )

    return _detect_recast_shot_ranges(
        np.stack(thumbnails),
        min_shot_frames=min_shot_frames,
        absolute_cut_threshold=absolute_cut_threshold,
    )


def _build_outpaint_shot_filter(
    start_frame, end_frame, pad_frames, fps,
):
    """Build an exact-frame, CFR filter for one lossless internal guide."""
    start = int(start_frame)
    end = int(end_frame)
    padding = max(0, int(pad_frames))
    rate = float(fps)
    if start < 0 or end <= start:
        raise ValueError("Outpaint shot frame bounds are invalid.")
    if not math.isfinite(rate) or rate <= 0:
        raise ValueError("Outpaint shot FPS must be positive.")
    rate_text = f"{rate:.12g}"
    return (
        f"trim=start_frame={start}:end_frame={end},"
        f"setpts=N/({rate_text}*TB),"
        f"tpad=stop_mode=clone:stop={padding}"
    )


def _write_outpaint_shot_guide(
    source_video, output_path, *, start_frame, end_frame, pad_frames,
    fps, abort_callback=None,
):
    """Write one frame-exact, lossless H.264 guide without loading it whole."""
    import subprocess

    if abort_callback is not None:
        abort_callback()
    os.makedirs(os.path.dirname(os.path.abspath(output_path)), exist_ok=True)
    filter_graph = _build_outpaint_shot_filter(
        start_frame,
        end_frame,
        pad_frames,
        fps,
    )
    ffmpeg_bin = os.environ.get("FFMPEG_BINARY", "ffmpeg")
    expected_frames = (
        int(end_frame) - int(start_frame) + max(0, int(pad_frames))
    )
    timeout = max(
        120,
        min(900, int(math.ceil(expected_frames / float(fps) * 10.0))),
    )
    command = [
        ffmpeg_bin,
        "-y",
        "-v",
        "error",
        "-i",
        str(source_video),
        "-map",
        "0:v:0",
        "-vf",
        filter_graph,
        "-an",
        "-map_metadata",
        "0",
        # The generated margins are color-sensitive. CRF 0 prevents an
        # intermediate guide encode from softening or shifting the protected
        # source before the IC-LoRA sees it.
        "-c:v",
        "libx264",
        "-crf",
        "0",
        "-preset",
        "fast",
        "-pix_fmt",
        "yuv420p",
        "-movflags",
        "+faststart",
        str(output_path),
    ]
    completed = subprocess.run(
        command,
        capture_output=True,
        text=True,
        timeout=timeout,
    )
    if abort_callback is not None:
        abort_callback()
    if completed.returncode != 0 or not os.path.isfile(output_path):
        if os.path.isfile(output_path):
            try:
                os.remove(output_path)
            except OSError:
                pass
        detail = (completed.stderr or "unknown ffmpeg error").strip()
        raise RuntimeError(
            "Could not prepare Outpaint camera shot: " + detail[:500]
        )

    actual_frames = _recast_video_frame_count(output_path)
    if actual_frames != expected_frames:
        try:
            os.remove(output_path)
        except OSError:
            pass
        raise RuntimeError(
            "Outpaint camera-shot guide changed timeline length "
            f"({actual_frames}/{expected_frames} frames)."
        )
    return output_path


def _build_outpaint_shot_manifest(
    base_params, source_video, shot_ranges, output_dir, job_id, *,
    target_frame_count, generation_fps, minimum_frames, latent_size,
    guide_writer=None, progress_callback=None, abort_callback=None,
):
    """Create exact-length official Outpaint tasks for every camera shot."""
    target_count = int(target_frame_count)
    if target_count <= 0:
        raise ValueError("Outpaint target timeline must contain frames.")
    ranges = [
        (int(bounds[0]), int(bounds[1]))
        for bounds in (shot_ranges or [])
    ]
    if not ranges:
        ranges = [(0, target_count)]
    cursor = 0
    for start, end in ranges:
        if start != cursor or end <= start or end > target_count:
            raise ValueError(
                "Outpaint camera shots must cover one contiguous timeline."
            )
        cursor = end
    if cursor != target_count:
        raise ValueError(
            "Outpaint camera shots do not cover the complete timeline."
        )

    writer = guide_writer or _write_outpaint_shot_guide
    os.makedirs(output_dir, exist_ok=True)
    tasks = []
    plans = []
    total_shots = len(ranges)
    for shot_index, (start, end) in enumerate(ranges):
        if abort_callback is not None:
            abort_callback()
        if progress_callback is not None:
            progress_callback(shot_index, total_shots)
        exact_frames = end - start
        generated_frames, trim_tail = _quantize_recast_shot_frame_count(
            exact_frames,
            minimum_frames,
            latent_size,
        )
        guide_path = os.path.join(
            output_dir,
            f"outpaint_{job_id}_shot_{shot_index + 1}_guide.mp4",
        )
        writer(
            source_video,
            guide_path,
            start_frame=start,
            end_frame=end,
            pad_frames=trim_tail,
            fps=generation_fps,
            abort_callback=abort_callback,
        )
        tasks.append({
            "shot_index": shot_index,
            "params": {
                "video_guide": guide_path,
                "video_length": generated_frames,
                "trim_tail_frames": trim_tail,
                "video_prompt_type": "VG",
                "image_prompt_type": "",
                "force_fps": "control",
                # Internal shots never replace their audio or perform the
                # continuous-path smear trim. One source track is attached
                # only after exact-frame assembly.
                "audio_prompt_type": "",
                "audio_guide": None,
                "audio_source": None,
                "_outpaint_preserve_audio": False,
                "_outpaint_source_video": None,
                "_outpaint_lock_source_pixels": False,
                "_outpaint_trim_smear": False,
                "output_filename": (
                    f"outpaint_{job_id}_shot_{shot_index + 1}.mp4"
                ),
            },
        })
        plans.append({
            "shot_index": shot_index,
            "start_frame": start,
            "end_frame": end,
            "frame_count": exact_frames,
            "generated_frame_count": generated_frames,
            "trim_tail_frames": trim_tail,
            "mode": "outpaint",
        })

    return {
        "tasks": tasks,
        "shots": plans,
        "published_shots": [dict(plan) for plan in plans],
        "frame_count": target_count,
        "fps": float(generation_fps),
    }


def _prepare_and_run_outpaint(job_id):
    """Detect camera cuts, prepare private shot tasks, then generate."""
    import secrets
    import shutil
    import tempfile

    job = _jobs[job_id]
    abort_state = {"abort": False}
    shot_temp_dir = None
    shot_final_out_dir = None
    has_shot_manifest = False

    try:
        # Match Recast/Repaint's two-phase lifecycle. Preparation is short and
        # CPU-bound, but taking the slot preserves submission order and avoids
        # stacking ffmpeg decoding on top of another active generation.
        with generation_slot(_gen_lock, job) as acquired:
            if not acquired:
                return
            if not try_start(
                job,
                generation_lock=_gen_lock,
                phase="Detecting camera shots",
                message="Detecting camera cuts for Outpaint...",
            ):
                return
            if not register_abort_state(
                job,
                job_id,
                _active_gen_states,
                abort_state,
            ):
                return

            def _abort_preparation():
                if is_cancel_requested(job):
                    raise InterruptedError(
                        "Outpaint camera-shot preparation was cancelled",
                    )

            params = job.get("params") or {}
            source_video = params.get("video_guide")
            target_frame_count = int(params.get("video_length") or 0)
            generation_fps = float(
                params.get("_outpaint_generation_fps") or 0
            )
            if not source_video or not os.path.isfile(source_video):
                raise ValueError("Outpaint source video is unavailable.")
            if target_frame_count <= 0 or generation_fps <= 0:
                raise ValueError("Outpaint timeline metadata is invalid.")

            shot_ranges = _detect_outpaint_video_shot_ranges(
                source_video,
                target_frame_count,
                abort_callback=_abort_preparation,
            )
            params["edit_outpaint_detected_shot_ranges"] = [
                [int(start), int(end)]
                for start, end in shot_ranges
            ]
            if len(shot_ranges) <= 1:
                print(
                    "[Outpaint] Detected one continuous camera shot; "
                    "using the proven continuous pipeline."
                )
            else:
                cut_times = ", ".join(
                    f"{start / generation_fps:.2f}s"
                    for start, _end in shot_ranges[1:]
                )
                print(
                    f"[Outpaint] Detected {len(shot_ranges)} camera shots; "
                    f"generating each independently after cuts at "
                    f"{cut_times}."
                )
                if not update_job(
                    job,
                    phase="Preparing camera shots",
                    message=(
                        f"Preparing {len(shot_ranges)} Outpaint shots..."
                    ),
                ):
                    raise InterruptedError(
                        "Outpaint camera-shot preparation was cancelled",
                    )

                try:
                    resolved_seed = int(params.get("seed", -1))
                except (TypeError, ValueError):
                    resolved_seed = -1
                if resolved_seed < 0:
                    resolved_seed = secrets.randbelow(1_000_000_000)
                params["seed"] = resolved_seed

                model_type = params.get("model_type")
                try:
                    minimum_frames, _frame_step, latent_size = (
                        wgp.get_model_min_frames_and_step(model_type)
                    )
                except Exception:
                    minimum_frames, latent_size = 17, 8

                shot_temp_dir = tempfile.mkdtemp(
                    prefix="maestro-outpaint-shots-",
                )

                def _preparation_progress(index, total):
                    if not update_job(
                        job,
                        phase="Preparing camera shots",
                        message=(
                            f"Preparing Outpaint shot {index + 1}/{total}..."
                        ),
                    ):
                        raise InterruptedError(
                            "Outpaint camera-shot preparation was cancelled",
                        )

                try:
                    shot_manifest = _build_outpaint_shot_manifest(
                        params,
                        source_video,
                        shot_ranges,
                        shot_temp_dir,
                        job_id,
                        target_frame_count=target_frame_count,
                        generation_fps=generation_fps,
                        minimum_frames=minimum_frames,
                        latent_size=latent_size,
                        progress_callback=_preparation_progress,
                        abort_callback=_abort_preparation,
                    )
                except Exception:
                    shutil.rmtree(shot_temp_dir, ignore_errors=True)
                    shot_temp_dir = None
                    raise

                shot_final_out_dir = job.get("out_dir") or _workspace_dir(
                    job.get("workspace"),
                )
                params.update({
                    "_defer_output_publication": True,
                    "_outpaint_shot_manifest": shot_manifest["tasks"],
                    "_outpaint_shot_temp_dir": shot_temp_dir,
                    "_outpaint_final_out_dir": shot_final_out_dir,
                    "_outpaint_shot_source_video": source_video,
                    "_outpaint_shot_bundle": {
                        "shots": shot_manifest["shots"],
                        "published_shots": shot_manifest[
                            "published_shots"
                        ],
                        "frame_count": shot_manifest["frame_count"],
                        "fps": shot_manifest["fps"],
                        "resolved_seed": resolved_seed,
                        "preserve_source_audio": bool(
                            params.get("_outpaint_preserve_audio", True)
                        ),
                    },
                    "edit_outpaint_shot_aware": True,
                    "edit_outpaint_shot_plan": shot_manifest[
                        "published_shots"
                    ],
                })
                job["out_dir"] = shot_temp_dir
                has_shot_manifest = True
                print(
                    "[Outpaint] Shot-aware plan prepared "
                    f"{len(shot_manifest['shots'])} camera shots, "
                    f"{shot_manifest['frame_count']} exact output frames "
                    f"at {shot_manifest['fps']:.6g}fps."
                )
    except InterruptedError:
        return
    except Exception as error:
        traceback.print_exc()
        if shot_temp_dir and os.path.isdir(shot_temp_dir):
            shutil.rmtree(shot_temp_dir, ignore_errors=True)
        if shot_final_out_dir:
            job["out_dir"] = shot_final_out_dir
        finish_job(
            job,
            "failed",
            error=f"Outpaint shot preparation failed: {error}",
            message="Outpaint shot preparation failed",
        )
        return
    finally:
        unregister_abort_state(
            job_id,
            _active_gen_states,
            abort_state,
        )

    if not try_requeue(job, message="Queued (outpaint)", phase=""):
        if shot_temp_dir and os.path.isdir(shot_temp_dir):
            shutil.rmtree(shot_temp_dir, ignore_errors=True)
        if shot_final_out_dir:
            job["out_dir"] = shot_final_out_dir
        return
    if has_shot_manifest:
        _run_outpaint_shot_generation(job_id)
    else:
        _run_generation(job_id)


@api.post("/api/v1/outpaint")
async def outpaint_endpoint(request: Request):
    """Submit an outpaint job: extend video/image canvas using IC-LoRA.

    Body: {
        video_path: str, prompt: str, model_type: str,
        pad_top?: int, pad_bottom?: int, pad_left?: int, pad_right?: int,
        gamma_correct?: bool, seed?: int,
        num_inference_steps?: int, guidance_scale?: float,
        negative_prompt?: str,
        activated_loras?: list, loras_multipliers?: str, workspace?: str,
    }
    """
    body = await request.json()

    video_path = body.get("video_path")
    if not video_path:
        raise HTTPException(status_code=400, detail="video_path is required")
    workspace = body.get("workspace") or _get_active_workspace()
    job_out_dir = _require_project_access(request, workspace)
    video_path = _resolve_authorized_request_media(request, video_path, workspace)
    if not video_path:
        raise HTTPException(status_code=404, detail="Source file not found")

    model_type = body.get("model_type")
    if not model_type:
        raise HTTPException(status_code=400, detail="model_type is required")
    requested_model_type = model_type

    pad_top = int(body.get("pad_top", 0))
    pad_bottom = int(body.get("pad_bottom", 0))
    pad_left = int(body.get("pad_left", 0))
    pad_right = int(body.get("pad_right", 0))
    total_pad = pad_top + pad_bottom + pad_left + pad_right
    if total_pad <= 0:
        raise HTTPException(status_code=400, detail="At least one padding direction must be > 0")

    # Determine if source is video or image; get source dimensions
    ext = os.path.splitext(video_path)[1].lower()
    is_video = ext in (".mp4", ".mkv", ".avi", ".mov", ".webm")

    from PIL import Image as PILImage

    # Optional film-strip trim: if the UI sent start_time/end_time, ffmpeg-cut
    # the source to that range before reading frames. The trimmed clip becomes
    # the canonical video_path for the rest of the request. Falls back to
    # untrimmed source if ffmpeg fails or range is invalid.
    if is_video:
        trim_start = body.get("start_time")
        trim_end = body.get("end_time")
        if trim_start is not None and trim_end is not None:
            try:
                trim_start_f = float(trim_start)
                trim_end_f = float(trim_end)
                if trim_end_f - trim_start_f > 0.05 and trim_start_f >= 0:
                    import subprocess
                    import tempfile
                    trim_dir = os.path.join(os.getcwd(), "uploads")
                    os.makedirs(trim_dir, exist_ok=True)
                    trim_id = uuid.uuid4().hex[:8]
                    trimmed_path = os.path.join(trim_dir, f"outpaint_trim_{trim_id}.mp4")
                    # -ss + -to with re-encode for frame-accurate cut at the
                    # requested sub-second boundaries (stream-copy seeks to
                    # the nearest keyframe and would round our trim).
                    cmd = [
                        "ffmpeg", "-y", "-i", video_path,
                        "-ss", f"{trim_start_f:.3f}",
                        "-to", f"{trim_end_f:.3f}",
                        "-c:v", "libx264", "-crf", "18", "-preset", "fast",
                        "-c:a", "aac", "-b:a", "192k",
                        trimmed_path,
                    ]
                    proc = subprocess.run(cmd, capture_output=True, text=True, timeout=120)
                    if proc.returncode == 0 and os.path.isfile(trimmed_path):
                        write_upload_access_sidecar(
                            trimmed_path,
                            request.state.maestro_session_id,
                            private=True,
                        )
                        print(f"[Outpaint] Trimmed source to [{trim_start_f:.2f}s, {trim_end_f:.2f}s] -> {os.path.basename(trimmed_path)}")
                        video_path = trimmed_path
                    else:
                        print(f"[Outpaint] Trim failed (continuing with full clip): {proc.stderr[:200]}")
            except (TypeError, ValueError) as e:
                print(f"[Outpaint] Invalid trim params: {e}")

    if is_video:
        import decord
        vr = decord.VideoReader(video_path)
        source_total_frames = len(vr)
        source_fps = float(vr.get_avg_fps() or 0)
        src_h, src_w = vr[0].shape[:2]
        del vr
        total_frames = source_total_frames
    else:
        img = PILImage.open(video_path).convert("RGB")
        src_w, src_h = img.size
        source_total_frames = 1
        source_fps = 0.0
        total_frames = 1
        del img

    # Resolve the output grid and protected source rectangle together. The
    # fractional percentages survive through wgp so inference and later
    # metadata describe the same exact canvas.
    resolution_preset = str(body.get("resolution_preset") or "auto").lower()
    base_model_type = wgp.get_base_model_type(model_type)
    outpaint_alignment = 64 if base_model_type == "ltx2_22B" else 32
    geometry = _resolve_outpaint_canvas_geometry(
        src_w,
        src_h,
        pad_top,
        pad_bottom,
        pad_left,
        pad_right,
        resolution_preset,
        outpaint_alignment,
    )
    final_w = geometry["final_w"]
    final_h = geometry["final_h"]
    overlay_w = geometry["overlay_w"]
    overlay_h = geometry["overlay_h"]
    overlay_x = geometry["overlay_x"]
    overlay_y = geometry["overlay_y"]
    video_guide_outpainting = " ".join(
        _format_outpaint_percentage(value)
        for value in geometry["dims"]
    )

    # Auto stays near native dimensions; quality presets apply a pixel budget
    # before both axes are snapped to the model grid.
    if (
        final_w != geometry["requested_w"]
        or final_h != geometry["requested_h"]
    ):
        print(
            f"[Outpaint] Grid-aligned canvas: "
            f"{geometry['requested_w']}x{geometry['requested_h']} -> "
            f"{final_w}x{final_h}"
        )
    print(
        f"[Outpaint] Source: {src_w}x{src_h}, "
        f"Target: {final_w}x{final_h}, "
        f"Protected rect: {overlay_w}x{overlay_h}"
        f"+{overlay_x}+{overlay_y}, "
        f"Dims (%): {video_guide_outpainting}"
    )

    requested_mask_preservation = bool(
        body.get("mask_preserving_outpaint", True)
    )
    mask_preserving_outpaint = bool(
        requested_mask_preservation
        and is_video
        and base_model_type == "ltx2_22B"
    )
    if requested_mask_preservation and not mask_preserving_outpaint:
        print(
            "[Outpaint] Mask-preserving workflow is currently available "
            "for LTX-2.3 22B video outpainting; using the legacy path."
        )
    official_outpaint = bool(mask_preserving_outpaint)
    if official_outpaint:
        model_type = _resolve_ltx2_outpaint_reference_model(model_type)
        if model_type != requested_model_type:
            print(
                "[Outpaint] Official reference model stack: "
                f"{requested_model_type} -> {model_type} "
                "(installed Dev checkpoint + Distilled 1.1 LoRA at 0.5 "
                "+ In/Outpainting IC-LoRA)."
            )
        else:
            selected_def = wgp.get_model_def(model_type) or {}
            if selected_def.get("ltx2_pipeline", "two_stage") == "distilled":
                print(
                    "[Outpaint] No installed Dev checkpoint was found; "
                    "using the selected baked-Distilled model as a "
                    "compatibility fallback."
                )
        base_model_type = wgp.get_base_model_type(model_type)
        print(
            "[Outpaint] Using Lightricks' official two-stage workflow "
            "(#66FF00 mask guide, full reference attention, decoded-pixel "
            "handoff, and Laplacian source restoration)."
        )

    # The official mask-conditioned path requires full control strength. The
    # legacy rollback path keeps accepting the old conditioning control.
    if mask_preserving_outpaint:
        source_preservation = 1.0
    else:
        source_preservation = float(
            body.get("source_preservation", 1.0)
        )
        source_preservation = max(
            0.3,
            min(1.0, source_preservation),
        )

    # The official in/outpainting LoRA is fixed at its trained strength.
    # Legacy mode retains the old multiplier solely for rollback testing.
    if mask_preserving_outpaint:
        outpaint_lora_strength = 1.0
    else:
        outpaint_lora_strength = float(
            body.get("outpaint_lora_strength", 1.0)
        )
        outpaint_lora_strength = max(
            0.0,
            min(2.0, outpaint_lora_strength),
        )

    # Preserve source audio: outpainting only changes spatial canvas — the
    # temporal content (and therefore the audio) is identical to the source.
    # LTX-2 distilled, however, always synthesizes a fresh audio track via its
    # audio decoder, which replaces the source audio with unrelated synthetic
    # audio. We post-mux the original source audio back onto the output after
    # generation completes (see _outpaint_audio_postprocess in _run_generation).
    # Default True since the alternative (LTX-generated audio for an outpaint)
    # is essentially never what the user wants.
    preserve_source_audio = bool(body.get("preserve_source_audio", True)) and is_video

    # Lock source pixels: composite the original source clip back into the
    # source-area rectangle of the output. Default OFF — empirical testing
    # showed (a) the IC-LoRA's regenerated source area actually preserves
    # lip detail well, and (b) hard-overlaying source pixels creates a
    # visible rectangular seam because the model's outpainted region has
    # slightly different color/tone than raw source. Kept as opt-in for
    # power users who explicitly want pixel-perfect source area.
    lock_source_pixels = bool(
        body.get("lock_source_pixels", False)
    ) and is_video and not mask_preserving_outpaint

    # Trim sliding-window smear: at the boundary between window 1 and
    # window 2, the model's prefix-conditioning produces ~reuse_frames
    # frames of "stutter" content (showing the same source content as
    # window 1's last frame). Empirically this introduces a constant
    # ~9-frame lag for the rest of the output (windows 2+ all carry the
    # same offset; lag does NOT accumulate per boundary). Cutting 9
    # frames at the window 1→2 boundary realigns the output with audio
    # for the entire remaining duration. Default ON for multi-window
    # video outpaint since this is what the user actually needs to fix
    # lip sync. Single-window outpaint has no boundary so no-op.
    trim_window_smear = bool(body.get("trim_window_smear", True)) and is_video

    # Sliding window for long clips: outpaint VRAM scales with window frames ×
    # canvas pixels. Single-shot generation works for short clips at modest
    # resolutions but OOMs on longer clips (e.g. 57s @ 720p needs ~6 windows).
    # Use the model's recommended window default unless the caller overrides.
    # LTX-2 (per ltx2_handler.py): window_default=241 (~10s @ 24fps),
    # overlap_default=9, discard_last_frames=8 (LTX has 8 distorted tail
    # frames per window — discarding lets the next window's overlap region
    # replace them so seams stay clean).
    try:
        _model_def = wgp.get_model_def(model_type) or {}
    except Exception:
        _model_def = {}
    try:
        _model_defaults = wgp.get_default_settings(model_type) or {}
    except Exception:
        _model_defaults = {}
    if is_video:
        (
            source_duration,
            generation_fps,
            total_frames,
        ) = _resolve_outpaint_video_timing(
            source_total_frames,
            source_fps,
            _model_def,
        )
        print(
            "[Outpaint] Timing: "
            f"{source_total_frames} frames at {source_fps:.3f} fps "
            f"({source_duration:.3f}s) -> {total_frames} frames at "
            f"{generation_fps:g} fps"
        )
    if official_outpaint:
        # The official graph distills the Dev transformer to the published
        # eight-step schedule. Do not let stale saved settings alter it.
        inference_steps = 8
        guidance_scale = 1.0
        print(
            "[Outpaint] Reference sampling: 8-step masked first pass + "
            "2-step decoded-pixel refinement, CFG 1."
        )
    else:
        try:
            inference_steps, guidance_scale = _resolve_outpaint_sampling(
                body,
                wgp.get_base_model_type(model_type),
                _model_def,
                _model_defaults,
            )
        except ValueError as error:
            raise HTTPException(
                status_code=400,
                detail=str(error),
            ) from error
    _sw_defaults = _model_def.get("sliding_window_defaults", {})
    sliding_window_size = int(body.get("sliding_window_size", _sw_defaults.get("window_default", 241)))
    sliding_window_overlap = int(body.get("sliding_window_overlap", _sw_defaults.get("overlap_default", 9)))
    sliding_window_discard_last_frames = int(body.get(
        "sliding_window_discard_last_frames",
        _sw_defaults.get("discard_last_frames", 8),
    ))
    # Clamp window to model's reported max (defaults to 501 for LTX-2).
    _window_max = int(_sw_defaults.get("window_max", 501))
    _window_min = int(_sw_defaults.get("window_min", 17))
    sliding_window_size = max(_window_min, min(_window_max, sliding_window_size))
    if official_outpaint and is_video:
        requested_window_size = sliding_window_size
        sliding_window_size = _cap_outpaint_single_stage_window(
            sliding_window_size,
            final_w,
            final_h,
            _window_min,
            _window_max,
        )
        if sliding_window_size < requested_window_size:
            print(
                "[Outpaint] Two-stage Outpaint VRAM window cap: "
                f"{requested_window_size} -> {sliding_window_size} frames "
                f"for {final_w}x{final_h}. The complete clip will use "
                "additional sliding windows."
            )
    # Outpaint system LoRAs are selected internally. Remove a persisted manual
    # selection of either system file so rerunning old settings cannot load
    # both the legacy and official variants at once.
    activated_loras = list(body.get("activated_loras") or [])
    multiplier_tokens = [
        token.split(";", 1)[0]
        for token in str(body.get("loras_multipliers") or "").split()
    ]
    system_outpaint_loras = {
        "ltx-2.3-22b-ic-lora-outpaint.safetensors",
        "ltx-2.3-22b-ic-lora-in-outpainting-0.9.safetensors",
    }
    filtered_loras = []
    filtered_multipliers = []
    for index, lora in enumerate(activated_loras):
        if os.path.basename(str(lora)).lower() in system_outpaint_loras:
            print(
                "[Outpaint] Ignoring manually selected system LoRA "
                f"{os.path.basename(str(lora))}; the workflow manages it."
            )
            continue
        if official_outpaint:
            print(
                "[Outpaint] Ignoring user LoRA "
                f"{os.path.basename(str(lora))}; the reference workflow "
                "manages its Distilled and IC-LoRA adapters internally."
            )
            continue
        filtered_loras.append(lora)
        filtered_multipliers.append(
            multiplier_tokens[index]
            if index < len(multiplier_tokens)
            else "1"
        )

    submitted_outpaint_prompt = str(body.get("prompt") or "").strip()
    if official_outpaint:
        # Lightricks recommends an empty/minimal prompt, or a description of
        # only the missing region. Appending a whole-scene instruction makes
        # the model redraw or duplicate subjects at the source boundary.
        outpaint_prompt = (
            "."
            if not submitted_outpaint_prompt
            or submitted_outpaint_prompt.lower() == "extend the scene naturally"
            else submitted_outpaint_prompt
        )
    else:
        raw_outpaint_prompt = submitted_outpaint_prompt
        if not raw_outpaint_prompt or raw_outpaint_prompt.lower() == "extend the scene naturally":
            raw_outpaint_prompt = (
                "the scene continues naturally beyond the original frame, "
                "consistent style and lighting"
            )
        outpaint_prompt = (
            f"{raw_outpaint_prompt}; seamlessly extend the scene into the "
            "empty margins, matching the existing content."
        )

    gen_params = {
        "prompt": outpaint_prompt,
        "model_type": model_type,
        # The published Outpaint app deliberately leaves this empty. A broad
        # generic negative prompt can shift the generated margins away from
        # the appearance of the protected source.
        "negative_prompt": (
            ""
            if official_outpaint
            else str(body.get("negative_prompt") or "")
        ),
        "seed": body.get("seed", -1),
        "guidance_scale": guidance_scale,
        "num_inference_steps": inference_steps,
        "video_length": max(total_frames, 17) if is_video else 1,
        # Keep the generated timeline on the source video's native cadence.
        # Forcing the reference demo's 24 fps collapsed a known-good 305-frame
        # / two-window clip into one 249-frame window and caused the generated
        # margins to diverge visibly from the protected source rectangle.
        "force_fps": "control" if is_video else "auto",
        "resolution": f"{final_w}x{final_h}",
        "generation_mode": "video" if is_video else "image",
        # Tag for the gallery's Edits filter + Load Settings restore path.
        "edit_sub_mode": "outpaint",
        # V = source video guide (the ORIGINAL, unpadded source — the pipeline
        # places it into the padded canvas internally); G = masked inpaint mode
        # (required for outpaint IC-LoRA gamma-round-trip to trigger).
        "video_prompt_type": "VG" if is_video else "G",
        "video_guide": video_path if is_video else None,
        "image_start": video_path if not is_video else None,
        "video_guide_outpainting": video_guide_outpainting,
        "input_video_strength": body.get("input_video_strength", 1.0),
        "denoising_strength": source_preservation,
        # Read by ltx2.get_loras_transformer — NOT a standard wgp param, so it
        # must survive the signature filter. We pass it through raw_params and
        # ltx2.py picks it up via kwargs.get.
        "outpaint_lora_strength": outpaint_lora_strength,
        "outpaint_mask_preserve": mask_preserving_outpaint,
        "outpaint_official_stack": official_outpaint,
        # Match the current Lightricks graph as one coherent pipeline. The
        # implementation paints the exact marker immediately before VAE
        # encoding, keeps full reference attention, blends pass one back to
        # source pixels, resizes with Lanczos, and restores source again after
        # pass two. The marker-safe source pyramid prevents #66FF00 leakage.
        "single_stage_pipeline": False,
        "outpaint_full_resolution_refine": official_outpaint,
        "activated_loras": filtered_loras,
        "loras_multipliers": " ".join(filtered_multipliers),
        # Sliding window engages automatically when total_frames > sliding_window_size
        # (wgp.py:6739). For images / very short clips, force window > clip so the
        # pipeline runs single-shot (cheaper than multi-window for tiny inputs).
        "sliding_window_size": sliding_window_size if (is_video and total_frames > sliding_window_size) else (max(total_frames, 17) + 10 if is_video else 17),
        "sliding_window_overlap": sliding_window_overlap,
        "sliding_window_discard_last_frames": sliding_window_discard_last_frames,
        "settings_version": 2.53,
        # Underscore-prefixed flags survive job["params"] but get stripped by
        # the wgp.generate_video signature filter (line ~5119), so they don't
        # reach the inference pipeline. _run_generation reads them after the
        # job completes to drive post-processing (audio mux + source overlay).
        "_outpaint_preserve_audio": preserve_source_audio,
        "_outpaint_source_video": video_path if (preserve_source_audio or lock_source_pixels) else None,
        "_outpaint_lock_source_pixels": lock_source_pixels,
        "_outpaint_overlay_w": overlay_w,
        "_outpaint_overlay_h": overlay_h,
        "_outpaint_overlay_x": overlay_x,
        "_outpaint_overlay_y": overlay_y,
        "_outpaint_canvas_w": final_w,
        "_outpaint_canvas_h": final_h,
        # Private preparation metadata for automatic camera-shot dispatch.
        # It is stripped from the final sidecar after assembly.
        "_outpaint_generation_fps": generation_fps if is_video else None,
        "_outpaint_source_frame_count": (
            source_total_frames if is_video else None
        ),
        # Smear trim params: only meaningful when total_frames > sliding_window_size
        # (multi-window mode). Boundary 1 is at output position
        # sliding_window_size - sliding_window_discard_last_frames.
        # Smear count = sliding_window_overlap (reuse_frames) — the model
        # produces this many "duplicate" frames at the boundary that we trim.
        "_outpaint_trim_smear": trim_window_smear and is_video and total_frames > sliding_window_size,
        "_outpaint_smear_boundary_frame": sliding_window_size - sliding_window_discard_last_frames,
        "_outpaint_smear_count": sliding_window_overlap,
        # Restore-able state for the gallery's Load Settings flow. The
        # frontend recomputes canvas + video box from these on reload so
        # the user sees the same composition that produced the output.
        "edit_video_path": video_path,
        "outpaint_pad_top": pad_top,
        "outpaint_pad_bottom": pad_bottom,
        "outpaint_pad_left": pad_left,
        "outpaint_pad_right": pad_right,
        "outpaint_aspect": body.get("outpaint_aspect"),
        "outpaint_resolution_preset": resolution_preset,
        "outpaint_source_preservation": source_preservation,
        "outpaint_lora_strength_ui": outpaint_lora_strength,
        "outpaint_mask_preserving": mask_preserving_outpaint,
        "outpaint_requested_model_type": requested_model_type,
        "edit_outpaint_raw_prompt": submitted_outpaint_prompt,
        "outpaint_trim_start": body.get("start_time"),
        "outpaint_trim_end": body.get("end_time"),
    }
    # Strip None values so they don't override defaults downstream
    gen_params = {k: v for k, v in gen_params.items() if v is not None}

    job_id = uuid.uuid4().hex[:8]
    job = {
        "id": job_id, "status": "queued", "progress": 0, "step": 0, "total_steps": 0,
        "phase": "", "message": "Queued (outpaint)", "created_at": time.time(),
        "params": gen_params, "output_files": [], "error": None,
        "workspace": workspace, "out_dir": job_out_dir,
    }
    worker = (
        _prepare_and_run_outpaint
        if official_outpaint and is_video
        else _run_generation
    )
    _queue_recovery_register_and_publish(
        job,
        worker=worker,
        recovery_kind=(
            "studio_outpaint_preparation"
            if worker is _prepare_and_run_outpaint
            else "studio_generation"
        ),
        thread_name=f"studio-outpaint-{job_id}",
    )

    # Estimate window count for the response so the UI can surface it.
    # Mirrors wgp.compute_sliding_window_no for the multi-window case.
    if is_video and total_frames > sliding_window_size:
        _stride = max(1, sliding_window_size - sliding_window_discard_last_frames - sliding_window_overlap)
        _left = max(0, total_frames - sliding_window_size + sliding_window_discard_last_frames)
        _window_count = 1 + (_left + _stride - 1) // _stride
    else:
        _window_count = 1

    return {
        "job_id": job_id,
        "status": "queued",
        "source_size": f"{src_w}x{src_h}",
        "output_size": f"{final_w}x{final_h}",
        "outpainting_dims": video_guide_outpainting,
        "total_frames": total_frames,
        "sliding_window_size": sliding_window_size,
        "sliding_window_count": _window_count,
    }


@api.post("/api/v1/blend")
async def blend_endpoint(request: Request):
    """Blend two clips with an AI-generated transition (Sora-1 style overlap).

    For `overlap` mode: the last `overlap_sec` of Clip A blends with the
    first `overlap_sec` of Clip B during a shared window. Total output
    duration = len(A) + len(B) - overlap_sec.

    Pipeline: sparse keyframe injection — A's last N frames anchored at
    blend positions 1..N, B's first N frames anchored at blend positions
    (transition-N+1)..transition. Middle is free for the model to invent.
    Uses `video_prompt_type="FI"` (image_refs + frames_positions), the same
    mechanism Continue/Extend and the Director/music-video flows use for
    motion-preserving keyframe anchoring.

    Body: {
        clip_a_path: str, clip_b_path: str,
        prompt?: str — describe the *transition itself*, not just "smooth blend".
        model_type: str,
        blend_mode?: 'insert'|'overlap', overlap_sec?: float (default 3),
        motion_prefix_sec?: float (default 1.0) — seconds of A's overlap-zone
            start used as `video_source`, switching the pipeline from SE to
            VE mode. Gives the model real motion history to extrapolate so
            rotation/pan direction continues from A. Set to 0 for pure SE
            (single still-frame anchor). Capped at 80% of overlap_sec.
        motion_suffix_sec?: float (default 1.0) — symmetric counterpart to
            motion_prefix_sec. Feeds B's overlap-zone end as `video_end`
            via a keyframe-injection path in ltx2.py, giving the model B's
            actual motion trajectory leading into the landing frame. Without
            this, the joggers (for ex.) tend to "slow-mo" into the anchor
            then hard-cut to real-speed B_post. Capped at 80% of overlap_sec.
        anchor_frames?: int (default 0) — optional weak keyframes near the
            edges for extra motion-context. Usually leave 0 with VE mode.
        injection_strength?: float (default 0.4) — strength for those.
        num_inference_steps?: int, guidance_scale?: float, negative_prompt?: str,
        seed?: int, activated_loras?: list, loras_multipliers?: str,
        workspace?: str,
        base_params?: dict — UI passes state.params here so the blend
            inherits progressive_pipeline, stage2_steps, etc. Blend-specific
            fields (image_start/end, resolution, video_length, ...) override.
    }
    """
    body = await request.json()

    clip_a_path = body.get("clip_a_path")
    clip_b_path = body.get("clip_b_path")
    if not clip_a_path or not clip_b_path:
        raise HTTPException(status_code=400, detail="Both clip_a_path and clip_b_path are required")

    workspace = body.get("workspace") or _get_active_workspace()
    job_out_dir = _require_project_access(request, workspace)
    clip_a_path = _resolve_authorized_request_media(
        request, clip_a_path, workspace,
    )
    clip_b_path = _resolve_authorized_request_media(
        request, clip_b_path, workspace,
    )
    if not clip_a_path:
        raise HTTPException(status_code=404, detail="Clip A not found")
    if not clip_b_path:
        raise HTTPException(status_code=404, detail="Clip B not found")

    model_type = body.get("model_type")
    if not model_type:
        raise HTTPException(status_code=400, detail="model_type is required")

    blend_mode = body.get("blend_mode", "overlap")
    overlap_sec = float(body.get("overlap_sec", 3))

    import tempfile
    import math
    import decord
    import numpy as np
    from PIL import Image as PILImage

    temp_dir = tempfile.mkdtemp(prefix="blend_")

    try:
        # ── Probe both clips ─────────────────────────────────────────────
        def _probe(path):
            ext = os.path.splitext(path)[1].lower()
            if ext in (".mp4", ".mkv", ".avi", ".mov", ".webm"):
                vr = decord.VideoReader(path)
                fps = float(vr.get_avg_fps()) or 24.0
                h, w = vr[0].shape[:2]
                return {"is_video": True, "fps": fps, "frames": len(vr), "h": h, "w": w, "reader": vr}
            img = PILImage.open(path).convert("RGB")
            return {"is_video": False, "fps": 24.0, "frames": 1, "h": img.size[1], "w": img.size[0], "image": img}

        info_a = _probe(clip_a_path)
        info_b = _probe(clip_b_path)

        # ── Target geometry (A's native, aligned to 32 for LTX) ──────────
        fps = info_a["fps"]
        # LTX-2 frames schedule: must be >= 17 and (n - 17) % 8 == 0
        raw_frames = max(17, int(round(overlap_sec * fps)))
        transition_frames = 17 + 8 * math.ceil((raw_frames - 17) / 8) if raw_frames > 17 else 17
        # Effective overlap after rounding (for frame-accurate trim/concat)
        overlap_sec_eff = transition_frames / fps

        # Snap resolution to LTX's 32-px alignment
        src_w = (info_a["w"] // 32) * 32
        src_h = (info_a["h"] // 32) * 32
        if src_w <= 0 or src_h <= 0:
            raise HTTPException(status_code=400, detail=f"Clip A resolution too small: {info_a['w']}x{info_a['h']}")

        def _resample_frames(raw_list, target_len, target_w, target_h):
            """Resize + resample a list of RGB np arrays to exactly target_len frames."""
            if not raw_list:
                return [np.zeros((target_h, target_w, 3), dtype=np.uint8)] * target_len
            resized = []
            for f in raw_list:
                if f.shape[0] != target_h or f.shape[1] != target_w:
                    f = np.array(PILImage.fromarray(f).resize((target_w, target_h), PILImage.LANCZOS))
                resized.append(f)
            if len(resized) == target_len:
                return resized
            idx = np.linspace(0, len(resized) - 1, target_len).astype(int)
            return [resized[i] for i in idx]

        # ── Extract A's tail (last overlap_sec_eff seconds) ──────────────
        if info_a["is_video"]:
            src_frames_a = max(1, int(round(overlap_sec_eff * info_a["fps"])))
            start_idx_a = max(0, info_a["frames"] - src_frames_a)
            raw_a = [info_a["reader"][i].asnumpy() for i in range(start_idx_a, info_a["frames"])]
            del info_a["reader"]
        else:
            raw_a = [np.array(info_a["image"])]

        # ── Extract B's head (first overlap_sec_eff seconds) ─────────────
        if info_b["is_video"]:
            src_frames_b = max(1, int(round(overlap_sec_eff * info_b["fps"])))
            end_idx_b = min(src_frames_b, info_b["frames"])
            raw_b = [info_b["reader"][i].asnumpy() for i in range(end_idx_b)]
            del info_b["reader"]
        else:
            raw_b = [np.array(info_b["image"])]

        frames_a = _resample_frames(raw_a, transition_frames, src_w, src_h)
        frames_b = _resample_frames(raw_b, transition_frames, src_w, src_h)

        # ── Anchor frames for seamless concat at both seams ────────────────
        # Correct frame selection for overlap semantics (a):
        #   A_pre = A[0 : L_a - O]          → last frame = A[L_a-O-1]
        #   blend starts at A[L_a - O]       → first blend frame
        #   blend ends   at B[O - 1]         → last blend frame
        #   B_post = B[O : L_b]              → first frame = B[O]
        b_end_path = os.path.join(temp_dir, "b_overlap_end.png")
        PILImage.fromarray(frames_b[-1]).save(b_end_path)

        # ── Motion-prefix mode: video_source from A's overlap-zone start ───
        # Pure SE gives the model only a STILL frame at position 0, so it
        # has no motion context and tends to invent rotation/pan direction
        # arbitrarily (often opposite to A's). Passing K frames of A's
        # overlap tail as `video_source` flips the pipeline into VE mode
        # (Continue/Extend + End-frame), giving the model motion history
        # to extrapolate from — the same mechanism that makes Continue
        # preserve motion well.
        #
        # Those first K frames become the first K frames of the blend
        # output. They are EXACTLY the frames of A's overlap zone that
        # A_pre was going to cut off anyway, so the concat stays frame-
        # perfect (A_pre → blend seam = A[L_a-O-1] → A[L_a-O]).
        # Default 1s of A's overlap-zone start as video_source (VE mode).
        # The "still-frame joggers" regression was caused by image_mode
        # from base_params coercing the pipeline into image-only output,
        # not by VE mode itself.
        motion_prefix_sec = float(body.get("motion_prefix_sec", 1.0))
        motion_prefix_sec = max(0.0, min(motion_prefix_sec, overlap_sec_eff * 0.8))
        K_prefix = int(round(motion_prefix_sec * fps)) if motion_prefix_sec > 0 else 0
        K_prefix = max(0, min(K_prefix, len(frames_a) - 2))  # leave room for generation

        def _write_mp4(path: str, frames: list, fps_val: float):
            import imageio
            _writer = imageio.get_writer(path, fps=fps_val, codec="libx264", quality=9)
            try:
                for f in frames:
                    _writer.append_data(f)
            finally:
                _writer.close()

        video_source_path = None
        a_start_path = None
        if K_prefix > 0:
            video_source_path = os.path.join(temp_dir, "motion_prefix.mp4")
            _write_mp4(video_source_path, frames_a[:K_prefix], fps)
        else:
            # Pure SE fallback: single-frame anchor at blend start
            a_start_path = os.path.join(temp_dir, "a_overlap_start.png")
            PILImage.fromarray(frames_a[0]).save(a_start_path)

        # ── Motion-suffix mode: video_end from B's overlap-zone end ────────
        # Symmetric counterpart to motion_prefix. Placed at the END of the
        # output latent sequence via the new `_append_suffix_entries` path
        # in ltx2.py (VideoConditionByKeyframeIndex at end positions).
        # Gives the model B's actual motion trajectory leading into the
        # landing frame, so the joggers arrive at full speed instead of
        # easing-in to hit a static anchor.
        #
        # Those last K frames become the final K frames of the blend output.
        # They are EXACTLY the frames of B's overlap zone that B_post was
        # going to skip anyway, so the blend → B_post seam stays frame-
        # perfect (blend[N-1] = B[O-1] → B_post[0] = B[O]).
        motion_suffix_sec = float(body.get("motion_suffix_sec", 1.0))
        motion_suffix_sec = max(0.0, min(motion_suffix_sec, overlap_sec_eff * 0.8))
        K_suffix = int(round(motion_suffix_sec * fps)) if motion_suffix_sec > 0 else 0
        # Cap so suffix + prefix don't exceed transition length with no room
        # for AI-invented middle. Leave at least 9 frames (1 latent chunk + 1)
        # for the generator.
        K_suffix = max(0, min(K_suffix, len(frames_b) - 1, transition_frames - K_prefix - 9))

        video_end_path = None
        if K_suffix > 0:
            video_end_path = os.path.join(temp_dir, "motion_suffix.mp4")
            # Last K frames of B's overlap zone, in forward temporal order
            _write_mp4(video_end_path, frames_b[-K_suffix:], fps)

        # ── Optional weak keyframe hints for motion continuity ─────────────
        # Pure SE loses A's rotation and B's stride rhythm (model has no
        # motion context beyond the two endpoints). `anchor_frames > 0`
        # injects a few WEAK keyframes from A's overlap zone (forward in
        # time from image_start) and B's overlap zone (backward in time
        # from image_end), at low injection_strength so they act as hints
        # not hard locks.
        #
        # Default 0 = pure SE (proven to produce great creative bridges).
        # Try 2-3 with injection_strength=0.3 to carry some motion context.
        n_anchors = int(body.get("anchor_frames", 0))
        max_anchors = min(len(frames_a) - 1, len(frames_b) - 1, max(1, transition_frames // 4))
        n_anchors = max(0, min(n_anchors, max_anchors))

        extra_refs = []
        extra_positions = []
        if n_anchors > 0:
            # A-side hints: A frames [1..n_anchors] at blend positions [2..n_anchors+1]
            # (position 1 = image_start = frames_a[0]; these continue A's motion forward)
            for i in range(1, n_anchors + 1):
                p = os.path.join(temp_dir, f"a_hint_{i:02d}.png")
                PILImage.fromarray(frames_a[i]).save(p)
                extra_refs.append(p)
                extra_positions.append(i + 1)

            # B-side hints: B frames [len-2..len-1-n_anchors] at positions [N-1..N-n_anchors]
            # (position N = image_end = frames_b[-1]; these bring B's motion into the end)
            for i in range(1, n_anchors + 1):
                b_idx = len(frames_b) - 1 - i
                if b_idx < 0:
                    break
                p = os.path.join(temp_dir, f"b_hint_{i:02d}.png")
                PILImage.fromarray(frames_b[b_idx]).save(p)
                extra_refs.append(p)
                extra_positions.append(transition_frames - i)

        injection_strength = float(body.get("injection_strength", 0.4))
        injection_strength = max(0.0, min(1.0, injection_strength))

        # Diagnostic: show what the UI actually sent us.
        _raw_base_params = body.get("base_params")
        if _raw_base_params is None:
            print(f"[Blend] base_params: <NOT SENT by UI — hard-refresh the browser to pick up the store change>")
        else:
            _bp_keys = sorted(_raw_base_params.keys()) if isinstance(_raw_base_params, dict) else []
            print(f"[Blend] base_params received: {len(_bp_keys)} keys: {_bp_keys}")

        print(f"[Blend] A={os.path.basename(clip_a_path)} ({info_a['w']}x{info_a['h']}@{info_a['fps']:.1f}), "
              f"B={os.path.basename(clip_b_path)} ({info_b['w']}x{info_b['h']}@{info_b['fps']:.1f})")
        # Describe the blend mode selected by prefix/suffix config
        _end_desc = (
            f"video_end={K_suffix} frames ({motion_suffix_sec:.2f}s) of B's overlap end"
            if video_end_path is not None else "image_end=B[O-1]"
        )
        if video_source_path is not None:
            print(f"[Blend] VE mode: video_source={K_prefix} frames ({motion_prefix_sec:.2f}s) of A's overlap start, {_end_desc}")
        else:
            print(f"[Blend] SE mode (no motion prefix): image_start=A[L-O], {_end_desc}")
        if extra_refs:
            print(f"[Blend]   + {len(extra_refs)} weak anchors @ strength={injection_strength:.2f}, "
                  f"positions={' '.join(str(p) for p in extra_positions)}")

        # ── Build generation params ─────────────────────────────────────────
        # Inherit the user's Studio settings (progressive_pipeline,
        # num_inference_steps, guidance_scale, negative_prompt, CFG-related
        # flags, etc.) so the blend uses the same generation config that
        # their manual SE tests used. Then override with blend-specific
        # fields (image_start/end, resolution, video_length, ...).
        default_prompt = (
            "continuous coherent camera motion smoothly transitioning "
            "between the two scenes, cinematic, natural movement"
        )
        default_neg = (
            "crossfade, dissolve, fade, double exposure, ghosting, "
            "static, still, abrupt cut, jump cut"
        )

        # Start from Studio's full params (if the UI passed them). Drop
        # keys we always compute ourselves so they can't leak through stale.
        base_params = dict(body.get("base_params") or {})
        for _k in (
            # Blend computes these
            "video_length", "resolution", "generation_mode", "image_prompt_type",
            "image_start", "image_end", "video_guide", "video_mask",
            "video_prompt_type", "image_refs", "frames_positions", "video_source", "video_end",
            # image_mode: Studio's image-vs-video toggle. MUST drop or the blend
            # can be coerced into image-only mode (outputs a .png instead of
            # generating a video — happened when user had image_mode active in
            # the sidebar and triggered a blend).
            "image_mode",
            # Blend is always a single generation; don't inherit Studio's repeat
            "repeat_generation",
            # Reference pipeline is a per-model Advanced Settings toggle for
            # plain generations; a blend inheriting it would silently switch
            # the sampling pipeline (and its blend target model may not even
            # support it). Never inherit.
            "reference_pipeline",
            # These had their own top-level overrides below
            "prompt", "model_type", "seed", "activated_loras", "loras_multipliers",
        ):
            base_params.pop(_k, None)

        gen_params = dict(base_params)  # start with inherited Studio settings
        gen_params.update({
            "prompt": body.get("prompt", default_prompt),
            "model_type": model_type,
            # negative_prompt: explicit body wins > inherited studio value > default
            "negative_prompt": body.get("negative_prompt", base_params.get("negative_prompt", default_neg)),
            "seed": body.get("seed", -1),
            # guidance_scale / num_inference_steps: explicit body wins > studio value > safe default
            "guidance_scale": float(body.get("guidance_scale", base_params.get("guidance_scale", 1.0))),
            "num_inference_steps": int(body.get("num_inference_steps", base_params.get("num_inference_steps", 15))),
            "video_length": transition_frames,
            "resolution": f"{src_w}x{src_h}",
            "generation_mode": "video",
            "image_mode": 0,  # defensive: blend is always a video job
            "image_prompt_type": "SE",
            "image_start": a_start_path,
            "image_end": b_end_path,
            "activated_loras": body.get("activated_loras", []),
            # Distilled pipeline has a single phase; strip multi-phase lora multipliers.
            "loras_multipliers": " ".join(m.split(";")[0] for m in (body.get("loras_multipliers", "") or "").split()),
            "sliding_window_size": transition_frames + 10,
            "settings_version": 2.52,
            "_blend_clip_a": clip_a_path,
            "_blend_clip_b": clip_b_path,
            "_blend_temp_dir": temp_dir,
            "_blend_mode": blend_mode,
            "_blend_overlap_sec": overlap_sec_eff,
            "_blend_fps": fps,
            "_blend_out_w": src_w,
            "_blend_out_h": src_h,
            # Final concat target — A's native dimensions (rounded to even for
            # libx264). The blend was generated at (src_w, src_h) which has
            # been snapped to 32-multiples (e.g. 1280x720 → 1280x704). Scaling
            # the blend up to A's native dims at concat time matches A_pre and
            # B_post pixel-perfectly, so the seams don't letterbox.
            "_blend_concat_w": int(info_a["w"]) - (int(info_a["w"]) % 2),
            "_blend_concat_h": int(info_a["h"]) - (int(info_a["h"]) % 2),
        })

        # Motion-prefix mode switches from SE (single start frame) to VE
        # (video_source + end frame), giving the model real motion history
        # from A so it extrapolates the rotation direction correctly.
        if video_source_path is not None:
            gen_params["image_prompt_type"] = "VE"
            gen_params["video_source"] = video_source_path
            # Remove image_start entirely — setting it to None explicitly
            # can confuse validation code that checks `key in dict`.
            # "V" in image_prompt_type supersedes "S" (video_source replaces image_start).
            gen_params.pop("image_start", None)

        # Motion-suffix: pass B's overlap-end frames as video_end so the
        # model sees B's motion trajectory leading into the landing frame.
        # Handled in ltx2.py via _append_suffix_entries — supersedes image_end.
        #
        # NOTE: image_end stays in gen_params even when suffix is active.
        # wgp.py validates image_prompt_type="VE" requires an end image, so
        # stripping image_end here triggers "You must provide an End Image"
        # BEFORE our code runs. We keep image_end = B[O-1] for validation;
        # ltx2.py's `has_suffix_frames` branch skips the image_end append
        # when the suffix is present, so it's effectively unused downstream.
        if video_end_path is not None:
            gen_params["video_end"] = video_end_path

        # input_video_strength: how tightly the pipeline locks to video_source
        # AND image_end. Default 1.0 = full lock → model ends up averaging
        # between the two anchors, which decodes as a crossfade for disparate
        # scenes. Lowering to 0.5-0.8 frees the model to invent motion
        # between the anchors instead of interpolating pixels.
        # Handler description: "you may try values lower value than 1 to
        # get more motion" (ltx2_handler.py:181).
        input_video_strength = float(body.get("input_video_strength", base_params.get("input_video_strength", 1.0)))
        input_video_strength = max(0.1, min(1.0, input_video_strength))
        gen_params["input_video_strength"] = input_video_strength

        if extra_refs:
            gen_params["video_prompt_type"] = "KFI"
            gen_params["image_refs"] = extra_refs
            gen_params["frames_positions"] = " ".join(str(p) for p in extra_positions)
            gen_params["injection_strength"] = injection_strength

        # Log the EFFECTIVE gen_params values actually being used for the job
        # (after merging base_params + body overrides + blend-specific fields).
        _effective_log_keys = (
            "num_inference_steps", "guidance_scale", "guidance_phases",
            "stage2_steps", "progressive_pipeline", "input_video_strength",
            "progressive_stage2_steps", "progressive_stage3_steps",
            "cfg_star_switch", "apg_switch",
            "sliding_window_size", "sliding_window_overlap",
        )
        _eff_summary = [(k, gen_params[k]) for k in _effective_log_keys if k in gen_params]
        if _eff_summary:
            print(f"[Blend] Effective gen_params: "
                  f"{', '.join(f'{k}={v!r}' for k, v in _eff_summary)}")
        _neg = gen_params.get("negative_prompt", "")
        if _neg:
            _neg_short = _neg if len(_neg) < 100 else _neg[:97] + "..."
            print(f"[Blend] negative_prompt: {_neg_short!r}")

        workspace = body.get("workspace") or _get_active_workspace()

        job_id = uuid.uuid4().hex[:8]
        job = {
            "id": job_id, "status": "queued", "progress": 0, "step": 0, "total_steps": 0,
            "phase": "", "message": "Queued (blend)", "created_at": time.time(),
            "params": gen_params, "output_files": [], "error": None,
            "workspace": workspace, "out_dir": job_out_dir,
        }
        _queue_recovery_register_and_publish(
            job,
            worker=_run_blend_generation,
            recovery_kind="studio_blend",
            thread_name=f"studio-blend-{job_id}",
        )

        return {"job_id": job_id, "status": "queued", "overlap_sec": overlap_sec_eff, "frames": transition_frames}

    except Exception:
        # Setup failed before the background thread took ownership of temp_dir.
        # _run_blend_generation is responsible for cleanup once it starts.
        import shutil
        shutil.rmtree(temp_dir, ignore_errors=True)
        raise


def _run_blend_generation(job_id: str):
    """Background thread: run VG blend generation, then concatenate
    A[:L_a - O] + generated_blend + B[O:] so the blend replaces the
    last O seconds of A and the first O seconds of B (overlap semantics).

    Uses filter_complex with explicit scale+fps normalization so the three
    segments (A at native res/fps, LTX output at snapped res/fps, B at
    native res/fps) always concatenate cleanly regardless of mismatches.
    """
    job = _jobs[job_id]
    temp_dir = job["params"].get("_blend_temp_dir")
    assembly_state = {"abort": False}

    try:
        if not _run_generation(job_id, finalize=False):
            return

        if not register_abort_state(
            job, job_id, _active_gen_states, assembly_state,
        ):
            return
        if not update_job(
            job, message="Assembling blend...", phase="Assembling blend",
        ):
            return

        if not job.get("output_files"):
            finish_job(
                job, "failed", error="Blend generation produced no output",
                message="Blend generation failed",
            )
            return

        blend_params = job["params"]
        clip_a = blend_params.get("_blend_clip_a")
        clip_b = blend_params.get("_blend_clip_b")
        overlap_sec = float(blend_params.get("_blend_overlap_sec", 3))
        # Generation dims (32-snapped, e.g. 1280x704 for a 1280x720 source)
        out_w = int(blend_params.get("_blend_out_w", 0))
        out_h = int(blend_params.get("_blend_out_h", 0))
        # Final concat dims (A's native, e.g. 1280x720) — used as the target
        # for the filter_complex so A_pre and B_post don't get letterboxed
        # down to the blend's 32-snapped aspect. The blend itself is force-
        # scaled to these dims (small vertical stretch if aspect differs).
        concat_w = int(blend_params.get("_blend_concat_w", out_w))
        concat_h = int(blend_params.get("_blend_concat_h", out_h))
        out_fps = float(blend_params.get("_blend_fps", 24.0))

        if not clip_a or not clip_b or not temp_dir:
            finish_job(
                job, "failed", error="Blend assembly inputs are incomplete",
                message="Blend assembly failed",
            )
            return

        import subprocess

        transition_file = job["output_files"][0]
        out_dir = job.get("out_dir", _workspace_dir())
        transition_path = os.path.join(out_dir, transition_file)

        if not os.path.isfile(transition_path):
            print(f"[Blend] Transition file not found: {transition_path}")
            finish_job(
                job, "failed", error="Generated transition file was not found",
                message="Blend assembly failed",
            )
            return

        # ── Durations ────────────────────────────────────────────────────
        def _duration(path):
            ext = os.path.splitext(path)[1].lower()
            if ext not in (".mp4", ".mkv", ".avi", ".mov", ".webm"):
                return 0.0
            try:
                import decord
                vr = decord.VideoReader(path)
                d = len(vr) / (float(vr.get_avg_fps()) or 24.0)
                del vr
                return d
            except Exception:
                return 0.0

        dur_a = _duration(clip_a)
        dur_b = _duration(clip_b)
        a_pre_dur = max(0.0, dur_a - overlap_sec)

        print(f"[Blend] Post: A={dur_a:.2f}s (pre={a_pre_dur:.2f}s), "
              f"B={dur_b:.2f}s (post={max(0.0, dur_b - overlap_sec):.2f}s), "
              f"blend gen={out_w}x{out_h} → concat={concat_w}x{concat_h}@{out_fps:.2f}fps")

        # ── Build ffmpeg filter_complex concat pipeline ──────────────────
        # We pass A, blend, B as three separate inputs, scale+fps-normalize
        # each inside the filter graph, then concat. This avoids the concat
        # demuxer's strict codec-param matching requirements and handles
        # arbitrary input resolutions/fps cleanly.
        import datetime
        ts = datetime.datetime.now().strftime("%Y-%m-%d-%Hh%Mm%Ss")
        blend_name = f"{ts}_blend.mp4"
        blend_path = os.path.join(out_dir, blend_name)

        have_pre = a_pre_dur > 0.05
        have_post = dur_b > overlap_sec + 0.05

        # Video normalization filters — all targeting concat_w × concat_h
        # (A's native dimensions, even). Using fully-named args for scale
        # because some ffmpeg builds reject mixing positional with named.
        #
        # _norm_v: aspect-preserve + pad. Used for A_pre and B_post which
        #          are already at concat dims so it's a no-op for matching
        #          inputs; falls back to pillarbox/letterbox if B's aspect
        #          differs from A's.
        # _norm_v_stretch: force-exact scale (no aspect preserve). Used
        #          for the generated blend, which was rendered at the
        #          32-snapped (out_w, out_h) and needs a tiny stretch to
        #          fill the native concat dims without black bars. The
        #          stretch is typically <3% (e.g. 704 → 720 is 2.3%) and
        #          visually imperceptible.
        def _norm_v(label_in, label_out):
            return (
                f"[{label_in}]scale=w={concat_w}:h={concat_h}:force_original_aspect_ratio=decrease,"
                f"pad=w={concat_w}:h={concat_h}:x=(ow-iw)/2:y=(oh-ih)/2,"
                f"setsar=1,fps={out_fps:.4f},format=yuv420p[{label_out}]"
            )

        def _norm_v_stretch(label_in, label_out):
            return (
                f"[{label_in}]scale=w={concat_w}:h={concat_h},"
                f"setsar=1,fps={out_fps:.4f},format=yuv420p[{label_out}]"
            )

        # Audio normalization: resample to 48k stereo. For inputs without
        # audio we synthesize silence via `anullsrc`.
        def _norm_a(label_in, label_out, dur):
            return f"[{label_in}]aresample=48000,aformat=channel_layouts=stereo[{label_out}]"

        def _silent_a(label_out, dur):
            return f"anullsrc=channel_layout=stereo:sample_rate=48000:d={dur:.3f}[{label_out}]"

        # Assemble inputs in playback order
        inputs = []
        filter_parts = []
        concat_v_labels = []
        concat_a_labels = []
        input_idx = 0

        def _has_audio(path):
            try:
                r = subprocess.run(
                    ["ffprobe", "-v", "error", "-select_streams", "a:0",
                     "-show_entries", "stream=codec_type", "-of", "csv=p=0", path],
                    capture_output=True, text=True, timeout=10,
                )
                return "audio" in (r.stdout or "").lower()
            except Exception:
                return False

        # A_pre (trimmed A)
        if have_pre:
            inputs += ["-t", f"{a_pre_dur:.4f}", "-i", clip_a]
            filter_parts.append(_norm_v(f"{input_idx}:v:0", f"v{input_idx}"))
            concat_v_labels.append(f"v{input_idx}")
            if _has_audio(clip_a):
                filter_parts.append(_norm_a(f"{input_idx}:a:0", f"a{input_idx}", a_pre_dur))
            else:
                filter_parts.append(_silent_a(f"a{input_idx}", a_pre_dur))
            concat_a_labels.append(f"a{input_idx}")
            input_idx += 1

        # Generated blend (the transition) — full duration.
        # Force-scale to concat dims so the 32-snapped render (e.g. 1280x704)
        # fills the native frame (e.g. 1280x720) without pillar/letterboxing.
        blend_dur = overlap_sec
        inputs += ["-i", transition_path]
        filter_parts.append(_norm_v_stretch(f"{input_idx}:v:0", f"v{input_idx}"))
        concat_v_labels.append(f"v{input_idx}")
        if _has_audio(transition_path):
            filter_parts.append(_norm_a(f"{input_idx}:a:0", f"a{input_idx}", blend_dur))
        else:
            filter_parts.append(_silent_a(f"a{input_idx}", blend_dur))
        concat_a_labels.append(f"a{input_idx}")
        input_idx += 1

        # B_post (B skipped by overlap_sec)
        if have_post:
            b_post_dur = dur_b - overlap_sec
            inputs += ["-ss", f"{overlap_sec:.4f}", "-i", clip_b]
            filter_parts.append(_norm_v(f"{input_idx}:v:0", f"v{input_idx}"))
            concat_v_labels.append(f"v{input_idx}")
            if _has_audio(clip_b):
                filter_parts.append(_norm_a(f"{input_idx}:a:0", f"a{input_idx}", b_post_dur))
            else:
                filter_parts.append(_silent_a(f"a{input_idx}", b_post_dur))
            concat_a_labels.append(f"a{input_idx}")
            input_idx += 1

        if input_idx <= 1:
            # Only the blend — nothing to concat. Leave job output as-is.
            print(f"[Blend] No flanking segments; output is the blend alone ({transition_file}).")
            finish_job(
                job,
                "completed",
                progress=100,
                step=0,
                total_steps=0,
                phase="",
                message="Done",
            )
            return

        # Concat filter. ffmpeg's concat demands inputs **interleaved** as
        # per-segment (v,a) pairs: [v0][a0][v1][a1][v2][a2]concat=n=3:v=1:a=1
        # NOT grouped by stream type [v0][v1][v2][a0][a1][a2] — that causes
        # "Media type mismatch" because the concat filter reads positionally.
        n = input_idx
        pairs = "".join(
            f"[{concat_v_labels[i]}][{concat_a_labels[i]}]" for i in range(n)
        )
        filter_parts.append(f"{pairs}concat=n={n}:v=1:a=1[outv][outa]")

        filter_complex = ";".join(filter_parts)

        # Write the filter to a file and use `-/filter_complex <file>`. This
        # sidesteps any shell/argv escaping issues with long filter strings
        # containing `:` `[` `]` `(` `)` on Windows. The `-/option file`
        # syntax is ffmpeg 7+'s replacement for the deprecated
        # `-filter_complex_script`.
        filter_script_path = os.path.join(temp_dir, "concat_filter.txt")
        with open(filter_script_path, "w", encoding="utf-8", newline="\n") as f:
            f.write(filter_complex)

        cmd = [
            "ffmpeg", "-y",
            *inputs,
            "-/filter_complex", filter_script_path,
            "-map", "[outv]", "-map", "[outa]",
            "-c:v", "libx264", "-crf", "18", "-preset", "fast",
            "-c:a", "aac", "-b:a", "192k",
            "-movflags", "+faststart",
            blend_path,
        ]

        if is_cancel_requested(job):
            return
        result = subprocess.run(cmd, capture_output=True, text=True, timeout=300)
        blend_ready = result.returncode == 0 and os.path.isfile(blend_path)
        if blend_ready:
            record_job_outputs(job, [blend_name])
        if is_cancel_requested(job):
            return
        if blend_ready:
            if not update_job(job, output_files=[blend_name]):
                return
            print(f"[Blend] Concatenated {n} segments "
                  f"({'A_pre+' if have_pre else ''}blend{'+B_post' if have_post else ''}) → {blend_name}")

            # Copy metadata sidecar from transition to blend
            meta_src = os.path.join(out_dir, os.path.splitext(transition_file)[0] + ".meta.json")
            meta_dst = os.path.join(out_dir, os.path.splitext(blend_name)[0] + ".meta.json")
            if os.path.isfile(meta_src):
                import shutil
                shutil.copy2(meta_src, meta_dst)
            finish_job(
                job,
                "completed",
                progress=100,
                step=0,
                total_steps=0,
                phase="",
                message="Done",
            )
        else:
            print(f"[Blend] ffmpeg concat failed (returncode={result.returncode})")
            print(f"[Blend] filter_complex was:\n  {filter_complex}")
            print(f"[Blend] cmd: {' '.join(repr(c) for c in cmd)}")
            print(f"[Blend] stderr tail:\n{result.stderr[-800:]}")
            finish_job(
                job,
                "failed",
                error=f"Blend assembly failed (ffmpeg exit {result.returncode})",
                message="Blend assembly failed",
            )

    except Exception as e:
        import traceback
        print(f"[Blend] Concatenation failed: {e}")
        traceback.print_exc()
        finish_job(job, "failed", error=str(e), message=f"Error: {e}")
    finally:
        unregister_abort_state(job_id, _active_gen_states, assembly_state)
        if temp_dir and os.path.isdir(temp_dir):
            import shutil
            shutil.rmtree(temp_dir, ignore_errors=True)


@api.get("/api/v1/sam/status")
async def sam_status_endpoint():
    """Check if the SAM segmentation service is available."""
    from services.inpaint_service import check_sam_status
    return check_sam_status()


@api.post("/api/v1/segment/preview")
async def segment_preview_endpoint(request: Request):
    """Preview mask segmentation on a video frame.

    Body: {
        video_path: str, text: str,
        start_time?: float, end_time?: float, frame_index?: int
    }
    """
    body = await request.json()
    video_path = body.get("video_path")
    if not video_path:
        raise HTTPException(status_code=400, detail="video_path is required")
    text = body.get("text")
    if not text:
        raise HTTPException(status_code=400, detail="text is required")

    workspace = body.get("workspace") or _get_active_workspace()
    video_path = _resolve_authorized_request_media(request, video_path, workspace)
    if not video_path:
        raise HTTPException(status_code=404, detail="Video not found")

    try:
        import asyncio
        from services.inpaint_service import segment_image_preview, segment_video, ensure_sam_running

        sam_target = text

        sam_ready = await asyncio.to_thread(ensure_sam_running)
        if not sam_ready:
            raise HTTPException(status_code=503, detail="SAM service not available. Check installation.")

        full_video = body.get("full_video", False)
        if full_video:
            result = await asyncio.to_thread(
                segment_video,
                video_path=video_path,
                text=sam_target,
                start_time=float(body.get("start_time", 0)),
                end_time=float(body.get("end_time", -1)),
                mask_padding=int(body.get("mask_padding", 20)),
            )
        else:
            result = await asyncio.to_thread(
                segment_image_preview,
                video_path=video_path,
                text=sam_target,
                frame_index=body.get("frame_index", -1),
                start_time=float(body.get("start_time", 0)),
                end_time=float(body.get("end_time", -1)),
            )
        result["target"] = sam_target

        # Invert mask if requested (select everything EXCEPT the target)
        invert = body.get("invert_mask", False)
        if invert:
            # Invert the preview image: swap green overlay
            if result.get("mask_preview"):
                import base64, io
                from PIL import Image as _PILImg
                import numpy as _np
                preview_bytes = base64.b64decode(result["mask_preview"])
                img = _PILImg.open(io.BytesIO(preview_bytes)).convert("RGB")
                arr = _np.array(img)
                # Detect green overlay pixels (G channel dominant)
                green_mask = (arr[:, :, 1] > arr[:, :, 0] + 30) & (arr[:, :, 1] > arr[:, :, 2] + 30)
                # Create inverted overlay
                original = arr.copy()
                # Remove green from currently-green pixels
                arr[green_mask] = (arr[green_mask] * 2).clip(0, 255).astype(_np.uint8)  # approximate original
                # Add green to currently non-green pixels
                arr[~green_mask] = (arr[~green_mask] * 0.5 + _np.array([0, 255, 0]) * 0.5).astype(_np.uint8)
                buf = io.BytesIO()
                _PILImg.fromarray(arr).save(buf, format="PNG")
                result["mask_preview"] = base64.b64encode(buf.getvalue()).decode()

            # Invert the saved mask file
            if result.get("masks_path") and os.path.isfile(result["masks_path"]):
                import numpy as _np
                mask = _np.load(result["masks_path"])
                _np.save(result["masks_path"], ~mask)

            result["target"] = f"NOT {sam_target}"

        return result
    except RuntimeError as e:
        raise HTTPException(status_code=503, detail=str(e))
    except Exception as e:
        traceback.print_exc()
        raise HTTPException(status_code=500, detail=str(e))


@api.post("/api/v1/inpaint")
async def inpaint_endpoint(request: Request):
    """Submit a text-driven inpaint job.

    Pipeline: SAM segment → LTX retake with spatial mask.

    Body: {
        video_path: str, description: str,
        start_time?: float, end_time?: float,
        model_type: str, retake_strength?: float,
        seed?: int, guidance_scale?: float, num_inference_steps?: int,
        negative_prompt?: str, mask_padding?: int, workspace?: str
    }
    """
    body = await request.json()
    video_path = body.get("video_path")
    if not video_path:
        raise HTTPException(status_code=400, detail="video_path is required")
    description = body.get("description")
    if not description:
        raise HTTPException(status_code=400, detail="description is required")
    model_type = body.get("model_type")
    if not model_type:
        raise HTTPException(status_code=400, detail="model_type is required")

    workspace = body.get("workspace") or _get_active_workspace()
    job_out_dir = _require_project_access(request, workspace)
    video_path = _resolve_authorized_request_media(request, video_path, workspace)
    if not video_path:
        raise HTTPException(status_code=404, detail="Video not found")

    from services.inpaint_service import check_sam_status, parse_inpaint_intent, segment_video, unload_sam, ensure_sam_running, shutdown_sam

    start_time = float(body.get("start_time", 0))
    end_time = float(body.get("end_time", -1))
    mask_padding = int(body.get("mask_padding", 20))
    cached_masks_path = body.get("masks_path")

    # Step 1: Determine SAM target and LTX prompt
    # If user provided explicit sam_target, use it directly (no LLM parsing needed)
    explicit_sam_target = body.get("sam_target", "").strip()
    if explicit_sam_target:
        sam_target = explicit_sam_target
        intent = {"target": sam_target, "prompt": description, "negative_prompt": ""}
        print(f"[Inpaint] Using explicit SAM target: '{sam_target}'")
    else:
        try:
            intent = parse_inpaint_intent(description)
            sam_target = intent["target"]
        except Exception as e:
            traceback.print_exc()
            intent = {"target": description, "prompt": description, "negative_prompt": ""}
            sam_target = description

    # Pre-scale video for SAM if user selected a lower resolution
    # This reduces SAM VRAM/time and produces a correctly-sized mask for LTX
    sam_video_path = video_path
    _sam_scaled_path = None
    user_res = body.get("resolution", "")
    if user_res and "x" in user_res:
        try:
            user_w, user_h = int(user_res.split("x")[0]), int(user_res.split("x")[1])
            if user_w > 0 and user_h > 0 and (user_w < src_w or user_h < src_h):
                # Aspect-preserving scale (same logic as retake)
                max_dim = max(user_h, user_w)
                src_max = max(src_h, src_w)
                if src_max > max_dim:
                    scale = max_dim / src_max
                    scaled_h = (int(src_h * scale) // 32) * 32
                    scaled_w = (int(src_w * scale) // 32) * 32
                    import subprocess as _sp
                    _sam_scaled_path = video_path.rsplit('.', 1)[0] + "_sam_scaled.mp4"
                    _sp.run([
                        "ffmpeg", "-y", "-i", video_path,
                        "-vf", f"scale={scaled_w}:{scaled_h}:flags=lanczos",
                        "-c:v", "libx264", "-crf", "18", "-preset", "fast",
                        "-an", _sam_scaled_path
                    ], capture_output=True, timeout=120)
                    if os.path.isfile(_sam_scaled_path):
                        sam_video_path = _sam_scaled_path
                        print(f"[Inpaint] Pre-scaled video for SAM: {src_w}x{src_h} → {scaled_w}x{scaled_h}")
        except Exception as e:
            print(f"[Inpaint] Pre-scale warning (non-fatal): {e}")

    # Step 2: SAM segmentation (skip if cached mask provided)
    if cached_masks_path and os.path.isfile(cached_masks_path):
        masks_path = cached_masks_path
        print(f"[Inpaint] Using cached mask: {masks_path}")
    else:
        # Start SAM on demand if needed
        import asyncio
        sam_ready = await asyncio.to_thread(ensure_sam_running)
        if not sam_ready:
            raise HTTPException(status_code=503, detail="SAM service not available. Check installation.")
        try:
            seg_result = await asyncio.to_thread(
                segment_video,
                video_path=sam_video_path,
                text=sam_target,
                start_time=start_time,
                end_time=end_time,
                mask_padding=mask_padding,
            )
            masks_path = seg_result.get("masks_path")
            if not masks_path:
                raise HTTPException(status_code=500, detail="SAM returned no mask data")
            # Invert mask if requested
            if body.get("invert_mask") and os.path.isfile(masks_path):
                import numpy as _np
                mask = _np.load(masks_path)
                _np.save(masks_path, ~mask)
                print(f"[Inpaint] Mask inverted (selecting everything except '{sam_target}')")
        except RuntimeError as e:
            raise HTTPException(status_code=503, detail=str(e))

    # Clean up scaled video
    if _sam_scaled_path and os.path.isfile(_sam_scaled_path):
        try: os.remove(_sam_scaled_path)
        except OSError: pass

    # Step 2b: Shut down SAM completely to free all VRAM (including CUDA context)
    try:
        import asyncio
        await asyncio.to_thread(shutdown_sam)
    except Exception:
        pass

    # Step 3: Build retake params with spatial mask
    try:
        import decord
        vr = decord.VideoReader(video_path)
        fps = vr.get_avg_fps()
        total_frames = len(vr)
        src_h, src_w = vr[0].shape[:2]
        del vr
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"Cannot read video: {e}")

    start_frame = max(0, int(start_time * fps))
    end_frame = int(end_time * fps) if end_time > 0 else total_frames
    end_frame = min(end_frame, total_frames)

    # Use user's resolution if provided, otherwise source
    resolution = body.get("resolution") or f"{src_w}x{src_h}"

    # CFG default bumped 1.0 → 3.5 for inpaint. At 1.0 the retake pipeline
    # runs a single unconditional pass, so the prompt barely influences the
    # regenerated masked region — the output looks ~identical to the source.
    # CFG > 1.0 triggers dual (positive + negative) prompt encoding inside
    # retake.py's new CFG branch, enabling prompt-driven replacement.
    _inpaint_cfg = float(body.get("guidance_scale", 3.5))
    _inpaint_steps = int(body.get("num_inference_steps", 8))
    _inpaint_retake_strength = float(body.get("retake_strength", 0.85))
    # Inpaint-specific default negative prompt. Distilled LTX-2.3's positive
    # and unconditional predictions are nearly identical, so CFG with an
    # empty negative gives `delta = (cond - uncond) ≈ 0` — no push. A concrete
    # negative prompt describing what we DON'T want (dull/static/unchanged)
    # gives the model a direction to move away from, making CFG actually
    # bite. User's explicit negative_prompt (if any) overrides this default.
    DEFAULT_INPAINT_NEG = (
        "unchanged, identical to source, no change, static pose, dull, plain, "
        "low detail, blurry, distorted, artifacts, extra limbs"
    )
    _inpaint_neg = (
        intent.get("negative_prompt")
        or body.get("negative_prompt")
        or DEFAULT_INPAINT_NEG
    )
    print(f"[Inpaint] CFG={_inpaint_cfg:.2f}, steps={_inpaint_steps}, retake_strength={_inpaint_retake_strength:.2f}, "
          f"prompt='{intent['prompt'][:60]}', neg='{_inpaint_neg[:60]}'")
    gen_params = {
        "prompt": intent["prompt"],
        "model_type": model_type,
        "negative_prompt": _inpaint_neg,
        "seed": body.get("seed", -1),
        "guidance_scale": _inpaint_cfg,
        "num_inference_steps": _inpaint_steps,
        "video_length": total_frames,
        "resolution": resolution,
        "activated_loras": body.get("activated_loras", []),
        "loras_multipliers": " ".join(m.split(";")[0] for m in (body.get("loras_multipliers", "") or "").split()),
        "generation_mode": "video",
        # Tag for the gallery's Edits filter + Load Settings restore path.
        "edit_sub_mode": "inpaint",
        "retake_video": video_path,
        "retake_start_frame": start_frame,
        "retake_end_frame": end_frame,
        "retake_strength": _inpaint_retake_strength,
        "retake_masks_path": masks_path,  # spatial mask from SAM
        "retake_engine": body.get("retake_engine", "native"),  # native pipeline with SpatialRegionMask
        "stage2_steps": body.get("stage2_steps", 3),
        # Set sliding window to cover full video — retake needs single pass
        "sliding_window_size": total_frames + 10,  # +10 buffer to ensure no split
        "settings_version": 2.52,  # prevent fix_settings from deleting sliding_window_size
        # Track restore-able fields for the UI.
        "edit_video_path": video_path,
        "edit_target": intent.get("target"),
        "edit_start_time": start_time,
        "edit_end_time": end_time if end_time > 0 else (total_frames / fps if fps else 0),
    }

    job_id = uuid.uuid4().hex[:8]
    job = {
        "id": job_id, "status": "queued", "progress": 0, "step": 0, "total_steps": 0,
        "phase": "inpaint", "message": f"Inpaint queued: {intent['target']}",
        "created_at": time.time(),
        "params": gen_params, "output_files": [], "error": None,
        "workspace": workspace, "out_dir": job_out_dir,
    }
    _queue_recovery_register_and_publish(job)

    return {"job_id": job_id, "status": "queued", "target": intent["target"], "prompt": intent["prompt"]}


def _apply_film_grain_to_file(video_path: str, intensity: float, saturation: float):
    """Apply film grain to an already-saved video file (post-generation).

    Reads frames with decord, applies grain on GPU if available, re-encodes
    in-place using the same codec settings.

    decord bridge state is restored to 'native' in a finally so subsequent
    code paths that index a VideoReader expecting decord.NDArray
    (`.asnumpy()`) — notably the retake pipeline at ltx2.py — don't break.
    Bug history: setting the bridge here without restoring caused every
    retake AFTER any film-grain-bearing generation to fail with
    `'Tensor' object has no attribute 'asnumpy'`. The retake side now
    has a defensive helper for the same case, but cleaning up here is
    the proper fix at the source.
    """
    import torch
    import decord
    from postprocessing.film_grain import add_film_grain
    from shared.utils.audio_video import save_video
    decord.bridge.set_bridge('torch')
    try:
        return _apply_film_grain_to_file_impl(video_path, intensity, saturation,
                                              torch=torch, decord=decord,
                                              add_film_grain=add_film_grain,
                                              save_video=save_video)
    finally:
        # Always restore decord's default bridge so downstream readers
        # (retake, director renderers, etc.) get decord.NDArray results.
        try:
            decord.bridge.set_bridge('native')
        except Exception:
            pass


def _apply_film_grain_to_file_impl(video_path: str, intensity: float, saturation: float,
                                   *, torch, decord, add_film_grain, save_video):
    """Body of _apply_film_grain_to_file. Extracted so the bridge-restore
    finally above can wrap the entire body cleanly without re-indenting
    the existing implementation."""

    reader = decord.VideoReader(video_path)
    fps = round(reader.get_avg_fps())
    # Read all frames as uint8 tensor [F, H, W, C]
    frames = reader.get_batch(range(len(reader)))
    # Rearrange to [C, F, H, W] as expected by add_film_grain
    frames = frames.permute(3, 0, 1, 2)
    # Free GPU memory from the generation model before using it for film grain
    if torch.cuda.is_available():
        import gc
        gc.collect()
        torch.cuda.empty_cache()
    # Try GPU first, fall back to CPU if OOM
    try:
        device = torch.device('cuda' if torch.cuda.is_available() else 'cpu')
        frames_dev = frames.to(device)
        frames = add_film_grain(frames_dev, intensity, saturation).cpu()
        del frames_dev
        if torch.cuda.is_available():
            torch.cuda.empty_cache()
    except torch.cuda.OutOfMemoryError:
        print("  [Film Grain] GPU OOM, falling back to CPU")
        if torch.cuda.is_available():
            torch.cuda.empty_cache()
        frames = add_film_grain(frames, intensity, saturation)
    # Check if source has audio track to preserve it
    has_audio = False
    audio_tmp = None
    try:
        import subprocess
        probe = subprocess.run(
            ['ffprobe', '-v', 'quiet', '-select_streams', 'a', '-show_entries', 'stream=codec_type', '-of', 'csv=p=0', video_path],
            capture_output=True, text=True, timeout=10
        )
        has_audio = 'audio' in probe.stdout
        if has_audio:
            import tempfile
            audio_tmp = tempfile.mktemp(suffix='.aac')
            subprocess.run(
                ['ffmpeg', '-y', '-i', video_path, '-vn', '-acodec', 'copy', audio_tmp],
                capture_output=True, timeout=60
            )
    except Exception:
        has_audio = False
    # Save back — save_video expects [B, C, F, H, W] for the uint8 fast path
    codec_type = wgp.server_config.get("video_output_codec", "libx264_8")
    container = wgp.server_config.get("video_container", "mp4")
    tmp_path = video_path + ".grain_tmp." + container
    # frames is [C, F, H, W] uint8 — save_video has a uint8 fast path (no normalize needed)
    save_video(tensor=frames.unsqueeze(0), save_file=tmp_path, fps=fps, nrow=1,
               normalize=False, codec_type=codec_type, container=container)
    def _replace_with_retry(src, dst, max_retries=5):
        """Replace file with retry loop for Windows file locking."""
        import gc
        for attempt in range(max_retries):
            try:
                os.replace(src, dst)
                return
            except (PermissionError, OSError) as e:
                if attempt < max_retries - 1:
                    gc.collect()
                    time.sleep(1)
                else:
                    raise

    # Mux audio back if present
    if has_audio and audio_tmp and os.path.exists(audio_tmp):
        try:
            import subprocess
            muxed_path = video_path + ".muxed." + container
            subprocess.run(
                ['ffmpeg', '-y', '-i', tmp_path, '-i', audio_tmp, '-c:v', 'copy', '-c:a', 'aac', '-shortest', muxed_path],
                capture_output=True, timeout=120
            )
            _replace_with_retry(muxed_path, video_path)
            os.remove(tmp_path)
        except Exception:
            _replace_with_retry(tmp_path, video_path)
        finally:
            if os.path.exists(audio_tmp):
                os.remove(audio_tmp)
    else:
        _replace_with_retry(tmp_path, video_path)


# ── Per-job VRAM coefficient adjustment ────────────────────────────
# Auto-tune sets a single base coefficient (e.g. 0.80 for a 24 GB
# card) but real jobs vary in memory pressure based on:
#   - LoRA stack size (each LoRA adds ~its file size in VRAM)
#   - Pipeline stage count (each extra stage holds latents resident)
#
# This helper lowers wgp.args.vram_safety_coefficient temporarily for
# the duration of a single job so heavier jobs get a tighter cap and
# more aggressive offloading. The base is restored after the job so
# subsequent lighter jobs aren't penalized.
#
# The effective coefficient is part of WGP's load configuration and opaque
# residency identity. A changed coefficient therefore triggers one safe MMGP
# reprofile instead of silently reusing an incompatible cached budget.
#
# The hardware probe (for total VRAM) is cached at module level — the
# answer doesn't change at runtime and detect_hardware() touches torch
# which we'd rather not call per-job.
_cached_hardware: dict | None = None


def _get_cached_hardware() -> dict:
    global _cached_hardware
    if _cached_hardware is None:
        try:
            from services.hardware_detect import detect_hardware
            _cached_hardware = detect_hardware()
        except Exception as e:
            print(f"[VRAM] hardware probe failed ({e}); per-job adjustment disabled")
            _cached_hardware = {"gpu_vram_gb": 0.0}
    return _cached_hardware


def _stage_count_from_params(params: dict) -> int:
    """Translate the user's pipeline-mode flags to a stage count.

    UI exposes three options:
      Single (1 stage)     → single_stage_pipeline=True
      Standard (2 stages)  → both flags False (the default)
      Progressive (3)      → progressive_pipeline=True

    Image-mode jobs (HiDream, Flux 2 Klein, Qwen Image) don't run through
    a multi-stage pipeline — they're single-pass. The "standard 2 stages"
    default only applies to video models (LTX-2 distilled, etc.). Returning
    2 for image jobs was triggering a phantom -0.083 coefficient penalty
    (and ~1.3 GB cap shrink) that did nothing useful and possibly caused
    HiDream's int8 quanto load path to mis-handle layer offload.
    """
    if params.get("image_mode", 0) and int(params.get("image_mode", 0)) > 0:
        return 1
    if params.get("progressive_pipeline"):
        return 3
    if params.get("outpaint_full_resolution_refine"):
        return 2
    if params.get("single_stage_pipeline"):
        return 1
    return 2


def _apply_per_job_coefficient(
    job: dict,
    *,
    apply: bool = True,
) -> dict | None:
    """Compute and apply a per-job VRAM safety coefficient.

    Mutates `wgp.args.vram_safety_coefficient` for the duration of the
    job so wgp's offload profile uses the tighter cap. Restored by
    `_restore_base_coefficient()` in the job's finally block.

    Records the result on `job` so the API/UI can surface it:
      job["vram_adjustment"] = {
          base_coef, effective_coef, lora_total_gb,
          lora_penalty, pass_penalty, stage_count, reasons
      }
    """
    try:
        from services.perf_recommend import compute_per_job_coefficient

        params = job.get("params") or {}

        # SFX (mmaudio) jobs don't go through the LoRA / stage pipeline —
        # nothing to adjust.
        if params.get("sfx_mode"):
            return None

        base_coef = float(
            wgp.server_config.get("vram_safety_coefficient", 0.80)
        )
        hw = _get_cached_hardware()
        total_vram_gb = float(hw.get("gpu_vram_gb", 0.0))
        if total_vram_gb <= 0:
            return None  # no VRAM info → can't adjust safely

        active_loras = list(params.get("activated_loras") or [])
        model_type = params.get("model_type")
        lora_dir = None
        if model_type:
            try:
                lora_dir = wgp.get_lora_dir(model_type)
            except Exception:
                lora_dir = None

        stage_count = _stage_count_from_params(params)
        resolution = params.get("resolution")
        # video_length is in frames (Maestro convention). For images
        # video_length is typically 1 — the helper handles both.
        video_length = params.get("video_length")
        try:
            video_length = int(video_length) if video_length is not None else None
        except (TypeError, ValueError):
            video_length = None

        # Director long-form jobs pass video_length = TOTAL movie frames
        # (e.g. 5400 for a 3-minute film), but the per-denoising-step
        # VRAM peak is bounded by sliding_window_size — wgp only holds
        # one window's worth of latents and activations on the GPU at
        # a time. Without this clamp, compute_per_job_coefficient sees
        # 5400 frames worth of "compute size" and applies an aggressive
        # (and wrong) penalty that pushes the safety coefficient too low,
        # shrinking the cap and forcing unnecessary offload during
        # Director video gen. Clamping here makes the calc correctly
        # size against the actual per-step working set.
        #
        # Studio single-shot jobs typically have video_length ≤
        # sliding_window_size, so the clamp is a no-op there.
        # Image jobs have video_length = 1 and no sliding window —
        # also a no-op.
        sliding_window_size = params.get("sliding_window_size")
        try:
            sliding_window_size = (
                int(sliding_window_size) if sliding_window_size is not None else None
            )
        except (TypeError, ValueError):
            sliding_window_size = None
        effective_frames = video_length
        if (
            sliding_window_size
            and sliding_window_size > 0
            and effective_frames
            and effective_frames > sliding_window_size
        ):
            effective_frames = sliding_window_size

        # SCAIL-2 activation surcharge. The model appends the driving
        # video as in-context tokens (~25% extra sequence) and prepends
        # reference latents, so its attention working set is far larger
        # than resolution × frames predicts — the generic compute curve
        # rates a 480p SCAIL-2 window "lighter than baseline" and
        # LOOSENS the cap. Measured on a 24GB RTX 4090: a 49-frame
        # 848x480 window peaked at 23.1GB under a 17.8GB weight cap
        # (~5.3GB activations); an 81-frame window extrapolates to
        # ~8.5GB activations and overflowed 24GB in the field
        # (user-reported OOM, 2026-07-17). Surcharge = 6GB at the
        # 848x480 x 81-frame reference, scaled linearly by window
        # pixels x frames, so the freed VRAM tracks the actual
        # activation need.
        model_activation_gb = 0.0
        try:
            _base_mt = wgp.get_base_model_type(model_type) if model_type else None
        except Exception:
            _base_mt = None
        if _base_mt in ("scail2_14B", "scail2_1.3B"):
            _ref_pixels, _ref_frames = 848 * 480, 81
            _pixels = _ref_pixels
            if isinstance(resolution, str) and "x" in resolution:
                try:
                    _w, _h = resolution.lower().split("x")
                    _pixels = int(_w) * int(_h)
                except (ValueError, TypeError):
                    pass
            _frames = effective_frames or _ref_frames
            model_activation_gb = 6.0 * (_pixels / _ref_pixels) * (_frames / _ref_frames)

        adjustment = compute_per_job_coefficient(
            base_coef=base_coef,
            total_vram_gb=total_vram_gb,
            active_loras=active_loras,
            lora_dir=lora_dir,
            stage_count=stage_count,
            resolution=resolution,
            video_length_frames=effective_frames,
            model_activation_gb=model_activation_gb,
        )
        # The dedicated upstream SCAIL-2 transformer uses the official
        # attention/token layout instead of WanGP's generalized fused path.
        # Its measured peak is healthy when transformer residency is held to
        # roughly 7 GB on a 24 GB card; allowing the ordinary coefficient
        # floor to keep 10-12 GB resident leaves too little attention
        # workspace and makes WDDM spill into shared memory (minutes per
        # denoise step). MMGP streams the remaining weights efficiently.
        dedicated_scail2 = (
            _base_mt in ("scail2_14B", "scail2_1.3B")
            and os.environ.get(
                "MAESTRO_SCAIL2_DEDICATED_MODEL", "1",
            ).strip().lower() not in {"0", "false", "no", "off"}
        )
        if dedicated_scail2:
            dedicated_weight_budget_gb = min(
                16.0,
                max(3.5, total_vram_gb - 17.0),
            )
            dedicated_coefficient_cap = (
                dedicated_weight_budget_gb / total_vram_gb
            )
            if adjustment["effective_coef"] > dedicated_coefficient_cap:
                adjustment["effective_coef"] = dedicated_coefficient_cap
                adjustment["floored"] = False
                adjustment["reasons"].append(
                    f"- dedicated SCAIL-2 transformer residency capped at "
                    f"{dedicated_weight_budget_gb:.1f} GB to preserve "
                    "attention workspace"
                )
            adjustment["dedicated_scail2_budget_gb"] = (
                dedicated_weight_budget_gb
            )
        job["vram_adjustment"] = adjustment

        effective = adjustment["effective_coef"]
        if apply and abs(effective - base_coef) > 1e-6:
            wgp.args.vram_safety_coefficient = effective
            cap_gb = effective * total_vram_gb
            base_cap_gb = base_coef * total_vram_gb
            # Log the frame-clamp explicitly when it fired so a future
            # "why is the coefficient X" question has data right next
            # to the answer.
            clamp_note = ""
            if (
                video_length and effective_frames
                and effective_frames < video_length
            ):
                clamp_note = (
                    f" [frames clamped {video_length}→{effective_frames} "
                    f"via sliding_window_size]"
                )
            print(
                f"[VRAM] Job {job.get('id', '?')}: coefficient "
                f"{base_coef:.2f} → {effective:.3f} "
                f"(cap {base_cap_gb:.1f}GB → {cap_gb:.1f}GB){clamp_note}"
            )
            for reason in adjustment["reasons"]:
                print(f"[VRAM]   {reason}")
        return adjustment
    except Exception as e:
        # Never let a coefficient-adjustment bug fail the job.
        print(f"[VRAM] per-job adjustment failed: {e}")
        return None


def _first_requested_generation_model(params: dict) -> str:
    """Return the first checkpoint the queued job will actually load."""
    plan = params.get("_h3_longform")
    if isinstance(plan, dict):
        segments = plan.get("segment_models")
        if isinstance(segments, list) and segments:
            first = segments[0]
            if isinstance(first, dict) and first.get("model_type"):
                return str(first["model_type"])
    return str(params.get("model_type") or "")


def _requested_vae_residency_setting(
    params: dict,
    model_type: str,
):
    """Mirror WGP's load-time VAE upsampler selection without model work."""
    model_def = wgp.get_model_def(model_type) or {}
    supported_modes = model_def.get("vae_upsampler")
    if supported_modes is None:
        return None
    try:
        image_mode = int(params.get("image_mode", 0) or 0)
    except (TypeError, ValueError):
        image_mode = 0
    spatial_upsampling = str(params.get("spatial_upsampling") or "")
    if image_mode not in supported_modes or "vae" not in spatial_upsampling:
        return None
    return spatial_upsampling


def _residency_request_params(params: dict) -> dict | None:
    """Return a non-mutating view of the first effective generation task."""
    model_type = str(params.get("model_type") or "")
    if model_type not in _H3_LONG_STUDIO_MODELS or isinstance(
        params.get("_h3_longform"), dict,
    ):
        return params
    candidate = dict(params)
    try:
        _apply_h3_adaptive_checkpoint(candidate)
        _prepare_h3_long_studio_request(candidate)
    except (TypeError, ValueError):
        # The worker will publish the detailed validation error. An invalid
        # request must not influence otherwise valid queue residency order.
        return None
    return candidate


def _stamp_requested_generation_residency(
    job: dict,
    *,
    replace: bool = False,
) -> bool:
    """Serialize identity derivation/stamping with live config mutations."""
    with residency_configuration_update():
        return _stamp_requested_generation_residency_locked(
            job, replace=replace,
        )


def _stamp_requested_generation_residency_locked(
    job: dict,
    *,
    replace: bool = False,
) -> bool:
    """Stamp a truthful base-only load identity before queue admission.

    LoRA affinity is intentionally omitted: the runtime currently proves only
    base-model residency.  A dry-run of the same per-job VRAM policy used at
    admission supplies the coefficient MMGP will profile, without mutating the
    process-global coefficient while another job may still be running.
    """
    if job.get("status") != "queued" or (
        job.get("residency_base_key") and not replace
    ):
        return False
    if replace:
        clear_job_residency(job)
    params = job.get("params")
    if not isinstance(params, dict) or params.get("sfx_mode"):
        return False
    identity_params = _residency_request_params(params)
    if identity_params is None:
        return False
    model_type = _first_requested_generation_model(identity_params)
    if not model_type or wgp.get_model_def(model_type) is None:
        return False
    adjustment = _apply_per_job_coefficient(job, apply=False)
    try:
        effective_coefficient = float(
            (adjustment or {}).get(
                "effective_coef",
                wgp.server_config.get("vram_safety_coefficient", 0.80),
            )
        )
    except (TypeError, ValueError):
        return False
    override_profile = identity_params.get("override_profile", -1)
    if override_profile is None:
        override_profile = -1
    image_mode = identity_params.get("image_mode", 0)
    try:
        image_mode = int(image_mode or 0)
    except (TypeError, ValueError):
        image_mode = 0
    base_key, _ = wgp.get_requested_residency_identity(
        model_type,
        override_profile=override_profile,
        output_type=wgp.get_output_type_for_model(model_type, image_mode),
        vae_setting=_requested_vae_residency_setting(
            identity_params, model_type,
        ),
        affinity_components=None,
        vram_safety_coefficient=effective_coefficient,
    )
    if not base_key:
        return False
    try:
        stamp_job_residency(job, base_key)
    except ValueError:
        # The job may have crossed into running/cancelled between the pure
        # computation and the lifecycle-owned atomic stamp.
        return False
    return True


def _restamp_queued_generation_residency() -> int:
    """Refresh queued keys after a live load-configuration mutation."""
    refreshed = 0
    for job in list(_jobs.values()):
        if _stamp_requested_generation_residency(job, replace=True):
            refreshed += 1
    return refreshed


def _restore_base_coefficient() -> None:
    """Restore wgp.args.vram_safety_coefficient to the persisted base.

    Called from the finally block in `_run_generation` and
    `_run_sfx_generation` so subsequent jobs start from the user's
    auto-tuned base, not a previous job's adjusted value.
    """
    try:
        base = float(wgp.server_config.get("vram_safety_coefficient", 0.80))
        wgp.args.vram_safety_coefficient = base
    except Exception:
        pass  # Never fail teardown


def _run_sfx_generation(job: dict, raw_params: dict, start_time: float):
    """Run standalone MMAudio SFX generation (called from _run_generation when sfx_mode is set).

    Handles two modes:
    - Video-guided: upload a video clip → MMAudio generates matching SFX audio
    - Text-only: prompt + duration → MMAudio generates audio from text description
    """
    try:
        if is_cancel_requested(job):
            return False
        if not update_job(
            job, message="Preparing MMAudio...", phase="Preparing MMAudio",
        ):
            return False

        out_dir = job.get("out_dir") or wgp.save_path
        os.makedirs(out_dir, exist_ok=True)
        wgp.save_path = out_dir
        print(f"[SFX {job.get('job_id', '')}] save_path locked to: {out_dir}")
        before = set(os.listdir(out_dir)) if os.path.isdir(out_dir) else set()

        variant = raw_params.get("_mmaudio_variant")
        prompt = raw_params.get("MMAudio_prompt", "") or raw_params.get("prompt", "")
        neg_prompt = raw_params.get("MMAudio_neg_prompt", "")
        seed = raw_params.get("seed", -1)
        duration = raw_params.get("duration_seconds", 10)
        text_weight = float(raw_params.get("sfx_text_weight", 1.0))
        video_path = raw_params.get("video_guide") or None  # Normalize empty string to None

        # Resolve video_guide path if it's a relative upload path
        if video_path and not os.path.isabs(video_path):
            candidate = os.path.join("uploads", video_path)
            if os.path.isfile(candidate):
                video_path = candidate

        if video_path and not os.path.isfile(video_path):
            print(f"[SFX] Warning: video_guide not found: {video_path}, falling back to text-only")
            video_path = None

        # If video provided, derive duration from it
        if video_path:
            try:
                import decord
                vr = decord.VideoReader(video_path)
                fps = vr.get_avg_fps()
                duration = len(vr) / fps if fps > 0 else duration
                del vr
                print(f"[SFX] Video: {video_path} ({duration:.1f}s)")
            except Exception as e:
                print(f"[SFX] Could not read video duration: {e}")
        else:
            # MMAudio generates max ~20s per pass (VRAM and quality constraints)
            MAX_SFX_DURATION = 20.0
            if duration > MAX_SFX_DURATION:
                print(f"[SFX] Text-only: capping duration from {duration}s to {MAX_SFX_DURATION}s (MMAudio limit)")
                duration = MAX_SFX_DURATION
            print(f"[SFX] Text-only mode, duration={duration}s")

        # Get MMAudio settings with variant override
        mmaudio_enabled, _, mmaudio_persistence, mmaudio_model_name, mmaudio_model_path = \
            wgp.get_mmaudio_settings(wgp.server_config, variant_override=variant)

        if not mmaudio_enabled and variant is None:
            finish_job(
                job,
                "failed",
                error="MMAudio is not enabled in server configuration",
                message="Error: MMAudio not enabled. Enable it in Settings → Extensions.",
            )
            return False

        # Download model files if needed
        if not update_job(
            job, message="Downloading MMAudio models...", phase="Downloading models",
        ):
            return False
        wgp.download_mmaudio(variant_override=variant)
        if is_cancel_requested(job):
            return False

        # Generate output filename — .mp4 when remuxing onto video, .wav for text-only
        seed_val = seed if seed >= 0 else int(time.time()) % 100000
        safe_prompt = "".join(c if c.isalnum() or c in " _-" else "" for c in (prompt or "sfx"))[:40].strip().replace(" ", "_")
        has_video = video_path is not None
        out_ext = ".mp4" if has_video else ".wav"
        base_filename = f"sfx_{safe_prompt}_{seed_val}{out_ext}"
        output_path = wgp.get_available_filename(out_dir, base_filename, force_extension=out_ext)

        # Run MMAudio
        if not update_job(
            job,
            message="Generating sound effects...",
            phase="MMAudio Generation",
            progress=10,
        ):
            return False
        print(f"[SFX] Running MMAudio: prompt='{prompt}', neg='{neg_prompt}', "
              f"duration={duration:.1f}s, model={mmaudio_model_name}, video={'yes' if video_path else 'no'}")

        from postprocessing.mmaudio.mmaudio import video_to_audio
        persist = mmaudio_persistence == wgp.MMAUDIO_PERSIST_RAM

        video_to_audio(
            video=video_path,  # None for text-only mode
            prompt=prompt,
            negative_prompt=neg_prompt,
            seed=seed,
            num_steps=25,
            cfg_strength=float(raw_params.get("guidance_scale", 4.5)),
            duration=duration,
            save_path=output_path,
            persistent_models=persist,
            audio_file_only=not has_video,  # Remux onto video when provided, WAV-only for text mode
            model_name=mmaudio_model_name,
            model_path=mmaudio_model_path,
            text_weight=text_weight,
        )
        # Publish files even when cancellation arrived during MMAudio's
        # non-cooperative call; terminal status/message remain untouched.
        after = set(os.listdir(out_dir)) if os.path.isdir(out_dir) else set()
        new_files = sorted(after - before)
        record_job_outputs(job, new_files)
        if is_cancel_requested(job):
            return False

        # Save sidecar metadata
        elapsed = time.time() - start_time
        for fname in new_files:
            ext = os.path.splitext(fname)[1].lower()
            if ext not in GENERATED_MEDIA_EXTENSIONS:
                continue
            sidecar = {
                "params": {
                    "prompt": prompt,
                    "MMAudio_prompt": prompt,
                    "MMAudio_neg_prompt": neg_prompt,
                    "seed": seed,
                    "model_type": f"mmaudio_{variant or 'v2'}",
                    "duration_seconds": duration,
                    "sfx_mode": True,
                },
                "upload_filenames": {"video_guide": os.path.basename(video_path)} if video_path else {},
                "generation_mode": "video" if ext in {".mp4", ".mkv", ".mov", ".webm"} else "audio",
                "job_id": job.get("id", ""),
                "generation_time": round(elapsed),
                "created_at": time.time(),
                "output_filename": fname,
            }
            stamp_sidecar_policy(
                sidecar,
                job.get("access_policy") or {},
                workspace=job.get("workspace") or "default",
            )
            meta_path = os.path.join(out_dir, os.path.splitext(fname)[0] + ".meta.json")
            try:
                temp_meta = f"{meta_path}.{uuid.uuid4().hex[:8]}.tmp"
                with open(temp_meta, "w", encoding="utf-8") as f:
                    json.dump(sidecar, f, indent=2)
                    f.flush()
                    os.fsync(f.fileno())
                os.replace(temp_meta, meta_path)
            except Exception as sidecar_error:
                try:
                    os.remove(temp_meta)
                except (OSError, UnboundLocalError):
                    pass
                media_path = os.path.join(out_dir, fname)
                quarantine = os.path.join(
                    out_dir, f".private-sidecar-failed-{uuid.uuid4().hex[:8]}",
                )
                try:
                    os.replace(media_path, quarantine)
                except OSError:
                    try:
                        os.remove(media_path)
                    except OSError:
                        pass
                raise RuntimeError(
                    f"Failed to publish protected SFX metadata for {fname}"
                ) from sidecar_error

        completed = finish_job(
            job,
            "completed",
            progress=100,
            step=0,
            total_steps=0,
            phase="",
            message="Done",
        )
        print(f"[SFX] Completed in {wgp.format_time(elapsed)}: {output_path}")
        return completed

    except Exception as e:
        traceback.print_exc()
        failure_updates = {"error": str(e), "message": f"Error: {e}"}
        # Tag the failure with OOM info if applicable so the UI can
        # surface the OOM recovery banner. detect_oom returns None
        # for non-OOM failures, in which case oom_info stays absent.
        try:
            from services.oom_detect import detect_oom
            _coef = float(wgp.server_config.get("vram_safety_coefficient", 0.80))
            _oom = detect_oom(e, _coef)
            if _oom:
                failure_updates["oom_info"] = _oom
        except Exception:
            pass  # Never fail a failure handler
        finish_job(job, "failed", **failure_updates)
        return False


def _chunked_flashvsr_upscale(video_path: str, method: str, *, job: dict = None, abort_check=None, progress_callback=None):
    """Chunked FlashVSR upscale of a saved video -> tmp VIDEO-ONLY file.

    Shared engine for the post-generation in-place pass
    (_apply_spatial_upsampling_to_file) and Tools -> Upscale
    (_run_tool_upscale).

    LONG videos are processed in bounded-RAM chunks: FlashVSR's output
    accumulates as float32 at full output resolution, so an unchunked
    4-minute 2x upscale tries to allocate 280+ GB of RAM. Each chunk is
    read with an 11-frame overlap and chained through FlashVSR's
    continue_cache (its native tail-handoff for seamless segment
    continuation), encoded to a segment file immediately to free the
    buffer, and the segments are stream-copy concatenated (same encoder
    settings -> frame-accurate). The FlashVSR models are kept resident
    across chunks regardless of the persistence setting, then released
    per the user's setting.

    Returns the tmp file path (NO audio track) — the caller owns audio
    muxing, final placement, and deleting the tmp. Returns None when
    aborted via abort_check. Raises on failure.
    """
    import gc
    import math
    import subprocess
    import torch

    from shared.utils.utils import get_video_info
    from postprocessing.flashvsr.runtime import FLASHVSR_CONTINUE_CACHE_FRAMES

    fps, width, height, total_frames = get_video_info(video_path)
    scale = wgp.flashvsr.scale_for_upsampling(method) or 2.0
    out_h, out_w = max(1, int(height * scale)), max(1, int(width * scale))

    # Direct bridge calls bypass perform_spatial_upsampling, so replicate
    # its live sync of the React Settings panel values (services.*) onto
    # the top-level keys the bridge reads — BEFORE the variant-dependent
    # chunk sizing below.
    _svc = wgp.server_config.get("services", {})
    for _k in ("flashvsr_mode", "flashvsr_topk_ratio", "flashvsr_backend"):
        if _k in _svc:
            wgp.server_config[_k] = _svc[_k]

    # Chunk length bounds the per-chunk output accumulation buffer (~8 GB).
    # tiny-long and full accumulate uint8 (3 B/px) — 4x longer chunks, which
    # also means 4x fewer per-chunk warmups/encodes; plain tiny still
    # accumulates float32 (12 B/px).
    _, _variant, _ = wgp.flashvsr.settings()
    bytes_per_out_frame = 3 * out_h * out_w * (1 if _variant in ("tiny-long", "full") else 4)
    chunk_frames = int(8e9 // max(1, bytes_per_out_frame))
    chunk_frames = max(49, min(chunk_frames, 1200))
    overlap = FLASHVSR_CONTINUE_CACHE_FRAMES
    n_chunks = max(1, math.ceil(max(1, int(total_frames)) / chunk_frames))

    # Free generation-model cache before loading FlashVSR.
    if torch.cuda.is_available():
        gc.collect()
        torch.cuda.empty_cache()

    def _progress(phase, current_step=None, total_steps=None):
        if callable(progress_callback):
            progress_callback(phase, current_step, total_steps)
            return
        if job is None:
            return
        changes = {}
        if phase:
            changes.update(message=str(phase), phase=str(phase))
        try:
            if total_steps:
                changes.update(
                    step=int(current_step or 0),
                    total_steps=int(total_steps),
                )
        except (TypeError, ValueError):
            pass
        if changes:
            update_job(job, **changes)

    output_fps = round(fps)
    container = wgp.server_config.get("video_container", "mp4")
    codec = wgp.server_config.get("video_output_codec", None)

    def _save_segment(frames, path):
        # tiny/tiny-long yield float32 in [-1,1]; the full variant yields
        # uint8 (decode_to_cpu_uint8) which save_video takes un-normalized.
        if frames.dtype == torch.uint8:
            wgp.save_video(tensor=frames[None], save_file=path, fps=output_fps, nrow=1, normalize=False, codec_type=codec, container=container)
        else:
            wgp.save_video(tensor=frames[None], save_file=path, fps=output_fps, nrow=1, normalize=True, value_range=(-1, 1), codec_type=codec, container=container)

    profile = wgp.loaded_profile if wgp.loaded_profile >= 0 else wgp.get_default_profile("video")

    # Keep the FlashVSR models resident across chunks; restore the user's
    # persistence choice (and release if they chose unload) afterwards.
    persistence_orig = wgp.server_config.get("flashvsr_persistence")
    wgp.server_config["flashvsr_persistence"] = wgp.flashvsr.PERSIST_RAM

    segment_paths = []
    concat_list = None
    tmp_video = None
    try:
        written = 0
        seg_idx = 0
        cache = None
        while True:
            if callable(abort_check) and abort_check():
                return None
            ov = overlap if written > 0 else 0
            seg = wgp.get_resampled_video(video_path, written - ov, ov + chunk_frames, fps)
            if seg is None or seg.shape[0] <= ov:
                break
            take_new = int(seg.shape[0]) - ov
            last = take_new < chunk_frames
            if n_chunks > 1:
                if job is not None:
                    if not update_job(
                        job,
                        message=f"Upscaling chunk {seg_idx + 1}/{n_chunks} (FlashVSR)...",
                    ):
                        return None
                print(f"  [Upscale] Chunk {seg_idx + 1}/{n_chunks}: frames {written}-{written + take_new - 1} (+{ov} overlap)")
            seg = seg.permute(-1, 0, 1, 2)  # [F,H,W,C] -> [C,F,H,W]
            out, cache = wgp.flashvsr.upscale(
                seg, method, seed=-1,
                continue_cache=cache, return_continue_cache=not last,
                vae_tile_size=None, process_files=wgp.process_files_def,
                vae_config=wgp.vae_config, init_pipe=wgp.init_pipe,
                profile=profile, still_image=False,
                abort_callback=abort_check, progress_callback=_progress,
            )
            seg = None
            if out is None:
                if callable(abort_check) and abort_check():
                    return None
                raise RuntimeError("FlashVSR returned no frames")
            if ov:
                # First `ov` output frames replicate the previous segment's
                # tail (continue_cache contract) — already encoded there.
                out = out[:, ov:]
            seg_path = video_path + f".upseg{seg_idx:03d}.{container}"
            _save_segment(out, seg_path)
            segment_paths.append(seg_path)
            out = None
            written += take_new
            seg_idx += 1
            if last:
                break
        if callable(abort_check) and abort_check():
            return None
        if not segment_paths:
            raise RuntimeError("No frames read from source video")

        if len(segment_paths) == 1:
            tmp_video = segment_paths[0]
            segment_paths = []
        else:
            if job is not None:
                if not update_job(job, message="Joining upscaled segments..."):
                    return None
            if callable(abort_check) and abort_check():
                return None
            concat_list = video_path + ".upconcat.txt"
            with open(concat_list, "w", encoding="utf-8") as f:
                for p in segment_paths:
                    f.write("file '" + os.path.abspath(p).replace("\\", "/").replace("'", "'\\''") + "'\n")
            tmp_video = video_path + f".upscale_tmp.{container}"
            result = subprocess.run(
                ["ffmpeg", "-y", "-f", "concat", "-safe", "0", "-i", concat_list, "-c", "copy", tmp_video],
                capture_output=True, text=True, timeout=600,
            )
            if result.returncode != 0 or not os.path.isfile(tmp_video):
                raise RuntimeError(f"ffmpeg concat failed: {result.stderr[-400:]}")

        if callable(abort_check) and abort_check():
            return None
        result_path = tmp_video
        tmp_video = None  # ownership transfers to the caller
        return result_path
    finally:
        wgp.server_config["flashvsr_persistence"] = persistence_orig if persistence_orig is not None else wgp.flashvsr.PERSIST_UNLOAD
        if persistence_orig != wgp.flashvsr.PERSIST_RAM:
            try:
                wgp.release_flashvsr_vram()
            except Exception:
                pass
        for leftover in segment_paths + [concat_list, tmp_video]:
            if leftover and os.path.isfile(leftover):
                try:
                    os.remove(leftover)
                except OSError:
                    pass


def _apply_spatial_upsampling_to_file(video_path: str, method: str, job: dict = None):
    """Upscale an already-saved video file IN PLACE (post-generation pass).

    Used to defer FlashVSR from the per-sliding-window inline path to a
    whole-file pass after generation: FlashVSR is a temporal model, and
    per-window application resets its state at every window boundary
    (visible detail/texture "pop" at the seams). Running on the assembled
    video avoids that — and stops FlashVSR from competing with the
    diffusion model for VRAM between windows.

    Thin wrapper over _chunked_flashvsr_upscale: re-muxes the original
    audio (e.g. LTX-2's generated track) onto the upscaled video and
    replaces the file (same name) so gallery entries and sidecar metadata
    keep pointing at the right clip — mirroring
    _apply_film_grain_to_file's in-place contract. Raises on failure; the
    caller treats it as a non-fatal warning and keeps the original.
    """
    audio_tracks, audio_metadata = wgp.extract_audio_tracks(video_path)
    tmp_video = None
    tmp_muxed = None
    try:
        abort_check = (
            (lambda: is_cancel_requested(job)) if job is not None else None
        )
        tmp_video = _chunked_flashvsr_upscale(
            video_path, method, job=job, abort_check=abort_check,
        )
        if tmp_video is None:
            raise RuntimeError("FlashVSR upscale was aborted")
        if callable(abort_check) and abort_check():
            raise RuntimeError("FlashVSR upscale was aborted")
        if audio_tracks:
            container = wgp.server_config.get("video_container", "mp4")
            tmp_muxed = video_path + f".upscale_mux.{container}"
            wgp.combine_video_with_audio_tracks(tmp_video, audio_tracks, tmp_muxed, audio_metadata=audio_metadata)
            if callable(abort_check) and abort_check():
                raise RuntimeError("FlashVSR upscale was aborted")
            os.replace(tmp_muxed, video_path)
            tmp_muxed = None  # consumed by the replace
        else:
            if callable(abort_check) and abort_check():
                raise RuntimeError("FlashVSR upscale was aborted")
            os.replace(tmp_video, video_path)
            tmp_video = None  # consumed by the replace
    finally:
        for leftover in (tmp_video, tmp_muxed):
            if leftover and os.path.isfile(leftover):
                try:
                    os.remove(leftover)
                except OSError:
                    pass
        wgp.cleanup_temp_audio_files(audio_tracks)


def _apply_delivery_fit_to_file(
    video_path: str,
    delivery_resolution: str,
    delivery_fit: str,
    *,
    job: dict | None = None,
) -> None:
    """Atomically enforce an exact, explicitly labeled delivery canvas."""
    import subprocess

    try:
        target_width, target_height = [
            int(value) for value in str(delivery_resolution).lower().split("x", 1)
        ]
    except (TypeError, ValueError) as exc:
        raise ValueError("Delivery resolution must be WIDTHxHEIGHT") from exc
    if (target_width, target_height) not in {(1920, 1080), (2688, 1536), (3840, 2160)}:
        raise ValueError("Unsupported H3 delivery resolution")
    if delivery_fit not in {"upscale_exact", "center_crop"}:
        raise ValueError("Unsupported H3 delivery fit")
    _, source_width, source_height, _ = wgp.get_video_info(video_path)
    source_width, source_height = int(source_width), int(source_height)
    if (source_width, source_height) == (target_width, target_height):
        return
    if delivery_fit == "upscale_exact":
        raise RuntimeError(
            f"Upscaler produced {source_width}x{source_height}; expected exact "
            f"{target_width}x{target_height} delivery"
        )
    if target_width > source_width or target_height > source_height:
        raise RuntimeError("Delivery fit cannot enlarge beyond the learned upscale canvas")
    target_aspect = target_width / target_height
    if source_width / source_height > target_aspect:
        crop_height = source_height - (source_height % 2)
        crop_width = min(source_width, int(crop_height * target_aspect))
        crop_width -= crop_width % 2
    else:
        crop_width = source_width - (source_width % 2)
        crop_height = min(source_height, int(crop_width / target_aspect))
        crop_height -= crop_height % 2
    crop_x = max(0, ((source_width - crop_width) // 2) // 2 * 2)
    crop_y = max(0, ((source_height - crop_height) // 2) // 2 * 2)
    container = os.path.splitext(video_path)[1].lower()
    if container not in {".mp4", ".mkv", ".webm"}:
        raise ValueError("Unsupported exact-delivery video container")
    temporary = video_path + ".delivery_fit.tmp" + container
    ffmpeg_bin = os.environ.get("FFMPEG_BINARY", "ffmpeg")
    command = [
        ffmpeg_bin, "-hide_banner", "-loglevel", "error", "-nostdin", "-y",
        "-i", video_path,
        "-vf", (
            f"crop={crop_width}:{crop_height}:{crop_x}:{crop_y},"
            f"scale={target_width}:{target_height}:flags=lanczos"
        ),
        "-map", "0:v:0", "-map", "0:a?",
    ]
    if container == ".webm":
        command.extend([
            "-c:v", "libvpx-vp9", "-deadline", "good", "-cpu-used", "2",
            "-crf", "17", "-b:v", "0", "-pix_fmt", "yuv420p",
            "-c:a", "copy",
        ])
    else:
        command.extend([
            "-c:v", "libx264", "-preset", "medium", "-crf", "17",
            "-pix_fmt", "yuv420p", "-c:a", "copy",
        ])
        if container == ".mp4":
            command.extend(["-movflags", "+faststart"])
    command.append(temporary)
    try:
        completed = subprocess.run(
            command, capture_output=True, text=True, timeout=3600,
        )
        if completed.returncode != 0 or not os.path.isfile(temporary):
            raise RuntimeError(
                "Exact delivery fit failed: " + (completed.stderr or "unknown ffmpeg error")[-500:]
            )
        if job is not None and is_cancel_requested(job):
            raise InterruptedError("Delivery fit cancelled")
        _, fitted_width, fitted_height, _ = wgp.get_video_info(temporary)
        if (int(fitted_width), int(fitted_height)) != (target_width, target_height):
            raise RuntimeError("Exact delivery fit produced an unexpected canvas")
        os.replace(temporary, video_path)
    finally:
        if os.path.isfile(temporary):
            try:
                os.remove(temporary)
            except OSError:
                pass


class _H3DeliveryFailure(RuntimeError):
    """Safe public delivery failure with optional path-free OOM facts."""

    def __init__(
        self,
        message: str,
        *,
        oom_info: dict | None = None,
        stage: str = "delivery",
        code: str = "delivery_failed",
        failure_details: dict | None = None,
    ):
        super().__init__(message)
        self.oom_info = oom_info
        self.stage = stage
        self.code = code
        self.failure_details = failure_details


def _release_h3_delivery_vram() -> list[str]:
    """Invalidate generation/upscaler residency and clear allocator caches."""
    actions = []
    try:
        wgp.release_flashvsr_vram()
        actions.append("released_flashvsr")
    except Exception:
        # Release helpers are best-effort, but H3 invalidation below is still
        # mandatory and must not be skipped because FlashVSR cleanup objected.
        actions.append("requested_flashvsr_release")
    try:
        # release_model invalidates WGP's loaded identity before fallible MMGP
        # cleanup, so even a cleanup exception cannot advertise stale H3
        # residency to the next load.
        wgp.release_model()
        actions.append("released_h3")
    except Exception:
        actions.append("invalidated_h3")
    gc.collect()
    if torch.cuda.is_available():
        torch.cuda.empty_cache()
        try:
            torch.cuda.ipc_collect()
        except Exception:
            pass
    actions.append("cleared_cuda_cache")
    return actions


def _atomic_write_json(path: str, value: dict) -> None:
    temporary = f"{path}.{uuid.uuid4().hex[:8]}.tmp"
    try:
        with open(temporary, "w", encoding="utf-8") as handle:
            json.dump(value, handle, indent=2)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, path)
        if os.name != "nt":
            directory = os.open(
                os.path.dirname(os.path.abspath(path)),
                os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
            )
            try:
                os.fsync(directory)
            finally:
                os.close(directory)
    finally:
        if os.path.isfile(temporary):
            try:
                os.remove(temporary)
            except OSError:
                pass


def _atomic_write_bytes(path: str, value: bytes) -> None:
    temporary = f"{path}.{uuid.uuid4().hex[:8]}.tmp"
    try:
        with open(temporary, "wb") as handle:
            handle.write(value)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, path)
        if os.name != "nt":
            directory = os.open(
                os.path.dirname(os.path.abspath(path)),
                os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
            )
            try:
                os.fsync(directory)
            finally:
                os.close(directory)
    finally:
        try:
            os.remove(temporary)
        except OSError:
            pass


def _stage_h3_delivery_native_outputs(
    job: dict,
    out_dir: str,
    file_names: list[str],
    delivery_plan: dict | None = None,
) -> list[dict]:
    """Move authoritative native finals into hidden owner-private staging."""
    token = uuid.uuid4().hex[:10]
    owner = str(job.get("session_id") or "")
    planned_by_original = {
        str(item.get("original_basename") or ""): item
        for item in (
            delivery_plan.get("staging") or []
            if isinstance(delivery_plan, dict) else []
        )
        if isinstance(item, dict)
    }
    staged = []
    try:
        for file_name in file_names:
            if os.path.basename(file_name) != file_name or file_name.startswith("."):
                raise RuntimeError("Unsafe H3 delivery output name")
            stem, extension = os.path.splitext(file_name)
            source_path = os.path.join(out_dir, file_name)
            source_meta = os.path.join(out_dir, stem + ".meta.json")
            planned = planned_by_original.get(file_name)
            private_name = str((planned or {}).get("native_basename") or (
                f".maestro-delivery-{job.get('id', 'job')}-{token}-{stem}.native"
                f"{extension}"
            ))
            native_path = os.path.join(out_dir, private_name)
            native_meta = os.path.join(
                out_dir,
                str((planned or {}).get("native_sidecar_basename") or (
                    os.path.splitext(private_name)[0] + ".meta.json"
                )),
            )
            work_basename = str((planned or {}).get("work_basename") or (
                f".maestro-delivery-{job.get('id', 'job')}-{token}-{stem}.work"
                f"{extension}"
            ))
            work_path = os.path.join(out_dir, work_basename)
            rollback_meta = os.path.splitext(work_path)[0] + ".rollback.meta.json"
            durable_owner = owner
            if os.path.isfile(native_meta):
                with open(native_meta, "rb") as handle:
                    current_native_meta = handle.read()
                try:
                    current_sidecar = json.loads(current_native_meta.decode("utf-8"))
                    current_recovery = current_sidecar.get("delivery_recovery")
                    if current_recovery is None:
                        # Crash after source_meta -> native_meta but before
                        # enrichment: the hidden sidecar is still the exact
                        # original policy and can be completed in place.
                        original_meta_bytes = current_native_meta
                    elif isinstance(current_recovery, dict):
                        encoded_original = current_recovery.get(
                            "original_sidecar_b64"
                        )
                        if not isinstance(encoded_original, str) or not encoded_original:
                            raise ValueError("missing original sidecar")
                        durable_owner = str(
                            current_recovery.get("owner_session_id") or owner
                        )
                        original_meta_bytes = base64.b64decode(
                            encoded_original, validate=True,
                        )
                    else:
                        raise ValueError("invalid delivery recovery metadata")
                    original_sidecar = json.loads(
                        original_meta_bytes.decode("utf-8")
                    )
                    if not isinstance(original_sidecar, dict):
                        raise ValueError("invalid original sidecar")
                except (ValueError, TypeError, json.JSONDecodeError):
                    raise RuntimeError("Protected H3 native metadata is incomplete")
            elif os.path.isfile(source_meta):
                with open(source_meta, "rb") as handle:
                    original_meta_bytes = handle.read()
            else:
                raise RuntimeError("Authoritative H3 native sidecar is incomplete")

            if isinstance(delivery_plan, dict):
                planned_source = (
                    planned.get("source") if isinstance(planned, dict) else None
                )
                if not isinstance(planned_source, dict):
                    raise RuntimeError("Durable H3 delivery source evidence is missing")
                expected_sidecar = os.path.splitext(file_name)[0] + ".meta.json"
                expected_unit = str(planned_source.get("producer_unit_id") or "")
                if (
                    planned_source.get("basename") != file_name
                    or planned_source.get("sidecar_basename") != expected_sidecar
                    or not expected_unit
                ):
                    raise RuntimeError("Durable H3 delivery source identity changed")
                media_candidates = [
                    path for path in (source_path, native_path)
                    if os.path.isfile(path) and not os.path.islink(path)
                ]
                sidecar_candidates = [
                    path for path in (source_meta, native_meta)
                    if os.path.isfile(path) and not os.path.islink(path)
                ]
                if len(media_candidates) != 1 or len(sidecar_candidates) != 1:
                    raise RuntimeError("Authoritative H3 native rename state is ambiguous")
                media_size, media_sha256 = _recovery_sha256_file(
                    media_candidates[0]
                )
                original_sidecar_sha256 = hashlib.sha256(
                    original_meta_bytes
                ).hexdigest()
                try:
                    original_sidecar = json.loads(
                        original_meta_bytes.decode("utf-8")
                    )
                except (UnicodeDecodeError, ValueError, TypeError):
                    raise RuntimeError(
                        "Authoritative H3 native sidecar is invalid"
                    ) from None
                if (
                    media_size != planned_source.get("size")
                    or media_sha256 != planned_source.get("sha256")
                    or len(original_meta_bytes) != planned_source.get("sidecar_size")
                    or original_sidecar_sha256
                    != planned_source.get("sidecar_sha256")
                    or not isinstance(original_sidecar, dict)
                    or original_sidecar.get("producer_unit_id") != expected_unit
                ):
                    raise RuntimeError(
                        "Authoritative H3 native source no longer matches intent"
                    )

            # The durable staging intent is committed before this function is
            # entered. Finish either half of a crash-interrupted rename pair.
            if not os.path.isfile(native_path):
                if not os.path.isfile(source_path):
                    raise RuntimeError("Authoritative H3 native output is incomplete")
                os.replace(source_path, native_path)
            if not os.path.isfile(native_meta):
                os.replace(source_meta, native_meta)
            item = {
                "file_name": file_name,
                "source_path": source_path,
                "source_meta": source_meta,
                "native_path": native_path,
                "native_meta": native_meta,
                "work_path": work_path,
                "rollback_meta": rollback_meta,
                "original_meta_bytes": original_meta_bytes,
                "work_basename": work_basename,
            }
            # Register ownership immediately after the two renames so any
            # later metadata read/write fault can restore this current item as
            # well as previously staged finals.
            staged.append(item)
            private_sidecar = json.loads(original_meta_bytes.decode("utf-8"))
            private_policy = {
                "private": True,
                "explicit": bool(private_sidecar.get("explicit", False)),
                "owner_session_id": owner or None,
            }
            original_job_id = str(private_sidecar.get("job_id") or job.get("id") or "")
            original_producer_class = str(
                private_sidecar.get("producer_artifact_class") or "final"
            )
            stamp_sidecar_policy(
                private_sidecar,
                private_policy,
                workspace=str(job.get("workspace") or "default"),
            )
            durable_recovery = {
                "schema_version": 1,
                "source_job_id": str(job.get("id") or ""),
                "original_filename": file_name,
                "requested_target": str(
                    (job.get("params") or {}).get("delivery_resolution") or ""
                ),
                "delivery_fit": str(
                    (job.get("params") or {}).get("delivery_fit") or ""
                ),
                "spatial_upsampling": str(
                    (job.get("params") or {}).get("spatial_upsampling") or ""
                ),
                "producer_job_id": original_job_id,
                "producer_artifact_class": original_producer_class,
                "artifact_lineage": private_sidecar.get("artifact_lineage"),
                "source_remote": bool(job.get("source_remote", False)),
                "owner_session_id": durable_owner,
                "original_sidecar_b64": base64.b64encode(
                    original_meta_bytes
                ).decode("ascii"),
                "final_private": bool((job.get("access_policy") or {}).get("private")),
                "final_explicit": bool((job.get("access_policy") or {}).get("explicit")),
                "manual_retry_count": 0,
                "manual_retry_limit": 2,
                "restart_supported": True,
            }
            if isinstance(delivery_plan, dict):
                durable_recovery.update({
                    "queue_recovery_unit_id": str(
                        delivery_plan.get("unit_id") or ""
                    ),
                    "queue_recovery_dependencies": list(
                        delivery_plan.get("dependencies") or []
                    ),
                    "queue_recovery_settings": dict(
                        delivery_plan.get("settings") or {}
                    ),
                })
            private_sidecar.update({
                "output_filename": private_name,
                "producer_artifact_class": "temporary",
                "artifact_class": "temporary",
                "delivery_native_source": True,
                "delivery_recovery": durable_recovery,
            })
            _atomic_write_json(native_meta, private_sidecar)
    except Exception:
        for item in reversed(staged):
            # Restore policy before media so the public basename is never
            # present without an authorization sidecar.
            restored_policy = False
            try:
                _atomic_write_bytes(
                    item["source_meta"], item["original_meta_bytes"],
                )
                restored_policy = True
            finally:
                if restored_policy:
                    try:
                        os.remove(item["native_meta"])
                    except OSError:
                        pass
                    if os.path.isfile(item["native_path"]):
                        os.replace(item["native_path"], item["source_path"])
        raise
    job["_h3_delivery_native"] = staged
    return staged


def _reset_h3_delivery_work(staged: list[dict]) -> None:
    import shutil

    for item in staged:
        try:
            os.remove(item["work_path"])
        except FileNotFoundError:
            pass
        shutil.copy2(item["native_path"], item["work_path"])


def _h3_delivery_native_available(staged: list[dict]) -> bool:
    return bool(staged) and all(
        os.path.isfile(item["native_path"])
        and os.path.isfile(item["native_meta"])
        for item in staged
    )


def _publish_h3_delivery_outputs(
    job: dict,
    staged: list[dict],
    *,
    recovery_action: str = "",
    requested_target: str = "",
) -> list[str]:
    """Commit sidecars-before-media and roll back every partial publication."""
    import shutil

    final_names = [item["file_name"] for item in staged]
    published_items = []
    final_policy = dict(job.get("access_policy") or {})
    owner = str(job.get("session_id") or "")

    def _publication_sidecar(item, *, final: bool) -> dict:
        with open(item["native_meta"], "r", encoding="utf-8") as handle:
            sidecar = json.load(handle)
        policy = final_policy if final else {
            "private": True,
            "explicit": bool(sidecar.get("explicit", False)),
            "owner_session_id": owner or None,
        }
        stamp_sidecar_policy(
            sidecar,
            policy,
            workspace=str(job.get("workspace") or "default"),
        )
        sidecar.update({
            "job_id": str(job.get("id") or sidecar.get("job_id") or ""),
            "output_filename": item["file_name"],
            "producer_artifact_class": "final" if final else "temporary",
            "artifact_class": "final" if final else "temporary",
        })
        if final:
            sidecar.pop("delivery_native_source", None)
            durable = (
                sidecar.get("delivery_recovery")
                if isinstance(sidecar.get("delivery_recovery"), dict) else {}
            )
            producer_job_id = str(
                durable.get("producer_job_id") or sidecar.get("job_id") or ""
            )
            producer_class = str(
                durable.get("producer_artifact_class")
                or sidecar.get("producer_artifact_class") or "final"
            )
            if recovery_action:
                # Recovery is a postprocess child, not a new producer. Keep
                # the native producer's top-level identity/lineage so search,
                # cleanup, and multi-output grouping retain normal parity.
                sidecar["job_id"] = producer_job_id
                sidecar["producer_job_id"] = producer_job_id
                sidecar["recovery_job_id"] = str(job.get("id") or "")
                original_lineage = durable.get("artifact_lineage")
                if isinstance(original_lineage, str) and original_lineage.strip():
                    sidecar["artifact_lineage"] = original_lineage
                recovery_record = {
                    "action": recovery_action,
                    "source_job_id": str(
                        job.get("_h3_delivery_recovery_source_job")
                        or job.get("id")
                        or ""
                    ),
                    "requested_target": str(requested_target or ""),
                    "completed_at": time.time(),
                    "producer_job_id": producer_job_id,
                    "producer_artifact_class": producer_class,
                    "recovery_job_id": str(job.get("id") or ""),
                }
                if recovery_action == "accept_native":
                    params = (
                        dict(sidecar.get("params") or {})
                        if isinstance(sidecar.get("params"), dict)
                        else {}
                    )
                    params["requested_delivery_resolution"] = str(
                        requested_target or params.get("delivery_resolution") or ""
                    )
                    params["delivery_resolution"] = ""
                    params["delivery_fit"] = ""
                    params["spatial_upsampling"] = ""
                    params["delivery_recovery"] = "accepted_native"
                    sidecar["params"] = params
                    try:
                        _, width, height, _ = wgp.get_video_info(item["native_path"])
                        recovery_record["actual_resolution"] = (
                            f"{int(width)}x{int(height)}"
                        )
                    except Exception:
                        recovery_record["actual_resolution"] = "native"
                sidecar["delivery_recovery"] = recovery_record
        else:
            sidecar["delivery_native_source"] = True
        return sidecar

    try:
        # A basename may appear only behind an owner-private temporary
        # sidecar. Final access policy is promoted after every media file has
        # landed and cancellation has been checked again.
        for item in staged:
            _atomic_write_json(
                item["source_meta"],
                _publication_sidecar(item, final=False),
            )
            shutil.copy2(item["source_meta"], item["rollback_meta"])
        if is_cancel_requested(job):
            raise InterruptedError("H3 delivery cancelled")
        for item in staged:
            if is_cancel_requested(job):
                raise InterruptedError("H3 delivery cancelled")
            os.replace(item["work_path"], item["source_path"])
            published_items.append(item)
        if is_cancel_requested(job):
            raise InterruptedError("H3 delivery cancelled")
        # This lifecycle update and request_cancel share one lock. If
        # cancellation won at the commit boundary, remove every prepared final
        # below and retain the hidden native sources.
        if not update_job(job, output_files=final_names):
            raise InterruptedError("H3 delivery cancelled")
        if is_cancel_requested(job):
            # update_job and request_cancel serialize, but the job remains
            # running until all postpasses finish. Retract this just-committed
            # view when cancellation lands in that narrow interval.
            job["output_files"] = []
            raise InterruptedError("H3 delivery cancelled")
        for item in staged:
            if is_cancel_requested(job):
                raise InterruptedError("H3 delivery cancelled")
            _atomic_write_json(
                item["source_meta"],
                _publication_sidecar(item, final=True),
            )
        if is_cancel_requested(job):
            raise InterruptedError("H3 delivery cancelled")
    except Exception:
        # The lifecycle record may have succeeded before a later sidecar or
        # cancellation fault. Retract the public job view before filesystem
        # rollback; artifact lineage remains available for local diagnostics.
        job["output_files"] = []
        # Prefer a recoverable hidden rename over deletion. If a viewer has the
        # file locked and even the rename fails, keep the basename behind an
        # owner-private temporary sidecar; never leave fail-open media.
        for item in published_items:
            try:
                os.replace(item["source_path"], item["work_path"])
            except OSError:
                pass
        for item in staged:
            try:
                os.replace(item["rollback_meta"], item["source_meta"])
            except OSError as rollback_error:
                # A second filesystem fault must never be suppressed merely
                # because some sidecar exists. Prove that any retained policy
                # is still the owner-private temporary policy; otherwise make
                # the security failure explicit for the safe outer wrapper.
                try:
                    with open(item["source_meta"], "r", encoding="utf-8") as handle:
                        retained = json.load(handle)
                    retained_is_private = (
                        retained.get("private") is True
                        and retained.get("artifact_class") == "temporary"
                        and str(retained.get("workspace") or "")
                            == str(job.get("workspace") or "default")
                    )
                except Exception:
                    retained_is_private = False
                if not retained_is_private:
                    raise RuntimeError(
                        "Unable to retain private H3 delivery rollback policy",
                    ) from rollback_error
        raise

    # Native bytes and byte-exact temporary sidecars stay protected until the
    # lifecycle transitions terminal-completed.  A cancel racing immediately
    # after publication can therefore retract every public basename.
    job["_h3_delivery_publication"] = {
        "staged": staged,
        "final_names": final_names,
    }
    return final_names


def _rollback_h3_delivery_publication(job: dict) -> None:
    publication = job.pop("_h3_delivery_publication", None)
    if not isinstance(publication, dict):
        return
    job["output_files"] = []
    for item in publication.get("staged") or []:
        if os.path.isfile(item["source_path"]):
            try:
                os.replace(item["source_path"], item["work_path"])
            except OSError:
                # Fail closed: retain a private temporary policy at a locked
                # public basename.  The rollback bytes below are byte-exact.
                pass
        if os.path.isfile(item["rollback_meta"]):
            os.replace(item["rollback_meta"], item["source_meta"])


def _finalize_h3_delivery_publication(job: dict) -> bool:
    publication = job.pop("_h3_delivery_publication", None)
    if not isinstance(publication, dict):
        return True
    cleanup_pending = []
    for item in publication.get("staged") or []:
        for path in (item["rollback_meta"], item["work_path"]):
            try:
                os.remove(path)
            except OSError:
                pass
        media_removed = not os.path.exists(item["native_path"])
        if not media_removed:
            try:
                os.remove(item["native_path"])
                media_removed = True
            except OSError:
                cleanup_pending.append(item)
                try:
                    with open(item["native_meta"], "r", encoding="utf-8") as handle:
                        meta = json.load(handle)
                    descriptor = meta.get("delivery_recovery")
                    if isinstance(descriptor, dict):
                        descriptor["cleanup_pending"] = True
                        descriptor["consumed"] = True
                        descriptor["completed_job_id"] = str(job.get("id") or "")
                        _atomic_write_json(item["native_meta"], meta)
                except (OSError, ValueError, TypeError):
                    traceback.print_exc()
        # Never remove the ownership sidecar while its native media remains.
        if media_removed:
            try:
                os.remove(item["native_meta"])
            except OSError:
                pass
    if cleanup_pending:
        job["_h3_delivery_native"] = cleanup_pending
        job["_h3_delivery_cleanup_pending"] = True
        return False
    job.pop("_h3_delivery_native", None)
    job.pop("_h3_delivery_cleanup_pending", None)
    return True


def _process_h3_delivery_from_protected_native(
    job: dict,
    out_dir: str,
    staged: list[dict],
    *,
    spatial_upsampling: str,
    delivery_resolution: str,
    delivery_fit: str,
) -> list[str]:
    """Run no operation except delivery from hash-verified native bytes."""
    for item in staged:
        if is_cancel_requested(job):
            raise InterruptedError("H3 delivery cancelled")

        def deliver_native(source_path, staging_path):
            import shutil
            shutil.copy2(source_path, staging_path)
            try:
                _apply_spatial_upsampling_to_file(
                    staging_path, spatial_upsampling, job=job,
                )
            except InterruptedError:
                raise
            except Exception as error:
                raise _H3DeliveryFailure(
                    "H3 delivery upscaling failed",
                    stage="flashvsr",
                    code="flashvsr_failed",
                ) from error
            if not update_job(
                job,
                message=f"Fitting exact {delivery_resolution} delivery...",
                phase="Delivery fit",
            ):
                raise InterruptedError("H3 delivery cancelled")
            try:
                _apply_delivery_fit_to_file(
                    staging_path, delivery_resolution, delivery_fit, job=job,
                )
            except InterruptedError:
                raise
            except Exception as error:
                raise _H3DeliveryFailure(
                    "H3 delivery fit failed",
                    stage="delivery",
                    code="delivery_fit_failed",
                ) from error
            return True

        replay_delivery_from_protected_native(
            out_dir,
            protected_descriptor=item["recovery_descriptor"],
            work_basename=item["work_basename"],
            deliver=deliver_native,
        )
    try:
        return _publish_h3_delivery_outputs(job, staged)
    except InterruptedError:
        raise
    except Exception as error:
        raise _H3DeliveryFailure(
            "H3 delivery publication failed",
            stage="publication",
            code="publication_failed",
        ) from error


def _deliver_h3_outputs_transactionally(
    job: dict,
    out_dir: str,
    file_names: list[str],
    spatial_upsampling: str,
    delivery_resolution: str,
    delivery_fit: str,
) -> list[str]:
    """Deliver all H3 finals from protected native bytes with one OOM retry."""
    from services.oom_detect import delivery_oom_info, is_oom

    if delivery_resolution not in {"1920x1080", "2688x1536", "3840x2160"}:
        raise _H3DeliveryFailure("H3 delivery target is invalid")
    if delivery_fit not in {"upscale_exact", "center_crop"}:
        raise _H3DeliveryFailure("H3 delivery fit is invalid")
    try:
        plan_builder = globals().get("_queue_recovery_delivery_plan")
        intent_checkpoint = globals().get(
            "_queue_recovery_checkpoint_delivery_intent"
        )
        pending_checkpoint = globals().get(
            "_queue_recovery_checkpoint_delivery_pending"
        )
        if (
            callable(plan_builder)
            and callable(intent_checkpoint)
            and callable(pending_checkpoint)
        ):
            delivery_plan = plan_builder(
                job,
                out_dir,
                file_names,
                spatial_upsampling=spatial_upsampling,
                delivery_resolution=delivery_resolution,
                delivery_fit=delivery_fit,
            )
            intent_checkpoint(job, delivery_plan)
            staged = _stage_h3_delivery_native_outputs(
                job, out_dir, file_names, delivery_plan,
            )
            pending_checkpoint(job, out_dir, staged, delivery_plan)
        else:
            # Compatibility for isolated legacy transaction harnesses. The
            # real launch module always has the durable functions above.
            staged = _stage_h3_delivery_native_outputs(
                job, out_dir, file_names,
            )
    except Exception as error:
        raise _H3DeliveryFailure(
            "Unable to protect native H3 outputs for delivery",
            stage="publication",
            code="delivery_native_protection_failed",
        ) from error
    job["_h3_delivery_recovery"] = {
        "nonce": uuid.uuid4().hex,
        "staged": staged,
        "spatial_upsampling": spatial_upsampling,
        "delivery_resolution": delivery_resolution,
        "delivery_fit": delivery_fit,
        "manual_retry_count": 0,
        "manual_retry_limit": 2,
        "active_job_id": "",
        "consumed": False,
        "restart_supported": True,
        "unsupported_after_restart_reason": "",
    }
    update_job(job, output_files=[])
    actions = _release_h3_delivery_vram()
    retry_count = 0
    for attempt in range(2):
        active_stage = "delivery"
        active_code = "delivery_failed"
        try:
            if is_cancel_requested(job):
                raise InterruptedError("H3 delivery cancelled")
            protected_delivery = globals().get(
                "_process_h3_delivery_from_protected_native"
            )
            if callable(protected_delivery) and all(
                isinstance(item.get("recovery_descriptor"), dict)
                for item in staged
            ):
                return protected_delivery(
                    job,
                    out_dir,
                    staged,
                    spatial_upsampling=spatial_upsampling,
                    delivery_resolution=delivery_resolution,
                    delivery_fit=delivery_fit,
                )
            _reset_h3_delivery_work(staged)
            for item in staged:
                if is_cancel_requested(job):
                    raise InterruptedError("H3 delivery cancelled")
                active_stage = "flashvsr"
                active_code = "flashvsr_failed"
                _apply_spatial_upsampling_to_file(
                    item["work_path"], spatial_upsampling, job=job,
                )
                if not update_job(
                    job,
                    message=f"Fitting exact {delivery_resolution} delivery...",
                    phase="Delivery fit",
                ):
                    raise InterruptedError("H3 delivery cancelled")
                active_stage = "delivery"
                active_code = "delivery_fit_failed"
                _apply_delivery_fit_to_file(
                    item["work_path"], delivery_resolution, delivery_fit, job=job,
                )
            active_stage = "publication"
            active_code = "publication_failed"
            return _publish_h3_delivery_outputs(job, staged)
        except InterruptedError:
            for item in staged:
                try:
                    os.remove(item["work_path"])
                except OSError:
                    pass
            raise
        except Exception as error:
            active_stage = str(getattr(error, "stage", active_stage))
            active_code = str(getattr(error, "code", active_code))
            for item in staged:
                try:
                    os.remove(item["work_path"])
                except OSError:
                    pass
            if is_cancel_requested(job):
                raise InterruptedError("H3 delivery cancelled") from error
            if is_oom(error) and attempt == 0:
                retry_count = 1
                actions.extend(_release_h3_delivery_vram())
                actions.append("retried_identical_delivery")
                continue
            native_available = _h3_delivery_native_available(staged)
            oom_info = delivery_oom_info(
                error,
                float(wgp.server_config.get("vram_safety_coefficient", 0.80)),
                requested_target=delivery_resolution,
                native_available=native_available,
                retry_count=retry_count,
                actions=actions,
            )
            message = (
                f"Exact {delivery_resolution} delivery ran out of GPU memory; "
                "the private native result was retained"
                if oom_info else f"Exact {delivery_resolution} delivery failed"
            )
            safe_failure_updates = globals().get("_safe_failure_updates")
            if callable(safe_failure_updates):
                failure_details = safe_failure_updates(
                    error, job, stage=active_stage, code=active_code,
                )["failure_details"]
            else:
                # Isolated transaction harnesses intentionally load only the
                # delivery symbols. Preserve the same safe envelope without
                # coupling those harnesses to the whole generation worker.
                from services.oom_detect import build_failure_details
                failure_details = build_failure_details(
                    error, stage=active_stage, code=active_code,
                )
            persist_failure = globals().get(
                "_persist_h3_delivery_failure_details"
            )
            if callable(persist_failure):
                persist_failure(job, failure_details, oom_info)
            elif oom_info is not None:
                # Compatibility for isolated legacy transaction harnesses.
                persist_oom = globals().get("_persist_h3_delivery_oom_info")
                if callable(persist_oom):
                    persist_oom(job, oom_info)
            raise _H3DeliveryFailure(
                message,
                oom_info=oom_info,
                stage=active_stage,
                code=active_code,
                failure_details=failure_details,
            ) from error
    raise AssertionError("unreachable H3 delivery retry state")


def _resume_pending_h3_delivery_only(job: dict) -> bool:
    """Resume a crash-interrupted delivery without reaching concat/denoise."""
    pending = _queue_recovery_delivery_pending(job)
    if pending is None:
        return False
    out_dir = os.path.realpath(str(job.get("out_dir") or ""))
    settings = dict(pending.get("settings") or {})
    dependencies = list(pending.get("dependencies") or [])
    expected = recovery_unit_id(
        str(job.get("id") or ""),
        "h3_delivery",
        dependencies=dependencies,
        settings=settings,
    )
    if not hmac.compare_digest(expected, str(pending.get("unit_id") or "")):
        raise QueueRecoveryRuntimeError("Protected delivery identity changed.")
    if pending.get("state") == "staging_native":
        plan = {
            "dependencies": dependencies,
            "settings": settings,
            "staging": [dict(item) for item in pending.get("staging") or []],
            "unit_id": expected,
        }
        file_names = [
            str(item.get("original_basename") or "")
            for item in plan["staging"]
            if isinstance(item, dict)
        ]
        staged = _stage_h3_delivery_native_outputs(
            job, out_dir, file_names, plan,
        )
        pending = _queue_recovery_checkpoint_delivery_pending(
            job, out_dir, staged, plan,
        )
    else:
        staged = _queue_recovery_restore_delivery_staged(job, out_dir, pending)
    completed_unit = _queue_recovery_unit_matches(
        job,
        kind="h3_delivery",
        variant=0,
        index=0,
        project_dir=out_dir,
    )
    if (
        completed_unit is not None
        and hmac.compare_digest(
            str(completed_unit.get("unit_id") or ""),
            str(pending.get("unit_id") or ""),
        )
    ):
        delivered = [
            str(artifact.get("basename") or "")
            for artifact in completed_unit.get("artifacts") or []
            if isinstance(artifact, dict)
        ]
        job["_h3_delivery_publication"] = {
            "staged": staged,
            "final_names": delivered,
        }
        completed = finish_job(
            job,
            "completed",
            output_files=delivered,
            progress=100,
            phase="",
            message="Done",
            error=None,
        )
        if completed and not is_cancel_requested(job):
            _finalize_h3_delivery_publication(job)
            cursor = dict(job.get("recovery_cursor") or {})
            cursor.pop("delivery_pending", None)
            _queue_recovery_checkpoint(
                job,
                recovery_cursor=cursor,
                recovery_state="terminal",
                reruns_denoise=False,
            )
            return True
        _rollback_h3_delivery_publication(job)
        return False
    job["_h3_delivery_recovery"] = {
        "nonce": uuid.uuid4().hex,
        "staged": staged,
        "spatial_upsampling": str(settings.get("spatial_upsampling") or ""),
        "delivery_resolution": str(settings.get("delivery_resolution") or ""),
        "delivery_fit": str(settings.get("delivery_fit") or ""),
        "manual_retry_count": 0,
        "manual_retry_limit": 2,
        "active_job_id": "",
        "consumed": False,
        "restart_supported": True,
        "unsupported_after_restart_reason": "",
    }
    try:
        update_job(
            job,
            output_files=[],
            phase="Delivery recovery",
            message="Resuming delivery from protected native output...",
        )
        _release_h3_delivery_vram()
        delivered = _process_h3_delivery_from_protected_native(
            job,
            out_dir,
            staged,
            spatial_upsampling=str(settings.get("spatial_upsampling") or ""),
            delivery_resolution=str(settings.get("delivery_resolution") or ""),
            delivery_fit=str(settings.get("delivery_fit") or ""),
        )
        _queue_recovery_checkpoint_delivery_completed(
            job, out_dir, delivered, pending,
        )
        completed = finish_job(
            job,
            "completed",
            output_files=delivered,
            progress=100,
            phase="",
            message="Done",
            error=None,
        )
        if completed and not is_cancel_requested(job):
            _finalize_h3_delivery_publication(job)
            cursor = dict(job.get("recovery_cursor") or {})
            cursor.pop("delivery_pending", None)
            _queue_recovery_checkpoint(
                job,
                recovery_cursor=cursor,
                recovery_state="terminal",
                reruns_denoise=False,
            )
            return True
        _rollback_h3_delivery_publication(job)
        return False
    except InterruptedError:
        _rollback_h3_delivery_publication(job)
        return False
    except Exception:
        _rollback_h3_delivery_publication(job)
        if try_requeue(
            job,
            queue_held=True,
            recovery_state="blocked",
            reruns_denoise=False,
            message="Delivery recovery is blocked for manual retry",
        ):
            return False
        raise


_h3_delivery_recovery_lock = threading.RLock()


def _persist_h3_delivery_oom_info(job: dict, oom_info: dict) -> bool:
    recovery = job.get("_h3_delivery_recovery") or {}
    originals = {}
    try:
        for item in recovery.get("staged") or []:
            with open(item["native_meta"], "rb") as handle:
                originals[item["native_meta"]] = handle.read()
        for item in recovery.get("staged") or []:
            meta = json.loads(originals[item["native_meta"]].decode("utf-8"))
            descriptor = meta.get("delivery_recovery")
            if not isinstance(descriptor, dict):
                raise ValueError("Missing delivery recovery descriptor")
            descriptor["oom_info"] = dict(oom_info)
            _atomic_write_json(item["native_meta"], meta)
        return True
    except (OSError, ValueError, TypeError):
        traceback.print_exc()
        for path, contents in originals.items():
            try:
                _atomic_write_bytes(path, contents)
            except OSError:
                traceback.print_exc()
        return False


def _persist_h3_delivery_failure_details(
    job: dict,
    failure_details: dict,
    oom_info: dict | None = None,
) -> bool:
    """Persist the safe failure stage for restart without inventing OOM."""
    from services.oom_detect import normalize_failure_details

    safe_details = normalize_failure_details(failure_details)
    recovery = job.get("_h3_delivery_recovery") or {}
    originals = {}
    try:
        for item in recovery.get("staged") or []:
            with open(item["native_meta"], "rb") as handle:
                originals[item["native_meta"]] = handle.read()
        for item in recovery.get("staged") or []:
            meta = json.loads(originals[item["native_meta"]].decode("utf-8"))
            descriptor = meta.get("delivery_recovery")
            if not isinstance(descriptor, dict):
                raise ValueError("Missing delivery recovery descriptor")
            descriptor["failure_details"] = dict(safe_details)
            if isinstance(oom_info, dict) and oom_info.get("is_oom") is True:
                descriptor["oom_info"] = dict(oom_info)
            else:
                descriptor.pop("oom_info", None)
            _atomic_write_json(item["native_meta"], meta)
        return True
    except (OSError, ValueError, TypeError):
        traceback.print_exc()
        for path, contents in originals.items():
            try:
                _atomic_write_bytes(path, contents)
            except OSError:
                traceback.print_exc()
        return False


def _persist_h3_delivery_recovery_state(job: dict) -> bool:
    recovery = job.get("_h3_delivery_recovery") or {}
    originals = {}
    try:
        for item in recovery.get("staged") or []:
            with open(item["native_meta"], "rb") as handle:
                originals[item["native_meta"]] = handle.read()
        for item in recovery.get("staged") or []:
            meta = json.loads(originals[item["native_meta"]].decode("utf-8"))
            descriptor = meta.get("delivery_recovery")
            if not isinstance(descriptor, dict):
                raise ValueError("Missing delivery recovery descriptor")
            descriptor["manual_retry_count"] = int(
                recovery.get("manual_retry_count") or 0
            )
            descriptor["manual_retry_limit"] = int(
                recovery.get("manual_retry_limit") or 2
            )
            descriptor["restart_supported"] = True
            _atomic_write_json(item["native_meta"], meta)
        return True
    except (OSError, ValueError, TypeError):
        traceback.print_exc()
        # A multi-output budget update is itself transactional.  Restore each
        # native sidecar byte-for-byte so restart cannot charge only a subset.
        for path, contents in originals.items():
            try:
                _atomic_write_bytes(path, contents)
            except OSError:
                traceback.print_exc()
        return False


def _reindex_h3_delivery_recoveries() -> int:
    """Rebuild owner-private retained-native jobs after a clean restart."""
    base = os.path.realpath(wgp.server_config.get("save_path", "outputs"))
    if not os.path.isdir(base):
        return 0
    directories = [("default", base)]
    with os.scandir(base) as entries:
        for entry in entries:
            safe_name = bool(entry.name) and entry.name[0].isalnum() and all(
                char.isalnum() or char in {"_", "-"} for char in entry.name
            )
            if entry.is_dir(follow_symlinks=False) and safe_name:
                directories.append((entry.name, os.path.realpath(entry.path)))
    groups = {}
    for workspace, out_dir in directories:
        if os.path.commonpath((base, out_dir)) != base:
            continue
        with os.scandir(out_dir) as entries:
            metas = [entry.path for entry in entries if entry.is_file(follow_symlinks=False)
                     and entry.name.startswith(".maestro-delivery-")
                     and entry.name.endswith(".native.meta.json")]
        for meta_path in metas:
            try:
                with open(meta_path, "r", encoding="utf-8") as handle:
                    meta = json.load(handle)
                descriptor = meta.get("delivery_recovery")
                source_id = str((descriptor or {}).get("source_job_id") or "")
                owner = str(
                    (descriptor or {}).get("owner_session_id")
                    or meta.get("owner_session_id") or ""
                )
                filename = str((descriptor or {}).get("original_filename") or "")
                native_path = meta_path[:-len(".meta.json")] + os.path.splitext(filename)[1]
                if not (meta.get("private") is True
                        and meta.get("delivery_native_source") is True
                        and isinstance(descriptor, dict)
                        and descriptor.get("schema_version") == 1
                        and str(descriptor.get("requested_target") or "")
                            in {"1920x1080", "2688x1536", "3840x2160"}
                        and str(descriptor.get("delivery_fit") or "")
                            in {"upscale_exact", "center_crop"}
                        and 1 <= len(source_id) <= 64
                        and source_id.replace("-", "").replace("_", "").isalnum()
                        and owner and os.path.basename(filename) == filename
                        and not filename.startswith(".")
                        and os.path.isfile(native_path)
                        and not os.path.islink(native_path)
                        and str(meta.get("workspace") or "default") == workspace):
                    continue
                stem, extension = os.path.splitext(filename)
                token = uuid.uuid4().hex[:10]
                item = {
                    "file_name": filename,
                    "source_path": os.path.join(out_dir, filename),
                    "source_meta": os.path.join(out_dir, stem + ".meta.json"),
                    "native_path": native_path,
                    "native_meta": meta_path,
                    "work_path": os.path.join(out_dir, f".maestro-delivery-{source_id}-{token}-{stem}.work{extension}"),
                    "rollback_meta": os.path.join(out_dir, f".maestro-delivery-{source_id}-{token}-{stem}.work.rollback.meta.json"),
                }
                groups.setdefault((workspace, source_id, owner), []).append((item, descriptor, meta))
            except (OSError, ValueError, TypeError):
                continue
    restored = 0
    for (workspace, source_id, owner), records in groups.items():
        if source_id in _jobs:
            continue
        first = records[0][1]
        signatures = {
            (
                str(record[1].get("requested_target") or ""),
                str(record[1].get("delivery_fit") or ""),
                str(record[1].get("spatial_upsampling") or ""),
                bool(record[1].get("final_private")),
                bool(record[1].get("final_explicit")),
            )
            for record in records
        }
        filenames = [record[0]["file_name"] for record in records]
        if len(signatures) != 1 or len(set(filenames)) != len(filenames):
            continue
        public_exists = [os.path.exists(record[0]["source_path"]) for record in records]
        if any(public_exists):
            if not all(public_exists):
                continue
            pending = []
            for item, _descriptor, _meta in records:
                try:
                    os.remove(item["native_path"])
                except OSError:
                    pending.append(item)
                    continue
                try:
                    os.remove(item["native_meta"])
                except OSError:
                    pass
            if pending:
                _jobs[source_id] = {
                    "id": source_id, "status": "completed",
                    "workspace": workspace, "out_dir": out_dir,
                    "session_id": owner,
                    "access_policy": {
                        "private": bool(first.get("final_private")),
                        "explicit": bool(first.get("final_explicit")),
                        "owner_session_id": owner if first.get("final_private") else None,
                    },
                    "private": bool(first.get("final_private")),
                    "explicit": bool(first.get("final_explicit")),
                    "source_remote": bool(first.get("source_remote", False)),
                    "params": records[0][2].get("params") or {},
                    "output_files": filenames,
                    "_h3_delivery_native": pending,
                    "_h3_delivery_cleanup_pending": True,
                }
                restored += 1
            continue
        staged = [record[0] for record in records]
        policy = {
            "private": bool(first.get("final_private")),
            "explicit": bool(first.get("final_explicit")),
            "owner_session_id": owner if first.get("final_private") else None,
        }
        recovery = {
            "nonce": uuid.uuid4().hex, "staged": staged,
            "spatial_upsampling": str(first.get("spatial_upsampling") or ""),
            "delivery_resolution": str(first.get("requested_target") or ""),
            "delivery_fit": str(first.get("delivery_fit") or ""),
            "manual_retry_count": max(int(r[1].get("manual_retry_count") or 0) for r in records),
            "manual_retry_limit": min(int(r[1].get("manual_retry_limit") or 2) for r in records),
            "active_job_id": "", "consumed": False,
            "restart_supported": True, "unsupported_after_restart_reason": "",
        }
        from services.oom_detect import normalize_failure_details
        recovery_evidence = []
        for _item, descriptor, _meta in records:
            candidate_oom = (
                descriptor.get("oom_info")
                if isinstance(descriptor.get("oom_info"), dict) else {}
            )
            candidate_confident_oom = candidate_oom.get("is_oom") is True
            candidate_failure = descriptor.get("failure_details")
            if not isinstance(candidate_failure, dict):
                candidate_failure = {
                    "stage": "delivery",
                    "code": (
                        "cuda_oom"
                        if candidate_confident_oom else "delivery_failed"
                    ),
                    "exception_type": "Exception",
                }
            else:
                candidate_failure = dict(candidate_failure)
            candidate_failure["is_oom"] = candidate_confident_oom
            if candidate_confident_oom:
                candidate_failure["code"] = "cuda_oom"
            elif candidate_failure.get("code") == "cuda_oom":
                candidate_failure["code"] = ""
            safe_failure = normalize_failure_details(candidate_failure)
            safe_oom_identity = {
                key: candidate_oom.get(key)
                for key in (
                    "is_oom", "requested_target", "retry_count", "actions",
                    "current_coefficient", "suggested_coefficient",
                )
                if key in candidate_oom
            }
            recovery_evidence.append((
                json.dumps(safe_failure, sort_keys=True),
                json.dumps(safe_oom_identity, sort_keys=True),
                safe_failure,
                candidate_oom,
            ))
        evidence_keys = {
            (failure_key, oom_key)
            for failure_key, oom_key, _failure, _oom in recovery_evidence
        }
        if len(evidence_keys) == 1:
            _failure_key, _oom_key, failure_details, stored_oom = (
                recovery_evidence[0]
            )
        else:
            # A crash between multi-output sidecar writes can leave mixed
            # evidence. Recovery must be order-independent and conservative.
            stored_oom = {}
            failure_details = normalize_failure_details({
                "stage": "delivery",
                "code": "delivery_failed",
                "exception_type": "Exception",
                "is_oom": False,
            })
        confident_oom = (
            stored_oom.get("is_oom") is True
            and failure_details.get("is_oom") is True
        )
        restored_job = {
            "id": source_id, "status": "failed", "workspace": workspace,
            "out_dir": records[0][0]["native_path"].rsplit(os.sep, 1)[0],
            "session_id": owner, "access_policy": policy,
            "private": policy["private"], "explicit": policy["explicit"],
            "source_remote": bool(first.get("source_remote", False)),
            "params": records[0][2].get("params") or {}, "output_files": [],
            "error": failure_details["detail"],
            "message": failure_details["detail"],
            "failure_details": failure_details,
            "_h3_delivery_native": staged,
            "_h3_delivery_recovery": recovery,
        }
        if confident_oom and failure_details.get("is_oom") is True:
            coefficient = float(
                wgp.server_config.get("vram_safety_coefficient", 0.80)
            )
            suggested = None if coefficient <= 0.50 else max(
                round(coefficient - 0.10, 2), 0.50,
            )
            if isinstance(stored_oom.get("current_coefficient"), (int, float)):
                coefficient = float(stored_oom["current_coefficient"])
            if (
                "suggested_coefficient" in stored_oom
                and stored_oom.get("suggested_coefficient") is None
            ):
                suggested = None
            elif isinstance(
                stored_oom.get("suggested_coefficient"), (int, float)
            ):
                suggested = float(stored_oom["suggested_coefficient"])
            safe_actions = [
                action for action in stored_oom.get("actions") or []
                if isinstance(action, str) and 0 < len(action) <= 64
                and all(
                    char.isalnum() or char in {"_", "-"}
                    for char in action
                )
            ][:8]
            restored_job["oom_info"] = {
                "is_oom": True,
                "stage": "h3_delivery",
                "requested_target": recovery["delivery_resolution"],
                "native_available": True,
                "retry_count": max(0, min(1, int(stored_oom.get("retry_count", 1)))),
                "recoverable": True,
                "actions": safe_actions or ["retained_native_reindexed"],
                "current_coefficient": coefficient,
                "suggested_coefficient": suggested,
                "message": (
                    "Delivery ran out of GPU memory after native generation "
                    "completed. The private native result is still available "
                    "for recovery."
                ),
            }
        _jobs[source_id] = restored_job
        restored += 1
    return restored


@api.on_event("startup")
def _start_h3_delivery_recovery_index() -> None:
    _reindex_h3_delivery_recoveries()


def _h3_delivery_recovery_token(job: dict, action: str) -> str:
    recovery = job.get("_h3_delivery_recovery") or {}
    payload = ":".join((
        str(job.get("id") or ""),
        str(action or ""),
        str(recovery.get("nonce") or ""),
        str(recovery.get("manual_retry_count") or 0),
    )).encode("utf-8")
    digest = hmac.new(_session_secret(), payload, hashlib.sha256).hexdigest()
    return f"h3r1.{digest}"


def _h3_delivery_recovery_state(job: dict) -> dict | None:
    recovery = job.get("_h3_delivery_recovery")
    if not isinstance(recovery, dict) or recovery.get("consumed"):
        return None
    staged = recovery.get("staged")
    if not isinstance(staged, list) or not _h3_delivery_native_available(staged):
        return None
    if str(job.get("status") or "") != "failed":
        return None
    return recovery


def _public_h3_delivery_recovery(job: dict) -> dict:
    recovery = _h3_delivery_recovery_state(job)
    if recovery is None:
        completed_job = str(
            (job.get("_h3_delivery_recovery") or {}).get("completed_job_id") or ""
        )
        return {
            "recoverable": False,
            "completed_recovery_job_id": completed_job or None,
            "actions": [],
        }
    manual_count = max(0, int(recovery.get("manual_retry_count") or 0))
    manual_limit = max(0, min(3, int(recovery.get("manual_retry_limit") or 0)))
    active_job_id = str(recovery.get("active_job_id") or "")
    actions = []
    if not active_job_id:
        actions.append({
            "action": "accept_native",
            "capability": _h3_delivery_recovery_token(job, "accept_native"),
            "method": "POST",
            "endpoint": f"/api/v1/jobs/{job['id']}/delivery-recovery/accept-native",
        })
        if manual_count < manual_limit:
            actions.append({
                "action": "retry_delivery",
                "capability": _h3_delivery_recovery_token(job, "retry_delivery"),
                "method": "POST",
                "endpoint": f"/api/v1/jobs/{job['id']}/delivery-recovery/retry",
            })
    return {
        "recoverable": True,
        "stage": "h3_delivery",
        "requested_target": str(recovery.get("delivery_resolution") or ""),
        "native_available": True,
        "manual_retry_count": manual_count,
        "manual_retry_limit": manual_limit,
        "active_recovery_job_id": active_job_id or None,
        "restart_supported": bool(recovery.get("restart_supported", False)),
        "unsupported_after_restart_reason": str(
            recovery.get("unsupported_after_restart_reason") or ""
        ) or None,
        "actions": actions,
    }


def _retry_h3_delivery_postprocess_only(
    job: dict,
    staged: list[dict],
    recovery: dict,
) -> list[str]:
    """Run one manual delivery attempt from retained native bytes only."""
    from services.oom_detect import delivery_oom_info, is_oom

    actions = _release_h3_delivery_vram()
    try:
        _reset_h3_delivery_work(staged)
        for item in staged:
            if is_cancel_requested(job):
                raise InterruptedError("H3 delivery recovery cancelled")
            _apply_spatial_upsampling_to_file(
                item["work_path"],
                str(recovery.get("spatial_upsampling") or ""),
                job=job,
            )
            if not update_job(
                job,
                phase="Delivery fit",
                message=(
                    "Fitting exact "
                    f"{recovery.get('delivery_resolution')} delivery..."
                ),
            ):
                raise InterruptedError("H3 delivery recovery cancelled")
            _apply_delivery_fit_to_file(
                item["work_path"],
                str(recovery.get("delivery_resolution") or ""),
                str(recovery.get("delivery_fit") or ""),
                job=job,
            )
        return _publish_h3_delivery_outputs(
            job,
            staged,
            recovery_action="retry_delivery",
            requested_target=str(recovery.get("delivery_resolution") or ""),
        )
    except InterruptedError:
        raise
    except Exception as error:
        for item in staged:
            try:
                os.remove(item["work_path"])
            except OSError:
                pass
        if is_cancel_requested(job):
            raise InterruptedError("H3 delivery recovery cancelled") from error
        oom_info = delivery_oom_info(
            error,
            float(wgp.server_config.get("vram_safety_coefficient", 0.80)),
            requested_target=str(recovery.get("delivery_resolution") or ""),
            native_available=_h3_delivery_native_available(staged),
            retry_count=0,
            actions=actions + ["manual_postprocess_retry"],
        )
        if oom_info is not None:
            oom_info["manual_retry_count"] = int(
                recovery.get("manual_retry_count") or 0
            )
        raise _H3DeliveryFailure(
            "Manual H3 delivery retry failed; the private native result was retained",
            oom_info=oom_info,
        ) from error


def _run_h3_delivery_recovery_job(job_id: str) -> None:
    job = _jobs[job_id]
    source_job_id = str(job.get("_h3_delivery_recovery_source_job") or "")
    action = str(job.get("_h3_delivery_recovery_action") or "")
    abort_state = {"abort": False}
    completed = False
    try:
        with generation_slot(_gen_lock, job) as acquired:
            if not acquired or not try_start(
                job,
                generation_lock=_gen_lock,
                phase="H3 delivery recovery",
                message=(
                    "Publishing retained native output..."
                    if action == "accept_native"
                    else "Retrying delivery from retained native output..."
                ),
            ):
                return
            if not register_abort_state(
                job, job_id, _active_gen_states, abort_state,
            ):
                return
            with _h3_delivery_recovery_lock:
                source_job = _jobs.get(source_job_id)
                recovery = (
                    source_job.get("_h3_delivery_recovery")
                    if isinstance(source_job, dict) else None
                )
                if (
                    not isinstance(recovery, dict)
                    or recovery.get("consumed")
                    or str(recovery.get("active_job_id") or "") != job_id
                    or not _h3_delivery_native_available(
                        recovery.get("staged") or [],
                    )
                ):
                    raise _H3DeliveryFailure("H3 delivery recovery is no longer available")
                staged = recovery["staged"]
                if action == "retry_delivery":
                    count = max(0, int(recovery.get("manual_retry_count") or 0))
                    limit = max(0, int(recovery.get("manual_retry_limit") or 0))
                    if count >= limit:
                        raise _H3DeliveryFailure("H3 delivery recovery is no longer available")
                    # Charge only after admission, start, registration, and
                    # retained-native validation: this is the actual attempt.
                    recovery["manual_retry_count"] = count + 1
                    if not _persist_h3_delivery_recovery_state(source_job):
                        recovery["manual_retry_count"] = count
                        raise _H3DeliveryFailure(
                            "H3 delivery recovery state could not be persisted"
                        )
            if action == "accept_native":
                _reset_h3_delivery_work(staged)
                output_files = _publish_h3_delivery_outputs(
                    job,
                    staged,
                    recovery_action="accept_native",
                    requested_target=str(recovery.get("delivery_resolution") or ""),
                )
            elif action == "retry_delivery":
                output_files = _retry_h3_delivery_postprocess_only(
                    job, staged, recovery,
                )
            else:
                raise _H3DeliveryFailure("Unsupported H3 delivery recovery action")
            completed = bool(finish_job(
                job,
                "completed",
                output_files=output_files,
                progress=100,
                phase="",
                message="Done",
                error=None,
            )) and not is_cancel_requested(job)
            if not completed:
                _rollback_h3_delivery_publication(job)
                return
            cleanup_complete = _finalize_h3_delivery_publication(job)
            with _h3_delivery_recovery_lock:
                recovery["consumed"] = True
                recovery["active_job_id"] = ""
                recovery["completed_job_id"] = job_id
                recovery["completed_action"] = action
                if cleanup_complete:
                    source_job.pop("_h3_delivery_native", None)
                    source_job.pop("_h3_delivery_cleanup_pending", None)
                else:
                    source_job["_h3_delivery_native"] = list(
                        job.get("_h3_delivery_native") or []
                    )
                    source_job["_h3_delivery_cleanup_pending"] = True
    except InterruptedError:
        _rollback_h3_delivery_publication(job)
        pass
    except _H3DeliveryFailure as error:
        updates = _safe_failure_updates(error, job)
        if error.oom_info:
            updates["oom_info"] = error.oom_info
        finish_job(job, "failed", **updates)
    except Exception as error:
        traceback.print_exc()
        finish_job(
            job,
            "failed",
            **_safe_failure_updates(
                error, job, stage="delivery", code="delivery_recovery_failed",
            ),
        )
    finally:
        if not completed:
            _rollback_h3_delivery_publication(job)
        unregister_abort_state(job_id, _active_gen_states, abort_state)
        with _h3_delivery_recovery_lock:
            source_job = _jobs.get(source_job_id)
            recovery = (
                source_job.get("_h3_delivery_recovery")
                if isinstance(source_job, dict) else None
            )
            if (
                isinstance(recovery, dict)
                and str(recovery.get("active_job_id") or "") == job_id
                and not recovery.get("consumed")
            ):
                recovery["active_job_id"] = ""
                recovery["nonce"] = uuid.uuid4().hex
                _persist_h3_delivery_recovery_state(source_job)
        if job.pop("_h3_delivery_workspace_reserved", False):
            _end_workspace_operation(str(job.get("workspace") or "default"))


class _GenerationStageFailure(RuntimeError):
    """Internal failure with safe public stage and code metadata."""

    def __init__(self, message: str, *, stage: str, code: str):
        super().__init__(message)
        self.stage = stage
        self.code = code


def _authoritative_h3_postprocess_outputs(
    file_names,
    producer_artifact_roles,
    *,
    is_multiclip: bool,
    join_output_file: str | None,
) -> list[str]:
    """Select only explicit final H3 videos for whole-file delivery work."""
    video_exts = {".mp4", ".webm", ".mkv"}
    videos = [
        str(name) for name in file_names
        if os.path.splitext(str(name))[1].lower() in video_exts
    ]
    # A segmented H3 task is not eligible for delivery until concat registered
    # its joined output. This keeps a stale/mistyped segment role from turning
    # into a Final at the boundary where concat failed or was cancelled.
    if is_multiclip and not join_output_file:
        return []
    # Repeated variants register their own producer-final joined files. Return
    # every requested authoritative final, never component/native segments.
    return [
        name for name in videos
        if producer_artifact_roles.get(name) == "final"
    ]


def _verified_h3_concat_output_names(
    job: dict,
    project_dir: str,
    candidate_names,
) -> list[str]:
    """Return candidate Finals backed by a verified concat checkpoint."""
    candidates = set(candidate_names or ())
    verified = []
    for unit in _queue_recovery_units(job):
        if unit.get("kind") != "h3_concat":
            continue
        try:
            matched = _queue_recovery_unit_matches(
                job,
                kind="h3_concat",
                variant=max(0, int(unit.get("variant", 0) or 0)),
                index=0,
                project_dir=project_dir,
            )
        except (TypeError, ValueError):
            matched = None
        if matched is None:
            continue
        for artifact in matched.get("artifacts") or []:
            name = (
                artifact.get("basename")
                if isinstance(artifact, dict) else None
            )
            if name in candidates and name not in verified:
                verified.append(name)
    return verified


def _job_failure_positions(job: dict) -> tuple[dict | None, dict | None, dict | None]:
    """Return bounded public progress coordinates without prompts or paths."""
    try:
        segment = {
            "current": max(0, int(job.get("clip_current") or 0)),
            "total": max(0, int(job.get("clip_total") or 0)),
            "variant": max(1, int(job.get("current_output") or 1)),
        }
    except (TypeError, ValueError):
        segment = None
    try:
        window = {
            "current": max(0, int(job.get("window_current") or 0)),
            "total": max(0, int(job.get("window_total") or 0)),
        }
    except (TypeError, ValueError):
        window = None
    try:
        step = {
            "current": max(0, int(job.get("step") or 0)),
            "total": max(0, int(job.get("total_steps") or 0)),
        }
    except (TypeError, ValueError):
        step = None
    return segment, window, step


def _failure_stage_from_job(job: dict) -> str:
    phase = str(job.get("phase") or job.get("message") or "").casefold()
    if "vae decod" in phase:
        return "vae_decode"
    if "seal" in phase or "checkpoint" in phase:
        return "segment_checkpoint"
    if "denois" in phase:
        return "denoise"
    if "flashvsr" in phase or "upscal" in phase:
        return "flashvsr"
    if "delivery" in phase or "fitting exact" in phase:
        return "delivery"
    if "audio" in phase or "mux" in phase:
        return "audio_mux"
    if "post" in phase or "film grain" in phase or "voice clon" in phase:
        return "postprocess"
    if "finaliz" in phase or "publish" in phase:
        return "publication"
    return "generation"


def _safe_failure_updates(error, job: dict, *, stage=None, code=None) -> dict:
    """Translate an exception/envelope into additive safe lifecycle fields."""
    from services.oom_detect import (
        build_failure_details,
        normalize_failure_details,
        oom_info_from_failure_details,
    )

    segment, window, step = _job_failure_positions(job)
    embedded = getattr(error, "failure_details", None)
    if isinstance(error, dict):
        embedded = error
    if isinstance(embedded, dict):
        details = normalize_failure_details(
            embedded, segment=segment, window=window, step=step,
        )
    else:
        exception = error if isinstance(error, Exception) else RuntimeError(str(error))
        details = build_failure_details(
            exception,
            stage=(
                stage
                or getattr(error, "stage", None)
                or _failure_stage_from_job(job)
            ),
            code=code or getattr(error, "code", None),
            segment=segment,
            window=window,
            step=step,
        )
    updates = {
        "failure_details": details,
        "error": details["detail"],
        "message": details["detail"],
    }
    try:
        coefficient = float(
            wgp.server_config.get("vram_safety_coefficient", 0.80)
        )
        oom_info = oom_info_from_failure_details(details, coefficient)
        if oom_info is not None:
            updates["oom_info"] = oom_info
    except Exception:
        pass
    return updates


# ============================================================================
# Standalone post-processing "Tools" — apply FlashVSR upscale or SeedVC
# revoice to ANY existing clip (a gallery output or an uploaded file),
# independent of a generation. These reuse the job plumbing (_jobs /
# _gen_lock / /status / /cancel) but run a thin post-processing path instead
# of the full model pipeline. (edit_video in wgp.py does the same work but is
# coupled to the Gradio gen state — send_cmd / get_gen_info / file_list — so
# we extract just the load -> upscale -> save -> remux core here.)
# See memory/project_tools_postprocessing.md.
# ============================================================================

def _resolve_authorized_project_asset_media(
    request: Request,
    value: str,
    workspace: str,
) -> str | None:
    """Resolve only manifest-declared media from one unlocked project card."""
    _require_project_access(request, workspace)
    try:
        store = _project_asset_store()
        for asset in store.list_assets(workspace, "main"):
            for variant in asset.get("variants") or []:
                if not _can_access_project_asset_variant(
                    variant, request.state.maestro_session_id,
                ):
                    continue
                for output in variant.get("outputs") or []:
                    policy = (
                        output.get("metadata")
                        if isinstance(output.get("metadata"), dict)
                        else {}
                    )
                    if not can_access_output(
                        policy, request.state.maestro_session_id,
                    ):
                        continue
                    relative = output.get("relative_path")
                    if not isinstance(relative, str):
                        continue
                    candidate = store.resolve_output_path(workspace, "main", relative)
                    matches = (
                        value == relative
                        if not os.path.isabs(value)
                        else os.path.normcase(os.path.abspath(value))
                        == os.path.normcase(os.path.abspath(candidate))
                    )
                    if matches and os.path.isfile(candidate):
                        return candidate
    except (OSError, TypeError, ValueError, KeyError):
        pass
    return None


def _resolve_authorized_request_media(
    request: Request,
    raw_path: str,
    workspace: str | None = None,
) -> str | None:
    """Resolve one direct media file after its owning scope authorizes it.

    Accepted sources are a direct output in ``workspace`` or a direct upload
    in ``uploads/`` or ``uploads/audio/``. Relative values must be bare
    filenames. Absolute values must lexically equal the contained candidate;
    traversal spellings and symlink aliases are deliberately rejected.
    """
    from services.win_safe_files import (
        is_safe_direct_basename,
        safe_direct_file_under,
    )

    if not isinstance(raw_path, str) or not raw_path or "\x00" in raw_path:
        return None
    value = raw_path.strip()
    if not value:
        return None
    if os.path.normpath(value) != value:
        return None
    is_absolute = os.path.isabs(value)
    name = os.path.basename(value)
    if not is_safe_direct_basename(name) or name.startswith("."):
        return None
    if not is_absolute and value != name:
        return None

    def _matches(candidate: str) -> bool:
        if not is_absolute:
            return True
        return os.path.normcase(os.path.abspath(value)) == os.path.normcase(candidate)

    def _authorized_upload(root: str) -> tuple[str | None, bool]:
        lexical = os.path.abspath(os.path.join(os.path.realpath(root), name))
        matching_entry = _matches(lexical) and os.path.lexists(lexical)
        candidate = safe_direct_file_under(root, name)
        if (
            candidate
            and _matches(candidate)
            and os.path.isfile(candidate)
            and can_access_upload(candidate, request.state.maestro_session_id)
        ):
            return candidate, True
        return None, matching_entry

    upload_roots = (
        os.path.join(os.getcwd(), "uploads"),
        os.path.join(os.getcwd(), "uploads", "audio"),
    )

    # Resolve upload ownership before touching project state. Remote upload
    # responses intentionally contain only a basename, and a first-time
    # session may not yet have a selected project. A matching upload entry is
    # authoritative: missing/malformed/foreign metadata and final-component
    # symlinks fail closed instead of falling through to a same-named output.
    matching_upload_entry = False
    for root in upload_roots:
        authorized, matching_entry = _authorized_upload(root)
        if authorized:
            return authorized
        matching_upload_entry = matching_upload_entry or matching_entry
    if matching_upload_entry:
        return None

    try:
        selected_workspace = _request_project_workspace(request, workspace)
    except HTTPException:
        # Direct uploads above remain independently session-owned and do not
        # require a project. A project-backed source must never inherit the
        # host's global active workspace for an external request.
        return None

    # Project reference cards copy sanctioned media into a project-owned
    # store. Match only manifest-declared outputs from the authorized project;
    # never accept an arbitrary path merely because it is under storage/.
    asset_resolver = globals().get("_resolve_authorized_project_asset_media")
    if callable(asset_resolver):
        project_asset = asset_resolver(request, value, selected_workspace)
        if project_asset:
            return project_asset

    try:
        _out_dir, output_path, _sidecar = _require_authorized_output(
            request, selected_workspace, name,
        )
        if _matches(output_path):
            return output_path
    except HTTPException as exc:
        if exc.status_code not in (400, 404):
            raise

    return None


def _inherit_media_access_policy(
    media_paths: list[str],
    workspace: str,
    owner_session_id: str,
) -> dict:
    """Aggregate privacy from authorized inputs for derived tool outputs."""
    private = False
    explicit = False
    out_dir = os.path.realpath(_workspace_dir(workspace))
    for media_path in media_paths:
        resolved = os.path.realpath(media_path)
        sidecar = None
        if os.path.dirname(resolved) == out_dir:
            sidecar = load_media_sidecars(out_dir, {os.path.basename(resolved)}).get(
                os.path.basename(resolved)
            )
        else:
            try:
                sidecar = read_upload_access_sidecar(resolved)
            except ValueError:
                sidecar = None
            # Manifest-declared project assets live outside the gallery and
            # are visible only through a project lock. Preserve that boundary
            # when creating a normal gallery output from one.
            if sidecar is None and "/storage/project-assets/" in resolved.replace("\\", "/"):
                private = True
        if isinstance(sidecar, dict):
            private = private or bool(sidecar.get("private", False))
            explicit = explicit or bool(sidecar.get("explicit", False))
    return {"private": private, "explicit": explicit}


def _write_tool_sidecar(out_dir, filename, *, source_name, tool, params, elapsed, job_id):
    """Write a .meta.json sidecar so a Tools output shows up in the gallery
    with the right mode + edit_sub_mode tag (mirrors _run_sfx_generation)."""
    sidecar = {
        "params": {**params, "edit_sub_mode": tool},
        "generation_mode": "video",
        "tool": tool,
        "tool_source": source_name,
        "job_id": job_id,
        "generation_time": round(elapsed),
        "created_at": time.time(),
        "output_filename": filename,
    }
    job = _jobs.get(job_id) or {}
    stamp_sidecar_policy(
        sidecar,
        job.get("access_policy") or {},
        workspace=job.get("workspace") or "default",
    )
    meta_path = os.path.join(out_dir, os.path.splitext(filename)[0] + ".meta.json")
    temp_path = f"{meta_path}.{uuid.uuid4().hex[:8]}.tmp"
    try:
        with open(temp_path, "w", encoding="utf-8") as f:
            json.dump(sidecar, f, indent=2)
            f.flush()
            os.fsync(f.fileno())
        os.replace(temp_path, meta_path)
    except Exception as exc:
        for path in (temp_path, os.path.join(out_dir, filename)):
            try:
                os.remove(path)
            except OSError:
                pass
        raise RuntimeError(
            f"Failed to publish protected {tool} metadata for {filename}"
        ) from exc


def _run_tool_upscale(job_id: str):
    """Background worker: upscale an existing clip with the configured spatial
    upsampler (FlashVSR / Lanczos), preserving the original audio. Thin extract
    of edit_video's postprocessing path — no model generation/Gradio state."""
    job = _jobs[job_id]
    start_time = time.time()
    abort_state = {"abort": False}
    audio_tracks = []
    with generation_slot(_gen_lock, job) as acquired:
        if not acquired:
            return False
        try:
            if not try_start(
                job,
                generation_lock=_gen_lock,
                message="Preparing upscale...",
                phase="Preparing",
            ):
                return False
            if not register_abort_state(
                job, job_id, _active_gen_states, abort_state,
            ):
                return False

            params = job["params"]
            workspace = job.get("workspace")
            out_dir = job.get("out_dir") or wgp.save_path
            os.makedirs(out_dir, exist_ok=True)
            wgp.save_path = out_dir

            method = params.get("method") or "flashvsr2"
            video_source = _resolve_tool_clip_path(params.get("video_path"), workspace)
            if not video_source:
                finish_job(
                    job, "failed", error="Input clip not found",
                    message="Error: input clip not found",
                )
                return False

            before = set(os.listdir(out_dir)) if os.path.isdir(out_dir) else set()

            from shared.utils.utils import get_video_info
            fps, _width, _height, _frames = get_video_info(video_source)

            # Preserve original audio — re-muxed onto the upscaled video.
            audio_tracks, audio_metadata = wgp.extract_audio_tracks(video_source)
            has_audio = len(audio_tracks) > 0

            if not update_job(
                job, message="Upscaling...", phase="Upscaling", progress=5,
            ):
                wgp.cleanup_temp_audio_files(audio_tracks)
                return False

            def _abort():
                return bool(abort_state.get("abort")) or is_cancel_requested(job)

            # FlashVSR's _report_progress always calls back with
            # (phase, current_step, total_steps); the latter two may be None.
            def _progress(phase, current_step=None, total_steps=None):
                changes = {}
                if phase:
                    changes.update(message=str(phase), phase=str(phase))
                try:
                    if total_steps:
                        step = int(current_step or 0)
                        total = int(total_steps)
                        # Map reported steps onto 5..95% so the bar moves.
                        changes.update(
                            step=step,
                            total_steps=total,
                            progress=max(5, min(95, int(step / total * 100))),
                        )
                except (TypeError, ValueError, ZeroDivisionError):
                    pass
                if changes:
                    update_job(job, **changes)

            container = wgp.server_config.get("video_container", "mp4")
            codec = wgp.server_config.get("video_output_codec", None)
            final_path = wgp.get_available_filename(out_dir, os.path.basename(video_source), "_upscaled", force_extension=f".{container}")

            if wgp.flashvsr.is_upsampling(method):
                # Chunked engine (shared with the post-generation pass) —
                # bounds RAM on long clips. The previous unchunked path let
                # FlashVSR allocate its float32 output buffer for the WHOLE
                # video: a 4-minute 2x upscale tried 280+ GB and died in
                # DefaultCPUAllocator.
                tmp_path = _chunked_flashvsr_upscale(video_source, method, job=job, abort_check=_abort, progress_callback=_progress)
                if tmp_path is None or _abort():
                    if tmp_path and os.path.isfile(tmp_path):
                        try:
                            os.remove(tmp_path)
                        except OSError:
                            pass
                    wgp.cleanup_temp_audio_files(audio_tracks)
                    return False
                if has_audio:
                    wgp.combine_video_with_audio_tracks(tmp_path, audio_tracks, final_path, audio_metadata=audio_metadata)
                    try:
                        os.remove(tmp_path)
                    except OSError:
                        pass
                    wgp.cleanup_temp_audio_files(audio_tracks)
                else:
                    os.replace(tmp_path, final_path)
            else:
                # Lanczos & friends — cheap stateless resize, legacy inline path.
                sample = wgp.get_resampled_video(video_source, 0, wgp.max_source_video_frames, fps)
                sample = sample.permute(-1, 0, 1, 2)  # [F,H,W,C] -> [C,F,H,W]
                sample = wgp.perform_spatial_upsampling(
                    sample, method, seed=int(params.get("seed", -1)),
                    abort_callback=_abort, progress_callback=_progress,
                )

                if _abort():
                    return False

                output_fps = round(fps)
                if has_audio:
                    tmp_path = wgp.get_available_filename(out_dir, os.path.basename(video_source), "_uptmp", force_extension=f".{container}")
                    wgp.save_video(tensor=sample[None], save_file=tmp_path, fps=output_fps, nrow=1, normalize=True, value_range=(-1, 1), codec_type=codec, container=container)
                    wgp.combine_video_with_audio_tracks(tmp_path, audio_tracks, final_path, audio_metadata=audio_metadata)
                    try:
                        os.remove(tmp_path)
                    except OSError:
                        pass
                    wgp.cleanup_temp_audio_files(audio_tracks)
                else:
                    wgp.save_video(tensor=sample[None], save_file=final_path, fps=output_fps, nrow=1, normalize=True, value_range=(-1, 1), codec_type=codec, container=container)

                sample = None
            after = set(os.listdir(out_dir)) if os.path.isdir(out_dir) else set()
            new_files = sorted(f for f in (after - before) if not f.endswith(".meta.json") and "_uptmp" not in f)
            record_job_outputs(job, new_files)
            if is_cancel_requested(job):
                return False
            for fname in new_files:
                _write_tool_sidecar(out_dir, fname, source_name=os.path.basename(video_source), tool="upscale", params={"method": method, "model_type": "post_processing"}, elapsed=time.time() - start_time, job_id=job_id)

            completed = finish_job(
                job,
                "completed",
                progress=100,
                phase="",
                message="Done",
            )
            print(f"[Tools/upscale] {os.path.basename(video_source)} -> {new_files} ({wgp.format_time(time.time() - start_time)})")
            return completed
        except Exception as e:
            traceback.print_exc()
            finish_job(job, "failed", error=str(e), message=f"Error: {e}")
            return False
        finally:
            unregister_abort_state(job_id, _active_gen_states, abort_state)
            try:
                wgp.cleanup_temp_audio_files(audio_tracks)
            except Exception:
                pass
            try:
                wgp.release_flashvsr_vram()
            except Exception:
                pass


def _run_tool_revoice(job_id: str):
    """Background worker: replace the voice(s) in an existing clip via SeedVC.
    Always writes a NEW file (copy first, convert the copy) — the source clip
    is never mutated."""
    import shutil
    job = _jobs[job_id]
    start_time = time.time()
    abort_state = {"abort": False}
    final_path = None
    with generation_slot(_gen_lock, job) as acquired:
        if not acquired:
            return False
        try:
            if not try_start(
                job,
                generation_lock=_gen_lock,
                message="Preparing revoice...",
                phase="Preparing",
            ):
                return False
            if not register_abort_state(
                job, job_id, _active_gen_states, abort_state,
            ):
                return False

            params = job["params"]
            workspace = job.get("workspace")
            out_dir = job.get("out_dir") or wgp.save_path
            os.makedirs(out_dir, exist_ok=True)

            video_source = _resolve_tool_clip_path(params.get("video_path"), workspace)
            if not video_source:
                finish_job(
                    job, "failed", error="Input clip not found",
                    message="Error: input clip not found",
                )
                return False

            mode = params.get("mode", "single")
            voice_refs = []
            for ref in (params.get("voice_ref_paths") or []):
                resolved = _resolve_tool_clip_path(ref, workspace)
                if resolved:
                    voice_refs.append(resolved)
            if not voice_refs:
                finish_job(
                    job, "failed", error="No voice reference found",
                    message="Error: no voice reference found",
                )
                return False

            # Copy source -> new output, then revoice the copy in place so the
            # original gallery clip is never modified.
            src_ext = os.path.splitext(video_source)[1] or ".mp4"
            final_path = wgp.get_available_filename(out_dir, os.path.basename(video_source), "_revoiced", force_extension=src_ext)
            if is_cancel_requested(job):
                return False
            shutil.copyfile(video_source, final_path)
            if is_cancel_requested(job):
                try:
                    os.remove(final_path)
                except OSError:
                    pass
                return False

            if not update_job(
                job,
                message="Replacing voice (SeedVC)...",
                phase="Voice Conversion",
                progress=10,
            ):
                try:
                    os.remove(final_path)
                except OSError:
                    pass
                return False

            from postprocessing.voice_clone import apply_voice_clone_to_file
            ok = apply_voice_clone_to_file(
                final_path, voice_refs, mode=mode,
                diffusion_steps=int(params.get("diffusion_steps", 25)),
                cfg_rate=float(params.get("cfg_rate", 0.5)),
            )
            if is_cancel_requested(job):
                try:
                    os.remove(final_path)
                except OSError:
                    pass
                return False
            if not ok:
                try:
                    os.remove(final_path)
                except OSError:
                    pass
                finish_job(
                    job,
                    "failed",
                    error="Voice replacement failed (clip has no audio, or SeedVC is unavailable)",
                    message="Error: voice replacement failed",
                )
                return False

            fname = os.path.basename(final_path)
            if not update_job(job, output_files=[fname]):
                try:
                    os.remove(final_path)
                except OSError:
                    pass
                return False
            _write_tool_sidecar(out_dir, fname, source_name=os.path.basename(video_source), tool="revoice", params={"mode": mode, "model_type": "post_processing"}, elapsed=time.time() - start_time, job_id=job_id)

            completed = finish_job(
                job,
                "completed",
                progress=100,
                phase="",
                message="Done",
            )
            print(f"[Tools/revoice] {os.path.basename(video_source)} -> {fname} ({wgp.format_time(time.time() - start_time)})")
            return completed
        except Exception as e:
            traceback.print_exc()
            finish_job(job, "failed", error=str(e), message=f"Error: {e}")
            return False
        finally:
            unregister_abort_state(job_id, _active_gen_states, abort_state)


@api.post("/api/v1/tools/upscale")
async def tools_upscale(request: Request):
    """Upscale an existing clip (a gallery output or an uploaded file) with the
    configured spatial upsampler. Returns a job_id; poll /api/v1/status/{job_id}.

    Body: { video_path: str, method?: str (default "flashvsr2"),
            seed?: int, workspace?: str }
    """
    body = await request.json()
    video_path = body.get("video_path")
    if not video_path:
        raise HTTPException(status_code=400, detail="video_path is required")
    workspace = body.get("workspace") or _get_active_workspace()
    job_out_dir = _require_project_access(request, workspace)
    resolved = _resolve_authorized_request_media(request, video_path, workspace)
    if not resolved:
        raise HTTPException(status_code=400, detail=f"Clip not found: {video_path}")
    inherited = _inherit_media_access_policy(
        [resolved], workspace, request.state.maestro_session_id,
    )
    if body.get("private_output") is None:
        body["private_output"] = inherited["private"]
    if body.get("explicit_output") is None:
        body["explicit_output"] = inherited["explicit"]

    job_id = uuid.uuid4().hex[:8]
    _jobs[job_id] = {
        "id": job_id, "status": "queued", "progress": 0, "step": 0, "total_steps": 0,
        "source_remote": bool(_request_remote.get()),
        "phase": "", "message": "Queued (upscale)", "created_at": time.time(),
        "params": {
            "video_path": resolved,
            "method": body.get("method") or "flashvsr2",
            "seed": body.get("seed", -1),
            "private_output": body.get("private_output"),
            "explicit_output": body.get("explicit_output"),
        },
        "output_files": [], "error": None,
        "workspace": workspace, "out_dir": job_out_dir,
    }
    threading.Thread(target=_run_tool_upscale, args=(job_id,), daemon=False).start()
    return {"job_id": job_id, "status": "queued"}


@api.post("/api/v1/tools/revoice")
async def tools_revoice(request: Request):
    """Replace the voice(s) in an existing clip via SeedVC. Returns a job_id.

    Body: { video_path: str, voice_ref_paths: [str, ...],
            mode?: "single"|"two", diffusion_steps?: int, cfg_rate?: float,
            workspace?: str }
    """
    body = await request.json()
    video_path = body.get("video_path")
    if not video_path:
        raise HTTPException(status_code=400, detail="video_path is required")
    workspace = body.get("workspace") or _get_active_workspace()
    job_out_dir = _require_project_access(request, workspace)
    resolved = _resolve_authorized_request_media(request, video_path, workspace)
    if not resolved:
        raise HTTPException(status_code=400, detail=f"Clip not found: {video_path}")

    voice_refs = body.get("voice_ref_paths")
    if not voice_refs and body.get("voice_ref_path"):
        voice_refs = [body.get("voice_ref_path")]
    if not voice_refs:
        raise HTTPException(status_code=400, detail="At least one voice_ref_path is required")

    mode = body.get("mode", "single")
    if mode not in ("single", "two"):
        mode = "single"

    resolved_voice_refs = [
        resolved_ref for ref in voice_refs
        if (resolved_ref := _resolve_authorized_request_media(request, ref, workspace))
    ]
    if not resolved_voice_refs:
        raise HTTPException(status_code=400, detail="No authorized voice reference found")
    inherited = _inherit_media_access_policy(
        [resolved, *resolved_voice_refs],
        workspace,
        request.state.maestro_session_id,
    )
    if body.get("private_output") is None:
        body["private_output"] = inherited["private"]
    if body.get("explicit_output") is None:
        body["explicit_output"] = inherited["explicit"]

    job_id = uuid.uuid4().hex[:8]
    _jobs[job_id] = {
        "id": job_id, "status": "queued", "progress": 0, "step": 0, "total_steps": 0,
        "source_remote": bool(_request_remote.get()),
        "phase": "", "message": "Queued (revoice)", "created_at": time.time(),
        "params": {
            "video_path": resolved,
            "voice_ref_paths": resolved_voice_refs,
            "mode": mode,
            "diffusion_steps": body.get("diffusion_steps", 25),
            "cfg_rate": body.get("cfg_rate", 0.5),
            "private_output": body.get("private_output"),
            "explicit_output": body.get("explicit_output"),
        },
        "output_files": [], "error": None,
        "workspace": workspace, "out_dir": job_out_dir,
    }
    threading.Thread(target=_run_tool_revoice, args=(job_id,), daemon=False).start()
    return {"job_id": job_id, "status": "queued"}


def _phase_progress_values(message: object, step: int = 0, total: int = 0) -> dict:
    """Normalize one producer phase without inventing a denominator."""
    import re

    text = str(message or "")
    stable_phase = re.sub(
        (
            r"\s*\|\s*(?:"
            r"\d+:\d+(?::\d+)?"
            r"|(?:\d+h\s+)?(?:\d+m\s+)?\d+(?:\.\d+)?s"
            r")\s*$"
        ),
        "",
        text,
    ).strip()
    return {
        "message": text,
        "phase": stable_phase or text,
        "progress_indeterminate": not bool(total and total > 0),
    }


def _window_progress_values(
    step: object,
    total: object,
    previous_percent: object = 0,
) -> tuple[float, int, bool]:
    """Return measurable step progress, preserving it during phase-only work."""
    try:
        step_value = max(0.0, float(step or 0))
        total_value = max(0.0, float(total or 0))
        previous = max(0, min(100, int(float(previous_percent or 0))))
    except (TypeError, ValueError):
        step_value = total_value = 0.0
        previous = 0
    if total_value <= 0:
        return previous / 100.0, previous, False
    fraction = max(0.0, min(1.0, step_value / total_value))
    return fraction, int(fraction * 100), True


def _preserve_indeterminate_progress(
    updates: dict,
    previous: dict,
    has_exact_progress: bool,
) -> dict:
    """Keep completed measurable work visible during denominatorless phases."""
    if has_exact_progress:
        return updates
    for key in ("progress", "window_progress", "overall_progress", "clip_progress"):
        try:
            updates[key] = max(0, min(100, int(previous.get(key) or 0)))
        except (TypeError, ValueError):
            updates[key] = 0
    return updates


def _subtask_eta_progress_updates(
    job: dict,
    progress_updates: dict,
    stream_data: object,
    timestamp: float | None = None,
) -> dict:
    """Track current-step timing from the raw WGP ``progress`` payload."""
    if not isinstance(stream_data, list) or len(stream_data) < 2:
        return {}
    now = time.time() if timestamp is None else float(timestamp)
    message = str(stream_data[1] or "")
    current_window = int(progress_updates.get("window_current") or 0)
    warmup_phase = "Running first H3 denoising step (runtime warmup)"
    if warmup_phase in message:
        return {
            "_eta_subtask_started_at": now,
            "_eta_subtask_baseline_step": 0.0,
            "_eta_subtask_inactive_at_start": float(
                job.get("_eta_inactive_seconds") or 0
            ),
            "_eta_subtask_window_current": current_window,
        }
    raw_position = stream_data[0]
    if not isinstance(raw_position, tuple) or len(raw_position) < 2:
        return {}
    try:
        step = float(raw_position[0] or 0)
        total = float(raw_position[1] or 0)
        subtask_started = float(job.get("_eta_subtask_started_at") or 0)
        subtask_window = int(job.get("_eta_subtask_window_current") or 0)
    except (TypeError, ValueError):
        return {}
    if total <= 0 or (subtask_started > 0 and subtask_window == current_window):
        return {}
    # Producers without an explicit pre-step boundary begin timing at the
    # observed step. ETA remains unavailable until a later measurable step.
    return {
        "_eta_subtask_started_at": now,
        "_eta_subtask_baseline_step": step,
        "_eta_subtask_inactive_at_start": float(
            job.get("_eta_inactive_seconds") or 0
        ),
        "_eta_subtask_window_current": current_window,
    }


def _generation_tasks_succeeded(
    *, completed: int, skipped: int, total_tasks: int, cancelled: bool,
) -> bool:
    """Return true only when every admitted task genuinely completed."""
    return bool(
        not cancelled
        and total_tasks > 0
        and skipped == 0
        and completed == total_tasks
    )


def _run_generation(job_id: str, *, finalize: bool = True) -> bool:
    """Build and run a job, optionally deferring success finalization."""
    from shared.utils.thread_utils import AsyncStream, async_run
    import inspect

    job = _jobs[job_id]
    start_time = time.time()
    abort_state = None

    # Director/internal callers can enter this worker without using the main
    # HTTP submission endpoint. Stamp them before registration so they receive
    # the same residency-aware ordering, while preserving all existing tiers.
    _stamp_requested_generation_residency(job, replace=True)

    with generation_slot(_gen_lock, job) as acquired:
        if not acquired:
            return False
        try:
            if not try_start(
                job, generation_lock=_gen_lock, message="Preparing...",
            ):
                return False

            # Per-job VRAM coefficient adjustment — accounts for active
            # LoRAs and pipeline stage count beyond what the auto-tuned
            # base captures. Mutates wgp.args.vram_safety_coefficient
            # in place; restored in the finally block below.
            _apply_per_job_coefficient(job)

            # A delivery checkpoint owns verified protected native bytes. It
            # is intentionally handled before task planning, model-version
            # checks, concat, or any denoising setup, so restart can only
            # replay the delivery safe unit.
            if _queue_recovery_delivery_pending(job) is not None:
                abort_state = {"abort": False}
                if not register_abort_state(
                    job,
                    job_id,
                    _active_gen_states,
                    abort_state,
                ):
                    return False
                return _resume_pending_h3_delivery_only(job)

            # Build minimal state (same structure as CLI mode, line 11935 of wgp.py)
            state = {
                "gen": {
                    "queue": [],
                    "in_progress": False,
                    "abort": False,
                    "file_list": [],
                    "artifact_list": [],
                    "file_settings_list": [],
                    "audio_file_list": [],
                    "audio_file_settings_list": [],
                    "selected": 0,
                    "audio_selected": 0,
                    "prompt_no": 0,
                    "prompts_max": 0,
                    "repeat_no": 0,
                    "total_generation": 1,
                    "window_no": 0,
                    "total_windows": 0,
                    "progress_status": "",
                    "process_status": "process:main",
                },
                "loras": [],
            }

            # Build task manifest from user params
            raw_params = job["params"].copy()
            validation_reference_bytes = job.get(
                "_h3_turbo_validation_reference_bytes"
            )
            server_h3_turbo_validation_authorized = (
                job.get("_h3_turbo_validation_authorized") is True
                and isinstance(validation_reference_bytes, bytes)
                and len(validation_reference_bytes)
                == _H3_TURBO_BENCHMARK_REFERENCE_BYTES
                and hashlib.sha256(validation_reference_bytes).hexdigest()
                == _H3_TURBO_BENCHMARK_REFERENCE_SHA256
            )
            if (
                job.get("_h3_turbo_validation_authorized") is True
                and not server_h3_turbo_validation_authorized
            ):
                finish_job(
                    job,
                    "failed",
                    error="Synthetic H3 validation input is unavailable.",
                    message="Synthetic H3 validation input is unavailable",
                )
                return False
            server_prepared_h3_plan = _trusted_h3_prepared_plan(
                raw_params, allow_server_prepared=True,
            )
            if server_prepared_h3_plan is None:
                try:
                    _apply_h3_adaptive_checkpoint(raw_params)
                except ValueError as exc:
                    finish_job(
                        job,
                        "failed",
                        error=f"Unable to select MiniMax H3 checkpoint: {exc}",
                        message="MiniMax H3 conditioning is incompatible",
                    )
                    return False
            _benchmark_custom = raw_params.get("custom_settings")
            _capture_h3_benchmark = bool(
                str(raw_params.get("model_type") or "") in _H3_LONG_STUDIO_MODELS
            )
            if _capture_h3_benchmark and torch.cuda.is_available():
                try:
                    torch.cuda.reset_peak_memory_stats()
                except Exception:
                    pass

            requested_model = str(raw_params.get("model_type") or "")

            # Director workers can submit generation dictionaries directly,
            # bypassing the HTTP endpoint. Apply the same H3 long-form guard
            # here so no oversized seamless scene reaches the native model
            # unclipped and no explicit scene is silently clamped.
            try:
                _require_h3_native_boundary_experimental(raw_params)
                _validate_h3_sampling_steps(raw_params)
                _validate_h3_explicit_multiclip_request(raw_params)
                worker_h3_plan = _prepare_h3_long_studio_request(raw_params)
                trusted_h3_plan = _trusted_h3_prepared_plan(
                    raw_params,
                    worker_h3_plan,
                    allow_server_prepared=True,
                )
                if trusted_h3_plan:
                    _validate_h3_segment_plan(
                        raw_params,
                        clip_frames=list(
                            trusted_h3_plan.get("clip_frames") or []
                        ),
                        segment_models=list(
                            trusted_h3_plan.get("segment_models") or []
                        ),
                        first_anchor=trusted_h3_plan.get(
                            "original_image_start"
                        ),
                        last_anchor=trusted_h3_plan.get(
                            "original_image_end"
                        ),
                    )
                _require_h3_acceleration_available(
                    raw_params,
                    trusted_h3_plan,
                    allow_server_prepared=True,
                )
                _classify_generation_maturity(
                    raw_params, trusted_h3_plan,
                )
                _require_h3_generation_terms(raw_params, trusted_h3_plan)
            except HTTPException as exc:
                finish_job(
                    job,
                    "failed",
                    error=str(exc.detail),
                    message="MiniMax H3 terms are required",
                )
                return False
            except (TypeError, ValueError) as exc:
                finish_job(
                    job,
                    "failed",
                    error=f"Unable to plan long MiniMax H3 generation: {exc}",
                    message="MiniMax H3 long-form planning failed",
                )
                return False
            if trusted_h3_plan:
                job["params"] = raw_params.copy()
                job["window_total"] = int(
                    trusted_h3_plan.get("clip_count") or 0
                )
                job["clip_total"] = job["window_total"]
                job["h3_segment_plan"] = _public_h3_long_plan(
                    trusted_h3_plan,
                )

            # Versioned repositories are checked inside the generation slot,
            # after request/plan validation and before any model load, so no
            # load can race a checkpoint replacement. Offline checks retain
            # the recorded last-known-good URL and proceed.
            requested_model_def = wgp.get_model_def(requested_model) or {}
            effective_h3_models = set(
                _h3_effective_model_types(raw_params, trusted_h3_plan)
            )
            requested_model_is_effective = (
                requested_model not in _H3_LONG_STUDIO_MODELS
                or requested_model in effective_h3_models
            )
            requested_model_checked = False
            if requested_model and requested_model_is_effective and (
                isinstance(requested_model_def.get("model_update"), dict)
                or isinstance(requested_model_def.get("component_updates"), list)
            ):
                update = _ensure_versioned_model_current(requested_model)
                requested_model_checked = True
                component_download_required = any(
                    isinstance(value, dict) and value.get("status") == "download_required"
                    for value in (update.get("components") or {}).values()
                )
                if update.get("status") == "download_required" or component_download_required:
                    # The ordinary WanGP loader downloads this immutable URL;
                    # a later successful pre-download records its manifest.
                    job["message"] = "Downloading latest compatible model version..."

            # Adaptive long-form plans may use checkpoints other than the
            # request's temporary effective model. Apply each recorded update
            # policy while the generation slot is exclusive, before any one
            # of those models can be loaded.
            effective_updates = _ensure_h3_effective_models_current(
                raw_params,
                trusted_h3_plan,
                already_checked=(
                    {requested_model} if requested_model_checked else set()
                ),
            )
            for effective_model, update in effective_updates.items():
                component_download_required = any(
                    isinstance(value, dict)
                    and value.get("status") == "download_required"
                    for value in (update.get("components") or {}).values()
                )
                if update.get("status") == "download_required" or component_download_required:
                    update_job(
                        job,
                        message=(
                            "Downloading latest compatible "
                            f"{effective_model} checkpoint…"
                        ),
                    )

            # Register the exact state before any model work. SFX uses the
            # same queue but does not own the Wan model interrupt.
            abort_state = state["gen"]
            if not register_abort_state(
                job,
                job_id,
                _active_gen_states,
                abort_state,
                interrupt_model=(
                    None if raw_params.get("sfx_mode") else _interrupt_wan_model
                ),
            ):
                return False

            # Inject progressive pipeline setting from services config (applies to all paths)
            _services_cfg = wgp.server_config.get("services", {})
            # ── SFX mode: standalone MMAudio generation ──────────────────
            # When sfx_mode is set, bypass the normal video generation pipeline
            # and run MMAudio directly (with or without a source video).
            if raw_params.get("sfx_mode"):
                _run_sfx_generation(job, raw_params, start_time)
                return job.get("status") == "completed"

            # Temporal-depth control has its own optional 458 MB / 1.54 GB
            # preprocessor checkpoint. Provision it before wgp loads the much
            # larger generation model; otherwise a fresh install spends
            # minutes loading LTX and only then fails on the missing file.
            try:
                from services.managed_preprocessors import (
                    ensure_video_depth_checkpoint,
                    uses_temporal_depth,
                )

                if uses_temporal_depth(raw_params):
                    ensure_video_depth_checkpoint(
                        wgp.server_config.get(
                            "depth_anything_v2_variant", "vitl"
                        ),
                        progress=lambda msg: update_job(job, message=msg),
                    )
                    update_job(job, message="Preparing temporal-depth control…")
            except Exception as e:
                finish_job(job, "failed", error=str(e), message=str(e))
                return False

            # Ordinary H3 LoRAs may target either FL2VA or Ref2VA compact
            # AdaLN widths.  Provision the small revision-pinned affine maps
            # for every effective checkpoint before MMGP preprocesses a LoRA.
            try:
                if raw_params.get("activated_loras"):
                    h3_lora_flavors = set()
                    lora_model_types = set(effective_h3_models)
                    if requested_model:
                        lora_model_types.add(requested_model)
                    for effective_model in lora_model_types:
                        effective_def = wgp.get_model_def(effective_model) or {}
                        architecture = str(
                            effective_def.get("architecture") or effective_model
                        )
                        if not architecture.startswith("minimax_h3"):
                            continue
                        h3_lora_flavors.add(
                            "ref2va"
                            if (
                                effective_model == _H3_REF2VA_MODEL
                                or effective_def.get("minimax_h3_reference_mode")
                            )
                            else "fl2va"
                        )
                    if h3_lora_flavors:
                        from services.managed_preprocessors import (
                            ensure_minimax_h3_lora_affine_maps,
                        )

                        for flavor in sorted(h3_lora_flavors):
                            ensure_minimax_h3_lora_affine_maps(
                                flavor,
                                progress=lambda msg: update_job(job, message=msg),
                            )
                        update_job(job, message="Preparing MiniMax H3 LoRAs…")
            except Exception as e:
                finish_job(job, "failed", error=str(e), message=str(e))
                return False

            # Safety net for managed auto-download LoRAs (e.g. Edit Anything):
            # fetch the file when missing if the frontend's proactive download
            # hasn't finished yet, so the user doesn't hit a "file not found"
            # error. No-op (one dict lookup) for jobs without a managed LoRA.
            try:
                _ensure_managed_loras_present(
                    raw_params.get("activated_loras"),
                    raw_params.get("model_type"),
                    progress=lambda msg: update_job(job, message=msg),
                )
            except Exception as e:
                finish_job(job, "failed", error=str(e), message=str(e))
                return False

            # For video: extract film grain settings and apply as post-processing
            # after generation (avoids 3x slowdown from pipeline re-processing).
            # For images: leave film grain in params so the pipeline applies it inline
            # (single image is instant, no slowdown issue).
            gen_mode = raw_params.get("generation_mode", "video")
            if gen_mode != "image":
                pp_film_grain_intensity = raw_params.pop("film_grain_intensity", 0)
                pp_film_grain_saturation = raw_params.pop("film_grain_saturation", 0.5)
            else:
                pp_film_grain_intensity = 0
                pp_film_grain_saturation = 0.5

            # FlashVSR upscaling is deferred to a whole-file post-pass (below):
            # one continuous temporal pass over the assembled video instead of
            # per-sliding-window chunks — FlashVSR's temporal state no longer
            # resets at window boundaries (detail "pop" at seams), and it stops
            # competing with the diffusion model for VRAM between windows.
            # Lanczos/VAE methods keep the inline per-window path (cheap,
            # stateless), and images keep inline upsampling (single frame).
            pp_spatial_upsampling = ""
            pp_delivery_resolution = str(
                raw_params.pop("delivery_resolution", "") or ""
            ).lower()
            pp_delivery_fit = str(
                raw_params.pop("delivery_fit", "") or ""
            ).lower()
            if gen_mode != "image":
                _su_val = str(raw_params.get("spatial_upsampling") or "")
                if "flashvsr" in _su_val:
                    pp_spatial_upsampling = _su_val
                    raw_params.pop("spatial_upsampling", None)
            if pp_delivery_resolution and not pp_spatial_upsampling:
                finish_job(
                    job, "failed",
                    error="Exact delivery requires the configured FlashVSR upscale stage",
                    message="Delivery pipeline configuration is invalid",
                )
                return False
            h3_delivery_request = bool(
                pp_delivery_resolution
                and (
                    str(job.get("params", {}).get("model_type") or "")
                    in _H3_LONG_STUDIO_MODELS
                    or isinstance(
                        job.get("params", {}).get("_h3_longform"), dict,
                    )
                )
            )

            # Voice clone postprocessing (SeedVC) — replaces 1 or 2 voices
            # in the generated video's audio with user-supplied reference
            # voice(s). Driven by three params (set by the UI):
            #   voice_clone_enabled: bool
            #   voice_clone_refs:    list[str] of uploaded voice ref file paths
            #   voice_clone_mode:    "single" or "two"
            # Pop them out of raw_params so they don't leak into the
            # generation handler (other handlers don't understand them).
            pp_voice_clone_enabled = bool(raw_params.pop("voice_clone_enabled", False))
            pp_voice_clone_refs = raw_params.pop("voice_clone_refs", None) or []
            pp_voice_clone_mode = raw_params.pop("voice_clone_mode", "single")

            defer_output_publication = bool(
                raw_params.pop("_defer_output_publication", False)
            )
            recast_shot_manifest = raw_params.pop(
                "_recast_shot_manifest",
                None,
            )
            repaint_shot_manifest = raw_params.pop(
                "_repaint_shot_manifest",
                None,
            )
            outpaint_shot_manifest = raw_params.pop(
                "_outpaint_shot_manifest",
                None,
            )
            h3_longform = raw_params.pop("_h3_longform", None)
            if not isinstance(h3_longform, dict):
                h3_longform = None
            if recast_shot_manifest is not None:
                shot_manifest = recast_shot_manifest
                shot_workflow = "Recast"
            elif repaint_shot_manifest is not None:
                shot_manifest = repaint_shot_manifest
                shot_workflow = "Repaint"
            else:
                shot_manifest = outpaint_shot_manifest
                shot_workflow = "Outpaint"

            if outpaint_shot_manifest is not None:
                # Internal Outpaint shots must not run the continuous job's
                # postprocessor against the complete source video. The final
                # shot-aware worker restores one pristine audio track only
                # after all exact-length clips have been assembled.
                raw_params["_outpaint_preserve_audio"] = False
                raw_params["_outpaint_source_video"] = None
                raw_params["_outpaint_lock_source_pixels"] = False
                raw_params["_outpaint_trim_smear"] = False

            # Shot-aware edits supply exact per-shot guides and settings. They
            # run through the ordinary task engine but defer concatenation and
            # publication to their finishing worker.
            if shot_manifest is not None:
                import copy

                if not isinstance(shot_manifest, list):
                    finish_job(
                        job,
                        "failed",
                        error=f"{shot_workflow} shot manifest is invalid",
                        message=f"{shot_workflow} shot preparation failed",
                    )
                    return False
                generated_entries = [
                    entry
                    for entry in shot_manifest
                    if isinstance(entry, dict)
                    and isinstance(entry.get("params"), dict)
                ]
                if not generated_entries:
                    finish_job(
                        job,
                        "failed",
                        error=(
                            f"{shot_workflow} shot manifest contains no "
                            "generated shots"
                        ),
                        message=f"{shot_workflow} shot preparation failed",
                    )
                    return False

                manifest = []
                group_id = f"{shot_workflow.casefold()}_shots_{job_id}"
                for sequence_index, entry in enumerate(generated_entries):
                    wgp.task_id += 1
                    shot_params = copy.deepcopy(raw_params)
                    shot_params.update(copy.deepcopy(entry["params"]))
                    shot_params["multi_prompts_gen_type"] = 0
                    shot_params["multi_clip_info"] = {
                        "group_id": group_id,
                        "index": int(entry.get(
                            "shot_index",
                            sequence_index,
                        )),
                        "total": len(generated_entries),
                        "defer_concat": True,
                        "progress_label": "Shot",
                    }
                    manifest.append({
                        "id": wgp.task_id,
                        "params": shot_params,
                        "plugin_data": {},
                    })

            # Multi-clip mode: split single request into per-clip tasks
            elif raw_params.get("multi_prompts_gen_type") == 3:
                prompt_text = raw_params.get("prompt", "")
                planned_clip_prompts = raw_params.pop(
                    "per_clip_prompts", None,
                )
                # Use clip boundary separator if present (Director v2 with sliding window support),
                # otherwise fall back to newline split (Studio mode / legacy Director)
                if isinstance(planned_clip_prompts, list) and planned_clip_prompts:
                    prompt_lines = [
                        str(prompt) for prompt in planned_clip_prompts
                    ]
                elif _MULTI_CLIP_SEPARATOR in prompt_text:
                    prompt_lines = [p.strip() for p in prompt_text.split(_MULTI_CLIP_SEPARATOR) if p.strip()]
                else:
                    prompt_lines = [l.strip() for l in prompt_text.split("\n") if l.strip()]
                image_starts = raw_params.get("image_start", [])
                if not isinstance(image_starts, list):
                    image_starts = [image_starts] if image_starts else []
                image_ends = raw_params.get("image_end", [])
                if not isinstance(image_ends, list):
                    image_ends = [image_ends] if image_ends else []
                sw_size = raw_params.get("sliding_window_size", raw_params.get("video_length", 121))
                per_clip_frames = raw_params.pop("per_clip_frames", None)  # optional per-clip durations
                per_clip_keyframes = raw_params.pop("per_clip_keyframes", None)  # optional keyframe injection per clip
                multi_clip_audio_start_sec = raw_params.pop("multi_clip_audio_start_sec", 0.0)
                # Recovery identity is job/variant/segment based. A timestamp
                # here made the same restored H3 chain look like new work and
                # prevented exact segment/concat reconciliation.
                group_id = f"mc_{job_id}"
                clip_count = max(len(prompt_lines), len(image_starts), 1)

                # Get model latent_size for frame quantization — wgp.py quantizes
                # video_length to (n-1)//latent_size*latent_size+1, so we must match
                # that here to keep cumulative audio offsets in sync with actual output.
                _mc_model_type = raw_params.get("model_type", "")
                try:
                    _mc_model_def = wgp.get_model_def(_mc_model_type) or {}
                    _mc_min_f, _mc_fs, _mc_latent = wgp.get_model_min_frames_and_step(_mc_model_type)
                except Exception:
                    _mc_model_def = {}
                    _mc_min_f, _mc_fs, _mc_latent = 17, 8, 8
                if not _mc_model_def:
                    _mc_model_def = {
                        "frames_minimum": _mc_min_f,
                        "frames_steps": _mc_fs,
                        "latent_size": _mc_latent,
                    }

                manifest = []
                # Director timelines can begin after a silent intro. Preserve
                # that source-audio origin for every clip's conditioning; the
                # ordinary Studio path continues to default to frame zero.
                try:
                    cumulative_offset = max(
                        0, int(raw_params.get("audio_frame_offset", 0) or 0),
                    )
                    multi_clip_audio_start_sec = max(
                        0.0, float(multi_clip_audio_start_sec or 0),
                    )
                except (TypeError, ValueError):
                    cumulative_offset = 0
                    multi_clip_audio_start_sec = 0.0
                total_trimmed_frames = 0
                last_se_clip_end_image = None  # track last clip's end image for tail compensation
                for i in range(clip_count):
                    wgp.task_id += 1
                    clip_params = raw_params.copy()
                    clip_params["prompt"] = prompt_lines[i] if i < len(prompt_lines) else (prompt_lines[-1] if prompt_lines else "")
                    clip_params["image_start"] = image_starts[i] if i < len(image_starts) else None
                    clip_end = image_ends[i] if i < len(image_ends) else None
                    clip_params["image_end"] = clip_end if clip_end else None
                    segment_plan = {}
                    if h3_longform:
                        planned_models = h3_longform.get("segment_models") or []
                        if i < len(planned_models) and isinstance(planned_models[i], dict):
                            segment_plan = planned_models[i]
                    segment_model = str(
                        segment_plan.get("model_type")
                        or clip_params.get("model_type")
                        or ""
                    )
                    if segment_plan:
                        clip_params["model_type"] = segment_model
                        clip_params["_h3_conditioning_reason"] = str(
                            segment_plan.get("reason") or "adaptive conditioning"
                        )
                    native_h3_boundaries = bool(
                        h3_longform
                        and h3_longform.get("native_boundary_conditioning")
                    )
                    if native_h3_boundaries and segment_plan.get(
                        "drop_semantic_refs"
                    ):
                        # This is an explicit per-segment override. Keep global
                        # edge anchors, but remove every semantic-media channel
                        # before enforcing the native FL2VA contract.
                        clip_params.pop("image_refs", None)
                        for semantic_key in (
                            "video_guide", "video_guide2", "video_guide3",
                            "audio_guide", "audio_guide2", "audio_guide3",
                        ):
                            clip_params.pop(semantic_key, None)
                        clip_params["video_prompt_type"] = ""
                        clip_params["audio_prompt_type"] = ""
                    if segment_model == "minimax_h3_ref2va":
                        if native_h3_boundaries:
                            clip_params["image_start"] = (
                                h3_longform.get("original_image_start")
                                if i == 0 else None
                            )
                            clip_end = (
                                h3_longform.get("original_image_end")
                                if i == clip_count - 1 else None
                            )
                            clip_params["image_end"] = clip_end
                        else:
                            clip_params["image_start"] = None
                            clip_params["image_end"] = None
                            clip_params["image_prompt_type"] = ""
                        ref_custom = dict(clip_params.get("custom_settings") or {})
                        if not native_h3_boundaries:
                            ref_custom["h3_ref2va_chain_id"] = group_id
                        ref_custom["h3_native_boundary_conditioning"] = (
                            native_h3_boundaries
                        )
                        clip_params["custom_settings"] = ref_custom
                        if not native_h3_boundaries:
                            clip_end = None
                    elif segment_model in _H3_FL2VA_MODELS and h3_longform:
                        clip_params["image_start"] = (
                            h3_longform.get("original_image_start") if i == 0 else None
                        )
                        clip_end = (
                            h3_longform.get("original_image_end")
                            if i == clip_count - 1 else None
                        )
                        clip_params["image_end"] = clip_end
                        if native_h3_boundaries:
                            # The shared policy selects FL2VA only when no
                            # semantic inputs exist. Fail closed if a later
                            # mutation would otherwise make us drop them.
                            from services.h3_boundary_policy import (
                                has_semantic_references,
                            )
                            if has_semantic_references(clip_params):
                                raise ValueError(
                                    "Native H3 boundary planning cannot drop semantic references"
                                )
                            fl_custom = dict(clip_params.get("custom_settings") or {})
                            fl_custom["h3_native_boundary_conditioning"] = True
                            clip_params["custom_settings"] = fl_custom
                        else:
                            # Legacy adaptive routing carried continuity with
                            # a generated still and could not retain Ref2VA
                            # media on an FL2VA segment.
                            clip_params.pop("image_refs", None)
                            for semantic_key in (
                                "video_guide", "video_guide2", "video_guide3",
                                "audio_guide", "audio_guide2", "audio_guide3",
                            ):
                                clip_params.pop(semantic_key, None)
                            clip_params["video_prompt_type"] = ""
                            clip_params["audio_prompt_type"] = ""
                    # Set per-clip image_prompt_type based on which images are present
                    has_start = bool(clip_params.get("image_start"))
                    has_end = bool(clip_end)
                    if has_start and has_end:
                        clip_params["image_prompt_type"] = "SE"
                    elif has_start:
                        clip_params["image_prompt_type"] = "S"
                    elif has_end:
                        clip_params["image_prompt_type"] = "E"
                    else:
                        clip_params["image_prompt_type"] = ""
                    boundary = {"type": "continuous", "source": "model_grid"}
                    if h3_longform and i > 0:
                        planned_boundaries = h3_longform.get("clip_boundaries") or []
                        if i - 1 < len(planned_boundaries):
                            candidate_boundary = planned_boundaries[i - 1]
                            if isinstance(candidate_boundary, dict):
                                boundary = dict(candidate_boundary)
                    boundary_type = str(boundary.get("type") or "continuous")
                    # FL2VA receives a hard last-frame anchor only across a
                    # continuous join. Ref2VA always receives semantic history,
                    # while continuous joins additionally request a rolling
                    # temporal-tail reference prepared after the prior task.
                    if i > 0 and native_h3_boundaries:
                        if segment_plan.get("temporal_overlap"):
                            clip_params["_h3_native_boundary_request"] = {
                                "boundary_type": boundary_type,
                                "overlap_frames": int(
                                    segment_plan.get("overlap_frames") or 0
                                ),
                                "discard_frames": int(
                                    segment_plan.get("discard_frames") or 0
                                ),
                            }
                        elif segment_plan.get("predecessor_semantic_still"):
                            clip_params["_ref2va_continuation"] = boundary_type
                    elif not has_start and i > 0:
                        if segment_model == "minimax_h3_ref2va":
                            clip_params["_ref2va_continuation"] = boundary_type
                        elif boundary_type in {"continuous", "precut"}:
                            clip_params["_continuation"] = True
                    clip_frames = per_clip_frames[i] if per_clip_frames and i < len(per_clip_frames) else sw_size
                    # Use the model's authoritative temporal grid. In
                    # particular MiniMax H3 requires 17*n+5, not the generic
                    # latent-grid 17*n+1 formula previously used here.
                    clip_frames = wgp.align_model_frame_count(
                        clip_frames, _mc_model_def,
                    )
                    clip_frames = max(clip_frames, _mc_min_f)
                    # SE mode: mark tail frames for trimming (removes end-frame
                    # conditioning distortion at tensor level before saving)
                    trim_tail = 0
                    expected_published_frames = None
                    if h3_longform:
                        planned_tail_trims = h3_longform.get(
                            "clip_trim_tail_frames"
                        )
                        planned_published_frames = h3_longform.get(
                            "clip_published_frames"
                        )
                        if planned_tail_trims is None and planned_published_frames is None:
                            # Legacy committed plans stored one aggregate final
                            # trim. Replay that contract without replanning.
                            trim_tail = (
                                max(0, int(h3_longform.get("final_trim_frames") or 0))
                                if i == clip_count - 1 else 0
                            )
                        elif (
                            not isinstance(planned_tail_trims, list)
                            or not isinstance(planned_published_frames, list)
                            or len(planned_tail_trims) != clip_count
                            or len(planned_published_frames) != clip_count
                        ):
                            raise ValueError(
                                "H3 per-segment publication geometry is incomplete"
                            )
                        else:
                            trim_tail = max(0, int(planned_tail_trims[i] or 0))
                            expected_published_frames = int(
                                planned_published_frames[i]
                            )
                        if trim_tail >= clip_frames:
                            raise ValueError(
                                "H3 segment trim must leave at least one frame"
                            )
                        if (
                            expected_published_frames is not None
                            and expected_published_frames != clip_frames - trim_tail
                        ):
                            raise ValueError(
                                "H3 segment publication geometry does not match its model frames"
                            )
                    elif has_end:
                        trim_tail = _mc_fs
                        last_se_clip_end_image = clip_end
                    clip_params["video_length"] = clip_frames
                    clip_params["trim_tail_frames"] = trim_tail
                    # Ref2VA audio guides are semantic references, not one
                    # continuous soundtrack. Reuse them from frame zero on
                    # every native H3 segment; cumulative slicing would turn
                    # later segments into silence once the <=15s reference
                    # had been exhausted. Generated embedded audio is joined
                    # separately below.
                    semantic_h3_refs = bool(
                        h3_longform
                        and segment_model == "minimax_h3_ref2va"
                    )
                    clip_params["audio_frame_offset"] = (
                        0 if semantic_h3_refs else cumulative_offset
                    )
                    cumulative_offset += clip_frames - trim_tail  # advance by post-trim frames for audio sync
                    total_trimmed_frames += trim_tail
                    clip_params["multi_clip_info"] = {
                        "group_id": group_id,
                        "index": i,
                        "total": clip_count,
                        "cumulative_offset": True,
                        "audio_start_sec": multi_clip_audio_start_sec,
                        "generated_frames": clip_frames,
                        "published_frames": clip_frames - trim_tail,
                        "trim_tail_frames": trim_tail,
                        "boundary_from_previous": (
                            None if i == 0 else boundary_type
                        ),
                        "boundary_source": (
                            None if i == 0 else boundary.get("source")
                        ),
                    }
                    if h3_longform:
                        clip_params["multi_clip_info"].update({
                            "automatic_h3_longform": True,
                            "requested_frames": h3_longform.get(
                                "requested_frames",
                            ),
                            "planned_frames": h3_longform.get(
                                "planned_frames",
                            ),
                            "global_prompt": h3_longform.get(
                                "global_prompt", "",
                            ),
                            "preserve_generated_audio": bool(
                                h3_longform.get("preserve_generated_audio")
                            ),
                            "conditioning_model": segment_model,
                            "conditioning_reason": str(
                                segment_plan.get("reason") or ""
                            ),
                            "boundary_plan": (
                                None if i == 0 else boundary
                            ),
                            "native_boundary_conditioning": native_h3_boundaries,
                            "boundary_overlap_discard_frames": int(
                                segment_plan.get("discard_frames") or 0
                            ),
                        })
                    # Structured H3 local timelines must stay intact. Mode 0
                    # splits newline content into separate prompts; mode 2 is
                    # the WGP structured Studio prompt path.
                    clip_prompt = clip_params.get("prompt", "")
                    clip_params["multi_prompts_gen_type"] = (
                        2 if h3_longform else (1 if "\n" in clip_prompt else 0)
                    )
                    # Keyframe injection: add image_refs and frames_positions for this clip
                    if per_clip_keyframes and i < len(per_clip_keyframes) and per_clip_keyframes[i]:
                        kf_paths = list(per_clip_keyframes[i])
                        if h3_longform and segment_model == "minimax_h3_ref2va":
                            # H3 Ref2VA treats local keyframes as semantic
                            # references. Preserve the request's existing refs
                            # and enforce the checkpoint's combined limit.
                            clip_params["image_refs"] = _merge_h3_ref2va_keyframes(
                                clip_params.get("image_refs"), kf_paths,
                            )
                        elif h3_longform and native_h3_boundaries:
                            raise ValueError(
                                "Native H3 FL2VA segments cannot accept per-clip semantic keyframes; select Ref2VA-compatible semantic conditioning"
                            )
                        else:
                            clip_params["image_refs"] = kf_paths
                            # Position each keyframe at "L" (last frame of each window)
                            clip_params["frames_positions"] = " ".join(["L"] * len(kf_paths))
                            # Enable frames injection mode
                            existing_vpt = clip_params.get("video_prompt_type", "")
                            if "KFI" not in existing_vpt:
                                clip_params["video_prompt_type"] = existing_vpt + "KFI"
                    manifest.append({
                        "id": wgp.task_id,
                        "params": clip_params,
                        "plugin_data": {},
                    })

                # Compensation tail clip: if SE trimming removed frames, generate a
                # short extra clip (start-frame only, no SE distortion) to fill the gap
                # so the final video matches the full audio duration.
                if total_trimmed_frames > 0 and not h3_longform:
                    # Snap to valid frame count for the model
                    model_type = raw_params.get("model_type", "")
                    try:
                        min_f, fs, _ = wgp.get_model_min_frames_and_step(model_type)
                    except Exception:
                        min_f, fs = 9, 8  # LTX-2 defaults
                    # Round up to nearest valid frame count (must be >= min_frames)
                    tail_frames = max(min_f, ((total_trimmed_frames - 1) // fs) * fs + 1)
                    if tail_frames < min_f:
                        tail_frames = min_f

                    wgp.task_id += 1
                    tail_params = raw_params.copy()
                    # Use last clip's prompt and last clip's end image as start frame
                    tail_params["prompt"] = prompt_lines[-1] if prompt_lines else ""
                    tail_params["image_start"] = last_se_clip_end_image
                    tail_params["image_end"] = None
                    tail_params["image_prompt_type"] = "S"  # start-only, no SE distortion
                    tail_params["video_length"] = tail_frames
                    tail_params["trim_tail_frames"] = 0
                    tail_params["audio_frame_offset"] = cumulative_offset
                    tail_params["multi_clip_info"] = {
                        "group_id": group_id,
                        "index": clip_count,
                        "total": clip_count + 1,
                        "cumulative_offset": True,
                        "audio_start_sec": multi_clip_audio_start_sec,
                        "published_frames": tail_frames,
                    }
                    tail_params["multi_prompts_gen_type"] = 0

                    # Update all previous clips' total count to include the tail
                    for m in manifest:
                        m["params"]["multi_clip_info"]["total"] = clip_count + 1

                    manifest.append({
                        "id": wgp.task_id,
                        "params": tail_params,
                        "plugin_data": {},
                    })
                    print(f"[Multi-Clip] SE trim compensation: lost {total_trimmed_frames} frames across {clip_count} clips, adding tail clip of {tail_frames} frames")

                if h3_longform:
                    # WGP's repeat loop lives inside each task.  Leaving a
                    # repeat count on every segment would run A1,A2,B1,B2...
                    # and overwrite group slots, while FL2VA B1 would inherit
                    # A2's frame.  Expand complete variant-major chains
                    # (A1,B1,... then A2,B2,...) with one repeat per task and
                    # a distinct concat group for every requested output.
                    try:
                        output_count = max(
                            1, int(raw_params.get("repeat_generation") or 1),
                        )
                    except (TypeError, ValueError):
                        output_count = 1
                    try:
                        base_seed = int(raw_params.get("seed", -1))
                    except (TypeError, ValueError):
                        base_seed = -1

                    def allocate_h3_task_id():
                        # Keep WGP's global task identity contract while the
                        # pure expander remains directly regression-testable.
                        wgp.task_id += 1
                        return wgp.task_id

                    manifest = _expand_h3_longform_outputs(
                        manifest,
                        group_id=group_id,
                        output_count=output_count,
                        base_seed=base_seed,
                        allocate_task_id=allocate_h3_task_id,
                    )
            else:
                wgp.task_id += 1
                # SE trim: if end image is set, mark tail frames for trimming
                # (removes distorted frames from end-frame conditioning)
                has_end_image = raw_params.get("image_end") not in (None, "", [])
                if has_end_image and raw_params.get("video_length"):
                    model_type = raw_params.get("model_type", "")
                    try:
                        _, fs, _ = wgp.get_model_min_frames_and_step(model_type)
                    except Exception:
                        fs = 8  # LTX-2 default
                    raw_params["trim_tail_frames"] = fs

                manifest = [{
                    "id": wgp.task_id,
                    "params": raw_params,
                    "plugin_data": {},
                }]

            # WanGP's manifest parser materializes authorized image/video
            # paths into PIL/tensor objects. Freeze the producer metadata
            # before that boundary so later sidecar publication never tries
            # to serialize runtime-only media objects.
            h3_task_sidecar_params: dict[str, dict] = {}
            for manifest_task in manifest:
                manifest_params = (
                    manifest_task.get("params")
                    if isinstance(manifest_task, dict) else None
                )
                manifest_info = (
                    manifest_params.get("multi_clip_info")
                    if isinstance(manifest_params, dict) else None
                )
                if (
                    isinstance(manifest_info, dict)
                    and manifest_info.get("automatic_h3_longform")
                ):
                    h3_task_sidecar_params[str(manifest_task.get("id"))] = (
                        _snapshot_h3_recovery_task_params(
                            manifest_params, manifest_info,
                        )
                    )

            queue, error = wgp._parse_task_manifest(manifest, state, os.getcwd())

            if error:
                finish_job(
                    job, "failed", error=error,
                    message=f"Validation error: {error}",
                )
                return False

            if not queue:
                finish_job(
                    job, "failed", error="Task validation failed",
                    message="Task validation failed",
                )
                return False

            state["gen"]["queue"] = queue

            # Track existing outputs to detect new files
            # Use workspace captured at submission time, not current global save_path
            out_dir = job.get("out_dir") or wgp.save_path
            # Point wgp.save_path to this job's target directory.
            # No save/restore — the workspace switch endpoint is the sole
            # controller of wgp.save_path outside of generation.
            wgp.save_path = out_dir
            wgp.image_save_path = out_dir
            wgp.audio_save_path = out_dir
            print(f"[Gen {job_id}] save_path locked to: {out_dir}")
            before = set()
            if os.path.isdir(out_dir):
                before = set(os.listdir(out_dir))

            # Process tasks with live progress (inline from process_tasks_cli)
            gen = wgp.get_gen_info(state)
            total_tasks = len(queue)
            completed = 0
            skipped = 0
            cancelled = False
            first_task_error = None
            first_failure_details = None
            clip_output_files: dict[int, str] = {}
            join_output_file = None
            producer_artifact_roles: dict[str, str] = {}

            def _record_eta_inactive_time(inactive_started: float) -> None:
                """Exclude scheduler holds from live runtime ETA samples."""
                inactive_seconds = max(0.0, time.time() - inactive_started)
                try:
                    previous_inactive = float(
                        job.get("_eta_inactive_seconds") or 0.0
                    )
                except (TypeError, ValueError):
                    previous_inactive = 0.0
                job["_eta_inactive_seconds"] = (
                    previous_inactive + inactive_seconds
                )

            def _write_output_sidecars(
                file_names, *, native_source=False, recovery_units=None,
                media_paths=None, task_params=None,
            ):
                """Stamp every produced media file, including abort leftovers.

                Director only exposes the final sliding-window file for each
                clip, but pipeline deletion also needs ownership metadata on
                superseded window saves.  Write these sidecars as soon as the
                files are discovered so a later cancellation cannot strand
                unowned intermediates.
                """
                if not file_names:
                    return
                source_params = (
                    task_params
                    if isinstance(task_params, dict)
                    else job["params"]
                )
                upload_filenames = {}
                for key in [
                    "image_start", "image_end", "video_guide", "video_guide2",
                    "video_guide3", "audio_guide",
                    "audio_guide2", "audio_guide3", "audio_guide4",
                    "audio_guide5", "audio_guide6",
                ]:
                    val = source_params.get(key)
                    if val and isinstance(val, str):
                        upload_filenames[key] = os.path.basename(val)
                    elif val and isinstance(val, list):
                        upload_filenames[key] = [
                            os.path.basename(v)
                            if isinstance(v, str) and v else ""
                            for v in val
                        ]
                sidecar_params = source_params.copy()
                # Native boundary descriptors are private, retry-scoped
                # recovery inputs. Persist only the separately sealed producer
                # continuation evidence, never staging paths or stale requests.
                sidecar_params.pop("_h3_native_boundary", None)
                sidecar_params.pop("_h3_native_boundary_request", None)
                # These settings are stripped before generation and applied
                # afterward, so retain them for pencil-restore metadata.
                if pp_film_grain_intensity > 0:
                    sidecar_params["film_grain_intensity"] = (
                        pp_film_grain_intensity
                    )
                    sidecar_params["film_grain_saturation"] = (
                        pp_film_grain_saturation
                    )
                if pp_spatial_upsampling:
                    sidecar_params["spatial_upsampling"] = (
                        pp_spatial_upsampling
                    )
                if pp_delivery_resolution:
                    sidecar_params["delivery_resolution"] = pp_delivery_resolution
                    sidecar_params["delivery_fit"] = pp_delivery_fit
                sidecar = {
                    "params": sidecar_params,
                    "upload_filenames": upload_filenames,
                    "generation_mode": source_params.get("generation_mode"),
                    "job_id": job_id,
                    "generation_time": round(time.time() - start_time),
                    "created_at": time.time(),
                }
                sidecar_policy = dict(job.get("access_policy") or {})
                if native_source:
                    sidecar_policy.update({
                        "private": True,
                        "owner_session_id": job.get("session_id"),
                    })
                stamp_sidecar_policy(
                    sidecar,
                    sidecar_policy,
                    workspace=job.get("workspace") or "default",
                )
                dpid = job["params"].get("_director_pipeline_id")
                if dpid:
                    sidecar["director_pipeline_id"] = dpid
                clip_index_by_filename = {
                    filename: index
                    for index, filename in clip_output_files.items()
                }
                for fname in file_names:
                    ext = os.path.splitext(fname)[1].lower()
                    if ext not in GENERATED_MEDIA_EXTENSIONS:
                        continue
                    file_sidecar = dict(sidecar)
                    file_sidecar["params"] = sidecar_params.copy()
                    resolved_seed = _extract_output_seed(fname)
                    if resolved_seed is not None:
                        # A request seed of -1 means "choose randomly".  The
                        # filename carries the seed that was actually used;
                        # store it so Load Settings reproduces a good result,
                        # including after ffmpeg post-processing.
                        file_sidecar["params"]["seed"] = resolved_seed
                    if fname in clip_index_by_filename:
                        file_sidecar["director_clip_index"] = (
                            clip_index_by_filename[fname]
                        )
                    else:
                        file_sidecar.pop("director_clip_index", None)
                    file_sidecar["output_filename"] = fname
                    producer_role = producer_artifact_roles.get(fname)
                    if producer_role:
                        # This role comes from the task's registered output
                        # order, not from a filename or file-size heuristic.
                        file_sidecar["producer_artifact_class"] = producer_role
                        file_sidecar["artifact_class"] = (
                            "temporary" if native_source else producer_role
                        )
                    if native_source:
                        file_sidecar["delivery_native_source"] = True
                    meta_path = os.path.join(
                        out_dir, os.path.splitext(fname)[0] + ".meta.json",
                    )
                    media_path = (
                        media_paths.get(fname)
                        if isinstance(media_paths, dict)
                        else None
                    ) or os.path.join(out_dir, fname)
                    if not os.path.isfile(media_path):
                        continue
                    recovery_unit = (
                        recovery_units.get(fname)
                        if isinstance(recovery_units, dict)
                        else None
                    )
                    if isinstance(recovery_unit, dict):
                        unit_kind = str(recovery_unit.get("kind") or "")
                        expected_role = _queue_recovery_expected_artifact_role(
                            unit_kind, file_sidecar,
                        )
                        if expected_role is None:
                            raise QueueRecoveryRuntimeError(
                                "Recovery artifact role is not declared."
                            )
                        file_sidecar["producer_artifact_class"] = expected_role
                        file_sidecar["artifact_class"] = (
                            "temporary" if native_source else expected_role
                        )
                        unit_variant = max(
                            0, int(recovery_unit.get("variant", 0) or 0),
                        )
                        if unit_kind in {"h3_segment", "h3_concat"}:
                            variant_lineage = (
                                f"h3:{job_id}:variant:{unit_variant}"
                            )
                            file_sidecar["artifact_lineage"] = variant_lineage
                            file_sidecar[
                                "producer_variant_lineage"
                            ] = variant_lineage
                        media_size, media_sha256 = _recovery_sha256_file(media_path)
                        file_sidecar.update({
                            "producer_unit_artifact_names": sorted({
                                str(name) for name in file_names
                                if isinstance(name, str)
                                and os.path.basename(name) == name
                            }),
                            "producer_unit_id": str(
                                recovery_unit.get("unit_id") or ""
                            ),
                            "producer_unit_kind": unit_kind,
                            "producer_unit_variant": unit_variant,
                            "producer_unit_index": max(
                                0, int(recovery_unit.get("index", 0) or 0),
                            ),
                            "producer_media_sha256": media_sha256,
                            "producer_media_size": media_size,
                        })
                        dependencies = recovery_unit.get("dependencies")
                        if isinstance(dependencies, list):
                            file_sidecar["producer_unit_dependencies"] = list(
                                dependencies
                            )
                        settings = recovery_unit.get("settings")
                        if isinstance(settings, dict):
                            file_sidecar["producer_unit_settings"] = dict(settings)
                        continuation = recovery_unit.get("continuation")
                        if isinstance(continuation, dict):
                            file_sidecar["producer_unit_continuation"] = dict(
                                continuation
                            )
                    elif os.path.isfile(meta_path):
                        # Later artifact-role refreshes must retain the sealed
                        # exactly-once producer evidence written at the safe
                        # unit boundary.
                        try:
                            with open(meta_path, "r", encoding="utf-8") as existing_file:
                                existing_meta = json.load(existing_file)
                            if isinstance(existing_meta, dict):
                                for key, value in existing_meta.items():
                                    if key.startswith("producer_") or key == "artifact_lineage":
                                        file_sidecar[key] = value
                                existing_params = existing_meta.get("params")
                                if (
                                    isinstance(existing_params, dict)
                                    and existing_meta.get("producer_unit_id")
                                ):
                                    file_sidecar["params"] = dict(existing_params)
                                preserved_role = existing_meta.get(
                                    "producer_artifact_class"
                                )
                                if preserved_role in _RECOVERY_ARTIFACT_ROLES:
                                    file_sidecar["artifact_class"] = (
                                        "temporary"
                                        if native_source
                                        else preserved_role
                                    )
                        except (OSError, ValueError, TypeError):
                            pass
                    temp_meta = f"{meta_path}.{uuid.uuid4().hex[:8]}.tmp"
                    try:
                        with open(temp_meta, "w", encoding="utf-8") as f:
                            json.dump(file_sidecar, f, indent=2)
                            f.flush()
                            os.fsync(f.fileno())
                        os.replace(temp_meta, meta_path)
                        if os.name != "nt":
                            directory = os.open(
                                out_dir,
                                os.O_RDONLY | getattr(os, "O_DIRECTORY", 0),
                            )
                            try:
                                os.fsync(directory)
                            finally:
                                os.close(directory)
                    except Exception as sidecar_error:
                        try:
                            os.remove(temp_meta)
                        except OSError:
                            pass
                        quarantine = os.path.join(
                            out_dir,
                            f".private-sidecar-failed-{uuid.uuid4().hex[:8]}-{fname}",
                        )
                        try:
                            os.replace(media_path, quarantine)
                        except OSError:
                            try:
                                os.remove(media_path)
                            except OSError:
                                pass
                        unit_kind = (
                            str(recovery_unit.get("kind") or "")
                            if isinstance(recovery_unit, dict) else ""
                        )
                        raise _GenerationStageFailure(
                            "Failed to publish protected output metadata",
                            stage=(
                                "segment_checkpoint"
                                if unit_kind == "h3_segment"
                                else "publication"
                            ),
                            code=(
                                "segment_checkpoint_failed"
                                if unit_kind == "h3_segment"
                                else "publication_failed"
                            ),
                        ) from sidecar_error

                # Persist the producer's current artifact view after every
                # publication pass. Later sliding-window saves reclassify the
                # prior cumulative final as a window, and the final pass leaves
                # one authoritative class on every sidecar. Cleanup trusts this
                # explicit metadata (plus conservative structural legacy data),
                # never a filename hint by itself.
                try:
                    if media_paths:
                        return
                    from services.search_index import load_media_sidecars as _load_sidecars
                    job_sidecars = {
                        name: meta
                        for name, meta in _load_sidecars(out_dir).items()
                        if meta.get("job_id") == job_id
                    }
                    for name, meta in job_sidecars.items():
                        # The gallery classifier intentionally uses filename
                        # hints for display of legacy leftovers. Those hints
                        # are not producer authority and must never be copied
                        # into a sidecar that cleanup later trusts.
                        meta.pop("artifact_class", None)
                        params = (
                            meta.get("params")
                            if isinstance(meta.get("params"), dict)
                            else {}
                        )
                        multi_clip = params.get("multi_clip_info")
                        structurally_component = (
                            isinstance(multi_clip, dict)
                            or meta.get("director_clip_index") is not None
                        )
                        producer_kind = str(meta.get("producer_unit_kind") or "")
                        producer_role = _queue_recovery_expected_artifact_role(
                            producer_kind, meta,
                        )
                        if producer_role in _RECOVERY_ARTIFACT_ROLES:
                            meta["artifact_class"] = producer_role
                        elif producer_kind:
                            # Modern but incomplete evidence never becomes a
                            # Final through fallback or filename resemblance.
                            meta["artifact_class"] = "component"
                        elif structurally_component:
                            meta["artifact_class"] = "component"
                        elif meta.get("producer_temporary") is True:
                            meta["artifact_class"] = "temporary"
                        else:
                            meta["artifact_class"] = "final"
                        meta_path = os.path.join(
                            out_dir, os.path.splitext(name)[0] + ".meta.json",
                        )
                        with open(meta_path, "w", encoding="utf-8") as handle:
                            json.dump(meta, handle, indent=2)
                except Exception as artifact_error:
                    print(f"[Gen {job_id}] Artifact metadata refresh skipped: {artifact_error}")

            def _replay_h3_concat_from_verified_segments(
                *, variant: int, total_segments: int, clip_info: dict,
            ) -> dict:
                """Rerun concat only; no denoising path is reachable here."""
                component_names = []
                component_hashes = []
                dependencies = []
                clip_start_frames = []
                clip_tail_frames = []
                for segment_index in range(total_segments):
                    unit = _queue_recovery_unit_matches(
                        job,
                        kind="h3_segment",
                        variant=variant,
                        index=segment_index,
                        project_dir=out_dir,
                    )
                    if unit is None:
                        raise QueueRecoveryRuntimeError(
                            "H3 concat recovery is missing a verified segment."
                        )
                    dependencies.append(str(unit.get("unit_id") or ""))
                    video_artifacts = [
                        artifact
                        for artifact in unit.get("artifacts") or []
                        if isinstance(artifact, dict)
                        and os.path.splitext(str(artifact.get("basename") or ""))[1].lower()
                        in {".mp4", ".webm", ".mkv", ".mov"}
                    ]
                    if not video_artifacts:
                        raise QueueRecoveryRuntimeError(
                            "H3 concat recovery segment has no verified video."
                        )
                    component = video_artifacts[-1]
                    component_names.append(component["basename"])
                    component_hashes.append(component["sha256"])
                    unit_settings = unit.get("settings")
                    if (
                        not isinstance(unit_settings, dict)
                        or "discard_prefix_frames" not in unit_settings
                    ):
                        raise QueueRecoveryRuntimeError(
                            "H3 concat recovery is missing attested segment trim metadata."
                        )
                    try:
                        discard = max(
                            0, int(unit_settings["discard_prefix_frames"]),
                        )
                    except (TypeError, ValueError):
                        raise QueueRecoveryRuntimeError(
                            "H3 concat recovery segment trim is invalid."
                        ) from None
                    if discard not in {0, 17}:
                        raise QueueRecoveryRuntimeError(
                            "H3 concat recovery segment trim is unsupported."
                        )
                    clip_start_frames.append(discard)
                    try:
                        clip_tail_frames.append(max(
                            0, int(unit_settings.get("trim_tail_frames", 0) or 0),
                        ))
                    except (TypeError, ValueError):
                        raise QueueRecoveryRuntimeError(
                            "H3 concat recovery segment tail trim is invalid."
                        ) from None
                settings = {
                    "audio_start_ms": int(
                        1000 * float(clip_info.get("audio_start_sec", 0) or 0)
                    ),
                    "component_hashes": component_hashes,
                    "clip_start_frames": clip_start_frames,
                    "clip_tail_frames": clip_tail_frames,
                    "preserve_generated_audio": bool(
                        clip_info.get("preserve_generated_audio")
                    ),
                }
                unit_id = recovery_unit_id(
                    job_id,
                    "h3_concat",
                    variant=variant,
                    dependencies=dependencies,
                    settings=settings,
                )
                extension = os.path.splitext(component_names[-1])[1] or ".mp4"
                output_name = f"recovered_{job_id}_v{variant + 1}_multiclip{extension}"
                preserve_audio = bool(clip_info.get("preserve_generated_audio"))
                concat_audio = (
                    raw_params.get("audio_source")
                    if preserve_audio
                    else (
                        raw_params.get("audio_guide")
                        or raw_params.get("audio_source")
                    )
                )

                def concatenate(component_paths, staging_path):
                    return wgp.concatenate_multi_clip_videos(
                        component_paths,
                        staging_path,
                        concat_audio,
                        audio_start_sec=clip_info.get("audio_start_sec", 0),
                        clip_start_frames=clip_start_frames,
                        abort_callback=lambda: is_cancel_requested(job),
                    )

                replay_concat_to_stable_output(
                    out_dir,
                    component_basenames=component_names,
                    output_basename=output_name,
                    concatenate=concatenate,
                )
                producer_artifact_roles[output_name] = "final"
                _write_output_sidecars(
                    [output_name],
                    native_source=h3_delivery_request,
                    recovery_units={
                        output_name: {
                            "dependencies": list(dependencies),
                            "index": 0,
                            "kind": "h3_concat",
                            "settings": dict(settings),
                            "unit_id": unit_id,
                            "variant": variant,
                        },
                    },
                    task_params={
                        **raw_params,
                        "multi_clip_info": dict(clip_info),
                    },
                )
                unit = _queue_recovery_checkpoint_unit(
                    job,
                    kind="h3_concat",
                    variant=variant,
                    index=0,
                    project_dir=out_dir,
                    artifact_names=[output_name],
                    dependencies=dependencies,
                    settings=settings,
                )
                path = os.path.join(out_dir, output_name)
                if path not in gen["file_list"]:
                    gen["file_list"].append(path)
                return unit

            def _h3_verified_segment_dependency_evidence(
                variant: int, segment_index: int,
            ) -> tuple[list[str], dict]:
                if segment_index <= 0:
                    return [], {}
                predecessor = _queue_recovery_unit_matches(
                    job,
                    kind="h3_segment",
                    variant=variant,
                    index=segment_index - 1,
                    project_dir=out_dir,
                )
                if predecessor is None or not predecessor.get("unit_id"):
                    raise QueueRecoveryRuntimeError(
                        "H3 segment predecessor is not durably checkpointed."
                    )
                artifact_hashes = sorted(
                    str(artifact.get("sha256") or "")
                    for artifact in predecessor.get("artifacts") or []
                    if isinstance(artifact, dict) and artifact.get("sha256")
                )
                if not artifact_hashes:
                    raise QueueRecoveryRuntimeError(
                        "H3 segment predecessor has no attested artifact hash."
                    )
                evidence = {"predecessor_artifact_hashes": artifact_hashes}
                continuation = predecessor.get("continuation")
                if isinstance(continuation, dict) and continuation.get("sha256"):
                    evidence["predecessor_continuation_sha256"] = str(
                        continuation["sha256"]
                    )
                return [str(predecessor["unit_id"])], evidence

            is_multiclip = total_tasks > 1 and any(t.get('params', {}).get('multi_clip_info') for t in queue)
            automatic_h3_longform = any(
                isinstance((task.get("params") or {}).get("multi_clip_info"), dict)
                and (task.get("params") or {})["multi_clip_info"].get(
                    "automatic_h3_longform"
                )
                for task in queue
            )

            for task_idx, task in enumerate(queue):
                if is_cancel_requested(job):
                    cancelled = True
                    break
                task_no = task_idx + 1
                # Per-segment ETA starts only when a producer provides a real
                # timing boundary. H3 supplies that boundary immediately
                # before its deliberately expensive first denoising step.
                job["_eta_subtask_started_at"] = 0
                job["_eta_subtask_baseline_step"] = 0
                job["_eta_subtask_inactive_at_start"] = float(
                    job.get("_eta_inactive_seconds") or 0
                )
                job["_eta_subtask_window_current"] = 0
                task_file_start = len(gen.get("file_list") or [])
                task_artifact_start = len(gen.get("artifact_list") or [])
                prompt_preview = (task.get('prompt', '') or '')[:60]
                print(f"\n[Task {task_no}/{total_tasks}] {prompt_preview}...")
                if is_multiclip:
                    progress_info = (
                        (task.get("params") or {}).get("multi_clip_info")
                        or {}
                    )
                    progress_label = str(
                        progress_info.get("progress_label") or "Clip"
                    )
                    if not update_job(
                        job,
                        message=f"{progress_label} {task_no}/{total_tasks}",
                        phase=f"{progress_label} {task_no}/{total_tasks}",
                        clip_current=task_no,
                        clip_total=total_tasks,
                        clip_progress=0,
                        window_current=task_no,
                        window_total=total_tasks,
                        window_step=0,
                        window_total_steps=0,
                        window_progress=0,
                        overall_progress=int(100 * task_idx / total_tasks),
                        progress_indeterminate=True,
                        model_type=str(
                            (task.get("params") or {}).get("model_type") or ""
                        ),
                        current_segment_model=str(
                            progress_info.get("conditioning_model") or ""
                        ),
                        current_segment_reason=str(
                            progress_info.get("conditioning_reason") or ""
                        ),
                        current_segment_boundary=progress_info.get("boundary_plan"),
                    ):
                        cancelled = True
                        break

                task_params = task.get("params")
                if not isinstance(task_params, dict):
                    task_params = {}
                    task["params"] = task_params
                recovery_clip_info = task_params.get("multi_clip_info")
                task_sidecar_params = h3_task_sidecar_params.get(
                    str(task.get("id")), task_params,
                )
                if (
                    isinstance(recovery_clip_info, dict)
                    and recovery_clip_info.get("automatic_h3_longform")
                ):
                    try:
                        recovery_variant = max(
                            0, int(recovery_clip_info.get("output_index", 0) or 0),
                        )
                        recovery_segment = max(
                            0, int(recovery_clip_info.get("index", 0) or 0),
                        )
                        recovery_total = max(
                            1, int(recovery_clip_info.get("total", 1) or 1),
                        )
                    except (TypeError, ValueError):
                        raise RuntimeError("Recovered H3 segment position is invalid")
                    recovered_segment = _queue_recovery_unit_matches(
                        job,
                        kind="h3_segment",
                        variant=recovery_variant,
                        index=recovery_segment,
                        project_dir=out_dir,
                    )
                    recovered_concat = (
                        _queue_recovery_unit_matches(
                            job,
                            kind="h3_concat",
                            variant=recovery_variant,
                            index=0,
                            project_dir=out_dir,
                        )
                        if recovery_segment + 1 == recovery_total else None
                    )
                    if (
                        recovered_segment is not None
                        and recovery_segment + 1 == recovery_total
                        and recovered_concat is None
                    ):
                        recovered_concat = _replay_h3_concat_from_verified_segments(
                            variant=recovery_variant,
                            total_segments=recovery_total,
                            clip_info=recovery_clip_info,
                        )
                    # Concat recovery above is deliberately standalone: a
                    # completed final native segment never re-enters denoising.
                    may_skip_segment = recovered_segment is not None and (
                        recovery_segment + 1 < recovery_total
                        or recovered_concat is not None
                    )
                    if may_skip_segment:
                        recovered_paths = []
                        for artifact in recovered_segment.get("artifacts") or []:
                            path = os.path.join(out_dir, artifact["basename"])
                            recovered_paths.append(path)
                            if path not in gen["file_list"]:
                                gen["file_list"].append(path)
                        video_path = next((
                            path for path in reversed(recovered_paths)
                            if os.path.splitext(path)[1].lower()
                            in {".mp4", ".webm", ".mkv", ".mov"}
                        ), None)
                        if not video_path:
                            raise RuntimeError("Recovered H3 segment has no video")
                        group_id = str(recovery_clip_info.get("group_id") or "")
                        group = gen.setdefault("multi_clip_paths", {}).setdefault(
                            group_id, {},
                        )
                        group[recovery_segment] = {
                            "path": video_path,
                            "prompt": task_params.get("prompt", ""),
                            "image_start": task_params.get("image_start") or "",
                            "discard_prefix_frames": int(
                                recovery_clip_info.get(
                                    "boundary_overlap_discard_frames", 0,
                                ) or 0
                            ),
                            "published_frames": int(
                                recovery_clip_info.get("published_frames")
                                or task_params.get("video_length") or 0
                            ),
                        }
                        if task_idx + 1 < total_tasks:
                            next_info = (
                                (queue[task_idx + 1].get("params") or {}).get(
                                    "multi_clip_info"
                                ) or {}
                            )
                            if str(next_info.get("group_id") or "") == group_id:
                                _apply_h3_recovered_continuation(
                                    recovered_segment,
                                    queue[task_idx + 1],
                                    out_dir,
                                )
                        if recovered_concat is not None:
                            for artifact in recovered_concat.get("artifacts") or []:
                                path = os.path.join(out_dir, artifact["basename"])
                                if path not in gen["file_list"]:
                                    gen["file_list"].append(path)
                                producer_artifact_roles[artifact["basename"]] = "final"
                                if join_output_file is None:
                                    join_output_file = artifact["basename"]
                        completed += 1
                        print(f"\n  Task {task_no} recovered from verified output")
                        continue
                validation_reference_restoration = None
                if server_h3_turbo_validation_authorized:
                    validation_reference_restoration = (
                        _materialize_h3_turbo_validation_reference(
                            validation_reference_bytes,
                            task_params,
                        )
                    )
                try:
                    validated_params = wgp.validate_task(
                        task,
                        state,
                        _h3_turbo_validation_authorized=(
                            server_h3_turbo_validation_authorized
                        ),
                    )
                finally:
                    # Validation uses the captured, content-pinned bytes so
                    # the originally uploaded pathname cannot be swapped
                    # after admission. Restore the serializable authorized
                    # path immediately after WanGP has copied the PIL image.
                    if validation_reference_restoration is not None:
                        _restore_h3_turbo_validation_reference(
                            task_params,
                            validation_reference_restoration,
                        )
                if validated_params is None:
                    print(f"  [SKIP] Task {task_no} failed validation")
                    skipped += 1
                    continue

                gen["prompt_no"] = task_no
                gen["prompts_max"] = total_tasks

                params = validated_params.copy()
                recovery_clip = params.get("multi_clip_info")
                recovery_h3_segment = bool(
                    isinstance(recovery_clip, dict)
                    and recovery_clip.get("automatic_h3_longform")
                )
                recovery_native_output = bool(
                    job.get("_recovery_manifest_pointer")
                    and (
                        recovery_h3_segment
                        or (not is_multiclip and not defer_output_publication)
                    )
                )
                recovery_staging_dir = None
                if recovery_native_output:
                    recovery_staging_dir = ensure_recovery_staging_directory(
                        out_dir
                    )
                    params["_recovery_output_directory"] = recovery_staging_dir
                    params["_recovery_output_prefix"] = (
                        f"unit-{job_id}-t{task_idx}"
                    )
                task_h3_turbo_validation_authorized = (
                    params.pop("_h3_turbo_validation_authorized", False)
                    is True
                )
                params['state'] = state

                # WGP splits API repeats into complete one-output model calls.
                # At each returned boundary, publish its registered finals and
                # full artifact lineage before a requested scheduler hold can
                # block this worker. H3 segment groups retain their existing
                # task-boundary yield below, and deferred Director/tool workers
                # retain their all-at-once publication contract.
                repeat_file_cursor = len(gen.get("file_list") or [])
                repeat_audio_cursor = len(gen.get("audio_file_list") or [])
                repeat_published_artifacts = set(collect_job_outputs(
                    gen,
                    out_dir,
                    before,
                    allow_legacy_fallback=False,
                ))
                repeat_final_files: set[str] = set()

                def _publish_and_yield_after_repeat_output():
                    nonlocal repeat_file_cursor, repeat_audio_cursor
                    try:
                        completed_repeats = max(
                            0, int(gen.get("repeat_no") or 0),
                        )
                    except (TypeError, ValueError):
                        completed_repeats = 0
                    staged_media = _queue_recovery_staged_media_paths(
                        list(gen.get("artifact_list") or [])
                        + list(gen.get("file_list") or [])
                        + list(gen.get("audio_file_list") or []),
                        recovery_staging_dir,
                    )
                    current_artifacts = (
                        list(staged_media)
                        if recovery_staging_dir else collect_job_outputs(
                            gen,
                            out_dir,
                            before,
                            allow_legacy_fallback=False,
                        )
                    )
                    new_artifacts = [
                        filename for filename in current_artifacts
                        if filename not in repeat_published_artifacts
                    ]

                    registered_files = list(gen.get("file_list") or [])
                    registered_audio = list(gen.get("audio_file_list") or [])
                    repeat_files = registered_files[repeat_file_cursor:]
                    repeat_audio = registered_audio[repeat_audio_cursor:]
                    repeat_file_cursor = len(registered_files)
                    repeat_audio_cursor = len(registered_audio)

                    final_paths = repeat_files + repeat_audio
                    if gen.get("sliding_window") and repeat_files:
                        try:
                            repeat_batch_size = max(
                                1, int(params.get("batch_size") or 1),
                            )
                        except (TypeError, ValueError):
                            repeat_batch_size = 1
                        final_paths = repeat_files[-repeat_batch_size:] + repeat_audio
                    final_names = {
                        os.path.basename(value)
                        for value in final_paths
                        if isinstance(value, str) and value
                    }
                    final_files = [
                        filename for filename in new_artifacts
                        if filename in final_names
                    ]

                    for filename in new_artifacts:
                        producer_artifact_roles[filename] = (
                            "final" if filename in final_names else "window"
                        )
                    if new_artifacts:
                        repeat_final_files.update(final_files)
                        repeat_unit_id = recovery_unit_id(
                            job_id,
                            "ordinary_repeat",
                            index=max(0, completed_repeats - 1),
                        )
                        recovery_units = {
                            filename: {
                                "index": max(0, completed_repeats - 1),
                                "kind": "ordinary_repeat",
                                "unit_id": repeat_unit_id,
                                "variant": 0,
                            }
                            for filename in new_artifacts
                        }
                        # Access policy must be durable before the filename is
                        # exposed on the job; otherwise a remote request could
                        # observe a private output during the sidecar gap.
                        _write_output_sidecars(
                            new_artifacts,
                            native_source=h3_delivery_request,
                            recovery_units=recovery_units,
                            media_paths={
                                name: staged_media[name]
                                for name in new_artifacts
                                if name in staged_media
                            },
                        )
                        if staged_media:
                            _queue_recovery_promote_staged_outputs(
                                gen,
                                out_dir,
                                {
                                    name: staged_media[name]
                                    for name in new_artifacts
                                    if name in staged_media
                                },
                            )
                        _queue_recovery_checkpoint_unit(
                            job,
                            kind="ordinary_repeat",
                            variant=0,
                            index=max(0, completed_repeats - 1),
                            project_dir=out_dir,
                            artifact_names=new_artifacts,
                            ordinary_repeat_offset=completed_repeats,
                        )
                        record_job_outputs(
                            job,
                            new_artifacts,
                            final_output_files=(
                                [] if h3_delivery_request else final_files
                            ),
                        )
                        repeat_published_artifacts.update(new_artifacts)
                    # No model call is active at this returned WGP boundary.
                    # Temporarily close live-counter mutation while deciding
                    # whether another repeat exists; held jobs remain editable
                    # through their queued request state and are reconciled on
                    # resume below.
                    unregister_abort_state(
                        job_id,
                        _active_gen_states,
                        abort_state,
                    )
                    try:
                        pending_repeats = int(gen.get("extra_orders", 0) or 0)
                        current_total = max(
                            completed_repeats,
                            int(gen.get("total_generation") or 0)
                            + pending_repeats,
                        )
                    except (TypeError, ValueError):
                        completed_repeats = current_total = 0
                    if completed_repeats >= current_total:
                        return True

                    update_job(
                        job,
                        message="Preparing next output…",
                        phase="Preparing next output",
                        step=0,
                        total_steps=0,
                        window_step=0,
                        window_total_steps=0,
                        window_progress=0,
                        progress_indeterminate=True,
                    )
                    inactive_started = time.time()
                    resumed = yield_generation_slot_after_output(_gen_lock, job)
                    _record_eta_inactive_time(inactive_started)
                    if resumed:
                        if is_cancel_requested(job):
                            return False
                        # Another job may have rebound WGP's process-global
                        # output roots and VRAM policy while this job yielded.
                        # Restore this job's complete mutable runtime context
                        # before its next one-output model call begins.
                        wgp.save_path = out_dir
                        wgp.image_save_path = out_dir
                        wgp.audio_save_path = out_dir
                        _restore_base_coefficient()
                        _apply_per_job_coefficient(job)
                        # A held running job is represented as queued while it
                        # waits. Output-count edits made in that interval update
                        # the job request rather than WGP's active counter; fold
                        # the latest target back into the next repeat here.
                        try:
                            completed_repeats = max(
                                0, int(gen.get("repeat_no") or 0),
                            )
                            active_total = max(
                                completed_repeats,
                                int(gen.get("total_generation") or 0),
                            )
                            requested_total = max(
                                completed_repeats,
                                int(job.get("requested_outputs") or active_total),
                            )
                            gen["extra_orders"] = requested_total - active_total
                        except (TypeError, ValueError):
                            pass
                        if not register_abort_state(
                            job,
                            job_id,
                            _active_gen_states,
                            abort_state,
                            interrupt_model=_interrupt_wan_model,
                        ):
                            return False
                    return resumed

                def _seal_final_h3_segment_before_concat(
                    rendered_path, callback_clip_info,
                ):
                    """Seal/promote the last component before WGP enters ffmpeg."""
                    if (
                        not recovery_h3_segment
                        or not isinstance(callback_clip_info, dict)
                        or not isinstance(rendered_path, str)
                    ):
                        raise QueueRecoveryRuntimeError(
                            "H3 pre-concat segment callback is invalid."
                        )
                    try:
                        variant = max(
                            0,
                            int(callback_clip_info.get("output_index", 0) or 0),
                        )
                        segment_index = max(
                            0, int(callback_clip_info.get("index", 0) or 0),
                        )
                        segment_total = max(
                            1, int(callback_clip_info.get("total", 1) or 1),
                        )
                    except (TypeError, ValueError):
                        raise QueueRecoveryRuntimeError(
                            "H3 pre-concat segment identity is invalid."
                        ) from None
                    if segment_index + 1 != segment_total:
                        raise QueueRecoveryRuntimeError(
                            "Only the final H3 segment may use pre-concat sealing."
                        )
                    name = os.path.basename(rendered_path)
                    if (
                        not name
                        or os.path.splitext(name)[1].lower()
                        not in {".mp4", ".webm", ".mkv", ".mov"}
                    ):
                        raise QueueRecoveryRuntimeError(
                            "H3 pre-concat segment media is invalid."
                        )
                    staged_media = _queue_recovery_staged_media_paths(
                        [rendered_path], recovery_staging_dir,
                    )
                    resolved = _queue_recovery_resolve_task_video_path(
                        rendered_path, out_dir, staged_media,
                    )
                    if resolved is None:
                        raise QueueRecoveryRuntimeError(
                            "H3 pre-concat segment media is unavailable."
                        )
                    dependencies, predecessor_evidence = (
                        _h3_verified_segment_dependency_evidence(
                        variant, segment_index,
                        )
                    )
                    segment_settings = _h3_segment_recovery_settings(
                        callback_clip_info,
                    )
                    segment_settings.update(predecessor_evidence)
                    unit_id = recovery_unit_id(
                        job_id, "h3_segment", variant=variant,
                        index=segment_index, dependencies=dependencies,
                        settings=segment_settings,
                    )
                    producer_artifact_roles[name] = "component"
                    update_job(
                        job,
                        message="Sealing rendered segment before final join...",
                        phase="Segment checkpoint",
                    )
                    _write_output_sidecars(
                        [name],
                        native_source=h3_delivery_request,
                        recovery_units={
                            name: {
                                "continuation": None,
                                "dependencies": list(dependencies),
                                "index": segment_index,
                                "kind": "h3_segment",
                                "settings": dict(segment_settings),
                                "unit_id": unit_id,
                                "variant": variant,
                            },
                        },
                        media_paths=(
                            {name: staged_media[name]}
                            if name in staged_media else None
                        ),
                        task_params=task_sidecar_params,
                    )
                    if name in staged_media:
                        _queue_recovery_promote_staged_outputs(
                            gen, out_dir, {name: staged_media[name]},
                        )
                    _queue_recovery_checkpoint_unit(
                        job,
                        kind="h3_segment",
                        variant=variant,
                        index=segment_index,
                        project_dir=out_dir,
                        artifact_names=[name],
                        dependencies=dependencies,
                        settings=segment_settings,
                    )
                    clip_output_files[segment_index] = name
                    return os.path.join(out_dir, name)

                if not is_multiclip and not defer_output_publication:
                    params["after_repeat_output"] = (
                        _publish_and_yield_after_repeat_output
                    )
                    cursor = job.get("recovery_cursor")
                    if isinstance(cursor, dict):
                        try:
                            params["repeat_start_offset"] = max(
                                0, int(cursor.get("ordinary_repeat_offset", 0) or 0),
                            )
                        except (TypeError, ValueError):
                            params["repeat_start_offset"] = 0
                if recovery_h3_segment:
                    try:
                        callback_index = max(
                            0, int((recovery_clip or {}).get("index", 0) or 0),
                        )
                        callback_total = max(
                            1, int((recovery_clip or {}).get("total", 1) or 1),
                        )
                    except (TypeError, ValueError):
                        callback_index = 0
                        callback_total = 1
                    if callback_index + 1 == callback_total:
                        params["after_segment_output"] = (
                            _seal_final_h3_segment_before_concat
                        )

                com_stream = AsyncStream()
                send_cmd = com_stream.output_queue.push
                _h3_call_timing = {}

                def make_error_handler(task, params, send_cmd):
                    def error_handler():
                        call_started = time.perf_counter()
                        try:
                            expected_args = set(inspect.signature(wgp.generate_video).parameters.keys())
                            filtered_params = {k: v for k, v in params.items() if k in expected_args}
                            if task_h3_turbo_validation_authorized:
                                filtered_params[
                                    "_h3_turbo_validation_authorized"
                                ] = True
                            plugin_data = task.get('plugin_data', {})
                            call_model = str(filtered_params.get("model_type") or "")
                            _h3_call_timing["model_load_state"] = (
                                "resident"
                                if _h3_model_is_resident(call_model)
                                else "cold"
                            )
                            wgp.generate_video(task, send_cmd, plugin_data=plugin_data, **filtered_params)
                        except Exception as e:
                            print(f"\n  [ERROR] {e}")
                            traceback.print_exc()
                            send_cmd(
                                "error",
                                _safe_failure_updates(e, job)[
                                    "failure_details"
                                ],
                            )
                        finally:
                            _h3_call_timing["seconds"] = max(
                                0.001, time.perf_counter() - call_started,
                            )
                            send_cmd("exit", None)
                    return error_handler

                async_run(make_error_handler(task, params, send_cmd))

                def _publish_window_progress(progress_updates, step=0, total=0):
                    """Attach exact clip/window state to an API job update."""
                    try:
                        window_current = max(0, int(gen.get("window_no") or 0))
                        window_total = max(0, int(gen.get("total_windows") or 0))
                    except (TypeError, ValueError):
                        window_current = window_total = 0
                    has_inner_windows = window_total > 1 and window_current > 0
                    active_prompt = str(
                        (
                            gen.get("current_window_prompt")
                            if has_inner_windows else None
                        )
                        or (task.get("params") or {}).get("prompt")
                        or ""
                    )[:500]
                    window_fraction, window_percent, has_exact_progress = (
                        _window_progress_values(
                            step,
                            total,
                            job.get("window_progress", 0),
                        )
                    )
                    if is_multiclip:
                        clip_current = task_no
                        clip_total = total_tasks
                        if has_exact_progress:
                            overall = max(
                                int(100 * task_idx / total_tasks),
                                int(progress_updates.get("progress") or 0),
                            )
                        else:
                            overall = max(
                                int(100 * task_idx / total_tasks),
                                int(job.get("overall_progress") or 0),
                            )
                        if not has_inner_windows:
                            # H3 has native clips rather than latent sliding
                            # windows. Alias clip position into the existing
                            # window fields so older clients still show useful
                            # overall/current progress.
                            window_current = clip_current
                            window_total = clip_total
                    elif window_total > 0 and window_current > 0:
                        clip_current = clip_total = 0
                        if has_exact_progress:
                            overall = int(
                                100 * min(
                                    1.0,
                                    ((window_current - 1) + window_fraction)
                                    / window_total,
                                )
                            )
                        else:
                            overall = int(job.get("overall_progress") or 0)
                    else:
                        clip_current = clip_total = 0
                        overall = (
                            int(progress_updates.get("progress") or 0)
                            if has_exact_progress
                            else int(job.get("overall_progress") or 0)
                        )
                    progress_updates.update(
                        window_current=window_current,
                        window_total=window_total,
                        window_step=max(0, int(step or 0)),
                        window_total_steps=max(0, int(total or 0)),
                        window_progress=window_percent,
                        overall_progress=overall,
                        active_window_prompt=active_prompt,
                        clip_current=clip_current,
                        clip_total=clip_total,
                        clip_progress=(
                            window_percent
                            if has_exact_progress
                            else int(job.get("clip_progress") or 0)
                        ),
                    )
                    _preserve_indeterminate_progress(
                        progress_updates,
                        job,
                        has_exact_progress,
                    )
                    if window_total > 1 or is_multiclip or not has_exact_progress:
                        progress_updates["progress"] = progress_updates[
                            "overall_progress"
                        ]

                # Process stream — update job dict with live progress
                task_error = False
                task_failure_details = None
                last_msg_len = 0
                in_status_line = False
                while True:
                    cmd, data = com_stream.output_queue.next()
                    if is_cancel_requested(job) and cmd != "exit":
                        continue
                    if cmd == "exit":
                        if in_status_line:
                            print()
                        break
                    elif cmd == "error":
                        print(f"\n  [ERROR] {data}")
                        in_status_line = False
                        task_error = True
                        failure_updates = _safe_failure_updates(data, job)
                        task_failure_details = failure_updates["failure_details"]
                        if first_task_error is None:
                            first_failure_details = task_failure_details
                            first_task_error = task_failure_details["detail"]
                        update_job(job, **failure_updates)
                    elif cmd == "progress":
                        if isinstance(data, list) and len(data) >= 2:
                            progress_updates = {}
                            import re as _re
                            if isinstance(data[0], tuple):
                                step, total = data[0]
                                msg = data[1] if len(data) > 1 else ""
                                # For TTS: extract progress from message
                                # Multi-speaker: "Segment 26/51" — use segment count
                                # Single-speaker: "45/600 s" — show seconds, use indeterminate progress
                                seg_match = _re.search(r'Segment\s+(\d+)/(\d+)', msg)
                                sec_match = _re.search(r'(\d+)/(\d+)\s*s\b', msg) if not seg_match else None
                                if sec_match:
                                    # Single/text mode: show seconds generated as a pulsing progress
                                    sec_current = int(sec_match.group(1))
                                    progress_updates.update(
                                        progress=min(95, sec_current * 3),
                                        step=sec_current,
                                        total_steps=0,
                                        message=f"Generating audio... {sec_current}s",
                                    )
                                if seg_match:
                                    seg_current = int(seg_match.group(1))
                                    seg_total = int(seg_match.group(2))
                                    progress_updates.update(
                                        progress=int((seg_current / seg_total) * 100) if seg_total > 0 else 0,
                                        step=seg_current,
                                        total_steps=seg_total,
                                    )
                                elif is_multiclip and total > 0:
                                    # Aggregate: each clip contributes 1/total_tasks of overall progress
                                    clip_progress = step / total
                                    progress_updates["progress"] = int(((task_idx + clip_progress) / total_tasks) * 100)
                                    progress_info = (
                                        (task.get("params") or {}).get(
                                            "multi_clip_info",
                                        )
                                        or {}
                                    )
                                    progress_label = str(
                                        progress_info.get(
                                            "progress_label",
                                        )
                                        or "Clip"
                                    )
                                    msg = (
                                        f"{progress_label} "
                                        f"{task_no}/{total_tasks}: {msg}"
                                    )
                                    progress_updates.update(step=step, total_steps=total)
                                else:
                                    progress_updates.update(
                                        progress=int((step / total) * 100) if total > 0 else 0,
                                        step=step,
                                        total_steps=total,
                                    )
                            else:
                                step = 0
                                msg = data[1] if len(data) > 1 else str(data[0])
                                total = 0
                                progress_updates.update(step=0, total_steps=0)
                            # WGP appends elapsed time to the display message.
                            # Strip only that volatile suffix so phase timing
                            # resets at real preparation/denoising/decode
                            # boundaries, never on every denoising callback.
                            progress_updates.update(
                                _phase_progress_values(msg, step, total)
                            )
                            _publish_window_progress(progress_updates, step, total)
                            progress_updates.update(
                                _subtask_eta_progress_updates(
                                    job,
                                    progress_updates,
                                    data,
                                )
                            )
                            if total and total > 0 and not job.get(
                                "_eta_progress_started_at"
                            ):
                                progress_updates.update(
                                    _eta_progress_started_at=time.time(),
                                    _eta_progress_baseline=float(
                                        progress_updates.get("overall_progress")
                                        or progress_updates.get("progress")
                                        or 0
                                    ),
                                    _eta_inactive_at_progress_start=float(
                                        job.get("_eta_inactive_seconds") or 0
                                    ),
                                )
                            if not update_job(job, **progress_updates):
                                continue
                            status_line = f"\r  [{step}/{total}] {msg}" if total > 0 else f"\r  {msg}"
                            print(status_line.ljust(max(last_msg_len, len(status_line))), end="", flush=True)
                            last_msg_len = len(status_line)
                            in_status_line = True
                    elif cmd == "status":
                        status_updates = {
                            "message": str(data),
                            "phase": str(data),
                            "step": 0,
                            "total_steps": 0,
                            "progress": 0,
                            "progress_indeterminate": True,
                        }
                        _publish_window_progress(status_updates)
                        if not update_job(
                            job,
                            **status_updates,
                        ):
                            continue
                        if "Loading" in str(data):
                            print(data)
                            in_status_line = False
                            last_msg_len = 0
                        else:
                            status_line = f"\r  {data}"
                            print(status_line.ljust(max(last_msg_len, len(status_line))), end="", flush=True)
                            last_msg_len = len(status_line)
                            in_status_line = True
                    elif cmd == "info":
                        print(f"\n  [INFO] {data}")
                        in_status_line = False

                # WGP may emit several cumulative sliding-window files for a
                # single clip. Bind only the latest file from this task to its
                # explicit multi-clip index; filename ordering is ambiguous.
                task_files = []
                for output_path in (
                    (gen.get("artifact_list") or [])[task_artifact_start:]
                    + (gen.get("file_list") or [])[task_file_start:]
                ):
                    if output_path not in task_files:
                        task_files.append(output_path)
                task_staged_media = _queue_recovery_staged_media_paths(
                    task_files, recovery_staging_dir,
                )
                clip_info = (task.get("params") or {}).get("multi_clip_info")
                task_params = task.get("params") or {}
                task_media_names = []
                task_role_by_filename = {}
                h3_continuation = None
                registered_artifact_roles = gen.get("artifact_roles")
                if not isinstance(registered_artifact_roles, dict):
                    registered_artifact_roles = {}
                for output_path in task_files:
                    filename = os.path.basename(output_path)
                    if os.path.splitext(filename)[1].lower() in GENERATED_MEDIA_EXTENSIONS:
                        task_media_names.append(filename)
                        role = registered_artifact_roles.get(output_path)
                        if role in _RECOVERY_ARTIFACT_ROLES:
                            task_role_by_filename[filename] = role
                if (
                    not task_error
                    and str(task_params.get("model_type") or "") in _H3_LONG_STUDIO_MODELS
                    and task_media_names
                ):
                    try:
                        _record_h3_benchmark_observation(
                            task_params,
                            wall_time_seconds=float(_h3_call_timing.get("seconds") or 0),
                            output_files=task_media_names,
                            out_dir=(
                                recovery_staging_dir
                                if task_staged_media else out_dir
                            ),
                            model_load_state=str(
                                _h3_call_timing.get("model_load_state") or "unknown"
                            ),
                        )
                    except Exception as benchmark_error:
                        print(f"[H3 Estimate] Observation skipped: {benchmark_error}")
                task_video_names = [
                    filename for filename in task_media_names
                    if os.path.splitext(filename)[1].lower()
                    in {".mp4", ".webm", ".mkv", ".mov"}
                    and task_role_by_filename.get(filename) != "final"
                ]
                try:
                    task_is_sliding = (
                        int(task_params.get("sliding_window_size") or 0) > 0
                        and int(task_params.get("video_length") or 0)
                        > int(task_params.get("sliding_window_size") or 0)
                    )
                except (TypeError, ValueError):
                    task_is_sliding = False
                for filename in task_media_names:
                    declared_role = task_role_by_filename.get(filename)
                    if declared_role in _RECOVERY_ARTIFACT_ROLES:
                        producer_artifact_roles[filename] = declared_role
                    elif filename in repeat_final_files:
                        producer_artifact_roles[filename] = "final"
                    elif (
                        task_is_sliding
                        and filename in task_video_names[:-1]
                    ):
                        producer_artifact_roles[filename] = "window"
                    elif isinstance(clip_info, dict):
                        producer_artifact_roles[filename] = "component"
                    else:
                        producer_artifact_roles[filename] = "final"
                if isinstance(clip_info, dict) and "index" in clip_info:
                    latest_clip_file = None
                    for output_path in reversed(task_files):
                        filename = os.path.basename(output_path)
                        _stem, extension = os.path.splitext(filename)
                        if extension.lower() not in {
                            ".mp4", ".webm", ".mkv", ".mov",
                        }:
                            continue
                        role = producer_artifact_roles.get(filename)
                        if role == "final":
                            if join_output_file is None:
                                join_output_file = filename
                        elif role == "component" and latest_clip_file is None:
                            latest_clip_file = filename
                    if latest_clip_file:
                        try:
                            clip_output_files[
                                int(clip_info["index"])
                            ] = latest_clip_file
                        except (TypeError, ValueError):
                            pass

                if is_cancel_requested(job) or gen.get("abort"):
                    cancelled = True
                    break

                # WGP renders and registers the last H3 segment before it
                # attempts concat/audio mux. If that post-decode operation
                # fails, seal the already-rendered component now so restart
                # can replay concat only and never repeat denoising.
                failure_stage = str(
                    (task_failure_details or {}).get("stage") or ""
                )
                if (
                    task_error
                    and failure_stage in {"concat", "audio_mux"}
                    and isinstance(clip_info, dict)
                    and clip_info.get("automatic_h3_longform")
                ):
                    try:
                        failed_variant = max(
                            0, int(clip_info.get("output_index", 0) or 0),
                        )
                        failed_segment = max(
                            0, int(clip_info.get("index", 0) or 0),
                        )
                        failed_total = max(
                            1, int(clip_info.get("total", 1) or 1),
                        )
                    except (TypeError, ValueError):
                        raise RuntimeError(
                            "H3 recovery segment identity is invalid"
                        )
                    failed_segment_names = [
                        name for name in task_media_names
                        if producer_artifact_roles.get(name)
                        in {"component", "window"}
                    ]
                    if failed_segment + 1 != failed_total:
                        raise QueueRecoveryRuntimeError(
                            "H3 concat failed before the final segment boundary."
                        )
                    if not failed_segment_names:
                        raise QueueRecoveryRuntimeError(
                            "H3 concat failure produced no sealable segment."
                        )
                    failed_dependencies, predecessor_evidence = (
                        _h3_verified_segment_dependency_evidence(
                        failed_variant, failed_segment,
                        )
                    )
                    failed_settings = _h3_segment_recovery_settings(clip_info)
                    failed_settings.update(predecessor_evidence)
                    failed_unit_id = recovery_unit_id(
                        job_id, "h3_segment", variant=failed_variant,
                        index=failed_segment, dependencies=failed_dependencies,
                        settings=failed_settings,
                    )
                    sealed_failed_unit = _queue_recovery_unit_matches(
                        job,
                        kind="h3_segment",
                        variant=failed_variant,
                        index=failed_segment,
                        project_dir=out_dir,
                    )
                    if sealed_failed_unit is None and not update_job(
                        job,
                        message="Sealing rendered segment...",
                        phase="Segment checkpoint",
                    ):
                        return False
                    failed_units = {
                        name: {
                            "continuation": None,
                            "dependencies": list(failed_dependencies),
                            "index": failed_segment,
                            "kind": "h3_segment",
                            "settings": dict(failed_settings),
                            "unit_id": failed_unit_id,
                            "variant": failed_variant,
                        }
                        for name in failed_segment_names
                    }
                    if sealed_failed_unit is None:
                        _write_output_sidecars(
                            failed_segment_names,
                            native_source=h3_delivery_request,
                            recovery_units=failed_units,
                            media_paths={
                                name: task_staged_media[name]
                                for name in failed_segment_names
                                if name in task_staged_media
                            },
                            task_params=task_sidecar_params,
                        )
                    if sealed_failed_unit is None and task_staged_media:
                        _queue_recovery_promote_staged_outputs(
                            gen,
                            out_dir,
                            {
                                name: task_staged_media[name]
                                for name in failed_segment_names
                                if name in task_staged_media
                            },
                        )
                    if sealed_failed_unit is None:
                        _queue_recovery_checkpoint_unit(
                            job,
                            kind="h3_segment",
                            variant=failed_variant,
                            index=failed_segment,
                            project_dir=out_dir,
                            artifact_names=failed_segment_names,
                            dependencies=failed_dependencies,
                            settings=failed_settings,
                        )

                if not task_error:
                    completed += 1
                    print(f"\n  Task {task_no} completed")

                    # Free VRAM between clips to prevent OOM on long pipelines
                    if is_multiclip and task_idx + 1 < total_tasks:
                        gc.collect()
                        torch.cuda.empty_cache()

                    # Multi-clip continuation: if next clip has no start image,
                    # extract last frame from this clip's output as its start image
                    if is_multiclip and task_idx + 1 < total_tasks:
                        next_task = queue[task_idx + 1]
                        next_params = next_task.get('params', {})
                        ref2va_boundary = next_params.get("_ref2va_continuation")
                        native_boundary_request = next_params.get(
                            "_h3_native_boundary_request"
                        )
                        if (
                            next_params.get("_continuation", False)
                            or ref2va_boundary
                            or native_boundary_request
                        ):
                            next_clip_info = (
                                next_params.get("multi_clip_info") or {}
                            )
                            required_h3_continuation = bool(
                                next_clip_info.get("automatic_h3_longform")
                            )
                            # Find the latest video explicitly registered by
                            # this task; a shared-folder diff can pick up a
                            # concurrent dashboard operation's media.
                            video_exts = {".mp4", ".webm", ".mkv", ".mov"}
                            latest_video = None
                            for output_path in reversed(task_files):
                                if os.path.splitext(output_path)[1].lower() in video_exts:
                                    latest_video = (
                                        _queue_recovery_resolve_task_video_path(
                                            output_path,
                                            out_dir,
                                            task_staged_media,
                                        )
                                    )
                                    if latest_video:
                                        break
                            if latest_video:
                                try:
                                    recovery_output_prefix = str(
                                        params.get("_recovery_output_prefix") or ""
                                    )
                                    if native_boundary_request:
                                        native_prefix = str(
                                            params.get("_recovery_output_prefix")
                                            or f"unit-{job_id}-t{task_idx}"
                                        )
                                        handoff = _attach_h3_native_boundary_handoff(
                                            next_params,
                                            latest_video=latest_video,
                                            project_dir=out_dir,
                                            output_prefix=native_prefix,
                                        )
                                        h3_continuation = dict(handoff)
                                        print(
                                            "  [H3 Native] 18-frame AV boundary "
                                            f"prepared for segment {task_no + 1}"
                                        )
                                    else:
                                        from PIL import Image as PILImage
                                        import decord
                                        vr = decord.VideoReader(latest_video)
                                        current_clip_info = (
                                            (task.get("params") or {}).get(
                                                "multi_clip_info"
                                            )
                                            or {}
                                        )
                                        safe_idx = max(0, len(vr) - 1)
                                        if not current_clip_info.get(
                                            "automatic_h3_longform"
                                        ):
                                            safe_idx = max(0, len(vr) - 9)
                                        frame_img = PILImage.fromarray(
                                            vr[safe_idx].asnumpy()
                                        )
                                        del vr
                                        if recovery_staging_dir:
                                            if not recovery_output_prefix:
                                                raise QueueRecoveryRuntimeError(
                                                    "H3 recovery continuation identity is missing."
                                                )
                                            cont_path = os.path.join(
                                                recovery_staging_dir,
                                                f"{recovery_output_prefix}-continuation.png",
                                            )
                                        else:
                                            cont_path = os.path.join(
                                                out_dir,
                                                f"_continuation_{task_no}.png",
                                            )
                                        frame_img.save(cont_path)
                                        if ref2va_boundary:
                                            handoff = _attach_h3_ref2va_handoff(
                                                next_params,
                                                latest_video=latest_video,
                                                last_frame_path=cont_path,
                                                out_dir=out_dir,
                                                task_no=task_no,
                                                boundary_type=str(ref2va_boundary),
                                                recovery_staging_dir=recovery_staging_dir,
                                                recovery_output_prefix=(
                                                    recovery_output_prefix or None
                                                ),
                                            )
                                            next_params.pop("_ref2va_continuation", None)
                                            warning = handoff.get("warning")
                                            h3_continuation = {
                                                "mode": str(handoff.get("mode") or "prompt_only"),
                                                "path": handoff.get("path"),
                                            }
                                            print(
                                                "  [H3 Ref2VA] "
                                                f"{handoff['mode']} handoff for segment "
                                                f"{task_no + 1} ({ref2va_boundary})"
                                                + (f"; fallback: {warning}" if warning else "")
                                            )
                                        else:
                                            next_params["image_start"] = cont_path
                                            next_params["image_prompt_type"] = "S" + (next_params.get("image_prompt_type", "") or "")
                                            next_task["start_image_data"] = frame_img
                                            next_params.pop("_continuation", None)
                                            h3_continuation = {
                                                "mode": "last_frame",
                                                "path": cont_path,
                                            }
                                            print(f"  [Continuation] Extracted last frame for clip {task_no + 1}")
                                except Exception as e:
                                    message = (
                                        "Failed to prepare the required last-frame "
                                        f"continuation for segment {task_no + 1}: {e}"
                                    )
                                    if required_h3_continuation:
                                        raise RuntimeError(message) from e
                                    next_params.pop("_continuation", None)
                                    next_params.pop("_ref2va_continuation", None)
                                    next_params.pop(
                                        "_h3_native_boundary_request", None,
                                    )
                                    print(f"  [Continuation] {message}")
                            elif required_h3_continuation:
                                raise RuntimeError(
                                    "Failed to prepare the required last-frame "
                                    f"continuation for segment {task_no + 1}: "
                                    "the preceding segment produced no readable video"
                                )
                            else:
                                next_params.pop("_continuation", None)
                                next_params.pop("_ref2va_continuation", None)
                                next_params.pop(
                                    "_h3_native_boundary_request", None,
                                )

                    if (
                        isinstance(clip_info, dict)
                        and clip_info.get("automatic_h3_longform")
                    ):
                        try:
                            h3_variant = max(
                                0, int(clip_info.get("output_index", 0) or 0),
                            )
                            h3_segment = max(0, int(clip_info.get("index", 0) or 0))
                            h3_total_segments = max(1, int(clip_info.get("total", 1) or 1))
                        except (TypeError, ValueError):
                            raise RuntimeError("H3 recovery segment identity is invalid")
                        h3_dependencies, predecessor_evidence = (
                            _h3_verified_segment_dependency_evidence(
                            h3_variant, h3_segment,
                            )
                        )
                        h3_segment_settings = _h3_segment_recovery_settings(
                            clip_info,
                        )
                        h3_segment_settings.update(predecessor_evidence)
                        h3_segment_unit_id = recovery_unit_id(
                            job_id, "h3_segment", variant=h3_variant,
                            index=h3_segment, dependencies=h3_dependencies,
                            settings=h3_segment_settings,
                        )
                        segment_names = [
                            name for name in task_media_names
                            if producer_artifact_roles.get(name)
                            in {"component", "window"}
                        ]
                        concat_names = [
                            name for name in task_media_names
                            if producer_artifact_roles.get(name) == "final"
                        ]
                        continuation_descriptor = None
                        if isinstance(h3_continuation, dict):
                            continuation_descriptor = (
                                _queue_recovery_continuation_descriptor(
                                    out_dir,
                                    h3_continuation.get("path"),
                                    mode=str(
                                        h3_continuation.get("mode") or "prompt_only"
                                    ),
                                    dependency=h3_segment_unit_id,
                                    metadata=h3_continuation,
                                )
                            )
                        sealed_segment_unit = _queue_recovery_unit_matches(
                            job,
                            kind="h3_segment",
                            variant=h3_variant,
                            index=h3_segment,
                            project_dir=out_dir,
                        )
                        if segment_names and sealed_segment_unit is None:
                            if not update_job(
                                job,
                                message="Sealing rendered segment...",
                                phase="Segment checkpoint",
                            ):
                                return False
                            segment_units = {
                                name: {
                                    "continuation": continuation_descriptor,
                                    "dependencies": list(h3_dependencies),
                                    "index": h3_segment,
                                    "kind": "h3_segment",
                                    "settings": dict(h3_segment_settings),
                                    "unit_id": h3_segment_unit_id,
                                    "variant": h3_variant,
                                }
                                for name in segment_names
                            }
                            _write_output_sidecars(
                                segment_names,
                                native_source=h3_delivery_request,
                                recovery_units=segment_units,
                                media_paths={
                                    name: task_staged_media[name]
                                    for name in segment_names
                                    if name in task_staged_media
                                },
                                task_params=task_sidecar_params,
                            )
                            if task_staged_media:
                                _queue_recovery_promote_staged_outputs(
                                    gen,
                                    out_dir,
                                    {
                                        name: task_staged_media[name]
                                        for name in segment_names
                                        if name in task_staged_media
                                    },
                                )
                            _queue_recovery_checkpoint_unit(
                                job,
                                kind="h3_segment",
                                variant=h3_variant,
                                index=h3_segment,
                                project_dir=out_dir,
                                artifact_names=segment_names,
                                dependencies=h3_dependencies,
                                continuation=continuation_descriptor,
                                settings=h3_segment_settings,
                            )
                        if concat_names and not task_error:
                            concat_dependencies = []
                            clip_start_frames = []
                            clip_tail_frames = []
                            component_hashes = []
                            for segment_index in range(h3_total_segments):
                                component_unit = _queue_recovery_unit_matches(
                                    job,
                                    kind="h3_segment",
                                    variant=h3_variant,
                                    index=segment_index,
                                    project_dir=out_dir,
                                )
                                if component_unit is None:
                                    raise QueueRecoveryRuntimeError(
                                        "H3 concat producer segment is not durable."
                                    )
                                concat_dependencies.append(
                                    str(component_unit.get("unit_id") or "")
                                )
                                component_settings = component_unit.get("settings")
                                if not isinstance(component_settings, dict):
                                    raise QueueRecoveryRuntimeError(
                                        "H3 concat producer trim metadata is unavailable."
                                    )
                                clip_start_frames.append(int(
                                    component_settings.get(
                                        "discard_prefix_frames", 0,
                                    ) or 0
                                ))
                                clip_tail_frames.append(int(
                                    component_settings.get(
                                        "trim_tail_frames", 0,
                                    ) or 0
                                ))
                                component_hashes.extend(
                                    artifact.get("sha256")
                                    for artifact in component_unit.get("artifacts") or []
                                    if isinstance(artifact, dict)
                                )
                            concat_settings = {
                                "audio_start_ms": int(
                                    1000 * float(clip_info.get("audio_start_sec", 0) or 0)
                                ),
                                "component_hashes": component_hashes,
                                "clip_start_frames": clip_start_frames,
                                "clip_tail_frames": clip_tail_frames,
                                "preserve_generated_audio": bool(
                                    clip_info.get("preserve_generated_audio")
                                ),
                            }
                            concat_unit_id = recovery_unit_id(
                                job_id,
                                "h3_concat",
                                variant=h3_variant,
                                dependencies=concat_dependencies,
                                settings=concat_settings,
                            )
                            concat_units = {
                                name: {
                                    "dependencies": list(concat_dependencies),
                                    "index": 0,
                                    "kind": "h3_concat",
                                    "settings": dict(concat_settings),
                                    "unit_id": concat_unit_id,
                                    "variant": h3_variant,
                                }
                                for name in concat_names
                            }
                            _write_output_sidecars(
                                concat_names,
                                native_source=h3_delivery_request,
                                recovery_units=concat_units,
                                media_paths={
                                    name: task_staged_media[name]
                                    for name in concat_names
                                    if name in task_staged_media
                                },
                                task_params=task_sidecar_params,
                            )
                            if task_staged_media:
                                _queue_recovery_promote_staged_outputs(
                                    gen,
                                    out_dir,
                                    {
                                        name: task_staged_media[name]
                                        for name in concat_names
                                        if name in task_staged_media
                                    },
                                )
                            _queue_recovery_checkpoint_unit(
                                job,
                                kind="h3_concat",
                                variant=h3_variant,
                                index=0,
                                project_dir=out_dir,
                                artifact_names=concat_names,
                                dependencies=concat_dependencies,
                                settings=concat_settings,
                            )

                    # A complete H3 variant is a safe scheduler boundary only
                    # after its final native segment has returned and WGP has
                    # concatenated the group. Never yield between continuation
                    # segments: the next segment still depends on the handoff
                    # prepared immediately above.
                    if task_idx + 1 < total_tasks:
                        current_group = str(
                            ((task.get("params") or {}).get("multi_clip_info") or {}).get("group_id")
                            or ""
                        )
                        next_group = str(
                            ((queue[task_idx + 1].get("params") or {}).get("multi_clip_info") or {}).get("group_id")
                            or ""
                        )
                        if current_group and next_group and current_group != next_group:
                            update_job(
                                job,
                                message="Preparing next output…",
                                phase="Preparing next output",
                                step=0,
                                total_steps=0,
                                window_step=0,
                                window_total_steps=0,
                                window_progress=0,
                                progress_indeterminate=True,
                            )
                            inactive_started = time.time()
                            if not yield_generation_slot_after_output(
                                _gen_lock, job,
                            ):
                                _record_eta_inactive_time(inactive_started)
                                cancelled = True
                                break
                            _record_eta_inactive_time(inactive_started)

            elapsed = time.time() - start_time
            print(f"\n{'='*50}")
            summary = f"Queue completed: {completed}/{total_tasks} tasks in {wgp.format_time(elapsed)}"
            if skipped > 0:
                summary += f" ({skipped} skipped)"
            print(summary)
            # A rejected task is not a completed task. In particular, an
            # all-rejected request must never satisfy ``0 == total-skipped``
            # and publish a false successful terminal state with no outputs.
            success = _generation_tasks_succeeded(
                completed=completed,
                skipped=skipped,
                total_tasks=total_tasks,
                cancelled=cancelled,
            )

            # Clean up continuation temp files
            if os.path.isdir(out_dir):
                for f in os.listdir(out_dir):
                    if f.startswith("_continuation_") and os.path.splitext(f)[1].lower() in {".png", ".mp4"}:
                        try:
                            os.remove(os.path.join(out_dir, f))
                        except Exception:
                            pass

            # Publish any files that finished before an abort. Director waits
            # for this worker to settle and persists these partial outputs.
            new_files = []
            if os.path.isdir(out_dir):
                new_files = collect_job_outputs(
                    gen,
                    out_dir,
                    before,
                    allow_legacy_fallback=not bool(
                        job["params"].get("_director_pipeline_id")
                    ),
                )
                verified_h3_final_files = (
                    _verified_h3_concat_output_names(job, out_dir, new_files)
                    if automatic_h3_longform else []
                )
                record_job_outputs(
                    job,
                    [] if defer_output_publication else new_files,
                    clip_output_files=(
                        None
                        if defer_output_publication
                        else clip_output_files
                    ),
                    join_output_file=(
                        None
                        if defer_output_publication
                        else (
                            join_output_file
                            if not automatic_h3_longform
                            or join_output_file in verified_h3_final_files
                            else None
                        )
                    ),
                    final_output_files=(
                        None
                        if defer_output_publication
                        else []
                        if h3_delivery_request
                        else verified_h3_final_files
                        if automatic_h3_longform
                        else None
                        if is_multiclip
                        else [
                            filename for filename in new_files
                            if producer_artifact_roles.get(filename) == "final"
                        ]
                    ),
                )
                if not defer_output_publication:
                    if h3_delivery_request:
                        _write_output_sidecars(new_files, native_source=True)
                    else:
                        _write_output_sidecars(new_files)

                if (
                    automatic_h3_longform
                    and not success
                    and not cancelled
                    and not is_cancel_requested(job)
                ):
                    # Only concat units sealed before the failure are complete
                    # Finals. A failed concat has none; an earlier completed
                    # variant remains available without promoting segments.
                    update_job(job, output_files=verified_h3_final_files)

            if cancelled or is_cancel_requested(job):
                return False

            if os.path.isdir(out_dir):
                # Post-generation outpaint cleanup: combines two operations
                # in a single ffmpeg invocation so we touch the output mp4
                # only once.
                #
                # 1. SOURCE-AREA OVERLAY (lip-sync drift fix). The IC-LoRA
                #    outpaint preserves the source rectangle only
                #    approximately — each window the model regenerates
                #    source pixels with strong conditioning toward the
                #    input, but adds tiny motion variation. Across multiple
                #    sliding windows that drift compounds (each window's
                #    prefix conditioning is the previous window's already
                #    slightly-drifted output), causing visible lip offset
                #    on long talking clips. Hard-overlaying source pixels
                #    on the source rectangle fixes this — the model still
                #    owns the outpainted padding regions.
                #
                # 2. SOURCE-AUDIO MUX. LTX-2 distilled always synthesizes
                #    a fresh audio track via its audio decoder, which
                #    replaces the source audio with unrelated synthetic
                #    audio. We replace it with the source clip's audio.
                #
                # Both ops run BEFORE film grain so film grain operates on
                # the audio-correct, source-locked file (film grain re-
                # encodes video so muxed audio is preserved).
                #
                # Windows file-lock note: the UI has often already opened
                # the freshly-saved mp4 over HTTP for streaming preview by
                # the time we get here. FastAPI's FileResponse does NOT
                # pass FILE_SHARE_DELETE, so os.replace into the live file
                # fails with PermissionError until the stream finishes.
                # We track replace success explicitly and on hard failure
                # promote the post-processed copy to a sibling filename
                # (`_with_source_audio.mp4`), updating job["output_files"]
                # so the UI shows the corrected version.
                _do_audio = bool(raw_params.get("_outpaint_preserve_audio"))
                _do_overlay = bool(raw_params.get("_outpaint_lock_source_pixels"))
                _do_trim = bool(raw_params.get("_outpaint_trim_smear"))
                _trim_boundary = int(raw_params.get("_outpaint_smear_boundary_frame", 0))
                _trim_count = int(raw_params.get("_outpaint_smear_count", 0))
                if success and (_do_audio or _do_overlay or _do_trim) and raw_params.get("_outpaint_source_video"):
                    src_video = raw_params.get("_outpaint_source_video")
                    if src_video and os.path.isfile(src_video):
                        video_exts = {".mp4", ".webm", ".mkv", ".mov"}
                        # Sliding-window outpaint produces ONE complete cumulative mp4
                        # per window (e.g. 4 windows → 4 timestamped saves: 473→937→1401→1424
                        # frames). The post-process should only run on the FINAL save,
                        # not every per-window intermediate. Pick the last canonical mp4
                        # by sorted order — wgp prefixes filenames with timestamps so
                        # alphabetic sort = chronological. Skip _tmp.mp4 (intermediate
                        # save_path_tmp leftover) and our own _with_source_audio.mp4
                        # (in case of re-runs).
                        _candidates = []
                        for fname in sorted(new_files):
                            ext = os.path.splitext(fname)[1].lower()
                            if ext not in video_exts:
                                continue
                            if fname.endswith("_tmp" + ext):
                                continue
                            if "_with_source_audio" in fname or fname.endswith("_post" + ext):
                                continue
                            _candidates.append(fname)
                        if not _candidates:
                            print(f"  [Outpaint] No canonical video output to post-process")
                            # Allow the surrounding 'if' chain to fall through
                        # Process only the final (latest-timestamp) canonical save.
                        # Iterate the single-element list so the existing per-fname logic
                        # (ffmpeg, os.replace, fallback) below still runs as written.
                        for fname in _candidates[-1:]:
                            out_video = os.path.join(out_dir, fname)
                            try:
                                import subprocess
                                # Probe source audio availability
                                src_has_audio = False
                                if _do_audio:
                                    probe = subprocess.run(
                                        ["ffprobe", "-v", "quiet", "-select_streams", "a",
                                         "-show_entries", "stream=codec_type", "-of", "csv=p=0", src_video],
                                        capture_output=True, text=True, timeout=10,
                                    )
                                    src_has_audio = bool(probe.stdout.strip())
                                    if not src_has_audio:
                                        print(f"  [Outpaint] Source has no audio — keeping generated track on {fname}")

                                muxed_path = out_video.rsplit(".", 1)[0] + "_post." + out_video.rsplit(".", 1)[1]

                                # Build ffmpeg command. Three modes:
                                #   - overlay+audio: scale source, overlay on output, mux source audio
                                #   - overlay only: scale source, overlay on output, keep generated audio
                                #   - audio only: copy video, mux source audio
                                cmd = ["ffmpeg", "-y", "-i", out_video, "-i", src_video]
                                if _do_overlay:
                                    ow = int(raw_params.get("_outpaint_overlay_w", 0))
                                    oh = int(raw_params.get("_outpaint_overlay_h", 0))
                                    ox = int(raw_params.get("_outpaint_overlay_x", 0))
                                    oy = int(raw_params.get("_outpaint_overlay_y", 0))
                                    if ow <= 0 or oh <= 0:
                                        # Bad coords — fall through to audio-only path
                                        _do_overlay = False

                                # Decide what filter graph we need. Modes:
                                #
                                #   smear-trim only: cut N frames at boundary 1 of
                                #     output video, mux source audio (no cuts —
                                #     source audio aligns with the trimmed video
                                #     because the smear lag was constant from that
                                #     point onward).
                                #
                                #   audio mux only: copy video, replace audio with
                                #     source audio.
                                #
                                #   overlay (legacy/opt-in): scale source video,
                                #     feathered alpha-overlay onto output, mux
                                #     source audio.
                                #
                                # Trim takes priority over overlay if both are on,
                                # since trim is what fixes the actual lip-sync bug.
                                if _do_trim and _trim_boundary > 0 and _trim_count > 0:
                                    # Read fps from output to compute timestamps.
                                    fps_probe = subprocess.run(
                                        ["ffprobe", "-v", "quiet", "-select_streams", "v:0",
                                         "-show_entries", "stream=r_frame_rate", "-of", "csv=p=0", out_video],
                                        capture_output=True, text=True, timeout=10,
                                    )
                                    _fps = 25.0
                                    _fps_str = fps_probe.stdout.strip()
                                    if "/" in _fps_str:
                                        _num, _den = _fps_str.split("/")
                                        if _den and float(_den) != 0:
                                            _fps = float(_num) / float(_den)
                                    cut_start = _trim_boundary / _fps
                                    cut_end = (_trim_boundary + _trim_count) / _fps
                                    # ffmpeg trim+concat: keep [0, cut_start) and [cut_end, end).
                                    # asetpts on source audio resets PTS so it starts at 0
                                    # in the output timeline; -shortest will clamp the audio
                                    # to the (now shorter by N frames) trimmed video duration.
                                    filter_str = (
                                        f"[0:v]trim=0:{cut_start:.6f},setpts=PTS-STARTPTS[v0];"
                                        f"[0:v]trim={cut_end:.6f},setpts=PTS-STARTPTS[v1];"
                                        f"[v0][v1]concat=n=2:v=1[outv]"
                                    )
                                    cmd += ["-filter_complex", filter_str, "-map", "[outv]"]
                                    cmd += ["-c:v", "libx264", "-crf", "18", "-preset", "fast", "-pix_fmt", "yuv420p"]
                                    if _do_audio and src_has_audio:
                                        cmd += ["-map", "1:a:0", "-c:a", "aac", "-b:a", "192k"]
                                    else:
                                        cmd += ["-an"]  # drop audio if we can't replace it
                                elif _do_overlay:
                                    cw = int(raw_params.get("_outpaint_canvas_w", 0)) or (ox + ow)
                                    ch = int(raw_params.get("_outpaint_canvas_h", 0)) or (oy + oh)
                                    fade_top = oy > 0
                                    fade_bottom = (oy + oh) < ch
                                    fade_left = ox > 0
                                    fade_right = (ox + ow) < cw
                                    feather = 24
                                    distances = []
                                    if fade_top: distances.append("Y")
                                    if fade_bottom: distances.append("(H-Y)")
                                    if fade_left: distances.append("X")
                                    if fade_right: distances.append("(W-X)")
                                    if distances:
                                        d_min = distances[0]
                                        for d in distances[1:]:
                                            d_min = f"min({d_min},{d})"
                                        alpha_expr = (
                                            f"if(gt({d_min},{feather}),255,"
                                            f"255*{d_min}/{feather})"
                                        )
                                        filter_str = (
                                            f"[1:v]scale={ow}:{oh}:flags=lanczos,setsar=1,format=yuva420p,"
                                            f"geq=lum='lum(X,Y)':cb='cb(X,Y)':cr='cr(X,Y)':"
                                            f"a='{alpha_expr}'[s];"
                                            f"[0:v][s]overlay={ox}:{oy}:shortest=1:format=auto[outv]"
                                        )
                                    else:
                                        filter_str = (
                                            f"[1:v]scale={ow}:{oh}:flags=lanczos,setsar=1[s];"
                                            f"[0:v][s]overlay={ox}:{oy}:shortest=1[outv]"
                                        )
                                    cmd += ["-filter_complex", filter_str, "-map", "[outv]"]
                                    cmd += ["-c:v", "libx264", "-crf", "18", "-preset", "fast", "-pix_fmt", "yuv420p"]
                                    if _do_audio and src_has_audio:
                                        cmd += ["-map", "1:a:0", "-c:a", "aac", "-b:a", "192k"]
                                    else:
                                        cmd += ["-map", "0:a?", "-c:a", "copy"]
                                else:
                                    # Audio mux only — no video filter
                                    cmd += ["-map", "0:v:0", "-c:v", "copy"]
                                    if _do_audio and src_has_audio:
                                        cmd += ["-map", "1:a:0", "-c:a", "aac", "-b:a", "192k"]
                                    else:
                                        cmd += ["-map", "0:a?", "-c:a", "copy"]

                                cmd += ["-shortest", muxed_path]

                                # Skip if there's truly nothing to do
                                if not _do_trim and not _do_overlay and not (_do_audio and src_has_audio):
                                    continue

                                op_label = []
                                if _do_trim: op_label.append("smear-trim")
                                if _do_overlay: op_label.append("source-overlay")
                                if _do_audio and src_has_audio: op_label.append("source-audio")
                                op_str = "+".join(op_label) or "noop"

                                # Re-encode for sliding-window 1425-frame outputs
                                # can take 30-60s at 720p — give plenty of timeout.
                                mux_result = subprocess.run(cmd, capture_output=True, text=True, timeout=600)
                                if not (mux_result.returncode == 0 and os.path.isfile(muxed_path)):
                                    print(f"  [Outpaint {op_str}] ffmpeg failed: {mux_result.stderr[:300]}")
                                    if os.path.isfile(muxed_path):
                                        try: os.remove(muxed_path)
                                        except OSError: pass
                                    continue

                                # Try os.replace into the canonical filename.
                                replaced = False
                                last_err = None
                                for _retry in range(15):  # up to ~15s
                                    try:
                                        os.replace(muxed_path, out_video)
                                        replaced = True
                                        break
                                    except PermissionError as pe:
                                        last_err = pe
                                        gc.collect()
                                        time.sleep(1)

                                if replaced:
                                    print(f"  [Outpaint {op_str}] Applied to {fname}")
                                    continue

                                # Hard fallback: promote post-processed copy
                                # to sibling final filename, swap in
                                # new_files. UI ends up pointing at the
                                # corrected version.
                                final_name = out_video.rsplit(".", 1)[0] + "_with_source_audio." + out_video.rsplit(".", 1)[1]
                                try:
                                    os.replace(muxed_path, final_name)
                                except OSError as e:
                                    print(f"  [Outpaint {op_str}] WARN: could not finalize: {e}")
                                    if os.path.isfile(muxed_path):
                                        try: os.remove(muxed_path)
                                        except OSError: pass
                                    continue
                                try:
                                    os.remove(out_video)
                                except OSError:
                                    pass
                                final_basename = os.path.basename(final_name)
                                new_files = [f if f != fname else final_basename for f in new_files]
                                for clip_index, clip_filename in list(
                                    clip_output_files.items()
                                ):
                                    if clip_filename == fname:
                                        clip_output_files[clip_index] = final_basename
                                record_job_outputs(
                                    job,
                                    [final_basename],
                                    clip_output_files=clip_output_files,
                                )
                                _write_output_sidecars([final_basename])
                                if not update_job(job, output_files=new_files):
                                    return False
                                print(f"  [Outpaint {op_str}] Original mp4 locked ({last_err}); promoted post copy → {final_basename}")
                            except Exception as outpaint_post_err:
                                print(f"  [Outpaint] Post-process error (non-fatal): {outpaint_post_err}")

                # Recast target lock: SCAIL-2 regenerates the full frame even
                # in Replace mode, so a strong identity can leak into a nearby
                # person. Trace the actual generated replacement, match it to
                # the approved source target by overlap, and restore the source
                # everywhere outside the union of the old and new silhouettes.
                if success and raw_params.get("_recast_protect_bystanders"):
                    source_video = raw_params.get("_recast_source_video")
                    mask_video = raw_params.get("video_mask")
                    video_exts = {".mp4", ".webm", ".mkv", ".mov"}
                    candidates = [
                        name for name in new_files
                        if os.path.splitext(name)[1].lower() in video_exts
                    ]
                    if source_video and mask_video and candidates:
                        fname = candidates[-1]
                        generated_video = os.path.join(out_dir, fname)
                        protected_path = None
                        adaptive_mask_dir = None
                        try:
                            if not update_job(
                                job,
                                message="Preparing adaptive Recast protection...",
                                phase="Tracing generated replacement",
                            ):
                                return False

                            # SAM3 needs its own CUDA headroom. Recast is
                            # already rendered, so release the generation model
                            # before tracing the finished replacement. The next
                            # generation reloads it normally.
                            if (
                                getattr(wgp, "wan_model", None) is not None
                                or getattr(wgp, "offloadobj", None) is not None
                            ):
                                print("  [Recast] Releasing generation model for adaptive protection")
                                wgp.release_model()

                            import tempfile
                            adaptive_mask_dir = tempfile.mkdtemp(
                                prefix="maestro-recast-protect-",
                            )
                            protection_progress = {"bucket": -1}

                            def _adaptive_protection_progress(done, total):
                                percent = min(
                                    100,
                                    max(0, int(round(100 * float(done) / max(1, total)))),
                                )
                                bucket = percent // 5
                                if bucket == protection_progress["bucket"]:
                                    return
                                protection_progress["bucket"] = bucket
                                if not update_job(
                                    job,
                                    message=f"Tracing generated replacement... {percent}%",
                                    phase="Tracing generated replacement",
                                ):
                                    raise InterruptedError("Recast protection was cancelled")

                            adaptive_mask = _build_recast_adaptive_mask(
                                generated_video,
                                mask_video,
                                raw_params.get("edit_recast_person_count", 1),
                                adaptive_mask_dir,
                                progress_callback=_adaptive_protection_progress,
                            )
                            if not update_job(
                                job,
                                message="Protecting people outside the generated replacement...",
                                phase="Protecting surrounding people",
                            ):
                                return False
                            protected_path = _render_recast_mask_locked_video(
                                source_video, adaptive_mask, generated_video,
                            )
                            replaced = False
                            last_error = None
                            for _retry in range(15):
                                try:
                                    os.replace(protected_path, generated_video)
                                    replaced = True
                                    break
                                except PermissionError as exc:
                                    last_error = exc
                                    gc.collect()
                                    time.sleep(1)
                            if replaced:
                                print(f"  [Recast] Protected non-target pixels in {fname}")
                            else:
                                stem, extension = os.path.splitext(generated_video)
                                final_path = f"{stem}_target_locked{extension}"
                                os.replace(protected_path, final_path)
                                protected_path = None
                                final_name = os.path.basename(final_path)
                                new_files = [
                                    final_name if name == fname else name
                                    for name in new_files
                                ]
                                record_job_outputs(job, new_files)
                                if not update_job(job, output_files=new_files):
                                    return False
                                print(
                                    "  [Recast] Original output was locked "
                                    f"({last_error}); published {final_name}"
                                )
                        except InterruptedError as recast_protect_cancelled:
                            print(f"  [Recast] {recast_protect_cancelled}")
                            return False
                        except Exception as recast_protect_error:
                            print(
                                "  [Recast] Warning: target-mask protection "
                                f"failed; keeping generated frame: {recast_protect_error}"
                            )
                            traceback.print_exc()
                        finally:
                            if protected_path and os.path.isfile(protected_path):
                                try:
                                    os.remove(protected_path)
                                except OSError:
                                    pass
                            if adaptive_mask_dir:
                                import shutil
                                shutil.rmtree(adaptive_mask_dir, ignore_errors=True)

                # Post-generation FlashVSR pass — whole-file upscale on the
                # assembled video (see the pop near the top of this function
                # for why this isn't done inline per sliding window). Ordered
                # BEFORE film grain so grain lands on the upscaled pixels (the
                # inline path had the same order), and before voice clone so
                # the audio swap happens on the final video.
                if success and pp_spatial_upsampling:
                    postprocess_files = (
                        _authoritative_h3_postprocess_outputs(
                            new_files,
                            producer_artifact_roles,
                            is_multiclip=is_multiclip,
                            join_output_file=join_output_file,
                        )
                        if h3_delivery_request else [
                            name for name in new_files
                            if os.path.splitext(name)[1].lower()
                            in {".mp4", ".webm", ".mkv"}
                        ]
                    )
                    if h3_delivery_request and not postprocess_files:
                        message = "No authoritative final H3 video was available for delivery post-processing"
                        finish_job(job, "failed", error=message, message=message)
                        return False
                    if h3_delivery_request:
                        try:
                            if not update_job(
                                job,
                                message=(
                                    "Releasing H3 and preparing protected "
                                    f"{pp_delivery_resolution} delivery..."
                                ),
                                phase="Upscaling",
                            ):
                                return False
                            delivered_files = _deliver_h3_outputs_transactionally(
                                job,
                                out_dir,
                                postprocess_files,
                                pp_spatial_upsampling,
                                pp_delivery_resolution,
                                pp_delivery_fit,
                            )
                            delivery_pending = _queue_recovery_delivery_pending(job)
                            if delivery_pending is None:
                                raise QueueRecoveryRuntimeError(
                                    "Protected H3 delivery checkpoint is missing."
                                )
                            _queue_recovery_checkpoint_delivery_completed(
                                job,
                                out_dir,
                                delivered_files,
                                delivery_pending,
                            )
                        except InterruptedError:
                            return False
                        except _H3DeliveryFailure as delivery_error:
                            failure_updates = _safe_failure_updates(
                                delivery_error, job,
                            )
                            if delivery_error.oom_info:
                                failure_updates["oom_info"] = delivery_error.oom_info
                            finish_job(job, "failed", **failure_updates)
                            return False
                    else:
                        for fname in postprocess_files:
                            video_path = os.path.join(out_dir, fname)
                            try:
                                if not update_job(
                                    job,
                                    message=f"Upscaling {fname} (FlashVSR)...",
                                    phase="Upscaling",
                                ):
                                    return False
                                print(f"  [Upscale] Applying {pp_spatial_upsampling} to {fname}")
                                _apply_spatial_upsampling_to_file(
                                    video_path, pp_spatial_upsampling, job=job,
                                )
                                print(f"  [Upscale] Done: {fname}")
                            except Exception as up_err:
                                print(f"  [Upscale] Warning: failed on {fname} (keeping original): {up_err}")
                                traceback.print_exc()

                # Post-generation film grain pass (applied to output files, not during inference)
                if success and pp_film_grain_intensity > 0:
                    video_exts = {".mp4", ".webm", ".mkv"}
                    for fname in new_files:
                        ext = os.path.splitext(fname)[1].lower()
                        if ext not in video_exts:
                            continue
                        video_path = os.path.join(out_dir, fname)
                        try:
                            if not update_job(
                                job, message=f"Applying film grain to {fname}...",
                            ):
                                return False
                            print(f"  [Film Grain] Applying to {fname} (intensity={pp_film_grain_intensity}, saturation={pp_film_grain_saturation})")
                            _apply_film_grain_to_file(video_path, pp_film_grain_intensity, pp_film_grain_saturation)
                            print(f"  [Film Grain] Done: {fname}")
                        except Exception as fg_err:
                            print(f"  [Film Grain] Warning: failed on {fname}: {fg_err}")
                            traceback.print_exc()

                # Post-generation voice clone pass (SeedVC). Replaces 1 or 2
                # voices in the generated video's audio track with user-
                # supplied reference voice(s). Order matters: runs AFTER
                # film grain so the audio replacement happens on the final
                # color-graded video. Video stream is copied through (no
                # re-encode), so film grain is preserved.
                #
                # The voice-clone function leaves the video unchanged on any
                # failure (no audio track, missing refs, SeedVC failure,
                # remux failure) — it's safe to enable speculatively.
                if success and pp_voice_clone_enabled and pp_voice_clone_refs:
                    video_exts = {".mp4", ".webm", ".mkv"}
                    for fname in new_files:
                        ext = os.path.splitext(fname)[1].lower()
                        if ext not in video_exts:
                            continue
                        video_path = os.path.join(out_dir, fname)
                        try:
                            if not update_job(
                                job,
                                message=f"Voice cloning ({pp_voice_clone_mode}) on {fname}...",
                            ):
                                return False
                            print(f"  [Voice Clone] mode={pp_voice_clone_mode} refs={len(pp_voice_clone_refs)} on {fname}")
                            from postprocessing.voice_clone import apply_voice_clone_to_file
                            apply_voice_clone_to_file(
                                video_path=video_path,
                                voice_ref_paths=pp_voice_clone_refs,
                                mode=pp_voice_clone_mode,
                            )
                            print(f"  [Voice Clone] Done: {fname}")
                        except Exception as vc_err:
                            print(f"  [Voice Clone] Warning: failed on {fname}: {vc_err}")
                            traceback.print_exc()

                # Post-generation dynamic audio normalization (smooths speaker volume transitions)
                if success and raw_params.get("tts_dynaudnorm"):
                    audio_exts = {".wav", ".mp3", ".flac", ".ogg"}
                    for fname in new_files:
                        ext = os.path.splitext(fname)[1].lower()
                        if ext not in audio_exts:
                            continue
                        audio_path = os.path.join(out_dir, fname)
                        try:
                            if not update_job(
                                job, message="Smoothing speaker volumes...",
                            ):
                                return False
                            print(f"  [DynAudNorm] Applying to {fname}")
                            tmp_path = audio_path + ".dynaudnorm.wav"
                            import subprocess
                            comp_threshold = raw_params.get("tts_comp_threshold", -25)
                            comp_attack = raw_params.get("tts_comp_attack", 5)
                            comp_release = raw_params.get("tts_comp_release", 100)
                            comp_makeup = raw_params.get("tts_comp_makeup", 4)
                            result = subprocess.run(
                                ["ffmpeg", "-y", "-i", audio_path,
                                 "-af", f"acompressor=threshold={comp_threshold}dB:ratio=3:attack={comp_attack}:release={comp_release}:makeup={comp_makeup},alimiter=limit=0.95",
                                 tmp_path],
                                capture_output=True, text=True, timeout=120,
                            )
                            if result.returncode == 0 and os.path.isfile(tmp_path):
                                os.replace(tmp_path, audio_path)
                                print(f"  [DynAudNorm] Done: {fname}")
                            else:
                                print(f"  [DynAudNorm] ffmpeg failed: {result.stderr[:200]}")
                                if os.path.isfile(tmp_path):
                                    os.remove(tmp_path)
                        except Exception as dan_err:
                            print(f"  [DynAudNorm] Warning: failed on {fname}: {dan_err}")

                # Refresh sidecars after post-processing/renames. Internal
                # shot clips are deleted after shot-aware edit assembly and
                # therefore must never be published as gallery artifacts.
                if not defer_output_publication and not h3_delivery_request:
                    _write_output_sidecars(new_files)

            if success and not finalize:
                deferred_updates = {}
                if defer_output_publication:
                    deferred_updates.update({
                        "_internal_output_files": list(new_files),
                        "_internal_clip_output_files": dict(
                            clip_output_files,
                        ),
                        "_internal_join_output_file": join_output_file,
                    })
                return update_job(
                    job,
                    progress=99,
                    step=0,
                    total_steps=0,
                    phase="Finalizing",
                    message="Finalizing...",
                    **deferred_updates,
                )

            published = finish_job(
                job,
                "completed" if success else "failed",
                progress=100 if success else 0,
                step=0,
                total_steps=0,
                phase="",
                error=None if success else first_task_error,
                failure_details=None if success else first_failure_details,
                message=(
                    "Done"
                    if success
                    else (
                        f"Generation failed: {first_task_error}"
                        if first_task_error
                        else "Generation failed"
                    )
                ),
            )
            if job.get("_h3_delivery_publication"):
                if published and job.get("status") == "completed" and not is_cancel_requested(job):
                    _finalize_h3_delivery_publication(job)
                    cursor = dict(job.get("recovery_cursor") or {})
                    cursor.pop("delivery_pending", None)
                    _queue_recovery_checkpoint(
                        job,
                        recovery_cursor=cursor,
                        recovery_state="terminal",
                        reruns_denoise=False,
                    )
                else:
                    _rollback_h3_delivery_publication(job)
            if success and job.get("status") == "completed":
                # H3 still/tail handoffs and WGP preprocessing files remain
                # private until every dependent segment, concat, and delivery
                # checkpoint has completed. Retire them only at that terminal
                # boundary while preserving staging owned by all live jobs.
                live_job_ids = [
                    str(candidate.get("id") or "")
                    for candidate in list(_jobs.values())
                    if str(candidate.get("status") or "").casefold()
                    not in {"cancelled", "canceled", "completed", "failed"}
                ]
                cleanup_orphan_staged_outputs(
                    out_dir, live_job_ids, maximum_removals=128,
                )
            return success and job.get("status") == "completed"

        except Exception as e:
            traceback.print_exc()
            finish_job(job, "failed", **_safe_failure_updates(e, job))
            return False
        finally:
            if job.get("_h3_delivery_publication"):
                if job.get("status") == "completed" and not is_cancel_requested(job):
                    _finalize_h3_delivery_publication(job)
                else:
                    _rollback_h3_delivery_publication(job)
            # Required H3 continuation frames are disposable worker inputs.
            # Clean them even when decoding/concatenation raises before the
            # ordinary post-loop cleanup path.
            try:
                continuation_dir = job.get("out_dir")
                if continuation_dir and os.path.isdir(continuation_dir):
                    for filename in os.listdir(continuation_dir):
                        if filename.startswith("_continuation_") and os.path.splitext(filename)[1].lower() in {".png", ".mp4"}:
                            try:
                                os.remove(os.path.join(continuation_dir, filename))
                            except OSError:
                                pass
            except Exception:
                pass
            if abort_state is not None:
                unregister_abort_state(job_id, _active_gen_states, abort_state)
            # Restore the persisted base coefficient so the next job
            # starts from the user's auto-tuned value, not whatever
            # this job's adjustment left it at.
            _restore_base_coefficient()
            # If no other jobs are running, sync save_path to the current active
            # workspace (which may have changed while this job was running).
            if not _active_gen_states:
                active_dir = _workspace_dir()
                wgp.save_path = active_dir
                wgp.image_save_path = active_dir


def _recast_video_frame_count(video_path):
    """Return the exact decoded video-frame count for final validation."""
    import decord

    reader = decord.VideoReader(video_path)
    try:
        return int(len(reader))
    finally:
        del reader


def _write_recast_shot_aware_sidecar(
    job, output_path, shot_bundle, generation_time,
):
    """Persist restorable settings without leaking disposable shot paths."""
    import copy

    output_name = os.path.basename(output_path)
    params = copy.deepcopy(job.get("params") or {})
    for key in (
        "_defer_output_publication",
        "_recast_shot_manifest",
        "_recast_shot_temp_dir",
        "_recast_final_out_dir",
        "_recast_shot_bundle",
    ):
        params.pop(key, None)
    params["video_length"] = int(shot_bundle["frame_count"])
    params["seed"] = int(shot_bundle["resolved_seed"])
    params["edit_recast_shot_aware"] = True
    params["edit_recast_shot_plan"] = list(
        shot_bundle.get("published_shots") or [],
    )

    upload_filenames = {}
    for key in (
        "image_start", "image_end", "video_guide", "video_guide2",
        "video_guide3", "audio_guide",
        "audio_guide2", "audio_guide3", "audio_guide4",
        "audio_guide5", "audio_guide6",
    ):
        value = params.get(key)
        if isinstance(value, str) and value:
            upload_filenames[key] = os.path.basename(value)
        elif isinstance(value, list):
            upload_filenames[key] = [
                os.path.basename(item)
                if isinstance(item, str) and item else ""
                for item in value
            ]

    sidecar = {
        "params": params,
        "upload_filenames": upload_filenames,
        "generation_mode": params.get("generation_mode"),
        "job_id": job.get("id"),
        "generation_time": int(round(float(generation_time))),
        "created_at": time.time(),
        "output_filename": output_name,
    }
    meta_path = os.path.splitext(output_path)[0] + ".meta.json"
    with open(meta_path, "w", encoding="utf-8") as handle:
        json.dump(sidecar, handle, indent=2)


def _run_recast_shot_generation(job_id):
    """Generate cast-aware segments independently, then restore source audio."""
    import shutil

    job = _jobs[job_id]
    params = job.get("params") or {}
    shot_bundle = params.get("_recast_shot_bundle") or {}
    temp_dir = params.get("_recast_shot_temp_dir")
    final_out_dir = params.get("_recast_final_out_dir") or _workspace_dir(
        job.get("workspace"),
    )
    assembly_state = {"abort": False}
    final_path = None
    published = False
    started_at = time.time()

    try:
        if not _run_generation(job_id, finalize=False):
            return
        if not register_abort_state(
            job,
            job_id,
            _active_gen_states,
            assembly_state,
        ):
            return
        if not update_job(
            job,
            progress=99,
            step=0,
            total_steps=0,
            phase="Joining Recast segments",
            message="Joining cast-aware segments and restoring source audio...",
        ):
            return

        clip_outputs = job.get("_internal_clip_output_files") or {}
        ordered_paths = []
        for shot in shot_bundle.get("shots") or []:
            if shot.get("mode") == "passthrough":
                clip_path = shot.get("passthrough_path")
            else:
                raw_name = (
                    clip_outputs.get(int(shot["shot_index"]))
                    or clip_outputs.get(str(int(shot["shot_index"])))
                )
                clip_path = (
                    raw_name
                    if raw_name and os.path.isabs(raw_name)
                    else os.path.join(temp_dir or "", raw_name or "")
                )
            if not clip_path or not os.path.isfile(clip_path):
                raise RuntimeError(
                    "Recast assembly is missing generation segment "
                    f"{int(shot.get('shot_index', 0)) + 1}."
                )
            ordered_paths.append(clip_path)

        if not ordered_paths:
            raise RuntimeError("Recast shot assembly has no video segments.")

        os.makedirs(final_out_dir, exist_ok=True)
        seed = int(shot_bundle["resolved_seed"])
        timestamp = time.strftime("%Y-%m-%d-%Hh%Mm%Ss")
        extension = os.path.splitext(ordered_paths[0])[1] or ".mp4"
        final_path = wgp.get_available_filename(
            final_out_dir,
            f"{timestamp}_seed{seed}_recast_shot_aware{extension}",
        )
        source_video = params.get("_recast_source_video")
        source_audio = None
        if source_video and os.path.isfile(source_video):
            try:
                if _recast_video_has_audio(source_video):
                    source_audio = source_video
            except Exception as audio_probe_error:
                print(
                    "[Recast] Could not probe source audio; assembling "
                    f"video-only: {audio_probe_error}"
                )

        assembled = wgp.concatenate_multi_clip_videos(
            ordered_paths,
            final_path,
            source_audio,
            audio_start_sec=0.0,
            abort_callback=lambda: is_cancel_requested(job),
            pad_audio=True,
            audio_duration_sec=(
                float(shot_bundle["frame_count"])
                / float(shot_bundle["fps"])
            ),
        )
        if is_cancel_requested(job):
            if final_path and os.path.isfile(final_path):
                try:
                    os.remove(final_path)
                except OSError:
                    pass
            return
        if not assembled or not os.path.isfile(final_path):
            raise RuntimeError("Recast cast-aware assembly failed.")

        expected_frames = int(shot_bundle["frame_count"])
        actual_frames = _recast_video_frame_count(final_path)
        if actual_frames != expected_frames:
            try:
                os.remove(final_path)
            except OSError:
                pass
            raise RuntimeError(
                "Recast cast-aware assembly changed the timeline length "
                f"({actual_frames}/{expected_frames} frames)."
            )

        _write_recast_shot_aware_sidecar(
            job,
            final_path,
            shot_bundle,
            time.time() - started_at,
        )
        final_name = os.path.basename(final_path)
        job["out_dir"] = final_out_dir
        published = finish_job(
            job,
            "completed",
            output_files=[final_name],
            clip_output_files={},
            join_output_file=final_name,
            progress=100,
            step=0,
            total_steps=0,
            phase="",
            message="Done",
        )
        if not published:
            return
        print(
            "[Recast] Shot-aware assembly completed: "
            f"{len(ordered_paths)} segments, {actual_frames} frames, "
            f"{'continuous source audio' if source_audio else 'video only'}."
        )
    except Exception as error:
        traceback.print_exc()
        if not is_cancel_requested(job):
            finish_job(
                job,
                "failed",
                error=str(error),
                message=f"Recast assembly failed: {error}",
            )
    finally:
        if final_path and not published:
            for leftover in (
                final_path,
                os.path.splitext(final_path)[0] + ".meta.json",
            ):
                if os.path.isfile(leftover):
                    try:
                        os.remove(leftover)
                    except OSError:
                        pass
        unregister_abort_state(
            job_id,
            _active_gen_states,
            assembly_state,
        )
        job["out_dir"] = final_out_dir
        job.pop("_internal_output_files", None)
        job.pop("_internal_clip_output_files", None)
        job.pop("_internal_join_output_file", None)
        if isinstance(job.get("params"), dict):
            published_shots = list(
                (shot_bundle or {}).get("published_shots") or [],
            )
            if published_shots:
                job["params"]["edit_recast_shot_aware"] = True
                job["params"]["edit_recast_shot_plan"] = published_shots
            job["params"].pop("_recast_shot_manifest", None)
            job["params"].pop("_recast_shot_temp_dir", None)
            job["params"].pop("_recast_final_out_dir", None)
            job["params"].pop("_recast_shot_bundle", None)
            job["params"].pop("_defer_output_publication", None)
        if temp_dir and os.path.isdir(temp_dir):
            resolved_temp = os.path.realpath(temp_dir)
            expected_prefix = "maestro-recast-shots-"
            if os.path.basename(resolved_temp).startswith(expected_prefix):
                shutil.rmtree(resolved_temp, ignore_errors=True)


def _write_repaint_shot_aware_sidecar(
    job, output_path, shot_bundle, generation_time,
):
    """Persist mapped Repaint settings without disposable shot artifacts."""
    import copy

    output_name = os.path.basename(output_path)
    params = copy.deepcopy(job.get("params") or {})
    for key in (
        "_defer_output_publication",
        "_repaint_shot_manifest",
        "_repaint_shot_temp_dir",
        "_repaint_final_out_dir",
        "_repaint_source_video",
        "_repaint_shot_bundle",
    ):
        params.pop(key, None)
    params["video_length"] = int(shot_bundle["frame_count"])
    params["seed"] = int(shot_bundle["resolved_seed"])
    params["edit_repaint_shot_aware"] = True
    params["edit_repaint_native_scene_preservation"] = True
    params["edit_repaint_shot_plan"] = list(
        shot_bundle.get("published_shots") or [],
    )

    upload_filenames = {}
    for key in (
        "image_start", "image_end", "video_guide", "video_guide2",
        "video_guide3", "audio_guide",
        "audio_guide2", "audio_guide3", "audio_guide4",
        "audio_guide5", "audio_guide6",
    ):
        value = params.get(key)
        if isinstance(value, str) and value:
            upload_filenames[key] = os.path.basename(value)
        elif isinstance(value, list):
            upload_filenames[key] = [
                os.path.basename(item)
                if isinstance(item, str) and item else ""
                for item in value
            ]

    sidecar = {
        "params": params,
        "upload_filenames": upload_filenames,
        "generation_mode": params.get("generation_mode"),
        "job_id": job.get("id"),
        "generation_time": int(round(float(generation_time))),
        "created_at": time.time(),
        "output_filename": output_name,
    }
    meta_path = os.path.splitext(output_path)[0] + ".meta.json"
    with open(meta_path, "w", encoding="utf-8") as handle:
        json.dump(sidecar, handle, indent=2)


