def _run_outpaint_shot_generation(job_id):
    """Generate Outpaint shots independently, then join one exact timeline."""
    import shutil

    job = _jobs[job_id]
    params = job.get("params") or {}
    shot_bundle = params.get("_outpaint_shot_bundle") or {}
    temp_dir = params.get("_outpaint_shot_temp_dir")
    final_out_dir = params.get("_outpaint_final_out_dir") or _workspace_dir(
        job.get("workspace"),
    )
    assembly_state = {"abort": False}
    final_path = None
    published = False
    started_at = time.time()

    try:
        if not _run_generation(job_id, finalize=False):
            return
        if not register_abort_state(
            job,
            job_id,
            _active_gen_states,
            assembly_state,
        ):
            return
        if not update_job(
            job,
            progress=99,
            step=0,
            total_steps=0,
            phase="Joining camera shots",
            message="Joining Outpaint shots and restoring source audio...",
        ):
            return

        clip_outputs = job.get("_internal_clip_output_files") or {}
        ordered_paths = []
        for shot in shot_bundle.get("shots") or []:
            shot_index = int(shot.get("shot_index", len(ordered_paths)))
            raw_name = (
                clip_outputs.get(shot_index)
                or clip_outputs.get(str(shot_index))
            )
            clip_path = (
                raw_name
                if raw_name and os.path.isabs(raw_name)
                else os.path.join(temp_dir or "", raw_name or "")
            )
            if not clip_path or not os.path.isfile(clip_path):
                raise RuntimeError(
                    "Outpaint shot assembly is missing camera shot "
                    f"{shot_index + 1}."
                )
            expected_shot_frames = int(shot.get("frame_count") or 0)
            actual_shot_frames = _recast_video_frame_count(clip_path)
            if actual_shot_frames != expected_shot_frames:
                raise RuntimeError(
                    f"Outpaint camera shot {shot_index + 1} changed "
                    "timeline length "
                    f"({actual_shot_frames}/{expected_shot_frames} frames)."
                )
            ordered_paths.append(clip_path)

        if not ordered_paths:
            raise RuntimeError("Outpaint shot assembly has no video segments.")

        os.makedirs(final_out_dir, exist_ok=True)
        seed = int(shot_bundle["resolved_seed"])
        timestamp = time.strftime("%Y-%m-%d-%Hh%Mm%Ss")
        extension = os.path.splitext(ordered_paths[0])[1] or ".mp4"
        final_path = wgp.get_available_filename(
            final_out_dir,
            f"{timestamp}_seed{seed}_outpaint_shot_aware{extension}",
        )
        source_video = params.get("_outpaint_shot_source_video")
        source_audio = None
        if (
            shot_bundle.get("preserve_source_audio", True)
            and source_video
            and os.path.isfile(source_video)
        ):
            try:
                if _recast_video_has_audio(source_video):
                    source_audio = source_video
            except Exception as audio_probe_error:
                print(
                    "[Outpaint] Could not probe source audio; using "
                    f"generated shot audio: {audio_probe_error}"
                )

        expected_frames = int(shot_bundle["frame_count"])
        fps = float(shot_bundle["fps"])
        assembled = wgp.concatenate_multi_clip_videos(
            ordered_paths,
            final_path,
            source_audio,
            audio_start_sec=0.0,
            abort_callback=lambda: is_cancel_requested(job),
            pad_audio=bool(source_audio),
            audio_duration_sec=float(expected_frames) / fps,
        )
        if is_cancel_requested(job):
            if final_path and os.path.isfile(final_path):
                try:
                    os.remove(final_path)
                except OSError:
                    pass
            return
        if not assembled or not os.path.isfile(final_path):
            raise RuntimeError("Outpaint camera-shot assembly failed.")

        actual_frames = _recast_video_frame_count(final_path)
        if actual_frames != expected_frames:
            try:
                os.remove(final_path)
            except OSError:
                pass
            raise RuntimeError(
                "Outpaint camera-shot assembly changed the timeline length "
                f"({actual_frames}/{expected_frames} frames)."
            )

        _write_outpaint_shot_aware_sidecar(
            job,
            final_path,
            shot_bundle,
            time.time() - started_at,
        )
        final_name = os.path.basename(final_path)
        job["out_dir"] = final_out_dir
        published = finish_job(
            job,
            "completed",
            output_files=[final_name],
            clip_output_files={},
            join_output_file=final_name,
            progress=100,
            step=0,
            total_steps=0,
            phase="",
            message="Done",
        )
        if not published:
            return
        print(
            "[Outpaint] Shot-aware assembly completed: "
            f"{len(ordered_paths)} shots, {actual_frames} frames, "
            f"{'continuous source audio' if source_audio else 'generated audio'}."
        )
    except Exception as error:
        traceback.print_exc()
        if not is_cancel_requested(job):
            finish_job(
                job,
                "failed",
                error=str(error),
                message=f"Outpaint assembly failed: {error}",
            )
    finally:
        if final_path and not published:
            for leftover in (
                final_path,
                os.path.splitext(final_path)[0] + ".meta.json",
            ):
                if os.path.isfile(leftover):
                    try:
                        os.remove(leftover)
                    except OSError:
                        pass
        unregister_abort_state(
            job_id,
            _active_gen_states,
            assembly_state,
        )
        job["out_dir"] = final_out_dir
        job.pop("_internal_output_files", None)
        job.pop("_internal_clip_output_files", None)
        job.pop("_internal_join_output_file", None)
        if isinstance(job.get("params"), dict):
            published_shots = list(
                (shot_bundle or {}).get("published_shots") or [],
            )
            if published_shots:
                job["params"]["edit_outpaint_shot_aware"] = True
                job["params"]["edit_outpaint_shot_plan"] = published_shots
            for key in (
                "_outpaint_shot_manifest",
                "_outpaint_shot_temp_dir",
                "_outpaint_final_out_dir",
                "_outpaint_shot_source_video",
                "_outpaint_shot_bundle",
                "_outpaint_generation_fps",
                "_outpaint_source_frame_count",
                "_defer_output_publication",
            ):
                job["params"].pop(key, None)
        if temp_dir and os.path.isdir(temp_dir):
            resolved_temp = os.path.realpath(temp_dir)
            expected_prefix = "maestro-outpaint-shots-"
            if os.path.basename(resolved_temp).startswith(expected_prefix):
                shutil.rmtree(resolved_temp, ignore_errors=True)


def _job_eta_values(job: dict) -> tuple[int | None, int | None]:
    """Blend the H3 seed with active-phase timing, excluding cold load/holds."""
    status = str(job.get("status") or "")
    estimate = job.get("h3_estimate")
    if not isinstance(estimate, dict):
        estimate = {}
    try:
        seeded_run = float(estimate.get("seconds") or 0)
        seeded_load = float(estimate.get("model_load_seconds") or 0)
        seeded_total = seeded_run + seeded_load
    except (TypeError, ValueError):
        seeded_run = seeded_load = seeded_total = 0
    if status == "queued":
        # Queue delay is intentionally not guessed. A content-free runtime
        # estimate becomes useful only after this job owns the generation slot.
        return None, None
    if status != "running":
        return None, None
    now = time.time()
    try:
        progress = float(job.get("overall_progress", job.get("progress", 0)) or 0)
        started_at = float(job.get("started_at") or 0)
    except (TypeError, ValueError):
        progress = started_at = 0
    try:
        inactive = max(0.0, float(job.get("_eta_inactive_seconds") or 0))
    except (TypeError, ValueError):
        inactive = 0.0
    elapsed = max(0.0, now - started_at - inactive) if started_at > 0 else 0
    eta = None
    seed_remaining = None
    if seeded_run > 0 and 0 < progress < 100:
        # Once measurable generation begins, checkpoint load time is sunk.
        # Scale only the generation/postprocess estimate by work remaining.
        seed_remaining = seeded_run * (100.0 - progress) / 100.0
    elif seeded_total > 0:
        # During loading/preparation, never count down below the estimated run
        # itself merely because a cold checkpoint took longer than expected.
        seed_remaining = max(seeded_run, seeded_total - elapsed)

    live_remaining = None
    try:
        timing_started = float(job.get("_eta_progress_started_at") or 0)
        baseline_progress = float(job.get("_eta_progress_baseline") or 0)
        inactive_at_start = float(
            job.get("_eta_inactive_at_progress_start") or 0
        )
    except (TypeError, ValueError):
        timing_started = baseline_progress = inactive_at_start = 0
    progress_delta = progress - baseline_progress
    phase_active_elapsed = max(
        0.0,
        now - timing_started - max(0.0, inactive - inactive_at_start),
    ) if timing_started > 0 else 0.0
    if 0 < progress < 100 and progress_delta >= 2.0 and phase_active_elapsed >= 2.0:
        live_remaining = (
            phase_active_elapsed * (100.0 - progress) / progress_delta
        )

    if seed_remaining is not None and live_remaining is not None:
        # Early samples are noisy (especially the first H3 step). Keep the
        # calibrated seed dominant, clamp the live sample to a sane envelope,
        # and increase its weight only after meaningful measured progress.
        lower = max(1.0, seed_remaining * 0.4)
        upper = max(lower, seed_remaining * 2.5)
        bounded_live = min(upper, max(lower, live_remaining))
        live_weight = min(0.65, progress_delta / 30.0)
        eta = round(
            seed_remaining * (1.0 - live_weight)
            + bounded_live * live_weight
        )
    elif seed_remaining is not None:
        eta = round(seed_remaining)
    elif live_remaining is not None:
        eta = min(7 * 86400, round(live_remaining))
    elif started_at > 0 and 0.5 <= progress < 100:
        # Compatibility fallback for non-H3 jobs with no seed/baseline.
        eta = min(7 * 86400, round(elapsed * (100.0 - progress) / progress))
    try:
        step = float(job.get("window_step") or job.get("step") or 0)
        total = float(job.get("window_total_steps") or job.get("total_steps") or 0)
        phase_started = float(job.get("phase_started_at") or started_at or 0)
        subtask_started = float(job.get("_eta_subtask_started_at") or 0)
        subtask_baseline = float(job.get("_eta_subtask_baseline_step") or 0)
        subtask_inactive_start = float(
            job.get("_eta_subtask_inactive_at_start") or 0
        )
    except (TypeError, ValueError):
        step = total = phase_started = 0
        subtask_started = subtask_baseline = subtask_inactive_start = 0
    subtask_eta = None
    step_delta = step - subtask_baseline
    if subtask_started > 0 and 0 < step < total and step_delta > 0:
        subtask_elapsed = max(
            0.0,
            now
            - subtask_started
            - max(0.0, inactive - subtask_inactive_start),
        )
        subtask_eta = min(
            7 * 86400,
            round(subtask_elapsed * (total - step) / step_delta),
        )
    elif phase_started > 0 and 0 < step < total:
        elapsed = max(0.0, now - phase_started)
        subtask_eta = min(7 * 86400, round(elapsed * (total - step) / step))
    return eta, subtask_eta


def _public_progress_telemetry(job: dict) -> dict:
    """Return additive phase semantics without changing legacy scalars."""
    running = str(job.get("status") or "") == "running"
    return {
        "progress_indeterminate": bool(
            running and job.get("progress_indeterminate", False)
        ),
    }


_BLOCKED_QUEUE_RECOVERY_STATES = frozenset({
    "blocked", "blocked_preparation", "blocked_remote_reauth",
})
_QUEUE_RECOVERY_REASON_TEXT = {
    "attempt_limit_reached": "Recovery attempt limit reached",
    "input_missing_or_changed": "A required input is missing or changed",
    "owner_reauthentication_required": "Unlock this project to resume",
    "preparation_must_resubmit": "This preparation must be resubmitted",
    "project_missing_or_recreated": "The recovery project is missing or was recreated",
    "worker_start_failed": "The recovery worker could not be started",
}


def _queue_recovery_is_blocked(job: dict) -> bool:
    return str(job.get("recovery_state") or "") in (
        _BLOCKED_QUEUE_RECOVERY_STATES
    )


def _queue_recovery_attempt(job: dict) -> int:
    try:
        return max(
            0,
            min(MAX_RECOVERY_ATTEMPTS, int(job.get("recovery_attempt", 0) or 0)),
        )
    except (TypeError, ValueError):
        return 0


def _recovered_job_remote_project_accessible(
    job: dict,
    request: Request,
) -> bool:
    """Bind recovered remote reads/actions to the unlocked project instance."""
    if not bool(getattr(request.state, "maestro_remote", False)):
        return True
    if not job.get("_recovery_owner_digest"):
        return True
    workspace = str(job.get("workspace") or "default")
    session_id = str(getattr(request.state, "maestro_session_id", "") or "")
    with _remote_active_projects_lock:
        active_workspace = _remote_active_projects.get(session_id, "")
    if active_workspace != workspace:
        return False
    try:
        project_dir = _existing_workspace_dir(workspace)
        access = _project_access.status(workspace, project_dir, session_id)
        if not access.protected or not access.unlocked:
            return False
        if os.path.normcase(os.path.realpath(project_dir)) != os.path.normcase(
            os.path.realpath(str(job.get("out_dir") or "")),
        ):
            return False
        current_digest = _queue_recovery_existing_project_identity(project_dir)
    except (
        HTTPException, QueueRecoveryAdapterError, OSError, ValueError,
    ):
        return False
    return hmac.compare_digest(
        current_digest, str(job.get("_recovery_project_digest") or ""),
    )


def _job_owned_by_request(job: dict | None, request: Request) -> bool:
    """Preserve local legacy jobs while hiding them from remote tenants."""
    if not job:
        return False
    owner = job.get("session_id")
    recovered_owner = str(job.get("_recovery_owner_digest") or "")
    if recovered_owner:
        try:
            request_owner = owner_principal_digest(
                _session_secret(), request.state.maestro_session_id,
            )
        except ValueError:
            return False
        return (
            hmac.compare_digest(recovered_owner, request_owner)
            and _recovered_job_remote_project_accessible(job, request)
        )
    if owner == request.state.maestro_session_id:
        return True
    return owner is None and not bool(
        getattr(request.state, "maestro_remote", False)
    )


def _queue_recovery_reason_code(job: dict) -> str | None:
    if not _queue_recovery_is_blocked(job):
        return None
    attempt = _queue_recovery_attempt(job)
    if attempt >= MAX_RECOVERY_ATTEMPTS:
        return "attempt_limit_reached"
    if _queue_recovery_worker(job) is None:
        return "preparation_must_resubmit"
    explicit = str(job.get("_recovery_reason_code") or "")
    if explicit in _QUEUE_RECOVERY_REASON_TEXT:
        return explicit
    state = str(job.get("recovery_state") or "")
    if state == "blocked_preparation":
        return "preparation_must_resubmit"
    if state == "blocked_remote_reauth":
        return "owner_reauthentication_required"
    message = str(job.get("message") or "")
    return {
        "Automatic recovery attempt limit reached": "attempt_limit_reached",
        "Recovery project is missing or was recreated": (
            "project_missing_or_recreated"
        ),
        "Recovery request or input validation failed": "input_missing_or_changed",
        "Recovery worker could not be started": "worker_start_failed",
    }.get(message)


def _public_queue_recovery_metadata(job: dict) -> dict:
    """Return bounded recovery state/actions without identities or paths."""
    state = str(job.get("recovery_state") or "")
    if state not in {
        "", "blocked", "blocked_preparation", "blocked_remote_reauth",
        "cancelled", "interrupted", "restored", "retrying", "terminal",
    }:
        state = "blocked"
    blocked = state in {
        "blocked", "blocked_preparation", "blocked_remote_reauth",
    }
    reason = _queue_recovery_reason_code(job)
    attempt = _queue_recovery_attempt(job)
    safe_worker = _queue_recovery_worker(job) is not None
    actions = []
    if attempt < MAX_RECOVERY_ATTEMPTS and safe_worker:
        if state == "blocked_remote_reauth" and reason == (
            "owner_reauthentication_required"
        ):
            actions = ["resume"]
        elif state == "blocked" and reason in {
            "input_missing_or_changed", "worker_start_failed",
        }:
            actions = ["retry"]
    return {
        "recovery_state": state or None,
        "recovery_interrupted": state == "interrupted",
        "recovery_blocked": blocked,
        "recovery_attempt": attempt,
        "recovery_attempt_limit": MAX_RECOVERY_ATTEMPTS,
        "recovery_reruns_denoise": bool(job.get("reruns_denoise", False)),
        "recovery_reason": reason,
        "recovery_reason_text": _QUEUE_RECOVERY_REASON_TEXT.get(reason),
        "recovery_actionable": bool(actions),
        "recovery_actions": actions,
    }


def _queue_wait_reason_for_job(job: dict) -> str | None:
    """Explain a queue wait without revealing another session's job details."""
    generation_busy = _gen_lock.locked()
    owner = job.get("session_id")
    active_other_user = False
    if generation_busy and owner is not None:
        active_other_user = any(
            candidate is not job
            and candidate.get("status") == "running"
            and candidate.get("session_id") is not None
            and candidate.get("session_id") != owner
            for candidate in _jobs.values()
        )
    return queue_wait_reason(
        job,
        generation_busy=generation_busy,
        active_other_user=active_other_user,
    )


def _public_queue_residency_metadata(
    job: dict,
    *,
    remote: bool = False,
) -> dict:
    """Return bounded, owner-safe scheduling facts without opaque keys."""
    reason = str(job.get("queue_reorder_reason") or "")
    if reason not in {
        "queue_order", "resident_base", "resident_affinity", "starvation_guard",
    }:
        reason = ""

    def bounded_int(name: str, maximum: int) -> int:
        try:
            return max(0, min(maximum, int(job.get(name, 0) or 0)))
        except (TypeError, ValueError):
            return 0

    bypassed_waiters = bounded_int(
        "queue_residency_bypassed_waiters", 10_000,
    )
    return {
        "queue_reorder_reason": reason or None,
        "queue_residency_bypass_count": (
            int(bounded_int("queue_residency_bypass_count", 2) > 0)
            if remote else bounded_int("queue_residency_bypass_count", 2)
        ),
        "queue_residency_bypassed_waiters": (
            int(bypassed_waiters > 0) if remote else bypassed_waiters
        ),
    }


def _set_recovery_no_store(response: Response) -> None:
    response.headers["Cache-Control"] = "private, no-store"
    response.headers["Pragma"] = "no-cache"


@api.get("/api/v1/status/{job_id}")
def get_status(job_id: str, request: Request, response: Response):
    """Get generation job status."""
    _set_recovery_no_store(response)
    if job_id not in _jobs:
        raise HTTPException(status_code=404, detail="Job not found")
    if not _job_owned_by_request(_jobs[job_id], request):
        raise HTTPException(status_code=404, detail="Job not found")
    j = snapshot_job(_jobs[job_id])
    recovery_blocked = _queue_recovery_is_blocked(j)
    eta_seconds, subtask_eta_seconds = _job_eta_values(j)
    return {
        "job_id": j["id"],
        "status": j["status"],
        "progress": j["progress"],
        "step": j.get("step", 0),
        "total_steps": j.get("total_steps", 0),
        "phase": j.get("phase", ""),
        "message": j["message"],
        "output_files": j["output_files"],
        "error": j["error"],
        "failure_details": j.get("failure_details"),
        # Present only on failed jobs that look like CUDA OOMs. UI
        # renders the OOM recovery banner when this is non-null.
        "oom_info": j.get("oom_info"),
        "prompt_preview": j.get("prompt_preview", ""),
        "model_type": j.get("model_type", ""),
        "generation_mode": j.get("generation_mode", ""),
        "workspace": j.get("workspace", "default"),
        "window_current": j.get("window_current", 0),
        "window_total": j.get("window_total", 0),
        "window_step": j.get("window_step", 0),
        "window_total_steps": j.get("window_total_steps", 0),
        "window_progress": j.get("window_progress", 0),
        "overall_progress": j.get("overall_progress", j.get("progress", 0)),
        "active_window_prompt": j.get("active_window_prompt", ""),
        "clip_current": j.get("clip_current", 0),
        "clip_total": j.get("clip_total", 0),
        "clip_progress": j.get("clip_progress", 0),
        "h3_segment_plan": j.get("h3_segment_plan"),
        "current_segment_model": j.get("current_segment_model", ""),
        "current_segment_reason": j.get("current_segment_reason", ""),
        "current_segment_boundary": j.get("current_segment_boundary"),
        "queue_priority": j.get("queue_priority", 0),
        "queue_held": bool(j.get("queue_held", False)),
        "hold_after_output": bool(j.get("hold_after_output", False)),
        "queue_position": (
            None if recovery_blocked else queue_position(_jobs[job_id])
        ),
        "queue_wait_reason": (
            None if recovery_blocked
            else _queue_wait_reason_for_job(_jobs[job_id])
        ),
        **_public_queue_residency_metadata(
            j, remote=bool(getattr(request.state, "maestro_remote", False)),
        ),
        "requested_outputs": j.get("requested_outputs", 1),
        "produced_outputs": len(j.get("output_files") or []),
        "eta_seconds": None if recovery_blocked else eta_seconds,
        "subtask_eta_seconds": (
            None if recovery_blocked else subtask_eta_seconds
        ),
        **_public_progress_telemetry(j),
        "h3_estimate": None if recovery_blocked else j.get("h3_estimate"),
        "estimate_after_resume": (
            j.get("h3_estimate") if recovery_blocked else None
        ),
        "events": job_events(_jobs[job_id], 100),
        "queue": queue_control_state(),
        **_public_queue_recovery_metadata(j),
    }


@api.post("/api/v1/cancel/{job_id}")
def cancel_job(job_id: str, request: Request, response: Response):
    """Cancel a queued or running generation job."""
    _set_recovery_no_store(response)
    if job_id not in _jobs:
        raise HTTPException(status_code=404, detail="Job not found")
    if not _job_owned_by_request(_jobs[job_id], request):
        raise HTTPException(status_code=404, detail="Job not found")

    job = _jobs[job_id]
    result = request_cancel(
        job,
        job_id=job_id,
        active_states=_active_gen_states,
    )
    if result.abort_signalled:
        print(f"[Cancel] Signalling abort for job {job_id}")
    return {"status": job["status"], "was_running": result.was_running}


@api.get("/api/v1/jobs")
def list_jobs(request: Request, response: Response):
    """List all active/recent jobs for reconnection after browser refresh."""
    _set_recovery_no_store(response)
    active = []
    for job in list(_jobs.values()):
        if not _job_owned_by_request(job, request):
            continue
        j = snapshot_job(job)
        if j["status"] in ("queued", "running", "failed", "cancelled"):
            recovery_blocked = _queue_recovery_is_blocked(j)
            eta_seconds, subtask_eta_seconds = _job_eta_values(j)
            active.append({
                "job_id": j["id"],
                "status": j["status"],
                "progress": j["progress"],
                "step": j.get("step", 0),
                "total_steps": j.get("total_steps", 0),
                "phase": j.get("phase", ""),
                "message": j["message"],
                "output_files": j["output_files"],
                "error": j["error"],
                "failure_details": j.get("failure_details"),
                "oom_info": j.get("oom_info"),
                "created_at": j.get("created_at", 0),
                "prompt_preview": j.get("prompt_preview", ""),
                "model_type": j.get("model_type", ""),
                "generation_mode": j.get("generation_mode", ""),
                "workspace": j.get("workspace", "default"),
                "window_current": j.get("window_current", 0),
                "window_total": j.get("window_total", 0),
                "window_step": j.get("window_step", 0),
                "window_total_steps": j.get("window_total_steps", 0),
                "window_progress": j.get("window_progress", 0),
                "overall_progress": j.get("overall_progress", j.get("progress", 0)),
                "active_window_prompt": j.get("active_window_prompt", ""),
                "clip_current": j.get("clip_current", 0),
                "clip_total": j.get("clip_total", 0),
                "clip_progress": j.get("clip_progress", 0),
                "h3_segment_plan": j.get("h3_segment_plan"),
                "current_segment_model": j.get("current_segment_model", ""),
                "current_segment_reason": j.get("current_segment_reason", ""),
                "current_segment_boundary": j.get("current_segment_boundary"),
                "queue_priority": j.get("queue_priority", 0),
                "queue_held": bool(j.get("queue_held", False)),
                "hold_after_output": bool(j.get("hold_after_output", False)),
                "queue_position": (
                    None if recovery_blocked else queue_position(job)
                ),
                "queue_wait_reason": (
                    None if recovery_blocked else _queue_wait_reason_for_job(job)
                ),
                **_public_queue_residency_metadata(
                    j,
                    remote=bool(getattr(request.state, "maestro_remote", False)),
                ),
                "requested_outputs": j.get("requested_outputs", 1),
                "produced_outputs": len(j.get("output_files") or []),
                "eta_seconds": None if recovery_blocked else eta_seconds,
                "subtask_eta_seconds": (
                    None if recovery_blocked else subtask_eta_seconds
                ),
                **_public_progress_telemetry(j),
                "h3_estimate": (
                    None if recovery_blocked else j.get("h3_estimate")
                ),
                "estimate_after_resume": (
                    j.get("h3_estimate") if recovery_blocked else None
                ),
                "events": job_events(job, 100),
                **_public_queue_recovery_metadata(j),
            })
    active.sort(key=lambda x: x["created_at"])
    return {"jobs": active, "queue": queue_control_state()}


def _require_owned_job(job_id: str, request: Request) -> dict:
    job = _jobs.get(job_id)
    if not _job_owned_by_request(job, request):
        raise HTTPException(status_code=404, detail="Job not found")
    return job


def _require_generic_queue_control_job(
    job_id: str,
    request: Request,
) -> dict:
    """Keep blocked recovery jobs immutable outside recovery endpoints."""
    job = _require_owned_job(job_id, request)
    if _queue_recovery_is_blocked(job):
        raise HTTPException(
            status_code=409,
            detail="Use an available recovery action for this blocked job",
        )
    return job


def _require_h3_delivery_recovery_job(
    job_id: str,
    request: Request,
    workspace: str = "",
) -> dict:
    """Return one owner/project-scoped retained-native source or opaque 404."""
    job = _jobs.get(job_id)
    if not _job_owned_by_request(job, request):
        raise HTTPException(status_code=404, detail="Job not found")
    expected_workspace = str(job.get("workspace") or "default")
    if workspace and workspace != expected_workspace:
        raise HTTPException(status_code=404, detail="Job not found")
    try:
        # Recovery must never create a missing local project as a side effect
        # of an authorization probe. All access denials share one opaque shape.
        out_dir = _existing_workspace_dir(expected_workspace)
        status = _project_access.status(
            expected_workspace, out_dir, request.state.maestro_session_id,
        )
        remote = bool(getattr(request.state, "maestro_remote", False))
        if (remote and not status.protected) or not status.unlocked:
            raise HTTPException(status_code=404, detail="Job not found")
    except Exception as error:
        raise HTTPException(status_code=404, detail="Job not found") from error
    if os.path.normcase(os.path.realpath(out_dir)) != os.path.normcase(
        os.path.realpath(str(job.get("out_dir") or "")),
    ):
        raise HTTPException(status_code=404, detail="Job not found")
    return job


@api.get("/api/v1/jobs/{job_id}/delivery-recovery")
def get_h3_delivery_recovery(
    job_id: str,
    request: Request,
    response: Response,
    workspace: str = "",
):
    _set_recovery_no_store(response)
    job = _require_h3_delivery_recovery_job(job_id, request, workspace)
    with _h3_delivery_recovery_lock:
        public = _public_h3_delivery_recovery(job)
    if not public.get("recoverable") and not public.get("completed_recovery_job_id"):
        raise HTTPException(status_code=404, detail="Job not found")
    return {"source_job_id": job_id, **public}


def _new_h3_delivery_recovery_job(source_job: dict, action: str) -> dict:
    params = source_job.get("params") or {}
    recovery = source_job.get("_h3_delivery_recovery") or {}
    job_id = uuid.uuid4().hex[:8]
    return {
        "id": job_id,
        "status": "queued",
        "progress": 0,
        "step": 0,
        "total_steps": 0,
        "phase": "",
        "message": "Queued (H3 delivery recovery)",
        "created_at": time.time(),
        "params": {
            "model_type": str(params.get("model_type") or ""),
            "generation_mode": "video",
            "_h3_delivery_recovery_action": action,
        },
        "output_files": [],
        "error": None,
        "workspace": str(source_job.get("workspace") or "default"),
        "out_dir": str(source_job.get("out_dir") or ""),
        "session_id": source_job.get("session_id"),
        "access_policy": dict(source_job.get("access_policy") or {}),
        "private": bool(source_job.get("private", False)),
        "explicit": bool(source_job.get("explicit", False)),
        "source_remote": bool(source_job.get("source_remote", False)),
        "prompt_preview": "",
        "model_type": str(params.get("model_type") or ""),
        "generation_mode": "video",
        "requested_outputs": len(recovery.get("staged") or []),
        "_h3_delivery_recovery_source_job": str(source_job.get("id") or ""),
        "_h3_delivery_recovery_action": action,
    }


async def _schedule_h3_delivery_recovery(
    job_id: str,
    action: str,
    request: Request,
) -> dict:
    try:
        body = await request.json()
    except Exception:
        body = {}
    workspace = str(body.get("workspace") or "")
    capability = str(body.get("capability") or "")
    source_job = _require_h3_delivery_recovery_job(
        job_id, request, workspace,
    )
    workspace_name = str(source_job.get("workspace") or "default")
    reserved = False
    recovery_job = None
    recovery_job_id = ""
    try:
        _begin_workspace_operation(workspace_name)
        reserved = True
        with _h3_delivery_recovery_lock:
            recovery = _h3_delivery_recovery_state(source_job)
            if recovery is None or recovery.get("active_job_id"):
                raise HTTPException(status_code=404, detail="Job not found")
            expected = _h3_delivery_recovery_token(source_job, action)
            if not capability or not hmac.compare_digest(capability, expected):
                raise HTTPException(status_code=404, detail="Job not found")
            if action == "retry_delivery":
                count = max(0, int(recovery.get("manual_retry_count") or 0))
                limit = max(0, int(recovery.get("manual_retry_limit") or 0))
                if count >= limit:
                    raise HTTPException(status_code=404, detail="Job not found")
            elif action != "accept_native":
                raise HTTPException(status_code=404, detail="Job not found")
            recovery_job = _new_h3_delivery_recovery_job(source_job, action)
            recovery_job_id = recovery_job["id"]
            recovery_job["_h3_delivery_workspace_reserved"] = True
            recovery["active_job_id"] = recovery_job_id
            # Every accepted schedule is one-shot, including accept-native.
            recovery["nonce"] = uuid.uuid4().hex
            _jobs[recovery_job_id] = recovery_job
        thread = threading.Thread(
            target=_run_h3_delivery_recovery_job,
            args=(recovery_job_id,), daemon=False,
            name=f"h3-delivery-recovery-{recovery_job_id}",
        )
        thread.start()
        reserved = False  # worker owns the reservation now
    except HTTPException as error:
        raise HTTPException(status_code=404, detail="Job not found") from error
    except Exception as error:
        with _h3_delivery_recovery_lock:
            recovery = source_job.get("_h3_delivery_recovery") or {}
            if str(recovery.get("active_job_id") or "") == recovery_job_id:
                recovery["active_job_id"] = ""
                recovery["nonce"] = uuid.uuid4().hex
            if recovery_job_id:
                _jobs.pop(recovery_job_id, None)
        raise HTTPException(status_code=503, detail="Recovery could not be scheduled") from error
    finally:
        if reserved:
            if isinstance(recovery_job, dict):
                recovery_job["_h3_delivery_workspace_reserved"] = False
            _end_workspace_operation(workspace_name)
    return {
        "source_job_id": job_id,
        "job_id": recovery_job_id,
        "status": "queued",
        "action": action,
        "reruns_denoise": False,
        "mutates_machine_settings": False,
    }


