@api.post("/api/v1/queue/{job_id}/output-count")
async def set_job_output_count(
    job_id: str, request: Request, response: Response,
):
    """Edit queued output count or a live repeat-capable generation."""
    _set_recovery_no_store(response)
    job = _require_generic_queue_control_job(job_id, request)
    body = await request.json()
    try:
        count = int(body.get("count"))
    except (TypeError, ValueError):
        raise HTTPException(status_code=400, detail="count must be an integer")
    if count < 1 or count > 25:
        raise HTTPException(status_code=400, detail="count must be between 1 and 25")
    if bool(job.get("_h3_turbo_validation_authorized", False)) and count != 1:
        raise HTTPException(
            status_code=409,
            detail="Synthetic H3 validation jobs always produce one output.",
        )
    if not update_requested_outputs(
        job,
        count,
        active_state=_active_gen_states.get(job_id),
    ):
        detail = (
            "A running segmented H3 chain cannot change variants safely; "
            "edit its output count while it is queued"
            if job.get("status") == "running"
            and isinstance((job.get("params") or {}).get("_h3_longform"), dict)
            else "Output count can only be changed while queued or before the current repeat finishes"
        )
        raise HTTPException(status_code=409, detail=detail)
    return {
        "job_id": job_id,
        "requested_outputs": job.get("requested_outputs", count),
        "produced_outputs": len(job.get("output_files") or []),
    }


