# ============================================================================
# API Routes: Favorites
# ============================================================================

_GALLERY_MEDIA_EXTENSIONS = {
    ".mp4", ".webm", ".mkv", ".mov", ".gif",
    ".png", ".jpg", ".jpeg", ".webp",
    ".wav", ".mp3", ".flac", ".ogg",
}


def _favorites_path(workspace: str | None = None) -> str:
    """Path to favorites JSON for the selected (or active) workspace."""
    return os.path.join(_workspace_dir(workspace), ".favorites.json")


def _load_favorites(workspace: str | None = None) -> set:
    """Load favorites for the selected (or active) workspace."""
    from services.win_safe_files import favorites_lock
    fp = _favorites_path(workspace)
    if os.path.isfile(fp):
        try:
            with favorites_lock:
                with open(fp, "r", encoding="utf-8") as f:
                    data = json.load(f)
            return set(data) if isinstance(data, list) else set()
        except Exception:
            pass
    return set()


def _save_favorites(favs: set, workspace: str | None = None):
    """Save favorites for the selected (or active) workspace.

    favorites_lock (shared with director_pipeline's delete sweep, which
    rewrites the same file) serializes read-modify-write cycles so a
    concurrent pipeline delete can't be clobbered by a stale write."""
    from services.win_safe_files import favorites_lock
    fp = _favorites_path(workspace)
    with favorites_lock:
        with open(fp, "w", encoding="utf-8") as f:
            json.dump(sorted(favs), f)


@api.get("/api/v1/favorites")
def list_favorites(request: Request, workspace: str = ""):
    """List only authorized favorites in one project."""
    if workspace == "__uploads__":
        return {"favorites": []}
    selected_workspace = _request_project_workspace(request, workspace)
    out_dir = _require_project_access(request, selected_workspace)
    sidecars = load_media_sidecars(out_dir)
    visible = [
        name for name in _load_favorites(selected_workspace)
        if os.path.isfile(os.path.join(out_dir, name))
        and not (
            os.path.isfile(os.path.join(
                out_dir, os.path.splitext(name)[0] + ".meta.json",
            ))
            and sidecars.get(name) is None
        )
        and can_access_output(sidecars.get(name), request.state.maestro_session_id)
    ]
    return {"favorites": sorted(visible)}


@api.post("/api/v1/favorites/{name}")
def toggle_favorite(request: Request, name: str, workspace: str = ""):
    """Toggle favorite status for a file. Returns new state."""
    from services.win_safe_files import favorites_lock
    # Hold across the whole read-modify-write so a concurrent pipeline
    # delete sweep can't be clobbered by this stale set (RLock — the
    # load/save helpers re-acquire internally).
    if workspace == "__uploads__":
        raise HTTPException(
            status_code=400,
            detail="Uploads cannot be favorited",
        )
    selected_workspace = _request_project_workspace(request, workspace)
    with _reserve_workspace_operations(selected_workspace):
        _require_authorized_output(request, selected_workspace, name)
        with favorites_lock:
            favs = _load_favorites(selected_workspace)
            if name in favs:
                favs.discard(name)
                is_fav = False
            else:
                favs.add(name)
                is_fav = True
            _save_favorites(favs, selected_workspace)
    return {"name": name, "workspace": selected_workspace, "favorite": is_fav}


from services.search_index import (
    ArtifactScope,
    artifact_lineage,
    artifact_matches_scope,
    classify_gallery_artifacts,
    linked_component_names,
    load_media_sidecars,
)


def _output_revision(
    filepath: str,
    out_dir: str,
    name: str,
    *,
    metadata_path: str | None = None,
) -> str:
    """Stable-enough identity for one media file plus its access sidecar."""
    revision_parts = []
    metadata_path = metadata_path or os.path.join(
        out_dir, os.path.splitext(name)[0] + ".meta.json",
    )
    for revision_path in (filepath, metadata_path):
        try:
            revision_stat = os.stat(revision_path)
            revision_parts.append(
                f"{revision_stat.st_mtime_ns:x}-{revision_stat.st_size:x}"
            )
        except (FileNotFoundError, OSError):
            revision_parts.append("0-0")
    return ".".join(revision_parts)


_output_share_revision_cache_lock = threading.RLock()
_output_share_revision_cache: dict[tuple, str] = {}


def _output_share_revision(
    filepath: str,
    out_dir: str,
    name: str,
    *,
    metadata_path: str | None = None,
) -> str:
    """Return a content identity for one shared media revision.

    Gallery refreshes use the inexpensive stat token above.  Public bearer
    links need a stronger invariant: replacing bytes while preserving a name,
    size, and timestamp must not make an old link serve new content.  Cache by
    inode/change-time metadata so range requests do not re-hash a large video;
    normal replacement or sidecar mutation invalidates the cache key.
    """
    metadata_path = metadata_path or os.path.join(
        out_dir, os.path.splitext(name)[0] + ".meta.json",
    )

    def stat_key(path: str) -> tuple | None:
        try:
            value = os.stat(path)
        except (FileNotFoundError, OSError):
            return None
        return (
            int(value.st_dev), int(value.st_ino), int(value.st_size),
            int(value.st_mtime_ns), int(value.st_ctime_ns),
        )

    cache_key = (
        os.path.realpath(filepath), stat_key(filepath),
        os.path.realpath(metadata_path), stat_key(metadata_path),
    )
    if cache_key[1] is None:
        raise FileNotFoundError(filepath)
    with _output_share_revision_cache_lock:
        cached = _output_share_revision_cache.get(cache_key)
    if cached is not None:
        return cached

    digest = hashlib.sha256()
    for label, path in ((b"media\0", filepath), (b"sidecar\0", metadata_path)):
        digest.update(label)
        try:
            size = os.path.getsize(path)
            digest.update(size.to_bytes(16, "big", signed=False))
            with open(path, "rb") as handle:
                while True:
                    chunk = handle.read(1024 * 1024)
                    if not chunk:
                        break
                    digest.update(chunk)
        except FileNotFoundError:
            digest.update(b"missing\0")
    revision = f"sha256:{digest.hexdigest()}"
    with _output_share_revision_cache_lock:
        if len(_output_share_revision_cache) >= 256:
            _output_share_revision_cache.clear()
        _output_share_revision_cache[cache_key] = revision
    return revision


@api.get("/api/v1/outputs")
def list_outputs(
    request: Request,
    limit: int = 0,
    offset: int = 0,
    favorites_only: bool = False,
    multiclip_only: bool = False,
    search: str = "",
    workspace: str = "",
    artifact_scope: ArtifactScope = ArtifactScope.FINAL,
    media_type: str = "",
):
    """List generated output files (newest first) from the active workspace.

    Supports pagination via limit/offset query params.
    Returns {outputs, total} where total is the full count before pagination.
    When limit=0 (default), returns all items (backwards compatible).

    workspace="__uploads__" lists the uploads folder instead (the gallery's
    virtual "Uploads" view) so user-supplied media can be previewed and
    reused. Browse-only: the server-side active workspace is untouched and
    generations never save here. Upload access sidecars are fail-closed:
    missing, malformed, and foreign-session uploads are omitted.
    """
    if workspace == "__uploads__":
        out_dir = os.path.join(os.getcwd(), "uploads")
        selected_workspace = "__uploads__"
    else:
        selected_workspace = _request_project_workspace(request, workspace)
        out_dir = _require_project_access(request, selected_workspace)
    if not os.path.isdir(out_dir):
        return {"outputs": [], "total": 0}

    media_exts = _GALLERY_MEDIA_EXTENSIONS
    video_exts = {".mp4", ".webm", ".mkv", ".mov", ".gif"}
    audio_exts = {".wav", ".mp3", ".flac", ".ogg"}

    # Uploads are a virtual browse scope, not an output project. Treat
    # favorites as inert here so listing cannot create
    # ``outputs/__uploads__/.favorites.json`` or consult project state.
    favs = (
        set()
        if selected_workspace == "__uploads__"
        else _load_favorites(selected_workspace)
    )

    # Build a quick listing with mtime — avoid reading JSON for every file
    # We only read sidecar JSON for files in the visible page
    raw_entries = []
    for name in os.listdir(out_dir):
        if name.startswith(".trash_") or name.startswith("."):
            continue
        filepath = os.path.join(out_dir, name)
        if not os.path.isfile(filepath):
            continue
        ext = os.path.splitext(name)[1].lower()
        if ext not in media_exts:
            continue
        raw_entries.append((name, filepath, ext, os.path.getmtime(filepath)))

    # Sort by creation time (newest first) before any filtering
    raw_entries.sort(key=lambda e: e[3], reverse=True)

    # First pass: read sidecar JSON ONCE per file and cache the bits we need
    # downstream (clip group info, generation_mode, edit_sub_mode). Files
    # without a sidecar simply have no entry in the cache. We previously read
    # sidecars in two separate passes (once for clip groups, once for mode);
    # consolidating saves disk I/O and keeps the mode/edit_sub_mode populated
    # for ALL files — the prior code only set `mode` when a multi-clip group
    # existed, which meant the gallery's Edits filter never had data to
    # filter on for non-multiclip outputs.
    media_names = {entry[0] for entry in raw_entries}
    sidecar_cache = load_media_sidecars(out_dir, media_names)
    upload_access_cache = {}
    if workspace == "__uploads__":
        session_id = request.state.maestro_session_id
        raw_entries = [
            entry for entry in raw_entries
            if can_access_upload(entry[1], session_id)
        ]
        media_names = {entry[0] for entry in raw_entries}
        upload_access_cache = {
            name: metadata
            for name in media_names
            if (metadata := read_upload_access_sidecar(
                os.path.join(out_dir, name),
            )) is not None
        }
    else:
        session_id = request.state.maestro_session_id
        raw_entries = [
            entry for entry in raw_entries
            if not (
                os.path.isfile(os.path.join(
                    out_dir, os.path.splitext(entry[0])[0] + ".meta.json",
                ))
                and sidecar_cache.get(entry[0]) is None
            )
            and can_access_output(sidecar_cache.get(entry[0]), session_id)
        ]
        media_names = {entry[0] for entry in raw_entries}
        sidecar_cache = {
            name: meta for name, meta in sidecar_cache.items()
            if name in media_names
        }
    if workspace == "__uploads__":
        artifact_classes = {name: "final" for name in media_names}
    else:
        artifact_entries = []
        for name, filepath, ext, mtime in raw_entries:
            try:
                size = os.path.getsize(filepath)
            except (FileNotFoundError, OSError):
                size = 0
            artifact_entries.append({
                "name": name,
                "meta": sidecar_cache.get(name) or {},
                "size": size,
                "created_at": mtime,
            })
        artifact_classes = classify_gallery_artifacts(artifact_entries)

    # Counts must use the exact destructive-authorization policy. Display
    # classification intentionally accepts legacy filename hints; presenting
    # those as cleanable would promise a cascade that the safe delete endpoint
    # correctly refuses to perform.
    component_counts = {
        name: len(linked_component_names(name, sidecar_cache, artifact_classes))
        for name in media_names
        if artifact_classes.get(name) == "final"
    }

    # Second pass: build the file list using the cached sidecar data.
    files = []
    for name, filepath, ext, mtime in raw_entries:
        ftype = "video" if ext in video_exts else ("audio" if ext in audio_exts else "image")
        cached = (
            upload_access_cache.get(name)
            if workspace == "__uploads__"
            else sidecar_cache.get(name)
        ) or {}
        params = cached.get("params") if isinstance(cached.get("params"), dict) else {}
        mode = cached.get("generation_mode")
        edit_sub_mode = params.get("edit_sub_mode")
        artifact_class = artifact_classes.get(name, "final")
        if not artifact_matches_scope(artifact_class, artifact_scope):
            continue
        # The file may vanish between os.scandir() and here (temp files renamed
        # mid-generation, etc.). Skip the entry rather than crashing the endpoint.
        try:
            size = os.path.getsize(filepath)
        except (FileNotFoundError, OSError):
            continue
        # A basename is not a stable gallery identity: the media may be
        # replaced in place, and its sidecar is commonly written a moment
        # later.  Surface a cheap revision token so clients can invalidate
        # inline/selected metadata without polling every sidecar separately.
        revision = (
            _output_revision(filepath, out_dir, name)
            if workspace != "__uploads__"
            else _output_revision(
                filepath, out_dir, name,
                metadata_path=f"{filepath}.access.json",
            )
        )
        files.append({
            "name": name,
            "type": ftype,
            "mode": mode,
            # Surface edit_sub_mode so the gallery's Edits filter can
            # identify retake/inpaint/outpaint/restyle/edit_anything outputs.
            "edit_sub_mode": edit_sub_mode,
            "artifact_class": artifact_class,
            "linked_component_count": component_counts.get(name, 0),
            "favorite": name in favs,
            "size": size,
            "created_at": mtime,
            "revision": revision,
            "workspace": selected_workspace,
            **public_output_policy(cached),
            "url": (
                f"/api/v1/file/{quote(name, safe='')}"
                f"?workspace={quote(selected_workspace, safe='')}"
            ),
        })

    # Compose every filter before pagination. Previously favorites/multiclip
    # returned early, silently ignoring search and any later predicate.
    if favorites_only:
        files = [f for f in files if f["favorite"]]
    if multiclip_only:
        # 1. Explicit multiclip files
        multiclips = [f for f in files if "multiclip" in f["name"].lower() and f["type"] == "video"]
        multiclip_names = {f["name"] for f in multiclips}

        # 2. Sliding-window finals identified by sidecar settings, not a broad
        # filename grouping that could merge separate same-prompt generations.
        sw_finals = []
        for f in files:
            if f["type"] != "video" or f["name"] in multiclip_names:
                continue
            meta = sidecar_cache.get(f["name"]) or {}
            params = meta.get("params") if isinstance(meta.get("params"), dict) else {}
            try:
                is_sliding = int(params.get("video_length") or 0) > int(
                    params.get("sliding_window_size") or 0
                ) > 0
            except (TypeError, ValueError):
                is_sliding = False
            if is_sliding and f["artifact_class"] == "final":
                sw_finals.append(f)

        combined = multiclips + sw_finals
        combined.sort(key=lambda f: f["created_at"], reverse=True)
        files = combined
    if search:
        from services.search_index import get_search_index
        idx = get_search_index()
        matching_names = idx.search(search, out_dir)
        # Combine index results with filename fallback (in case index missed
        # a file that was created between index builds)
        query_lower = search.lower()
        files = [f for f in files if f["name"] in matching_names or query_lower in f["name"].lower()]

    normalized_media_type = str(media_type or "").strip().lower()
    if normalized_media_type == "images":
        files = [f for f in files if f["type"] == "image"]
    elif normalized_media_type == "videos":
        files = [f for f in files if f["type"] == "video"]
    elif normalized_media_type == "audio":
        files = [f for f in files if f["type"] == "audio"]
    elif normalized_media_type in {"avatars", "edits"}:
        files = [
            f for f in files
            if f.get("edit_sub_mode") or f.get("mode") == "avatar"
        ]

    total = len(files)
    if limit > 0:
        files = files[offset:offset + limit]
    return {"outputs": files, "total": total}


@api.get("/api/v1/file/{filename:path}")
def serve_file(request: Request, filename: str, workspace: str = ""):
    """Serve one authorized output from one explicitly scoped project.

    Uses share_delete_file_response so that on Windows the file can be
    deleted/renamed by the gallery delete button even while the browser
    is actively streaming it (e.g. mid-video playback). Without share-
    delete, Python's default open() locks the file for delete and the
    user has to close the entire app to clean up.
    """
    from services.win_safe_files import (
        is_safe_direct_basename,
        safe_direct_file_under,
        share_delete_file_response,
    )
    if not is_safe_direct_basename(filename) or filename.startswith("."):
        raise HTTPException(status_code=400, detail="Invalid output name")
    selected_workspace = _request_project_workspace(request, workspace)
    if selected_workspace == "__uploads__":
        filepath = safe_direct_file_under(
            os.path.join(os.getcwd(), "uploads"), filename,
        )
        if (
            filepath
            and os.path.isfile(filepath)
            and can_access_upload(filepath, request.state.maestro_session_id)
        ):
            return share_delete_file_response(filepath)
        raise HTTPException(status_code=404, detail="File not found")
    try:
        _, filepath, _ = _require_authorized_output(
            request, selected_workspace, filename,
        )
    except HTTPException as error:
        if error.status_code == 404:
            raise HTTPException(status_code=404, detail="File not found") from error
        raise
    return share_delete_file_response(filepath)


@api.get("/api/v1/outputs/{name}/metadata")
def get_output_metadata(request: Request, name: str, workspace: str = ""):
    """Get metadata for an output file. Tries sidecar first, then embedded."""
    selected_workspace = _request_project_workspace(request, workspace)
    out_dir, filepath, authorized_sidecar = _require_authorized_output(
        request, selected_workspace, name,
    )

    # Helper: read embedded metadata from the media file
    def _read_embedded():
        ext = os.path.splitext(name)[1].lower()
        try:
            if ext in (".mp4", ".mkv"):
                from shared.utils.video_metadata import read_metadata_from_video
                return read_metadata_from_video(filepath)
            elif ext in (".png", ".jpg", ".jpeg", ".webp"):
                from shared.utils.audio_video import read_image_metadata
                return read_image_metadata(filepath)
            elif ext in (".wav", ".mp3"):
                from shared.utils.audio_metadata import read_audio_metadata
                return read_audio_metadata(filepath)
        except Exception:
            pass
        return None

    # Strategy 1: Read sidecar .meta.json
    meta_path = os.path.join(out_dir, os.path.splitext(name)[0] + ".meta.json")
    if authorized_sidecar is not None and os.path.isfile(meta_path):
        try:
            with open(meta_path, "r", encoding="utf-8") as f:
                sidecar = json.load(f)
            if not can_access_output(
                sidecar, request.state.maestro_session_id,
            ):
                raise HTTPException(status_code=404, detail="Output file not found")
            # Merge actual seed from embedded metadata if sidecar has seed=-1
            params = sidecar.get("params", {})
            if params.get("seed", -1) == -1:
                embedded = _read_embedded()
                if embedded and "seed" in embedded:
                    params["seed"] = embedded["seed"]
                else:
                    resolved_seed = _extract_output_seed(name)
                    if resolved_seed is not None:
                        params["seed"] = resolved_seed
            response_sidecar = _redact_local_paths(sidecar)
            return {"source": "sidecar", **response_sidecar}
        except HTTPException:
            raise
        except Exception:
            pass

    # Strategy 2: Read embedded metadata from media file
    embedded = _read_embedded()
    if embedded:
        return {"source": "embedded", "params": _redact_local_paths(embedded)}

    return {"source": "none", "params": None}


def _share_not_found() -> HTTPException:
    # One generic response prevents token, project, private-output, and stale
    # revision existence from becoming an oracle.
    return HTTPException(status_code=404, detail="Shared output not found")


def _resolve_shared_output(token: str) -> tuple[dict, str]:
    from services.win_safe_files import (
        is_safe_direct_basename,
        safe_direct_file_under,
    )

    record = _output_share_manager().resolve(token)
    if record is None:
        raise _share_not_found()
    workspace = record["workspace"]
    filename = record["filename"]
    if not is_safe_direct_basename(filename) or filename.startswith("."):
        raise _share_not_found()
    try:
        out_dir = _existing_workspace_dir(workspace)
    except HTTPException as error:
        raise _share_not_found() from error
    filepath = safe_direct_file_under(out_dir, filename)
    if filepath is None or not os.path.isfile(filepath):
        raise _share_not_found()
    sidecar_path = safe_direct_file_under(
        out_dir, os.path.splitext(filename)[0] + ".meta.json",
    )
    sidecar = load_media_sidecars(out_dir, {filename}).get(filename)
    if sidecar_path and os.path.isfile(sidecar_path) and sidecar is None:
        raise _share_not_found()
    if not hmac.compare_digest(
        str(record["revision"]),
        _output_share_revision(filepath, out_dir, filename),
    ):
        raise _share_not_found()
    return record, filepath


def _public_output_share_base(request: Request) -> str | None:
    configured = _public_share_url()
    if configured:
        return configured
    if _request_is_cloudflare_remote(request):
        candidates = sorted(
            origin for origin in _request_external_origins(request)
            if not _approved_local_origin(origin)
        )
        if candidates:
            return candidates[0]
    return None


@api.post("/api/v1/output-shares")
async def create_output_share(request: Request):
    """Create/copy a read-only capability for one authorized output.

    This is deliberately available to both local users and password-unlocked
    Cloudflare project users. The recipient needs only the capability link;
    it never unlocks or lists the containing project.
    """
    import mimetypes

    body = await request.json()
    workspace = _request_project_workspace(request, body.get("workspace"))
    name = str(body.get("name") or "")
    if os.path.splitext(name)[1].lower() not in _GALLERY_MEDIA_EXTENSIONS:
        raise HTTPException(status_code=400, detail="Only gallery media can be shared")
    with _reserve_workspace_operations(workspace):
        out_dir = _require_project_access(request, workspace)
        with _output_lineage_mutation_guard(out_dir):
            out_dir, filepath, sidecar = _require_authorized_output(
                request, workspace, name,
            )
            gallery_revision = _output_revision(filepath, out_dir, name)
            expected_revision = body.get("revision")
            if expected_revision is not None and not hmac.compare_digest(
                str(expected_revision), gallery_revision,
            ):
                raise HTTPException(status_code=409, detail="Output changed; refresh before sharing")
            revision = _output_share_revision(filepath, out_dir, name)
            media_type = mimetypes.guess_type(name)[0] or "application/octet-stream"
            record = _output_share_manager().create(
                workspace=workspace,
                filename=name,
                revision=revision,
                media_type=media_type,
                explicit=bool((sidecar or {}).get("explicit", False)),
            )
    share_path = f"/share/{quote(record['token'], safe='')}"
    public_base = _public_output_share_base(request)
    return {
        "share_path": share_path,
        "public_url": f"{public_base}{share_path}" if public_base else "",
        "configured_public_origin": bool(public_base),
        "created_at": record["created_at"],
        "explicit": record["explicit"],
    }


@api.delete("/api/v1/output-shares")
async def revoke_output_share(request: Request):
    from services.win_safe_files import is_safe_direct_basename

    body = await request.json()
    workspace = _request_project_workspace(request, body.get("workspace"))
    name = str(body.get("name") or "")
    if (
        not is_safe_direct_basename(name)
        or name.startswith(".")
        or os.path.splitext(name)[1].lower() not in _GALLERY_MEDIA_EXTENSIONS
    ):
        raise HTTPException(status_code=400, detail="Invalid output name")
    with _reserve_workspace_operations(workspace):
        out_dir = _require_project_access(request, workspace)
        with _output_lineage_mutation_guard(out_dir):
            # Revocation is intentionally name-scoped rather than file-scoped:
            # deleting a missing file or recreating identical bytes must never
            # resurrect an old bearer capability.
            revoked = _output_share_manager().revoke(
                workspace=workspace, filename=name,
            )
    return {"revoked": revoked}


@api.get("/api/v1/output-shares/{token}/media", include_in_schema=False)
def serve_output_share_media(token: str):
    record = _output_share_manager().resolve(token)
    if record is None:
        raise _share_not_found()
    return _PinnedOutputShareResponse(token, record["media_type"])


class _PinnedOutputShareResponse(Response):
    """Stream the exact media inode whose capability revision was checked.

    Output mutations use the same project reservation and lineage lock.  The
    file is opened while those guards are held, then the pinned handle is
    streamed after releasing them.  A concurrent rename/replacement therefore
    cannot make a verified token serve the replacement bytes.
    """

    chunk_size = 64 * 1024

    def __init__(self, token: str, media_type: str):
        self.token = token
        super().__init__(content=b"", media_type=media_type)
        self.headers["Cache-Control"] = "private, no-store"
        self.headers["Referrer-Policy"] = "no-referrer"
        self.headers["X-Content-Type-Options"] = "nosniff"
        self.headers["Accept-Ranges"] = "bytes"

    async def __call__(self, scope, receive, send) -> None:
        from services.win_safe_files import (
            _RangeError,
            _open_share_delete,
            _parse_range,
        )

        handle = None
        try:
            initial = _output_share_manager().resolve(self.token)
            if initial is None:
                raise _share_not_found()
            workspace = initial["workspace"]
            with _reserve_workspace_operations(workspace):
                out_dir = _existing_workspace_dir(workspace)
                with _output_lineage_mutation_guard(out_dir):
                    current, filepath = _resolve_shared_output(self.token)
                    if not hmac.compare_digest(
                        str(initial["revision"]), str(current["revision"]),
                    ):
                        raise _share_not_found()
                    handle = _open_share_delete(filepath)
                    size = os.fstat(handle.fileno()).st_size
        except (HTTPException, FileNotFoundError, OSError):
            if handle is not None:
                handle.close()
            await Response(
                content="Shared output not found", status_code=404,
                media_type="text/plain",
                headers={
                    "Cache-Control": "private, no-store",
                    "Referrer-Policy": "no-referrer",
                    "X-Content-Type-Options": "nosniff",
                },
            )(scope, receive, send)
            return

        range_header = next((
            value.decode("latin-1")
            for key, value in scope.get("headers", [])
            if key.lower() == b"range"
        ), None)
        start, end = 0, size - 1
        status_code = 200
        if range_header:
            try:
                start, end = _parse_range(range_header, size)
                status_code = 206
            except _RangeError:
                handle.close()
                await Response(
                    content="Range Not Satisfiable", status_code=416,
                    headers={
                        "Content-Range": f"bytes */{size}",
                        "Cache-Control": "private, no-store",
                    },
                )(scope, receive, send)
                return

        remaining = max(0, end - start + 1)
        self.headers["Content-Length"] = str(remaining)
        if status_code == 206:
            self.headers["Content-Range"] = f"bytes {start}-{end}/{size}"
        elif "Content-Range" in self.headers:
            del self.headers["Content-Range"]

        try:
            await send({
                "type": "http.response.start",
                "status": status_code,
                "headers": self.raw_headers,
            })
            if start:
                handle.seek(start)
            while remaining > 0:
                chunk = handle.read(min(self.chunk_size, remaining))
                if not chunk:
                    break
                remaining -= len(chunk)
                await send({
                    "type": "http.response.body",
                    "body": chunk,
                    "more_body": remaining > 0,
                })
            # Satisfy the declared Content-Length if an out-of-process writer
            # truncates an inode after it has been pinned.
            while remaining > 0:
                chunk = b"\0" * min(self.chunk_size, remaining)
                remaining -= len(chunk)
                await send({
                    "type": "http.response.body",
                    "body": chunk,
                    "more_body": remaining > 0,
                })
            if size == 0:
                await send({
                    "type": "http.response.body", "body": b"",
                    "more_body": False,
                })
        finally:
            handle.close()


@api.get("/share/{token}", response_class=HTMLResponse, include_in_schema=False)
def view_output_share(token: str):
    import html

    record, _ = _resolve_shared_output(token)
    filename = html.escape(record["filename"], quote=True)
    media_url = f"/api/v1/output-shares/{quote(token, safe='')}/media"
    media_type = record["media_type"]
    if media_type.startswith("video/"):
        media = f'<video controls autoplay playsinline src="{media_url}"></video>'
    elif media_type.startswith("audio/"):
        media = f'<audio controls autoplay src="{media_url}"></audio>'
    else:
        media = f'<img src="{media_url}" alt="Shared Maestro output">'
    page = f"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="referrer" content="no-referrer"><title>Shared Maestro output</title>
<style>html,body{{margin:0;min-height:100%;background:#090b10;color:#e7eaf0;font:14px system-ui}}main{{min-height:100vh;display:grid;place-items:center;padding:24px;box-sizing:border-box}}section{{width:min(1100px,100%);text-align:center}}video,img{{display:block;max-width:100%;max-height:82vh;margin:auto;background:#000;border-radius:10px}}audio{{width:min(700px,100%)}}p{{color:#9299a8;overflow-wrap:anywhere}}a{{color:#76a7ff}}</style></head>
<body><main><section>{media}<p>{filename}</p><a href="{media_url}" download="{filename}">Download</a></section></main></body></html>"""
    return HTMLResponse(
        page,
        headers={
            "Cache-Control": "private, no-store",
            "Referrer-Policy": "no-referrer",
            "X-Content-Type-Options": "nosniff",
            "Content-Security-Policy": "default-src 'none'; media-src 'self'; img-src 'self'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'",
        },
    )


@api.post("/api/v1/outputs/rejoin")
def rejoin_clips(request: Request, body: dict):
    """Re-concatenate clips from a multi-clip group.

    Body: { group_id: str, audio_file?: str }
    Finds all clip files matching the group_id and re-concatenates them.
    """
    from wgp import concatenate_multi_clip_videos
    group_id = body.get("group_id")
    if not group_id:
        raise HTTPException(status_code=400, detail="group_id is required")

    selected_workspace = _request_project_workspace(request, body.get("workspace"))
    out_dir = _require_project_access(request, selected_workspace)
    # Scan all sidecar files to find clips belonging to this group
    clips_by_index: dict[int, dict] = {}
    audio_path = None
    audio_start_sec = 0.0
    source_sidecar = None
    source_sidecars = []
    for fname in os.listdir(out_dir):
        if not fname.endswith(".meta.json"):
            continue
        meta_path = os.path.join(out_dir, fname)
        try:
            with open(meta_path, "r", encoding="utf-8") as f:
                meta = json.load(f)
            if not can_access_output(meta, request.state.maestro_session_id):
                continue
            params = meta.get("params", {})
            mci = params.get("multi_clip_info")
            if not mci or mci.get("group_id") != group_id:
                continue
            media_name = fname.replace(".meta.json", "")
            # Try common extensions
            media_path = None
            for ext in (".mp4", ".mkv", ".webm"):
                candidate = os.path.join(out_dir, media_name + ext)
                if os.path.isfile(candidate):
                    media_path = candidate
                    break
            if not media_path:
                continue
            clips_by_index[mci["index"]] = {
                "path": media_path,
                "total": mci["total"],
            }
            if source_sidecar is None:
                source_sidecar = meta
            source_sidecars.append(meta)
            # Get audio from first clip's params
            if mci["index"] == 0 and not audio_path:
                ag = params.get("audio_guide", "")
                if ag:
                    audio_path = _resolve_authorized_request_media(
                        request, ag, selected_workspace,
                    )
                if audio_path:
                    try:
                        audio_start_sec = max(
                            0.0, float(mci.get("audio_start_sec", 0) or 0),
                        )
                    except (TypeError, ValueError):
                        audio_start_sec = 0.0
        except Exception:
            continue

    if not clips_by_index:
        raise HTTPException(status_code=404, detail=f"No clips found for group {group_id}")

    total = max(c["total"] for c in clips_by_index.values())
    # Build ordered list of clip paths
    clip_paths = []
    for i in range(total):
        if i in clips_by_index:
            clip_paths.append(clips_by_index[i]["path"])
        else:
            print(f"[Rejoin] Warning: missing clip index {i} for group {group_id}")

    if len(clip_paths) < 2:
        raise HTTPException(status_code=400, detail="Need at least 2 clips to rejoin")

    # Allow override audio from request body
    body_audio = body.get("audio_file")
    if body_audio:
        audio_path = _resolve_authorized_request_media(
            request,
            body_audio,
            selected_workspace,
        )
        if not audio_path:
            raise HTTPException(status_code=404, detail="Audio file not found")

    with _reserve_workspace_operations(selected_workspace):
        # Recheck after reservation: deletion may have won while the source
        # plan was being assembled, but cannot race publication from here.
        out_dir = _require_project_access(request, selected_workspace)
        if any(not os.path.isfile(path) for path in clip_paths):
            raise HTTPException(status_code=409, detail="Source clips changed before rejoin")

        # Generate output path
        import time
        timestamp = time.strftime("%Y-%m-%d_%H%M%S")
        concat_name = f"{timestamp}_rejoin_multiclip.mp4"
        concat_path = os.path.join(out_dir, concat_name)

        success = concatenate_multi_clip_videos(
            clip_paths,
            concat_path,
            audio_path,
            audio_start_sec=audio_start_sec,
        )
        if not success or not os.path.isfile(concat_path):
            raise HTTPException(status_code=500, detail="Concatenation failed")

        inherited_audio = _inherit_media_access_policy(
            [audio_path] if audio_path else [],
            selected_workspace,
            request.state.maestro_session_id,
        )
        private = inherited_audio["private"] or any(
            bool(sidecar.get("private", False)) for sidecar in source_sidecars
        )
        explicit = inherited_audio["explicit"] or any(
            bool(sidecar.get("explicit", False)) for sidecar in source_sidecars
        )
        policy = {"private": private, "explicit": explicit}
        joined_sidecar = {
            "params": {
                "multi_clip_info": {"group_id": group_id, "joined": True},
                "prompt": ((source_sidecar or {}).get("params") or {}).get("prompt", ""),
            },
            "artifact_class": "final",
            "job_id": (source_sidecar or {}).get("job_id"),
            "generation_mode": "video",
            "created_at": time.time(),
            "output_filename": concat_name,
        }
        stamp_sidecar_policy(joined_sidecar, policy, workspace=selected_workspace)
        joined_meta_path = os.path.splitext(concat_path)[0] + ".meta.json"
        joined_meta_temp = f"{joined_meta_path}.{uuid.uuid4().hex[:8]}.tmp"
        try:
            with open(joined_meta_temp, "w", encoding="utf-8") as handle:
                json.dump(joined_sidecar, handle, indent=2)
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(joined_meta_temp, joined_meta_path)
        except Exception as exc:
            for path in (joined_meta_temp, concat_path):
                try:
                    os.remove(path)
                except OSError:
                    pass
            raise HTTPException(
                status_code=500,
                detail="Joined output metadata could not be published safely",
            ) from exc

    return {"filename": concat_name, "clip_count": len(clip_paths), "workspace": selected_workspace}


@api.get("/api/v1/outputs/group/{group_id}")
def get_group_clips(request: Request, group_id: str, workspace: str = ""):
    """Get all clip files belonging to a multi-clip group."""
    selected_workspace = _request_project_workspace(request, workspace)
    out_dir = _require_project_access(request, selected_workspace)
    clips: list[dict] = []
    for fname in os.listdir(out_dir):
        if not fname.endswith(".meta.json"):
            continue
        meta_path = os.path.join(out_dir, fname)
        try:
            with open(meta_path, "r", encoding="utf-8") as f:
                meta = json.load(f)
            if not can_access_output(meta, request.state.maestro_session_id):
                continue
            params = meta.get("params", {})
            mci = params.get("multi_clip_info")
            if not mci or mci.get("group_id") != group_id:
                continue
            media_name = fname.replace(".meta.json", "")
            media_file = None
            for ext in (".mp4", ".mkv", ".webm"):
                candidate = media_name + ext
                if os.path.isfile(os.path.join(out_dir, candidate)):
                    media_file = candidate
                    break
            if media_file:
                clips.append({
                    "filename": media_file,
                    "index": mci["index"],
                    "total": mci["total"],
                    "prompt": params.get("prompt", ""),
                })
        except Exception:
            continue
    clips.sort(key=lambda c: c["index"])
    return {"group_id": group_id, "clips": clips}


def _output_revision_token(media_path: str) -> str:
    """Return the gallery revision for media plus its exact sidecar."""
    revision_parts = []
    sidecar_path = os.path.splitext(media_path)[0] + ".meta.json"
    for revision_path in (media_path, sidecar_path):
        try:
            revision_stat = os.stat(revision_path)
            revision_parts.append(
                f"{revision_stat.st_mtime_ns:x}-{revision_stat.st_size:x}"
            )
        except (FileNotFoundError, OSError):
            revision_parts.append("0-0")
    return ".".join(revision_parts)


def _workspace_artifact_snapshot(out_dir: str):
    """Load direct media, sidecars and artifact classes once for an operation."""
    from services.win_safe_files import safe_direct_file_under
    media_names = set()
    entries = []
    try:
        candidates = os.listdir(out_dir)
    except OSError:
        candidates = []
    for name in candidates:
        if name.startswith(".") or os.path.splitext(name)[1].lower() not in _GALLERY_MEDIA_EXTENSIONS:
            continue
        path = safe_direct_file_under(out_dir, name)
        if path is None or not os.path.isfile(path):
            continue
        media_names.add(name)
    sidecars = load_media_sidecars(out_dir, media_names)
    for name in media_names:
        path = safe_direct_file_under(out_dir, name)
        if path is None:
            continue
        try:
            stat = os.stat(path)
        except OSError:
            continue
        entries.append({
            "name": name,
            "meta": sidecars.get(name) or {},
            "size": stat.st_size,
            "created_at": stat.st_mtime,
        })
    return media_names, sidecars, classify_gallery_artifacts(entries)


def _authorized_lineage_plan(
    out_dir: str,
    name: str,
    session_id: str,
) -> tuple[list[str], dict[str, dict], dict[str, str]]:
    """Freeze the selected output plus its sidecar-authorized non-finals.

    A job/seed lineage is deliberately not an ownership boundary: repeat jobs
    and separately published finals can share it.  Destructive operations may
    therefore include the selected final and metadata-backed components,
    windows, or temporary artifacts, but never another final implicitly.
    """
    media_names, sidecars, classes = _workspace_artifact_snapshot(out_dir)
    if name not in media_names:
        raise HTTPException(status_code=404, detail=f"Output not found: {name}")
    from services.win_safe_files import safe_direct_file_under
    expected_sidecar = safe_direct_file_under(
        out_dir, os.path.splitext(name)[0] + ".meta.json",
    )
    if expected_sidecar and os.path.isfile(expected_sidecar) and name not in sidecars:
        # A modern managed output with malformed/ambiguous metadata is hidden
        # by the gallery and must fail closed for mutations too.
        raise HTTPException(status_code=404, detail=f"Output not found: {name}")
    target_meta = sidecars.get(name) or {}
    if not can_access_output(target_meta, session_id):
        raise HTTPException(status_code=404, detail=f"Output not found: {name}")
    lineage = artifact_lineage(target_meta)
    if lineage is None:
        return [name], sidecars, classes
    planned = [name]
    if classes.get(name) == "final":
        for candidate in linked_component_names(name, sidecars, classes):
            meta = sidecars.get(candidate) or {}
            if can_access_output(meta, session_id):
                planned.append(candidate)
    return list(dict.fromkeys(planned)) or [name], sidecars, classes


def _validate_bulk_item_revision(out_dir: str, item: dict) -> None:
    expected = str(item.get("revision") or "")
    if not expected:
        return
    from services.win_safe_files import safe_direct_file_under
    path = safe_direct_file_under(out_dir, str(item.get("name") or ""))
    if path is None or _output_revision_token(path) != expected:
        raise HTTPException(
            status_code=409,
            detail=f"Output changed since selection: {item.get('name')}",
        )


_output_lineage_mutation_registry_lock = threading.Lock()
_output_lineage_mutation_locks: dict[str, threading.RLock] = {}


class _OutputLineageMutationGuard:
    """Acquire stable workspace locks in path order to avoid move deadlocks."""

    def __init__(self, *out_dirs: str):
        keys = sorted({os.path.normcase(os.path.realpath(path)) for path in out_dirs})
        with _output_lineage_mutation_registry_lock:
            self._locks = [
                _output_lineage_mutation_locks.setdefault(key, threading.RLock())
                for key in keys
            ]

    def __enter__(self):
        for lock in self._locks:
            lock.acquire()
        return self

    def __exit__(self, exc_type, exc_value, traceback_value):
        for lock in reversed(self._locks):
            lock.release()
        return False


def _output_lineage_mutation_guard(*out_dirs: str) -> _OutputLineageMutationGuard:
    """Return the shared lock used by every lineage mutation path."""
    return _OutputLineageMutationGuard(*out_dirs)


def _freeze_lineage_revisions(out_dir: str, names: list[str]) -> dict[str, str]:
    """Capture media+sidecar identities for a frozen mutation plan."""
    from services.win_safe_files import safe_direct_file_under
    revisions = {}
    for name in dict.fromkeys(names):
        path = safe_direct_file_under(out_dir, name)
        if path is None or not os.path.isfile(path):
            raise HTTPException(status_code=409, detail=f"Missing lineage member: {name}")
        revisions[name] = _output_revision_token(path)
    return revisions


def _recheck_lineage_revisions(out_dir: str, revisions: dict[str, str]) -> None:
    """Fail before commit when any frozen lineage member changed."""
    from services.win_safe_files import safe_direct_file_under
    for name, expected in revisions.items():
        path = safe_direct_file_under(out_dir, name)
        if path is None or not os.path.isfile(path) or _output_revision_token(path) != expected:
            raise HTTPException(
                status_code=409,
                detail=f"Output changed during mutation: {name}",
            )


def _set_lineage_privacy(
    out_dir: str,
    names: list[str],
    *,
    workspace: str,
    private: bool,
    session_id: str,
    expected_revisions: dict[str, str] | None = None,
) -> list[str]:
    """Rewrite every frozen lineage sidecar or restore all original bytes."""
    from services.win_safe_files import safe_direct_file_under
    unique_names = list(dict.fromkeys(names))
    staged: list[tuple[str, str]] = []
    originals: list[tuple[str, bytes | None]] = []
    commit_started = False
    with _output_lineage_mutation_guard(out_dir):
        try:
            if expected_revisions is not None:
                _recheck_lineage_revisions(out_dir, expected_revisions)
            prepared: list[tuple[str, dict]] = []
            for name in unique_names:
                sidecar_name = os.path.splitext(name)[0] + ".meta.json"
                path = safe_direct_file_under(out_dir, sidecar_name)
                if path is None:
                    raise HTTPException(
                        status_code=409,
                        detail=f"Invalid lineage sidecar: {name}",
                    )
                if os.path.isfile(path):
                    try:
                        with open(path, "rb") as handle:
                            original = handle.read()
                        meta = json.loads(original)
                    except (OSError, ValueError, TypeError) as error:
                        raise HTTPException(
                            status_code=409,
                            detail=f"Invalid lineage sidecar: {name}",
                        ) from error
                elif len(unique_names) == 1:
                    # Legacy gallery media may predate sidecars. It is safe to
                    # create policy metadata for the selected file only; a
                    # multi-member lineage must already be metadata-backed.
                    original = None
                    meta = {"output_filename": name}
                else:
                    raise HTTPException(
                        status_code=409,
                        detail=f"Missing lineage sidecar: {name}",
                    )
                if not isinstance(meta, dict):
                    raise HTTPException(
                        status_code=409,
                        detail=f"Invalid lineage sidecar: {name}",
                    )
                if not can_access_output(meta, session_id):
                    raise HTTPException(
                        status_code=404,
                        detail=f"Output not found: {name}",
                    )
                originals.append((path, original))
                updated = dict(meta)
                updated["private"] = private
                updated.pop("owner_session_id", None)
                prepared.append((path, updated))

            for path, updated in prepared:
                staged.append((_stage_json_replacement(path, updated), path))

            if expected_revisions is not None:
                _recheck_lineage_revisions(out_dir, expected_revisions)
            # All parsing and staging has succeeded. Revoke before publishing
            # the first sidecar so a durable store failure leaves the exact
            # original presentation metadata in place.
            _revoke_output_shares(workspace, unique_names)
            commit_started = True
            for temp, path in staged:
                os.replace(temp, path)
            return unique_names
        except HTTPException:
            raise
        except Exception as error:
            rollback_error = None
            if commit_started:
                for path, original in originals:
                    try:
                        if original is None:
                            if os.path.exists(path):
                                os.remove(path)
                        else:
                            _restore_file_bytes(path, original)
                    except Exception as restore_error:
                        rollback_error = rollback_error or restore_error
            if rollback_error is not None:
                raise HTTPException(
                    status_code=500,
                    detail="Could not safely restore output privacy metadata",
                ) from rollback_error
            raise HTTPException(
                status_code=500,
                detail="Could not update output privacy metadata",
            ) from error
        finally:
            for temp, _ in staged:
                try:
                    os.remove(temp)
                except OSError:
                    pass


def _revoke_output_shares(workspace: str, names: list[str]) -> int:
    """Durably revoke capabilities before mutating the named outputs."""
    manager = _output_share_manager()
    return sum(
        manager.revoke(workspace=workspace, filename=name)
        for name in dict.fromkeys(names)
    )


def _move_lineage_files(
    source_dir: str,
    target_dir: str,
    names: list[str],
    *,
    source_workspace: str,
    target_workspace: str,
    expected_revisions: dict[str, str] | None = None,
) -> list[str]:
    """Move media+sidecars as a preflighted lineage transaction."""
    import shutil
    from services.win_safe_files import safe_direct_file_under
    unique_names = list(dict.fromkeys(names))
    with _output_lineage_mutation_guard(source_dir, target_dir):
        if expected_revisions is not None:
            _recheck_lineage_revisions(source_dir, expected_revisions)
        media_pairs = []
        original_sidecars = {}
        sidecar_updates = []
        staged_sidecars = []
        for name in unique_names:
            sidecar_name = os.path.splitext(name)[0] + ".meta.json"
            source_media = safe_direct_file_under(source_dir, name)
            target_media = safe_direct_file_under(target_dir, name)
            source_sidecar = safe_direct_file_under(source_dir, sidecar_name)
            target_sidecar = safe_direct_file_under(target_dir, sidecar_name)
            if source_media is None or target_media is None or not os.path.isfile(source_media):
                raise HTTPException(status_code=409, detail=f"Missing lineage member: {name}")
            if source_sidecar is None or target_sidecar is None:
                raise HTTPException(status_code=409, detail=f"Invalid lineage member: {sidecar_name}")
            for target, candidate in ((target_media, name), (target_sidecar, sidecar_name)):
                if os.path.exists(target):
                    raise HTTPException(status_code=409, detail=f"Target already contains: {candidate}")
            if not os.path.isfile(source_sidecar):
                if len(unique_names) == 1:
                    media_pairs.append((source_media, target_media))
                    continue
                raise HTTPException(status_code=409, detail=f"Missing lineage member: {sidecar_name}")
            with open(source_sidecar, "rb") as handle:
                content = handle.read()
            try:
                meta = json.loads(content)
            except (TypeError, ValueError) as error:
                raise HTTPException(
                    status_code=409, detail=f"Invalid lineage sidecar: {sidecar_name}",
                ) from error
            if not isinstance(meta, dict):
                raise HTTPException(status_code=409, detail=f"Invalid lineage sidecar: {sidecar_name}")
            original_sidecars[source_sidecar] = content
            updated = dict(meta)
            updated["workspace"] = target_workspace
            updated.pop("owner_session_id", None)
            sidecar_updates.append((target_sidecar, updated))
            media_pairs.append((source_media, target_media))
        if expected_revisions is not None:
            _recheck_lineage_revisions(source_dir, expected_revisions)
        # Capability invalidation is the first irreversible step. A durable
        # store failure leaves every source and target path untouched.
        _revoke_output_shares(source_workspace, unique_names)
        published_sidecars = []
        removed_source_sidecars = []
        rollback_error = None
        try:
            # Target authorization metadata is published before media. Source
            # media disappears before its sidecar, so neither workspace can
            # ever observe a private output without its policy metadata.
            for target, updated in sidecar_updates:
                staged_sidecars.append((_stage_json_replacement(target, updated), target))
            for staged, target in staged_sidecars:
                os.replace(staged, target)
                published_sidecars.append(target)
            for source, target in media_pairs:
                shutil.move(source, target)
            for source in original_sidecars:
                os.remove(source)
                removed_source_sidecars.append(source)
            return unique_names
        except Exception as error:
            for source, target in reversed(media_pairs):
                if os.path.exists(target):
                    try:
                        if os.path.exists(source):
                            os.remove(target)
                        else:
                            shutil.move(target, source)
                    except Exception as restore_error:
                        rollback_error = rollback_error or restore_error
            for source, content in original_sidecars.items():
                if source in removed_source_sidecars or not os.path.isfile(source):
                    try:
                        _restore_file_bytes(source, content)
                    except Exception as restore_error:
                        rollback_error = rollback_error or restore_error
            for target in published_sidecars:
                try:
                    if os.path.exists(target):
                        os.remove(target)
                except OSError as restore_error:
                    rollback_error = rollback_error or restore_error
            if rollback_error is not None:
                raise HTTPException(
                    status_code=500, detail="Could not safely restore moved output lineage",
                ) from rollback_error
            if isinstance(error, HTTPException):
                raise
            raise HTTPException(status_code=500, detail="Could not move output lineage") from error
        finally:
            for staged, _ in staged_sidecars:
                try:
                    os.remove(staged)
                except OSError:
                    pass


@api.post("/api/v1/outputs/bulk/privacy")
async def bulk_output_privacy(request: Request):
    body = await request.json()
    items = body.get("items")
    if not isinstance(items, list) or not items:
        raise HTTPException(status_code=400, detail="items are required")
    private = body.get("private", True)
    if not isinstance(private, bool):
        raise HTTPException(status_code=400, detail="private must be a boolean")
    results = []
    processed: set[tuple[str, str]] = set()
    for raw_item in items:
        item = raw_item if isinstance(raw_item, dict) else {}
        name = str(item.get("name") or "")
        workspace = _request_project_workspace(request, item.get("workspace"))
        if (workspace, name) in processed:
            results.append({
                "name": name,
                "workspace": workspace,
                "ok": True,
                "changed": [],
            })
            continue
        try:
            with _reserve_workspace_operations(workspace):
                out_dir = _require_project_access(request, workspace)
                with _output_lineage_mutation_guard(out_dir):
                    _validate_bulk_item_revision(out_dir, item)
                    names, _, _ = _authorized_lineage_plan(
                        out_dir, name, request.state.maestro_session_id,
                    )
                    names = [n for n in names if (workspace, n) not in processed]
                    revisions = _freeze_lineage_revisions(out_dir, names) if names else {}
                    changed = _set_lineage_privacy(
                        out_dir, names, workspace=workspace, private=private,
                        session_id=request.state.maestro_session_id,
                        expected_revisions=revisions,
                    ) if names else []
                    processed.update((workspace, n) for n in changed)
            results.append({"name": name, "workspace": workspace, "ok": True, "changed": changed})
        except HTTPException as error:
            results.append({"name": name, "workspace": workspace, "ok": False, "error": error.detail})
        except Exception:
            results.append({
                "name": name, "workspace": workspace, "ok": False,
                "error": "Could not update output privacy",
            })
    return {"private": private, "results": results}


@api.post("/api/v1/outputs/bulk/move")
async def bulk_move_outputs(request: Request):
    body = await request.json()
    items = body.get("items")
    target_workspace = str(body.get("target_workspace") or "")
    if not isinstance(items, list) or not items or not target_workspace:
        raise HTTPException(status_code=400, detail="items and target_workspace are required")
    results = []
    processed: set[tuple[str, str]] = set()
    for raw_item in items:
        item = raw_item if isinstance(raw_item, dict) else {}
        name = str(item.get("name") or "")
        workspace = _request_project_workspace(request, item.get("workspace"))
        try:
            if workspace == target_workspace:
                raise HTTPException(status_code=400, detail="Already in that project")
            with _reserve_workspace_operations(workspace, target_workspace):
                source_dir = _require_project_access(request, workspace)
                target_dir = _require_project_access(request, target_workspace)
                with _output_lineage_mutation_guard(source_dir, target_dir):
                    _validate_bulk_item_revision(source_dir, item)
                    names, _, _ = _authorized_lineage_plan(
                        source_dir, name, request.state.maestro_session_id,
                    )
                    names = [n for n in names if (workspace, n) not in processed]
                    revisions = _freeze_lineage_revisions(source_dir, names) if names else {}
                    moved = _move_lineage_files(
                        source_dir, target_dir, names,
                        source_workspace=workspace,
                        target_workspace=target_workspace,
                        expected_revisions=revisions,
                    ) if names else []
                    processed.update((workspace, n) for n in moved)
            results.append({"name": name, "workspace": workspace, "ok": True, "moved": moved})
        except HTTPException as error:
            results.append({"name": name, "workspace": workspace, "ok": False, "error": error.detail})
        except Exception:
            results.append({
                "name": name, "workspace": workspace, "ok": False,
                "error": "Could not move output lineage",
            })
    return {"target_workspace": target_workspace, "results": results}


def _delete_frozen_output_names(
    out_dir: str,
    workspace: str,
    names: list[str],
    *,
    expected_revisions: dict[str, str] | None = None,
) -> tuple[list[str], list[str]]:
    """Atomically hide one frozen lineage, rolling back any staging fault."""
    from services.win_safe_files import safe_delete, safe_direct_file_under
    unique_names = list(dict.fromkeys(names))
    with _output_lineage_mutation_guard(out_dir):
        if expected_revisions is not None:
            _recheck_lineage_revisions(out_dir, expected_revisions)
        pairs = []
        for name in unique_names:
            media = safe_direct_file_under(out_dir, name)
            if media is None or not os.path.isfile(media):
                raise HTTPException(status_code=409, detail=f"Missing lineage member: {name}")
            paths = [media]
            sidecar = safe_direct_file_under(
                out_dir, os.path.splitext(name)[0] + ".meta.json",
            )
            if sidecar and os.path.isfile(sidecar):
                paths.append(sidecar)
            for path in paths:
                staged = os.path.join(
                    out_dir,
                    f".trash_{time.time_ns()}_{uuid.uuid4().hex[:8]}_{os.path.basename(path)}",
                )
                pairs.append((path, staged))
        if expected_revisions is not None:
            _recheck_lineage_revisions(out_dir, expected_revisions)

        # Revoke before staging the first path. A share-store failure is then
        # a clean abort; once revocation succeeds, any later file rollback may
        # safely leave the output present with its old link invalidated.
        _revoke_output_shares(workspace, unique_names)

        staged_pairs = []
        rollback_error = None
        try:
            for source, staged in pairs:
                os.replace(source, staged)
                staged_pairs.append((source, staged))
        except Exception as error:
            for source, staged in reversed(staged_pairs):
                if os.path.exists(staged) and not os.path.exists(source):
                    try:
                        os.replace(staged, source)
                    except OSError as restore_error:
                        rollback_error = rollback_error or restore_error
            if rollback_error is not None:
                raise HTTPException(
                    status_code=500, detail="Could not safely restore output lineage",
                ) from rollback_error
            raise HTTPException(status_code=423, detail="Output lineage is locked") from error

        for _, staged in staged_pairs:
            safe_delete(staged)

        deleted = unique_names
        from services.win_safe_files import favorites_lock
        with favorites_lock:
            favorites = _load_favorites(workspace)
            updated = favorites.difference(deleted)
            if updated != favorites:
                _save_favorites(updated, workspace)
        try:
            from services.search_index import get_search_index
            get_search_index().invalidate()
        except Exception:
            pass
        return deleted, []


@api.post("/api/v1/outputs/bulk/delete")
async def bulk_delete_outputs(request: Request):
    body = await request.json()
    items = body.get("items")
    cascade = bool(body.get("cascade", True))
    if not isinstance(items, list) or not items:
        raise HTTPException(status_code=400, detail="items are required")
    results = []
    processed: set[tuple[str, str]] = set()
    for raw_item in items:
        item = raw_item if isinstance(raw_item, dict) else {}
        name = str(item.get("name") or "")
        workspace = _request_project_workspace(request, item.get("workspace"))
        try:
            with _reserve_workspace_operations(workspace):
                out_dir = _require_project_access(request, workspace)
                with _output_lineage_mutation_guard(out_dir):
                    _validate_bulk_item_revision(out_dir, item)
                    plan, _, classes = _authorized_lineage_plan(
                        out_dir, name, request.state.maestro_session_id,
                    )
                    if not cascade or classes.get(name) != "final":
                        plan = [name]
                    plan = [candidate for candidate in plan if (workspace, candidate) not in processed]
                    plan.sort(key=lambda candidate: classes.get(candidate) == "final")
                    revisions = _freeze_lineage_revisions(out_dir, plan) if plan else {}
                    deleted, failed = _delete_frozen_output_names(
                        out_dir, workspace, plan, expected_revisions=revisions,
                    ) if plan else ([], [])
                    processed.update((workspace, candidate) for candidate in deleted)
            results.append({
                "name": name,
                "workspace": workspace,
                "ok": not failed,
                "deleted": deleted,
                "failed": failed,
            })
        except HTTPException as error:
            results.append({"name": name, "workspace": workspace, "ok": False, "error": error.detail})
        except Exception:
            results.append({
                "name": name, "workspace": workspace, "ok": False,
                "error": "Could not delete output lineage",
            })
    return {"cascade": cascade, "results": results}


@api.post("/api/v1/outputs/{name:path}/move")
async def move_output(name: str, request: Request):
    """Move an output file and its sidecar metadata to another workspace."""
    body = await request.json()
    target_ws = body.get("workspace", "")
    source_ws = _request_project_workspace(request, body.get("source_workspace"))
    if not target_ws:
        raise HTTPException(status_code=400, detail="workspace is required")

    from services.win_safe_files import (
        is_safe_direct_basename,
        is_safe_workspace_name,
    )
    if not is_safe_workspace_name(target_ws):
        raise HTTPException(status_code=400, detail="Invalid workspace name")
    if (
        not is_safe_direct_basename(name)
        or name.startswith(".")
        or os.path.splitext(name)[1].lower() not in _GALLERY_MEDIA_EXTENSIONS
    ):
        raise HTTPException(status_code=400, detail="Invalid output name")

    with _reserve_workspace_operations(source_ws, target_ws):
        src_dir, _, _ = _require_authorized_output(
            request, source_ws, name,
        )
        dst_dir = _require_project_access(request, target_ws)
        if src_dir == dst_dir:
            raise HTTPException(status_code=400, detail="Already in that workspace")

        print(f"[Move] {name} -> {target_ws}")
        with _output_lineage_mutation_guard(src_dir, dst_dir):
            _validate_bulk_item_revision(src_dir, {"name": name, "revision": body.get("revision")})
            names, _, _ = _authorized_lineage_plan(
                src_dir, name, request.state.maestro_session_id,
            )
            revisions = _freeze_lineage_revisions(src_dir, names)
            moved = _move_lineage_files(
                src_dir, dst_dir, names, source_workspace=source_ws,
                target_workspace=target_ws,
                expected_revisions=revisions,
            )

        # Update favorites (lock held across the read-modify-write)
        from services.win_safe_files import favorites_lock
        with favorites_lock:
            favs = _load_favorites(source_ws)
            updated = favs.difference(moved)
            if updated != favs:
                favs = updated
                _save_favorites(favs, source_ws)

    try:
        from services.search_index import get_search_index
        get_search_index().invalidate()
    except Exception:
        pass
    return {"moved": name, "lineage": moved, "to": target_ws}


def _plan_output_component_cleanup(name: str, out_dir: str):
    """Validate a final and return its sidecar-authorized cleanup plan."""
    from services.win_safe_files import safe_direct_file_under

    try:
        media_names = {
            filename
            for filename in os.listdir(out_dir)
            if (
                os.path.splitext(filename)[1].lower() in _GALLERY_MEDIA_EXTENSIONS
                and os.path.isfile(os.path.join(out_dir, filename))
            )
        }
    except OSError:
        media_names = set()
    if name not in media_names:
        raise HTTPException(status_code=404, detail="Final output not found")

    sidecars = load_media_sidecars(out_dir, media_names)
    artifact_entries = []
    for filename in media_names:
        path = safe_direct_file_under(out_dir, filename)
        if path is None:
            continue
        try:
            stat = os.stat(path)
        except OSError:
            continue
        artifact_entries.append({
            "name": filename,
            "meta": sidecars.get(filename) or {},
            "size": stat.st_size,
            "created_at": stat.st_mtime,
        })
    classes = classify_gallery_artifacts(artifact_entries)
    if classes.get(name) != "final" or artifact_lineage(sidecars.get(name) or {}) is None:
        raise HTTPException(
            status_code=409,
            detail="This output has no stable sidecar lineage for safe component cleanup",
        )

    candidates = linked_component_names(name, sidecars, classes)
    return out_dir, candidates


def _delete_output_component_candidates(
    name: str,
    out_dir: str,
    candidates,
    workspace: str | None = None,
    session_id: str | None = None,
):
    """Execute a validated all-or-nothing component cleanup plan."""
    selected_workspace = workspace or _get_active_workspace()
    unique_candidates = list(dict.fromkeys(candidates))
    with _output_lineage_mutation_guard(out_dir):
        if session_id:
            current_plan, _, classes = _authorized_lineage_plan(
                out_dir, name, session_id,
            )
            allowed = {
                candidate for candidate in current_plan
                if candidate != name and classes.get(candidate) != "final"
            }
            if any(candidate not in allowed for candidate in unique_candidates):
                raise HTTPException(
                    status_code=409,
                    detail="Output lineage changed before component cleanup",
                )
        revisions = _freeze_lineage_revisions(out_dir, unique_candidates)
        deleted, failed = _delete_frozen_output_names(
            out_dir, selected_workspace, unique_candidates,
            expected_revisions=revisions,
        ) if unique_candidates else ([], [])
    return {
        "final": name,
        "deleted": deleted,
        "deferred": [],
        "failed": failed,
    }


@api.delete("/api/v1/outputs/{name:path}/components")
def delete_output_components(
    request: Request,
    name: str,
    workspace: str | None = None,
):
    """Delete only sidecar-linked non-final artifacts for one final output.

    Linkage is metadata-only (explicit lineage, job+group, or job+seed).  A
    basename resemblance is never enough to authorize deletion.
    """
    selected_workspace = _request_project_workspace(request, workspace)
    with _reserve_workspace_operations(selected_workspace):
        out_dir, _, _ = _require_authorized_output(
            request, selected_workspace, name,
        )
        out_dir, candidates = _plan_output_component_cleanup(name, out_dir)
        return _delete_output_component_candidates(
            name, out_dir, candidates, selected_workspace,
            request.state.maestro_session_id,
        )


@api.delete("/api/v1/outputs/{name}")
def delete_output(
    request: Request,
    name: str,
    delete_components: bool = False,
    workspace: str | None = None,
    revision: str | None = None,
):
    """Atomically hide an output and optionally its authorized non-finals.

    Every member is renamed to contained hidden trash before reclamation.
    Any staging fault restores the entire frozen plan, so a locked file can
    never leave half a generation deleted.
    """
    import gc
    from services.win_safe_files import (
        is_safe_direct_basename,
        safe_direct_file_under,
    )
    selected_workspace = _request_project_workspace(request, workspace)
    if (
        not is_safe_direct_basename(name)
        or name.startswith(".")
        or os.path.splitext(name)[1].lower() not in _GALLERY_MEDIA_EXTENSIONS
    ):
        raise HTTPException(status_code=400, detail="Invalid output name")
    with _reserve_workspace_operations(selected_workspace):
        out_dir = _require_project_access(request, selected_workspace)
        with _output_lineage_mutation_guard(out_dir):
            filepath = safe_direct_file_under(out_dir, name)
            if filepath is None:
                raise HTTPException(status_code=400, detail="Invalid output name")
            if not os.path.isfile(filepath):
                _revoke_output_shares(selected_workspace, [name])
                return {"deleted": name}
            _require_authorized_output(request, selected_workspace, name)
            _validate_bulk_item_revision(out_dir, {"name": name, "revision": revision})
            plan, _, classes = _authorized_lineage_plan(
                out_dir, name, request.state.maestro_session_id,
            )
            if not delete_components or classes.get(name) != "final":
                plan = [name]
            plan.sort(key=lambda candidate: classes.get(candidate) == "final")
            revisions = _freeze_lineage_revisions(out_dir, plan)

            # Drop recent metadata readers before the all-member rename transaction.
            gc.collect()
            deleted, _ = _delete_frozen_output_names(
                out_dir, selected_workspace, plan, expected_revisions=revisions,
            )

    component_names = [candidate for candidate in deleted if candidate != name]
    cleanup_result = None if not delete_components else {
        "final": name,
        "deleted": component_names,
        "deferred": [],
        "failed": [],
    }
    return {"deleted": name, "components": cleanup_result}


@api.post("/api/v1/upload")
async def upload_image(
    request: Request,
    file: UploadFile = File(...),
    private: bool = True,
):
    """Upload an image or audio/video asset. Image was the original use;
    audio/video also flow through here when the frontend doesn't hit the
    dedicated /api/v1/upload-audio endpoint. Compressed audio formats get
    transcoded to wav so downstream libsndfile callers work."""
    cl = request.headers.get("content-length")
    if cl and cl.isdigit() and int(cl) > MAX_IMAGE_UPLOAD_BYTES:
        raise HTTPException(status_code=413, detail="File too large (max 500 MB)")

    upload_dir = os.path.join(os.getcwd(), "uploads")
    os.makedirs(upload_dir, exist_ok=True)

    ext = os.path.splitext(file.filename or "img.png")[1].lower() or ".png"
    unique_name = f"{uuid.uuid4().hex[:8]}{ext}"
    filepath = os.path.join(upload_dir, unique_name)

    content = await file.read()
    if len(content) > MAX_IMAGE_UPLOAD_BYTES:
        raise HTTPException(status_code=413, detail="File too large (max 500 MB)")
    with open(filepath, "wb") as f:
        f.write(content)

    # libsndfile-incompatible audio → transcode to wav so slice_audio_window
    # and friends can read it without a downstream crash. Mirrors the logic
    # in /api/v1/upload-audio.
    if ext in (".mp3", ".m4a", ".aac"):
        wav_name = f"{os.path.splitext(unique_name)[0]}.wav"
        wav_path = os.path.join(upload_dir, wav_name)
        compressed_original = filepath
        transcode_ok = False
        try:
            import ffmpeg as _ffmpeg
            (
                _ffmpeg
                .input(filepath)
                .output(wav_path, acodec="pcm_s16le")
                .overwrite_output()
                .run(quiet=True)
            )
            transcode_ok = True
            os.remove(compressed_original)
            filepath = wav_path
            unique_name = wav_name
        except _ffmpeg.Error as err:
            stderr = getattr(err, "stderr", b"") or b""
            if isinstance(stderr, (bytes, bytearray)):
                stderr = stderr.decode("utf-8", errors="ignore")
            raise HTTPException(
                status_code=400,
                detail=f"Failed to decode {ext} audio: {(stderr or str(err)).strip()[:300]}",
            ) from err
        except Exception as err:
            raise HTTPException(status_code=500, detail=f"Audio transcode failed: {err}") from err
        finally:
            if not transcode_ok:
                for stale in (wav_path, compressed_original):
                    if stale and os.path.isfile(stale):
                        try:
                            os.remove(stale)
                        except OSError:
                            pass

    if bool(getattr(request.state, "maestro_remote", False)):
        private = True
    access = write_upload_access_sidecar(
        filepath,
        request.state.maestro_session_id,
        private=private,
    )
    result = {
        "filename": unique_name,
        "path": (
            unique_name
            if bool(getattr(request.state, "maestro_remote", False))
            else filepath
        ),
        "url": f"/api/v1/uploads/{unique_name}",
        **public_output_policy(access),
    }
    # For video uploads, report the source frame rate so the client can
    # compute frame counts for models that follow the control video's
    # fps (force_fps="control" — the SCAIL-2 class). The UI otherwise
    # converts seconds to frames at the model's nominal 16 fps and
    # under-counts: a "10s" request against a 25fps guide covered only
    # 6.4s of the performance.
    if ext in (".mp4", ".webm", ".mkv", ".mov", ".avi", ".m4v"):
        try:
            from shared.utils.utils import get_video_info
            _fps, _w, _h, _frame_count = get_video_info(filepath)
            if _fps:
                result["fps"] = float(_fps)
                result["frame_count"] = int(_frame_count or 0)
                result["duration_seconds"] = round(
                    float(_frame_count or 0) / float(_fps), 3,
                )
            try:
                import av as _av

                with _av.open(filepath) as _container:
                    result["has_audio"] = bool(_container.streams.audio)
            except Exception:
                result["has_audio"] = False
        except Exception:
            pass
    return result


@api.get("/api/v1/uploads/{filename}")
def serve_upload(request: Request, filename: str):
    """Serve one direct-child upload.

    Output media is intentionally *not* resolved here.  It must use the
    workspace-scoped ``/file`` route so project authorization is enforced;
    uploads remain independently session-owned.
    """
    from services.win_safe_files import (
        safe_direct_file_under,
        share_delete_file_response,
    )
    base = os.path.join(os.getcwd(), "uploads")
    filepath = safe_direct_file_under(base, filename)
    if filepath is not None and os.path.isfile(filepath):
        resolved = _resolve_authorized_request_media(request, filepath)
        if resolved == filepath:
            return share_delete_file_response(resolved)
    raise HTTPException(status_code=404, detail="Upload not found")


